COLLDATA("sh1110","ar",[[37770,"أخبرنا أبو موسى، كتابة، أخبرنا أبو نصر أحمد بن عمر الغازي، أخبرنا إسماعيل بن زاهر، أخبرنا القطان، أخبرنا عبد الله بن جعفر بن درستويه، حدثنا يعقوب بن سفيان، حدثنا عمرو بن عون، حدثنا أبو شهاب، حدثنا الحجاج، عن ابن أبي مليكة، عن محمود بن سليمان بن أبي حثمة، عن عمه سهل بن أبي حثمة، قال: رأيت محمد بن مسلمة يطارد امرأة ببصره على إجار، يقال لها: ثبيتة بنت الضحاك، أخت أبي جبيرة، فقلت: أتفعل هذا وأنت صاحب رسول الله صلى الله عليه وآله وسلم! فقال: نعم."],[37771,"قال رسول الله صلى الله عليه وآله وسلم: «إذا ألقي الله عز وجل في قلب رجل خطبة امرأة فلا بأس أن ينظر إليها»."],[37772,"ورواه جماعة عن الحجاج بن أرطأة، عن محمد بن سليمان، لم يذكروا ابن أبي مليكة."],[37773,"وفي رواية زكريا بن أبي زائدة، عن الحجاج سماها نبيهة."],[37774,"وقال أبو معاوية، عن الحجاج، عن سهل بن محمد بن أبي حثمة، عن عمه سليمان، وقال: نبيثة، يعني: بالنون."],[37775,"وله طرق عن محمد بن مسلمة."],[37776,"أخرجه أبو عمر، وأبو موسى"],[37777,"٦٧٩٦ - ثبيتة بنت النعمان"],[37778,"د ع: ثبيتة بنت النعمان بن عمرو بن النعمان بن خلدة بن عمرو بن أمية بن عامر ابن بياضة الأنصارية الخزرجية، ثم البياضية."],[37779,"لها ولأبيها، ولجدها صحبة."],[37780,"أسلمت وبايعت النبي صلى الله عليه وآله وسلم. قاله محمد بن سعد، وقال ابن حبيب مثله في نسبها، إلا أنه جعلها من بني جحجبى."],[37781,"وهذا النسب معروف في بني بياضة، فإن النعمان أبا هذه وأبا عمرا لهما صحبة، وهما من بني بياضة."],[37782,"٦٧٩٧ - ثبيتة بنت يعار"],[37783,"ب: ثبيتة بنت يعار بن زيد بن عبيد بن زيد بن مالك بن عوف بن عمرو بن عوف الأنصارية."],[37784,"كانت من المهاجرات الأول، ومن فضلاء النساء الصحابيات."],[37785,"وهي امرأة أبي حذيفة بن عتبة بن ربيعة، وهي مولاة سالم مولى أبي حذيفة، أعتقته فوالى سالم أبا حذيفة، فقيل: سالم مولى أبي حذيفة، قتل سالم يوم اليمامة."],[37786,"وقد اختلف في اسمها فقال مصعب: ثبيتة كما ذكرناه."],[37787,"وقال أبو طوالة: عمرة بنت يعار."],[37788,"وقال ابن إسحاق: سالم مولى امرأة من الأنصار."],[37789,"وقال موسى بن عقبة، عن ابن شهاب: سالم بن معقل، مولى سلمى بنت تعار، بالتاء فوقها نقطتان."],[37790,"وقال إبراهيم بن المنذر: إنما هو يعار، يعني: بالياء تحتها نقطتان."],[37791,"أخرجها أبو عمر."],[37792,"٦٧٩٨ - ثويبة مولاة أبي لهب"],[37793,"د ع: ثويبة مولاة أبي لهب أرضعت النبي صلى الله عليه وآله وسلم اختلف في إسلامها."],[37794,"أخرجها ابن منده، وأبو نعيم، وقال أبو نعيم: لا أعلم أحدا أثبت إسلامها غير المتأخر يعني: ابن منده."],[37795,"حرف الجيم"],[37796,"٦٧٩٩ - جثامة المزنية"],[37797,"س: جثامة المزنية"],[37798,"أخبرنا عمر بن محمد بن طبرزد، أخبرنا ابن البناء، أخبرنا أبو محمد الجوهري، أخبرنا أبو بكر بن مالك، حدثنا محمد بن يونس، حدثنا أبو عاصم، حدثنا صالح بن رستم، عن ابن أبي مليكة، عن عائشة، قالت: جاءت عجوز إلى النبي صلى الله عليه وآله وسلم قال لها: «من أنت؟» قالت: أنا جثامة."],[37799,"قال: «بل أنت حضانة، كيف أنتم؟ كيف حالكم؟ كيف كنتم بعدنا؟» قالت: بخير يا رسول الله."],[37800,"قالت عائشة: فلما خرجت قلت: يا رسول الله، تقبل على هذه العجوز هذا الإقبال! قال: «إنها كانت تأتينا زمن خديجة، وإن حسن العهد من الإيمان»، وقيل: إن رسول الله صلى الله عليه وآله وسلم قال لها لما قالت أنا جثامة: «بل أنت حسانة»."],[37801,"أخرجها أبو موسى، ويرد ذكرها في حسانة إن شاء الله تعالى"],[37802,"٦٨٠٠ - جبلة بنت المصفح"],[37803,"ب: جبلة بنت المصفح أدركت النبي صلى الله عليه وآله وسلم. روى عنها فضيل بن مرزوق."],[37804,"أخرجها أبو عمر مختصرا."],[37805,"٦٨٠١ - جدامة بنت جندل"],[37806,"جدامة بنت جندل ذكرها ابن إسحاق فيمن هاجر من نساء بني غنم بن دودان بن أسد بن خزيمة."],[37807,"٦٨٠٢ - جدامة بنت الحارث"],[37808,"د ع: جذامة بنت الحارث أخت حليمة بنت الحارث أم النبي صلى الله عليه وآله وسلم من الرضاعة."],[37809,"نذكر نسبها عند ذكر حليمة، تلقب: الشيماء، لا تعرف لها رواية."],[37810,"أخرجها ابن منده، وأبو نعيم."],[37811,"قلت: كذا قال: لقبها شيماء، وإنما الشيماء بنت حليمة، وهي أخت رسول الله صلى الله عليه وآله وسلم من الرضاعة لا خالته."],[37812,"٦٨٠٣ - جدامة بنت وهب"],[37813,"ب د ع: جدامة بنت وهب الأسدية من أسد بني خزيمة."],[37814,"أسلمت بمكة وبايعت النبي صلى الله عليه وآله وسلم وهاجرت مع قومها إلى المدينة، وكانت تحت أنيس بن قتادة بن ربيعة، من بني عمرو بن عوف، روت عنها عائشة."],[37815,"أخبرنا أبو الفرج بن أبي الرجاء وأبو ياسر بن أبي حبة، بإسنادهما عن مسلم بن الحجاج، حدثنا عبيد الله بن سعيد ومحمد بن أبي عمر المكي، قالا: حدثنا المقرئ، أخبرنا سعيد بن أبي أيوب، حدثني أبو الأسود، عن عروة، عن عائشة، عن جذامة بنت وهب أخت عكاشة، قالت: حضرت رسول الله صلى الله عليه وآله وسلم في أناس وهو يقول: «لقد هممت أن أنهى عن الغيلة، فنظرت في الروم وفارس، فإذا هم يغيلون أولادهم ولا يضر أولادهم ذلك شيئا»"],[37816,"ثم سألوه عن العزل فقال رسول الله صلى الله عليه وآله وسلم: «ذلك الوأد الخفي»."],[37817,"أخرجه الثلاثة"],[37818,"٦٨٠٤ - الجرباء بنت قسامة"],[37819,"الجرباء بنت قسامة بن قيس بن عبيد بن طريف بن مالك أخت حنظلة بن قسامة وعمة زينب بنت حنظلة."],[37820,"ذكرها أبو عمر في زينب، ولم يذكرها ههنا، وذكرها الزبير بن أبي بكر، وقالت: قدمت على النبي صلى الله عليه وآله وسلم فتزوجها طلحة بن عبد الله، فولدت له أم إسحاق بنت طلحة."],[37821,"٦٨٠٥ - جسرة بنت دجاجة"],[37822,"د ع: جسرة بنت دجاجة روى عثمان بن علي، عن قدامة، عن جسرة بنت دجاجة، قالت: أتانا آت يوم وفاة رسول الله صلى الله عليه وآله وسلم فأشرف على الجبل، وقال: يا أهل الوادي، انخرق الدين ثلاث مرات مات نبيكم الذي تزعمون."],[37823,"فإذا هو شيطان، فحسبناه فوجدناه مات ذلك اليوم."],[37824,"وقد روت عن أبي ذر."],[37825,"أخبرنا يعيش بن صدقة بن علي، بإسناده عن أحمد بن شعيب، قال: أخبرنا نوح بن حبيب، أخبرنا يحيى بن سعيد القطان، حدثنا قدامة بن عبد الله، قال: حدثتني جسرة بنت دجاجة، قالت: سمعت أبا ذر يقول: قام النبي صلى الله عليه وآله وسلم حتى أصبح بآية، والآية ﴿إِنْ تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ وَإِنْ تَغْفِرْ لَهُمْ فَإِنَّكَ أَنْتَ الْعَزِيزُ الْحَكِيمُ﴾."],[37826,"أخرجها ابن منده، وأبو نعيم"],[37827,"٦٨٠٦ - جعدة بنت عبد الله"],[37828,"جعدة بنت عبد الله بن ثعلبة بن عبيد بن ثعلبة بن غنم بن مالك بن النجار الأنصارية كان النبي صلى الله عليه وآله وسلم يأتي إلى منزلها ويأكل عندها."],[37829,"قاله العدوي، ذكرها الغساني."],[37830,"٦٨٠٧ - جعدة بنت عبيد"],[37831,"جعدة بنت عبيد بن ثعلبة بن سواد بن غنم بن حارثة بن النعمان الأنصارية بايعت النبي صلى الله عليه وآله وسلم. قاله ابن حبيب."],[37832,"٦٨٠٨ - جمانة بنت أبي طالب"],[37833,"س: جمانة بنت أبي طالب قسم لها رسول الله صلى الله عليه وآله وسلم ثلاثين وسقا من خيبر."],[37834,"رواه عمار، عن سلمة، عن ابن إسحاق، وقال أبو أحمد العسكري في ترجمة عبد الله بن أبي سفيان بن الحارث بن عبد المطلب: أمة جمانة بنت أبي طالب."],[37835,"وقال: هو الذي تزوج أمامة بنت أبي العاص بن الربيع، وأمها زينب بنت رسول الله صلى الله عليه وآله وسلم. والصحيح أن الذي تزوجها المغيرة بن نوفل بن الحارث بن عبد المطلب، وهو ابن عم عبد الله، وهذه جمانة أخت أم هانئ، قاله الزبير بن بكار."],[37836,"أخرجه أبو موسى."],[37837,"٦٨٠٩ - جمرة بنت عبد الله"],[37838,"ب د ع: جمرة بنت عبد الله التميمة اليربوعية من بني يربوع بن حنظلة بن مالك بن زيد مناة بن تميم، عدادها في أهل الكوفة."],[37839,"روى عطوان بن مسكان، عن جمرة بنت عبد الله اليربوعية، قالت: ذهب بي أبي إلى النبي صلى الله عليه وآله وسلم فقال: ادع الله لبنتي هذه بالبركة."],[37840,"قالت: فأجلسني النبي صلى الله عليه وآله وسلم في حجرة، ثم وضع يده على رأسي فدعا لي بالبركة."],[37841,"أخرجه الثلاثة."],[37842,"عطوان: قد ضبطها أبو عمر بفتح العين والطاء، وقيل: بضم العين، وتسكين الطاء."],[37843,"والله أعلم."],[37844,"٦٨١٠ - جمرة بنت قحافة"],[37845,"ب د ع: جمرة بنت قحافة الكندية تعد في أهل الكوفة."],[37846,"روى شبيب بن غرقدة، عن جمرة بنت قحافة، قالت: كنت مع أم سلمة أم المؤمنين في حجة الوداع، فسمعت النبي صلى الله عليه وآله وسلم يقول: «يا أمتاه، هل بلغتكم؟» قالت: فقال بني لها: يا أمه، ماله يدعو أمه؟ قالت: فقلت: يا بني، إنما يدعو أمته، وهو يقول: «ألا إن أموالكم وأعراضكم ودماءكم عليكم حرام كحرمة يومكم هذا، في بلدكم هذا في شهركم هذا»."],[37847,"أخرجه الثلاثة، وقال أبو عمر،: إسناد حديثها يعبأ به."],[37848,"٦٨١١ - جمرة بنت النعمان"],[37849,"ع س: جمرة بنت النعمان العدوية روى الواقدي، عن شعيب بن ميمون المخزومي، عن أبي مراية البلوي، عن جمرة بنت النعمان، وكانت لها صحبة، قالت: «أمر رسول الله صلى الله عليه وآله وسلم أن يدفن الشعر والدم»."],[37850,"أخرجه أبو نعيم، وأبو موسى."],[37851,"٦٨١٢ - جميل بنت يسار"],[37852,"س: جميل بنت يسار أخت معقل بن يسار المزنية، امرأة أبي البداح فطلقها، وفيها نزل قوله تعالى: ﴿وَإِذَا طَلَّقْتُمُ النِّسَاءَ فَبَلَغْنَ أَجَلَهُنَّ فَلا تَعْضُلُوهُنَّ أَنْ يَنْكِحْنَ أَزْوَاجَهُنَّ﴾."],[37853,"الآية."],[37854,"أخبرنا أبو محمد عبد الله بن علي بن عبد الله التكريتي، بإسناده عن علي بن أحمد بن متوية، قال: نزلت هذه الآية في أخت معقل بن يسار، قال: أخبرنا محمد بن عبد الرحمن بن محمد بن أحمد بن جعفر النحوي، حدثنا محمد بن محمد بن أحمد بن إسحاق، أخبرني أحمد بن محمد بن الحسين، حدثنا أحمد بن حفص بن عبد الله، حدثنا أبي، أخبرنا إبراهيم بن طهمان، عن يونس بن عبيد، عن الحسن، قال في هذه الآية: «حدثني معقل بن يسار، أنها نزلت فيه، قالت: كنت زوجت أختا لي من رجل فطلقها، حتى إذا انقضت عدتها جاء يخطبها، فقلت له: زوجتك وأكرمتك وأفرشتك فطلقتها ثم جئت تخطبها! لا، والله لا تعود إليها أبدا، قال: وكان رجلا لا بأس به، وكانت المرأة تريد أن ترجع إليه، فأنزل الله عز وجل هذه الآية."],[37855,"فقلت: الآن أفعل يا رسول الله."],[37856,"فزوجتها إياه»."],[37857,"وروى ابن جريج، عن الحسن، قال: اسمها جميل."],[37858,"وسماها الكلبي في تفسيره جميلا."],[37859,"وقال الأمير أبو نصر: وأما جميل بضم الجيم وفتح الميم فهي جميل بنت يسار، أخت معقل بن يسار، وهي التي عضلها أخوها."],[37860,"أخرجها أبو موسى"],[37861,"٦٨١٣ - جميلة بنت أبي ابن سلول"],[37862,"ب د ع: جميلة بنت أبي ابن سلول أخت عبد الله رأس المنافقين."],[37863,"وقيل كانت ابنة عبد الله، وهو وهم، وكانت تحت حنظلة بن أبي عامر غسيل الملائكة، فقتل عنها يوم أحد، فتزوجها ثابت بن قيس بن شماس، فتركته ونشزت عليه، فأرسل إليها رسول الله صلى الله عليه وآله وسلم: «ما كرهت من ثابت؟» فقالت: والله ما كرهت منه شيئا إلا دمامته فقال لها: «أتردين عليه حديقته؟» قالت: نعم."],[37864,"ففرق بينهما، وتزوجها بعده مالك بن الدخشم، ثم تزوجها بعد مالك حبيب بن إساف."],[37865,"أخرجها الثلاثة، قال أبو عمر: روى البصريون هكذا، يعني: جميلة بنت أبي، وروى أهل المدينة فقالوا: حبيبة بنت سهل الأنصاري وأما ابن منده فلم يذكر أنها كانت تحت حنظلة فقتل عنها، وذكر ما سوى ذلك."],[37866,"٦٨١٤ - جميلة بنت أبي صعصعة"],[37867,"جميلة بنت أبي صعصعة الأنصارية من بني مازن."],[37868,"بايعت النبي صلى الله عليه وآله وسلم. قاله ابن حبيب."],[37869,"٦٨١٥ - جميلة امرأة أوس بن الصامت"],[37870,"د ع: جميلة ويقال خولة وقيل خويلة امرأة أوس بن الصامت."],[37871,"أخبرنا أبو أحمد عبد الوهاب بن علي، بإسناده عن أبي داود، حدثنا هارون بن عبد الله، أخبرنا محمد بن الفضل، أخبرنا حماد بن سلمة، عن هشام بن عروة، عن أبيه، عن عائشة، «أن جميلة امرأة أوس بن الصامت كان به لمم فإذا اشتد به ظاهر من امرأته، فأنزل الله عز وجل كفارة اليمين»."],[37872,"أخرجه ابن منده، وأبو نعيم، وقال أبو نعيم: كذا قال يعني: ابن منده: جميلة، وإنما هي خويلة فأوصل الواو بالياء فقال: جميلة"],[37873,"٦٨١٦ - جميلة بنت ثابت بن أبي الأقلح"],[37874,"ب د ع: جميلة بنت ثابت بن أبي الأقلح الأنصارية أخت عاصم بن ثابت، امرأة عمر بن الخطاب، تكنى أم عاصم بابنها عاصم بن عمر بن الخطاب، سمته باسم أخيها."],[37875,"روى حماد بن سلمة، عن عبيد الله بن عمر، عن نافع، عن ابن عمر، «أنها كان اسمها عاصية، فلما أسلمت سماها رسول الله صلى الله عليه وآله وسلم جميلة»."],[37876,"تزوجها عمر سنة سبع من الهجرة، فولدت له عاصما، ثم طلقها عمر فتزوجها يزيد بن جارية، فولدت له عبد الرحمن بن يزيد، فهو أخو عاصم لأمة، وهي التي جاء فيها الحديث، أن عمر ركب إلى قباء فوجد ابنه عاصما يلعب مع الصبيان، فحمله بين يديه، فأدركته جدته الشموس بنت أبي عامر، فنازعته إياه، حتى انتهى إلى أبي بكر الصديق، فقال له أبو بكر: خل بينه وبينهما."],[37877,"فما راجعه وسلمه إليها."],[37878,"أخرجها الثلاثة."],[37879,"٦٨١٧ - جميلة بنت أبي جهل"],[37880,"د ع: جميلة وقيل جويرية بنت أبي جهل بن هشام المخزومية أدركت النبي صلى الله عليه وآله وسلم. روى عنها زوجها، أنها قالت: مر بنا رسول الله صلى الله عليه وآله وسلم فاستسقى فسقيته، وقال: «خير أمتي قرني، ثم الذين يلونهم، ثم الذي يلونهم»."],[37881,"أخرجها ابن منده، وأبو نعيم."],[37882,"٦٨١٨ - جميلة بنت زيد"],[37883,"جميلة بنت زيد بن صيفي بن عمرو بن جشم بن حارثة الأنصارية أخت عبلة بن زيد."],[37884,"بايعت النبي صلى الله عليه وآله وسلم تقدم نسبها عند ذكر أخيها."],[37885,"٦٨١٩ - جميلة بنت سعد"],[37886,"ب د ع: جميلة بنت سعد بن الربيع الأنصارية تقدم نسبها عند ذكر أبيها."],[37887,"أدركت النبي صلى الله عليه وآله وسلم وروت عنه."],[37888,"روى عنها ثابت بن عبيد الأنصاري أن أباها وعمها قتلا يوم أحد، فدفنا في قبر واحد."],[37889,"وهي امرأة زيد بن ثابت، قال ثابت بن عبيد: دخلت على جميلة بنت سعد بن الربيع، فقربت إلي رطبا أو تمرا فقلت لها: أرى هذا ورثت عن أبيك؟ فقالت: ما ورثت من أبي شيئا، قتل أبي قبل أن تنزل الفرائض."],[37890,"أخرجها الثلاثة."],[37891,"٦٨٢٠ - جميلة بنت سنان"],[37892,"جميلة بنت سنان بن ثعلبة بن عامر بن مجدعة بن جشم بن حارثة الأنصارية الأوسية بايعت النبي صلى الله عليه وآله وسلم. قاله ابن حبيب."],[37893,"٦٨٢١ - جميلة بنت عبد الله بن أبي ابن سلول"],[37894,"د: جميلة بنت عبد الله بن أبي ابن سلول وهي ابنة أخي الأولى التي ترجمتها جميلة بنت أبي ابن سلول."],[37895,"تزوجها حنظلة بن أبي عامر، فقتل عنها يوم أحد، ثم خلف عليها ثابت بن قيس بن شماس، فمات عنها، ثم خلف عليها مالك بن الدخشم من بني عوف بن الخزرج، ثم خلف عليها حبيب بن يساف، من بني الحارث بن الخزرج."],[37896,"أخرجها ابن منده، ورواه عن محمد بن سعد كاتب الواقدي."],[37897,"قال أبو نعيم: قال المتأخر يعني: ابن منده: جميلة بنت عبد الله بن أبي بن سلول، قتل عنها حنظلة، فتزوجها ثابت، وحكاه عن محمد بن سعد الواقدي، وأفردها عن المختلعة."],[37898,"وخالف الجماعة واهما فيه بعد أن ذكر الصحيح في الترجمة الأولى التي هي جميلة بنت أبي."],[37899,"قلت: الحق مع أبي نعيم، وأعجب ما في وهم ابن منده أنه ذكر في الترجمة الأولى أنها اختلعت من زوجها ثابت بن قيس، وذكر في هذه أنه توفي عنها فخلف عليها مالك، ولا شك حيث نقل في هذه أنها كانت زوجة حنظلة، ولم ينقل في تلك أنها كانت زوج حنظلة، ظنهما اثنين، أو أنه حيث رأى في هذه أن ثابتا توفي عنها، وفي تلك أنها اختلعت منه ظنهما اثنتين، أو أنه رأى جميلة بنت أبي، ثم رأى جميلة بنت عبد الله بن أبي، ظنهما اثنتين، وليس كذلك، فإنها قيل فيها: جميلة بنت أبي، وقيل: بنت عبد الله بن أبي، والأول هو الصحيح، والثاني وهم، وليس بشيء، ولو نظر فيهما لعلم أنهما واحدة، والله أعلم."],[37900,"٦٨٢٢ - جميلة بنت عبد الله بن حنظلة"],[37901,"جميلة بنت عبد الله بن حنظلة الأنصارية ثم من بلحبلى، بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[37902,"٦٨٢٣ - جميلة بنت عبد العزى"],[37903,"ب: جميلة بنت عبد العزى بن قطن من بني المصطلق، بطن من خزاعة."],[37904,"كانت من المبايعات، وهي زوج عبد الرحمن بن العوام، أخي الزبير بن العوام أم بنيه لا يعرف لها رواية."],[37905,"أخرجها أبو عمر."],[37906,"٦٨٢٤ - جميلة بنت عمر بن الخطاب"],[37907,"جميلة بنت عمر بن الخطاب روى حماد بن سلمة، عن عبيد الله، عن نافع، عن ابن عمر، «أن ابنة لعمر كان يقال لها عاصية فسماها رسول الله صلى الله عليه وآله وسلم جميلة»."],[37908,"هكذا أخرجه الغساني مستدركا على أبي عمر، وليس بشيء، فإن جميلة امرأة عمر، وهي بنت ثابت، كان اسمها عاصية «فسماها رسول الله صلى الله عليه وآله وسلم جميلة»، وقد تقدم ذلك من رواية حماد بن سلمة، بإسناده."],[37909,"٦٨٢٥ - جميمة بنت حمام"],[37910,"جميمة بنت حمام بن الجموح الأنصارية من بلحبلى."],[37911,"بايعت النبي صلى الله عليه وآله وسلم. قاله ابن حبيب."],[37912,"٦٨٢٦ - جميمة بنت صيفي"],[37913,"جميمة بنت صيفى بن صخر بن خنساء الأنصارية بايعت النبي صلى الله عليه وآله وسلم. قاله ابن حبيب، استدركها أبو علي الغساني على أبي عمر."],[37914,"٦٨٢٧ - جهدمة امرأة بشير ابن الخصاصية"],[37915,"ب د ع: جهدمة امرأة بشير بن الخصاصية وهي من بني شيبان، ولها رؤية للنبي صلى الله عليه وآله وسلم روى أبو جناب يحيى بن أبي حبة، عن إياد بن لقيط، عن جهدمة امرأة بشير بن الخصاصية، قالت: «كان اسم بشير زحمان فسماه النبي صلى الله عليه وآله وسلم بشير»، وقالت: «أنا رأيت رسول الله صلى الله عليه وآله وسلم فخرج من بيته ينفض رأسه وقد اغتسل وبرأسه ردع من الحناء»."],[37916,"أخرجه الثلاثة."],[37917,"٦٨٢٨ - جويرية بنت أبي جهل"],[37918,"د: جويرية بنت أبي جهل وهي التي خطبها علي بن أبي طالب رضي الله عنه، وقيل: اسمها جميلة."],[37919,"أخبرنا أبو محمد عبد الله بن علي بن سويدة، أخبرنا أبو الفضل بن ناصر، أخبرنا أبو صالح أحمد بن عبد الملك المؤذن، أخبرنا أبو القاسم عبد الملك بن محمد بن بشران، حدثنا أبو سهل أحمد بن محمد بن زياد القطان، حدثنا عبد الكريم بن الهيثم الديرعاقولي، حدثنا أبو اليمان الحكم بن نافع، أخبرني شعيب، عن الزهري، عن علي بن الحسين، أن المسور بن مخرمة، أخبره، أن علي بن أبي طالب خطب ابنة أبي جهل، وعنده فاطمة بنت رسول الله صلى الله عليه وآله وسلم فلما سمعت فاطمة عليها السلام أتت رسول الله صلى الله عليه وآله وسلم فقالت: إن قومك يتحدثون أنك لا تغضب لبناتك، وهذا علي ناكح ابنة أبي جهل، قال المسور: فقام رسول الله صلى الله عليه وآله وسلم فسمعته حين تشهد فقال: «أما بعد فإني أنكحت أبا العاص بن الربيع، فحدثني فصدقني، وإن فاطمة بنت محمد بضعة مني، وأنا أكره أن تفتنوها، وإنه والله لا يجتمع ابنة رسول الله صلى الله عليه وآله وسلم وابنة عدو الله عند رجل واحد»."],[37920,"فترك علي الخطبة، ولما ترك علي الخطبة تزوجها عتاب بن أسيد، فولدت له عبد الرحمن بن عتاب."],[37921,"أخرجها ابن منده"],[37922,"٦٨٢٩ - جويرية بنت الحارث"],[37923,"ب د ع: جويرية بنت الحارث بن أبي ضرار بن حبيب بن عائذ بن مالك بن جذيمة وهو المصطلق بن سعد بن عمرو بن ربيعة بن حارثة بن عمرو مزيقيا، وعمرو هو أبو خزاعة كلها، الخزاعية المصطلقية."],[37924,"سباها رسول الله صلى الله عليه وآله وسلم يوم المريسيع، وهي غزوة بني المصطلق، سنة خمس، وقيل: سنة ست، وكانت تحت مسافع بن صفوان المصطلقي، فوقعت في سهم ثابت بن قيس بن شماس أو ابن عم له."],[37925,"أخبرنا أبو جعفر عبيد الله بن أحمد، بإسناده عن يونس بن بكير، عن ابن إسحاق، قال: حدثني محمد بن جعفر بن الزبير، عن عروة بن الزبير، عن عائشة، قالت: لما قسم رسول الله صلى الله عليه وآله وسلم سبايا بني المصطلق، وقعت جويرية بنت الحارث في السهم لثابت بن قيس بن شماس، أو لابن عم له، فكاتبته على نفسها، وكانت امرأة حلوة ملاحة، لا يراها أحد إلا أخذت بنفسه، فأتت رسول الله صلى الله عليه وآله وسلم تستعينه في كتابتها، قالت عائشة: فوالله ما هو إلا أن رأيتها فكرهتها، وقلت: يرى منها ما قد رأيت! فلما دخلت على رسول الله صلى الله عليه وآله وسلم قالت: يا رسول الله، أنا جويرية بنت الحارث، سيد قومه، وقد أصابني من البلاء ما لم يخف عليك، وقد كاتبت على نفسي، فأعني على كتابتي، فقال رسول الله صلى الله عليه وآله وسلم: «أو خير من ذلك أؤدي عنك كتابك وأتزوجك؟» فقالت: نعم، ففعل رسول الله صلى الله عليه وآله وسلم فبلغ الناس أنه قد تزوجها، فقالوا: أصهار رسول الله صلى الله عليه وآله وسلم. فأرسلوا ما كان في أيديهم من بني المصطلق، فلقد أعتق بها مائة أهل بيت من بني المصطلق، فما أعلم امرأة، أعظم بركة منها على قومها، ولما تزوجها رسول الله صلى الله عليه وآله وسلم حجبها، وقسم لها، وكان اسمها برة فسماها رسول الله صلى الله عليه وآله وسلم جويرية."],[37926,"رواه شعبة، ومسعر، وابن عيينة، عن محمد بن عبد الرحمن مولى آل طلحة، عن كريب مولى ابن عباس، عن ابن عباس"],[37927,"وروى إسرائيل، عن محمد بن عبد الرحمن، عن كريب، عن ابن عباس، قال: «كان اسم ميمونة برة فسماها رسول الله صلى الله عليه وآله وسلم ميمومة»، قاله أبو عمر."],[37928,"روت جويرية عن النبي صلى الله عليه وآله وسلم روى عنها ابن عباس وجابر، وابن عمر، وعبيد بن السباق، وغيرهم."],[37929,"أخبرنا أبو جعفر، بإسناده عن ابن إسحاق، قال: ثم تزوج رسول الله صلى الله عليه وآله وسلم بعد زينب بنت جحش جويرية بنت الحارث، وكانت قلبه عند ابن عم لها يقال له: ابن ذي الشفر، فمات رسول الله صلى الله عليه وآله وسلم ولم يصب منها ولدا"],[37930,"أخبرنا إبراهيم بن محمد، وغيره، بإسنادهم عن أبي عيسى، حدثنا محمد بن بشار، حدثنا محمد بن جعفر، حدثنا شعبة، عن محمد بن عبد الرحمن، قال: سمعت كريبا يحدث، عن ابن عباس، عن جويرية بنت الحارث، أن النبي صلى الله عليه وآله وسلم مر عليها وهي في مسجدها، ثم مر عليها قريبا من نصف النهار، فقال لها: «ما زلت على حالك؟» قالت: نعم."],[37931,"قال: «إلا أعلمك كلمات تقولينها: سبحان الله عدد خلقه، سبحان الله عدد خلقه، سبحان الله عدد خلقه، سبحان الله رضا نفسه، سبحان الله رضا نفسه، سبحان الله رضا نفسه، سبحان الله زنة عرشه، سبحان الله زنة عرشه، سبحان الله زنة عرشه، سبحان الله مداد كلماته، سبحان الله مداد كلماته، سبحان الله مداد كلماته»."],[37932,"أخرجه الثلاثة"],[37933,"٦٨٣٠ - جويرية بنت المجلل"],[37934,"جويرية بنت المجلل تكنى أم جميل وهي مشهورة بكنيتها، واختلف في اسمها."],[37935,"وهي امرأة حاطب بن الحارث الجمحي، ونذكرها في الكنى إن شاء الله تعالى أتم من هذا."],[37936,"أخرجها أبو عمر."],[37937,"حرف الحاء"],[37938,"٦٨٣١ - حبشية الخزاعية"],[37939,"د ع: حبشية الخزاعية العدوية عدي خزاعة زوجة سفيان بن معمر بن حبيب البياض من مهاجرة الحبشة."],[37940,"ورواه ابن لهيعة، عن أبي الأسود، عن عروة وهو تصحيف إنما هي حسنة امرأة سفيان بن معمر بن حبيب الجمحي، كما ذكره ابن إسحاق، وغيره."],[37941,"أخرجها ابن منده، وأبو نعيم."],[37942,"٦٨٣٢ - حبيبة بنت أبي أمامة"],[37943,"ب د ع: حبيبة بنت أبي إمامة أسعد بن زرارة تقدم نسبها عند ذكر أبيها، وهي أنصارية من الخزرج، تزوجها سهل بن حنيف، فولدت له أبا أمامة، سماه رسول الله صلى الله عليه وآله وسلم أسعد وكناه أبا أمامة، باسم جده وكنيته."],[37944,"وأختها الفارعة امرأة نبيط بن جابر، من بني مالك بن النجار."],[37945,"روى عبد الله بن إدريس، عن محمد بن عمارة الأنصاري المدني، عن زينب بنت نبيط امرأة أنس بن مالك، قالت: «أوصى أبو أمامة بأمي وخالتي إلى رسول الله صلى الله عليه وآله وسلم فقدم عليه حلي من ذهب ولؤلؤ، يقال له: الرعاث، فحلاهن رسول الله صلى الله عليه وآله وسلم من ذلك الرعاث، قالت زينب: فأدركت بعض ذلك»."],[37946,"ورواه إبراهيم بن محمد الأسلمي، عن محمد بن عمارة: حدثتني أمي حبيبة وخالتي كبشة أختا فريعة بنت أبي إمامة."],[37947,"أخرجه الثلاثة."],[37948,"٦٨٣٣ - حبيبة بنت أبي تجراة"],[37949,"ب د ع: حبيبة بنت أبي تجراة الشيبية العبدرية من بني عبد الدار، يقال: حبيبة بالتشديد، وهي مكية."],[37950,"أخبرنا أبو ياسر، بإسناده إلى عبد الله، حدثني أبي، حدثنا يونس، عن عبد الله بن المؤمل، عن عمر بن عبد الرحمن، عن عطاء، عن صفية بنت شيبة، عن حبيبة بنت أبي تجراة: قالت: دخلنا دار أبي حسين في نسوة من قريش، ورسول الله صلى الله عليه وآله وسلم يطوف بين الصفا والمروة، قالت: وهو يسعى يدور به إزاره من شدة السعي، وهو يقول: «اسعوا، فإن الله كتب عليكم السعي» قال أبو عمر: حديثها مثل حديث تملك الشيبية، روت عنها صفية بنت شيبة."],[37951,"وفي إسناده اضطرب على عبد الله بن المؤمل."],[37952,"أخرجه الثلاثة."],[37953,"قلت: قد جعلها أبو عمر غير تملك، وأما ابن منده، وأبو نعيم فلم يذكرا ما يدل على أنها هي ولا غيرها، والذي يغلب على ظني أنها هي، واختلف في اسمها، والله أعلم."],[37954,"٦٨٣٤ - حبيبة بنت جحش"],[37955,"ب: حبيبة بنت جحش قاله قوم وزعموا أنها تكنى أم حبيب."],[37956,"والأشهر أنها أم حبيبة مشهورة بكنيتها، وسنذكرها في الكنى أتم من هذا إن شاء الله تعالى."],[37957,"أخرجها أبو عمر مختصرا."],[37958,"٦٨٣٥ - حبيبة بنت زيد"],[37959,"ب د ع: حبيبة بنت زيد بن الخارجة بن أبي زهير الخزرجي زوج أبي بكر الصديق، قاله ابن منده، وأبو نعيم."],[37960,"وقال أبو عمر: حبيبة، وقيل: مليكة بنت خارجة بن زيد بن أبي زهير بن مالك بن امرئ القيس بن مالك بن ثعلبة بن كعب بن الخزرج بن الحارث بن الخزرج، زوج أبي بكر الصديق، وهي التي، قال فيها أبو بكر في مرضه الذي مات فيه: قد ألقي في روعي أن ذا بطن بنت خارجة جارية، سمتها عائشة أم كلثوم: تزوجها طلحة ابن عبيد الله، فولدت له زكريا وعائشة."],[37961,"وروى ابن منده، وأبو نعيم أن أبا بكر استأذن رسول الله صلى الله عليه وآله وسلم حين رأى منه خفة في مرضه أن يأتي ابنة خارجة، فأذن له في حديث طويل."],[37962,"أخرجه الثلاثة."],[37963,"قلت: قدم أبو عمر في نسبها خارجة على زيد، وقدم ابن منده، وأبو نعيم زيدا على خارجة، والصواب قول أبي عمر."],[37964,"٦٨٣٦ - حبيبة بنت أبي سفيان"],[37965,"ب د ع: حبيبة بنت أبي سفيان قاله أبان بن صمعة."],[37966,"روى عنها محمد بن سيرين، قال: حدثتني حبيبة بنت أبي سفيان، قالت: سمعت النبي صلى الله عليه وآله وسلم يقول: «من مات له ثلاثة من الولد … ...»."],[37967,"لم يرو عنها غير ابن سيرين، ولا تعرف لأبي سفيان بنت اسمها حبيبة، قال أبو عمر: والذي أظنه حبيبة بنت أم حبيبة بنت أبي سفيان."],[37968,"وقد ذكرها ابن عيينة في حديثه، عن الزهري، عن زينب بنت أم سلمة، عن حبيبة بنت أم حبيبة، عن أمها أم حبيبة، عن زينب بنت جحش، قالت: استيقظ رسول الله صلى الله عليه وآله وسلم من نوم محمرا وجهه، وهو يقول: «لا إله إلا الله، ويل للعرب من شر قد اقترب …"],[37969,"» الحديث."],[37970,"في هذا الحديث أربع نسوة راويات، رأين النبي صلى الله عليه وآله وسلم: زينب وحبيبة ربيبتاه، أم حبيبة وزينب بنت جحش زوجتاه، وحبيبة بنت أم حبيبة، اسم أبيها عبيد الله بن جحش تنصر بالحبشة، ومات هناك نصرانيا."],[37971,"أخرجه الثلاثة، إلا أن ابن منده وأبا نعيم ذكراها فقالا: حبيبة خادمة عائشة، ورويا عن أبان بن صمعة، عن محمد ابن سيرين، وعن حبيبة، قالت: كنت في بيت عائشة فدخل النبي صلى الله عليه وآله وسلم فقال: «ما من مسلم يموت له ثلاث من الولد إلا جيء بهم يوم القيامة فيقال لهم:"],[37972,"ادخلوا الجنة فيقولون: حتى يدخلها آباؤنا."],[37973,"فيقال لهم في الثالثة أو الرابعة: ادخلوا أنتم وآباؤكم»."],[37974,"٦٨٣٧ - حبيبة بنت سهل الأنصارية"],[37975,"ب د ع: حبيبة بنت سهل الأنصارية أراد النبي صلى الله عليه وآله وسلم أن يتزوجها ثم تركها فتزوجها ثابت بن قيس بن شماس."],[37976,"روت عنها عمرة."],[37977,"وهي التي اختلعت من زوجها ثابت بن قيس بن شماس، وقد تقدم أن التي اختلعت منه جميلة بنت أبي ابن سلول."],[37978,"أخبرنا عبد الوهاب بن هبة الله، بإسناده عن عبد الله بن أحمد، حدثني أبي، حدثنا عبد القدوس بن بكر بن خنيس، أخبرنا حجاج، عن عمرو بن شعيب، عن أبيه، عن عبد الله بن عمرو."],[37979,"ح والحجاج، عن محمد بن سليمان بن أبي حثمة، عن عمه سهل بن أبي حثمة، قالا: كانت حبيبة بنت سهل تحت ثابت بن قيس بن شماس فكرهته، وكان رجلا دميما، فجاءت إلى النبي صلى الله عليه وآله وسلم فقالت: يا رسول الله، إني لأراه، ولولا مخافة الله لبزقت في وجهه، فقال رسول الله صلى الله عليه وآله وسلم: «تردين عليه حديقته التي أصدقك؟» قالت: نعم، فأرسل إليه فردت عليه حديقته، وفرق بينهما."],[37980,"وكان ذلك أول خلع في الإسلام."],[37981,"ورواه ابن جريج، ويزيد بن هارون، وهشيم، ويحيى بن أبي زائدة، عن يحيى بن سعيد الأنصاري، عن عمرة، عن حبيبة، وقالوا: فتزوجها ثابت، وكان في خلق ثابت شدة فضربها، وذكروا الخلع."],[37982,"أخرجه الثلاثة، قال أبو عمر: جائز أن يكون حبيبة وجميلة بنت أبي اختلعتا من ثابت، والله أعلم"],[37983,"٦٨٣٨ - حبيبة بنت شريق"],[37984,"ب د ع: حبيبة بنت شريق أدركت النبي صلى الله عليه وآله وسلم وروت عن بديل بن ورقاء."],[37985,"روى حديثهما صالح بن كيسان، عن عيسى بن مسعود بن الحكم الزرقي، عن جدته حبيبة بنت شريق أنها كانت مع أمها العجماء في أيام الحج بمنى، قالت: فجاءهم بديل بن ورقاء على راحلة رسول الله صلى الله عليه وآله وسلم فنادى أن رسول الله صلى الله عليه وآله وسلم قال: «من كان صائما فليفطر، فإنها أيام أكل وشرب»."],[37986,"أخرجه الثلاثة."],[37987,"٦٨٣٩ - حبيبة بنت عبيد الله بن جحش"],[37988,"د ع: حبيبة بنت عبيد الله بن جحش ربيبة رسول الله صلى الله عليه وآله وسلم."],[37989,"أمها أم حبيبة بنت أبي سفيان بن حرب زوج النبي صلى الله عليه وآله وسلم. هاجرت مع أمها إلى الحبشة، ورجعت بها إلى المدينة."],[37990,"قاله ابن إسحاق، وموسى بن عقبة، وغيرهما."],[37991,"روت عن أمها الحديث الرباعي من الصحابيات، وقد تقدم في حبيبة بنت أبي سفيان."],[37992,"أخرجه ابن منده، وأبو نعيم."],[37993,"قلت: قد استدركه أبو موسى على ابن منده، وقد أخرجه ابن منده، فلا حجة له في استدراكه."],[37994,"٦٨٤٠ - حبيبة بنت عمرو بن حصن"],[37995,"د ع: حبيبة بنت عمرو بن حصن من بني عامر بن زريق أسلمت وبايعت لا تعرف لها رواية."],[37996,"أخرجها ابن منده، وأبو نعيم."],[37997,"٦٨٤١ - حبيبة بنت قيس"],[37998,"حبيبة بنت قيس بن زيد بن عامر بن سواد الأنصارية من بني ظفر، وهي أم عبيد الله بن معاذ الحارث، ابن عفراء."],[37999,"بايعت رسول الله صلى الله عليه وآله وسلم"],[38000,"٦٨٤٢ - حبيبة بنت مسعود"],[38001,"د ع: حبيبة بنت مسعود بن خالد من بني عامر بن زريق بايعت النبي صلى الله عليه وآله وسلم لا تعرف لها رواية."],[38002,"أخرجها ابن منده، وأبو نعيم."],[38003,"٦٨٤٣ - حبيبة بنت معتب"],[38004,"حبيبة بنت معتب بن عبيد بن سواد بن الهيثم كانت عند بشر بن الحارث، ولدت له بريدة بنت بشر، بايعت النبي صلى الله عليه وآله وسلم"],[38005,"٦٨٤٤ - حبيبة بنت مليل"],[38006,"د ع: حبيبة بنت مليل بن وبرة بن خالد بن العجلان الأنصاري من بني عوف من الخزرج."],[38007,"بايعت النبي صلى الله عليه وآله وسلم وتزوجها فروة بن عمرو بن ودقة بن عبيد بن عامر بن بياضة، فولدت له عبد الرحمن، قاله محمد بن سعد."],[38008,": أخرجه ابن منده، وأبو نعيم."],[38009,"٦٨٤٥ - حذاقة بنت الحارث"],[38010,"حذافة بنت الحارث السعدية وهي الشيماء عرفت به، قاله ابن إسحاق."],[38011,"وهي أخت النبي صلى الله عليه وآله وسلم من الرضاعة، وكانت تحتضنه مع أمها، ويرد ذكرها في الشين."],[38012,"٦٨٤٦ - حرملة بنت عبد الأسود"],[38013,"ب: حرملة بنت عبد الأسود من جذيمة بن أقيش بن عامر بن بياض الخزاعية وقيل: حريملة، أخرجها أبو عمر حريملة مصغرة، كذا ذكرها الطبري، وسماها ابن حبيب حرملة."],[38014,"٦٨٤٧ - حرملة بنت عبيد بن ثعلبة"],[38015,"حرملة بنت عبيد بن ثعلبة بن سواد بن غنم الأنصارية، من بني مالك بن الخزرج بايعت النبي صلى الله عليه وآله وسلم. قاله ابن حبيب"],[38016,"٦٨٤٨ - حزمة بنت قيس الفهرية"],[38017,"ب د ع: حزمة بنت قيس الفهرية أخت فاطمة بنت قيس."],[38018,"تزوجها سعيد بن زيد بن عمرو بن نفيل، فولدت له."],[38019,"حديثها عند الزهري، عن عبيد الله بن عبد الله."],[38020,"أخرجه الثلاثة."],[38021,"حزمة: بفتح الحاء وسكون الزاي."],[38022,"٦٨٤٩ - حسانة المزنية"],[38023,"ب س: حسانة المزنية كان اسمها جثامة، فقال لها رسول الله صلى الله عليه وآله وسلم: «أنت حسانة»."],[38024,"كانت صديقة خديجة زوج النبي صلى الله عليه وآله وسلم وكان رسول الله صلى الله عليه وآله وسلم يصلها، ويقول: «حسن العهد من الإيمان»."],[38025,"روى ابن أبي مليكة، عن عائشة، قالت: جاءت عجوز إلى النبي صلى الله عليه وآله وسلم فقال: «من أنت؟» قالت: أنا جثامة المزنية، قال: «بل أنت حسانة، كيف حالكم؟ كيف كنتم بعدنا؟» قالت: بخير بأبي أنت وأمي يا رسول الله."],[38026,"فلما خرجت قلت: يا رسول الله، تقبل على هذه العجوز كل هذا الإقبال؟! قال: «إنها كانت تأتينا زمان خديجة وإن حسن العهد من الإيمان»."],[38027,"أخرجه أبو عمر، وأبو موسى، قال أبو عمر: وهذه الرواية أولى بالصواب من رواية من روى ذلك في الحولاء بنت تويب."],[38028,"وروى ثابت، عن أنس قال: كان رسول الله صلى الله عليه وآله وسلم إذا أهديت إليه هدية، قال: «اذهبوا ببعضها إلى فلانة فإنها كانت صديقة خديجة» أو: «إنها كانت تحب خديجة»."],[38029,"٦٨٥٠ - حسنة أم شرحبيل"],[38030,"د ع: حسنة أم شرحبيل ابن حسنة ذكرت فيمن هاجر إلى أرض الحبشة."],[38031,"روى إبراهيم بن سعد فيمن هاجر إلى أرض الحبشة من بني جمح بن عمرو: سفيان بن معمر بن حبيب بن وهب بن حذافة بن جمح، ومعه ابناه خالد وجنادة، وامرأته حسنة، وهي أمهما، وأخوهما لأمهما شرحبيل بن حسنة."],[38032,"أخرجه ابن منده، وأبو نعيم."],[38033,"٦٨٥١ - حفصة بنت حاطب"],[38034,"حفصة بنت حاطب بن عمرو بن عبيد بن أمية بن زيد الأنصاري الأوسية أخت الحارث بن حاطب، بايعت النبي صلى الله عليه وآله وسلم. قاله ابن حبيب."],[38035,"٦٨٥٢ - حفصة بنت عمر رضي الله عنهما"],[38036,"ب د ع: حفصة بنت عمر بن الخطاب رضي الله عنهما تقدم نسبها عند ذكر أبيها، وهي من بني عدي بن كعب، وأمها وأم أخيها عبد الله بن عمر: زينب بنت مظعون، أخت عثمان بن مظعون."],[38037,"وكانت حفصة من المهاجرات، وكانت قبل رسول الله صلى الله عليه وآله وسلم تحت حنيس بن حذافة السهمي، وكان ممن شهد بدرا، وتوفي بالمدينة."],[38038,"فلما تأيمت حفصة ذكرها عمر لأبي بكر وعرضها عليه، فلم يرد عليه أبو بكر كلمة، فغضب عمر من ذلك، فعرضها على عثمان حين ماتت رقية بنت رسول الله صلى الله عليه وآله وسلم فقال عثمان: ما أريد أن أتزوج اليوم."],[38039,"فانطلق عمر إلى رسول الله صلى الله عليه وآله وسلم فشكا إليه عثمان، فقال رسول الله صلى الله عليه وآله وسلم: «يتزوج حفصة من هو خير من عثمان ويتزوج عثمان من هي خير من حفصة»، ثم خطبها إلى عمر، فتزوجها رسول الله صلى الله عليه وآله وسلم فلقي أبو بكر عمر، رضي الله عنهما فقال: لا تجد علي في نفسك، فإن رسول الله صلى الله عليه وآله وسلم ذكر حفصة، فلم أكن لأفشي سر رسول الله صلى الله عليه وآله وسلم فلو تركها لتزوجتها."],[38040,"وتزوجها رسول الله صلى الله عليه وآله وسلم سنة ثلاثة عند أكثر العلماء."],[38041,"وقال أبو عبيدة: سنة اثنتين من التاريخ، وتزوجها بعد عائشة، وطلقها تطليقة ثم ارتجعها، أمره جبريل عليه السلام بذلك، وقال: إنها صوامة قوامة، وإنها زوجتك في الجنة."],[38042,"وروى موسى بن علي بن رباح، عن أبيه، عن عقبة بن عامر، قال: «طلق رسول الله صلى الله عليه وآله وسلم حفصة تطليقة، فبلغ ذلك عمر، فحثا التراب على رأسه، وقال: ما يعبأ الله بعمر وابنته بعدها، فنزل جبريل عليه السلام، وقال: إن الله يأمرك أن تراجع حفصة بنت عمر، رحمة لعمر»."],[38043,"أخبرنا أبو الفضل بن أبي الحسن المخزومي، بإسناده عن أبي يعلى، حدثنا أبو كريب، أخبرنا يونس بن بكير، عن الأعمش، عن أبي صالح، عن ابن عمر، قال: دخل عمر على حفصة وهي تبكي، فقال لها: «ما يبكيك؟ لعل رسول الله صلى الله عليه وآله وسلم قد طلقك؟ إنه كان طلقك مرة ثم راجعك من أجلي، إن كان طلقك مرة أخرى لا أكلمك أبدا»."],[38044,"وأوصى عمر إلى حفصة بعد موته، وأوصت حفصة إلى أخيها عبد الله بن عمر بما أوصى به إليها عمر، وبصدقة تصدق بها بمال وقفته بالغاية."],[38045,"روت عن النبي صلى الله عليه وآله وسلم روى عنها أخوها عبد الله، وغيره"],[38046,"أخبرنا غير واحد، بإسنادهم، عن أبي عيسى، قال: حدثنا إسحاق بن منصور، أخبرنا معن، عن مالك، عن ابن شهاب، عن السائب بن يزيد، عن المطلب بن أبي وداعة السهمي، عن حفصة زوج النبي صلى الله عليه وآله وسلم أنها قالت: «ما رأيت رسول الله صلى الله عليه وآله وسلم في سبحته قاعدا حتى كان قبل وفاته بعام، فإنه كان يصلي في سبحته قاعدا ويقرأ بالسورة فيرتلها حتى تكون أطول من أطول منها»"],[38047,"وأخبرنا أبو الحرم بن ريان، بإسناده عن يحيى بن يحيى، عن مالك، عن نافع، عن ابن عمر، عن أخته حفصة، أن رسول الله صلى الله عليه وآله وسلم «كان إذا سكت المؤذن من الأذان لصلاة الصبح، صلى ركعتين خفيفتين قبل أن تقام الصلاة» وتوفيت حفصة حين بايع الحسن بن علي رضي الله عنهما معاوية وذلك في جمادى الأولى سنة إحدى وأربعين، وقيل: توفيت سنة خمس وأربعين، وقيل: سنة سبع وعشرين."],[38048,"أخرجها الثلاثة"],[38049,"٦٨٥٣ - حقة بنت عمرو"],[38050,"ب د ع: حقة بنت عمرو صحبت النبي صلى الله عليه وآله وسلم وصلت معه القبلتين."],[38051,"روى شريك، عن عاصم الأحول، عن أبي مجلز، عن حقة بنت عمرو، «وكانت قد أدركت النبي صلى الله عليه وآله وسلم وصلت معه القبلتين، وكانت إذا أحرمت أو أرادت أن تحرم قربت عيبتها فلبست من ثيابها ما شاءت وفيها العصفر»."],[38052,"أخرجه الثلاثة."],[38053,"٦٨٥٤ - حكيمة بنت غيلان"],[38054,"ب: حكيمة بنت غيلان الثقفية امرأة يعلى بن مرة."],[38055,"روت عن زوجها."],[38056,"ما أدري أسمعت من النبي صلى الله عليه وآله وسلم أم لا."],[38057,"قاله أبو عمر، وهو انفرد بإخراجها."],[38058,"حكيمة: بضم الحاء، وفتح الكاف، قاله الأمير."],[38059,"٦٨٥٥ - حليمة بنت أبي ذؤيب"],[38060,"ب د ع: حليمة بنت أبي ذؤيب، واسمه: عبد الله بن الحارث بن شجنة بن جابر بن رزام بن ناصرة بن سعد بن بكر بن هوازن."],[38061,"كذا نقل أبو عمر هذا النسب، ووافقه ابن أبي خيثمة."],[38062,"وقال هشام بن الكلبي، وابن هشام: شجنة بن جابر بن رزام بن ناصرة بن فصية بن نصر بن سعد بن بكر بن هوزان."],[38063,"وهذا أصح، إلا أن الكلبي، قال: اسم أبي ذؤيب: الحارث بن عبد الله بن شجنة."],[38064,"والباقي مثل ابن هشام."],[38065,"ووافقهما البلاذري."],[38066,"وأخبرنا أبو جعفر، بإسناده إلى يونس، عن ابن إسحاق، قال: فدفع رسول الله صلى الله عليه وآله وسلم إلى أمه، فالتمست له الرضعاء، واسترضع له من حلمية بنت أبي ذؤيب: عبد الله بن الحارث بن شجنة بن جابر بن رزام بن ناصرة بن فصية بن نصر بن سعد ابن بكر بن هوزان وهي أم رسول الله صلى الله عليه وآله وسلم من الرضاعة روى عنها عبد الله بن جعفر بن أبي طالب."],[38067,"أخبرنا عبيد الله بن أحمد البغدادي، بإسناده عن يونس، عن ابن إسحاق، قال: حدثني جهم ابن أبي الجهم مولى لامرأة من بني تميم، كانت عند الحارث بن حاطب، وكان يقال: مولى الحارث بن حاطب، قال: حدثني من سمع عبد الله بن جعفر بن أبي طالب يقول: حدثت عن حليمة بنت الحارث أم رسول الله صلى الله عليه وآله وسلم التي أرضعته، أنها قالت: «قدمت مكة في نسوة من بني سعد بن بكر نلتمس الرضعاء في سنة شهباء، فقدمت على أتان قمراء كانت أذمت بالركب، ومعي صبي لنا وشارف لنا، والله ما ننام ليلنا ذلك أجمع مع صبينا ذاك ما يجد في ثديي ما يغنيه، ولا في شارفنا ما يغذيه."],[38068,"فقدمنا مكة فوالله ما علمت منا امرأة إلا وقد عرض عليها رسول الله صلى الله عليه وآله وسلم فإذا قيل: يتيم، تركناه، وقلنا: ماذا عسى أن تصنع إلينا أمه! إنما نرجو المعروف من أب الولد، فأما أمه فماذا عسى أن تصنع إلينا، فوالله ما بقي من صواحبي امرأة إلا أخذت رضيعا غيري، فلما لم أجد غيره قلت لزوجي الحارث بن عبد العزى: والله إني لأكره أن أرجع من بين صواحبي ليس معي رضيع، لأنطلقن على ذلك اليتيم فلآخذنه، فقال: لا عليك."],[38069,"فذهبت، فأخذته، فما هو إلا أن أخذته فجئت به رحلي، فأقبل علي ثدياي بما شاء من لبن، وشرب أخوه حتى روى، وقام صاحبي إلى شارفي تلك فإذا بها حافل، فحلب ما شرب، وشربت حتى روينا فبتنا بخير ليلة، فقال لي صاحبي: يا حليمة، والله إني لأراك أخذت نسمة مباركة»."],[38070,"الحديث، وذكر فيه من معجزات ما هو مشور به صلى الله عليه وآله وسلم"],[38071,"أخبرنا أبو الفضل بن أبي الحسن الفقيه، بإسناده عن أحمد بن علي بن المثنى، قال: حدثنا عمرو بن الضحاك بن مخلد، حدثنا جعفر بن يحيى بن ثوبان، حدثنا عمارة بن ثوبان، أن أبا الطفيل، أخبره، أن النبي صلى الله عليه وآله وسلم «كان بالجعرانة يقسم لحما، وأنا يومئذ غلام أحمل عضو البعير، فأقبلت امرأة بدوية فلما دنت من النبي صلى الله عليه وآله وسلم بسط لها رداءه فجلست عليه، فقلت: من هذه؟ قالوا: أمه التي أرضعته، وكان اسم زوجها الذي أرضعت رسول الله صلى الله عليه وآله وسلم بلبنه الحارث بن عبد العزى بن رفاعة بن ملان بن ناصرة بن فصية بن نصر بن سعد بن بكر»."],[38072,"وقد روي عن ابن هشام في السيرة فصية بالفاء والقاف جميعا، والصواب بالفاء، قاله ابن دريد، وهو تصغير فصية."],[38073,"أخرجها الثلاثة"],[38074,"٦٨٥٦ - حمامة"],[38075,"حمامة ذكرها أبو عمر في جملة من كان يعذب في الله تعالى، واشتراها أبو بكر فأعتقها."],[38076,"قاله ابن الدباغ."],[38077,"٦٨٥٧ - حمنة بنت جحش"],[38078,"ب د ع: حمنة بنت جحش وقد تقدم نسبها في أخويها: عبد الله وعبيد، قال أبو نعيم: حمنة بنت جحش بن رياب، تكنى أم حبيبة."],[38079,"وقال ابن منده: حمنة بنت جحش، وقيل: حبيبة."],[38080,"قال أبو عمر: حمنة بنت جحش، كانت تستحاض هي وأختها أم حبيبة بنت جحش، وهي أخت زينب بنت جحش أم المؤمنين زوج النبي صلى الله عليه وآله وسلم. وكانت حمنة زوج مصعب بن عمير، فقتل عنها يوم أحد، فتزوجها طلحة بن عبيد الله، فولدت له محمدا وعمران ابني طلحة."],[38081,"وأمها أميمة بنت عبد المطلب، عمة رسول الله صلى الله عليه وآله وسلم وكانت ممن قال في الإفك على عائشة رضي الله عنها، فعلت ذلك حمية لأختها زينب، إلا أن زينب رضي الله عنها لم تقل فيها شيئا، فقال بعضهم: إنها جلدت مع من جلد فيه، وقيل: لم يجلد أحد، وكانت من المهاجرات وشهدت أحدا فكانت تسقي العطشى، وتحمل الجرحى وتداويهم."],[38082,"روت عن النبي صلى الله عليه وآله وسلم روى عنها ابنها عمران بن طلحة."],[38083,"أخبرنا غير واحد، بإسنادهم إلى أبي عيسى، قال: حدثنا محمد بن بشار، أخبرنا أبو عامر العقدي، أخبرنا زهير بن محمد، عن عبد الله بن محمد بن عقيل، عن إبراهيم بن محمد بن طلحة، عن عمه عمران بن طلحة، عن أمه حمنة بنت جحش، قالت: كنت أستحاض حيضة كثيرة شديدة، فأتيت النبي صلى الله عليه وآله وسلم أستفتيه وأخبره، فوجدته في بيت أختي زينب، فقلت: يا رسول الله، إني أستحاض حيضة كثيرة شديدة، فما تأمرني فيها: قد منعتني الصلاة والصيام."],[38084,"قال: «أنعت لك الكرسف، فإنه يذهب الدم»، قالت: هو أكثر من ذلك."],[38085,"قال: «فتلجمي»، قالت: هو أكثر من ذلك."],[38086,"قال «فاتخذي ثوبا»، قالت: هو أكثر من ذلك، إنما أثج ثجا، فقال النبي صلى الله عليه وآله وسلم: «سآمرك أمرين أيهما صنعت أجزأ عنك»."],[38087,"وذكر الحديث."],[38088,"أخرجها الثلاثة."],[38089,"قلت: قد جعل ابن منده حمنة هي حبيبة وجعل أبو نعيم أم حبيبة كنية حمنة وجعلها أبو عمر اثنتين، فطلب في الكنى، فأما أبو نعيم فلم يذكر في الكنى ما يدل على أنها هي ولا غيرها، وأما أبو عمر فإنه كشف الأمر وصرح بأنهما اثنتان، فقال: أم حبيبة."],[38090,"ويقال: أم حبيب ابنة جحش بن رياب الأسدي، أخت زينب بنت جحش، وأخت حمنة أكثرهم يسقطون الهاء فيقولون: أم حبيب، وكانت تحت عبد الرحمن بن عوف، وكانت تستحاض."],[38091,"وأهل السير يقولون: إن المستحاضة حمنة."],[38092,"والصحيح عند أهل الحديث أنهما كانتا تستحاضان جميعا."],[38093,"قال: وقد قيل: إن زينب بنت جحش استحيضت، ولا يصح."],[38094,"وقال ابن ماكولا وذكر ابني جحش: عبد الله وعبيد ثم قال وأخواتهما: زينب أم المؤمنين، كانت عند رسول الله صلى الله عليه وآله وسلم وأم حبيبة كانت عند عبد الرحمن بن عوف، وكانت مستحاضة، وحمنة بنت جحش كانت عند طلحة بن عبيد الله، وهي صاحبة الاستحاضة."],[38095,"فهو قد وافق أبا عمر، والله أعلم، ويرد ذكرها مستقصى في الكنى إن شاء الله تعالى فهذا القدر كاف في بيان أنهما اثنتان، والله أعلم."],[38096,"٦٨٥٨ - حمنة بنت أبي سفيان"],[38097,"س: حمنة بنت أبي سفيان بن حرب بن أمية"],[38098,"أخبرنا أبو موسى، إجازة، أخبرنا أبو غالب أحمد بن العباس الكوشيدي، أخبرنا أبو بكر بن ريذة، أخبرنا أبو القاسم الطبراني، حدثنا أبو مسلم الكشي، أخبرنا ابن عائشة، أخبرنا حماد بن سلمة، عن هشام بن عروة، عن أبيه، عن زينب بنت أبي سلمة، عن أم حبيبة، أنها قالت: يا رسول الله، هل لك في حمنة بنت أبي سفيان؟ قال: «أصنع ماذا؟» قالت: تنكحها، قال: «فهل تحل لي؟»."],[38099,"الحديث."],[38100,"ورواه غير واحد عن هشام، فلم يسموها وسماها بعضهم: عزة، وقيل: درة."],[38101,"أخرجها أبو موسى"],[38102,"٦٨٥٩ - حميمة بنت صيفي"],[38103,"د ع: حميمة بنت صيفي بن صخر من بني كعب بن سلمة من الأنصار، تزوجها البراء بن معرور."],[38104,"وأظنها ابنة عمه، لأن البراء بن معرور بن صخر من بني كعب بن سلمة من الأنصار، ثم تزوجها بعد البراء زيد بن حارثة، أسلمت وبايعت."],[38105,"قاله محمد بن سعد كاتب الواقدي."],[38106,"أخرجها ابن منده، وأبو نعيم."],[38107,"٦٨٦٠ - حمينة بنت أبي طلحة"],[38108,"س: حمينة بنت أبي طلحة بن عبد العزى بن عثمان بن عبد الدار روى ابن جريج، عن عكرمة، في قوله تعالى: ﴿إِلا مَا قَدْ سَلَفَ﴾ قال عكرمة مولى ابن عباس: فرق الإسلام بين أربع وبين أبناء بعولتهن: حمينة بنت أبي طلحة، كانت تحت خلف بن أسد بن عاصم بن بياضة الخزاعي، فخلف عليها الأسود بن خلف."],[38109,"أخرجها أبو موسى."],[38110,"٦٨٦١ - حواء أم بجيد الأنصارية"],[38111,"ب د ع: حواء أم بجيدة الأنصارية كانت من المبايعات من الأنصار، أسلمت قبل زوجها قيس بن الخطيم، وهي بنت يزيد بن السكن بن كرز بن زعوراء من بني عبد الأشهل، قاله أبو نعيم."],[38112,"قال: وقيل: هي حواء بنت رافع بن امرئ القيس من بني عبد الأشهل، قال هذا جميعه أبو نعيم، عن ابن إسحاق، عن عاصم بن عمر بن قتادة، فقد جعل أبو نعيم أم بجيد هي بنت يزيد بن السكن، وهي بنت رافع."],[38113,"وأما ابن منده، فإنه قال: حواء بنت زيد بن السكن الأشهلية امرأة قيس بن الخطيم، أسلمت وهاجرت، يقال لها: أم بجيد."],[38114,"وذكر ترجمة أخرى: حواء بنت رافع، فقد جعلهما اثنتين، وأما أبو عمر فقال:"],[38115,"حواء بنت زيد بن السكن، وترجمة ثانية: حواء بنت يزيد بن سنان بن كرز بن زعوراء امرأة قيس بن الخطيم، وترجمة ثالثة: حواء الأنصارية جدة ابن بجيد، فقد جعلهن ثلاثا على ما نذكره مفصلا في التراجم بعد هذه إن شاء الله تعالى."],[38116,"روى هشام بن سعد، عن زيد بن أسلم، عن ابن بجيد، عن جدته حواء، وكانت من المبايعات، قالت: سمعت رسول الله صلى الله عليه وآله وسلم يقول: «اسفروا بالصبح فإنه أعظم للأجر»."],[38117,"ذكر هذا الحديث أبو نعيم، وأبو عمر في هذه الترجمة، وذكراهما أيضا، وابن منده عن مالك، عن زيد ابن أسلم، عن عمرو بن معاذ، عن جدته حواء، عن النبي صلى الله عليه وآله وسلم قال: «لا تردوا السائل ولو بظلف محرق»."],[38118,"فاستدل أبو نعيم وابن منده بهذا على أنهما واحدة، وأما أبو عمر فإنه جعل هذا اختلافا في الإسناد، فإنه قال: قد ذكرت الاضطراب في هذا الإسناد في كتاب «التمهيد»، وقال أبو عمر: ومنهم من يجعل هذه التي قبلها، يعني: حواء بنت يزيد بن السكن."],[38119,"أخرجها الثلاثة، إلا أن ابن منده ترجم عليها فقال: حواء بنت السكن الأشهلية."],[38120,"٦٨٦٢ - حواء بنت رافع"],[38121,"د: حواء بنت رافع بن امرئ القيس من بني عبد الأشهل، بايعت النبي صلى الله عليه وآله وسلم قاله ابن سعد."],[38122,"أخرجه ابن منده مختصرًا."],[38123,"٦٨٦٣ - حواء بنت زيد بن السكن"],[38124,"ب د: حواء بنت زيد بن السكن الأنصارية من بني عبد الأشهل، مدنية جدة عمرو بن معاذ الأشهلي."],[38125,"أخبرنا أبو ياسر بن أبي حبة، بإسناده عن عبد الله بن أحمد، حدثني أبي، أخبرنا روح، أخبرنا مالك، عن زيد بن أسلم، عن ابن بجيد الأنصاري، عن جدته، عن النبي صلى الله عليه وآله وسلم أنها سمعته يقول: «ردوا السائل ولو بظلف محرق» وروى عنها عمرو بن معاذ المذكور."],[38126,"أخرج أحمد بن حنبل هذا المتن في ترجمة حواء جدة عمرو بن معاذ، فعلى هذا تكون حواء جدة ابن بجيد أيضا."],[38127,"وأخرج أبو نعيم، وأبو عمرو هذا المتن في ترجمة حواء أم بجيد قبل هذه الترجمة، وأخرجه أبو عمر في هذه الترجمة أيضا، فيكون أبو عمر قد أخرجه في ترجمتين."],[38128,"وهذا يدل على أنهما واحدة، وقد جعلهما اثنتين."],[38129,"أخرج هذه أبو عمر وابن منده."],[38130,"٦٨٦٤ - حواء بنت يزيد بن سنان"],[38131,"ب: حواء بنت يزيد بن سنان بن كرز بن زعوراء الأنصارية قال مصعب: أسلمت، وكانت تكتم إسلامها من زوجها قيس بن الخطيم الشاعر، فلما قدم قيس مكة حين خرجوا يطلبون الحلف من قريش، عرض عليه رسول الله صلى الله عليه وآله وسلم الإسلام، فاستنظره قيس حتى يقدم المدينة فسأله رسول الله صلى الله عليه وآله وسلم أن يجتنب زوجته حواء بنت يزيد، وأوصاه بها خيرا، وقال له: «إنها قد أسلمت»."],[38132,"ففعل قيس، وحفظ وصية رسول الله صلى الله عليه وآله وسلم فبلغ ذلك رسول الله صلى الله عليه وآله وسلم وقال: «وفى الأديعج»."],[38133,"وقد أنكر بعض العلماء هذا على مصعب، وقال منكره: إن زوجها قيس بن شماس."],[38134,"وأما قيس بن الخطيم فقتل قبل الهجرة."],[38135,"قال أبو عمر: والقول قول مصعب، وقيس بن شماس أسن من قيس بن الخطيم، ولم يدرك الإسلام، وإنما أدركه ابنه، ثابت بن قيس بن شماس."],[38136,"أخرجه أبو عمر."],[38137,"قلت: قد وافق مصعب بن إسحاق، فجعلها امرأة قيس بن الخطيم."],[38138,"أخبرنا أبو جعفر، بإسناده عن يونس، عن ابن إسحاق، قال: حدثني عاصم بن عمر بن قتادة، قال: «كانت حواء بنت يزيد بن السكن عند قيس ابن الخطيم بالمدينة، وكانت أمها عقرب بنت معاذ، أخت سعد بن معاذ، فأسلمت حواء فحسن إسلامها، وكان زوجها قيس على كفره، وكان يدخل عليها فيراها تصلي، فيأخذ ثيابها فيضعها على رأسها ويقول: إنك لتدينين دينا لا ندري ما هو."],[38139,"وذكر وصية النبي صلى الله عليه وآله وسلم بأن يكف الأذى عنها، فكف الأذى عنها» وأظن أن قول مصعب وابن إسحاق صحيح، لأنه عالم، ومن أهل المدينة، ويروي عن عاصم، وهو أيضا من أعلم الناس بأخبار الأنصار، وأهل مكة أخبر بشعابها، والله أعلم."],[38140,"جعل أبو عمر هذه زوج قيس بن الخطيم، وجعلها ابن منده، وأبو نعيم الأولى، كما ذكرنا في ترجمتها فليتأمل."],[38141,"وذكرها العدوي فقال: حواء بنت يزيد بن السكن بن كرز بن زعوراء بن عبد الأشهل، وهي أم ثابت بن قيس بن الخطيم، وذكر نحو ما ذكرناه من وصية من النبي صلى الله عليه وآله وسلم فقد وافق أبا عمر في أنها زوج قيس بن الخطيم."],[38142,"وقال محمد بن سلام الجمحي: أسلمت امرأة قيس بن الخطيم، وكان يقال لها: حواء، وكان يصدها عن الإسلام، فأخبر رسول الله صلى الله عليه وآله وسلم بإسلامها فلما كان الموسم أتاه النبي صلى الله عليه وآله وسلم فأخبره بإسلامها، وقال: «أحب أن لا تعرض إليها» ففعل."],[38143,"فقد جعل أبو عمر حواء ثلاثا: حواء الأنصارية أم بجيد، وحواء بنت زيد بن السكن، وحواء بنت يزيد بن سنان، وجعلهن ابن منده اثنتين: حواء بنت زيد بن السكن أم بجيد، وحواء بنت رافع وجعلهن أبو نعيم واحدة: حواء بنت زيد بن السكن، وهي أم بجيد، وهي بنت رافع."],[38144,"وقد أخرجنا تراجم الجميع، والله أعلم."],[38145,"٦٨٦٥ - الحولاء بنت تويت"],[38146,"ب د ع: الحولاء بنت تويت بن حبيب بن أسد بن عبد العزى بن قصي القرشية الأسدية هاجرت إلى المدينة، وكانت كثيرة العبادة."],[38147,"أخبرنا عبد الله بن أحمد بن محمد بن عبد القاهر، أخبرنا جعفر بن أحمد، أخبرنا الحسن بن شاذان، أخبرنا عثمان بن أحمد، حدثنا الحسن بن مكرم، حدثنا عثمان بن عمر، حدثنا يونس، عن الزهري، عن عروة، عن عائشة، أن الحولاء بنت تويت مرت بها وعندها رسول الله صلى الله عليه وآله وسلم فقلت: هذه الحولاء يزعمون أنها لا تنام الليل، فقال النبي صلى الله عليه وآله وسلم: «خذوا من العمل ما تطيقون، فوالله لا يسأم الله حتى تسأموا» وروى أبو عاصم النبيل، عن صالح بن رستم، عن ابن أبي مليكة، عن عائشة، قالت: استأذنت الحولاء على رسول الله صلى الله عليه وآله وسلم فأذن لها وأقبل عليها، وقال: «كيف أنت؟»"],[38148,"فقلت: أتقبل على هذه هذا الإقبال؟! فقال: «إنها كانت تأتينا زمن خديجة، وإن حسن العهد من الإيمان»."],[38149,"قال أبو عمر: هكذا رواه محمد بن موسى الشامي، عن أبي عاصم فقال: الحولاء ولم ينسبها، ولا قال: بنت تويت، وقد غلط، فإن الصواب أنها: حسانة المزنية، وقد تقدم ذكرها."],[38150,"أخرجها الثلاثة."],[38151,"٦٨٦٦ - الحولاء امرأة عثمان بن مظعون"],[38152,"د: الحولاء امرأة عثمان بن مظعون لها ذكر، لا تعرف لها رواية."],[38153,"أخرجها ابن منده مختصرا."],[38154,"٦٨٦٧ - الحولاء العطارة"],[38155,"س: الحولاء العطارة"],[38156,"أخبرنا أبو موسى، إجازة، أخبرنا أبو علي محمد بن علي الكاتب والحسن بن أحمد، قالا: أخبرنا أبو منصور عبد الرزاق بن أحمد، أخبرنا أبو الشيخ عبد الله بن محمد، حدثنا محمد، حدثنا إسحاق بن جميل، حدثنا إسحاق بن الفيض، حدثنا القاسم بن الحكم، حدثنا جرير بن أيوب البجلي، حدثنا حماد بن أبي سليمان، عن زياد الثقفي، عن أنس بن مالك، قال: كانت امرأة بالمدينة عطارة تسمى الحولاء، فجاءت حتى دخلت على عائشة، فقالت: يا أم المؤمنين، إني لأتطيب كل ليلة، وأتزين، حتى كأني عروس أزف، فأجيء حتى أدخل في لحاف زوجي أبتغي بذلك مرضاة ربي، فيحول وجهه عني، فأستقبله فيعرض عني ولا أراه إلا قد أبغضني، فقالت لها عائشة رضي الله عنها: لا تبرحي حتى يجيء رسول الله صلى الله عليه وآله وسلم. فلما جاء رسول الله صلى الله عليه وآله وسلم قال: «إني لأجد ريح الحولاء، فهل أتتكم؟ هل ابتعتم منها شيئا؟» قالت عائشة: لا، والله يا رسول الله، ولكن جاءت تشكو زوجها، فقال لها رسول الله صلى الله عليه وآله وسلم: «مالك يا حولاء؟» فقالت: يا رسول الله، إني لأتزين وأفعل كذا وكذا، نحو ما ذكرت لعائشة، فقال لها رسول الله صلى الله عليه وآله وسلم: «اذهبي أيتها المرأة فاسمعي وأطيعي زوجك»."],[38157,"قالت: يا رسول الله، فما لي من الأجر؟ الحديث."],[38158,"فذكر من حق الزوج على المرأة، وحق المرأة على الزوج، وما في الحمل والولادة والفطام من الأجر."],[38159,"أخرجه أبو موسى"],[38160,"٦٨٦٨ - الحويصلة بنت قطبة"],[38161,"الحويصلة بنت قطبة ذكرها أبو عمر في ترجمة قطبة أبيها أنه قال للنبي صلى الله عليه وآله وسلم: أبايعك على نفسي وعلى الحويصلة."],[38162,"٦٨٦٩ - حية بنت أبي حية"],[38163,"د ع: حية بنت أبي حية روى حديثها عبد الله بن عون، عن عمرو بن سعيد، عن أبي زرعة بن عمرو بن جرير، عن حية بنت أبي حية، قالت: «دخل علي رجل، فقلت: من أنت؟ قال: أبو بكر الصديق، قلت: صاحب رسول الله صلى الله عليه وآله وسلم قال: نعم»."],[38164,"أخرجه ابن منده، وأبو نعيم."],[38165,"قال الأمير أبو نصر: أما حية أوله حاء مهملة، بعدها ياء مشددة معجمة باثنتين من تحتها، فهي حية بنت أبي حية، روت عن أبي بكر الصديق، روى عنها أبو زرعة بن عمرو بن جرير."],[38166,"حرف الخاء"],[38167,"٦٨٧٠ - خالدة بنت الأسود"],[38168,"س: خالدة بنت الأسود بن عبد يغوث بن وهب بن عبد مناف بن زهرة القرشية الزهرية"],[38169,"أخبرنا عمر بن محمد بن المعمر، أخبرنا أبو القاسم الجريري، أخبرنا أبو إسحاق البرمكي، أخبرنا أبو بكر محمد بن عبد الله بن خلف بن بخيت، حدثنا إسماعيل بن موسى الحاسب، حدثنا جبارة بن مغلس، عن ابن المبارك، عن معمر، عن الزهري، عن عبيد الله بن عبد الله بن عتبة، عن عائشة، أن رسول الله صلى الله عليه وآله وسلم دخل عليها فرأى عندها امرأة فقال: «من هذه؟» قالت: بنت الأسود بن عبد يغوث: فقال النبي صلى الله عليه وآله وسلم: ﴿يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ﴾."],[38170,"وقد روي من طريق آخر، وفيه: فقال: «من هذه؟» فقالت: إحدى خالاتك خالدة بنت الأسود."],[38171,"وقال ابن حبيب: وممن هاجر: خالدة بنت الأسود، وكانت امرأة صالحة."],[38172,"أخرجها أبو موسى"],[38173,"٦٨٧١ - خالدة بنت أنس"],[38174,"ب د ع: خالدة بنت أنس الأنصارية الساعدية أم بني حزم روى محمد بن عمارة، عن أبي بكر بن محمد، أن خالدة بنت أنس جاءت إلى النبي صلى الله عليه وآله وسلم فعرضت عليه الرقى، فأمر بها."],[38175,"أخرجها الثلاثة."],[38176,"٦٨٧٢ - خالدة بنت الحارث، أو خلدة"],[38177,"س: خالدة أو خلدة بنت الحارث عمة عبد الله بن سلام."],[38178,"ذكر محمد بن إسحاق في قصة عبد الله بن سلام أنها أسلمت وحسن إسلامها، أوردها الحافظ إسماعيل بن محمد بن الفضل في تفسير قوله تعالى: ﴿وَلَئِنْ أَتَيْتَ الَّذِينَ أُوتُوا الْكِتَابَ بِكُلِّ آيَةٍ﴾."],[38179,"الآية."],[38180,"أخرجها أبو موسى."],[38181,"٦٨٧٣ - خدامة بنت جندل"],[38182,"د ع: خدامة بنت جندل الأسدية وقيل جدامة هاجرت إلى النبي صلى الله عليه وآله وسلم لا يعرف لها رواية."],[38183,"قاله عروة بن الزبير، وابن إسحاق."],[38184,"أخرجها ابن منده، وأبو نعيم."],[38185,"٦٨٧٤ - خديجة بنت خويلد"],[38186,"ب د ع: خديجة بنت خويلد بن أسد بن عبد العزى بن قصي القرشية الأسدية أم المؤمنين زوج النبي صلى الله عليه وآله وسلم أول امرأة تزوجها، وأول خلق الله أسلم بإجماع المسلمين، لم يتقدمها رجل ولا امرأة."],[38187,"قال الزبير: كانت تدعى في الجاهلية الطاهرة."],[38188,"وأمها فاطمة بنت زائدة بن الأصم، واسمه جندب بن هدم بن رواحة بن حجر بن عبد بن معيص بن عامر بن لؤي."],[38189,"وكانت خديجة قبل رسول الله صلى الله عليه وآله وسلم تحت أبي هالة بن زرارة بن نباش بن عدي بن حبيب بن صرد بن سلامة بن جروة بن أسيد بن عمرو بن تميم التميمي."],[38190,"كذا نسبه الزبير."],[38191,"وقال علي بن عبد العزيز الجرجاني: كانت خديجة عند أبي هالة هند بن النباش بن زرارة بن وقدان بن حبيب بن سلامة بن جروة بن أسيد بن عمرو بن تميم."],[38192,"ثم اتفقا فقالا: ثم خلف عليها بعد أبي هالة عتيق بن عابد بن عبد الله بن عمر بن مخزوم المخزومي، ثم خلف عليها بعد عتيق رسول الله صلى الله عليه وآله وسلم."],[38193,"وقال قتادة: كانت خديجة تحت عتيق بن عابد بن عبد الله بن عمر بن مخزوم، ثم خلف عليها بعده أبو هالة هند بن زرارة بن النباش."],[38194,"قال قتادة: والقول الأول أصح إن شاء الله تعالى، قاله أبو عمر."],[38195,"وروى يونس بن بكير، عن ابن إسحاق، قال: وتزوج خديجة قبل رسول الله صلى الله عليه وآله وسلم وهي بكر: عتيق بن عابد بن عبد الله بن عمر بن مخزوم، ثم هلك عنها فتزوجها بعده أبو هالة النباش بن زرارة."],[38196,"قال: وكانت خديجة قبل أن ينكحها رسول الله صلى الله عليه وآله وسلم تحت عتيق بن عابد بن عبد الله، فولدت له هند بنت عتيق، ثم خلف عليها بعد عتيق أبو هالة مالك بن النباش بن زرارة التميمي الأسدي، حليف بني عبد الدار بن قصي، فولدت له هند بنت أبي هالة، وهالة بن أبي هالة، فهند بنت عتيق، وهند وهالة ابنا أبي هالة كلهم إخوة أولاد رسول الله صلى الله عليه وآله وسلم من خديجة."],[38197,"كل ذلك ذكره الزبير، وهذا عكس ما نقله أبو عمر عن الزبير، فإن أبا عمر نقل عن الزبير أنها كانت عند أبي هالة أولا ثم بعده عند عتيق."],[38198,"ونقل أبو نعيم عن الزبير فقدم عتيقا على أبي هالة، وأما الذي رويناه في «نسب قريش للزبير» قال: وكانت يعني: خديجة قبل النبي صلى الله عليه وآله وسلم عند عتيق بن عابد بن عبد الله بن عمر بن مخزوم فولدت له جارية، وهلك عنها عتيق، فتزوجها أبو هالة بن مالك، أحد بني عمرو بن تميم، ثم أحد بني أسيد."],[38199,"قال الزبير: وبعض الناس يقول: أبو هالة قبل عتيق."],[38200,"وتزوج رسول الله صلى الله عليه وآله وسلم خديجة رضي الله عنها قبل الوحي وعمره حينئذ خمس وعشرون سنة وقيل: إحدى وعشرون سنة، زوجها منه عمها عمرو بن أسد."],[38201,"ولما خطبها رسول الله صلى الله عليه وآله وسلم قال عمها: محمد بن عبد الله بن عبد المطلب يخطب خديجة بنت خويلد، هذا الفحل لا يقدع أنفه."],[38202,"وكان عمرها حينئذ أربعين سنة وأقامت معه أربعا وعشرين سنة."],[38203,"وكان سبب تزوجها برسول الله صلى الله عليه وآله وسلم ما أخبرنا أبو جعفر، بإسناده عن يونس، عن ابن إسحاق، قال: كانت خديجة امرأة تاجرة ذات شرف ومال، تستأجر الرجال في مالها تضاربهم إياه بشيء تجعله لهم منه."],[38204,"فلما بلغها عن رسول الله صلى الله عليه وآله وسلم ما بلغها من صدق حديثه وعظم أمانته وكرم أخلاقه بعثت إليه وعرضت عليه أن يخرج في مالها إلى الشام تاجرا، وتعطيه أفضل ما كانت تعطي غيره من التجار، مع غلام لها يقال له: ميسرة، فقبله منها وخرج في مالها ومعه غلامها ميسرة، حتى قدم الشام فنزل رسول الله صلى الله عليه وآله وسلم في ظل شجرة قريبا من صومعة راهب، فاطلع الراهب إلى ميسرة فقال: من هذا الرجل الذي نزل تحت هذه الشجرة؟ قال: هذا رجل من قريش من أهل الحرم، فقال له الراهب: ما نزل تحت هذه الشجرة قط إلا نبي."],[38205,"ثم باع رسول الله صلى الله عليه وآله وسلم سلعته التي خرج بها، واشترى ما أراد، ثم أقبل قافلا إلى مكة، فلما قدم على خديجة بمالها باعت ما جاء به، فأضعف أو قريبا، وحدثها ميسرة عن قول الراهب."],[38206,"وكانت خديجة امرأة حازمة لبيبة شريفة مع ما أراد الله بها من كرامتها."],[38207,"فلما أخبرها ميسرة بعثت إلى رسول الله صلى الله عليه وآله وسلم فقالت له: إني قد رغبت فيك لقرابتك مني، وشرفك في قومك، وأمانتك عندهم، وحسن خلقك، وصدق حديثك، ثم عرضت عليه نفسها، وكانت أوسط نساء قريش نسبا، وأعظمهم شرفا، وأكثرهم مالا."],[38208,"فلما قالت لرسول الله صلى الله عليه وآله وسلم ما، قالت، ذكر ذلك لأعمامه، فخرج معه حمزة بن عبد المطلب حتى دخل على خويلد بن أسد، فخطبها إليه فتزوجها رسول الله صلى الله عليه وآله وسلم فولدت لرسول الله صلى الله عليه وآله وسلم ولده كلهم قبل أن ينزل عليه الوحي: زينب، وأم كلثوم، وفاطمة، ورقية، والقاسم، والطاهر والطيب."],[38209,"فأما القاسم والطيب والطاهر فهلكوا قبل الإسلام، وبالقاسم كان يكنى رسول الله صلى الله عليه وآله وسلم وأما بناته فأدركن الإسلام، فهاجرن معه واتبعنه وآمن به، وقيل: إن الطاهر والطيب ولدا في الإسلام."],[38210,"وقد تقدم أن عمها عمرا زوجها، وأن أباها كان قد مات، قاله الزبير، وغيره."],[38211,"واختلف العلماء في أولاد رسول الله صلى الله عليه وآله وسلم منها، فروى معمر عن الزهري، قال: زعم بعض العلماء أنها ولدت له ولدا يسمى الطاهر، وقال: قال بعضهم: ما نعلمها ولدت له إلا القاسم وبناته الأربع."],[38212,"وقال عقيل، عن ابن شهاب، وذكر بناته، وقال: والقاسم والطاهر."],[38213,"وقال قتادة: ولدت له خديجة غلامين، وأربع بنات: القاسم، وبه كان يكنى، وعاش حتى مشى، وعبد الله مات صغيرا."],[38214,"وقال الزبير: ولدت لرسول الله صلى الله عليه وآله وسلم القاسم وهو أكبر ولده ثم زينب ثم عبد الله وكان يقال له: الطيب، ويقال له: الطاهر، ثم مات القاسم بمكة، وهو أول ميت مات من ولده، ثم عبد الله مات أيضا بمكة."],[38215,"وقال الزبير أيضا: حدثني إبراهيم بن المنذر، عن ابن وهب، عن ابن لهيعة، عن أبي الأسود محمد بن عبد الرحمن، «أن خديجة بنت خويلد ولدت لرسول الله صلى الله عليه وآله وسلم: القاسم، والطاهر، والطيب، وعبد الله، وزينب ورقية، وأم كلثوم، وفاطمة»."],[38216,"وقال علي بن عبد العزيز الجرجاني: أولاد رسول الله صلى الله عليه وآله وسلم: القاسم وهو أكبر ولده ثم زينب، قال: وقال الكلبي: زينب والقاسم، ثم أم كلثوم، ثم فاطمة، ثم رقية، ثم عبد الله وكان يقال له: الطيب والطاهر."],[38217,"قال: وهذا هو الصحيح، وغيره تخليط."],[38218,"وقال الكلبي: ولد عبد الله في الإسلام وكل ولده منها ولد قبل الإسلام."],[38219,"وأما إسلامها:"],[38220,"فأخبرنا محمد بن محمد سرايا بن علي وغير واحد، بإسنادهم إلى محمد بن إسماعيل، حدثنا يحيى بن بكير، حدثنا الليث، عن عقيل، عن ابن شهاب، عن عروة، عن عائشة أم المؤمنين، قالت: أول ما بدئ به رسول الله صلى الله عليه وآله وسلم من الوحي الرؤيا الصالحة في النوم، كان لا يرى رؤيا إلا جاءت مثل فلق الصبح."],[38221,"وذكر الحديث، قال يعني جبريل عليه السلام: ﴿اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ﴾ فرجع بها رسول الله صلى الله عليه وآله وسلم يرجف فؤاده، فدخل على خديجة رضي الله عنها فقال: «زملوني»، فزملوه حتى ذهب عنه الروع، وقال لخديجة وأخبرها الخبر: «لقد خشيت على نفسي»، فقالت خديجة: كلا، والله لا يخزيك الله أبدا، إنك لتصل الرحم، وتحمل الكل، وتكسب المعدوم، وتقري الضيف، وتعين على نوائب الحق."],[38222,"وانطلقت به خديجة إلى ورقة بن نوفل، وكان امرءا تنصر في الجاهلية، ويكتب الكتاب العبراني، ويكتب من الإنجيل ما شاء الله أن يكتب، فقالت له خديجة: يا ابن عم، اسمع من ابن أخيك، فقال له ورقة: ماذا ترى؟ فأخبره رسول الله صلى الله عليه وآله وسلم فقال: يا ليتني فيها جذعا، ليتني أكون حيا إذ يخرجك قومك"],[38223,"أخبرنا أبو جعفر، بإسناده إلى يونس، عن ابن إسحاق، قال: «وكانت خديجة أول من آمن بالله ورسوله، وصدق بما جاء به، فخفف الله بذلك عن رسول الله صلى الله عليه وآله وسلم لا يسمع شيئا يكرهه من رد عليه وتكذيب له فيحزنه إلا فرج الله عنه بها إذا رجع إليها تثبته وتخفف عنه، وتصدقه وتهون عليه أمر الناس، رضي الله عنها»"],[38224,"قال ابن إسحاق: حدثني إسماعيل بن أبي حكيم مولى الزبير، أنه حدث، عن خديجة، أنها قالت لرسول الله صلى الله عليه وآله وسلم: يا ابن عم، «هل تستطيع أن تخبرني بصاحبك الذي يأتيك إذا جاءك؟ قال: نعم»."],[38225,"فبينا رسول الله صلى الله عليه وآله وسلم عندها إذ جاءه جبريل عليه السلام، فقال رسول الله صلى الله عليه وآله وسلم: «هذا جبريل قد جاءني»، فقالت: «أتراه الآن؟ قال: نعم»، قالت: اجلس على شقي الأيسر، فجلس، فقالت: «هل تراه الآن: قال: نعم»، قالت: فاجلس على شقي الأيمن، فجلس، فقالت: «هل تراه الآن؟ قال: نعم»، قالت: فتحول فاجلس في حجري، فتحول رسول الله صلى الله عليه وآله وسلم فجلس، فقالت: «هل تراه؟ قال: نعم»."],[38226,"قال: «فتحسرت وألقت خمارها، فقالت: هل تراه؟ قال: لا»، قالت: ما هذا شيطان، إن هذا لملك يا ابن عم، اثبت وأبشر ثم آمنت به وشهدت أن الذي جاء به الحق"],[38227,"أخبرنا أبو محمد بن عبد الله بن علي، أخبرنا أبو الفضل بن ناصر، أخبرنا أبو صالح أحمد بن عبد الملك المؤذن، أخبرنا الحسين بن فاذشاه، أخبرنا أبو القاسم الطبراني، حدثنا القاسم بن زكريا المطرز، حدثنا يوسف بن موسى القطان، حدثنا تميم بن الجعد، حدثنا أبو جعفر الرازي، عن ثابت، عن أنس، قال: قال رسول الله صلى الله عليه وآله وسلم: «خير نساء العالمين مريم بنت عمران، وآسية بنت مزاحم، وخديجة بنت خويلد، وفاطمة بنت محمد صلى الله عليه وآله وسلم»"],[38228,"قال: وأخبرنا أبو صالح، أخبرنا أبو علي الحسن بن علي الواعظ، أخبرنا أحمد بن جعفر، أخبرنا عبد الله بن أحمد بن حنبل، حدثني أبي، حدثنا أبو عبد الرحمن، حدثنا داود، عن علباء، عن عكرمة، عن ابن عباس، قال: خط رسول الله صلى الله عليه وآله وسلم في الأرض أربع خطوط، قال: «أتدرون ما هذا؟» قالوا: الله ورسوله أعلم، فقال رسول الله صلى الله عليه وآله وسلم: «أفضل نساء أهل الجنة خديجة بنت خويلد، وفاطمة بنت محمد، ومريم بنت عمران وآسية بنت مزاحم امرأة فرعون»."],[38229,"قال في اصل الشيخ: داود مصلح، ورواه عارم: داود بن أبي الفرات، عن علباء بن أحمر"],[38230,"أخبرنا إبراهيم وإسماعيل، وغيرهما، بإسنادهم عن محمد بن عيسى: أخبرنا الحسين بن حريث، حدثنا الفضل بن موسى، عن هشام بن عروة، عن أبيه، عن عائشة، «أن رسول الله صلى الله عليه وآله وسلم بشر خديجة ببيت في الجنة من قصب، لا صخب فيه ولا نصب»"],[38231,"أخبرنا يحيى بن محمود وعبد الوهاب بن أبي حبة، بإسنادهما إلى مسلم، حدثنا أبو كريب، أخبرنا أبو أسامة، عن هشام، عن أبيه، عن عبد الله بن جعفر، قال: سمعت علي بن أبي طالب رضي الله عنه يقول: سمعت رسول الله صلى الله عليه وآله وسلم يقول: «خير نسائها خديجة بنت خويلد، وخير نسائها مريم بنت عمران»، قال أبو كريب: وأشار وكيع إلى السماء والأرض"],[38232,"أخبرنا أبو الفضل عبد الله بن أحمد بن محمد الطوسي، أخبرنا جعفر بن أحمد السراج، حدثنا أبو علي بن شاذان، حدثنا أبو عمرو عثمان بن أحمد الدقاق، حدثنا ابن أبي العوام، حدثنا الوليد بن القاسم، حدثنا إسماعيل بن أبي خالد، عن ابن أبي أوفى، «أن رسول الله صلى الله عليه وآله وسلم بشر خديجة ببيت في الجنة من قصب، لا نصب فيه ولا صخب»"],[38233,"أخبرنا عبد الله بن أحمد، أخبرنا أبو بكر بن بدران الحلواني، قال: قرئ على أبي الحسين محمد بن أحمد بن محمد الأبنوسي، وأنا أسمع، أخبركم أبو الحسين محمد بن عبد الرحمن بن جعفر الدينوري، فأقر به، أخبرنا أبو بكر محمد بن عبد الله بن غيلان الخزاز، حدثنا أبو هشام الرفاعي، حدثنا حفص بن غياث، عن هشام بن عروة، عن أبيه، عن عائشة، قالت: «ما غرت على أحد من أزواج النبي صلى الله عليه وآله وسلم ما غرت على خديجة، وما بي أن أكون أدركتها، وما ذاك إلا لكثرة ذكر رسول الله صلى الله عليه وآله وسلم لها، وإن كان مما تذبح الشاة يتبع بها صدائق خديجة، فيهديها لهن»"],[38234,"أخبرنا يحيى بن محمود وأبو ياسر، بإسنادهما عن مسلم، قال: حدثنا أبو بكر بن أبي شيبة وأبو كريب وابن نمير، قالوا: حدثنا ابن"],[38235,"فضيل، عن عمارة، عن أبي زرعة، قال: سمعت أبا هريرة، رضي الله عنه، قال: «أتى جبريل عليه السلام النبي صلى الله عليه وآله وسلم فقال: يا رسول الله، هذه خديجة قد أتتك ومعها إناء فيه إدام أو طعام أو شراب فإذا هي أتتك فاقرأ عليها السلام من ربها، ومني، وبشرها ببيت في الجنة من قصب، لا صخب فيه ولا نصب»."],[38236,"قال أبو بكر في روايته: عن أبي هريرة رضي الله عنه ولم يقل: سمعت، ولم يقل في الحديث: «ومني»"],[38237,"وروى مجالد، عن الشعبي، عن مسروق، عن عائشة، قالت: كان رسول الله صلى الله عليه وآله وسلم لا يكاد يخرج من البيت حتى يذكر خديجة، فيحسن الثناء عليها."],[38238,"فذكرها يوما من الأيام فأدركتني الغيرة، فقلت: «هل كانت إلا عجوزا، فقد أبدلك الله خيرا منها فغضب حتى أهتز مقدم شعره من الغضب، ثم قال: لا، والله ما أبدلني الله خيرا منها، آمنت إذ كفر الناس، وصدقتني وكذبني الناس، وواستني في مالها إذ حرمني الناس، ورزقني الله منها أولادا إذ حرمني أولاد النساء»."],[38239,"قالت عائشة: فقلت في نفسي: لا أذكرها بسيئة أبدا."],[38240,"وروى الزبير بن بكار، عن محمد بن الحسن، عن يعلى بن المغيرة، عن ابن أبي رواد، قال: دخل رسول الله صلى الله عليه وآله وسلم على خديجة في مرضها الذي ماتت فيه، فقال لها: «بالكره مني ما أثني عليك يا خديجة، وقد يجعل الله في الكره خيرا كثيرا، أما علمت أن الله تعالى زوجني معك في الجنة مريم بنت عمران، وكلثم أخت موسى، وآسية امرأة فرعون؟»، فقالت: وقد فعل ذلك يا رسول الله؟ قال: «نعم»."],[38241,"قالت: بالرفاء والبنين."],[38242,"أخبرنا عبيد الله بن أحمد، بإسناده عن يونس، عن ابن إسحاق، قال: «ثم إن خديجة توفيت بعد أبي طالب، وكانا ماتا في عام واحد، فتتابعت على رسول الله صلى الله عليه وآله وسلم المصائب بهلاك خديجة وأبي طالب، وكانت خديجة وزيرة صدق على الإسلام كان يسكن إليها» وقال أبو عبيدة معمر بن المثني: توفيت خديجة قبل الهجرة بخمس سنين، وقيل: بأربع سنين."],[38243,"وقال عروة وقتادة: توفيت قبل الهجرة بثلاث سنين."],[38244,"وهذا هو الصواب."],[38245,"وقالت عائشة: توفيت خديجة قبل أن تفرض الصلاة."],[38246,"قيل: إن وفاة خديجة كانت بعد أبي طالب بثلاثة أيام، وكان موتها في رمضان، ودفنت بالحجون."],[38247,"قيل: كان عمرها خمسا وستين سنة."],[38248,"أخرجها الثلاثة."],[38249,"٦٨٧٥ - خرقاء"],[38250,"ب د ع: خرقاء امرأة سوداء كانت تقم المسجد، مسجد رسول الله صلى الله عليه وآله وسلم. لها ذكر في حديث حماد بن زيد، عن ثابت، عن أنس."],[38251,"قاله ابن منده، وأبو نعيم."],[38252,"وقال أبو عمر: الخرقاء روى عنها أبو السفر سعيد بن محمد، ذكرها ابن السكن في الصحابيات، وليس في حديثها ما يدل على صحبتها ولا على رؤيتها."],[38253,"٦٨٧٦ - خزيمة بنت جهم"],[38254,"ب: خزيمة بنت جهم بن قيس العبدرية من بني عبد الدار بن قصي."],[38255,"هاجرت مع أبيها وأمها خولة بنت الأسود أم حرملة إلى أرض الحبشة."],[38256,"أخرجها أبو عمر."],[38257,"٦٨٧٧ - خضرة"],[38258,"د ع: خضرة خادم النبي صلى الله عليه وآله وسلم."],[38259,"روى أبو كريب، عن معاوية بن هشام، عن سفيان، عن جعفر بن محمد، عن أبيه، قال: «كان للنبي صلى الله عليه وآله وسلم خادمة يقال لها: خضرة»."],[38260,"أخرجها ابن منده، وأبو نعيم."],[38261,"٦٨٧٨ - خليدة بنت الحباب"],[38262,"خليدة بنت الحباب بن سعد بن معاذ الأنصارية، ثم من بني ظفر."],[38263,"بايعت النبي صلى الله عليه وآله وسلم. قاله ابن حبيب."],[38264,"٦٨٧٩ - خليدة بنت قعنب"],[38265,"د ع: خليدة بنت قعنب الضبية كانت من المهاجرات، بايعت النبي صلى الله عليه وآله وسلم"],[38266,"أخبرنا يحيى بن محمود، كتابة، بإسناده إلى ابن أبي عاصم، قال: حدثنا محمد بن معمر، عن حميد بن حماد بن أبي الخوار، عن ثعلبة بنت الخوار، عن خالتها خليدة بنت قعنب، «أنها كانت في النسوة اللاتي أتين رسول الله صلى الله عليه وآله وسلم يبايعنه، فأتته امرأة في يدها سوار من ذهب، فأبي أن يبايعها، فخرجت من الزحام فرمت بالسوار، ثم جاءت إلى النبي صلى الله عليه وآله وسلم فبايعها، قالت: فخرجت فطلبت السوار، فإذا هو قد ذهب به»."],[38267,"أخرجها ابن منده، وأبو نعيم"],[38268,"٦٨٨٠ - خليسة جارية حفصة"],[38269,"د ع: خليسة جارية حفصة زوج النبي صلى الله عليه وآله وسلم روى حديثها علية بنت الكميت، عن جدتها، عن خليسة جارية حفصة، أن عائشة وحفصة رضي الله عنهما كانتا جالستين تتحدثان، فأقبلت سودة زوج النبي صلى الله عليه وآله وسلم فقالت إحداهما للأخرى: أما ترى سودة؟ ما أحسن حالها! لنفسدن عليها وكانت من أحسنهن حالا، كانت تعمل الأديم الطائفي فلما دنت منهما، قالتا لها: يا سودة، أما شعرت؟ قالت: وما ذلك؟ قالتا: خرج الأعور الدجال."],[38270,"ففزعت وخرجت حتى دخلت خيمة لهم يوقدون فيها، وكأن في مآقيها زعفران."],[38271,"فأقبل النبي صلى الله عليه وآله وسلم فلما رأتاه استضحكتا وجعلتا لا تستطيعان أن تكلماه، حتى أومأت إليه فذهب حتى قام على باب الخيمة، فقالت: يا نبي الله، «خرج الدجال الأعور؟ فقال: لا»."],[38272,"وكان قد خرج فخرجت، وجعلت تنفض عنها نسج العنكبوت."],[38273,"أخرجها ابن منده، وأبو نعيم."],[38274,"٦٨٨١ - خليسة مولاة سلمان الفارسي"],[38275,"س: خليسة مولاة سلمان الفارسي."],[38276,"لها ذكر في قصة إسلام سلمان، رواه أبو سلمة بن عبد الرحمن، عن سلمان الفارسي، وذكر قصة إسلامه، قال: فمر بي أعراب من كلب فاحتملوني، حتى أتوا بي يثرب، فاشترتني امرأة يقال لها خليسة بنت فلان حليف بني النجار بثلثمائة درهم، قال: فمكثت معها ستة عشر شهرا حتى قدم محمد صلى الله عليه وآله وسلم المدينة، قال: فأتيته وذكر إسلامه، قال: فأرسل إليها النبي صلى الله عليه وآله وسلم علي بن أبي طالب يقول لها: إما أن تعتقي سلمان وإما أن أعتقه."],[38277,"وكانت قد أسلمت، فقالت: قل للنبي صلى الله عليه وآله وسلم إن شئت أعتقته، وإن شئت فهو لك."],[38278,"قال رسول الله صلى الله عليه وآله وسلم: «أعتقيه أنت»."],[38279,"فأعتقته، قال: فغرس لها رسول الله صلى الله عليه وآله وسلم ثلاثمائة فسيلة."],[38280,"أخرجه أبو موسى أتم من هذا في الطولات، وهذا غريب، فإن المشهور في مكاتبته تقدم في ترجمة سلمان رضي الله عنه."],[38281,"٦٨٨٢ - خنساء بنت خدام"],[38282,"ب د ع: خنساء بنت خدام بن خالد الأنصارية من بني عمرو بن عوف، وقيل: خنساء بنت خدام بن وديعة."],[38283,"ورد ذكرها في حديث أبي هريرة رضي الله عنه."],[38284,"روى عنها عبد الرحمن ومجمع ابنا يزيد، أن أباها زوجها وهي بنت فكرهت ذلك، فجاءت إلى رسول الله صلى الله عليه وآله وسلم فرد نكاحها."],[38285,"وقد اختلفت الرواية في حالها عند تزويجها هذا."],[38286,"أخبرنا أبو الحرم مكي بن ربان، بإسناده عن يحيى بن يحيى، عن مالك، عن عبد الرحمن بن القاسم، عن أبيه، عن عبد الرحمن ومجمع، ابني يزيد بن جارية، عن خنساء، «أن أباها زوجها وهي ثيب فكرهت ذلك، فأتت رسول الله صلى الله عليه وآله وسلم فرد نكاحه»."],[38287,"ورواه الثوري، عن عبد الرحمن بن القاسم، عن عبد الله بن يزيد بن وديعة، عن خنساء بنت خدام، أنها كانت يومئذ بكرا."],[38288,"وحديث مالك أصح وروى محمد بن إسحاق، عن حجاج بن السائب، عن أبيه، عن جدته خنساء بنت خدام بن خالد، قال: وكانت قد أيمت من رجل فزوجها أبوها من رجل من بني عمرو بن عوف، وأنها خطبت إلى أبي لبابة بن عبد المنذر، فارتفع شأنهما إلى رسول الله صلى الله عليه وآله وسلم «فأمر رسول الله صلى الله عليه وآله وسلم أباها أن يلحقها بهواها»، فتزوجت أبا لبابة."],[38289,"أخرجها الثلاثة."],[38290,"٦٨٨٣ - خنساء بنت عمرو"],[38291,"ب: خنساء بنت عمرو الشريد بن رباح بن ثعلبة بن عصية بن خفاف بن امرئ القيس بن بهثة بن سليم السلمية الشاعرة كذا نسبها أبو عمر."],[38292,"وقال هشام بن الكلبي: صخر ومعاوية وخنساء واسمها تماضر: بنو عمرو بن الشريد بن رباح بن يقظة بن عصية بن خفاف بن امرئ القيس بن سليم. قال: ولها يقول دريد بن الصمة:"],[38293,"حيوا تماضر واربعوا صحبي"],[38294,"قدمت على رسول الله صلى الله عليه وآله وسلم مع قوها فأسلمت معهم، فذكروا أن رسول الله صلى الله عليه وآله وسلم كان يستنشدها ويعجبه شعرها، فكانت تنشده يقول: هيه يا خناس. قالوا: وكانت تقول في أول أمرها البيتين والثلاثة، حتى قتل أخوها معاوية وهو شقيقها قتله هاشم وزيد المريان، وقتل صخر وهو أخوها لأبيها، وكان أحبهما إليها، وكان حليما جوادا محبوبا في العشيرة، طعنه أبو ثور الأسدي، فمرض منها قريبا من سنة، ثم مات. فلما مات أكثرت أخته من المراثي، فأجادت من قولها في صخر أخيها:"],[38295,"أعيني جودا ولا تجمدا … ألا تبكيان لصخر الندى؟"],[38296,"ألا تبكيان الجريء الجميل؟ … ألا تبكيان الفتى السيدا؟"],[38297,"طويل العماد عظيم الرماد … ساد عشيرته أمردا"],[38298,"ولها فيه:"],[38299,"أشم أبلج يأتم الهداة به … كأنه علم في رأسه نار"],[38300,"وإن صخرا لمولانا وسيدنا … وإن صخر إذا نشتوا لنحار"],[38301,"وأجمع أهل العلم بالشعر أنه لم تكن امرأة قلبها ولا بعدها أشعر منها."],[38302,"وذكر الزبير بن بكار، عن محمد بن الحسين المخزومي، عن عبد الرحمن بن عبد الله، عن أبيه، عن أبي وجزة، عن أبيه، أن الخنساء شهدت القادسية ومعها أربعة بنين لها، فقالت لهم أول الليل: يا بني، إنكم أسلمتم وهاجرتم مختارين والله الذي لا إله غيره إنكم لبنو رجل واحد، كما أنكم بنو امرأة واحدة، ما خنت أباكم ولا فضحت خالكم، ولا هجنت حسبكم، ولا غيرت نسبكم."],[38303,"وقد تعلمون ما أعد الله للمسلمين من الثواب الجزيل في حرب الكافرين."],[38304,"واعلموا أن الدار الباقية خير من الدار الفانية، يقول الله عز وجل: ﴿يَأَيُّهَا الَّذِينَ آمَنُوا اصْبِرُوا وَصَابِرُوا وَرَابِطُوا وَاتَّقُوا اللَّهَ لَعَلَّكُمْ تُفْلِحُونَ﴾."],[38305,"فإذا أصبحتم غدا إن شاء الله سالمين فاغدوا إلى قتال عدوكم مستبصرين، وبالله على أعدائه مستنصرين."],[38306,"وإذا رأيتم الحرب قد شمرت عن ساقها، واضطرمت لظى على سياقها، وجللت نارا على أرواقها، فتيمموا وطيسها، وجالدوا رئيسها عند احتدام خميسها، تظفروا بالغنم والكرامة، في دار الخلد والمقامة."],[38307,"فخرج بنوها قابلين لنصحها، وتقدموا فقاتلوا وهم يرتجزون، وأبلوا بلاء حسنا، واستشهدوا رحمهم الله."],[38308,"فلما بلغها الخبر، قالت: الحمد لله الذي شرفني بقتلهم، وأرجو من ربي أن يجمعني بهم في مستقر رحمته."],[38309,"وكان عمر بن الخطاب رضي الله عنه يعطي الخنساء أرزاق أولادها الأربعة، لكل واحد مائتا درهم، حتى قبض رضي الله عنه."],[38310,"أخرجها أبو عمر."],[38311,"٦٨٨٤ - خولة بنت الأسود"],[38312,"ب د ع: خولة بنت الأسود بن حذافة تكنى أم حرملة الخزاعية روى موسى بن عقبة، عن ابن شهاب في تسمية من هاجر إلى أرض الحبشة من بني عبد الدار: جهيم بن قيس وقيل: جهم ومعه امرأته خولة بنت الأسود بن حذافة."],[38313,"سماها ابن عقبة ولم يكنها."],[38314,"وكناها ابن إسحاق ولم يسمها فقال: أم حرملة بنت عبد الأسود بن جزيمة بن أقيش بن عامر بن بياضة بن سبيع بن جعثمة بن سعد بن مليح بن عمرو بن خزاعة."],[38315,"هاجرت مع زوجها جهيم بن قيس."],[38316,"أخرجها الثلاثة."],[38317,"٦٨٨٥ - خولة بنت ثامر الأنصارية"],[38318,"ب د ع: خولة بنت ثامر الأنصارية"],[38319,"أخبرنا يحيى، إجازة، بإسناده عن ابن أبي عاصم، حدثنا يعقوب بن حميد، حدثنا عبد الله بن يزيد، عن سعيد بن أبي أيوب، قال: حدثني أبو الأسود، عن النعمان بن أبي عياش الزرقي، عن خولة الأنصارية، أنها قالت: سمعت رسول الله صلى الله عليه وآله وسلم يقول: «الدنيا خضرة حلوة، وإن رجالا سيخوضون في مال الله بغير حق، لهم النار يوم القيامة»."],[38320,"أخرجها الثلاثة، وقال أبو عمر: قيل: هي، ابنة قيس بن فهد، وثامر لقب"],[38321,"٦٨٨٦ - خولة بنت ثعلبة"],[38322,"ب د ع: خولة بنت ثعلبة وقيل خويلة والأول أكثر وقيل خولة بنت حكيم وقيل خولة بنت مالك بن ثعلبة بن أصرم به فهر بن ثعلبة بن غنم بن عوف."],[38323,"روي عن يوسف بن عبد الله بن سلام خولة، وروي عنه خويلة."],[38324,"أخبرنا أبو ياسر بإسناده عن عبد الله بن أحمد، حدثني أبي، حدثنا سعد ويعقوب، ابنا إسحاق، عن معمر بن عبد الله بن حنظلة، عن يوسف بن عبد الله بن سلام: حدثتني خويلة امرأة أوس بن الصامت، أخي عبادة بن الصامت، قالت: في والله وفي أوس بن الصامت أنزل الله عز وجل صدر سورة المجادلة، قالت: كنت عنده، وكان شيخا كبيرا قد ساء خلقه وضجر، قالت: فدخل علي يوما فراجعته في شيء، فغضب، وقال: أنت علي كظهر أمي، ثم خرج فجلس في نادي قومه ساعة، ثم دخل علي فإذا هو يريدني على نفسي، قالت: فقلت: كلا، والذي نفسي خويلة بيده لا تخلص إلي وقد قلت ما قلت حتى يحكم الله ورسوله فينا!."],[38325,"قالت: فواثبني وامتنعت منه، فغلبته بما تغلب به المرأة الشيخ الضعيف، فألقيته عني."],[38326,"قالت: ثم خرجت إلى بعض جاراتي فاستعرت منها ثيابها، ثم خرجت حتى جئت رسول الله صلى الله عليه وآله وسلم فجلست بين يديه، فذكرت له ما لقيت منه، وجعلت أشكو إليه ما ألقي من سوء خلقه."],[38327,"قالت: فجعل رسول الله صلى الله عليه وآله وسلم يقول: «يا خويلة، ابن عمك شيخ كبير، فاتقي الله فيه»."],[38328,"قالت: فوالله ما برحت حتى نزل في القرآن، فتغشى رسول الله صلى الله عليه وآله وسلم وما كان يتغشاه، ثم سري عنه فقال: «يا خويلة، قد أنزل الله فيك وفي صاحبك»، ثم قرأ علي: ﴿قَدْ سَمِعَ اللَّهُ قَوْلَ الَّتِي تُجَادِلُكَ فِي زَوْجِهَا وَتَشْتَكِي إِلَى اللَّهِ﴾ الآيات، إلى قوله: ﴿وَلِلْكَافِرِينَ عَذَابٌ أَلِيمٌ﴾ قالت: فقال رسول الله صلى الله عليه وآله وسلم: «مريه فليعتق رقبة»، قالت: فقلت: والله يا رسول الله ما عنده ما يعتق! قال: «فليصم شهرين متتابعين»."],[38329,"قالت: فقلت: والله إنه شيخ كبير ما به من صيام."],[38330,"«فليطعم ستين مسكينا وسقا من تمر»."],[38331,"قالت: فقلت: يا رسول الله، ما ذاك عنده! قالت: فقال رسول الله صلى الله عليه وآله وسلم: «فإنا سنعينه بعرق من تمر»، قالت: فقلت: يا رسول الله، وأنا سأعينه بعرق آخر."],[38332,"قال: «فقد أصبت وأحسنت، فاذهبي فتصدقي به عنه، ثم استوصي بابن عمك خيرا»."],[38333,"قالت: ففعلت."],[38334,"ورواه يونس بن بكير، عن ابن إسحاق، بإسناده، وقال: خولة بنت ثعلبة."],[38335,"ورواه جعفر بن الحارث، عن ابن إسحاق، بإسناده فقال: خولة بنت مالك."],[38336,"ورواه محمد بن أبي حرملة، عن عطاء بن يسار، أن خولة بنت ثعلبة كانت تحت أوس ابن الصامت، وذكر نحوه."],[38337,"ورواه أبو إسحاق السبيعي، عن يزيد بن زيد، عن خولة بنت الصامت."],[38338,"وذكر نحوه."],[38339,"وأخرج ابن منده حديثها وترجم عليه: خولة بنت الصامت."],[38340,"ويرد ذكره إن شاء الله تعالى."],[38341,"وروى محمد بن السائب الكلبي، عن أبي صالح، عن ابن عباس، أن خولة بنت ثعلبة بن مالك بن الدخشم الأنصارية كانت تحت أوس بن الصامت."],[38342,"وذكر نحوه، وقيل: جميلة، وقيل: خويلة بنت دليج."],[38343,"ولا يثبت، والأول أصح. روي عن عمر بن الخطاب رضي الله عنه أنه خرج ومعه الناس، فمر بعجوز، فجعل يحدثها وتحدثه، فقال رجل: يا أمير المؤمنين، حسبت الناس على هذه العجوز؟! قال: ويلك! تدري من هذه؟ هي امرأة سمع الله عز وجل شكواها من فوق سبع سموات، هذه خولة بنت ثعلبة التي أنزل الله فيها: ﴿قَدْ سَمِعَ اللَّهُ قَوْلَ الَّتِي تُجَادِلُكَ فِي زَوْجِهَا﴾."],[38344,"والله لو أنها وقفت إلي الليل ما فارقتها إلا للصلاة، ثم أرجع."],[38345,"أخرجها الثلاثة."],[38346,"٦٨٨٧ - خولة بنت حكيم"],[38347,"ع س: خولة بنت حكيم الأنصارية فرق الطبراني بينها وبين خولة بنت حكيم السلمية امرأة عثمان بن مظعون رضي الله عنه"],[38348,"أخبرنا أبو موسى، إذنا، أخبرنا أبو غالب الكوشيدي، أخبرنا أبو بكر بن ريذة."],[38349,"ح قال أبو موسى: وأخبرنا الحسن بن أحمد، حدثنا أبو نعيم، قالا: حدثنا سليمان، حدثنا علي بن عبد العزيز، حدثنا مسلم بن إبراهيم، حدثنا شعبة، عن عطاء الخراساني، عن سعيد بن المسيب، عن خولة بنت حكيم، قالت: سألت النبي صلى الله عليه وآله وسلم فقلت: يا رسول الله، المرأة ترى في المنام ما يرى الرجل؟ قال: «إذا رأت ذلك فلتغتسل»."],[38350,"ورواه إسماعيل بن عياش، عن عطاء."],[38351,"ورواه الثوري، عن علي بن زيد، عن سعيد."],[38352,"أخرجه أبو نعيم، وأبو موسى"],[38353,"٦٨٨٨ - خولة بنت حكيم بن أمية"],[38354,"ب د ع: خولة وقيل خويلة بنت حكيم بن أمية بن حارثة بن الأوقص بن مرة بن هلال بن فالج بن ذكوان بن ثعلبة بن بهثة بن سليم السلمية امرأة عثمان بن مظعون."],[38355,"وهي التي وهبت نفسها للنبي صلى الله عليه وآله وسلم في قول بعضهم."],[38356,"وكانت امرأة صالحة."],[38357,"روى عنها سعد ابن أبي وقاص في النزول في السفر."],[38358,"أخبرنا عبد الله بن أحمد الخطيب، أخبرنا أبو بكر بن بدران الحلواني، حدثنا أبو محمد عبد الله بن عبيد الله بن يحيى، أخبرنا الحسين بن إسماعيل المحاملي، أخبرنا إبراهيم بن هانئ، حدثنا عبد الله بن صالح، عن الليث بن سعد، عن يزيد بن أبي حبيب، عن الحارث بن يعقوب بن عبد الله، عن بسر بن سعيد، عن سعد هو ابن أبي وقاص، عن خولة بنت حكيم السلمية، قالت: سمعت رسول الله صلى الله عليه وآله وسلم يقول: «من نزل منزلا فقال: أعوذ بكلمات الله التامات من شر ما خلق، لم يضره شيء حتى يرتحل من منزله ذلك» وهي التي قالت للنبي: إن فتح الله عليك الطائف، فأعطني حلي بادية بنت غيلان، فقال لها رسول الله صلى الله عليه وآله وسلم: «أرأيت إن كان لم يؤذن في ثقيف»."],[38359,"أخرجه الثلاثة."],[38360,"٦٨٨٩ - خولة بنت دليج"],[38361,"د: خولة بنت دليج وقيل خويلة روت قصة الظهار."],[38362,"وقد ذكرناها في خولة بنت ثعلبة."],[38363,"أخرجها ابن منده."],[38364,"٦٨٩٠ - خولة خادم الرسول"],[38365,"ب د ع: خولة خادم رسول الله صلى الله عليه وآله وسلم جدة حفص بن سعيد."],[38366,"أخبرنا يحيى بن أبي الرجاء، كتابة، بإسناده عن ابن أبي عاصم، حدثنا أبو بكر بن أبي شيبة، حدثنا أبو نعيم الفضل بن دكين، عن حفص بن سعيد القرشي، قال: حدثتني أمي، عن أمها وكانت خادم رسول الله صلى الله عليه وآله وسلم أن جروا دخل البيت فمات تحت السرير، فمكث رسول الله صلى الله عليه وآله وسلم أياما لا ينزل عليه الوحي، فقال: «يا خولة، ما حدث في بيت رسول الله صلى الله عليه وآله وسلم جبرئيل لا يأتيني!» فقلت: والله ما أتى علينا يوم خير من يومنا."],[38367,"فأخذ برده فلبسه، فقلت: لو هيأت البيت وكنسته، فأوهيت بالمكنسة فإذا شيء ثقيل، لم أزل أهيئه حتى بدا لي الجرو ميتا، فألقيته خلف الدار."],[38368,"فجاء نبي الله صلى الله عليه وآله وسلم الله ترعد لحيته، وكان إذا أتاه الوحي أخذته الرعدة، فقال: «يا خولة، دثريني»."],[38369,"فأنزل الله تعالى: ﴿وَالضُّحَى وَاللَّيْلِ إِذَا سَجَى مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَى﴾، إلى قوله ﴿فَتَرْضَى﴾."],[38370,"فقام، فوضعت له ماء فتطهر، ولبس بردته، كذا قيل: والصحيح أن هذه السورة نزلت من أول ما نزل من القرآن، لما انقطع عنه الوحي، فقال المشركون: إن محمدا قد ودعه ربه، فأنزل الله هذه السورة."],[38371,"أخرجها الثلاثة، وقال أبو عمر: لا يحتج بإسناد حديثها"],[38372,"٦٨٩١ - خولة بنت الصامت"],[38373,"د: خولة بنت الصامت روى أبو إسحاق السبيعي، عن يزيد بن زيد، عن خولة بنت الصامت قصة الظهار."],[38374,"وقد ذكرناها في خولة بنت ثعلبة."],[38375,"أخرجها ابن منده."],[38376,"٦٨٩٢ - خولة بنت عاصم"],[38377,"د ع: خولة بنت عاصم امرأة هلال بن أمية التي لاعنها ففرق النبي صلى الله عليه وآله وسلم بينهما."],[38378,"أخرجها ابن منده، وأبو نعيم."],[38379,"٦٨٩٣ - خولة بنت عبد الله الأنصاري"],[38380,"ب د ع: خولة بنت عبد الله الأنصارية عدادها في البصريين."],[38381,"روت رقية بنت سعد، عن جدتها خولة بنت عبد الله الأنصارية أنها سمعت رسول الله صلى الله عليه وآله وسلم يقول: «الناس دثار، والأنصار شعار، اللهم اغفر للأنصار، ولأبناء الأنصار، ولأبناء أبناء الأنصار»."],[38382,"وأرجو أن تكون قد أدركتني دعوة رسول الله صلى الله عليه وآله وسلم. أخرجها الثلاثة، قال أبو عمر: في إسنادها مقال."],[38383,"٦٨٩٤ - خولة بنت عمرو"],[38384,"د ع: خولة بنت عمر لها ذكر في حديث عائشة."],[38385,"روى هشام بن عروة، عن أبيه، عن عائشة، أن النبي صلى الله عليه وآله وسلم «ابتاع جزورا، فبعث إلى خولة بنت عمرو يستسلفها»."],[38386,"أخرجها ابن منده، وأبو نعيم."],[38387,"٦٨٩٥ - خولة بنت قيس الأنصارية"],[38388,"ب د ع: خولة بنت قيس بن قهد بن قيس بن ثعلبة بن غنم بن مالك بن النجار الأنصارية النجارية."],[38389,"زوج حمزة بن عبد المطلب رضي الله عنه، تكنى أم محمد."],[38390,"وقد قيل: إن امرأة حمزة: خولة بنت ثامر، وقيل: إن ثامرا لقب لقيس بن قهد."],[38391,"والأول أصح، قاله أبو عمر."],[38392,"وقال أبو نعيم: تكنى أم محمد، وقيل: أم حبيبة."],[38393,"وقال ابن منده: تكنى أم صبية، وقيل: أم محمد."],[38394,"وهذا وهم منه، صحف حبيبة بصبية، فإن أم صبية جهنية وهذه أنصارية من أنفسهم."],[38395,"قتل عنها حمزة يوم أحد، فخلف عليها النعمان بن العجلان الأنصاري الزرقي."],[38396,"قال علي بن المديني: خولة بنت قيس، هي خولة بنت ثامر."],[38397,"روى عنها عبيد أبو الوليد سنوطي ومحمود بن الربيع، ومعاذ بن رفاعة، ومحمد بن يحيي بن حبان."],[38398,"أخبرنا أبو منصور بن مكارم، أخبرنا نصر ابن صفوان، بإسناده عن المعافي بن عمران، عن عبد الحميد بن جعفر الأنصاري، عن سعيد، أن أبا الوليد عبيدا، أخبره، أنه دخل مع أبي عبيدة الزرقي على خولة ابنة قيس، قالت: ذكر المال عند رسول الله صلى الله عليه وآله وسلم فقال: «إن المال حلوة خضرة، من أصابه بحقه بورك له فيه، ورب متخوض فيما اشتهت نفسه في مال الله ورسوله يوم القيامة في النار» وروى محمود بن لبيد، عن خولة بنت قيس بن قهد، أن النبي صلى الله عليه وآله وسلم قال: «ألا أخبركم بكفارات الخطٍايا»."],[38399,"قالوا: بلى يا رسول الله."],[38400,"قال: «إسباغ الوضوء عند المكاره، وكثرة الخطى إلى المساجد، وانتظار الصلاة بعد الصلاة»."],[38401,"أخرجه الثلاثة."],[38402,"قلت: ما أقرب أن يكون ثامر لقب قيس ابن قهد، فإن الحديث في الترجمتين واحد، وهو، أن هذا المال حلوة خضرة."],[38403,"والله أعلم."],[38404,"٦٨٩٦ - خولة بنت قيس الجهنية"],[38405,"ب ع س: خولة بنت قيس الجهنية أم صبية."],[38406,"حديثها عند سالم ونافع ابني سرج أو النعمان بن خربوذ."],[38407,"فرق الطبراني بينها وبين خولة بنت قيس بن قهد الأنصارية زوج حمزة بن عبد المطلب، إلا أن أبا نعيم كناها أم صبية."],[38408,"وكذلك فرق بينهما أبو عمر أيضا، وكناها أم صبية أيضا."],[38409,"وقال جعفر المستغفري: خولة بنت قيس أم صبية، هي جدة خارجة بن النعمان، وليست بامرأة حمزة، ولا بالمجادلة التي اشتكت زوجها."],[38410,"أخبرنا أبو موسى، إذنا، أخبرنا أبو علي، أخبرنا أحمد بن عبد الله."],[38411,"ح قال أبو موسى: وأخبرنا أبو غالب، حدثنا أبو بكر محمد بن عبد الله، قالا: حدثنا سليمان بن أحمد، حدثنا علي بن المبارك الصنعاني، حدثنا إسماعيل بن أبي أويس، حدثني خارجة بن الحارث بن رافع بن مكيث الجهني، عن سالم بن سرج مولى أم صبية، وهي خولة بنت قيس هي أم جدة خارجة، أنه سمعها تقول: «اختلفت يدي ويد رسول الله صلى الله عليه وآله وسلم في إناء واحد»، تعني في الوضوء."],[38412,"أخرجها أبو نعيم، وأبو عمر، وأبو موسى. وأما ابن منده فإنه جعل أم صبية كنية خولة بنت قيس بن فهد، التي قبل هذه الترجمة ظنا منه أنها هي حيث رأى بنسبها ابنة قيس وهذه جهينة وتلك أنصارية، وسنذكرها في الكني إن شاء الله تعالى، فإنها مشهورة بكنيتها."],[38413,"وقد أخرج أحمد بن حنبل في مسنده ترجمة خولة بنت قيس، وروى لها حديث: «الدنيا حلوة خضرة»."],[38414,"وأخرج ترجمة أخرى أم صبية الجهنية، وروى لها حديث: «اختلفت يدي رسول الله صلى الله عليه وآله وسلم في إناء واحد»، إلا أنه لم يسمها، وهذا يدل أنهما اثنتان"],[38415,"٦٨٩٧ - خولة بنت الهذيل"],[38416,"ب: خولة بنت الهذيل بن هبيرة بن قبيصة بن الحارث بن حبيب بن حرفة بن ثعلبة بن بكر بن حبيب بن غنم بن ثعلب التغلبية."],[38417,"تزوجها رسول الله صلى الله عليه وآله وسلم فماتت في الطريق قبل أن تصل إليه، قاله الجرجاني النسابة."],[38418,"أخرجه أبو عمر."],[38419,"حرفة: بضم الحاء المهملة، وتسكين الراء، وبالفاء."],[38420,"٦٨٩٨ - خولة بنت يسار"],[38421,"ب د ع: خولة بنت يسار روى علي بن ثابت الجزري، عن الوازع بن نافع، عن أبي سلمة بن عبد الرحمن، عن خولة بنت يسار، أنها قالت: قلت: يا رسول الله، إني أحيض وليس لي إلا ثوب واحد؟ قال: «اغسليه وصلي فيه»."],[38422,"قلت: يا رسول الله، إنه يبقى فيه أثر الدم؟ قال: «لا يضرك»."],[38423,"وروى أبو هريرة، رضي الله عنه، أن خولة بنت يسار، قالت لرسول الله صلى الله عليه وآله وسلم: أرأيت إن لم يخرج أثر الدم؟ قال: «يكفيك غسله ولا يضرك»."],[38424,"أخرجها الثلاثة، وقال أبو عمر: أخشى أن تكون خولة بنت اليمان، لأن إسناد حديثهما واحد، وإنما هو علي بن ثابت، عن الوازع، عن أبي سلمة."],[38425,"الحديث الذي نذكره في خولة بنت اليمان، إلا أن من دون علي بن ثابت يختلف في الحديثين، وفي ذلك نظر."],[38426,"٦٨٩٩ - خولة بنت اليمان"],[38427,"ب د ع: خولة بنت اليمان العبسية أخت حذيفة بن اليمان."],[38428,"أخبرنا يحيى، كتابة، بإسناده عن ابن أبي عاصم، قال: حدثنا صلت بن مسعود، عن علي ابن ثابت، عن الوازع بن نافع، عن أبي سلمة بن عبد الرحمن، عن خولة بنت اليمان، قالت: قال رسول الله صلى الله عليه وآله وسلم: «لا خير في جماعة النساء إلا على ميت، فإنهن إذا اجتمعن قلن وقلن» وروى ربعي بن حراش، عن امرأته، عن أخت حذيفة، قالت: قام فينا رسول الله صلى الله عليه وآله وسلم فحمد الله وأثنى عليه، ثم قال: «يا معاشر النساء، أما لكن في الفضة ما تحلين به؟ أما إنه ليس منكن امرأة تحلى ذهبا تظهره إلا عذبت به»."],[38429,"أخرجه الثلاثة."],[38430,"٦٩٠٠ - خولة"],[38431,"ع س: خولة روى عنها معاوية بن إسحاق قال أبو نعيم: أفردها الطبراني، وقال: أراها امرأة حمزة."],[38432,"أخبرنا يحيى، كتابة، بإسناده إلى ابن أبي عاصم، قال: حدثنا محمد بن عوف، حدثنا موسى بن أيوب، حدثنا بقية، عن ابن أبي الجون، عن أبي سعيد، عن معاوية بن إسحاق، عن خولة، أنها قالت: قال رسول الله صلى الله عليه وآله وسلم: «ما يقدس الله أمة لا يأخذ ضعيفها من قويها حقه غير متعتع»"],[38433,"قال: «ومن انصرف عن غريمه وهو راض عنه صلت عليه دواب الأرض ونون البحار، ومن انصرف عن غريمه وهو ساخط عليه، كتب عليه كل يوم وليلة وجمعة وشهر ظلم»."],[38434,"أخرجه أبو نعيم، وأبو موسى"],[38435,"٦٩٠١ - خيرة بنت أبي حدرد"],[38436,"ب د ع: خيرة بنت أبي حدرد أم الدرداء الكبرى وقيل اسمها هجيمة وهي زوج أبي الدرداء."],[38437,"روى حديثها سهل بن معاذ، عن أبيه، وصفوان بن عبد الله، وعبد الله بن باباه."],[38438,"أخبرنا أبو محمد بن أبي القاسم الدمشقي، أخبرنا أبي، أخبرنا أبو منصور محمود بن أحمد بن عبد المنعم، أخبرنا أبو علي الحسين بن عمر بن الحسن بن يونس، أخبرنا أبو عمر القاسم بن جعفر، أخبرنا أبو هاشم عبد الغافر بن سلامة، حدثنا يحيى بن عثمان، حدثنا محمد بن حمير، عن أسامة، عن سهل، عن أبيه، أنه سمع أم الدرداء تقول: خرجت من الحمام فلقيني رسول الله صلى الله عليه وآله وسلم فقال: «من أين أقبلت يا أم الدرداء؟» فقلت: من الحمام، فقال: «والذي نفسي بيده، ما منكن امرأة تضع ثيابها في بيت أحد إلا وهي هاتكة كل ستر بينها وبين الرحمن عز وجل»."],[38439,"أخرجها الثلاثة. وترد في الكنى إن شاء الله تعالى."],[38440,"قلت: قد جعل ابن منده، وأبو نعيم خيرة أم الدرداء الكبرى، قالا: وقيل: هجيمة."],[38441,"فجعلاهما واحدة، وليس كذلك، فإن الكبرى اسمها خيرة، وأم الدرداء الصغرى اسمها هجيمة الكبرى، لها صحبة، والصغرى لا صحبة لها."],[38442,"هذا هو الصحيح وما سواه وهم، قال علي بن المديني: كان لأبي الدرداء امرأتان، كلاهما يقال لها: أم الدرداء، إحداهما رأت النبي صلى الله عليه وآله وسلم وهي خيرة بنت أبي حدرد، والثانية تزوجها بعد وفاة النبي صلى الله عليه وآله وسلم وهي التي نروي عنها، وهي هجيمة الوصابية."],[38443,"وقال أبو مسهر: هما واحدة."],[38444,"وهو وهم منه."],[38445,"قال الأمير أبو نصر: خيرة بنت أبي حدرد أم الدرداء الكبرى، زوجة أبي الدرداء، لها صحبة، يقال: ماتت قبل أبي الدرداء، وأم الدرداء الصغرى هجيمة بنت حي الوصابية، هي التي خطبها معاوية فأبت أن تتزوجه فظهر بهذا أنهما اثنتان، والله أعلم"],[38446,"٦٩٠٢ - خيرة امرأة كعب"],[38447,"ب د ع: خيرة امرأة كعب بن مالك الأنصاري."],[38448,"أخبرنا يحيى، إجازة، بإسناده عن ابن أبي عاصم، قال: حدثنا الحسن بن علي، حدثنا عبد الله بن صالح، عن الليث بن سعد، عن رجل من ولد كعب بن مالك، يقال له: عبد الله بن يحيى، عن أبيه، عن جدته خيرة امرأة كعب بن مالك، أنها أتت رسول الله صلى الله عليه وآله وسلم بحلي لها فقالت: إني تصدقت بهذا، فقال رسول الله صلى الله عليه وآله وسلم: «إنه لا يجوز للمرأة في مالها أمر إلا بإذن زوجها."],[38449,"فهل استأذنت كعبا؟» فقالت: نعم."],[38450,"فبعث رسول الله صلى الله عليه وآله وسلم إلى كعب فقال: «هل أذنت لخيرة أن تتصدق بحليها؟» فقال: نعم."],[38451,"فقبله رسول الله صلى الله عليه وآله وسلم منها."],[38452,"وروى عبد الله بن يحيى، عن أبيه، عن جدته خيرة امرأة كعب."],[38453,"أخرجه الثلاثة"],[38454,"حرف الدال"],[38455,"٦٩٠٣ - درة بنت أبي سفيان"],[38456,"س: درة بنت أبي سفيان صخرة بن حرب بن أمية القرشية الأموية أخت أم حبيبة زوج النبي صلى الله عليه وآله وسلم روى هشام بن عروة، عن أبيه، عن زينب بنت أبي سلمة، عن أم حبيبة، أنها قالت لرسول الله صلى الله عليه وآله وسلم: هل لك في درة بنت أبي سفيان؟ قال لها: «فأفعل ماذا؟»، قالت: تزوجها، قال: «أتحبين ذلك»، قالت: لست بمخلية لك، وأحب من شركني فيك أختي، قال: «فإنها لا تحل لي»، قالت: إنه بلغني أنك تخطب بنت أبي سلمة؟ قال: «فليست تحل لي، إنها ربيبتي في حجري، وإني وأياها أرضعتنا ثويبة، فلا تعرضن علي بناتكن ولا أخواتكن»."],[38457,"أخرجه أبو عمر، وقال: الأشهر في بنت أبي سفيان أن أسمها عزة، وقيل فيها: حسنة وقد تقدم، والله أعلم."],[38458,"٦٩٠٤ - درة بنت أبي سلمة"],[38459,"ب د ع: درة بنت أبي سلمة بن عبد الأسد القرشية المخزومية ربيبة رسول الله صلى الله عليه وآله وسلم أمها أم سلمة زوج النبي صلى الله عليه وآله وسلم روى الليث بن سعد، عن يزيد بن أبي حبيب، عن عراك بن مالك، أن زينب بنت أبي سلمة أخبرته أن أم حبيبة قالت لرسول الله صلى الله عليه وآله وسلم: إنا قد تحدثنا أنك ناكح درة بنت أبي سلمة فقال رسول الله صلى الله عليه وآله وسلم: «أعلى أم سلمة، لو أني لم أنكح أم سلمة لم حلت لي، إن أباها أخي من الرضاعة»."],[38460,"أخرجه الثلاثة، وقال أبو عمر: إنها معروفة عند أهل العلم بالسير والخبر والحديث في بنات أم سلمة ربائب النبي صلى الله عليه وآله وسلم. وقال الزبير: ولد أبو سلمة بن عبد الأسد: سلمة، وعمرو، ودرة وزينب، أمهم: أم سلمة بنت أبي أمية."],[38461,"٦٩٠٥ - درة بنت أبي لهب"],[38462,"ب د ع: درة بنت أبي لهب بن عبد المطلب بن هاشم القرشية الهاشمية بنت عم النبي صلى الله عليه وآله وسلم. أسلمت وهاجرت إلى المدينة، وكانت عند الحارث بن نوفل بن الحارث بن عبد المطلب، فولدت له عقبة والوليد وأبا مسلم."],[38463,"روى محمد بن إسحاق، عن نافع، وزيد بن أسلم، عن ابن عمر، وعن سعيد بن أبي سعيد المقبري، وابن المنكدر، عن أبي هريرة رضي الله عنه، وعن عمار بن ياسر، قالوا: قدمت درة بنت أبي لهب المدينة مهاجرة، فنزت في دار رافع بن المعلى الزرقي، فقال لها نسوة جلسن إليها من بني زريق، أنت ابنة أبي لهب الذي يقول الله له: ﴿تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ﴾ فما يغني عنك مهاجرتك فأتت النبي صلى الله عليه وآله وسلم فذكرت له ما قلن لها فسكنها، وقال: «اجلسي»، ثم صلى بالناس الظهر، وجلس على المنبر ساعة، ثم قال: «أيها الناس، مالي أوذى في أهلي؟ فوالله إن شفاعتي لتنال بقرابتي حتى إن صداء وحكما وسلهما لتنالها يوم القيامة»."],[38464,"وسلهم في نسب اليمن."],[38465,"أخبرنا أبو ياسر، بإسناده عن عبد الله بن أحمد، حدثني أبي، حدثنا أحمد بن عبد الملك، عن شريك، عن سماك بن حرب، عن زوج درة بنت أبي لهب، عن درة بنت أبي لهب، قالت: قام رجل إلى النبي صلى الله عليه وآله وسلم وهو على المنبر فقال: يا رسول الله، أي الناس خير؟ فقال: «خير الناس أقرؤهم وأتقاهم، وآمرهم بالمعروف وأنهاهم عن المنكر، وأوصلهم للرحم»."],[38466,"وقد روى عن شريك، عن سماك، عن عبد الله بن عميرة، عن زوج درة، عن درة."],[38467,"ورواه شعبة، عن سماك، عن عبد الله بن عميرة، عن رجل، عن زوج درة بنت أبي لهب، عن بنت أبي جهل."],[38468,"وهو وهم."],[38469,"أخرجه الثلاثة"],[38470,"٦٩٠٦ - دقرة أم ولد أذينة"],[38471,"ع س: دقرة أم ولد أذينة ذكرها الطبراني، وقال: يقال: لها صحبة."],[38472,"ولم يذكر لها شيئا."],[38473,"روت عن عائشة."],[38474,"أخرجها أبو نعيم، وأبو موسى مختصرا."],[38475,"حرف الذال"],[38476,"٦٩٠٧ - ذرة"],[38477,"د ع: ذرة امرأة من أصحاب النبي صلى الله عليه وآله وسلم غير منسوبة."],[38478,"روى عنها: محمد بن المنكدر، وزيد بن أسلم."],[38479,"روى أبو النصر هاشم بن القاسم، عن أبي جعفر الرازي، عن ليث، عن محمد بن المنكدر، عن ذرة، أنها قالت: قال رسول الله صلى الله عليه وآله وسلم: «أنا وكافل اليتيم له أو لغيره كهاتين في الجنة، وأشار بإصبعيه، الساعي على الأرملة والمسكين كالغازي في سبيل الله تعالى، وكالقائم الصائم الذي لا يفتر»."],[38480,"أخرجه ابن منده، وأبو نعيم."],[38481,"حرف الراء"],[38482,"٦٩٠٨ - رائطة بنت الحارث"],[38483,"ب س: رائطة بنت الحارث بن جبيلة بن عامر بن كعب بن سعد بن تيم بن مرة هاجرت مع زوجها الحارث بن خالد بن صخر بن عامر بن كعب إلى أرض الحبشة، فولدت له هناك عائشة وزينب بنت الحارث، هلكن جميعا."],[38484,"أخبرنا أبو جعفر، بإسناده إلى يونس، عن محمد بن إسحاق، في تسمية من هاجر إلى أرض الحبشة: ومن بني تميم بن مرة الحارث بن خالد بن صخر بن عامر بن كعب، ومعه امرأته ريطة بنت الحارث."],[38485,"أخرجها أبو موسى فسماها رائطة، وأخرجها أبو عمر فسماها ريطة"],[38486,"٦٩٠٩ - رائطة بنت حيان"],[38487,"رائطة بنت حيان بن عميرة بن ناصرة من سبي هوزان، وهبها رسول الله صلى الله عليه وآله وسلم لعلي بن أبي طالب فعلمها شيئا من القرآن."],[38488,"أخبرنا بذلك أبو جعفر بن السمين، بإسناده عن يونس، عن ابن إسحاق"],[38489,"٦٩١٠ - رائطة بنت سفيان"],[38490,"ب د ع: رائطة بنت سفيان بن الحارث الخزاعية زوج قدامة بن مظعون روت عنها ابنتها عائشة بنت قدامة أنها كانت مع أمها رائطة لما بايعت رسول الله صلى الله عليه وآله وسلم هي والنساء."],[38491,"وقد ذكرت في عائشة بنت قدامة."],[38492,"أخرجها الثلاثة."],[38493,"٦٩١١ - رائطة بنت عبد الله"],[38494,"ع: رائطة بنت عبد الله امرأة ابن مسعود وقيل ريطة وتذكر في ريطة إن شاء الله تعالى."],[38495,"أخرجها أبو نعيم."],[38496,"٦٩١٢ - رائعة بنت ثابت"],[38497,"رائعة بنت ثابت بن الفاكه بن ثعلبة الأنصارية ثم من بني خطمة بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[38498,"٦٩١٣ - الرباب بنت معرور"],[38499,"الرباب بنت البراء بن معرور بن خنساء الأنصارية بايعت النبي صلى الله عليه وآله وسلم. قاله ابن حبيب."],[38500,"٦٩١٤ - الرباب بنت حارثة"],[38501,"الرباب بنت حارثة بن سنان بن عبيد الأنصارية ثم من بني الأبجر بايعت رسول الله صلى الله عليه وآله وسلم قاله ابن حبيب."],[38502,"٦٩١٥ - الرباب بنت كعب"],[38503,"الرباب بنت كعب بن عدي بن عبد الأشهل وهي أم حذيفة وسعد وصفوان بني اليمان."],[38504,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[38505,"٦٩١٦ - الرباب بنت النعمان"],[38506,"الرباب بنت النعمان بن امرئ القيس بن زيد بن عبد الأشهل الأنصاري، وهي أم معاذ بن زرارة الظفري، بايعت النبي صلى الله عليه وآله وسلم. قاله ابن حبيب."],[38507,"٦٩١٧ - الربداء بنت عمرو"],[38508,"الربداء بنت عمرو بن عمارة بن عطية البلوية قال عبيد الله بن سعيد: كان ياسر أبو الربداء عبدا لامرأة من بلي يقال لها الربداء بنت عمرو بن عمارة البلوي، فزعم أنه مر به النبي صلى الله عليه وآله وسلم وهو يرعى غنم مولاته، وله فيها شاتان، فاستسقاه النبي صلى الله عليه وآله وسلم فحلب له شاتيه، ثم راح وقد حفلتا فأخبر مولاته، فأعتقته، فاكتنى بابي الربداء ذكره الغساني."],[38509,"٦٩١٨ - الربيع بنت معوذ"],[38510,"ب د ع: الربيع بنت معوذ ابن عفراء الأنصارية تقدم نسبها عند ذكر أبيها وأعمامها."],[38511,"لها صحبة."],[38512,"روى عنها أهل المدينة، وكانت ربما غزت مع رسول الله صلى الله عليه وآله وسلم فتداوي الجرحي وترد القتلى إلى المدينة، وكانت من المبايعات تحت الشجرة بيعة الرضوان."],[38513,"وروى الزبير، عن عمه، عن الواقدي، قال كانت بنت مخربة تبيع العطر بالمدينة، وهي أم عياش، وعبد الله ابني أبي ربيعة المخزوميين، فدخلت هذه أسماء على الربيع بنت معوذ ومعها عطرها في نسوة فسألنها، فانتسبت الربيع، فقالت لها أسماء: أنت ابنة قاتل سيدة تعني: أبا جهل."],[38514,"قالت الربيع: بل أنا ابنة قاتل عبده."],[38515,"قالت: حرام علي أن أبيعك من عطري شيئا."],[38516,"قلت: وحرام على أن أشتري منه شيئا، فما رأيت لعطر نتنا غير عطرك، ثم قمت."],[38517,"وإنما قلت ذلك لأغيظها."],[38518,"أخبرنا غير واحد، بإسنادهم عن أبي عيسى، قال: حدثنا حميد بن مسعدة البصري، حدثنا بشر بن المفضل، حدثنا خالد بن ذكوان، عن الربيع بنت معوذ، قالت: جاءنا رسول الله صلى الله عليه وآله وسلم فدخل علي غداة بني بي، فجلس على فراشي كمجلسك مني، وجويريات لنا يضربن بدفوفهن ويندبن من قتل من آبائي يوم بدر، إلى أن قالت إحداهن: وفينا نبي ما في غد، فقال لها: «اسكتي عن هذه، وقولي التي كنت تقولين قبلها» وروى أبو عبيدة بن محمد بن عمار بن ياسر، قال: قلت للربيع بنت معوذ بن عفراء: صفي لي رسول الله صلى الله عليه وآله وسلم فقالت: يا بني، لو رأيته لرأيت الشمس طالعة."],[38519,"أخرجها الثلاثة."],[38520,"الربيع: بضم الراء، وفتح الموحدة، وتشديد الياء تحتها نقطتان."],[38521,"٦٩١٩ - الربيع بنت النضر"],[38522,"ب د ع: الربيع تصغير الربيع أيضا هي بنت النضر تقدم نسبها عند أخيها أنس بن النضر، وهي أنصارية من بني عدي بن النجار، وهي أم حارثة بن سراقة الذي استشهد بين يدي رسول الله صلى الله عليه وآله وسلم ببدر، فأتت أمة الربيع رسول الله صلى الله عليه وآله وسلم فقالت: يا رسول الله، أخبرني عن حارثة فإن كان في الجنة صبرت واحتسبت، وإن كان غير ذلك اجتهدت في البكاء، فقال: «إنها جنات، وإنه أصاب الفردوس الأعلى»."],[38523,"وهذه الربيع هي التي كسرت ثنية امرأة، فعرضوا عليهم الأرش فأبوا، وطلبوا العفو فأبوا وأتوا النبي صلى الله عليه وآله وسلم فأمر النبي صلى الله عليه وآله وسلم بالقصاص، فقام أخوها أنس بن النضر فقال: يا رسول الله أتكسر ثنية الربيع لا والذي بعثك بالحق لا تكسر ثنيتها فعفا القوم بعد أن كانوا امتنعوا، فقال رسول الله صلى الله عليه وآله وسلم: «إن من عباد الله من أقسم على الله لأبره»."],[38524,"وقد قيل: إن التي فعلت ذلك كانت أخت الربيع."],[38525,"أخبرنا يحيى بن محمود عن عبد الوهاب بن أبي حبة."],[38526,"بإسنادهما عن مسلم، قال: حدثنا أبو بكر بن أبي شيبة، حدثنا عفان، حدثنا حماد، حدثنا ثابت، عن أنس: أن أخت الربيع أم حارثة جرحت إنسانا، فاختصموا إلى رسول الله صلى الله عليه وآله وسلم فقال رسول الله صلى الله عليه وآله وسلم: «القصاص القصاص» فقالت أم الربيع: يا رسول الله، أيقتص من فلانة! والله لا يقتصن منها أبدا، فقال رسول الله صلى الله عليه وآله وسلم: «سبحان الله يا أم الربيع! القصاص كتاب الله»."],[38527,"قالت: والله لا يقتص منها أبدا."],[38528,"فما زالت حتى قبلوا، فقال رسول الله صلى الله عليه وآله وسلم: «إن من عباد الله من لو أقسم على الله لأبره»."],[38529,"أخرجها الثلاثة"],[38530,"٦٩٢٠ - رجاء الغنوية"],[38531,"ب د ع: رجاء الغنوية سكنت البصرة، روى عنها محمد بن سيرين."],[38532,"أخبرنا أبو ياسر، بإسناده عن عبد الله بن أحمد، حدثني أبي، حدثنا عبد الرزاق، أخبرنا هشام، عن ابن سيرين، عن امرأة يقال لها: رجاء، أنها قالت: كنت عند النبي صلى الله عليه وآله وسلم فجاءته امرأة بابن لها فقالت: يا رسول الله، ادع الله لي فيه بالبركة، فإنه توفي لي ثلاثة، فقال لها رسول الله صلى الله عليه وآله وسلم: «أمنذ أسلمت؟» قالت: نعم، فقال رسول الله صلى الله عليه وآله وسلم: «جنة حصينة»."],[38533,"قالت: فقال لي رجل عند رسول الله صلى الله عليه وآله وسلم: اسمعي يا رجاء ما يقول رسول الله صلى الله عليه وآله وسلم. أخرجه الثلاثة"],[38534,"٦٩٢١ - رزينة خادم رسول الله ﷺ"],[38535,"ب د ع: رزينة خادم رسول الله صلى الله عليه وآله وسلم وهي مولاة صفية زوج النبي صلى الله عليه وآله وسلم روت عنها ابنتها أمة الله، ولها أيضا صحبة في قول."],[38536,"روي أن النبي صلى الله عليه وآله وسلم لما تزوج صفية بنت حيي أمهرها خادما، وهي رزينة."],[38537,"وروت عليلة بنت الكميت العتكية، عن أمها أمينة، عن أمة الله بنت رزينة، قالت: سألت أمي رزينة: ما كان رسول الله صلى الله عليه وآله وسلم يقول في صوم يوم عاشور؟ قالت: إن كان ليصومه ويأمر بصيامه."],[38538,"أخرجها الثلاثة."],[38539,"حديثها عند أهل البصرة."],[38540,"٦٩٢٢ - رضوى مولاة رسول الله ﷺ"],[38541,"س: رضوى مولاة رسول الله صلى الله عليه وآله وسلم ذكرها جعفر المستغفري في الصحابيات، ولم يخرج لها شيئا."],[38542,"أخرجها أبو موسى مختصرا."],[38543,"٦٩٢٣ - رضوى بنت كعب"],[38544,"س: رضوى بنت كعب روى سعيد بن بشير، عن قتادة، عن رضوى بنت كعب، قالت: سألت النبي صلى الله عليه وآله وسلم عن الحائض تختضب، فقال: «ما بذلك بأس»."],[38545,"أخرجها أبو موسى."],[38546,"٦٩٢٤ - رفاعة بنت ثابت"],[38547,"رفاعة بنت ثابت بن الفاكه بن ثعلبة الأنصارية من بني خطمة."],[38548,"بايعت النبي صلى الله عليه وآله وسلم. قال ابن حبيب."],[38549,"٦٩٢٥ - رفيدة الأنصارية"],[38550,"س: رفيدة الأنصارية وقيل الأسلمية"],[38551,"أخبرنا عبيد الله بن أحمد، بإسناده عن يونس، عن ابن إسحاق، قال: وكان رسول الله صلى الله عليه وآله وسلم حين أصاب سعدا السهم بالخندق، قال لقومه: «اجعلوه في خيمة رفيدة حتى أعوده من قريب»."],[38552,"وكانت امرأة من أسلم، في مسجده، فكانت تداوي الجرحى، وتحتسب بنفسها على خدمة من كانت به ضيعة من المسلمين، وكان رسول الله صلى الله عليه وآله وسلم يمر به فيقول: «كيف أمسيت وكيف أصبحت؟» فيخبره."],[38553,"أخرجه أبو موسى"],[38554,"٦٩٢٦ - رقيقة الثقفية"],[38555,"ب ع س: رقيقة الثقفية"],[38556,"أخبرنا يحيى بن محمود، إذنا، بإسناده عن ابن أبي عاصم، قال: حدثنا عمرو بن علي، حدثنا أبو عاصم، عن عبد الله بن عبد الرحمن بن يعلي بن كعب الطائفي، عن عبد ربه بن الحكم، عن ابنة رقيقة، عن أمها رقيقة، قالت: لما جاء النبي صلى الله عليه وآله وسلم يبتغي النصر بالطائف، دخل علي، فأخرجت له شرابا من سويق، فقال: «يا رقيقة، لا تعبدي طاغيتهم ولا تصلن إليها»."],[38557,"قالت: إذا يقتلوني، قال: «فإذا قالوا لك فقولي: ربي رب هذه الطاغية، فإذا صليت فوليها ظهرك»، ثم خرج رسول الله صلى الله عليه وآله وسلم من عندي"],[38558,"قالت بنت رقيقة: فأخبرني أخواي سفيان ووهب ابنا قيس بن أبان، قالا: لما أسلمت ثقيف خرجنا إلى رسول الله صلى الله عليه وآله وسلم قال: «ما فعلت أمكما؟»، قلنا: هلكت على الحال التي تركتها، قال: «لقد أسلمت أمكما»."],[38559,"أخرجها أبو نعيم، وأبو عمر، وأبو موسى"],[38560,"٦٩٢٧ - رقيقة بنت صيفي"],[38561,"ب ع س: رقيقة بنت صيفي بن هاشم بن عبد مناف أوردها الطبراني وجعفر المستغفري في الصحابيات، وقال أبو نعيم: لا أراها أدركت البعثة والدعوة."],[38562,"أخبرنا أبو موسى، إذنا، أخبرنا الكوشيدي، أخبرنا أبو بكر بن ريذة، حدثنا سليمان بن أحمد، أخبرنا محمد بن موسى البربري، أخبرنا زكريا بن يحيى الطائي، حدثني عم أبي زحر بن حصن، عن جده حميد بن منهب، حدثني عروة بن مضرس، أخبرنا مخرمة بن نوفل، عن أمه رقيقة، قال: وكانت لدة عبد المطلب بن هاشم، قالت: تتابعت على قريش سنون أقلحت الضرع، وأدقت العظم، فبينا أنا راقدة اللهم أو مهومة إذ أنا بهاتف يصرخ بصوت صحل، يقول: يا معشر قريش، إن هذا النبي مبعوث، قد أظلتكم أيامه، وهذا إبان نجومه، فجي هلا بالحيا والخصب، ألا فانظروا رجلا منكم وسيطا، عظاما جساما، أبيض بضا، أوطف الأهداب، سهل الخدين، أشم العرنين، له فخر يكظم عليه، وسنة تهدي إليه، فليخلص هو وولده، ليهبط إليه من كل بطن رجل فليشنوا من الماء، وليمسوا من الطيب، وليستلموا الركن، ثم ليرقوا أبا قبيس، ثم ليدع الرجل، وليؤمن القوم فغثتم ما شئتم."],[38563,"فأصبحت علم الله مذعورة، اقشعر جلدي، ودله عقلي، واقتصصت رؤياي، ونمت في شعاب مكة، فوالحرمة والحرم ما بقي بها أبطحي إلا قال: هذا شيبة الحمد."],[38564,"وتناهت إليه رجالات قريش، وهبط إليه من كل بطن رجل، فشنوا ومسوا واستلموا، ثم ارتقوا أبا قيس، واصطفوا حوله ما يبلغ سعيهم مهلة، حتى إذا استووا بذروة الجبل، قام عبد المطلب ومعه رسول الله صلى الله عليه وآله وسلم غلام قد أيفع، أو كرب، فرفع يديه فقال: «اللهم ساد الخلة، وكاشف الكربة، أنت معلم غير معلم ومسئول غير مبخل، وهذه عبداك وإماؤك بعذرات حرمك، يشكون إليك سنتهم التي أذهبت الخف والظلف، اللهم فأمطر علينا مغدقا مرتعا»."],[38565,"فورب الكعبة ما راموا حتى تفجرت السماء بما فيها، واكتظ الوادي بشجيجة، فسمعت شيخان قريش وجلتها: عبد الله بن جدعان، وجرب بن أمية، وهشام بن المغيرة يقولون لعبد المطلب: هنيئا لك أبا البطحاء، أي: عاش بك أهل البطحاء."],[38566,"وفي ذلك تقول رقيقة:"],[38567,"بشيبة الحمد أسقى الله بلدتنا … وقد فقدنا الحيا واجلوذ المطر"],[38568,"فجاد بالماء جوني له سبل … سحا، فعاشت به الأنعام والشجر"],[38569,"منا من الله بالميمون طائره … وخير من بشرت يوما به مضر"],[38570,"مبارك الأمر يستسقي الغمام به … ما في الأنام له عدل ولا خطر"],[38571,"أخرجه أبو نعيم، وأبو موسى، وقال أبو موسى: هذا حديث حسن عال، في هذا الحديث غريب نشرحه مختصرا قوله: لدة عبد المطلب، أي: على سنه."],[38572,"وأقحلت: أيبست."],[38573,"وأدقت العظم، أي: جعلته ضعيفا من الجهد."],[38574,"وروى: أرقت، بالراء."],[38575,"والتهويم: أول النوم، والإبان: الوقت."],[38576,"وحي هلا كلمة تعجيل."],[38577,"والحيا مقصور: المطر، والخصب، أي: أتاكم المطر والخصب عاجلا."],[38578,"والوسيط: النسيب، والعظام بضم العين أبلغ من العظيم، وكذلك الجسام أبلغ من الجشيم."],[38579,"والبض: الرقيق البشرة."],[38580,"والأوطف: الطويل، والأشم: المرتفع."],[38581,"وقوله: له فخر يكظم عليه: أي: يخفيه ولا يفاخر به."],[38582,"والسنة: الطريقة."],[38583,"وتهدي إليه، أي: تدل الناس عليه."],[38584,"فليشنوا بالسين والشين أي: فليصبوا."],[38585,"ومعناه: فليغتسلوا."],[38586,"فغثتم، أي: أتاكم الغيث والغوث."],[38587,"ونمت، أي: فشت."],[38588,"وشيبة الحمد: لقب عبد المطلب."],[38589,"وتناهت إليه وفي رواية: تنامت إليه، ومعناهما واحد، أي: جاءوا كلهم، ويعني بقوله: رجالات قريش: رؤساؤهم."],[38590,"ومهله: سكونه."],[38591,"وقوله: كرب، أي قرب والخلة: الحاجة."],[38592,"والعبدي مقصور: العباد."],[38593,"والعذرات: الأفنية."],[38594,"والسنة: القحط والشدة."],[38595,"ويعني بالظلف والخف: الغنم والإبل."],[38596,"والمغدق: الكثير."],[38597,"ومرتعا، أي: ترتع فيه الدواب."],[38598,"واكتظ، أي: ازدحم."],[38599,"والثجيج: سيلان كثرة الماء."],[38600,"والشيخان: المشايخ."],[38601,"والجلة: ذوو الأقدار، اجلوذ أي: تأخر."],[38602,"والجوني: السحاب الأسود، وسحا، أي: منصبا."],[38603,"٦٩٢٨ - رقية بنت ثابت بن خالد"],[38604,"رقية بنت ثابت بن خالد بن النعمان الأنصارية بايعت النبي صلى الله عليه وآله وسلم. قاله ابن حبيب."],[38605,"٦٩٢٩ - رقية بنت رسول الله ﷺ"],[38606,"ب د ع: رقية بنت رسول الله صلى الله عليه وآله وسلم أمها خديجة بنت خويلد رضي الله عنهما."],[38607,"روى الزبير بن بكار، عن عمه مصعب بن عبد الله، أن خديجة ولدت لرسول الله صلى الله عليه وآله وسلم فاطمة، وزينب، ورقية، وأم كلثوم."],[38608,"وروى أيضا عن ابن لهيعة، عن أبي الأسود، أن خديجة ولدت للنبي صلى الله عليه وآله وسلم زينب، ورقية، وفاطمة، وأم كلثوم."],[38609,"وروى محمد بن فضالة، قال: سمعت أن خديجة ولدت للنبي صلى الله عليه وآله وسلم زينب، وأم كلثوم، وفاطمة، ورقية، وقيل: إن فاطمة أصغرهن عليهن السلام."],[38610,"وقال أبو عمر: لا أعلم خلافا أن زينب أكبر بنات رسول الله صلى الله عليه وآله وسلم. واختلف فيمن بعدها."],[38611,"وكان رسول الله صلى الله عليه وآله وسلم قد زوج ابنته رقية من عتبة بن أبي لهب، وزوج أختها أم كلثوم عتيبة بن أبي لهب، فلما نزلت سورة «تبت»، قال لهما أبوهما أبو لهب، وأمهما أم جميل بنت حرب بن أمية حمالة الحطب: فارقا ابنتي محمد."],[38612,"ففارقاهما قبل أن يدخلا بهما كرامة من الله تعالى لهما وهوانا لابني أبي لهب."],[38613,"فتزوج عثمان بن عفان رقية بمكة، وهاجرت معه إلى الحبشة، وولدت له هناك ولدا، فسماه عبد الله."],[38614,"وكان عثمان يكنى به، فبلغ الغلام ست سنين: فنقر عينه ديك، فورم وجهه ومرض ومات، وكان موته في جمادى الأولى سنة أربع، وصلى عليه رسول الله صلى الله عليه وآله وسلم ونزل أبوه عثمان في حفرته."],[38615,"وقال قتادة: إن رقية لم تلد من عثمان ولدا."],[38616,"وهذا ليس بصحيح، إنما أختها أم كلثوم لم تلد من عثمان، وكان تزوجها بعد رقية، وهذا يدل على أن رقية أكبر من أم كلثوم."],[38617,"ولما سار رسول الله صلى الله عليه وآله وسلم إلى بدر كانت ابنته رقية مريضة، فتخلف عليها عثمان بأمر رسول الله صلى الله عليه وآله وسلم له بذلك، فتوفيت يوم وصول زيد بن حارثة مبشرا بظفر رسول الله صلى الله عليه وآله وسلم بالمشركين، وكانت قد أصابتها الحصبة، فماتت بها، وقيل: ماتت قبل وصول زيد ودفنت عند ورود زيد، فبينما هم يدفنونها سمع الناس التكبير، فقال عثمان: ما هذا التكبير؟ فنظروا فإذا زيد على ناقة رسول الله صلى الله عليه وآله وسلم الجدعاء بشيرا بقتلى بدر والغنيمة، وضرب رسول الله صلى الله عليه وآله وسلم لعثمان بسهمه وأجره، لا خلاف بين أهل السير في ذلك."],[38618,"وقال قتادة: حدثني النضر بن أنس، عن أبيه أنس، قال: خرج عثمان مهاجرا إلى أرض الحبشة، ومعه زوجه رقية بنت رسول الله صلى الله عليه وآله وسلم فاحتبس خبرهم عن النبي صلى الله عليه وآله وسلم فكان يخرج فيسأل عن أخبارهما، فجاءته امرأة فأخبرته أنها رأتهما، فقال النبي صلى الله عليه وآله وسلم: «صحبهما الله، إن عثمان أول من هاجر بأهله بعد لوط عليه السلام»."],[38619,"أخرجها الثلاثة."],[38620,"٦٩٣٠ - رقية بنت كعب الأسلمية"],[38621,"رقية بنت كعب الأسلمية قيل: لها صحبة."],[38622,"روى سفيان بن حمزة، عن أشياخه عنها."],[38623,"قاله الأمير أبو نصر بن ماكولا."],[38624,"٦٩٣١ - رملة بنت الحارث"],[38625,"رملة بنت الحارث بن ثعلبة بن الحارث بن زيد الأنصارية النجارية"],[38626,"أخبرنا أبو جعفر، بإسناده عن يونس بن بكير، عن ابن إسحاق، قال: ثم استنزلوا يعني: بني قريظة لما حكم سعد بن معاذ فيهم، فحبسوا في دار رملة بنت الحارث، امرأة من الأنصار من بني النجار"],[38627,"وذكرها ابن حبيب فيمن بايع رسول الله صلى الله عليه وآله وسلم من الأنصار."],[38628,"٦٩٣٢ - رملة بنت أبي سفيان"],[38629,"ب د ع: رملة بنت أبي سفيان صخر بن حرب بن أمية بن عبد شمس أم حبيبة القرشية الأموية أم المؤمنين زوج رسول الله صلى الله عليه وآله وسلم ورضي عنها."],[38630,"وأمها صفية بنت أبي العاص عمة عثمان بن عفان بن أبي العاص."],[38631,"قيل: اسمها رملة، وقيل: هند."],[38632,"اسلمت قديما بمكة، وهاجرت إلى الحبشة مع زوجها عبيد الله بن جحش، فتنصر بالحبشة."],[38633,"ومات بها، وأبت هي أن تتنصر، وثبتت على إسلامها، فتزوجها رسول الله صلى الله عليه وآله وسلم وهي بالحبشة زوجها منه عثمان بن عفان، وقيل: عقد عليها خالد بن سعيد بن العاص بن أمية، وأمهرها النجاشي عن رسول الله صلى الله عليه وآله وسلم أربعمائة دينار، وأولم عليها عثمان لحما، وقيل: أولم عليها النجاشي، وحملها شرحبيل ابن حسنة إلى المدينة."],[38634,"وقد قيل: إن رسول الله صلى الله عليه وآله وسلم تزوجها وهي بالمدينة."],[38635,"روى مسلم بن الحجاج في صحيحه، أن أبا سفيان طلب من النبي صلى الله عليه وآله وسلم أن يتزوجها فأجابه إلى ذلك."],[38636,"وهذا مما يعد من أوهام مسلم، لأن رسول الله صلى الله عليه وآله وسلم كان قد تزوجها وهي بالحبشة قبل إسلام أبي سفيان، لم يختلف أهل السير في ذلك."],[38637,"ولما جاء أبو سفيان إلى المدينة قبل الفتح، لما أوقعت قريش بخزاعة، ونقضوا عهد رسول الله صلى الله عليه وآله وسلم فخاف، فجاء إلى المدينة ليجدد العهد، فدخل على ابنته أم حبيبة، فلم تتركه يجلس على فراش رسول الله صلى الله عليه وآله وسلم وقالت: أنت مشرك."],[38638,"وقال قتادة: لما عادت من الحبشة مهاجرة إلى المدينة خطبها رسول الله صلى الله عليه وآله وسلم فتزوجها."],[38639,"وكذلك روى الليث، عن عقيل، عن ابن شهاب."],[38640,"وروى معمر، عن الزهري: أن رسول الله صلى الله عليه وآله وسلم تزوجها وهي بالحبشة."],[38641,"وهو أصح."],[38642,"ولما بلغ الخبر إلى أبي سفيان، أن رسول الله صلى الله عليه وآله وسلم نكح أم حبيبة ابنته، قال: «ذلك الفحل، لا يقدع أنفه»."],[38643,"وتزوجها رسول الله صلى الله عليه وآله وسلم سنة ست، وتوفيت سنة أربع وأربعين، وقيل: إن رسول الله صلى الله عليه وآله وسلم أرسل عمرو بن أمية الضمري إلى النجاشي يخطب أم حبيبة، فزوجها إياه."],[38644,"وروى الزبير بن بكار، قال: حدثني محمد بن الحسن، عن عبد الله بن عمرو بن زهير، عن إسماعيل بن عمرو، أن أم حبيبة، قالت: «ما شعرت وأنا بأرض الحبشة إلا برسول النجاشي جارية، فاستأذنت فأذنت لها، فقالت: إن الملك يقول لك: إن رسول الله صلى الله عليه وآله وسلم كتب إلي أن أزوجكيه، فقلت: بشرك الله بخير، فقالت: يقول الملك: وكلى من يزوجك."],[38645,"فأرسلت إلى خالد بن سعيد، فوكلته، فأمر النجاشي جعفر بن أبي طالب ومن هناك من المسلمين يحضرون، وخطب النجاشي، وقال: إن رسول الله صلى الله عليه وآله وسلم كتب إلي أن أزوجه أم حبيبة بنت أبي سفيان، فأجبت إلى ما دعا إليه رسول الله صلى الله عليه وآله وسلم وزوجته أم حبيبة، فبارك الله لرسوله."],[38646,"ودفع النجاشي الدنانير إلى خالد»."],[38647,"وروت عن النبي صلى الله عليه وآله وسلم روى عنها أخوها معاوية بن أبي سفيان، وكان سألها: هل كان النبي صلى الله عليه وآله وسلم يصلي في الثوب الذي يجامع فيه؟ قالت: نعم، إذا لم ير فيه أذى."],[38648,"وروى عنها غيره:"],[38649,"أخبرنا إبراهيم بن محمد، وغيره، قالوا: بإسنادهم عن أبي عيسى الترمذي، حدثنا علي ابن حجر، أخبرنا يزيد بن هارون، عن محمد بن عبد الله الشعيثي، عن أبيه، عن عنبسة بن أبي سفيان، عن أم حبيبة، قالت: قال رسول الله صلى الله عليه وآله وسلم: «من صلى قبل الظهر أربعا وبعده أربعا، حرمه الله عز وجل على النار»."],[38650,"أخرجه الثلاثة"],[38651,"٦٩٣٣ - رملة بنت شيبة"],[38652,"ب: رملة بنت شيبة بن ربيعة بن عبد شمس القرشية العبشمية وهي ابنة عم هند بنت عتبة بن ربيعة، وابنة عم أبي حذيفة بن عتبة."],[38653,"أسلمت قديما، وهاجرت إلى المدينة مع زوجها عثمان بن عفان."],[38654,"أخرجها أبو عمر."],[38655,"وعندي فيه نظر، فإن قوله هاجرت إلى المدينة مع زوجها عثمان، فإن عثمان هاجر إلى الحبشة، ثم إلى المدينة ومعه زوجته رقية بنت رسول الله صلى الله عليه وآله وسلم ثم بعدها تزوج أم كلثوم بنت رسول الله صلى الله عليه وآله وسلم فلو لم يقل: هاجرت مع زوجها عثمان لكان الصواب، فإنها هاجرت، ثم تزوجها عثمان، والله أعلم، وقيل: اسمها رميلة، قاله الزبير."],[38656,"ولما أسلمت، قالت ابنة عمها هند بنت عتبة تعيب عليها دخولها في الإسلام، وتعيرها بقتل أبيها شيبة يوم بدر:"],[38657,"لحا الرحمن صابئة بوج … ومكة أو بأطراف الحجون"],[38658,"تدين لمعشر قتلوا أباها … أقتل أبيك جاءك باليقين؟!"],[38659,"وأم رملة بنت شيبة: أم شراك بنت وقدان بن عبد شمس بن عبد ود بن نصر، من بني عامر بن لؤي."],[38660,"٦٩٣٤ - رملة بنت عبد الله بن أبي ابن سلول"],[38661,"رملة بنت عبد الله بن أبي ابن سلول الأنصارية ثم من بلحبلى."],[38662,"أبوها رأس المنافقين."],[38663,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[38664,"٦٩٣٥ - رملة بنت أبي عوف"],[38665,"ب ع س: رملة بنت أبي عوف بن صبيرة بن سعيد بن سعد بن سهم وهي ابنة أخي أبي وداعة بن صبيرة السهمي."],[38666,"روى زياد بن عبد الله البكائي، عن محمد بن إسحاق، في تسمية من أسلم بمكة: المطلب بن أزهر بن عوف الزهري، وامرأته رملة بنت أبي عوف بن صبيرة."],[38667,"وهاجرا كلاهما إلى أرض الحبشة، وولدت له هناك عبد الله بن المطلب."],[38668,"وكان يقال إنه لأول رجل ورث أباه في الإسلام."],[38669,"أخرجه أبو نعيم، وأبو عمر، وأبو موسى."],[38670,"٦٩٣٦ - رملة بنت الوقيعة"],[38671,"س: رملة بنت الوقيعة بن حرام بن غفار الغفارية وهي أم أبي ذر، قاله خليفة بن خياط."],[38672,"وسماها أبو نعيم، وجعفر، وغيرهما، وورد إسلامها في قصة إسلام أبي ذر، ولم تسم في الحديث، وقيل: هي أم عمرو بن عبسة أيضا."],[38673,"أخرجها أبو موسى."],[38674,"٦٩٣٧ - رميثة بنت حكيم"],[38675,"س: رميثة بنت حكيم."],[38676,"روى الليث بن سعد، عن يزيد بن أبي حبيب حديثا لها عن رسول الله صلى الله عليه وآله وسلم وهو مرسل إنما هي تابعية تروي عن عائشة."],[38677,"قاله أبو موسى."],[38678,"٦٩٣٨ - رميثة بنت عمرو بن هاشم"],[38679,"ب د ع: رميثة بنت عمرو بن هاشم بن عبد المطلب بن عبد مناف جدة عاصم بن عمر بن قتادة، وهي أم حكيم والد القعقاع."],[38680,"قاله أبو عمر."],[38681,"وقال أبو نعيم: رميثة الأنصارية."],[38682,"أخبرنا الحسين بن يوحن بن أتوية بن النعمان الباوري وعثمان بن أبي علي، قالا: أخبرنا أبو الفضل محمد بن عبد الواحد النيلي الأصفهاني، أخبرنا أبو القاسم أحمد بن منصور الخليلي، أخبرنا أبو القاسم علي بن أحمد الخزاعي، حدثنا أبو سعيد الهيثم بن كليب، حدثنا محمد بن عيسى بن سورة، حدثنا أبو مصعب المدني، حدثنا يوسف بن الماجشون، عن أبيه، عن عاصم بن عمر بن قتادة، عن جدته رميثة، قالت: سمعت رسول الله صلى الله عليه وآله وسلم ولو أشاء أن أقبل الخاتم الذي بين كتفيه من قربه، لفعلت يقول لسعد بن معاذ يوم مات: «اهتز له عرش الرحمن»."],[38683,"أخرجه الثلاثة، وقد رواه جماعة عن يوسف بن الماجشون، عن عاصم بن عمر"],[38684,"٦٩٣٩ - الرميصاء أم أنس بن مالك"],[38685,"د ع: الرميصاء وقيل الغميصاء وهي أم أنس بن مالك."],[38686,"روت عنها عائشة، وأم سلمة، وابنها أنس بن مالك، وغيرهم."],[38687,"وهي امرأة أبي طلحة، وهي بكنيتها أشهر، وكنيتها أم سليم."],[38688,"أخبرنا أبو الفضل المخزومي الفقيه، بإسناده عن أبي يعلى، حدثنا صالح بن مالك، حدثنا عبد العزيز بن أبي سلمة، عن محمد بن المنكدر، عن جابر، قال: قال رسول الله صلى الله عليه وآله وسلم: «أريت أني دخلت الجنة، فإذا أنا بالرميصاء امرأة أبي طلحة»."],[38689,"أخرجها ابن منده، وأبو نعيم"],[38690,"٦٩٤٠ - الرميصاء"],[38691,"د ع: الرميصاء وقيل الغميصاء شكت زوجها إلى النبي صلى الله عليه وآله وسلم."],[38692,"روى سليمان بن يسار، عن عبيد الله بن العباس، قال: جاءت الرميصاء أو الغميصاء إلى رسول الله صلى الله عليه وآله وسلم تشكو زوجها، وتزعم أنه لا يصل إليها."],[38693,"فما كان إلا يسيرا حتى جاء زوجها، فزعم أنها كاذبة، ولكنها تريد أن ترجع إلى زوجها الأول، فقال لها رسول الله صلى الله عليه وآله وسلم: «ليس لك ذلك حتى يذوق عسيلتك رجل غيره»."],[38694,"أخرجها ابن منده، وأبو نعيم."],[38695,"٦٩٤١ - روضة"],[38696,"ب د ع: روضة أسلمت بالمدينة."],[38697,"كانت مولاة لامرأة من أهل المدينة أسلمت هي ومولاتها عند قدوم النبي صلى الله عليه وآله وسلم المدينة."],[38698,"أخبرنا يحيى بن محمود، إجازة، بإسناده عن ابن أبي عاصم، حدثنا عبد الجليل بن الحارث بن عبد الله بن عبيد الأنصاري أبو صالح، حدثتني شيبة بنت الأسود، حدثتني روضة: «أنها كانت وصيفة لامرأة من أهل المدينة، فلما هاجر رسول الله صلى الله عليه وآله وسلم إلى المدينة، قالت لي مولاتي: يا روضة، قومي على باب الدار، فإذا مر هذا الرجل تعني النبي صلى الله عليه وآله وسلم فأعلميني."],[38699,"قالت: فقمت على باب الدار، فإذا هو قدم ومعه نفر من أصحابه، فأخذت بطرف من ردائه، فتبسم في وجهي، قالت: وأظنها، قالت: مسح يده على رأسي فقلت لمولاتي: يا هذه، هو ذا قد جاء هذا الرجل تعني النبي صلى الله عليه وآله وسلم فخرجت مولاتي ومن كان معها في الدار، فعرض عليهم الإسلام فأسلموا»."],[38700,"أخرجها الثلاثة"],[38701,"٦٩٤٢ - ريحانة سرية رسول الله ﷺ"],[38702,"ب س: ريحانة سرية رسول الله صلى الله عليه وآله وسلم وهي ريحانة بنت شمعون بن زيد بن قثامة من بني قريظة، وقيل: من بني النضير."],[38703,"والأول أكثر، قاله أبو عمر."],[38704,"وقال ابن إسحاق: ريحانة بنت عمرو بن خنافة، إحدى نساء بني عمرو بن قريظة."],[38705,"ماتت قبل وفاة النبي صلى الله عليه وآله وسلم قيل: ماتت سنة عشر لما رجع رسول الله صلى الله عليه وآله وسلم من حجة الوداع."],[38706,"وأخبرنا أبو جعفر، بإسناده عن يونس، عن ابن إسحاق، أن النبي صلى الله عليه وآله وسلم توفي عنها وهي في ملكه."],[38707,"وكان رسول الله صلى الله عليه وآله وسلم عرض عليها أن يتزوجها ويضرب عليها الحجاب، فقالت: يا رسول الله، بل تتركني في ملكك، فهو أخف علي وعليك، فتركها، وكانت حين سباها قد تعصت بالإسلام وأبت إلا اليهودية، فوجد رسول الله صلى الله عليه وآله وسلم في نفسه، فبينما هو مع أصحابه، إذ سمع وقع نعلين خلفه، فقال: «هذا ثعلبة بن سعية يبشرني بإسلام ريحانة» فبشره بإسلامها."],[38708,"أخرجها أبو عمر، وأبو موسى."],[38709,"وقال أبو موسى: ريحانة بنت عمرو، سرية رسول الله صلى الله عليه وآله وسلم ذكرها الحافظ أبو عبد الله يعني: ابن منده في ترجمة مارية، ولم يترجم لها، ويقال: ربيحة"],[38710,"٦٩٤٣ - ريطة بنت عبد الله"],[38711,"ب د ع: ريطة بنت عبد الله بن معاوية الثقفية امرأة عبد الله بن مسعود ويقال: رائطة."],[38712,"قيل: إنها زينب، وأن رائطة لقب لها، وقيل: ريطة زوجة أخرى له، وهي أم ولده."],[38713,"أخبرنا يحيى، إجازة، بإسناده عن ابن أبي عاصم، حدثنا محمد بن إسماعيل، حدثنا ابن أبي أويس، أخبرني ابن أبي الزناد، عن أبيه، عن عروة بن الزبير، عن عبيد الله بن عبد الله، عن رائطة امرأة عبد الله بن مسعود أم ولده وكانت امرأة صناعا، وليس لعبد الله بن مسعود مال، فكانت تنفق عليه وعلى ولده من ثمن صنعتها فقالت: والله لقد شغلتني أنت وولدك عن الصدقة! فقال: ما أحب إن لم يكن لك أجر أن تفعلي."],[38714,"فسألت رسول الله صلى الله عليه وآله وسلم فقالت: إني امرأة ذات صنعة فأبيع، وليس لي ولا لوالدي ولا لزوجي شيء، ويشغلونني فلا أتصدق، فهل لي في النفقة عليهم من أجر؟ فقال: «لك في ذلك أجر ما أنفقت عليهم، فأنفقي عليهم»."],[38715,"أخرجه الثلاثة قلت: وهذه القصة قد وردت عن زينب الثقافية امرأة عبد الله مسعود، ويرد الحديث في زينب إن شاء الله تعالى."],[38716,"وروي عن عروة، عن عبد الله بن عبد الله الثقفي، عن أخته رائطة، وروى عن عروة، عن ريطة."],[38717,"٦٩٤٤ - ريطة بنت منبه"],[38718,"د ع: ريطة بنت منبه بن الحجاج السهمية أم عبد الله بن عمرو بن العاص."],[38719,"وأمها زينب بنت وائل بن هشام بن سعيد بن سهم."],[38720,"أسلمت وبايعت، لها ذكر وليس لها حديث."],[38721,"أخرجها ابن منده، وأبو نعيم."],[38722,"حرف الزاي"],[38723,"٦٩٤٥ - زائدة مولاة عمر بن الخطاب"],[38724,"س: زائدة وقيل زيدة مولاة عمر بن الخطاب"],[38725,"أخبرنا أبو موسى، إذنا، أخبرنا أبو بكر محمد بن أبي نصر اللفتواني، أخبرنا أبو حفص السمسار، أخبرنا أبو سعيد النقاش، أخبرنا أبو يعلى الحسين بن محمد الزبيري، حدثني أبو بكر محمد بن حمدون بن خالد، حدثنا الفضل بن يزيد بن الفضل، حدثني بشر بن بكر، حدثنا الأوزاعي، عن واصل، عن أم نجيح كذا قال، قالت عائشة: كنت قاعدة عند النبي صلى الله عليه وآله وسلم إذ أقبلت زيدة جارية عمر بن الخطاب، وكانت من المجتهدات في العبادة، وكان النبي صلى الله عليه وآله وسلم يدنيها لما يعلم منها، فقالت: السلام عليك ورحمة الله يا رسول الله، كنت عجنت عجينا لأهلي، فخرجت لأحتطب، فإذا أنا برجل نقي الثياب طيب الريح، كأن وجهه القمر ليلة البدر، على فرس أغر محجل، فدنا مني، وقال: السلام عليك يا زائدة."],[38726,"فقلت: وعليك السلام."],[38727,"قال: هل أنت مبلغة عني ما أقول؟ قلت: نعم، إن شاء الله عز وجل فقال: إذا لقيت محمدا فقولي: إني لقيت الخضر، وهو يقرئك السلام."],[38728,"وذكر الحديث في فضل النبي صلى الله عليه وآله وسلم وأمته."],[38729,"أخرجه أبو موسى"],[38730,"٦٩٤٦ - زجاء"],[38731,"زجاء."],[38732,"روى عنها ابن سيرين قالت: كنت عند النبي صلى الله عليه وآله وسلم فجاءته امرأة بابن لها، وقيل: رجاء، بالراء."],[38733,"وقد تقدمت في حرف الراء."],[38734,"٦٩٤٧ - زرينة"],[38735,"س: زرينة والدة أمة الله قيل رزينة بتقديم الراء على الزاي، وقد تقدم ذكرها."],[38736,"أخبرنا يحيى، كتابة، بإسناده إلى ابن أبي عاصم: أخبرنا عقبة بن مكرم، حدثنا محمد بن موسى، حدثتني عليلة بنت الكميت العتكية، حدثتني أمي، عن أمة الله، قالت:"],[38737,"سألت زرينة ما كان رسول الله صلى الله عليه وآله وسلم يقول في صوم يوم عاشوراء؟ فقالت: «إن كان ليصومه ويأمر بصيامه»."],[38738,"أخرجها أبو موسى"],[38739,"٦٩٤٨ - زنيرة الرومية"],[38740,"ب د ع: زنيرة الرومية كانت من السابقات إلى الإسلام، أسلمت في أول الإسلام، وعذبها المشركون، وقيل: كانت مولاة بني مخزوم، فكان أبو جهل يعذبها، وقيل: كانت مولاة بني عبد الدار، فلما أسلمت عميت، فقال المشركون: أعمتها اللات والعزى لكفرها بهما! فقالت: وما يدري اللات والعزى من يعبدهما، إنما هذا من السماء، وربي قادر على رد بصري، فأصبحت من الغد وقد رد الله بصرها، فقالت قريش: هذا من سحر محمد."],[38741,"ولما رأى أبو بكر رضي الله عنه ما ينالها من العذاب، اشتراها فأعتقها، وهي أحد السبعة الذين أعتقهم أبو بكر."],[38742,"أخرجها الثلاثة."],[38743,"زنيرة: بكسر الزاي، والنون المشددة، وتسكين الياء تحتها نقطتان، وآخره راء، ثم هاء."],[38744,"٦٩٤٩ - زينب الأسدية"],[38745,"ب د ع: زينب الأسدية، مكية."],[38746,"روى أبو الزبير، عن مجاهد، عن زينب الأسدية، قالت: أتيت رسول الله صلى الله عليه وآله وسلم فقلت: يا رسول الله، إن أبي مات وترك جارية، فولدت غلاما، وإنا كنا نتهمها، فقال: «ائتوني به»."],[38747,"فلما أتوه به نظر إليه، فقال لها: «إن الميراث له، وأما أنت فاحتجبي منه»."],[38748,"أخرجها الثلاثة."],[38749,"٦٩٥٠ - زينب بنت أسعد بن زرارة"],[38750,"س: زينب بنت أسعد بن زرارة الأنصارية وكنية أسعد أبو أمامة كانت هي وأختاها فريعة وأخرى في حجر رسول الله صلى الله عليه وآله وسلم أوصى بهن أبوهن إلى رسول الله صلى الله عليه وآله وسلم فكان يحليهن الرعاث من الذهب، وقيل: اسم ابنتي أبي أمامة: حبيبة وكبشة، وأما الفريعة فأمهما، والله أعلم."],[38751,"أخرجها أبو موسى."],[38752,"٦٩٥١ - زينب الأنصارية"],[38753,"ب: زينب الأنصارية امرأة أبي مسعود الأنصاري روى علقمة، عن عبد الله، أن زينب الأنصارية امرأة أبي مسعود وزينب الثقفية أتتا رسول الله صلى الله عليه وآله وسلم تسألانه عن النفقة على أزواجهما."],[38754,"الحديث، وهو أيضا مذكور من حديث الأعمش، عن أبي وائل، عن عمرو بن الحارث بن المصطلق، عن ابن أخي زينب امرأة عبد الله بن مسعود، عن زينب امرأة عبد الله بن مسعود، قالت: انطلقت إلى رسول الله صلى الله عليه وآله وسلم فإذا امرأة من الأنصار حاجتها حاجتي، اسمها زينب."],[38755,"فذكر الحديث في النفقة على أزواجهما وأيتام في حجورهما، فقال لهما رسول الله صلى الله عليه وآله وسلم: «نعم، لكما أجران: أجر الصدقة، وأجر القرابة»."],[38756,"أخرجها أبو عمر."],[38757,"٦٩٥٢ - زينب التميمية"],[38758,"ب: زينب التميمية حديثها عن النبي صلى الله عليه وآله وسلم أنه كره أن يفضل الذكور من البنين على الإناث في العطية."],[38759,"أخرجها أبو عمر مختصرا."],[38760,"٦٩٥٣ - زينب بنت ثابت بن قيس"],[38761,"زينب بنت ثابت بن قيس بن شماس الأنصارية من بلحارث بن الخزرج."],[38762,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[38763,"٦٩٥٤ - زينب بنت جابر"],[38764,"س: زينب بنت جابر الأحمسية كانت في زمان النبي صلى الله عليه وآله وسلم وحدثت عن أبي بكر، روى عنها عبد الله بن جابر الأحمسي وهي عمته كذا قاله ابن منده في التاريخ، وقيل: هي بنت المهاجر بن جابر."],[38765,"ويشبه أن تكون بنت نبيط بن جابر، امرأة أنس بن مالك، لأنها من أحمس."],[38766,"أخرجها أبو موسى كذا مختصرا."],[38767,"قلت: قد أخرجها ابن منده في المعرفة فقال: زينب بنت جابر الأحمسية، وروى لها حديث محمد بن عمارة، عن زينب بنت نبيط، وهو مذكور في زينب بنت نبيط، فليس لاستدراكه وجه، والله أعلم."],[38768,"٦٩٥٥ - زينب بنت جحش"],[38769,"ب د ع: زينب بنت جحش زوج النبي صلى الله عليه وآله وسلم أخت عبد الله بن جحش."],[38770,"وهي أسدية من أسد بن خزيمة، وأمها أميمة بنت عبد المطلب، عمة النبي صلى الله عليه وآله وسلم."],[38771,"وقد تقدم نسبها عند ذكر أخيها، وتكنى أم الحكم."],[38772,"وكانت قديمة الإسلام، ومن المهاجرات وكانت قد تزوجها زيد بن حارثة، مولى النبي صلى الله عليه وآله وسلم تزوجها ليعلمها كتاب الله وسنة رسوله، ثم إن الله تعالى زوجها النبي صلى الله عليه وآله وسلم من السماء، وأنزل الله تعالى ﴿وَإِذْ تَقُولُ لِلَّذِي أَنْعَمَ اللَّهُ عَلَيْهِ وَأَنْعَمْتَ عَلَيْهِ أَمْسِكْ عَلَيْكَ زَوْجَكَ وَاتَّقِ اللَّهَ وَتُخْفِي فِي نَفْسِكَ مَا اللَّهُ مُبْدِيهِ وَتَخْشَى النَّاسَ وَاللَّهُ أَحَقُّ أَنْ تَخْشَاهُ فَلَمَّا قَضَى زَيْدٌ مِنْهَا وَطَرًا زَوَّجْنَاكَهَا﴾."],[38773,"الآية."],[38774,"فتزوجها رسول الله صلى الله عليه وآله وسلم سنة ثلاثة من الهجرة، قاله أبو عبيدة."],[38775,"وقال قتادة: سنة خمس."],[38776,"وقال ابن إسحاق: تزوجها رسول الله صلى الله عليه وآله وسلم بعد أم سلمة."],[38777,"أخبرنا عبد الوهاب بن هبة الله، أخبرنا أبو غالب بن البناء، أخبرنا أبو محمد الجوهري، أخبرنا أبو بكر القطيعي، أخبرنا محمد بن يونس، حدثنا حبان بن هلال، حدثنا سليمان بن المغيرة، عن ثابت، عن أنس قال: لما انقضت عدة زينب بنت جحش قال رسول الله صلى الله عليه وآله وسلم لزيد بن حارثة: «اذهب فاذكرني لها»."],[38778,"قال زيد: فلما قال لي رسول الله صلى الله عليه وآله وسلم ذلك، عظمت في عيني، فذهبت إليها، فجعلت ظهري إلى الباب، فقلت: يا زينب، بعث بي رسول الله صلى الله عليه وآله وسلم يذكرك؟ فقالت: ما كنت لأحدث شيئا حتى أؤامر ربي عز وجل."],[38779,"فقامت إلى مسجدها، وأنزل الله هذه الآية ﴿فَلَمَّا قَضَى زَيْدٌ مِنْهَا وَطَرًا زَوَّجْنَاكَهَا﴾ فجعل رسول الله صلى الله عليه وآله وسلم يدخل عليها بغير إذن أخبرنا أبو محمد عبد الله بن علي بن سويدة، بإسناده عن علي بن أحمد، قال: أخبرنا أبو عبد الرحمن محمد بن عبد العزيز الفقيه، حدثنا محمد بن الفضل بن محمد السلمي، أخبرنا أبي، حدثنا أبو أحمد محمد بن عبد الوهاب، حدثنا الحسين بن الوليد، عن عيسى بن طهمان، عن أنس بن مالك، قال: «كانت زينب بنت جحش تفخر على نساء النبي صلى الله عليه وآله وسلم وتقول: زوجني الله من السماء."],[38780,"وأولم عليها رسول الله صلى الله عليه وآله وسلم بخبز ولحم، وكانت زينب كثيرة الخير والصدقة، ولما دخلت على رسول الله صلى الله عليه وآله وسلم كان اسمها برة فسماها زينب، وتكلم المنافقون في ذلك وقالوا: إن محمدا يحرم نكاح نساء الأولاد، وقد تزوج امرأة ابنه زيد، لأنه كان يقال له: زيد بن محمد، قال الله تعالى: ﴿مَا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِنْ رِجَالِكُمْ﴾، وقال: ﴿ادْعُوهُمْ لآبَائِهِمْ هُوَ أَقْسَطُ عِنْدَ اللَّهِ﴾، فكان يدعى زيد بن حارثة."],[38781,"وهجرها رسول الله صلى الله عليه وآله وسلم وغضب عليها لما قالت لصفية بنت حيي: تلك اليهودية، فهجرها ذا الحجة والمحرم وبعض صفر، وعاد إلى ما كان عليه، وقيل: إن التي قالت لها ذلك حفصة."],[38782,"وقالت عائشة: لم يكن أحد من نساء النبي صلى الله عليه وآله وسلم تساميني في حسن المنزلة عنده إلا زينب بنت جحش."],[38783,"وكانت تفخر على نساء النبي صلى الله عليه وآله وسلم وتقول: إن آباءكن أنكحوكن وإن الله أنكحني إياه."],[38784,"وبسببها أنزل الحجاب."],[38785,"وكانت امرأة صناع اليد، تعمل بيدها، وتتصدق في سبيل الله»"],[38786,"أخبرنا أبو الفضل بن أبي الحسن الفقيه، بإسناده إلى أبي يعلى، حدثنا هارون بن عبد الله، عن ابن فديك، حدثنا ابن أبي ذئب، حدثني صالح مولى التوءمة، عن أبي هريرة رضي الله عنه، أن رسول الله صلى الله عليه وآله وسلم قال للنساء عام حجة الوداع: «هذه ثم ظهور الحصر»."],[38787,"قال: فكن كلهن يحججن إلا سودة وزينب بنت جحش، فإنهما كانتا تقولان: والله لا تحركنا دابة بعد إذ سمعنا من رسول الله صلى الله عليه وآله وسلم"],[38788,"أخبرنا يحيى وأبو ياسر، بإسنادهما عن مسلم، قال: حدثنا محمود بن غيلان، حدثنا الفضل بن موسى السيناني، أخبرنا طلحة بن يحيى بن طلحة، عن عائشة بنت طلحة، عن عائشة أم المؤمنين، قالت: قال رسول الله صلى الله عليه وآله وسلم: «أسرعكن لحوقا بي أطولكن يدا»."],[38789,"قالت:"],[38790,"فكنا نتطاول أينا أطول يدا، قالت: فكانت زينب أطولنا يدا لأنها كانت تعمل بيدها، وتتصدق."],[38791,"وقالت عائشة: «ما رأيت امرأة قط خيرا في الدين من زينب، وأتقى لله، وأصدق حديثا، وأوصل للرحم، وأعظم أمانة وصدقة». وروى شهر بن حوشب، عن عبد الله بن شداد، أن رسول الله صلى الله عليه وآله وسلم قال لعمر بن الخطاب: «إن زينب بنت جحش لأواهة»، فقال رجل: يا رسول الله، ما الأواه؟ قال: «المتخشع المتضرع»."],[38792,"وكانت أول نساء رسول الله صلى الله عليه وآله وسلم لحوقا به كما أخبر رسول الله صلى الله عليه وآله وسلم وتوفيت سنة عشرين."],[38793,"أرسل إليها عمر بن الخطاب اثني عشر ألف درهم، كما فرض لنساء النبي صلى الله عليه وآله وسلم فأخذتها وفرقتها في ذوي قرابتها وأيتامها، ثم قالت: اللهم لا يدركني عطاء لعمر بن الخطاب بعد هذا! فماتت، وصلى عليها عمر بن الخطاب، ودخل قبرها أسامة بن زيد، ومحمد بن عبد الله بن جحش، وعبد الله بن أحمد بن جحش قيل: هي أول امرأة صنع لها النعش."],[38794,"ودفنت بالبقيع."],[38795,"أخرجها الثلاثة."],[38796,"٦٩٥٦ - زينب بنت الحارث"],[38797,"ب س: زينب ابنة الحارث بن خالد بن صخر القرشية التميمية من بني تيم بن مرة."],[38798,"ولدت بأرض الحبشة مع أختها عائشة، وفاطمة، أمهن رائطة بنت الحارث بن جبيلة."],[38799,"هلكت هي وأخوها موسى وأختها عائشة من ماء شربوه في الطريق، وقدمت فاطمة على رسول الله صلى الله عليه وآله وسلم ولم يبق من ولد رائطة غيرها."],[38800,"روى ذلك عن ابن إسحاق."],[38801,"أخرجه أبو عمر، وأبو موسى."],[38802,"٦٩٥٧ - زينب بنت الحباب"],[38803,"زينب بنت الحباب بن الحارث الأنصارية من بني مازن."],[38804,"بايعت رسول الله صلى الله عليه وآله وسلم."],[38805,"قاله ابن حبيب."],[38806,"٦٩٥٨ - زينب بنت حميد"],[38807,"د ع: زينب بنت حميد بن زهير بن الحارث بن أسد بن عبد العزى القرشية الأسدية أم عبد الله بن هشام."],[38808,"أخبرنا أبو ياسر، بإسناده عن عبد الله بن أحمد، حدثني أبي، أخبرنا عبد الله بن يزيد، حدثنا سعيد يعني ابن أبي أيوب، حدثني أبو عقيل زهرة بن معبد، عن جده عبد الله بن هشام وكان قد أدرك النبي صلى الله عليه وآله وسلم وذهبت به أمه إلى النبي صلى الله عليه وآله وسلم فقالت: يا رسول الله، بايعه."],[38809,"قال النبي صلى الله عليه وآله وسلم: «هو صغير، فمسح رأسه، ودعا له»."],[38810,"أخرجه ابن منده، وأبو نعيم، إلا أن ابن منده، قال: زينب جدة عبد الله بن هشام، وذكر في الحديث: وذهبت به أمه، فنقض قوله الأول، والصحيح أنها أمه"],[38811,"٦٩٥٩ - زينب بنت حنظلة"],[38812,"ب: زينب بنت حنظلة بن قسامة بن قيس بن عبيد بن طريف بن مالك بن جدعان بن ذهل بن رومان بن جندب بن خارجة بن سعد ابن قطرة من طيء، ولطريف بن مالك يقول امرؤ القيس: لعمري، لنعم المرء يعشو لضوئه طريف بن مال ليلة الريح والحضر كانت هذه زينب تحت أسامة بن زيد بن حارثة، فطلقها، فلما حلت قال رسول الله صلى الله عليه وآله وسلم: «من يتزوج زينب بنت حنظلة وأنا صهره؟» فتزوجها نعيم بن عبد الله بن النحام."],[38813,"وكانت زينب قدمت هي وأبوها وعمتها الجرباء بنت قسامة إلى النبي صلى الله عليه وآله وسلم. أخرجها أبو عمر."],[38814,"٦٩٦٠ - زينب بنت خباب"],[38815,"س: زينب ابنة خباب بن الأرت قال جعفر: سماها البخاري في تسمية من روى عن النبي صلى الله عليه وآله وسلم روى الأعمش، عن أبي إسحاق، عن عبد الرحمن بن زيد الفائشي، عن ابنة خباب، قالت: خرج خباب في سرية وكان رسول الله صلى الله عليه وآله وسلم يتعاهدنا حتى يحلب عنزا لنا في جفنة لنا."],[38816,"أخرجها أبو موسى."],[38817,"٦٩٦١ - زينب بنت خزيمة"],[38818,"ب د ع: زينب بنت خزيمة بن الحارث بن عبد الله بن عمرو بن عبد مناف بن هلال بن عامر بن صعصعة الهلالية زوج النبي صلى الله عليه وآله وسلم يقال لها: أم المساكين، لكثرة إطعامها المساكين وصدقتها عليهم."],[38819,"وكانت تحت عبد الله بن جحش، فقتل عنها يوم أحد، فتزوجها رسول الله صلى الله عليه وآله وسلم وقيل: كانت عند الطفيل بن الحارث بن المطلب بن عبد مناف، ثم خلف عليها أخوه عبيد بن الحارث، قاله أبو عمر عن علي بن عبد العزيز الجرجاني."],[38820,"وقال: كانت أخت ميمونة زوج النبي صلى الله عليه وآله وسلم لأمها."],[38821,"قال أبو عمر: ولم أر ذلك لغيره."],[38822,"وتزوجها رسول الله صلى الله عليه وآله وسلم بعد حفصة."],[38823,"قال أبو عمر: ولم تلبث عند رسول الله صلى الله عليه وآله وسلم إلا يسيرا شهرين أو ثلاثة حتى توفيت، وكانت وفاتها في حياته."],[38824,"لا خلاف فيه."],[38825,"وذكر ابن منده في ترجمتها قول النبي صلى الله عليه وآله وسلم: «أسرعكن لحوقا أبي أطولكن يدا»، فكان نساء النبي صلى الله عليه وآله وسلم يتذارعن أيتهن أطول يدا، فلما توفيت زينب علمن أنها كانت أطولهن يدا في الخير."],[38826,"وهذا عندي وهم، فإنه صلى الله عليه وآله وسلم قال: «أسرعكن لحوقا بي»."],[38827,"وهذه سبقته، إنما أراد أول نسائه تموت بعد وفاته، وقد تقدم في زينب بنت جحش، وهو بها أشبه لأنها كانت أيضا كثيرة الصدقة من عمل يدها، وهي أول نسائه توفيت بعده، والله أعلم."],[38828,"أخرجها الثلاثة."],[38829,"٦٩٦٢ - زينب بنت خناس"],[38830,"زينب بنت خناس"],[38831,"أخبرنا عبيد الله بن السمين، بإسناده عن يونس، عن ابن إسحاق، قال: «وأعطى رسول الله صلى الله عليه وآله وسلم عثمان بن عفان زينب بنت ابن خناس، يعني من سبي هوازان»"],[38832,"وقال ابن إسحاق: فحدثني أبو وجزة، أن عثمان كان قد أصاب جارية، يعني من سبي هوزان فحطت إلى ابن عم لها كان زوجها وكان ساقطا، فلما ردت السبايا فقدم بها المدينة في زمان عمر أو زمان عثمان، فلقيها عثمان وأعطاها شيئا بما كان أصاب منها فلما رأى عثمان زوجها، قال: ويحك! أهذا كان أحب إليك مني؟ قالت: نعم."],[38833,"زوجي وابن عمي"],[38834,"٦٩٦٣ - زينب بنت أبي رافع"],[38835,"د ع: زينب بنت أبي رافع روى إبراهيم بن علي الرافعي، عن جدته زينب بنت أبي رافع، قالت: رأيت فاطمة بنت رسول الله صلى الله عليه وآله وسلم أتت بابنيها إلى رسول الله صلى الله عليه وآله وسلم في شكواه الذي توفي فيه، فقالت: يا رسول الله هذان ابناك فورثهما، فقال: «أما حسن فإن له هيبتي وسؤددي، وأما حسين فإن له جرأتي وجودي»."],[38836,"أخرجه ابن منده، وأبو نعيم."],[38837,"٦٩٦٤ - زينب بنت رسول الله ﷺ"],[38838,"ب د ع: زينب بنت رسول الله صلى الله عليه وآله وسلم هي أكبر بناته، ولدت ولرسول الله صلى الله عليه وآله وسلم ثلاثون سنة، وماتت سنة ثمان في حياة رسول الله صلى الله عليه وآله وسلم. وأمها خديجة بنت خويلد بن أسلم."],[38839,"وقد شذ من لا اعتبار به أنها لم تكن أكبر بناته، وليس بشيء إنما الاختلاف بين القاسم وزينب، أيهما ولد قبل الآخر؟ فقال بعض العلماء بالنسب: أول ولد ولد له القاسم، ثم زينب."],[38840,"وقال ابن الكلبي: زينب ثم القاسم."],[38841,"وهاجرت بعد بدر، وقد ذكرنا ذلك في ترجمة أبي العاص بن الربيع، وفي لقيط، فإن لقيطا اسم أبي العاص."],[38842,"وولدت منه غلاما اسمه علي، فتوفي وقد ناهز الاحتلام، وكان رديف رسول الله صلى الله عليه وآله وسلم يوم الفتح، وولدت له أيضا بنتا اسمها أمامة، وقد تقدم ذكرهما، وأسلم أبو العاص."],[38843,"أخبرنا أبو جعفر، بإسناده عن يونس بن بكير، عن محمد بن إسحاق، قال: حدثني يحيى بن عباد بن عبد الله بن الزبير، عن أبيه، عن عائشة، رضي الله عنها، قالت: «وكان الإسلام قد فرق بين زينب وبين أبي العاص حين أسلمت، إلا أن رسول الله صلى الله عليه وآله وسلم كان لا يقدر على أن يفرق بينهما، وكان رسول الله صلى الله عليه وآله وسلم مغلوبا بمكة، ولا يحل ولا يحرم»."],[38844,"قيل: إن أبا العاص لما أسلم رد عليه رسول الله صلى الله عليه وآله وسلم زينب، فقيل: بالنكاح الأول، وقيل: ردها بنكاح جديد"],[38845,"أخبرنا أبو أحمد عبد الوهاب بن علي بن علي الأمين، أخبرنا أبو الفضل بن ناصر بن علي، أخبرنا الخطيب أبو طاهر محمد بن أحمد بن محمد بن أبي الصقر الأنباري، أخبرنا أبو البركات أحمد بن عبد الواحد بن الفضل بن نظيف الفراء، أخبرنا أبو محمد الحسن بن رشيق، أخبرنا أبو بشر محمد بن أحمد بن حماد الأنصاري الدولابي، أخبرنا إبراهيم بن يعقوب، أخبرنا يزيد بن هارون، أخبرنا محمد بن إسحاق، عن داود بن الحصين، عن عكرمة، عن ابن عباس، أن النبي صلى الله عليه وآله وسلم «رد زينب على أبي العاص بعد سنتين بالنكاح الأول، لم يحدث صداقا»"],[38846,"قال: وحدثنا الدولابي، حدثنا إبراهيم بن يعقوب، أخبرنا يزيد بن هارون، عن الحجاج بن أرطاة، عن عمرو بن شعيب، عن أبيه، عن جده، أن رسول الله صلى الله عليه وآله وسلم «رد زينب على أبي العاص بمهر جديد ونكاح جديد» وتوفيت زينب بالمدينة في السنة الثامنة، ونزل رسول الله صلى الله عليه وآله وسلم في قبرها وهو مهموم ومحزون، فلما خرج سري عنه وقال: «كنت ذكرت زينب وضعفها، فسألت الله تعالى أن يخفف عنها ضيق القبر وغمه، ففعل وهون عليها»، ثم توفي بعدها زوجها أبو العاص."],[38847,"أخرجها الثلاثة."],[38848,"٦٩٦٥ - زينب بنت أبي سفيان"],[38849,"د ع: زينب بنت أبي سفيان بن حرب بن أمية القرشية الأموية، امرأة عروة بن مسعود الثقفي روى محمد بن عبيد الله الثقفي، عن عروة بن مسعود الثقفي، أنه أسلم وعنده نسوة منهن أربع من قريش، فأمره النبي صلى الله عليه وآله وسلم أن يختار منهم أربعا، فاختار أربعا منهم زينب بنت أبي سفيان."],[38850,"أخرجها ابن منده، وأبو نعيم."],[38851,"٦٩٦٦ - زينب بنت أبي سلمة"],[38852,"ب د ع: زينب بنت أبي سلمة بن عبد الأسد القرشية المخزومية ربيبة رسول الله صلى الله عليه وآله وسلم."],[38853,"وأمها أم سلمة زوج النبي صلى الله عليه وآله وسلم. كان اسمها برة فسماها رسول الله صلى الله عليه وآله وسلم زينب."],[38854,"ونقل مثل هذا عن زينب بنت جحش رضي الله عنها."],[38855,"ولدتها أمها بأرض الحبشة، وقدمت بها معها."],[38856,"أخبرنا عمر بن محمد بن المعمر، أخبرنا أبو غالب أحمد بن الحسن بن أحمد، أخبرنا أبو محمد الجوهري، أخبرنا أحمد بن جعفر بن حمدان، حدثنا عبد الله بن أحمد، حدثني الهيثم بن خارجة، أخبرنا عطاف بن خالد المخزومي، عن أمه، عن زينب بنت أبي سلمة، قالت: كانت أمي إذا دخل رسول الله صلى الله عليه وآله وسلم يغتسل تقول: ادخلي عليه."],[38857,"فإذا دخلت عليه نضح في وجهي من الماء ويقول: «ارجعي»، قال عطاف: قالت أمي: ورأيت زينب وهي عجوز كبيرة ما نقص من وجهها شيء."],[38858,"وتزوجها عبد الله بن زمعة بن الأسود الأسدي، فولدت له، وكانت من أفقه نساء زمانها روى جرير بن حازم، عن الحسن، قال: لما كان يوم الحرة قتل أهل المدينة، فكان فيمن قتل ابنا زينب ربيبة رسول الله صلى الله عليه وآله وسلم فحملا فوضعا بين يديها مقتولين، فقالت: إن لله وإنا إليه راجعون، والله إن المصيبة فيهما علي لكبيرة، وهي علي في هذا أكبر منها في هذا لأنه جلس في بيته، فدخل عليه، فقتل مظلوما، وأما الآخر فإنه بسط يده وقاتل فلا أدري علام هو من ذلك؟ وهما ابنا عبد الله بن زمعة."],[38859,"أخرجها الثلاثة."],[38860,"٦٩٦٧ - زينب بنت سهل"],[38861,"زينب بنت سهل بن الصعب بن قيس الأنصارية الخزرجية ثم من بني الحبلى."],[38862,"بايعت النبي صلى الله عليه وآله وسلم. قاله ابن حبيب."],[38863,"٦٩٦٨ - زينب بنت صيفي"],[38864,"زينب بنت صيفي بن صخر بن خنساء الأنصارية بايعت النبي صلى الله عليه وآله وسلم. قاله ابن حبيب."],[38865,"٦٩٦٩ - زينب بنت علي بن أبي طالب"],[38866,"زينب بنت علي بن أبي طالب واسمه عبد مناف بن عبد المطلب بن هاشم القرشية الهاشمية."],[38867,"وأمها فاطمة بنت رسول الله صلى الله عليه وآله وسلم."],[38868,"أدركت النبي صلى الله عليه وآله وسلم وولدت في حياته، ولم تلد فاطمة بنت رسول الله صلى الله عليه وآله وسلم بعد وفاته شيئا."],[38869,"وكانت زينب امرأة عاقلة لبيبة جزلة زوجها أبوها علي رضي الله عنهما من عبد الله بن أخيه جعفر، فولدت له عليا، وعونا الأكبر، وعباسا، ومحمدا، وأم كلثوم."],[38870,"وكانت مع أخيها الحسين رضي الله عنه لما قتل، وحملت إلى دمشق، وحضرت عند يزيد بن معاوية، وكلامها ليزيد حين طلب الشامي أختها فاطمة بنت علي من يزيد مشهور مذكور في التواريخ، وهو يدل على عقل وقوة جنان."],[38871,"٦٩٧٠ - زينب بنت العوام"],[38872,"ب: زينب بنت العوام أخت الزبير، وهي أم عبد الله بن حكيم بن حرام أسلمت، وبقيت إلى أن قتل ابنها يوم الجمل، فقالت ترثيه وترثي الزبير أخاها:"],[38873,"أعيني جودا بالدموع فأسرعا … على رجل طلق اليدين كريم"],[38874,"زبير، وعبد الله ندعو لحادث … وذي خلة منا وحمل يتيم"],[38875,"قتلتم حواري النبي وصهره … وصاحبه فاستبشروا بجحيم"],[38876,"وقد هدني قتل ابن عفان قبله … وجادت عليه عبرتي بسجوم"],[38877,"وأيقنت أن الدين أصبح مدبرا … فكيف نصلي بعده ونصوم"],[38878,"وكيف بنا؟ أم كيف بالدين بعدما … أصيب وابن أروى ابن أم حكيم"],[38879,"٦٩٧١ - زينب بنت قيس"],[38880,"ب د ع: زينب بنت قيس بن مخرمة بن المطلب بن عبد سائب بن الحارث بن قيس بن عدى بن سعيد بن سعد بن سهم بن عمرو بن هصيص بن كعب بن مناف القرشية المطلبية صلت القبلتين جمعا، وهي مولاة السدي المفسر، أعتقت أباه."],[38881,"روى أسباط بن نصر، عن السدي، عن أبيه، قال: «كاتبتني زينب بنت قيس بن مخرمة، من بني المطلب بن عبد مناف، على عشرة آلاف درهم فتركت لي ألفا، وكانت قد صلت القبلتين مع رسول الله صلى الله عليه وآله وسلم»."],[38882,"أخرجها الثلاثة."],[38883,"٦٩٧٢ - زينب ابنة مالك"],[38884,"س: زينب ابنة مالك، أخت أبي سعيد الخدري تقدم نسبها عند ذكر أبيها وأخيها."],[38885,"روى أبو ضمرة، عن سعد بن إسحاق بن كعب بن عجرة، عن زينب بنت كعب، عن أبي سعيد وأخته زينب، عن النبي صلى الله عليه وآله وسلم في كفارة المرض."],[38886,"ورواه يحيى بن سعيد، عن سعد، فلم يذكر أخت أبي سعيد."],[38887,"أخرجها أبو موسى."],[38888,"٦٩٧٣ - زينب بنت مصعب بن عمير"],[38889,"زينب بنت مصعب بن عمير بن هاشم بن عبد مناف بن عبد الدار القرشية العبدرية قتل أبوها يوم أحد، فتكون لها صحبة، ولم يعقب مصعب بن عمير إلا منها."],[38890,"وأمها حمنة بنت جحش، وهي أخت محمد وعمران ابني طلحة بن عبيد الله لأمهما، لأن طلحة تزوج حمنة بعد مصعب، وتزوج زينب عبد الله بن عبد الله بن أبي أمية بن المغيرة المخزومي، فولدت له محمدا ومصعبا، وغيرهما."],[38891,"ذكرها الزبير بن بكار."],[38892,"٦٩٧٤ - زينب بنت مظعون"],[38893,"ب س: زينب بنت مظعون بن حبيب بن وهب بن حذافة بن جمح القرشية الجمحية أخت عثمان بن مظعون."],[38894,"وهي زوج عمر بن الخطاب وأم ولده عبد الله بن عمر، وأم حفصة بنت عمر، وعبد الرحمن بن عمر."],[38895,"قال أبو عمر: ذكر الزبير أنها كانت من المهاجرات."],[38896,"قال أبو عمر: أخشى أن يكون وهما لأنه قد قيل: إنها ماتت مسلمة بمكة قبل الهجرة، وحفصة ابنتها من المهاجرات."],[38897,"أخرجها أبو عمر، وأبو موسى."],[38898,"وقال أبو موسى: قد روي في بعض الحديث أن عبد الله بن عمر هاجر مع أبويه."],[38899,"٦٩٧٥ - زينب بنت معاوية"],[38900,"ب د ع: زينب بنت معاوية وقيل ابنة معاوية الثقفية امرأة عبد الله بن مسعود، قاله ابن منده، وأبو نعيم."],[38901,"وقال أبو عمر: زينب بنت عبد الله بن معاوية بن عتاب بن الأسعد بن غاضرة بن خطيط ابن جشم بن ثقيف، وهي ابنة أبي معاوية الثقفي، روى عنها بسر بن سعيد، وابن أخيها."],[38902,"أخبرنا أبو الفرج بن أبي الرجاء وأبو ياسر بن أبي حبة، بإسنادهما إلى مسلم، قال: حدثنا الحسن بن الربيع، حدثنا أبو الأحوص، عن الأعمش، عن شقيق، عن عمرو بن الحارث، عن زينب امرأة عبد الله، قالت: قال رسول الله صلى الله عليه وآله وسلم «تصدقن يا معشر الناس ولو من حليكن»."],[38903,"قالت: فانطقت فإذا امرأة من الأنصار بباب رسول الله صلى الله عليه وآله وسلم حاجتي حاجتها، قالت: وكان رسول الله صلى الله عليه وآله وسلم قد ألقيت عليه المهابة، قالت: فخرج علينا بلال فقلنا له."],[38904,"ائت رسول الله صلى الله عليه وآله وسلم فأخبره أن امرأتين بالباب يسألانك: أتجزئ الصدقة عنهما على أزواجهما، وعلى أيتام في حجورهما؟ ولا تخبره من نحن."],[38905,"فدخل بلال على رسول الله صلى الله عليه وآله وسلم فسأله، فقال رسول الله صلى الله عليه وآله وسلم: «من هما؟» قال: امرأة من الأنصار وزينب، فقال رسول الله صلى الله عليه وآله وسلم: «أي الزيانب؟» قال: امرأة عبد الله، فقال رسول الله صلى الله عليه وآله وسلم: «لها أجران، أجر القرابة، وأجر الصدقة»."],[38906,"أخرجه الثلاثة"],[38907,"٦٩٧٦ - زينب بنت نبيط"],[38908,"ب د ع: زينب بنت نبيط بن جابر الأنصارية مدنية امرأة أنس بن مالك."],[38909,"وقيل إنها أحمسية."],[38910,"روى عبد الله بن إدريس، عن محمد بن عمارة، عن زينب بنت نبيط امرأة أنس بن مالك، قالت: «أوصى أبو أمامة بأمي وخالتي إلى رسول الله صلى الله عليه وآله وسلم فأتاه حلى من ذهب ولؤلؤ يقال له: الرعاث، قالت: فحلاهن من الرعاث وأدركت بعض الحلى»."],[38911,"ورواه محمد بن عمرو بن علقمة، عن محمد بن عمارة، عن زينب بنت نبيط، قال: حدثتني أمي، وخالتي، أن النبي صلى الله عليه وآله وسلم «حلاهن رعاثا من ذهب، وأمها حبيبة، وخالتها كبشة أبنتا فريعة، وأبوهما أسعد بن زرارة، وهو أبو أمامة»."],[38912,"وقد أخرجها أبو موسى فقال: زينب بنت جابر الأحمسية."],[38913,"وأخرجها ابن منده كما ترى، فلم يصنع أبو موسى شيئا إلا أنه نسبها إلى جدها، ومثل هذا كثير في كتبهم، ينسب أحدهم الشخص إلى أبيه، وينسبه آخر إلى جده أو من فوق جده، وهما واحد."],[38914,"فلو سلك هذا لكثير الاستدراك عليه."],[38915,"أخرجه الثلاثة."],[38916,"٦٩٧٧ - زينب"],[38917,"س: زينب غير منسوبة يحتمل أن تكون إحدى الزيانب المذكورات."],[38918,"أخبرنا أبو موسى، كتابة، أخبرنا أبو غالب أحمد بن العباس وفاطمة العقيلية، قالا: أخبرنا أبو بكر بن ريذة، أخبرنا أبو القاسم الطبراني، حدثنا عبد الله بن أحمد بن حنبل، حدثنا شيبان بن فروخ، أخبرنا محمد بن زياد البرجمي، حدثنا أبو ظلال، عن أنس بن مالك، عن أمه، قالت: كان لي شاة، فجعلت من سمنها عكة، فبعثت بها مع زينب، فقلت: يا زينب، أبلغي هذه رسول الله صلى الله عليه وآله وسلم لعله يأتدم بها."],[38919,"قالت: فجاءت زينب إلى رسول الله صلى الله عليه وآله وسلم فقالت: يا رسول الله، هذا سمن بعثته إليك أم سليم فقال: «أفرغوا لها عكتها»."],[38920,"ففرغت العكة، ودفعت إليها."],[38921,"فجاءت وأم سليم ليست في البيت فعلقت العكة على وتد فجاءت أم سليم فرأت العكة ممتلئة تقطر سمنا، فقالت: يا زينب، أليس أمرتك أن تبلغي هذه العكة رسول الله صلى الله عليه وآله وسلم يأتدم بها؟! قالت: قد فعلت، فإن لم تصدقيني فتعالي معي إلى رسول الله صلى الله عليه وآله وسلم."],[38922,"فذهب أم سليم وزينب معها إلى النبي صلى الله عليه وآله وسلم فقالت: إني قد بعثت إليك معها بعكة فيها سمن، فقال: «قد جاءت بها»."],[38923,"فقلت: والذي بعثك بالهدى ودين الحق إنها ممتلئة سمنا تقطر، فقال النبي صلى الله عليه وآله وسلم: «أتعجبين يا أم سليم أن الله عز وجل أطعمك»."],[38924,"أخرجها أبو موسى"],[38925,"حرف السين"],[38926,"٦٩٧٨ - سائبة مولاة رسول الله ﷺ"],[38927,"س: سائبة مولاة رسول الله صلى الله عليه وآله وسلم روت عن رسول الله صلى الله عليه وآله وسلم في اللقطة روى عنها طارق بن عبد الرحمن."],[38928,"ذكرت في تاريخ النساء."],[38929,"أخرجها أبو موسى"],[38930,"٦٩٧٩ - سبيعة بنت الحارث"],[38931,"ب د ع: سبيعة بنت الحارث الأسلمية كانت امرأة سعد بن خولة فتوفي عنها بمكة في حجة الوداع وهي حامل، فوضعت بعد وفاة زوجها بليال، قيل: شهر، وقيل: خمس وعشرون، وقيل: أقل من ذلك."],[38932,"أخبرنا أبو الحرم مكي بن ربان النحوي، بإسناده عن يحيى بن يحيى، عن مالك بن أنس، عن عبد ربه بن سعيد، عن أبي سلمة بن عبد الرحمن أنه قال: سئل عبد الله بن عباس، وأبو هريرة عن المرأة الحامل يتوفى عنها زوجها، فقال ابن عباس: آخر الأجلين."],[38933,"وقال أبو هريرة: إذا ولدت فقد حلت."],[38934,"فدخل أبو سلمة بن عبد الرحمن على أم سلمة زوج النبي صلى الله عليه وآله وسلم فسألها عن ذلك، فقالت أم سلمة ولدت سبيعة الأسلمية بعد وفاة زوجها بنصف شهر، فخطبها رجلان أحدهما شاب والآخر كهل، فحطت إلى الشاب، فقال الشيخ: لم تحلي بعد."],[38935,"وكان أهلها غيبا، ورجا إذا جاء أهلها أن يؤثروه بها، فجاءت إلى النبي صلى الله عليه وآله وسلم فقال: «قد حللت فانكحي من شئت»"],[38936,"وروى عنها عبد الله بن عمر، أن النبي صلى الله عليه وآله وسلم قال: «من استطاع منكم أن يموت بالمدينة فليمت فإنه لا يموت بها أحد إلا كنت له شهيدا أو شفيعا يوم القيامة»."],[38937,"أخرجها الثلاثة، وقال أبو عمر: زعم العقيلي أن سبيعة التي روى عنها ابن عمر غير سبيعة الأسلمية، قال: ولا يصح ذلك عندي."],[38938,"٦٩٨٠ - سبيعة بنت حبيب"],[38939,"ب د ع: سبيعة بنت حبيب الضبعية بصرية روى عنها ثابت البناني أن رجلا مر بالنبي صلى الله عليه وآله وسلم فقال رجل: إني أحبه في الله."],[38940,"أخرجها الثلاثة."],[38941,"٦٩٨١ - سبيعة القرشية"],[38942,"د ع: سبيعة القرشية غير منسوبة."],[38943,"روت عنها عائشة، قالت: سمعت سبيعة القرشية، قالت: يا رسول الله، إني زنيت، فأقم علي حد الله."],[38944,"قال: «اذهبي حتى تضعي ما في بطنك»."],[38945,"فلما وضعت ما في بطنها أتته ولو لم تأته ما سأل عنها فقالت: يا رسول الله قد وضعت ما في بطني."],[38946,"قال: «اذهبي فأرضعيه حتى تفطميه»."],[38947,"فلما فطمته أتت النبي صلى الله عليه وآله وسلم فقالت: إني قد فطمته، فقال رسول الله صلى الله عليه وآله وسلم: «من لهذا الصبي؟» فقال رجل من الأنصار، أنا يا رسول الله."],[38948,"فرئي في وجه رسول الله صلى الله عليه وآله وسلم الكراهية، فقال: «اذهبوا بها فارجموها»."],[38949,"أخرجها ابن منده، وأبو نعيم."],[38950,"٦٩٨٢ - سبيعة بنت أبي لهب"],[38951,"دع: سبيعة بنت أبي لهب ذكرها ابن منده، وأبو نعيم، وقال أبو نعيم: صوابه: درة بنت أبي لهب."],[38952,"وروى يزيد بن عبد الملك النوفلي، عن سعيد بن أبي سعيد المقبري، عن أبي هريرة، رضي الله عنه، أن سبيعة بنت أبي لهب جاءت إلى رسول الله صلى الله عليه وآله وسلم فقالت: إن الناس يصيحون بي يقولون: إني ابنة حطب النار! فقام رسول الله صلى الله عليه وآله وسلم وهو مغضب شديد الغضب فقال: «ما بال أقوام يؤذونني في نسبي وذوي رحمي، ألا ومن آذي نسبي وذوي رحمي فقد آذاني، ومن آذاني فقد آذى الله عز وجل»."],[38953,"وقد رواه محمد بن إسحاق، وغيره، عن سعيد، عن أبي هريرة رضي الله عنه فقال: قدمت درة بنت أبي لهب."],[38954,"وقد تقدم ذكرها."],[38955,"٦٩٨٣ - سخبرة بنت تميم"],[38956,"سخبرة بنت تميم ذكرها ابن إسحاق فيمن هاجر إلى المدينة من بني غنم بن دودان، قاله ابن هشام عنه، ويونس بن بكير أيضا، عن ابن إسحاق."],[38957,"استدركه أبو علي، على أبي عمر."],[38958,"٦٩٨٤ - سخيلة بنت عبيدة"],[38959,"سخيلة بنت عبيدة زوج عمرو بن أمية الضمري."],[38960,"روى الزبرقان بن عبد الله، عن أبيه، عن عمرو بن أمية الضمري أنها اشترى مرطا فكساه امرأته سخيلة بنت عبيدة، فقال له عثمان أو عبد الرحمن بن عوف ما فعل المرط الذي ابتعت؟ قال: تصدقت به على سخيلة بنت عبيدة، فقال له عثمان أو عبد الرحمن بن عوف أفكل ما صنعت إلى أهلك صدقة؟ فقال عمرو: وسمعت رسول الله صلى الله عليه وآله وسلم يقول ذلك."],[38961,"فذكر ما قال عمرو لرسول الله صلى الله عليه وآله وسلم فقال: «صدق عمر»."],[38962,"أخرجه ابن الدباغ مستدركا على أبي عمرو."],[38963,"٦٩٨٥ - سدوس بنت قطبة"],[38964,"سدوس بنت قطبة بن عبد عمرو بن مسعود من بني دينار."],[38965,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[38966,"٦٩٨٦ - سديسة الأنصارية"],[38967,"د ع: سديسة الأنصارية قيل: هي مولاة حفصة بنت عمر."],[38968,"روى إسحاق بن يسار، عن الفضل بن الموفق، عن إسرائيل، عن الأوزاعي، عن سالم عن سديسة مولاة حفصة، وقال مرة: عن حفصة، قالت: قال رسول الله صلى الله عليه وآله وسلم: «إن الشيطان لم يلق عمر منذ أسلم إلا خر لوجهه»."],[38969,"ورواه عبد الرحمن بن الفضل، عن أبيه، ولم يذكر حفصة في الإسناد."],[38970,"أخرجها ابن منده، وأبو نعيم."],[38971,"٦٩٨٧ - سري بنت نبهان"],[38972,"ب د ع: سري بنت نبهان الغنوية قاله ابن منده، وأبو نعيم."],[38973,"وقال أبو عمر العنبرية والأول أصح وأكثر."],[38974,"روى عنها ربيعة بن عبد الرحمن الغنوي، وساكنة بنت الجعد."],[38975,"أخبرنا أبو أحمد عبد الوهاب بن علي، بإسناده إلى أبي داود، حدثنا محمد بن بشار، حدثنا أبو عاصم، عن ربيعة بن عبد الرحمن، عن سرى بنت نبهان الغنوية وكانت ربة بيت في الجاهلية، قالت: خطبنا النبي صلى الله عليه وآله وسلم في حجة الوداع فقال: «أي يوم هذا؟» قلنا: الله ورسوله أعلم."],[38976,"قال: «أليس أوسط أيام التشريق؟»."],[38977,"إلى هنا روى أبو داود، وزاد غيره: ثم قال: «هل تدرون أي بلد هذا؟» قلنا: الله ورسوله أعلم."],[38978,"قال: «أليس هذا المشعر الحرام؟» ثم قال: «لعلي لا ألقاكم بعد يومي هذا، ألا وإن دماءكم وأموالكم وأعراضكم عليكم حرام كحرمة يومكم هذا، في بلدكم هذا، حتى تلقوا ربكم»."],[38979,"أخرجها الثلاثة سري: بفتح السين، وإمالة الراء المشددة، وآخره ياء ساكنة."],[38980,"قاله الأمير أبو نصر."],[38981,"٦٩٨٨ - سعاد بنت رافع"],[38982,"سعاد بنت رافع بن أبي عمرو بن ثعلبة الأنصارية من بني مالك."],[38983,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[38984,"٦٩٨٩ - سعاد بنت سلمة"],[38985,"سعاد بنت سلمة بن زهير بن ثعلبة وهي التي سألت النبي صلى الله عليه وآله وسلم أن يبايعها لما في بطنها وكانت حاملا فقال لها النبي صلى الله عليه وآله وسلم: «أنت حرة الحرائر»."],[38986,"٦٩٩٠ - سعدة بنت قمامة"],[38987,"ب: سعدة بنت قمامة روى عنها أنها كانت تؤم النساء وتقوم في وسطهن، على حسب ما روى عن أم سلمة."],[38988,"يقال: إنها أدركت النبي صلى الله عليه وآله وسلم. أخرجها أبو عمر مختصرًا."],[38989,"٦٩٩١ - سعدى بنت عمرو"],[38990,"ب د ع: سعدى بنت عمرو المرية قاله أبو عمر."],[38991,"وقال ابن منده، وأبو نعيم: سعدى بنت عوف بن خارجة بن سنان."],[38992,"وهي امرأة طلحة بن عبيد الله، وهي أم يحيى بن طلحة."],[38993,"روى عنها يحيى بن طلحة، وزفر بن عقيل، ومحمد بن عمران بن طلحة."],[38994,"أخبرنا أبو الفضل بن أبي الحسن الفقيه، بإسناده إلى أبي يعلى الموصلي، حدثنا هارون بن إسحاق، حدثني محمد بن عبد الوهاب القناد، عن مسعر بن كدام، عن إسماعيل بن أبي خالد، عن الشعبي، عن يحيى بن طلحة، عن أمه سعدى المرية، قالت: مر عمر بطلحة بعد وفاة النبي صلى الله عليه وآله وسلم وهو مكتئب، فقال: أساءتك امرأة ابن عمك؟ قال: لا، ولكني سمعت رسول الله صلى الله عليه وآله وسلم يقول: «إني لأعلم كلمة لا يقولها عبد عند موته إلا كانت نورا في صحيفته، وإن جسده وروحه ليجدان لها روحا عند الموت»."],[38995,"قال عمر، أنا أعلمها، هي التي أراد عليها عمه، ولو علم شيئا أنجى له منها لأمره، يعني لا إله إلا الله."],[38996,"أخرجه الثلاثة"],[38997,"٦٩٩٢ - سعدى"],[38998,"د ع: سعدى غير منسوبة."],[38999,"روى حديثها عبد الواحد بن زياد، عن عثمان بن حكيم، عن أبي بكر بن عبد الله، عن جدته سعدى أو أسماء، أن النبي صلى الله عليه وآله وسلم دخل على ضباعة بنت الزبير بن عبد المطلب، فقال: «يا عمة، حجي»، فقالت: إني امرأة ثقيلة، وإني أخاف الحبس، فقال: «حجي واشترطي أن تحلي حيث حبست»."],[39000,"أخرجه ابن منده، وأبو نعيم."],[39001,"٦٩٩٣ - سعيدة بنت رفاعة"],[39002,"سعيدة بنت رفاعة بن عمرو بن عبيد بن أمية الأنصارية الأشهلية بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39003,"٦٩٩٤ - سعيدة"],[39004,"س: سعيدة قال مقاتل بن حيان: كان بين النبي صلى الله عليه وآله وسلم وبين كفار مكة عهد يوم الحديبية أن يرد من أتاه منهم، فجاءت امرأة منهم يقال لها: سعيدة كانت تحت أبي صيفي الراهب، وهو مشرك مقيم بمكة، فقالوا: ردها، فقال: كان الشرط في الرجال دون النساء."],[39005,"فأنزل الله عز وجل: ﴿فَامْتَحِنُوهُنَّ﴾."],[39006,"أخرجها أبو موسى."],[39007,"٦٩٩٥ - سعيرة الأسدية"],[39008,"س: سعيرة الأسدية قال جعفر: في إسناد حديثها نظر، أوردها ابن منده، وغيره بالشين المعجمة."],[39009,"وقال جعفر المستغفري: هو بالسين يعني: المهلمة أثبت."],[39010,"قال عطاء الخراساني، عن عطاء بن أبي رباح، قال: قال لي ابن عباس: ألا أريك إنسانا من أهل الجنة؟ قال: فأراني حبشية صفراء عظيمة، قال هذه سعيرة الأسدية، أتت رسول الله صلى الله عليه وآله وسلم فقالت: يا رسول الله، إن بي هذه الموتة، تعني الجنون فادع الله أن يشفيني مما بي، فقال لها رسول الله صلى الله عليه وآله وسلم: «إن شئت دعوت الله عز وجل أن يعافيك مما بك، ويكتب لك حسناتك وسيئاتك، وإن شئت فاصبري ولك الجنة؟» فاختارت الصبر والجنة."],[39011,"أخرجها أبو موسى، وقال: قال محمد بن إسحاق بن خزيمة، أنا أبرأ من عهدة هذا الإسناد!."],[39012,"٦٩٩٦ - سفانة بنت حاتم"],[39013,"ع س: سفانة بنت حاتم الطائي تقدم نسبها عند أخيها عدي، وكان أبوها حاتم يكني أبا سفانة."],[39014,"أخبرنا أبو جعفر، بإسناده عن يونس، عن محمد بن إسحاق، قال: أصابت خيل رسول الله صلى الله عليه وآله وسلم ابنة حاتم، فقدم بها على رسول الله صلى الله عليه وآله وسلم في سبايا طيء، فجعلت ابنة حاتم في حظيرة بباب المسجد، فمر بها رسول الله صلى الله عليه وآله وسلم فقامت إليه وكانت امرأة جزلة فقالت: يا رسول الله، هلك الوالد، وغاب الوافد، فامنن علي من الله عليك."],[39015,"قال: «من وافدك؟» قالت: عدي بن حاتم."],[39016,"قال: «الفار من الله ورسوله؟» ثم مضى رسول الله صلى الله عليه وآله وسلم وتركني، حتى مر بي ثلاثا، فأشار إلي رجل من خلفه أن قومي فكلميه."],[39017,"فقمت فقلت: يا رسول الله، هلك الوالد، وغاب الوافد، فامنن علي من الله عليك."],[39018,"قال: «قد فعلت، فلا تعجلي حتى تجدي ثقة يبلغك بلادك، ثم آذنيني»."],[39019,"فسألت عن الرجل الذي أشار إلي، فقيل: علي بن أبي طالب."],[39020,"وقدم ركب من بلي، فأتيت رسول الله صلى الله عليه وآله وسلم فقلت: قدم رهط من قومي."],[39021,"قالت: فكساني رسول الله صلى الله عليه وآله وسلم وحملني، وأعطاني نفقة، فخرجت حتى قدمت الشام على أخي عدي بن حاتم، فقال لها عدي: ما ترين في أمرها هذا الرجل."],[39022,"قالت: أرى أن تلحق به."],[39023,"كذا رواه يونس، ولم يسم سفانة، وسماها غيره."],[39024,"ورواه عبد العزيز بن أبي رواد نحوه، وزاد: وكانت أسلمت فحسن إسلامها."],[39025,"أخرجها أبو نعيم، وأبو موسى"],[39026,"٦٩٩٧ - سكينة بنت أبي وقاص"],[39027,"ع س: سكينة بنت أبي وقاص أم الحكم"],[39028,"أخبرنا أبو موسى، إجازة، أخبرنا أبو الطيب حبيب بن محمد، بقراءة والدي، أخبرنا أبو العباس أحمد بن محمد بن النعمان."],[39029,"ح قال أبو موسى: وأخبرنا الحسن بن أحمد، أخبرنا أحمد بن عبد الله، قالا: حدثنا محمد بن إبراهيم بن علي، حدثنا أبو عروبة الحسين بن محمد، حدثنا أبو موسى، حدثنا مكي بن إبراهيم، حدثنا هاشم بن هاشم، عن أم الحكم سكينة بنت أبي وقاص، أنها قالت: إن النبي صلى الله عليه وآله وسلم ذكر الجهاد فقيل: يا رسول الله، ما جهادنا؟ قال: «جهادكن الحج»."],[39030,"أوردها أبو عروبة في الصحابيات."],[39031,"أخرجها أبو نعيم، وأبو موسى"],[39032,"٦٩٩٨ - سكينة"],[39033,"د ع: سكينة غير منسوبة."],[39034,"روى عنها مولاها أبو صالح، عن النبي صلى الله عليه وآله وسلم. أخرجها ابن منده، وأبو نعيم مختصرا."],[39035,"٦٩٩٩ - سلامة حاضنة إبراهيم"],[39036,"ع س: سلامة حاضنة إبراهيم ابن النبي صلى الله عليه وآله وسلم روى عنها أنس بن مالك."],[39037,"أخبرنا أبو موسى، إجازة، أخبرنا الحسن بن أحمد، حدثنا أحمد بن عبد الله، حدثنا محمد بن الحسن اليقطيني، حدثنا عمر بن سعيد بن سنان المنجبي."],[39038,"ح قال أحمد: وحدثنا أبو عمرو بن حمدان، قال: حدثنا الحسن بن سفيان، قالا: حدثنا هاشم بن عمار، عن أبيه عمار بن نصير، عن عمرو بن سعيد الخولاني، عن أنس بن مالك، عن سلامة حاضنة إبراهيم ابن النبي صلى الله عليه وآله وسلم أنها قالت: يا رسول الله، إنك تبشر الرجال بكل خير ولا تبشر النساء! قال: «أصويحابتك دسسنك لهذا؟» قالت: أجل، هن أمرنني."],[39039,"قال: «ألا ترضى إحداكن أنها إذا كانت حاملا من زوجها وهو عنها راض أن لها مثل أجر الصائم القائم في سبيل الله عز وجل وإذا أصابها الطلق لم يعلم أهل السماء والأرض ما أخفي لها من قرة أعين»."],[39040,"وذكر الحديث في فضل الولادة والرضاع والسهر على الولد."],[39041,"أخرجه أبو نعيم، وأبو موسى"],[39042,"٧٠٠٠ - سلامة بنت الحر الأزدية"],[39043,"ب د ع: سلامة بنت الحر الأزدية وقيل الجعفية وقيل الفزارية أخت خرشة بن الحر."],[39044,"روت عن النبي صلى الله عليه وآله وسلم أحاديث، منها ما"],[39045,"أخبرنا به يحيى بن محمود، إجازة، بإسناده عن أبي بكر بن أبي عاصم: أخبرنا أبو بكر، عن وكيع، عن أم غراب مولاة بني فزارة، عن مولاة لهم يقال لها: عقيلة، عن سلامة بنت الحر أخت خرشة بن الحر، قالت: سمعت رسول الله صلى الله عليه وآله وسلم يقول: «يأتي على الناس زمان يقومون ساعة لا يجدون إماما يصلي بهم»."],[39046,"أخرجه الثلاثة، إلا أن أبا عمر روى في هذه الترجمة عن أم داود الوابشية، عن سلامة بنت الحر أخت خرشة بن الحر، قالت: كنت أرعى غنما في بدء الإسلام ويرد في سلامة الوابشية إن شاء الله تعالى"],[39047,"٧٠٠١ - سلامة بنت سعد بن الشهيد"],[39048,"سلامة بنت سعد بن الشهيد من بني عمرو بن عوف، أم بني طلحة بن أبي طلحة."],[39049,"بايعت النبي صلى الله عليه وآله وسلم بعد الفتح."],[39050,"قاله ابن حبيب."],[39051,"٧٠٠٢ - سلامة الضبية"],[39052,"ب د ع: سلامة الضبية روت عنها أم داود الوابشية، حديثها عند عبد الله بن داود الخريبي، قاله أبو عمر."],[39053,"وقال ابن منده، وأبو نعيم: سلامة الوابشية."],[39054,"ورويا عن عبد الله بن داود الخريبي، عن أم داود الوابشية، عن سلامة، قالت: مر بي النبي صلى الله عليه وآله وسلم في بدء الإسلام وأنا أرعى غنما لأهلي، فقال لي: «يا سلامة، بم تشهدين؟» فقلت:: أشهد أن لا إله إلا الله، ثم أشهد أن محمدا رسول الله."],[39055,"قالت: فتبسم والله ضاحكا."],[39056,"أخرجه الثلاثة، وقال أبو نعيم: هي عندي المتقدمة، أخت خرشة بن الحر، ذكرها المتأخر وسماها الوابشية، رواه مسدد عن الخريبي فقال: عن سلامة بنت الحر."],[39057,"قلت: وقد جعلها أبو عمر ترجمتين، وروى حديثها عن الخريبي، عن أم داود الوابشية، عنها."],[39058,"وروى أيضا في ترجمة سلامة بنت الحر حديث أم داود عنها، فما أقرب أن تكونا واحدة كما قال أبو نعيم، والله أعلم."],[39059,"٧٠٠٣ - سلامة بنت معقل الخزاعية"],[39060,"ب د ع: سلامة بنت معقل الخزاعية وقال أبو عمر: الأنصارية."],[39061,"وذكرها ابن أبي عاصم، وقال: هي من خارجة قيس عيلان، والله أعلم."],[39062,"أخبرنا عبد الوهاب بن علي بن سكينة الصوفي، بإسناده عن أبي داود، قال: حدثنا عبد الله بن محمد النفيلي، حدثنا محمد بن سلمة، عن محمد بن إسحاق، عن الخطاب بن صالح، عن أمه، قالت: حدثتني سلامة بنت معقل امرأة من خارجة قيس عيلان، قالت: قدم بي عمي في الجاهلية فباعني من الحباب بن عمرو الأنصاري أخي أبي اليسر فولدت له عبد الرحمن بن الحباب ثم هلك، فقالت لي امرأته: الآن والله تباعين في دينه."],[39063,"فأتيت رسول الله صلى الله عليه وآله وسلم فقلت: يا رسول الله، إني امرأة من خارجة قيس عيلان، قدم بي عمي المدينة، فباعني من الحباب بن عمرو، أخي أبي اليسر بن عمرو، فولدت له عبد الرحمن بن الحباب، فقالت امرأته: الآن تباعين في دينه، فقال: «من ولي الحباب؟» قالوا: أخوه أبو اليسر بن عمرو."],[39064,"فبعث إليه، وقال: «اعتقوها وإذا سمعتم برقيق قدم علي فأتوني أعوضكم منها»."],[39065,"قالت: فأعتقوني، وقدم على رسول الله صلى الله عليه وآله وسلم رقيق فعوضهم مني غلاما."],[39066,"أخرجها الثلاثة"],[39067,"٧٠٠٤ - سلمى الأنصارية"],[39068,"د: سلمى الأنصارية غير منسوبة."],[39069,"بايعت النبي صلى الله عليه وآله وسلم روى محمد بن إسحاق، عن رجل من الأنصار، عن أمه سلمى، قالت: «أتيت النبي صلى الله عليه وآله وسلم أبايعه في نسوة من الأنصار، فكان فيما أخذ علينا، أن لا نغش أزواجنا»."],[39070,"أخرجه ابن منده، وقال: هذه بنت قيس."],[39071,"وسنذكرها إن شاء الله تعالى."],[39072,"٧٠٠٥ - سلمى الأودية"],[39073,"ب: سلمى الأودية حديثها عند أهل الكوفة ليس بصحيح."],[39074,"أخرجها أبو عمر مختصرا."],[39075,"٧٠٠٦ - سلمى"],[39076,"سلمى"],[39077,"أخبرنا أبو ياسر بن أبي حبة، بإسناده عن عبد الله، حدثني أبي، حدثنا عبد الصمد، حدثنا همام، عن قتادة، عن سلمى بنت حمزة، «أن مولاها مات وترك ابنة، فورث النبي صلى الله عليه وآله وسلم ابنته النصف، وورث يعلى النصف وهو ابن سلمى»"],[39078,"٧٠٠٧ - سلمى بنت أبي ذؤيب"],[39079,"س: سلمى بنت أبي ذؤيب أخت حليمة بنت أبي ذؤيب ظئر النبي صلى الله عليه وآله وسلم."],[39080,"وهذه سلمى خالته من الرضاعة."],[39081,"يقال: إنها أتت النبي صلى الله عليه وآله وسلم فبسط لها رداءه، وقال: «مرحبا يا أمي»."],[39082,"ذكرها جعفر المستغفري في الصحابة."],[39083,"أخرجها أبو موسى."],[39084,"٧٠٠٨ - سلمى خادم رسول الله ﷺ"],[39085,"ب د ع: سلمى خادم النبي صلى الله عليه وآله وسلم وهي مولاة صفية بنت عبد المطلب، وهي امرأة أبي رافع."],[39086,"ويقال: إنها أيضا مولاة للنبي صلى الله عليه وآله وسلم."],[39087,"وكانت قابلة بني فاطمة بنت رسول الله صلى الله عليه وآله وسلم وقابلة إبراهيم ابن رسول الله صلى الله عليه وآله وسلم."],[39088,"وهي التي غسلت فاطمة مع زوجها علي ومع أسماء بنت عميس."],[39089,"وشهدت خيبر مع رسول الله صلى الله عليه وآله وسلم ومن حديثها ما"],[39090,"أخبرنا به إسماعيل بن علي وإبراهيم بن محمد، وغيرهما، قالوا: بإسنادهم عن أبي عيسى، قال: حدثنا أحمد بن منيع، حدثنا حماد بن خالد الخياط، أخبرنا قائد مولى لآل أبي رافع، عن علي بن عبيد الله، عن جدته، وكانت تخدم النبي صلى الله عليه وآله وسلم قالت: «ما كان يكون برسول الله صلى الله عليه وآله وسلم قرحة أو نكبة إلا أمرني أن أضع عليها الحناء»."],[39091,"وقد روى هذا عن عبيد الله بن علي، عن جدته سلمى."],[39092,"قال الترمذي: عبيد الله بن علي أصح"],[39093,"أخبرنا أبو موسى، إجازة، أخبرنا أبو علي، أخبرنا أبو نعيم، حدثنا أبو بكر بن مالك، أخبرنا عبد الله بن أحمد، حدثني أبي، أخبرنا يعقوب بن إبراهيم، حدثنا أبي، عن ابن إسحاق، عن هشام بن عروة، عن أبيه، عن عائشة، قالت: جاءت سلمى امرأة أبي رافع مولى النبي صلى الله عليه وآله وسلم تستأذنه على أبي رافع، وقالت: إنه يضربني، فقال النبي صلى الله عليه وآله وسلم لأبي رافع: «ما لك ولها يا أبا رافع؟» فقال: تؤذيني يا رسول الله."],[39094,"قال: «بم آذيتيه يا سلمى؟»، قالت: يا رسول الله، ما آذيته بشيء، ولكنه أحدث وهو يصلي، فقلت له: يا أبا رافع، إن رسول الله صلى الله عليه وآله وسلم قد أمر المسلمين إذا خرج من أحدهم ريح أن يتوضأ."],[39095,"فقام يضربني، فجعل رسول الله صلى الله عليه وآله وسلم يضحك ويقول: «يا أبا رافع، إنها لم تأمر إلا بخير»، وقال: «لا تضربها»."],[39096,"أخرجها الثلاثة"],[39097,"٧٠٠٩ - سلمى بنت زيد"],[39098,"سلمى بنت زيد بن تيم بن أمية بن بياضة بن خفاف بن سعد بن مرة بن مالك بن الأوس الأنصارية الأوسية وهي من الجعادرة وعدادهم في بني عبد الأشهل."],[39099,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39100,"٧٠١٠ - سلمى بنت صخر"],[39101,"سلمى بنت صخر أم الخير أم أبي بكر الصديق رضي الله عنه."],[39102,"ترد في الكنى أتم من هذا إن شاء الله تعالى."],[39103,"أخرجها أبو موسى."],[39104,"٧٠١١ - سلمى بنت عمرو"],[39105,"سلمى بنت عمرو بن خنيس بن لوذان بن عبد ود أخت المنذر، وهي من بني ساعدة."],[39106,"٧٠١٢ - سلمى بنت عميس"],[39107,"سلمى بنت عميس الخثعمية أخت أسماء تقدم نسبها عند أختها."],[39108,"وهي إحدى الأخوات اللاتي، قال فيهن رسول الله صلى الله عليه وآله وسلم «الأخوات مؤمنات»."],[39109,"وكانت سلمى زوج حمزة بن عبد المطلب رضي الله عنه، ثم خلف عليها بعده شداد بن أسامة بن الهاد الليثي، فولدت له عبد الله، وعبد الرحمن، وقيل: إن التي كانت تحت حمزة أسماء بنت عميس، فخلف عليها بعده شداد، ثم جعفر."],[39110,"وليس بشيء."],[39111,"روى همام، عن قتادة، عن سلمى، «أن مولى لها مات وترك بنتا فورث النبي صلى الله عليه وآله وسلم ابنته النصف، وورث يعلى هو ابن حمزة منها النصف»."],[39112,"وقد تقدم هذا في الورقة التي قبل هذه في سلمى بنت حمزة."],[39113,"أخرجها الثلاثة."],[39114,"قلت: قول من جعل أسماء امرأة حمزة، ثم شداد، ثم جعفر، ليس بشيء، فإنه لا خلاف بين أهل السير أن جعفرا هاجر إلى الحبشة من مكة ومعه امرأته وأسماء، وأنها ولدت له أولاد بالحبشة ولم يقدم على النبي صلى الله عليه وآله وسلم إلا وهو محاصر خيبر، وكان حمزة قد قتل، فكيف تكون امرأته، ثم امرأة شداد، وقد ولدت لجعفر بالحبشة، وهاجرت معه في حياة حمزة، هذا مما تمجه العقول، ولا خلاف أيضا أن جعفرا لما قتل تزوج امرأته أسماء أبو بكر، فأولدها محمدا."],[39115,"ولما توفي أبو بكر تزوجها علي، فولدت له."],[39116,"والصحيح أن سلمى هي امرأة حمزة، والله أعلم."],[39117,"ومما يقوى هذا أن عليا لما أخذ ابنة حمزة في عمرة القضاء، واختصم فيها علي وجعفر وزيد بن حارثة، فقضى بها رسول الله صلى الله عليه وآله وسلم لخالتها، وسلمها إلى جعفر، وقال: «الخالة بمنزلة الأم»."],[39118,"٧٠١٣ - سلمى بنت قيس"],[39119,"ب د ع: سلمى بنت قيس بن عمرو بن عبيد بن مالك بن عدي بن عامر بن غنم بن عدي بن النجار تكنى أم المنذر أخت سليط بن قيس."],[39120,"وهي إحدى خالات النبي صلى الله عليه وآله وسلم من جهة أبيه."],[39121,"وقال ابن منده: تكنى أم أيوب."],[39122,"والأول أصح."],[39123,"وكانت من المبايعات، وصلت القبلتين، وبايعت بيعة الرضوان."],[39124,"أخبرنا أبو جعفر، بإسناده عن يونس بن بكير، عن ابن إسحاق، عن سليط بن أيوب بن الحكم، عن أمه، عن سلمى بنت قيس وكانت إحدى خالات النبي صلى الله عليه وآله وسلم وممن صلى القبلتين، قالت: بايعت النبي صلى الله عليه وآله وسلم فيمن بايعه من النساء على ألا نشرك بالله شيئا، ولا نسرق، ولا نزني، ولا نقتل أولادنا، ولا نأتي ببهتان نفتريه بين أيدينا وأرجلنا، ولا نعصيه في معروف، ولا نغشش أزواجنا، فبايعناه."],[39125,"فلما انصرفنا، قلت لامرأة ممن معي: ويحك! ارجعي فسليه: ما غش أزواجنا؟ فسألته، فقال: «تأخذ ماله فتحابي به غيره»."],[39126,"أخرجه الثلاثة قلت: قول أبي عمر: إحدى خالات النبي صلى الله عليه وآله وسلم من جهة أبيه، يعني: به جده عبد المطلب، فإن أباه عبد الله أمه مخزومية، وأما جده عبد المطلب فأمه من بني عدي بن النجار، لأن أمه سلمى بنت عمرو بن زيد الخزرجية، من بني عدي."],[39127,"وأهل الرجل من قبل النساء له ولآبائه وأجداده كلهن خالات."],[39128,"وقد استقصينا نسبه صلى في الكامل في التاريخ."],[39129,"٧٠١٤ - سلمى بنت محرز"],[39130,"سلمى بنت محرز بن عامر الأنصارية من بني عدي."],[39131,"بايعت النبي صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39132,"٧٠١٥ - سلمى أم مسطح"],[39133,"سملى أم مسطح بن أثاثة لها ذكر في حديث الإفك."],[39134,"وقد ذكرت في الكني أتم من هذا."],[39135,"٧٠١٦ - سلمى بنت نصر"],[39136,"ع س: سلمى بنت نصر المحاربية ذكرها الطبراني، وقال: يقال: لها صحبة."],[39137,"وأورد لها ما أخبرنا به أبو موسى، إجازة، أخبرنا أبو غالب الكوشيدي، أخبرنا أبو بكر بن ريذة."],[39138,"ح قال أبو موسى: أخبرنا الحسن بن أحمد، أخبرنا أحمد بن عبد الله، قالا: حدثنا سليمان بن أحمد، حدثنا محمد بن عبد الله الحضرمي، حدثنا منجاب بن الحارث، حدثنا علي بن مسهر، عن محمد بن إسحاق، عن عاصم بن عمر بن قتادة، عن سلمى بنت نصر المحاربية، قالت: «سألت عائشة عن عتاقة ولد الزنا، فقالت: أعتقيه»."],[39139,"أخرجه أبو نعيم، وأبو موسى"],[39140,"٧٠١٧ - سلمى بنت يعار"],[39141,"سلمى بنت يعار وقيل تعار بالتاء فوقها نقطتان أخت ثبيتة."],[39142,"٧٠١٨ - سلمى"],[39143,"د ع: سلمى غير منسوبة."],[39144,"روى عنها ابن ابنها عبيد الله بن علي."],[39145,"روى إسحاق بن إبراهيم الحبيبي، عن فائد بن عبد الرحمن، عن عبيد الله بن علي مولاه، عن جدته سلمى، قالت: «أتانا رسول الله صلى الله عليه وآله وسلم فصنعنا له خزيرة»."],[39146,"قاله ابن منده، وقال أبو نعيم ذكرها المتأخر، وهي عندي المتقدمة، امرأة أبي رافع."],[39147,"وروى من حديث الفضل بن سليمان، عن فائد مولى عبيد الله، عن عبيد الله بن علي بن أبي رافع، عن جدته، أنها أخبرته، قالت: صنعت لرسول الله صلى الله عليه وآله وسلم خزيرة، فقربتها فأكل معه ناس من أصحابه، وبقي منها قليل، فمر بالنبي صلى الله عليه وآله وسلم أعرابي، فدعاه النبي صلى الله عليه وآله وسلم فأخذها الأعرابي كلها بيده، فقال له النبي صلى الله عليه وآله وسلم: «ضعها»."],[39148,"فوضعها، ثم قال: «سم الله عز وجل وخذ من أدناها تشبع»."],[39149,"قالت: فشبع منها، وفضلت فضلة."],[39150,"أخرجه ابن منده، وأبو نعيم."],[39151,"٧٠١٩ - سلمى"],[39152,"د ع: سلمى ترجمة أخرى، أخرجها ابن منده، وأبو نعيم غير التي قبلها."],[39153,"حديثها، أنها قالت: قال رسول الله صلى الله عليه وآله وسلم: «بعث الله عز وجل أربعة آلاف نبي»، في حديث طويل."],[39154,"رواه محمد بن عقبة، عن وهب بن عبد الله بن كعب."],[39155,"٧٠٢٠ - سمراء بنت قيس"],[39156,"ب د ع: سمراء وقيل: سميراء بنت قيس الأنصارية لها ذكر في حديث أبي أمامة بن سهل بن حنيف."],[39157,"أخرجها الثلاثة، إلا أن أبا عمر ذكرها سميراء مصغرة."],[39158,"٧٠٢١ - سمية أم عمار"],[39159,"ب د ع: سمية أم عمار بن ياسر وهي سمية بنت خباط كانت أمة لأبي حذيفة بن المغيرة المخزومي، وكان ياسر حليفا لأبي حذيفة، فزوجه سمية، فولدت له عمارا، فأعتقه أبو حذيفة."],[39160,"وكانت من السابقين إلى الإسلام، قيل: كانت سابع سبعة في الإسلام."],[39161,"وكانت ممن يعذب في الله عز وجل أشد العذاب."],[39162,"أخبرنا أبو جعفر، بإسناده عن يونس بن بكير، عن ابن إسحاق، قال: حدثني رجال من آل عمار بن ياسر أن سمية أم عمار عذبها هذا الحي من بني المغيرة بن عبد الله بن عمر بن مخزوم على الإسلام، وهي تأبى غيره، حتى قتلوها، وكان رسول الله صلى الله عليه وآله وسلم مر بعمار وأمه وأبيه وهم يعذبون بالأبطح في رمضاء مكة، فيقول: «صبرا آل ياسر موعدكم الجنة»"],[39163,"وروي أن أبا جهل طعنها في قبلها بحربة في يده فقتلها، فهي أول شهيد في الإسلام."],[39164,"وكان قتلها قبل الهجرة، وكانت ممن أظهر الإسلام بمكة في أول الإسلام."],[39165,"قال مجاهد: أول من أظهر الإسلام بمكة سبعة: رسول الله صلى الله عليه وآله وسلم وأبو بكر، وبلال، وخباب، وصهيب، وعمار، وسمية."],[39166,"فأما رسول الله صلى الله عليه وآله وسلم وأبو بكر فمنعهما قومهما، وأما الآخرون فألبسوا أدراع الحديد، ثم صهروا في الشمس، وجاء أبو جهل إلى سمية فطعنها بحربة فقتلها."],[39167,"وقال ابن قتيبة إن سمية خلف عليها بعد ياسر الأزرق، وكان غلاما روميا للحارث بن كلدة الثقفي، فولدت له سلمة، فهو أخو عمار لأمه."],[39168,"وهذا وهم منه فاحش، فإن الأزرق إنما خلف على سمية أم زياد، فسلمة بن الأزرق أخو زياد لأمه، اشتبه على ابن قتيبة سمية أم زياد بسمية أم عمار، والله أعلم."],[39169,"أخرجه الثلاثة."],[39170,"خباط: بالخاء المعجمة، وبالباء الموحدة، قاله ابن ماكولا، وقيل: بالياء تحتها نقطتان."],[39171,"وكذا ضبطه أبو نعيم."],[39172,"٧٠٢٢ - سناء بنت أسماء"],[39173,"ب د ع: سناء بنت أسماء بن الصلت السلمية تزوجها رسول الله صلى الله عليه وآله وسلم فماتت قبل أن يدخل بها، فيما ذكر أبو عبيدة معمر بن المثنى، عن حفص بن النضر، وعبد القاهر بن السري السلميين، قالا: تزوج رسول الله صلى الله عليه وآله وسلم. وذكره وهي عمة عبد الله بن خازم بن أسماء بن الصلت السلمي أمير خراسان."],[39174,"أخرجه الثلاثة."],[39175,"٧٠٢٣ - سنبلة بنت ماعز"],[39176,"سنبلة بنت ماعز بن قيس بن خلدة الأنصارية من بني زريق."],[39177,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39178,"٧٠٢٤ - سنينة بنت مخنف"],[39179,"سنينة بضم السين، وفتح النون، وسكون الياء تحتها نقطتان، ثم نون وهي سنينة بنت محنف بن زيد النكرية."],[39180,"لها صحبة ورواية، حديث عنها حبة بنت الشماخ النكرية، قاله ابن مكولا."],[39181,"النكرية: بالنون، وقيل: بالباء."],[39182,"٧٠٢٥ - سهلة بنت سعد"],[39183,"د ع: سهلة بنت سعد الساعدي أخت سهل بن سعد."],[39184,"روى حديثها منصور بن عمار، عن ابن لهيعة، عن عبد الله بن هبيرة، عن سهلة بنت سعد، أنها قالت: يا رسول الله، المرأة تصنع لزوجها أشياء تعطفه عليها فقال: «متاع في الدنيا، ولا خلاق لها في الآخرة»."],[39185,"أخرجها ابن منده، وأبو نعيم."],[39186,"٧٠٢٦ - سهلة بنت سهل"],[39187,"ع س: سهلة بنت سهل أوردها الطبراني."],[39188,"أخبرنا أبو موسى، كتابة، أخبرنا أبو غالب، أخبرنا أبو بكر محمد بن عبد الله."],[39189,"ح قال أبو موسى: وأخبرنا الحسن، أخبرنا أبو نعيم، قالا: حدثنا سليمان بن أحمد، حدثنا عبد الملك بن يحيى، حدثنا أبي، حدثنا ابن لهيعة، عن عبد الله بن هبيرة، عن سهلة بنت سهل، أنها قالت: يا رسول الله «أتغتسل إحدانا إذا احتملت؟ قال: نعم، إذا رأت الماء»."],[39190,"أورده جعفر المستغفري في ترجمة سهيل بن سهيل، وزاد فيه قلت: يا رسول الله، برج الخفاء."],[39191,"أخرجها أبو نعيم، وأبو موسى، وقال أبو موسى: ويحتمل أن تكون بنت سهيل، والله أعلم قلت: وما أقرب أن تكون سهلة أخت سهيل بن سعد فإن الراوي عنها في الترجمتين ابن لهيعة، عن ابن هبيرة، ويكون بعض الرواة غلط فيه، فجعل أخت بنت، والله أعلم."],[39192,"٧٠٢٧ - سهلة بنت سهيل"],[39193,"ب د ع: سهلة بنت سهيل بن عمرو القرشية من بني عامر بن لؤي."],[39194,"تقدم نسبها في ترجمة أبيها."],[39195,"وهي امرأة أبي حذيفة بن عتبة بن ربيعة."],[39196,"وهاجرت معه إلى الحبشة."],[39197,"وهي من السابقين إلى الإسلام، وولدت له بالحبشة محمد بن أبي حذيفة."],[39198,"أخبرنا عبيد الله بن أحمد، بإسناده عن يونس، عن ابن إسحاق، في تسمية من هاجر إلى أرض الحبشة: وأبو حذيفة بن عتبة بن ربيعة بن عبد شمس، وكانت معه امرأته سهلة بنت سهيل بن عمرو، أخي بني عامر بن لؤي، ولدت له بأرض الحبشة محمد بن أبي حذيفة."],[39199,"ولا عقب له وهي أيضا أم سليط بن عبد الله بن الأسود القرشي العامري، وأم بكير بن شماخ بن سعيد بن قائف، وأم سالم بن عبد الرحمن بن عوف، قاله أبو عمر، والزبير."],[39200,"أخبرنا أبو أحمد، بإسناده عن أبي داود سليمان بن الأشعث، حدثنا عبد العزيز بن يحيى، حدثنا محمد يعني ابن سلمة، عن محمد بن إسحاق، عن عبد الرحمن بن القاسم، عن أبيه، عن عائشة، «أن سهلة بنت سهيل استحيضت، فأتت النبي صلى الله عليه وآله وسلم فأمرها أن تغتسل لكل صلاة."],[39201,"فلما جهدها ذلك أمرها أن تجمع بين الظهر والعصر بغسل، وبين المغرب والعشاء الآخرة بغسل، وتغتسل للصبح»."],[39202,"وهي التي أرضعت سالما مولى أبي حذيفة وهو رجل، وقد تقدمت القصة في أبي حذيفة، وسالم."],[39203,"أخرجها الثلاثة"],[39204,"٧٠٢٨ - سهلة بنت عاصم"],[39205,"ب د ع: سهلة بنت عاصم بن عدي الأنصارية ولدت يوم خيبر فسماها رسول الله صلى الله عليه وآله وسلم سهلة."],[39206,"روى عبد العزيز بن عمران، عن سعيد بن زياد، عن حفص بن عمر بن عبد الرحمن بن عوف، عن جدته سهلة بنت عاصم بن عدي، قالت: ولدت يوم خيبر، فسماني رسول الله صلى الله عليه وآله وسلم سهلة، وقال: «سهل الله أمركم»."],[39207,"فضرب لي بسهم، وزوجني عبد الرحمن بن عوف يوم ولدت."],[39208,"أخرجها الثلاثة."],[39209,"٧٠٢٩ - سهيمة بنت أسلم"],[39210,"سهيمة بنت أسلم بن حريش بن عدي بن مجدعة بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39211,"٧٠٣٠ - سهيمة امرأة رفاعة القرظي"],[39212,"سهيمة امرأة رفاعة القرظي وقد تقدم ذكرها في رفاعة، وفي عبد الرحمن بن الزبير."],[39213,"وقيل اسمها تميمة، وقيل: عائشة."],[39214,"٧٠٣١ - سهيمة بنت عمير"],[39215,"د ع: سهيمة بنت عمير المزنية امرأة ركانة بن عبد يزيد المطلبي."],[39216,"أخبرنا محمد بن سرايا علي، أخبرنا أبو زرعة، أخبرنا محمد بن إدريس الشافعي، حدثنا عمي محمد بن علي، عن عبد الله بن السائب، عن نافع بن عجير بن عبد يزيد."],[39217,"أن ركانة بن عبد يزيد طلق امرأته سهيمة ألبته، ثم أتى النبي صلى الله عليه وآله وسلم فقال: إني طلقت امرأتي سهيمة ألبته، ووالله ما أردت إلا واحدة، فقال رسول الله صلى الله عليه وآله وسلم: «والله ما أردت إلا واحدة؟» فقال ركانة: والله ما أردت إلا واحدة."],[39218,"فردها النبي صلى الله عليه وآله وسلم وطلقها الثانية في زمن عمر، والثالثة في زمن عثمان."],[39219,"أخرجها ابن منده، وأبو نعيم"],[39220,"٧٠٣٢ - سهيمة بنت مسعود"],[39221,"سهيمة بنت مسعود بن أوس بن مالك بن سواد الأنصارية الظفرية زوج جابر بن عبد الله."],[39222,"ولدت له عبد الرحمن، بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39223,"٧٠٣٣ - سوادة بنت مسرج"],[39224,"ب د ع: سوادة بنت مسرج الكندية وقيل سودة وهو أكثر روى عنها عروة بن فيروز، أنها قالت: كنت فيمن شهد فاطمة حين ضربها المخاض، فجاء النبي صلى الله عليه وآله وسلم فقال: «كيف هي؟» قلت: إنها لتجهد."],[39225,"قال: «فإذا وضعت فلا تحدثي شيئا»."],[39226,"فوضعت الحسن، فسررته ولففته في خرقة."],[39227,"وجاء النبي صلى الله عليه وآله وسلم فقال: «كيف هي؟» فقلت: قد وضعت ابنا فسررته ولففته في خرقة صفراء، فقال: «ائتني به»."],[39228,"فألقى عنه الخرقة الصفراء، ولفه في خرقة بيضاء، وتفل في فيه، وسقاه من ريقه، ودعا عليًا فقال: «ما سميته؟» فقال: جعفرا."],[39229,"قال: «لا، ولكنه الحسن، وبعده الحسين، فأنت أبو الحسن والحسين»."],[39230,"أخرجها الثلاثة."],[39231,"مسرج: بكسر الميم، وسكون السين المهملة."],[39232,"٧٠٣٤ - سوداء بنت عاصم"],[39233,"ب د ع: سوداء بنت عاصم بن خالد بن صداد بن عبد الله بن قرط بن رزاح بن عدي بن كعب بن لؤي القرشية العدوية روت عنها أم عاصم، قاله أبو نعيم وابن منده."],[39234,"وقال أبو عمر: هي سوداء الأسدية، قال بعضهم: هي السوداء بنت عاصم، حديثها عن النبي صلى الله عليه وآله وسلم في الخضاب."],[39235,"أخبرنا يحيى بن محمود، إجازة، بإسناده عن ابن أبي عاصم، حدثنا أبو بكر، حدثنا أبو إسحاق الأودي، حدثتنا نائلة هي مولاة أبي العيزار الكوفية، عن أم عاصم، عن السوداء، قالت: أتيت رسول الله صلى الله عليه وآله وسلم لأبايعه، فقال: «انطلقي فاختضبي ثم تعالي حتى أبايعك»."],[39236,"أخرجها الثلاثة"],[39237,"٧٠٣٥ - سوداء بنت زمعة"],[39238,"ب د ع: سودة بنت زمعة بن قيس بن عبد شمس بن عبد ود بن نصر بن مالك بن حسل بن عامر بن لؤي القرشية العامرية وأمها الشموس بنت قيس بن زيد بن عمرو بن لبيد بن خداش بن عامر بن غنم بن عدي بن النجار الأنصارية."],[39239,"وسودة هي زوج النبي صلى الله عليه وآله وسلم تزوجها رسول الله صلى الله عليه وآله وسلم بمكة بعد وفاة خديجة قبل عائشة، قاله عقيل عن الزهري، وقاله قتادة، وأبو عبيدة، وابن إسحاق."],[39240,"وقال عبد الله بن محمد بن عقيل: تزوجها بعد عائشة."],[39241,"ورواه يونس عن الزهري."],[39242,"وكانت قبله تحت ابن عمها السكران بن عمرو، أخي سهيل بن عمرو، من بني عامر بن لؤي، وكان مسلما فتوفي عنها، فتزوجها رسول الله صلى الله عليه وآله وسلم. وكانت امرأة ثقيلة ثبطة، وأسنت عند رسول الله صلى الله عليه وآله وسلم ولم تصب منه ولدا إلى أن مات."],[39243,"وروى محمد بن إسحاق، عن حكيم بن حكيم، عن محمد بن علي بن الحسين، عن أبيه، قال: «كان جميع ما تزوج رسول الله صلى الله عليه وآله وسلم خمس عشرة امرأة، وكان أول امرأة تزوجها بعد خديجة بنت خويلد سودة بنت زمعة»."],[39244,"أخبرنا غير واحد، بإسنادهم عن محمد بن عيسى، قال: حدثنا محمد بن المثنى، حدثنا أبو داود الطيالسي، حدثنا سليمان بن معاذ، عن سماك، عن عكرمة، عن ابن عباس، قال: «خشيت سودة أن يطلقها رسول الله صلى الله عليه وآله وسلم فقالت: لا تطلقني وأمسكني، واجعل يومي لعائشة، ففعل، فنزلت: ﴿فَلا جُنَاحَ عَلَيْهِمَا أَنْ يُصْلِحَا بَيْنَهُمَا صُلْحًا وَالصُّلْحُ خَيْرٌ﴾."],[39245,"فما اصطلحا عليه من شيء فهو جائز»"],[39246,"أخبرنا عبد الوهاب بن هبة الله، بإسناده عن عبد الله، حدثني أبي، حدثنا عبد العزيز بن عبد الصمد العمي أبو عبد الصمد، حدثنا منصور، عن مجاهد، عن مولى لابن الزبير يقال له: يوسف بن الزبير، أو الزبير بن يوسف، عن ابن الزبير، عن سودة بنت زمعة، قالت: جاء رجل إلى رسول الله صلى الله عليه وآله وسلم فقال: إن أبي شيخ كبير لا يستطيع أن يحج؟ قال: «أرأيت لو كان على أبيك دين فقضيته عنه قبل منك؟» قال: نعم."],[39247,"قال «فالله أرحم، حج عن أبيك» وتوفيت سودة آخر خلافة عمر."],[39248,"أخرجها الثلاثة"],[39249,"٧٠٣٦ - سودة بنت أبي ضبيس"],[39250,"سودة بنت أبي ضبيس الجهنية أسلمت وبايعت بعد الهجرة، لها ولأبيها صحبة."],[39251,"قاله محمد بن نقطة، عن محمد بن سعد."],[39252,"٧٠٣٧ - سودة امرأة أبي الطفيل"],[39253,"دع: سودة امرأة أبي الطفيل قال عبد الله بن عثمان بن خثيم: دخلت على أبي الطفيل، فوجدته طيب النفس، فقلت: لأغتنمن ذلك منه، فقلت: يا أبا الطفيل، النفر الذين لعنهم رسول الله صلى الله عليه وآله وسلم من هم: فهم أن يخبرني بهم، قالت امرأته سودة: إن رسول الله صلى الله عليه وآله وسلم قال: «إنما أنا بشر، فمن دعوت عليه بدعوة فاجعلها له زكاة ورحمة»."],[39254,"أخرجه ابن منده، وأبو نعيم."],[39255,"٧٠٣٨ - سودة القرشية"],[39256,"د ع: سودة القرشية خطبها رسول الله صلى الله عليه وآله وسلم وكانت مصبية، فقالت: أكره أن يضغو صبيتي عند رأسك."],[39257,"روى شهر بن حوشب، عن ابن عباس، أن النبي صلى الله عليه وآله وسلم خطب امرأة من قومه يقال لها: سودة مصبية، وكان لها خمسة صبية أو ستة من بعل لها مات، فقالت: والله ما يمنعني منك وأنت أحب البرية إلي، ولكني أكرمك أن يضغو هؤلاء الصبية عند رأسك بكرة وعشية، فقال لها رسول الله صلى الله عليه وآله وسلم «يرحمك الله، إن خير نساء ركبن على أعجاز الإبل صالح نساء قريش، أحناه على ولد في صغره، وأرعاه لبعل في ذات يده»."],[39258,"أخرجه ابن منده، وأبو نعيم."],[39259,"٧٠٣٩ - سودة بنت مسرح"],[39260,"ع: سودة بنت مسرح وقيل سوادة وقد تقدمت."],[39261,"أخرجها هنا أبو نعيم."],[39262,"٧٠٤٠ - سيرين أخت مارية القبطية"],[39263,"ب د ع: سيرين أخت مارية القبطية."],[39264,"أهداهما المقوقس صاحب الإسكندرية إلى النبي صلى الله عليه وآله وسلم فتسرى النبي صلى الله عليه وآله وسلم مارية، وهي أم ابنة إبراهيم عليه السلام، وهب سيرين لحسان بن ثابت، فهي أم ابنه عبد الرحمن بن حسان."],[39265,"روى عنها ابنها عبد الرحمن، أنها قالت: حضر إبراهيم ابن النبي صلى الله عليه وآله وسلم الموت فرأيت رسول الله صلى الله عليه وآله وسلم كلما صحت أنا وأختي، نهانا عن الصياح، وغسله الفضل بن العباس، ورسول الله صلى الله عليه وآله وسلم والعباس على سرير، ثم حمل فرأيته جالسا على شفير القبر، ونزل في قبره الفضل والعباس وأسامة، وكسفت الشمس يومئذ، فقال الناس: كسفت لموت إبراهيم! فقال رسول الله صلى الله عليه وآله وسلم: «لا تكسف لموت أحد ولا لحياته»."],[39266,"ورأى رسول الله صلى الله عليه وآله وسلم فرجة في قبر إبراهيم، فأمر بها فسدت، وقال: «إنها لا تضر ولا تنفع، ولكن تقر عين الحي، وإن العبد إذا عمل شيئا أحب الله منه أن يتقنه»."],[39267,"أخرجها الثلاثة."],[39268,"حرف الشين"],[39269,"٧٠٤١ - شجيرة بنت تميم"],[39270,"س: شجيرة بنت تميم من بني غنم بن دودان بن أسد من المهاجرات الأول."],[39271,"ذكرها جعفر المستغفري، بإسناده عن ابن إسحاق."],[39272,"أخرجها أبو موسى."],[39273,"٧٠٤٢ - شراف بنت خليفة"],[39274,"ب ع س: شراف بنت خليفة بن فروة الكلبية أخت دحية بن خليفة."],[39275,"تزوجها رسول الله صلى الله عليه وآله وسلم ولم يدخل بها، فيما قيل."],[39276,"أخبرنا أبو موسى، إجازة، أخبرنا أبو غالب، أخبرنا أبو."],[39277,"ح قال أبو موسى: وأخبرنا الحسن، حدثنا أبو نعيم، قالا: حدثنا سليمان بن أحمد، حدثنا محمد بن عبد الله الحضرمي، حدثنا عبد الرحمن بن الفضل بن الموفق، حدثنا أبي، أخبرنا سفيان الثوري، عن جابر، عن ابن أبي مليكة، قال: «خطب النبي صلى الله عليه وآله وسلم امرأة من بني كلب، فبعث عائشة تنظر إليها»."],[39278,"أخرجها أبو نعيم، وأبو عمر، وأبو موسى"],[39279,"٧٠٤٣ - شرفة الدار بنت الحارث"],[39280,"شرفة الدار بنت الحارث بن قيس بن هيشة الأنصارية ثم من بني معاوية."],[39281,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39282,"٧٠٤٤ - شريرة بنت الحارث"],[39283,"شريرة بنت الحارث بن عوف بن قتيرة أم الحكم بن حارثة بن سلامة بن حارثة التجيبي."],[39284,"ذكر ابن عقبة أنها ممن بايعت النبي صلى الله عليه وآله وسلم ذكر ذلك عنها ابنها الحكم بن حارثة."],[39285,"قال الأمير أبو نصر بن ماكولا: شريرة: بضم الشين وبالراءين."],[39286,"٧٠٤٥ - الشفاء بنت عبد الله"],[39287,"ب د ع: الشفاء بنت عبد الله بن عبد شمس بن خلف بن صداد بن عبد الله بن قرط بن رزاح بن عدي بن كعب بن لؤي القرشية العدوية أم سليمان بن أبي خثمة."],[39288,"قيل: اسمها ليلى."],[39289,"أسلمت قديما، وهي من المبايعات، ومن المهاجرات الأول."],[39290,"وأمها فاطمة بنت أبي وهب ابن عمرو بن عائذ بن عمرو بن مخزوم."],[39291,"وكانت من عقلاء النساء وفضلائهن، وكان رسول الله صلى الله عليه وآله وسلم يقيل عندها."],[39292,"واتخذت له فراشا وإزارا ينام فيه، فلم يزل ذلك عندها حتى أخذه منهم مروان."],[39293,"وكانت ترقى من النملة، فأمرها رسول الله صلى الله عليه وآله وسلم أن تعلمها حفصة."],[39294,"وأقطعها رسول الله صلى الله عليه وآله وسلم دارا عند الحكاكين، فنزلتها مع ابنها سليمان."],[39295,"وكان عمر رضي الله عنه يقدمها في الرأي ويرضاها."],[39296,"روى عنها أبو بكر، وعثمان بن سليمان بن أبي حثمة."],[39297,"أخبرنا أبو ياسر، بإسناده عن عبد الله بن أحمد، قال: حدثني أبي، حدثنا هاشم بن القاسم، حدثنا المسعودي، عن عبد الله بن عمير، عن رجل من آل أبي خثمة، عن الشفاء بنت عبد الله، وكانت امرأة من المهاجرات، قالت: إن رسول الله صلى الله عليه وآله وسلم سئل عن أفضل الأعمال فقال: «إيمان بالله، وجهاد في سبيله، وحج مبرور» روى الأوزاعي، عن الزهري، عن أم سلمة، عن الشفاء بنت عبد الله، قالت: «أتيت رسول الله صلى الله عليه وآله وسلم أسأله، فجعل يعتذر إلي وأنا ألومه، قالت: فحضرت الصلاة فخرجت فدخلت على ابنتي وهي تحت شرحبيل بن حسنة، فوجدت شرحبيلا في البيت وأقول: قد حضرت الصلاة وأنت في البيت! وجعلت ألومه، فقال: يا خالة، لا تلوميني، فإنه كان لنا ثوب، فاستعاره رسول الله صلى الله عليه وآله وسلم. فقلت: بأبي أنت وأمي إني كنت ألومه وهذه حاله ولا أشعر! قال شرحبيل: ما كان إلا درعا رقعناه»."],[39298,"وروى عثمان بن سليمان بن أبي حثمة، عن الشفاء بنت عبد الله، أنها كانت ترقي في الجاهلية، وأنها لما هاجرت إلى النبي صلى الله عليه وآله وسلم وكانت قد بايعته بمكة قبل أن يخرج فقدمت عليه، فقالت: يا رسول الله، إني كنت أرقي برقى في الجاهلية، وإني أردت أن أعرضها عليك."],[39299,"قال: «فاعرضيها»."],[39300,"فعرضتها وكانت منها رقية النملة فقال: «أرقي بها، وعلميها حفصة: باسم الله صلوا صلب جبر تعوذا من أفواهها فلا تضر أحدا، اللهم اكشف الباس رب الناس»، قال: «ترقي به على عود كزكم سبع مرار وتضعه مكانا نظيفا، ثم تدلكه على حجر يخل خمر ثقيف، وتطليه على النملة»."],[39301,"أخرجها الثلاثة."],[39302,"٧٠٤٦ - الشفاء بنت عبد الرحمن"],[39303,"ب د: الشفاء بنت عبد الرحمن روى عنها أبو سلمة بن عبد الرحمن."],[39304,"قال ابن منده: أراها الأولى."],[39305,"وقال أبو عمر: الشفاء بنت عبد الرحمن الأنصارية مدنية."],[39306,"روى عنها أبو سلمة بن عبد الرحمن."],[39307,"أخرجها ابن منده، وأبو عمر مختصرا."],[39308,"٧٠٤٧ - الشفاء بنت عوف"],[39309,"ب: الشفاء بنت عوف بن عبد بن الحارث بن زهرة قال الزبير: هذه أم عبد الرحمن بن عوف، وأم أخيه الأسود بن عوف."],[39310,"قال الزبير: وقد هاجرت مع أختها لأمها الضيزية بنت أبي قيس بن عبد مناف."],[39311,"قال أبو عمر: على ما ذكر الزبير: عبد عوف جد عبد الرحمن أبو أبيه، وعوف جده أبو أمه، أخوان ابنا عبد بن الحارث بن زهرة، فانظر في ذلك."],[39312,"هذا كلام أبي عمر، وهو أخرجه، هذا كلام أبي عمر عن الزبير."],[39313,"وقد قال ابن أبي عاصم ما أخبرنا به يحيى بن محمود، إجازة، بإسناده عن ابن أبي عاصم، قال: ومن ذكر عبد الرحمن بن عوف بن عبد عوف بن عبد الحارث بن زهرة، وأمه العنقاء وهي الشفاء بنت عوف بن عبد الحارث بن زهرة فهي ابنة عم أبيه."],[39314,"وقد قال ابن عباس: إن أم عبد الرحمن أسلمت."],[39315,"وقد ذكرنا ذلك في أروى بنت كريز."],[39316,"أخرجها أبو عمر."],[39317,"٧٠٤٨ - الشفاء بنت عوف"],[39318,"د ع: شقيرة الأسدية حبشية، مولاة لهم."],[39319,"روى عطاء الخراساني، عن عطاء بن أبي رياح، قال: قال لي ابن عباس: ألا أريك امرأة من أهل الجنة؟ فأراني حبشية صفراء."],[39320,"الحديث."],[39321,"وقد تقدمت في سعيرة."],[39322,"أخرجها منده، وأبو نعيم."],[39323,"٧٠٤٩ - شقيرة الأسدية"],[39324,"ب: الشفاء بنت عوف أخت عبد الرحمن بن عوف."],[39325,"هاجرت مع أختها عاتكة، وعاتكة هي أم المسور بن مخزمة، قاله الزبير، وقيل: إن الشفاء أم المسور."],[39326,"ورى أبو أحمد العسكري ذلك هو، وغيره."],[39327,"أخرجها أبو عمر مختصرا."],[39328,"٧٠٥٠ - شقيقة بنت مالك"],[39329,"شقيقة بنت مالك بن قيس بن محرث وهي أخت الشموس بنت مالك."],[39330,"بايعت رسول الله صلى الله عليه وآله وسلم. أخرجها ابن حبيب."],[39331,"٧٠٥١ - الشموش بنت أبي عامر"],[39332,"الشموس بنت أبي عامر واسمه عبد عمرو بن صيفي بن زيد بن أمية الأنصارية من بني عمرو بن عوف، وهي أم عاصم وجميلة ولدي ثابت بن أبي الأقلح."],[39333,"بايعت رسول الله صلى الله عليه وآله وسلم. قال ابن حبيب."],[39334,"٧٠٥٢ - الشموس بنت عمرو"],[39335,"الشموس بنت عمرو بن حرام بن زيد وهي أم بنات مسعود بن أوس الظفريات."],[39336,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39337,"٧٠٥٣ - الشموس بنت مالك"],[39338,"الشموس بنت مالك بن قيس محرث الأنصارية من بني مازن بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39339,"٧٠٥٤ - الشموس بنت النعمان"],[39340,"د ع: الشموس بنت النعمان بن عامر بن مجمع الأنصارية حضرت مع النبي صلى الله عليه وآله وسلم حين أسس مسجد قباء، وكانت من المبايعات."],[39341,"روى شبابة بن سوار، عن عاصم بن سويد بن عامر بن يزيد بن جارية، عن أبيه سويد، عن الشموس بنت النعمان، قالت: نظرت إلى النبي صلى الله عليه وآله وسلم حين قدم ونزل وأسس هذا المسجد مسجد قباء، فرأيته يأخذ الحجر أو الصخرة حتى يهصره الحجر، وأنظر إلى بياض التراب على بطنه حتى أسسه ويقول: «إن جبريل عليه السلام يؤم الكعبة»، وكان يقال: أقوم مسجد قبلة مسجد قباء."],[39342,"رواه عتبة بن وديعة، عن الشموس، نحوه."],[39343,"أخرجه الثلاثة."],[39344,"قلت: قوله: «يؤم الكعبة»، فيه نظر، فإن النبي صلى الله عليه وآله وسلم لما قدم المدينة وأسس مسجد قباء لم تكن القبلة إلى الكعبة، إنما كانت إلى البيت المقدس، ثم حولت إلى الكعبة بعد ذلك."],[39345,"٧٠٥٥ - شميلة بنت الحارث"],[39346,"شميلة بنت الحارث بن عمرو بن حارثة بن الهيثم الأنصارية الظفرية بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39347,"٧٠٥٦ - شهيدة أم ورقة الأنصارية"],[39348,"د ع: شهيدة أم ورقة الأنصارية روى عبد الرحمن بن خلاد الأنصاري، عن أم ورقة الأنصارية، أن رسول الله صلى الله عليه وآله وسلم كان يقول: «انطلقوا بنا إلى الشهيدة نزورها»."],[39349,"وأمرها أن تؤذن في دارها وتقيم وأن تؤم أهل دارها في الفرائض."],[39350,"أخرجها ابن منده، وأبو نعيم."],[39351,"٧٠٥٧ - الشيماء بنت الحارث"],[39352,"ب د ع: الشيماء بنت الحارث السعدية أخت النبي صلى الله عليه وآله وسلم من الرضاعة."],[39353,"أخبرنا أبو جعفر، بإسناده عن ابن إسحاق، قال: واسم أبي رسول الله صلى الله عليه وآله وسلم الذي أرضعه: الحارث بن عبد العزى بن رفاعة بن ملان بن ناصرة بن بكر بن هوازن."],[39354,"وإخوته من الرضاعة: عبد الله بن الحارث، وأنيسة بنت الحارث، وحذاقة ابنة الحارث، وهي الشيماء."],[39355,"غلب عليها ذلك، وهم لحليمة أم رسول الله صلى الله عليه وآله وسلم. وذكروا أن الشيماء كانت تحضن رسول الله صلى الله عليه وآله وسلم مع أمها"],[39356,"قال ابن إسحاق: عن أبي وجزة السعدي، قال: لما انتهت الشيماء إلى رسول الله صلى الله عليه وآله وسلم قالت: يا رسول الله إني لأختك من الرضاعة."],[39357,"قال: «وما علامة ذلك؟» قلت: عضة عضضتينها في ظهري وأنا متوركتك."],[39358,"فعرف رسول الله صلى الله عليه وآله وسلم العلامة، فبسط لها رداءه."],[39359,"وقد تقدم ذكرها في حذافة، وغيرها."],[39360,"أخرجها أبو نعيم، وأبو عمر، وأبو موسى"],[39361,"حرف الصاد"],[39362,"٧٠٥٨ - الصعبة بنت الحضرمي"],[39363,"س: الصعبة بنت الحضرمي قال الجعابي: اسم الحضرمي عبد الله بن عماد بن ربيعة، وهي أخت العلاء بن الحضرمي أم طلحة بن عبيد الله التيمي."],[39364,"ذكرها جعفر من حديث عبد الله بن رافع، عن أبيه، قال: خرجت الصعبة بنت الحضرمي، قال: فسمعتها تقول لابنها طلحة بن عبيد الله: إن عثمان قد اشتد حصره فلو كلمت فيه حتى يرد عنه."],[39365,"وروى البلاذري، عن الواقدي، أنها توفيت على عهد رسول الله صلى الله عليه وآله وسلم قال: وأخبرني بعض آل طلحة أنها أسلمت."],[39366,"وكان هذا أشبه من قول من قال: إنها بقيت إلى أن قتل عثمان رضي الله عنه."],[39367,"أخرجها أبو موسى."],[39368,"٧٠٥٩ - الصعبة بنت سهل"],[39369,"الصعبة بنت سهل بن عمرو بن زيد بن عمرو بن الأشهل الأنصارية"],[39370,"بايعت رسول الله صلى الله عليه وآله وسلم."],[39371,"قاله ابن حبيب."],[39372,"٧٠٦٠ - صفية بنت بجير"],[39373,"ب: صفية عوض العين فاء وهي صفية بنت بجير الهذلية روت عن النبي صلى الله عليه وآله وسلم في الشرب من ماء زمزم."],[39374,"أخرجه أبو عمر مختصرا."],[39375,"٧٠٦١ - صفية بنت بشامة"],[39376,"صفية بنت بشامة، أخت الأعور بن بشامة خطبها النبي صلى الله عليه وآله وسلم ولم يدخل بها، وهي من بني العنبر بن تميم."],[39377,"قاله ابن حبيب في المحبر."],[39378,"٧٠٦٢ - صفية بنت ثابت"],[39379,"صفية بنت ثابت بن الفاكه بن ثعلبة الأنصارية ثم من بني خطمة."],[39380,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39381,"٧٠٦٣ - صفية بنت حيي بن أخطب"],[39382,"ب د ع: صفية بنت حيي بن أخطب بن سعية بن ثعلبة بن عبيد بن كعب بن الخزرج بن أبي حبيب بن النضير بن النحام بن ناخوم وقيل ينخوم وقيل نخوم."],[39383,"والأول قاله اليهود، وهم أعلم بلسانهم، وهم من بني إسرائيل من سبط لاوي بن يعقوب، ثم من ولد هارون بن عمران، أخي موسى صلى الله عليهم، وأم صفية برة بنت سموأل: وكانت زوج سلام بن مشكم اليهودي، ثم خلف عليها كنانة بن أبي الحقيق، وهما شاعران، فقتل عنها كنانة يوم خيبر."],[39384,"روى أنس بن مالك، أن رسول الله صلى الله عليه وآله وسلم لما افتتح خيبر وجمع السبي، أتاه دحية بن خليفة فقال: أعطني جارية من السبي."],[39385,"قال: «اذهب فخذ جارية»."],[39386,"فذهب فأخذ صفية."],[39387,"قيل: يا رسول الله، إنها سيدة قريظة والنضير، ما تصلح إلا لك، فقال له رسول الله صلى الله عليه وآله وسلم: «خذ جارية من السبي غيرها»."],[39388,"وأخذها رسول الله صلى الله عليه وآله وسلم واصطفاها، وحجبها وأعتقها وتزوجها، وقسم لها."],[39389,"وكانت عاقلة من عقلاء النساء."],[39390,"أخبرنا أبو جعفر، بإسناده عن يونس، عن ابن إسحاق، قال: حدثني والدي إسحاق بن يسار، قال: لما افتتح رسول الله صلى الله عليه وآله وسلم القموص حصن ابن أبي الحقيق أتي بصفية بنت حيي، ومعها ابنة عم لها، جاء بهما بلال، فمر بهما إلى قتلى من قتلى يهود، فلما رأتهم التي مع صفية صكت وجهها وصاحت، وحثت التراب على رأسها، فقال رسول الله صلى الله عليه وآله وسلم: «أغربوا هذه الشيطانة عني»، وأمر رسول الله صلى الله عليه وآله وسلم بصفية فحيزت خلفه، وغطى عليها ثوبه، فعرف الناس أنه قد اصطفاها لنفسه، فقال رسول الله صلى الله عليه وآله وسلم لبلال حين رأى من اليهودية ما رأى: «يا بلال، أنزعت منك الرحمة حتى تمر بامرأتين على قتلاهما؟!» وقد كانت صفية قبل ذلك رأت أن قمرا وقع في حجرها، فذكرت ذلك لأبيها فضرب وجهها ضربة أثرت فيه، وقال: إنك لتمدين عنقك إلى أن تكوني عند ملك العرب! فلم يزل الأثر في وجهها حتى أتى بها رسول الله صلى الله عليه وآله وسلم فسألها عنه، فأخبرته الخبر"],[39391,"أخبرنا غير واحد، بإسنادهم عن أبي عيسى، قال: حدثنا قتيبة، أخبرنا أبو عوانة، عن قتادة وعبد العزيز بن صهيب، عن أنس، أن رسول الله صلى الله عليه وآله وسلم «أعتق صفية، وجعل عتقها صداقها»"],[39392,"قال: وأخبرنا محمد بن عيسى، أخبرنا بندار عن عبد الصمد، أخبرنا هاشم بن سعيد الكوفي، أخبرنا كنانة، حدثتنا صفية بنت حيي، قالت: دخل علي رسول الله صلى الله عليه وآله وسلم وقد بلغني عن حفصة وعائشة كلام، فذكرت ذلك لرسول الله صلى الله عليه وآله وسلم فقال: «ألا قلت: وكيف تكونان خيرا مني، وزوجي محمد، وأبي هارون، وعمي موسى؟!» وكان بلغها أنهما، قالتا: نحن أكرم على رسول الله صلى الله عليه وآله وسلم منها، نحن أزواج رسول الله صلى الله عليه وآله وسلم وبنات عمه"],[39393,"أخبرنا عبد الوهاب بن أبي حبة، بإسناده عن عبد الله بن أحمد، حدثني أبي، حدثنا عبد الرزاق، حدثنا جعفر بن سليمان، عن ثابت، قال: حدثتني شميسة أو سمية، قال"],[39394,"عبد الرزاق: وهي في كتابي سمية عن صفية بنت حيي، أن النبي صلى الله عليه وآله وسلم حج بنسائه، فلما كان ببعض الطريق برك بصفية جملها، فبكت وجاء رسول الله صلى الله عليه وآله وسلم حين أخبر بذلك فجعل يمسح دموعها بيده، وجعلت تزداد بكاء وهو ينهاها، فنزل رسول الله صلى الله عليه وآله وسلم بالناس، فلما كان عند الرواح، قال لزينب بنت جحش: «يا زينب، أفقري أختك جملا؟» وكانت من أكثرهن ظهرا، قالت، أنا أفقر يهوديتك؟! فغضب النبي صلى الله عليه وآله وسلم حين سمع ذلك منها، فلم يكلمها حتى قدم مكة، وأيام منى في سفره حتى رجع إلى المدينة، ومحرم وصفر، فلم يأتها ولم يقسم لها، ويئست منه، فلما كان شهر ربيع الأول دخل عليها، فلما رأت ظله، قالت: هذا ظل رجل، وما يدخل علي رسول الله صلى الله عليه وآله وسلم! فدخل النبي صلى الله عليه وآله وسلم فلما رأته، قالت: يا رسول الله، ما أصنع؟ قالت: وكانت لها جارية تخبؤها من النبي صلى الله عليه وآله وسلم فقالت: فلانة لك."],[39395,"قال: فمشى النبي إلى سرير صفية، وكان قد رفع فوضعه بيده، ورضي عن أهله وروى عنها علي بن الحسين، قالت: جئت إلى النبي صلى الله عليه وآله وسلم أتحدث عنده، وكان معتكفا في المسجد، فقام معي يبلغني بيتي، فلقيه رجلان من الأنصار، قالت: فلما رأيا رسول الله رجعا، فقال: «تعاليا فإنها صفية»، فقالا: نعوذ بالله! سبحان الله! يا رسول الله، فقال: «إن الشيطان ليجري من ابن آدم مجرى الدم»."],[39396,"وتوفيت سنة ست وثلاثين، وقيل: سنة خمسين."],[39397,"أخرجها الثلاثة."],[39398,"٧٠٦٤ - صفية بنت الخطاب"],[39399,"صفية بنت الخطاب، أخت عمر بن الخطاب وهي امرأة قدامة بن مظعون."],[39400,"وقد ذكرناها في قدامة."],[39401,"ذكرها الغساني."],[39402,"٧٠٦٥ - صفية خادم رسول الله"],[39403,"ب: صفية خادم رسول الله صلى الله عليه وآله وسلم روت عنها أمة الله بنت رزينة في الكسوف مرفوعا."],[39404,"أخرجها أبو عمر مختصرا."],[39405,"٧٠٦٦ - صفية بنت شيبة"],[39406,"ب د ع: صفية بنت شيبة بن عثمان العبدرية من بني عبد الدار."],[39407,"اختلف في صحبتها."],[39408,"روى عنها عبيد الله بن عبد الله بن أبي ثور، وميمون بن مهران."],[39409,"أخبرنا أبو جعفر، بإسناده عن يونس بن بكير، عن ابن إسحاق، عن محمد بن جعفر بن الزبير، عن عبيد الله بن عبد الله بن أبي ثور، عن صفية بنت شيبة، قالت: «إن رسول الله صلى الله عليه وآله وسلم لما اطمأن بمكة عام الفتح، طاف على بعير يستلم الحجر بمحجن في يده، ثم دخل الكعبة فوجد فيها حمامة عيدان فكسرها، ثم قام على باب الكعبة وأنا أنظر، فرمى بها» وروى عنها ميمون بن مهران، أن النبي صلى الله عليه وآله وسلم تزوج ميمونة، وهما حلالان."],[39410,"أخرجها الثلاثة."],[39411,"٧٠٦٧ - صفية بنت عبد المطلب"],[39412,"ب د ع: صفية بنت عبد المطلب بن هاشم بن عبد مناف القرشية الهاشمية عمة رسول الله صلى الله عليه وآله وسلم وهي أم الزبير بن العوام، وأمها هالة بنت وهيب بن عبد مناف بن زهرة، وهي شقيقة حمزة والمقوم وحجل بني عبد المطلب."],[39413,"لم يختلف في إسلامها من عمات النبي صلى الله عليه وآله وسلم واختلف في عاتكة وأروى، والصحيح أنه لم يسلم غيرها، كانت في الجاهلية قد تزوجها الحارث بن حرب بن أمية بن عبد شمس، أخو أبي سفيان بن حرب، فمات عنها، فتزوجها العوام بن خويلد، فولدت له الزبير، وعبد الكعبة، وعاشت كثيرا، وتوفيت سنة عشرين في خلافة عمر بن الخطاب، ولها ثلاث وسبعون سنة."],[39414,"ودفنت بالبقيع، وقيل: إن العوام تزوجها أولا، وليس بشيء، قاله أبو عمر."],[39415,"ولما قتل أخوها حمزة وجدت عليه وجدا شديدا، وصبرت صبرا عظيما."],[39416,"أخبرنا أبو جعفر، بإسناده عن يونس، عن ابن إسحاق، قال: حدثني الزهري وعاصم بن عمر بن قتادة ومحمد بن يحيى بن حبان والحصين بن عبد الرحمن بن عمرو بن سعد بن معاذ، وغيرهم من علمائنا، عن يوم أحد وقتل حمزة، قال: فاقبلت صفية بنت عبد المطلب لتنظر إلى حمزة بأحد، وكان أخاها لأمها، فقال رسول الله صلى الله عليه وآله وسلم لابنها الزبير: «القها فارجعها لا ترى ما بأخيها»."],[39417,"فلقيها الزبير، وقال: أي أمه إن رسول الله صلى الله عليه وآله وسلم يأمرك أن ترجعي."],[39418,"قالت: ولم، فقد بلغني أن مثل بأخي، وذاك في الله، فما أرضانا بما كان من ذلك، لأصبرن ولأحتسبن إن شاء الله."],[39419,"فلما جاء الزبير إليه فأخبره قول صفية، قال: «خل سبيلها»."],[39420,"فأتته فنظرت إليه واسترجعت، واستغفرت له ثم أمر به رسول الله صلى الله عليه وآله وسلم فدفن"],[39421,"قال: وحدثنا ابن إسحاق، قال: حدثني يحيى بن عباد بن عبد الله بن الزبير، عن أبيه، قال: «كانت صفية بنت عبد المطلب في فارع حصن حسان بن ثابت، يعني في وقعة الخندق، قالت: وكان حسان معنا في الحصن مع النساء والصبيان حيث خندق رسول الله صلى الله عليه وآله وسلم قالت صفية: فمر بنا رجل يهودي فجعل يطيف بالحصن، وقد حاربت بنو قريظة وقطعت ما بينها وبين رسول الله صلى الله عليه وآله وسلم وليس بيننا وبينهم أحد يدفع عنا، ورسول الله صلى الله عليه وآله وسلم والمسلمون في نحور عدوهم، لا يستطيعون أن ينصرفوا إلينا عنهم أن أتانا آت، قالت: فقلت: يا حسان، إن هذا اليهودي يطوف بالحصن كما ترى، ولا أمنه أن يدل على عوراتنا من وراءنا من يهود، فأنزل إليه فاقتله، فقال: يغفر الله لك يا ابنة عبد المطلب! والله لقد عرفت ما أنا بصاحب هذا! قالت صفية: فلما قال ذلك، ولم أر عنده شيئا، احتجزت وأخذت عمودا ونزلت من الحصن إليه، فضربته بالعمود حتى قتلته، ثم رجعت إلى الحصن فقلت: يا حسان، انزل فاسلبه فإنه لم يمنعني من سلبه إلا أنه رجل، فقال: ما لي بسلبه حاجة يا ابنة عبد المطلب»."],[39422,"ح قال يونس: وحدثنا هشام بن عروة، عن أبيه، عن صفية بنت عبد المطلب مثله ونحوه، وزاد فيه: وهي أول امرأة قلت رجلا من المشركين."],[39423,"أخرجه الثلاثة"],[39424,"٧٠٦٨ - صفية بنت أبي عبيد"],[39425,"ب د ع: صفية بنت أبي عبيد أخت المختار بن أبي عبيد الثقفي."],[39426,"تقدم نسبها عند ذكر أبيها."],[39427,"أدركت النبي صلى الله عليه وآله وسلم وهي امرأة عبد الله بن عمرو بن الخطاب لا يصح لها سماع من النبي صلى الله عليه وآله وسلم روى عنها نافع."],[39428,"أخرجها الثلاثة."],[39429,"٧٠٦٩ - صفية بنت عمر بن الخطاب"],[39430,"ع س: صفية بنت عمر بن الخطاب العدوية أوردها الطبراني في الصحابة."],[39431,"أخبرنا أبو موسى، إذنا، أخبرنا أبو علي، أخبرنا أبو نعيم."],[39432,"ح قال أبو موسى: وأخبرنا أبو العباس، أخبرنا أبو بكر، قالا: حدثنا أبو القاسم الطبراني، حدثنا محمد بن عثمان بن أبي شيبة، حدثنا الحسن بن سهل الحناط، حدثنا محمد بن سهل الأسدي، حدثنا شريك، عن عبد الكريم، عن عكرمة، عن ابن عباس، «أن صفية بنت عمر بن الخطاب رضي الله عنه كانت مع النبي صلى الله عليه وآله وسلم يوم خيبر»."],[39433,"أخرجها أبو نعيم، وأبو موسى"],[39434,"٧٠٧٠ - صفية بنت محمية"],[39435,"صفية بنت محمية بن جزء الزبيدي امرأة الفضل بن العباس."],[39436,"لها ذكر في الحديث."],[39437,"٧٠٧١ - صفية امرأة من الصحابة"],[39438,"ب: صفية امرأة من الصحابة حديثها عند أهل الكوفة."],[39439,"روى عنها مسلم بن صفوان."],[39440,"أخرجها أبو عمر."],[39441,"٧٠٧٢ - صفية امرأة من الصحابة"],[39442,"ب: صفية امرأة من الصحابة أيضا، روى عنها إسحاق بن عبد الله بن الحارث، أنها قالت: دخل علي رسول الله صلى الله عليه وآله وسلم فقربت إليه كتفا، فأكل وصلى ولم يتوضأ."],[39443,"أخرجها أبو عمر أيضا."],[39444,"٧٠٧٣ - الصماء بنت بسر"],[39445,"ب ع: الصماء بنت بسر المازنية من مازن بن منصور، أخت عبد الله بن بسر."],[39446,"قاله أبو عمر، وقيل: الصماء أخت بسر."],[39447,"قاله أبو نعيم، والأول أصح."],[39448,"أخبرنا إبراهيم بن محمد، وغير واحد، بإسنادهم عن أبي عيسى السلمي، قال: حدثنا حميد بن مسعدة، حدثنا سفيان بن حبيب، عن ثور ابن يزيد، عن خالد بن معدان، عن عبد الله بن بسر، عن أخته، أن رسول الله صلى الله عليه وآله وسلم قال: «لا تصوموا يوم السبت إلا فيما افترض عليكم، فإن لم يجد أحدكم إلا لحاء عنبة أو عود شجرة، فليمضغه»."],[39449,"ورواه فضيل بن فضالة، عن عبد الله فقال: عن خالته."],[39450,"ورواه أبو داود السجستاني عن يزيد بن قيس من أهل جبلة، عن الوليد، عن ثور فقال: عن أخته الصماء."],[39451,"قلت: قال أبو عمر في بسر بن أبي بسر والد عبد الله: روى عنه ابنه، وليس من الصماء في شيء."],[39452,"وقد جعله ههنا أخاها"],[39453,"٧٠٧٤ - صميتة الليثية"],[39454,"ب د ع: صميتة الليثية من بني ليث بن بكر بن عبد مناه بن كنانة."],[39455,"أخبرنا يحيى، إجازة، بإسناده إلى ابن أبي عاصم، قال: حدثنا الحسن بن علي، حدثنا عبد الله بن صالح، حدثنا الليث، عن عقيل، عن الزهري، عن عبيد الله بن عبد الله بن عتبة، عن صميتة وكانت في حجر رسول الله صلى الله عليه وآله وسلم قالت: سمعت رسول الله صلى الله عليه وآله وسلم يقول: «من استطاع منكم أن يموت بالمدينة فليمت، فإنه من يموت بها أشفع له وأشهد له»."],[39456,"ورواه صالح بن أبي الأخضر، عن الزهري، وقال: كانت يتيمة في حجر عائشة، ورواه يونس، عن الزهري، عن عبيد الله، عن صفية بنت أبي عبيد، عن صميتة."],[39457,"ورواه ابن أبي ذئب، عن الزهري، عن عبيد الله، عن صفية بنت أبي عبيد، عن النبي صلى الله عليه وآله وسلم. أخرجها الثلاثة"],[39458,"حرف الضاد"],[39459,"٧٠٧٥ - ضباعة بنت الحارث"],[39460,"ب: ضباعة بنت الحارث الأنصارية أخت أم عطية."],[39461,"روت عنها أم عطية في ترك الوضوء مما غيرت النار."],[39462,"أخرجها أبو عمر مختصرا، وأما ابن منده، وأبو نعيم فلم يخرجا هذه في ترجمة مفردة، بل ذكرا حديثها في ترك الوضوء مما غيرت النار، في ترجمة ضباعة بنت الزبير بن عبد المطلب بعد حديث الاشتراط في الحج، على ما نذكره إن شاء الله تعالى."],[39463,"روى أبو نعيم عن الطبراني، عن علي بن عبد العزيز، عن خلف بن موسى بن خلف العمي، عن أبيه، عن قتادة، عن إسحاق بن عبد الله الهاشمي، عن أم عطية، عن أختها ضباعة، أنها رأت النبي صلى الله عليه وآله وسلم أكل كتفا ثم قام إلى الصلاة ولم يتوضأ."],[39464,"وقال: رواه محمد بن المثنى، عن خلف ابن موسى، عن أبيه، مثله، عن أم عطية، عن أختها."],[39465,"وقال: ورواه إسحاق بن زياد، عن خلف، عن أبيه، عن قتادة، عن أبي المليح، عن إسحاق، عن أم عطية."],[39466,"وهو وهم، وقال: ورواه همام، عن قتادة، عن إسحاق أن جدته أم حكيم حدثته عن أختها ضباعة."],[39467,"وقال أبو نعيم: أخبرنا ابن حمدان، حدثنا الحسن بن سفيان، حدثنا هدبة بن خالد، حدثنا همام، حدثنا قتادة، عن إسحاق بن عبد الله بن الحارث، أن جدته أم حكيم حدثته، عن أختها ضباعة بنت الزبير، «أنها رفعت للنبي صلى الله عليه وآله وسلم لحما فانتهش منها ثم صلى ولم يتوضأ» وهذا جميعه يدل على أن الترجمة الأولى وهم، وأن أبا عمر حيث رأى يروى عنها أختها أم عطية، وأم عطية أنصارية، ظنهما اثنتين، فإن بنت الزبير قرشية، فجعلهما اثنتين والصحيح أنهما واحدة، فإن أم حكيم هي بنت الزبير، وهي أخت ضباعة بنت الزبير، والله أعلم."],[39468,"٧٠٧٦ - ضباعة بنت الزبير"],[39469,"ب د ع: ضباعة بنت الزبير بن عبد المطلب بن هاشم القرشية الهاشمية ابنة عم النبي صلى الله عليه وآله وسلم."],[39470,"كانت زوج المقداد بن عمرو فولدت له عبدا الله وكريمة، قتل عبد الله يوم الجمل مع عائشة رضي الله عنها."],[39471,"روى عن ضباعة بن عباس، وجابر، وأنس، وعائشة، وعروة، والأعرج."],[39472,"أخبرنا إسماعيل بن علي، بإسنادهم إلى محمد بن عيسى، قال: حدثنا زياد بن أيوب البغدادي، عن عباد بن العوام، عن هلال بن خباب، عن عكرمة، عن ابن عباس، أن ضباعة بنت الزبير أتت النبي صلى الله عليه وآله وسلم وقال: يا رسول الله، إني أريد الحج، أفأشترط؟ قال: «نعم»."],[39473,"قالت: كيف أقول؟ قال: «قولي: لبيك اللهم لبيك، لبيك محلي من الأرض حيث تحبسني»."],[39474,"أخرجها الثلاثة"],[39475,"٧٠٧٧ - ضباعة بنت عامر"],[39476,"ع س: ضباعة بنت عامر بن قرط العامرية أسلمت بمكة."],[39477,"أخبرنا أبو موسى، إجازة، حدثنا أبو علي، حدثنا أبو نعيم، حدثنا محمد بن أحمد، حدثنا محمد بن عثمان بن أبي شيبة، حدثنا منجاب، أخبرنا عبد الله بن الأجلح، عن الكلبي، أخبرني عبد الرحمن العامري، عن أشياخ من قومه، قالوا: أتانا رسول الله صلى الله عليه وآله وسلم ونحن بعكاظ، فدعانا إلى نصرته ومنعته فأجبناه، إذ جاء بيحرة بن فراس القشيري، فغمز شاكلة ناقة رسول الله صلى الله عليه وآله وسلم فقمصت برسول الله صلى الله عليه وآله وسلم فألقته، وعندنا يومئذ ضباعة بنت قرط كانت من النسوة اللاتي أسلمن مع رسول الله صلى الله عليه وآله وسلم بمكة، جاءت زائرة إلى بني عمها فقات: يا آل عامر، ولا عامر لي، أيصنع هذا برسول الله صلى الله عليه وآله وسلم بين أظهركم، لا يمنعه أحد منكم؟! فقام ثلاثة من بني عمها إلى بيحرة فأخذ كل رجل منهم، رجلا فجلد به الأرض، ثم جلس على صدره، ثم علقوا وجهه لطما، فقال رسول الله صلى الله عليه وآله وسلم: «اللهم بارك على هؤلاء»."],[39478,"فأسلموا وقتلوا شهداء."],[39479,"أخرجها أبو نعيم، وأبو موسى"],[39480,"٧٠٧٨ - الضحاك بنت مسعود"],[39481,"د ع: الضحاك بنت مسعود أخت حويصة، ومحيصة ابني مسعود."],[39482,"روى يزيد بن عياض، عن سهل بن عبد الله، عن سهل بن أبي حثمة، أن الضحاك بنت مسعود، «خرجت مع رسول الله صلى الله عليه وآله وسلم حين غزا خيبر."],[39483,"» الحديث."],[39484,"أخرجها ابن منده، وأبو نعيم، وقال أبو نعيم: كذا ذكرها المتأخر يعني: ابن منده وهي أم الضحاك، وستذكر في الكنى إن شاء الله تعالى."],[39485,"حرف الطاء"],[39486,"٧٠٧٩ - طرية جارية حسان بن ثابت"],[39487,"دع: طرية جارية حسان بن ثابت."],[39488,"ذكرها عبد الله بن عباس."],[39489,"روى ابن وهب، عن أبي بكر بن أبي أويس، عن أبيه، عن حسين بن عبد الله، عن عكرمة، عن ابن عباس، قال: «أمر حسان بن ثابت جاريته طرية وناس عنده سماطين بفناء أطمة فارع فمر بهم النبي صلى الله عليه وآله وسلم ولم يأمرهم ولم ينههم»."],[39490,"أخرجها ابن منده، وأبو نعيم، وقال أبو نعيم: ذكرها المتأخر، وأخرج حديث ابن أبي أويس هذا."],[39491,"وروى أبو نعيم حدث يونس بن محمد، عن ابن أبي أويس، عن حسين، عن عكرمة، عن ابن عباس، قال: مر رسول الله صلى الله عليه وآله وسلم بحسان ومعه أصحابه سماطين وجارية له يقال لها سيرين، تختلف بين السماطين، وهي تغنيهم، فلم يأمرهم ولم ينههم."],[39492,"٧٠٨٠ - طعيمة بنت جريج"],[39493,"د: طعيمة بنت جريج لها ذكر وليس لها حديث."],[39494,"أخرجها ابن منده."],[39495,"٧٠٨١ - طفية بنت وهب"],[39496,"س: طفية بنت وهب أم أبي موسى الأشعري."],[39497,"أسلمت وهاجرت."],[39498,"قال المستغفري: ذكرها ابن قتيبة في كتاب المعارف."],[39499,"وقال الطبراني: أسلمت وماتت بالمدينة."],[39500,"٧٠٨٢ - طليحة بنت عبد الله"],[39501,"ب: طليحة بنت عبد الله التي كانت عند رشيد الثقفي فطلقها ونكحت في عدتها."],[39502,"ذكر الليث عن الزهري، أنها بنت عبيد الله أخرجها أبو عمر مختصرا."],[39503,"حرف الظاء"],[39504,"٧٠٨٣ - ظبية بنت البراء"],[39505,"د ع: ظبية بنت البراء بن معرور امرأة أبي قتادة الأنصاري."],[39506,"روت عبدة بنت عبد الرحمن بن مصعب بن ثابت بن عبد الله بن أبي قتادة، قالت: حدثني أبي، عن أبيه، عن جده، عن أبي قتادة، أن النبي صلى الله عليه وآله وسلم قال لظبية بنت البراء بن معرور، امرأة أبي قتادة، «ليس عليكن جمعة ولا جهاد»، فقالت: علمني يا رسول الله تسبيح الجهاد."],[39507,"قال: «قولي: سبحان الله، ولا إله إلا الله، والله أكبر، ولله الحمد»."],[39508,"أخرجها ابن منده، وأبو نعيم."],[39509,"٧٠٨٤ - ظبية بنت وهب"],[39510,"ظبية بنت وهب امرأة من عك ماتت بالمدينة مسلمة، قاله هشام بن الكلبي."],[39511,"وذكر أبو أحمد العسكري في ترجمة أبي موسى الأشعري، قال: وأمه ظبية بنت وهب من عك، أسلمت وماتت بالمدينة."],[39512,"وقيل فيها: طفية."],[39513,"وقد تقدمت في الطاء، والله أعلم."],[39514,"حرف العين"],[39515,"٧٠٨٥ - عاتكة بنت أسيد"],[39516,"ب س: عاتكة بنت أسيد بن أبي العيص بن أمية بن عبد شمس القرشية الأموية أخت عتاب بن أسيد."],[39517,"أسلمت يوم الفتح، لها صحبة ولا تعرف لها رواية."],[39518,"قاله ابن إسحاق."],[39519,"روى الزبير، عن محمد بن سلام، قال: أرسل عمر بن الخطاب إلى الشفاء بنت عبد الله العدوية."],[39520,"أن أغدي علي."],[39521,"قالت: فغدوت عليه فوجدت عاتكة بنت أسيد ببابه، فدخلنا فتحدثنا ساعة، فدعا بنمط فأعطاها إياه، ودعا بنمط دونه فأعطانيه، قالت: فقلت: تربت يداك يا عمر! أنا قبلها إسلام، وأنا ابنة عمك وأرسلت إلي وجاءتك من قبل نفسها؟! فقال: ما كنت رفعت ذلك إلا لك، فلما اجتمعتما ذكرت أنها أقرب إلى رسول الله صلى الله عليه وآله وسلم منك."],[39522,"أخرجها أبو عمر، وأبو موسى."],[39523,"٧٠٨٦ - عاتكة بنت خالد"],[39524,"ب د ع: عاتكة بنت خالد بن منقذ بن ربيعة وقيل عاتكة بنت خالد بن خليف بن منقذ بن ربيعة بن أصرم بن ضبيس بن حرام بن حبشية بن سلول بن كعب بن عمرو بن ربيعة الخزاعية وهي أم معبد كنيت بابنها معبد."],[39525,"وكان زوجها أكثم بن أبي الجون الخزاعي، وهو أبو معبد."],[39526,"وهي التي نزل بها رسول الله صلى الله عليه وآله وسلم لما هاجر إلى المدينة، وحديثه معها مشهور، وذلك المنزل يعرف اليوم بخيمة أم معبد."],[39527,"روى عبد الملك بن وهب المذحجي، عن الحر بن الصياح النخعي، عن أبي معبد الخزاعي، عن أم معبد، قالت: نظر رسول الله صلى الله عليه وآله وسلم إلى شاة في كسر البيت فقال: «ما هذه الشاة يا أم معبد؟» قالت: شاة خلفها الجهد عن الغنم."],[39528,"قال: «هل لها من لبن؟» قالت: هي أجهد من ذلك قال: «أتأذنين أن أحلبها»."],[39529,"قالت: نعم بأبي أنت وأمي، إن رأيت بها حلبا فاحلبها."],[39530,"فمسح ضرعها وذكر اسم الله، ودعا بإناء يربض الرهط، فحلب فيها فسقاها حتى رويت، وسقى أصحابه فشربوا حتى رووا وشرب آخرهم، وقال: «ساقى القوم آخرهم شربا»."],[39531,"فشربوا جميعا عللا بعد نهل حتى رضوا."],[39532,"أخرجها الثلاثة."],[39533,"٧٠٨٧ - عاتكة بنت زيد"],[39534,"ب د ع: عاتكة بنت زيد بن عمرو بن نفيل القرشية العدوية تقدم نسبها عند أخيها سعيد بن زيد."],[39535,"وهي ابنة عم عمر بن الخطاب، يجتمعان في نفيل."],[39536,"كانت من المهاجرات إلى المدينة، وكانت امرأة عبد الله بن أبي بكر الصديق، وكانت حسناء جميلة، فأحبها حبا شديدا حتى غلبت عليه وشغلته عن مغازيه، وغيرها، فأمره أبوه بطلاقها، فقال:"],[39537,"يقولون طلقها وخيم مكانها … مقيما تمني النفس أحلام نائم"],[39538,"وإن فراقي أهل بيت جمعتهم … على كبر مني لإحدى العظائم"],[39539,"أراني وأهلي كالعجول تروحت … إلى بوها قبل العشار الروائم"],[39540,"فعزم عليه أبوه حتى طلقها، فتبعتها نفسه، فسمعه أبو بكر يوما وهو يقول:"],[39541,"أعاتك لا أنساك ما ذر شارق … وما ناح قمري الحمام المطوق"],[39542,"أعاتك قلبي كل يوم وليلة … إليك بما تخفي النفوس معلق"],[39543,"ولم أر مثلي طلق اليوم مثلها … ولا مثلها في غير جزم تطلق"],[39544,"لها خلق جزل ورأى ومنصب … وخلق سوي في الحياء ومصدق"],[39545,"فرق له أبوه وأمره فارتجعها، ثم شهد عبد الله الطائف مع رسول الله صلى الله عليه وآله وسلم فرمي بسهم فمات منه بالمدينة، فقالت عاتكة ترثية:"],[39546,"رزئت بخير الناس بعد نبيهم … وبعد أبي بكر وما كان قصرا فآليت لا تنفك عيني حزينة … عليك ولا ينفك جلدي أغبرا"],[39547,"فلله عينا من رأى مثله فتى … أكر وأحمى في الهياج وأصبرا"],[39548,"إذا شرعت فيه الأسنة خاضها … إلى الموت حتى يترك الرمح أحمرا"],[39549,"فتزوجها زيد بن الخطاب، وقيل: لم يتزوجها، وقتل عنها يوم اليمامة شهيدا، فتزوجها عمر بن الخطاب سنة اثنتي عشرة، فأولم عليها، فدعا جمعا فيهم علي بن أبي طالب، فقال: يا أمير المؤمنين، دعني أكلم عاتكة."],[39550,"قال: افعل فأخذ بجانبي الباب، وقال: يا عدية نفسها، أين قولك:"],[39551,"فآليت لا تنفك عيني حزينة … عليك ولا ينفك جلدي أغبرا"],[39552,"فبكت، فقال عمر: ما دعاك إلى هذا يا أبا الحسن؟ كل النساء يفعلن هذا، فقال: قال الله تعالى: ﴿يَأَيُّهَا الَّذِينَ آمَنُوا لِمَ تَقُولُونَ مَا لا تَفْعَلُونَ كَبُرَ مَقْتًا عِنْدَ اللَّهِ أَنْ تَقُولُوا مَا لا تَفْعَلُونَ﴾."],[39553,"فقتل عنها عمر فقالت ترثيه:"],[39554,"عين جودي بغبرة ونحيب … لا تملي على الإمام النحيب"],[39555,"قل لأهل الضراء والبؤس موتوا … قد سقته المنون كأس شعوب"],[39556,"ثم تزوجها الزبير بن العوام، فقتل عنها، فقالت ثريته:"],[39557,"غدر ابن جرموز بفارس بهمة … يوم اللقاء وكان غير معرد"],[39558,"يا عمرو لو نبهته لوجدته … لا طائشا رعش الجنان ولا اليد"],[39559,"كم غمرة قد خاضها لم يثنه … عنها طرادك يا ابن فقع القردد"],[39560,"ثكلتك أمك إن طفرت بمثله … فمن مضى فمن يروح ويغتدي"],[39561,"والله ربك إن قتلت لمسلما … حلت عليك عقوبة المتعمد"],[39562,"ثم خطبها علي بن أبي طالب، فقالت: يا أمير المؤمنين، أنت بقية الناس وسيد المسلمين، وإني أنفس بك عن الموت."],[39563,"فلم يتزوجها، وكانت تحضر صلاة الجماعة في المسجد، فلما خطبها عمر شرطت عليه أن لا يمنعها عن المسجد ولا يضربها، فأجابها على كره منه، فلما خطبها الزبير ذكرت له ذلك، فأجابها إليه أيضا، فلما أرادت الخروج إلى المسجد للعشاء الآخرة شق ذلك عليك ولم يمنعها، فلما عيل صبره خرج ليلة إلى العشاء وسبقها، وقعد لها على الطريق بحيث لا تراه، فلما مرت ضرب بيده على عجزها، فنفرت من ذلك ولم تخرج بعد."],[39564,"أخرجها الثلاثة."],[39565,"٧٠٨٨ - عاتكة بنت عبد المطلب"],[39566,"ب د ع: عاتكة بنت عبد المطلب بن هاشم القرشية الهاشمية عمة رسول الله صلى الله عليه وآله وسلم. اختلف في إسلامها، فقال ابن إسحاق، وجماعة من العلماء: لم يسلم من عمات النبي صلى الله عليه وآله وسلم غير صفية."],[39567,"وكانت عاتكة عند أبي أميمة بن المغيرة المخزومي أبي أم سلمة، وهي أم ابنة عبد الله بن أبي أمية، وأم زهير وقريبة."],[39568,"روت عنها أم كلثوم بنت عقبة بن أبي معيط، وغيرها."],[39569,"أخبرنا عبيد الله بن أحمد، بإسناده، عن يونس، عن ابن إسحاق، قال: حدثني حسين بن عبد الله بن عبيد بن عباس، عن عكرمة، عن ابن عباس."],[39570,"ح قال: وحدثني يزيد بن رومان، عن عروة بن الزبير، قال: «رأت عاتكة بنت عبد المطلب فيما يرى النائم قبل مقدم ضمضم بن عمرو الغفاري على قريش مكة بثلاث ليال رؤيا فأصبحت عاتكة فبعثت إلى أخيها العباس، فقالت: يا أخي، لقد رأيت الليلة رؤيا: ليدخلن على قومك منها شر وبلاء! فقال: وما هي؟ فقالت: رأيت فيما يرى النائم رجلا أقبل على بعير له فوقف بالأبطح، فقال: انفروا يا آل غدر، لمصارعكم في ثلاث."],[39571,"فأرى الناس اجتمعوا إليه، ثم أرى بعيره دخل به المسجد، واجتمع الناس إليه، ثم مثل به بعيره، فإذا هو على رأس الكعبة فقال: انفروا يا آل غدر، لمصارعكم في ثلاث، ثم أرى بعيره مثل به على رأس أبي قبيس فقال: انفروا يا آل غدر، لمصارعكم في ثلاث، ثم أخذ صخرة فأرسلها من رأس الجبل، فأقبلت تهوي، حتى إذا كانت في أسفله ارفضت فما بقيت دار من دور قومك، ولا بيت إلا دخل فيها بعضها، فقال العباس: اكتميها، قالت: وأنت فاكتمها، فخرج العباس من عندها فلقي الوليد بن عتبة وكان له صديقا فذكرها له واستكتمه إياها، فذكرها الوليد لأبيه، فتحدث بها، ففشا الحديث، فقال العباس: والله إني لغاد إلى الكعبة لأطوف بها، فإذا أبو جهل في نفر يتحدثون عن رؤيا عاتكة، فقال أبو جهل: يا أبا الفضل متى حدثت فيكم هذه النبية؟ فقلت: وما ذاك؟ قال: رؤيا عاتكة بنت عبد المطلب، أما رضيتم أن تنبأ رجالكم حتى تنبأت نساؤكم؟! سنتربص بكم الثلاث التي ذكرت عاتكة، فإن كان حقا فسيكون، وإلا كتبنا عليكم كتابا أنكم أكذب أهل بيت في العرب! فأنكرت وقلت: ما رأت شيئا."],[39572,"فلما أمسيت لم تبق امرأة من بني عبد المطلب إلا أتتني فقلن: صبرتم لهذا الفاسق الخبيث أن يقع في رجالكم، ثم قد تناول النساء، وأنت تسمع، فلم يكن عندك غيرة؟! فقلت: قد والله صدقتن، ولا تعرضن له، فإن عاد لأكفينكنه."],[39573,"فغدوت في اليوم الثالث أتعرض له ليقول شيئا أشاتمه، فوالله إني لمقبل نحوه إذ ولى نحو باب المسجد يشتد، فقلت في نفسي: اللهم العنه، أكل هذا فرقا أن أشاتمه! وإذا هو قد سمع ما لم أسمع صوت ضمضم بن عمرو وهو واقف على بعيره بالأبطح، حتى حول رحله، وشق قميصه، وجدع بعيره، يقول: يا معشر قريش، اللطيمة اللطيمة، أموالكم أموالكم مع أبي سفيان، قد عرض لها محمد وأصحابه، الغوث الغوث."],[39574,"فشغله ذلك عني، وشغلني عنه، فلم يكن إلا الجهاز، حتى خرجنا إلى بدر، فأصاب قريشا ما أصابها ببدر، وصدق الله سبحانه وتعالى رؤيا عاتكة»."],[39575,"أخرجه الثلاثة"],[39576,"٧٠٨٩ - عاتكة بنت عوف"],[39577,"ب: عاتكة بنت عوف بن عبد عوف بن عبد الحارث بن زهرة القرشية الزهرية أخت عبد الرحمن بن عوف، وهي أم المسور بن مخرمة."],[39578,"هاجرت هي وأختها الشفاء، فهي من المهاجرات."],[39579,"أخرجها أبو عمر."],[39580,"٧٠٩٠ - عاتكة بنت نعيم"],[39581,"ب د ع: عاتكة بنت نعيم بن عبد الله العدوية قاله أبو نعيم."],[39582,"وقال أبو عمر: الأنصارية."],[39583,"روى عبد الله بن عقبة، عن أبي الأسود، عن حميد بن نافع، عن زينب بنت أبي سلمة، عن عاتكة بنت نعيم أخت عبد الله بن نعيم أنها جاءت رسول الله صلى الله عليه وآله وسلم فقالت: إن ابنتها توفي زوجها، فحدت عليه، فرمدت رمدا شديدا، وقد خشيت على بصرها، هل تكتحل؟ قال: «إنما هي أربعة أشهر وعشر، وقد كانت المرأة منكن تحد سنة ثم تخرج فترمى بالبعرة على رأس الحول»."],[39584,"وقد روي ولم تسم المرأة."],[39585,"أخبرنا غير واحد، بإسنادهم عن الترمذي، قال: حدثنا الأنصاري، حدثنا معن، عن مالك، عن عبد الله بن أبي بكر بن محمد بن عمرو بن حزم، عن حميد بن نافع، عن زينب بنت أبي سلمة، عن أمها أم سلمة، قالت: «جاءت امرأة إلى النبي صلى الله عليه وآله وسلم فقالت: يا رسول الله، إن ابنتي توفي عنها زوجها»."],[39586,"وذكر نحوه."],[39587,"ورواه ابن لهيعة، عن محمد بن عبد الرحمن، عن القاسم بن محمد، عن زينب، عن أمها أم سلمة، أن ابنة نعيم بن عبد الله العدوي أتت النبي صلى الله عليه وآله وسلم. وذكر نحوه."],[39588,"أخرجها الثلاثة. قلت: قول أبي عمر أنها أنصارية ليس بشيء، إنما هي عدوية، عدي قريش، وهي ابنة نعيم بن عبد الله بن النحام، وهو الصواب."],[39589,"٧٠٩١ - عاتكة بنت الوليد"],[39590,"س: عاتكة بنت الوليد بن المغيرة المخزومية وهي أخت خالد بن الوليد."],[39591,"وهي امرأة صفوان بن أمية الجمحي، وكان عند صفوان ست نسوة إحداهن عاتكة فلما أسلم طلق منهن اثنتين، وبقيت عنده عاتكة، فطلقها أيام عمر بن الخطاب."],[39592,"ويرد تمام الخبر بذلك في أم وهب."],[39593,"أخرجها أبو موسى."],[39594,"٧٠٩٢ - العالية بنت ظبيان"],[39595,"ب د ع: العالية بنت ظبيان بن عمرو بن عوف بن عبد بن أبي بكر بن كلاب الكلابية تزوجها رسول الله صلى الله عليه وآله وسلم فكانت عنده ما شاء الله، ثم طلقها."],[39596,"وقليل من العلماء يذكرها، قاله أبو عمر."],[39597,"وقال ابن منده، وأبو نعيم: إنه طلقها ولم يدخل بها، وإنها تزوجت قبل أن يحرم الله عز وجل نساءه ابن عم لها من قومها، فولدت فيهم، وقيل: إنها هي التي رأى بها بياضا فطلقها."],[39598,"روى أبو نعيم هذا من حديث سعيد بن أبي عروبة، وروى عن الزهري، أن النبي صلى الله عليه وآله وسلم طلق العالية بنت ظبيان، فتزوجها ابن عم لها، وذلك قبل أن يحرم الله على الناس نكاحهن."],[39599,"وقال يحيى بن أبي كثير: تزوج رسول الله صلى الله عليه وآله وسلم امرأة من ربيعة، يقال لها العالية بنت ظبيان، فطلقها حين أدخلت عليه."],[39600,"وقال عبد الله بن محمد بن عقيل: تزوج رسول الله صلى الله عليه وآله وسلم امرأة من بني عمرو بن كلاب، وفارقها."],[39601,"أخرجها الثلاثة."],[39602,"٧٠٩٣ - عائشة بنت أبي بكر الصديق"],[39603,"ب د ع: عائشة بنت أبي بكر الصديق الصديقة بنت الصديق أم المؤمنين، زوج النبي صلى الله عليه وآله وسلم وأشهر نسائه، وأمها أم رومان ابنة عامر بن عويمر بن عبد شمس بن عتاب بن أذينة بن سبيع بن دهمان بن الحارث بن غنم بن مالك بن كنانة الكنانية."],[39604,"تزوجها رسول الله صلى الله عليه وآله وسلم قبل الهجرة بسنتين، وهي بكر، قاله أبو عبيدة، وقيل: بثلاث سنين."],[39605,"وقال الزبير: تزوجها رسول الله صلى الله عليه وآله وسلم بعد خديجة بثلاث سنين."],[39606,"وتوفيت خديجة قبل الهجرة بثلاث سنين، وقيل: بأربع سنين، وقيل: بخمس سنين وكان عمرها لما تزوجها رسول الله صلى الله عليه وآله وسلم ست سنين، وقيل: سبع سنين."],[39607,"وبنى بها وهي بنت تسع سنين بالمدينة."],[39608,"وكان جبريل عليه السلام قد عرض على رسول الله صلى الله عليه وآله وسلم صورتها في سرقة حرير في المنام، لما توفيت خديجة، وكناها رسول الله صلى الله عليه وآله وسلم أم عبد الله، بابن أختها عبد الله بن الزبير."],[39609,"أخبرنا يحيى بن محمود، فيما أذن لي، بإسناده عن ابن أبي عاصم، قال: حدثنا سعيد بن يحيى بن سعيد، حدثنا أبي، عن محمد بن عمرو، عن يحيى بن عبد الرحمن بن حاطب، عن عائشة، قالت: لما توفيت خديجة، قالت خولة بنت حكيم بن الأوقص امرأة عثمان بن مظعون وذلك بمكة: أي رسول الله، ألا تزوج؟ قال: «ومن؟»، قلت: إن شئت بكرا، وإن شئت ثيبا."],[39610,"قال: «فمن البكر؟» قالت: ابنة أحب خلق الله إليك: عائشة بنت أبي بكر."],[39611,"قال: «ومن الثيب؟» قالت: سودة بنت زمعة بن قيس، آمنت بك واتبعتك على ما أنت عليه."],[39612,"قال: «فاذهبي فاذكريهما علي»."],[39613,"فجاءت فدخلت بيت أبي بكر، فوجدت أم رومان أم عائشة، فقالت: أي أم رومان، ما أدخل الله عليكم من الخير والبركة، قالت: وما ذاك؟ قالت: أرسلني رسول الله صلى الله عليه وآله وسلم أخطب عليه عائشة، قالت: وددت، انتظري أبا بكر، فإنه آت."],[39614,"فجاء أبو بكر، فقالت: يا أبا بكر، ماذا أدخل الله عليكم من الخير والبركة، قال: وما ذاك؟ قالت: أرسلني رسول الله صلى الله عليه وآله وسلم أخطب عليه عائشة."],[39615,"قال: وهل تصلح له، إنما هي بنت أخيه، فرجعت إلى رسول الله صلى الله عليه وآله وسلم فذكرت ذلك له، فقال: «ارجعي وقولي له، أنت أخي في الإسلام، وابنتك تصلح لي»."],[39616,"فأتت أبا بكر، فقال: ادعي لي رسول الله صلى الله عليه وآله وسلم فجاء فأنكحه، وهي يومئذ بنت ست سنين، وقال رسول الله صلى الله عليه وآله وسلم: «ومن الثيب؟»، قالت: سودة بنت زمعة، قد آمنت بك واتبعتك."],[39617,"قال: «اذهبي فاذكريها علي»."],[39618,"قالت: فخرجت فدخلت على سودة، فقالت: يا سودة، ما أدخل الله عليكم من الخير والبركة، قالت: وما ذاك؟ قالت: أرسلني رسول الله صلى الله عليه وآله وسلم أخطبك عليه، قالت: وددت، أدخلي على أبي فاذكري ذلك له، قالت: وهو شيخ كبير قد تخلف عن الحج فدخلت عليه، فقلت: إن محمد بن عبد الله أرسلني أخطب عليه سودة، قال: كفء كريم، فماذا تقول صاحبتك؟ قالت: تحب ذلك، قال: ادعيها، فدعتها، فقال: إن محمد بن عبد الله أرسل يخطبك وهو كفء كريم، أفتحبين أن أزوجك؟ قالت: نعم، قال: فادعيه لي، فدعته فجاء فزوجها، وجاء أخوها عبد بن زمعة من الحج فجعل يحثو التراب على رأسه، وقال بعد أن أسلم: إني لسفيه يوم أحثو التراب على رأسي أن تزوج رسول الله صلى الله عليه وآله وسلم سودة"],[39619,"أخبرنا أبو الفرج بن أبي الرجاء، حدثنا أبو علي الحداد، وأنا حاضر أسمع، أخبرنا أحمد بن عبد الله الحافظ، حدثنا فاروق، حدثنا محمد بن محمد بن حبان التمار، حدثنا عبد الله بن مسلمة القعنبي، حدثنا سليمان بن بلال، عن أبي طوالة، عن أنس بن مالك، قال: قال رسول الله صلى الله عليه وآله وسلم: «فضل عائشة على النساء كفضل الثريد على سائر الطعام»"],[39620,"أخبرنا محمد بن سرايا بن علي العدل والحسين بن أبي صالح بن فناخسرو، وغيرهما، بإسنادهم، عن محمد بن إسماعيل، حدثنا عبد الله بن عبد الوهاب، حدثنا حماد، حدثنا هشام، عن أبيه، قال: كان الناس يتحرون بهداياهم يوم عائشة، قالت: فاجتمع صواحبي إلى أم سلمة فقالوا: يا أم سلمة، إن الناس يتحرون بهداياهم يوم عائشة، وإنا نريد من الخير كما تريد عائشة، فمري رسول الله صلى الله عليه وآله وسلم أن يأمر الناس أن يهدوا إليه حيثما كان أو حيث ما دار قالت: فذكرت ذلك أم سلمة للنبي، قالت: فأعرض عني فلما عاد إلي ذكرت له ذلك، فأعرض عني، فلما كان في الثالثة ذكرت له ذلك، فقال: «يا أم سلمة، لا تؤذيني في عائشة، فإنه والله ما نزل علي الوحي وأنا في لحاف امرأة منكن غيرها»"],[39621,"قال:"],[39622,"وحدثنا محمد بن إسماعيل، حدثنا يحيى بن بكير، حدثنا الليث، عن يونس، عن ابن شهاب، قال: قال أبو سلمة، أن عائشة، قالت: قال رسول الله صلى الله عليه وآله وسلم: «يا عائش، هذا جبريل عليه السلام يقرئك السلام»، فقالت: وعليه السلام ورحمة الله وبركاته، ترى ما لا أرى"],[39623,"أخبرنا إسماعيل بن علي وإبراهيم بن محمد، وغيرهما، بإسنادهم عن محمد بن عيسى، قال: حدثنا عبد بن حميد، حدثنا عبد الرزاق، عن عبد الله بن عمرو بن علقمة الملكي، عن ابن أبي حسين، عن ابن أبي مليكة، عن عائشة، «أن جبريل عليه السلام جاء بصورتها في خرقة حرير خضراء إلى النبي صلى الله عليه وآله وسلم فقال: هذه زوجتك في الدنيا والآخرة»"],[39624,"قال: وحدثنا محمد بن عيسى، حدثنا بندار وإبراهيم بن يعقوب، قالا: حدثنا يحيى بن حماد، حدثنا عبد العزيز بن المختار، أخبرنا خالد الحذاء، عن أبي عثمان النهدي، عن عمرو بن العاص، أن رسول الله صلى الله عليه وآله وسلم استعمله على جيش ذات السلاسل، قال: فأتيته فقلت: يا رسول الله، «أي الناس أحب إليك؟ قال: عائشة»، قلت: «من الرجال؟ قال: أبوها»"],[39625,"قال: وحدثنا محمد بن عيسى، حدثنا محمد بن بشار، حدثنا عبد الرحمن بن مهدي، حدثنا سفيان، عن أبي إسحاق، عن عمرو بن غالب: «أن رجلا نال من عائشة رضي الله عنها عند عمار بن ياسر، فقال: اعزب مقبوحا منبوحا أتؤذي حبيبة رسول الله صلى الله عليه وآله وسلم» وكان مسروق إذا روى عنها يقول: حدثتني الصديقة بنت الصديق، البريئة المبرأة."],[39626,"وكان أكابر الصحابة يسألونها عن الفرائض، وقال عطاء بن أبي رباح: كانت عائشة من أفقه الناس وأحسن الناس رأيا في العامة."],[39627,"وقال عروة: ما رأيت أحدا أعلم بفقه ولا بطب ولا بشعر من عائشة، ولو لم يكن لعائشة من الفضائل إلا قصة الإفك لكفى بها فضلا وعلو مجد، فإنها نزل فيها من القرآن ما يتلى إلى يوم القيامة."],[39628,"ولولا خوف التطويل لذكرنا قصة الإفك بتمامها، وهي أشهر من أن تخفى."],[39629,"أخبرنا مسمار بن عمر بن العويس وأبو الفرج محمد بن عبد الرحمن بن أبي العز، وغيرهما، بإسنادهم، عن محمد بن إسماعيل، حدثنا محمد بن بشار، حدثنا عبد الوهاب بن عبد المجيد، حدثنا ابن عون، عن القاسم بن محمد، «أن عائشة اشتكت فجاء ابن عباس، فقال: يا أم المؤمنين تقدمين على فرط صدق، على رسول الله صلى الله عليه وآله وسلم وعلى أبي بكر» وروت عن النبي صلى الله عليه وآله وسلم كثيرا، روى عنها عمر ابن الخطاب وكثير من الصحابة، ومن التابعين ما لا يحصى."],[39630,"روى يحيى بن أيوب، عن عبيد الله بن زحر، عن علي بن زيد، عن القاسم، عن أبي أمامة، أن عمر بن الخطاب، قال: أدنوا الخيل وانتضلوا وانتعلوا، وإياكم وأخلاق الأعاجم، وأن تجلسوا على مائدة يشرب عليها الخمر، ولا يحل لمؤمن ولا مؤمنة تدخل الحمام إلا بمئزر إلا من سقم، فإن عائشة حدثتني أن رسول الله صلى الله عليه وآله وسلم قال وهو على فراشي: «أيما امرأة مؤمنة وضعت خمارها على غير بيتها، هتكت الحجاب بينها وبين ربها عز وجل»."],[39631,"وتوفيت عائشة سنة سبع وخمسين، وقيل: سنة ثمان وخمسين ليلة الثلاثاء لسبع عشرة ليلة خلت من رمضان، وأمرت أن تدفع بالبقيع ليلا، فدفنت وصلى عليها أبو هريرة رضي الله عنه، ونزل في قبرها خمسة: عبد الله، وعروة، ابنا الزبير، والقاسم بن محمد بن أبي بكر، وعبد الله بن محمد بن أبي بكر، وعبد الله بن عبد الرحمن بن أبي بكر، ولما توفي النبي صلى الله عليه وآله وسلم كان عمرها ثمان عشرة سنة."],[39632,"أخرجها الثلاثة."],[39633,"٧٠٩٤ - عائشة بنت جرير"],[39634,"عائشة بنت جرير بن عمرو بن عبد رزاح زوجة أبي المنذر السلمي، من بني سلمة من الأنصار."],[39635,"وأبو المنذر بدري مات في خلافة عمر رضي الله عنه، وأسمه: يزيد بن عامر بن حديدة."],[39636,"بايعت عائشة رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39637,"٧٠٩٥ - عائشة بنت الحارث"],[39638,"ب س: عائشة بنت الحارث بن خالد بن صخر القرشية التيمية ولدت هي وأختاها فاطمة وزينب بأرض الحبشة، ولما عادوا من أرض الحبشة شربوا ماء فهلكوا منه، فماتت عائشة وأختها زينب وأمها ريطة، وأخوهما موسى من ذلك الماء، ونجت أختهم فاطمة."],[39639,"قاله ابن إسحاق."],[39640,"أخرجها أبو عمر، وأبو موسى."],[39641,"٧٠٩٦ - عائشة بنت أبي سفيان"],[39642,"عائشة بنت أبي سفيان بن الحارث بن زيد الأنصارية الأشهلية بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39643,"٧٠٩٧ - عائشة بنت عبد الرحمن"],[39644,"س: عائشة بنت عبد الرحمن بن عتيك النضيري تقدم ذكرها في ترجمة زوجها رفاعة."],[39645,"أخرجها أبو موسى مختصرا."],[39646,"٧٠٩٨ - عائشة بنت عجرد"],[39647,"س: عائشة بنت عجرد روى يحيى بن معين."],[39648,"أن أبا حنيفة الفقيه صاحب الرأي سمع عائشة تقول: سمعت رسول الله صلى الله عليه وآله وسلم يقول: «أكثر جنود الله تعالى في الأرض الجراد، لا آكله ولا أحرمه»."],[39649,"وقد روى عن أبي حنيفة، عن عثمان بن راشد، عن عائشة بنت عجرد، عن ابن عباس."],[39650,"وهي من التابعين، ذكرها كثير من العلماء فيهم."],[39651,"أخرجها أبو موسى."],[39652,"٧٠٩٩ - عائشة بنت عمير"],[39653,"عائشة بنت عمير بن الحارث بن ثعلبة الأنصارية ثم من بني حرام."],[39654,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39655,"٧١٠٠ - عائشة بنت قدامة"],[39656,"ب د ع: عائشة بنت قدامة بن مظعون القرشية الجمحية هي وأمها رائطة بنت سفيان الخزاعية من المبايعات."],[39657,"أخبرنا عبد الوهاب بن أبي حبة، بإسناده عن عبد الله بن أحمد، حدثني أبي، حدثنا إبراهيم ابن أبي العباس ويونس المعني، قالا: حدثنا عبد الرحمن يعني: ابن عثمان بن إبراهيم بن محمد بن حاطب، قال: حدثني أبي، عن أمه عائشة، قالت: كنت مع أمي رائطة بنت سفيان والنبي يبايع النساء، ويقول: أبايعكن على أن لا تشركن بالله شيئا، ولا تسرقن ولا تزنين، ولا تقتلن أولادكن، ولا تأتين ببهتان تفترينه بين أيديكن وأرجلكن، ولا تعصينني في معروف."],[39658,"قالت: فأطرقن، فقال رسول الله صلى الله عليه وآله وسلم: «قلن نعم فيما استطعتن» فكن يقلن، وأقول معهن، وأمي تلقنني: قولي أي بنية له: نعم فيما استطعت."],[39659,"فكنت أقول كما يقلن."],[39660,"أخرجه الثلاثة"],[39661,"٧١٠١ - عبادة بنت أبي نائلة"],[39662,"عبادة بنت أبي نائلة بن سلامة بن وقش بن زغبة بن زعوراء بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39663,"٧١٠٢ - عتبة بنت زرارة"],[39664,"عتبة بنت زرارة بن عدس الأنصارية بايعت رسول الله صلى الله عليه وآله وسلم."],[39665,"قاله ابن حبيب."],[39666,"٧١٠٣ - العجماء الأنصارية"],[39667,"د ع: العجماء الأنصارية خالة أبي أمامة بن سهل بن حنيف"],[39668,"روى سعيد بن أبي هلال، عن مروان بن عثمان، عن أبي أمامة، عن خالته العجماء، قالت سمعت رسول الله صلى الله عليه وآله وسلم يقول: «الشيخ والشيخة إذا زنيا فارجموهما ألبتة، بما قضيا من اللذة»."],[39669,"أخرجها ابن منده، وأبو نعيم."],[39670,"٧١٠٤ - عجوز من بني نمير"],[39671,"عجوز من بني نمير روى عنها أبو السليل أنها رمقت النبي صلى الله عليه وآله وسلم وهو يصلي بالأبطح، تجاه البيت قبل الهجرة، قالت: فسمعته يقول: «اللهم اغفر لي ذنبي، خطئي وجهلي»."],[39672,"وقد تقدم في العين في عجوز ابن نمير أتم من هذا."],[39673,"٧١٠٥ - عذبة بنت سعد"],[39674,"عذبة بنت سعد بن خليفة بن الأشرف الأنصارية من بني طريف بن الخزرج ابن ساعدة، وهي أم سعيد بن سعد."],[39675,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39676,"٧١٠٦ - عزة الأشجعية"],[39677,"ب د ع: عزة الأشجعية مولاة أبي حازم من قومه."],[39678,"روى أشعث بن سوار، عن منصور، عن أبي حازم، عن مولاته عزة، قالت: سمعت رسول الله صلى الله عليه وآله وسلم يقول: «ويلكن من الأحمرين: الذهب والزعفران»."],[39679,"أخرجها الثلاثة."],[39680,"٧١٠٧ - عزة بنت الحارث"],[39681,"ب: عزة بنت الحارث أخت ميمونة، ولبابة ابنتي الحارث، تقدم نسبها."],[39682,"أخرجها أبو عمر مختصرا، قال: ولم أر أحدا ذكرها في الصحابة، وأظنها لم تدرك الإسلام."],[39683,"٧١٠٨ - عزة بنت خابل"],[39684,"ب د ع: عزة بنت خابل الخزاعية بايعت النبي صلى الله عليه وآله وسلم"],[39685,"أخبرنا يحيى بن محمود، إجازة، بإسناده عن ابن أبي عاصم، حدثنا دحيم، حدثنا ابن أبي فديك، عن موسى بن يعقوب، عن عطاء بن مسعود الكعبي، عن عمته عزة بنت خايل، أخبرته «أنها خرجت حتى قدمت على رسول الله صلى الله عليه وآله وسلم فبايعها على أن لا تزنين، ولا تسرقين، ولا تؤذين فتبدين أو تخفين، قالت عزة: فأما الإيذاء فقد كانت عرفته وعلمته، وهو قتل الولد، وأما المخفى فلم أسأل عنه رسول الله صلى الله عليه وآله وسلم ولم يخبرني به، وقد وقع في نفسي أنه إفساد الولد، فوالله لا أفسد لي ولدا أبدا، فلم تفسد لها ولدا حتى ماتت»."],[39686,"يعني: الغيل."],[39687,"أخرجه الثلاثة، إلا أن أبا عمر قال: عزة بنت كامل بالكاف، وقد ذكره مسلم: خابل بالخاء، كما ذكره ابن منده، وأبو نعيم، وهو الصواب"],[39688,"٧١٠٩ - عزة بنت أبي سفيان"],[39689,"ب س: عزة بنت أبي سفيان صخر بن حرب بن أمية القرشية الأموية أخت أم حبيبة، ومعاوية."],[39690,"روى الليث، عن يزيد بن أبي حبيب، أن محمد بن مسلم هو الزهري كتب يذكر أن عروة حدثه، أن زينب بنت أبي سلمة حدثته، أن أم حبيبة، حدثتها أنها قالت: يا رسول الله، أنكح أختي عزة، فقال رسول الله صلى الله عليه وآله وسلم: «أتحبين ذلك؟» قالت: نعم، لست لك بمخلية، وأحب من شركني أختي، فقال رسول الله صلى الله عليه وآله وسلم: «فإن تلك لا تحل لي»، وقيل: اسمها درة، وقيل: حمنة."],[39691,"وقد ذكرناها."],[39692,"أخرجها أبو عمر، وأبو موسى."],[39693,"٧١١٠ - عصمة بنت حبان"],[39694,"عصمة بنت حبان بن صخر بن خنساء الأنصارية ثم من بني حرام بايعت النبي صلى الله عليه وآله وسلم قاله ابن حبيب."],[39695,"٧١١١ - عفراء بنت السكن"],[39696,"عفراء بنت السكن بن رافع بن معاوية بن عبيد بن الأبجر أم سعد بن زرارة الأنصارية الخزرجية ثم النجارية."],[39697,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39698,"٧١١٢ - عفراء بنت عبيد"],[39699,"عفراء بنت عبيد بن ثعلبة بن سواد بن غنم بن مالك بن النجار الأنصارية أم معاذ ومعوذ وعوف، وبها تعرف أولادها، وكلهم من الأنصار."],[39700,"قال ابن الكلبي: قتل معاذ ومعوذ يومئذ يعني: يوم بدر فجاءت أمهما إلى النبي صلى الله عليه وآله وسلم فقالت لعوف ابنها: يا رسول الله، هذا شر بني فقال: «لا»."],[39701,"ولم يعقب معاذ ومعوذ، وإنما الولد لعوف."],[39702,"وقال غير الكلبي: إن معاذ لم يقتل يوم بدر على ما ذكرناه في اسمه، والله أعلم وبايعت أمه النبي صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39703,"٧١١٣ - عقرب بنت سلامة"],[39704,"عقرب بنت سلامة بن وقش بن زغبة بن زعوراء بن عبد الأشهل الأنصارية الأشهلية بايعت رسول الله."],[39705,"قاله ابن حبيب."],[39706,"٧١١٤ - عقرب بنت معاذ"],[39707,"عقرب بنت معاذ بن النعمان بن امرئ القيس بن زيد بن عبد الأشهل وهي أم رافع بن يزيد الأشهلي، ويزيد وثابت ابني قيس ابن الخطيم."],[39708,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39709,"٧١١٥ - عقيلة بنت عبيد"],[39710,"ب ع س: عقيلة بنت عبيد بن الحارث العتوارية كانت من المهاجرات والمبايعات."],[39711,"مدنية."],[39712,"روت عنها ابنتها حجة بنت قريط، وقيل: حجية بنت قرطة."],[39713,"وروى عن ابنتها حجية زيد بن عبد الرحمن بن أبي سلامة وقيل: ابن سلامة وهي أمه."],[39714,"أوردها البخاري والطبراني بالعين المهلمة والقاف، وأوردها ابن منده بالعين المعجمة والفاء."],[39715,"أخرجها ههنا أبو نعيم، وأبو عمر، وأبو موسى."],[39716,"٧١١٦ - عكناء بنت أبي صفرة"],[39717,"د ع: عكناء أو عكثاء بنت أبي صفرة أخت المهلب بن أبي صفرة."],[39718,"روى هشام بن سفيان، عن عبيد الله بن عبد الله، عن أبي الشعثاء، قال: قالت عكناء أو عكثاء بنت أبي سفرة، أخت المهلب، إن رسول الله صلى الله عليه وآله وسلم «أمر بصوم عاشوراء»، يوم العاشر من المحرم."],[39719,"قال: وسألته عن أبي الشعثاء، قال: شيخ مجهول، وليس هو جابر بن زيد."],[39720,"أخرجه ابن منده، وأبو نعيم."],[39721,"٧١١٧ - علاثة"],[39722,"س: علاثة أوردها جعفر المستغفري هكذا عن الخليل بن أحمد، عن محمد بن إسحاق، عن قتيبة، عن يعقوب بن عبد الرحمن، عن أبي حازم بن دينار، أن رجالا أتوا سهل بن سعد، وقد امتروا في المنبر: مم عوده؟ فسألوه عن ذلك، فقال: والله إني لا أعرف مم هو، ولقد رأيته أول يوم وضع وأول يوم جلس عليه رسول الله صلى الله عليه وآله وسلم أرسل إلى علاثة امرأة قد سماها سهل بن سعد: «أن مري غلامك النجار أن يعمل لي أعوادا أجلس عليها إذا كلمت الناس»."],[39723,"أورده جعفر في حرف العين، وقد صحفه هو أو شيخه الخليل، فإن محمد بن إسحاق ومن فوقه أحفظ من أن يخفى عليهم هذا، إنما هو: أرسل رسول الله إلى فلانة، امرأة لم يعرف اسمها، فصحف فلانة بعلاثة."],[39724,"أخرجه أبو موسى، وأمثال هذا لو أضرب أبو موسى عنه لكان أحسن من ذكره، فإن التصحيف كثير، فإن كان كل تصحيف وغلط يذكر، فقد فاته أضعاف ما ذكر، ولولا الاقتداء به لما ذكرناه."],[39725,"٧١١٨ - علية بنت شريح"],[39726,"علية بنت شريح الحضرمي أخت السائب بن يزيد بن أخت التمر."],[39727,"وهي أخت مخرمة بن شريح، الذي ذكر عند النبي صلى الله عليه وآله وسلم فقال: «ذاك رجل لا يتوسد القرآن»."],[39728,"أخرجها أبو عمر."],[39729,"علية: بضم العين، وفتح اللام، وتشديد الياء تحتها نقطتان."],[39730,"٧١١٩ - عمارة بنت حمزة بن عبد المطلب"],[39731,"س: عمارة بنت حمزة بن عبد المطلب القرشية الهاشمية ابنة عم النبي صلى الله عليه وآله وسلم روى الواقدي، عن أم حبيبة، عن داود بن الحصين، عن عكرمة، عن ابن عباس، قال: كانت عمارة بنت حمزة بن عبد المطلب وأمها سلمى بنت عميس بمكة، فلما قدم رسول الله صلى الله عليه وآله وسلم مكة في عمرة القضية، كلم علي بن أبي طالب النبي صلى الله عليه وآله وسلم فقال: علام نترك بنت عمنا بين ظهراني المشركين؟! فلم ينهه النبي صلى الله عليه وآله وسلم عن إخراجها، فخرج بها، فتكلم زيد بن حارثة وكان وصي حمزة، وكان رسول الله صلى الله عليه وآله وسلم قد آخى بينهما حين آخى بين المهاجرين فقال: «أنا أحق بابنة أخي»."],[39732,"وقال جعفر: «أنا أحق بها، فإن خالتها عندي»."],[39733,"وذكر الحديث."],[39734,"وقال الخطيب أبو بكر: انفرد الواقدي بتسمية عمارة في هذا الحديث، وسماها غيره أمامة، وذكر غير واحد من العلماء أن حمزة كان له ابن اسمه عمارة، وهو الصواب."],[39735,"أخرجها أبو موسى."],[39736,"٧١٢٠ - عمرة الأشهلية"],[39737,"د ع: عمرة الأشهلية غير منسوبة."],[39738,"حديثها، قالت: أتانا رسول الله صلى الله عليه وآله وسلم فصلى في مسجدنا الظهر والعصر، وكان صائما، فلما غربت الشمس وأذن المؤذن أتوه بفطره شواء كتف وذراع، فجعل ينهسها بأسنانه، ثم أقام المؤذن فمسح يده بخرقة، ثم قام فصلى، ولم يمس ماء."],[39739,"أخرجها ابن منده، وأبو نعيم."],[39740,"٧١٢١ - عمرة بنت أبي أيوب"],[39741,"عمرة بنت أبي أيوب خالد بن زيد الأنصارية وأبوها أبو أيوب مشهور."],[39742,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39743,"٧١٢٢ - عمرة بنت الجون"],[39744,"د: عمرة بنت الجون الكلابية لها ذكر في حديث عالية."],[39745,"وقد ذكرناها في عمرة بنت يزيد."],[39746,"أخرجها ابن منده."],[39747,"٧١٢٣ - عمرة بنت الحارث"],[39748,"ب د ع: عمرة بنت الحارث بن أبي ضرار الخزاعية المصطلقية تقدم نسبها عند ذكر أختها جويرية بنت الحارث."],[39749,"أخبرنا يحيى بن أبي الرجاء، إذنا، بإسناده عن أبي بكر أبي عاصم، حدثنا صلت بن مسعود الجحدري، حدثنا محمد بن خالد بن سلمة المخزومي، حدثنا أبي، عن محمد بن عمرو بن الحارث بن أبي ضرار، عن عمته عمرة بنت الحارث، أن النبي صلى الله عليه وآله وسلم قال: «الدنيا خضرة حلوة، فمن أصاب منها من شيء من حلة بورك فيه، ورب متخوض في مال الله ومال رسوله، له النار يوم القيامة»."],[39750,"أخرجه الثلاثة"],[39751,"٧١٢٤ - عمرة بنت حزم"],[39752,"ب د ع: عمرة بنت حزم الأنصارية قاله ابن منده، وأبو عمر."],[39753,"وقال أبو نعيم: عمرة بنت حرام."],[39754,"قال: وذكرها المتأخر: عمرة بنت حزم، وكانت تحت سعد بن الربيع فقتل عنها يوم أحد."],[39755,"روى يحيى بن أيوب، عن محمد بن ثابت البناني، عن محمد بن المنكدر، عن جابر، عن عمرة بنت حزم، «أنها جعلت النبي صلى الله عليه وآله وسلم في صور نخل كنسته ورشته، وذبحت له شاة، فأكل منها وتوضأ وصلى الظهر، ثم قدمت له من لحمها فأكل وصلى العصر ولم يتوضأ»."],[39756,"ورواه أبو نعيم، عن الطبراني، عن يحيى بن عثمان بن صالح، عن عمرو بن الربيع بن طارق، عن يحيى، بإسناده، وقال: عمرة بنت حرام."],[39757,"ورواه ابن منده، بإسناده عن محمد بن إسحاق الصاغاني، وأبي حاتم الرازي، عن عمرو بن الربيع، عن يحيى بن أيوب، عن محمد فقال: عمرة بنت حزم."],[39758,"وروى هذا الحديث عبد الله بن محمد بن عقيل، عن جابر، ولم يسمها."],[39759,"وذكرها ابن أبي عاصم فقال: بنت حزم."],[39760,"أخبرنا أبو الفرج بن محمود، إجازة، بإسناده إلى القاضي أبو بكر أحمد بن عمرو، حدثنا محمد بن سهل بن عسكر، حدثنا عمرو بن الربيع، حدثنا يحيى بن أيوب، عن محمد بن ثابت البناني، عن محمد بن المنكدر، عن جابر بن عبد الله، عن عمرة بنت حزم."],[39761,"وذكر نحوه."],[39762,"٧١٢٥ - عمرة بنت الربيع"],[39763,"عمرة بنت الربيع بن النعمان بن يساف الأنصارية الخزرجية من بني مالك بن النجار."],[39764,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39765,"٧١٢٦ - عمرة بنت رواحة"],[39766,"ب د ع: عمرة بنت رواحة أخت عبد الله بن رواحة، تقدم نسبها عند ذكر أخيها، وهي أم النعمان بن بشير، وهي التي سألت زوجها بشيرا أن يهب ابنها النعمان هبة دون إخوته، ففعل، فقالت له: أشهد على هذا رسول؟لله صلى الله عليه وآله وسلم. ففعل فقال له رسول الله صلى الله عليه وآله وسلم: «أكل بنيك أعطيته مثل هذا؟» قال: لا."],[39767,"قال: «فإني لا أشهد على جور»، وقيل: إن النبي صلى الله عليه وآله وسلم قال له: «أيسرك أن يكونوا في البر لك سواء؟»."],[39768,"قال: نعم."],[39769,"قال: «فلا آذن»."],[39770,"وهذه عمرة هي التي ذكرها قيس بن الخطيم في شعره بقوله:"],[39771,"أجد بعمرة غنيانها … فتهجر أم شأننا شأنها؟"],[39772,"فإن تمس شطت بها دارها … وباح لك اليوم هجرانها"],[39773,"وعمرة من سروات النساء … تنفخ بالمسك أردانها"],[39774,"وهي طويلة."],[39775,"أخبرنا عبد الله بن أبي نصر الخطيب، بإسناده عن أبي داود الطيالسي، حدثنا شعبة، عن محمد بن النعمان، عن طلحة اليامي، عن امرأة من عبد القيس، عن أخت عبد الله بن رواحة، أنها قالت: وجب الخروج على كل ذات نطاق .."],[39776,"ورواه عبد الله بن أحمد بن حنبل، عن أبيه، عن محمد بن جعفر، عن شعبة، عن محمد عن طلحة، عن امرأة من عبد القيس، عن أخت عبد الله بن رواحة."],[39777,"أخرجها الثلاثة"],[39778,"٧١٢٧ - عمرة بنت سعد"],[39779,"س: عمرة بنت سعد بن عمرو بن زيد مناة بن عدي بن عمرو بن مالك بن النجار أم سعد بن عبادة كذا سماها المستغفري، وقيل: عمرة بنت سعد بن قيس."],[39780,"وقال أبو عمر: عمرة بنت مسعود بن قيس بن عمرو بن زيد مناة بن عدي بن عمرو أم سعد بن عبادة، توفيت سنة خمس من الهجرة."],[39781,"وحديثها مشهور، ولم تسم في الحديث."],[39782,"أخرجها أبو موسى، وذكرها أبو عمر فقال: عمرة بنت مسعود بن قيس."],[39783,"ويرد ذكرها إن شاء الله تعالى."],[39784,"٧١٢٨ - عمرة بنت السعدي"],[39785,"س: عمرة بنت السعدي بن وقدان بن عبد شمس بن عبد ود بن نصر بن مالك بن حسل بن عامر بن لؤي امرأة مالك بن زمعة بن قيس بن عبد شمس بن عبد ود من بني عامر بن لؤي."],[39786,"هاجرت إلى أرض الحبشة."],[39787,"أخبرنا عبيد الله بن أحمد، بإسناده عن يونس، عن محمد بن إسحاق في تسمية من هاجر إلى أرض الحبشة: ومالك بن ربيعة بن قيس بن عبد شمس بن لؤي ومعه امرأته عمرة بنت السعدي."],[39788,"أخرجها أبو موسى"],[39789,"٧١٢٩ - عمرة بنت عويم"],[39790,"س: عمرة بنت عويم بن ساعدة قال جعفر: ذكرها البخاري."],[39791,"أخرجها أبو موسى مختصرا."],[39792,"٧١٣٠ - عمرة بنت قيس"],[39793,"عمرة بنت قيس بن عمرو وهي أم أبي شيخ بن ثابت، أخي حسان بن ثابت."],[39794,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39795,"٧١٣١ - عمرة بنت مرشدة"],[39796,"عمرة بنت مرشدة وهي أخت أسماء، بايعت هي وأختها النبي صلى الله عليه وآله وسلم"],[39797,"٧١٣٢ - عمرة بنت مسعود الظفرية"],[39798,"عمرة بنت مسعود بن أوس بن مالك بن سواد بن ظفر الظفرية الأنصارية كانت عند محمد بن مسلمة، فولدت له عبد الله."],[39799,"بايعت رسول الله صلى الله عليه وآله وسلم قاله ابن حبيب."],[39800,"٧١٣٣ - عمرة بنت مسعود بن الحارث"],[39801,"عمرة بنت مسعود بن الحارث بن رفاعة الأنصارية من بني مالك بن النجار."],[39802,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39803,"٧١٣٤ - عمرة بنت مسعود بن قيس"],[39804,"ب: عمرة بنت مسعود بن قيس بن عمرو بن زيد مناة بن عدي بن عمرو بن مالك بن النجار أم سعد بن عبادة."],[39805,"وكانت من المبايعات، توفيت في حياة رسول الله صلى الله عليه وآله وسلم سنة خمس من الهجرة."],[39806,"أخرجها أبو عمر، وأخرجها أبو موسى فقال: عمرة بنت سعد."],[39807,"وقد تقدم ذكرها."],[39808,"٧١٣٥ - عمرة بنت معاوية"],[39809,"ع: عمرة بنت معاوية الكندية روى محمد بن إسحاق، عن حكيم بن حكيم، عن محمد بن علي بن الحسين، عن أبيه، قال: «وتزوج رسول الله صلى الله عليه وآله وسلم عمرة بنت معاوية من كندة»."],[39810,"وروى مجالد، عن الشعبي، أن النبي صلى الله عليه وآله وسلم تزوج امرأة من كندة، فجيء بها بعد ما مات النبي صلى الله عليه وآله وسلم. أخرجها أبو نعيم."],[39811,"٧١٣٦ - عمرة بنت هزال"],[39812,"عمرة بنت هزال بن عمرو بن قرواش الأنصارية ثم من بني عوف بن الخزرج."],[39813,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39814,"٧١٣٧ - عمرة بنت يزيد الكلابية"],[39815,"ب: عمرة بنت يزيد بن الجون الكلابية وقيل عمرة بنت يزيد بن عبيد بن رواس بن كلاب الكلابية قاله أبو عمر، وقال: هذا أصح."],[39816,"تزوجها رسول الله صلى الله عليه وآله وسلم فبلغه أن بها برصا، فطلقها ولم يدخل بها."],[39817,"أخبرنا أبو جعفر، بإسناده عن يونس، عن ابن إسحاق، قال: وتزوج رسول الله صلى الله عليه وآله وسلم عمرة بنت يزيد إحدى نساء بني كلاب، ثم من بني الوحيد وكانت قبله عند الفضل بن العباس بن عبد المطلب، فطلقها رسول الله صلى الله عليه وآله وسلم قبل أن يدخل بها، وقيل: إنها التي تزوجها رسول الله صلى الله عليه وآله وسلم فاستعاذت منه حين دخلت عليه، فقال: «لقد عذت بمعاذ»."],[39818,"فطلقها، وأمر أسامة بن زيد فمتعها ثلاثة أثواب."],[39819,"رواه هشام بن عروة، عن أبيه، عن عائشة."],[39820,"وقال أبو عبيد: إنما قال ذلك لأسماء بنت النعمان بن الجون."],[39821,"وقال قتادة: إنما قال ذلك في امرأة من بني سليم."],[39822,"والاختلاف فيها كثير، على ما ذكرناه في اسمها."],[39823,"أخرجها أبو عمر"],[39824,"٧١٣٨ - عمرة بنت يزيد بن السكن"],[39825,"عمرة بنت يزيد بن السكن بن رافع بن امرئ القيس الأنصارية الأشهلية بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39826,"٧١٣٩ - عمرة بنت يسار"],[39827,"س: عمرة بنت يسار بن أزيهر لها صحبة، قاله جعفر."],[39828,"أخرجها أبو موسى مختصرا."],[39829,"٧١٤٠ - عمرة بنت يعار"],[39830,"ب: عمرة بنت يعار الأنصارية امرأة أبي حذيفة بن عتبة، مولى سالم."],[39831,"اختلف في اسمها."],[39832,"وقد ذكرناها في الثاء."],[39833,"أخرجها أبو عمر."],[39834,"٧١٤١ - عميرة بنت أبي الحكم"],[39835,"ع س: عميرة بزيادة ياء التصغير هي عميرة بنت أبي الحكم رافع بن سنان."],[39836,"أخبرنا أبو موسى، إجازة، أخبرنا أبو علي الحداد، أخبرنا أبو نعيم، حدثنا محمد بن إسحاق بن أيوب، حدثنا إبراهيم بن سعدان، حدثنا بكر ابن بكار، حدثنا عبد الحميد بن جعفر، حدثني أبي وغير واحد من قومنا أن أبا الحكم أسلم ولم تسلم امرأته، فأتت النبي صلى الله عليه وآله وسلم فقالت: يا رسول الله، إن أبا الحكم أخذ ابنتي ومنعنيها، فأمر رسول الله صلى الله عليه وآله وسلم أبا الحكم فجلس ناحية، وأمر المرأة فجلست ناحية، ووضع الجارية بينها، ثم قال: «ادعواها»."],[39837,"فدعواها، فمالت إلى أمها، فقال رسول الله صلى الله عليه وآله وسلم: «اللهم أهدها»."],[39838,"فمالت إلى أبيها، فأخذها."],[39839,"وأسمها عميرة بنت أبي الحكم وقد روي من غير طريق نحو هذا، وقلما تسمى البنت."],[39840,"٧١٤٢ - عميرة بنت حماسة"],[39841,"عميرة بنت حماسة الأنصارية الخطمية بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39842,"٧١٤٣ - عميرة بنت سعد"],[39843,"عميرة بنت سعد بن مالك أخت سهل بن سعد، وهي أم رفاعة بن مبشر بن أبيرق الظفري."],[39844,"٧١٤٤ - عميرة بنت سهل"],[39845,"ب د ع: عميرة بنت سهل بن رافع صاحب الصاعين الذي لمزه المنافقون."],[39846,"روت قصة أبيها في الصدقة بالصاعين."],[39847,"وكان قد خرج بابنته هذه عميرة وبصاع من تمر إلى رسول الله صلى الله عليه وآله وسلم فقال: يا رسول الله، إن لي إليك حاجة، ابنتي هذه تدعو لها وتمسح رأسها، فإنه ليس لي ولد غيرها."],[39848,"قالت: فوضع يده على رأسي، قالت: فأقسم بالله لكأن برد كف رسول الله صلى الله عليه وآله وسلم على كبدي بعد."],[39849,"أخرجها الثلاثة."],[39850,"٧١٤٥ - عميرة بنت ظهير"],[39851,"عميرة بنت ظهير بن رافع بن عدي بن زيد بن جشم بايعت النبي صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39852,"٧١٤٦ - عميرة بنت عبد سعد"],[39853,"عميرة بنت عبد سعد بن عامر بن عدي بايعت النبي صلى الله عليه وآله وسلم"],[39854,"٧١٤٧ - عميرة بنت عبيد"],[39855,"عميرة بنت عبيد بن معروف بن الحارث بن زيد بن عبيد الأنصارية من بني عمرو بن عوف."],[39856,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39857,"٧١٤٨ - عميرة بنت عقبة"],[39858,"عميرة بنت عقبة بن أحيحة الأنصارية من بني جحجبى."],[39859,"بايعت النبي صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39860,"٧١٤٩ - عميرة بنت قرط"],[39861,"عميرة بنت قرط بن خنساء بن سنان الأنصارية من بني حرام."],[39862,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39863,"٧١٥٠ - عميرة بنت قيس"],[39864,"عميرة بنت قيس بن عمرو بن عبيد بن مالك بن عدي بن الجرار بن سليط بن قيس الأنصارية من بني عدي."],[39865,"بايعت رسول الله صلى الله عليه وآله وسلم."],[39866,"قاله ابن حبيب."],[39867,"٧١٥١ - عميرة بنت قيس بن أبي كعب"],[39868,"عميرة بنت قيس بن أبي كعب الأنصارية ثم من بني سواد، أخت سهل بن قيس الشهيد بأحد."],[39869,"بايعت النبي صلى الله عليه وآله وسلم"],[39870,"٧١٥٢ - عميرة بنت كلثوم"],[39871,"عميرة بنت كلثوم بن الهدم بن امرئ القيس بن الحارث بن زيد بن عبيد الأنصارية بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39872,"٧١٥٣ - عميرة بنت مسعود"],[39873,"ع س: عميرة بنت مسعود الأنصارية"],[39874,"أخبرنا أبو موسى، إذنا، أخبرنا الحسن بن أحمد، حدثنا أحمد بن عبد الله، حدثنا محمد بن إبراهيم بن علي، حدثنا أبو عروبة، حدثنا هلال بن بشر، حدثنا إسحاق بن إدريس الأحول، حدثنا إبراهيم بن جعفر بن محمود بن محمد بن مسلمة، أخبرني جعفر بن محمود، أن جدته عميرة بنت مسعود، حدثته، «أنها دخلت على رسول الله صلى الله عليه وآله وسلم هي وأخواتها وهن خمس يبايعنه، فوجدنه وهو يأكل قديدا، فمضع لهن قديدة ثم ناولهن إياها فقسمنها، فمضغت كل واحدة منهن قطعة، فلقين الله عز وجل ما وجد، في أفواههن خلوفا، ولا اشتكين من أفواههن شيئا»."],[39875,"أخرجها أبو نعيم، وأبو موسى"],[39876,"٧١٥٤ - عنقودة"],[39877,"ع س: عنقودة"],[39878,"أخبرنا أبو موسى، كتابة، أخبرنا الحسن بن أحمد، حدثنا أبو نعيم، حدثنا محمد بن إبراهيم ابن علي، حدثنا محمد بن قارن، حدثنا أبو زرعة، حدثني غسان بن الفضل، أبو عمر، حدثنا صبيح بن سعيد النجاشي المدني سنة ثمانين ومائة وزعم أنه بلغ اثنتين وخمسين ومائة سنة قال: سمعت أمي، «أنها كانت اسمها عنبة، فسماها رسول الله صلى الله عليه وآله وسلم عنقودة»."],[39879,"أخرجها أبو نعيم، وأبو موسى"],[39880,"٧١٥٥ - عنقودة جارية عائشة"],[39881,"س: عنقودة جارية عائشة جعلها أبو موسى ترجمة منفردة غير الأولى، وقال: ذكرها جعفر، وفي إسناد حديثها نظر."],[39882,"روى حميد بن حوشب، عن الحسن، عن علي بن أبي طالب، قال: لما أراد النبي صلى الله عليه وآله وسلم أن يبعث معاذ إلى اليمن، صلى صلاة الغداة، ثم أقبل علينا بوجهه فقال: «يا معشر المهاجرين والأنصار، من ينتدب إلى اليمن؟» فقال أبو بكر، أنا يا رسول الله."],[39883,"فسكت عنه رسول الله، ثم قال: «من ينتدب إلى اليمن؟» فقال معاذ، أنا يا رسول الله، فقال: «أنت لها، وهي لك»."],[39884,"وتجهز وشيعه رسول الله صلى الله عليه وآله وسلم والمهاجرون وأفناء الناس، ثم قال رسول الله صلى الله عليه وآله وسلم: «أوصيك يا معاذ وصية الأخ الشقيق، أوصيك بتقوى الله عز وجل وحسن العمل، ولين الكلام، وصدق الحديث، وأداء الأمانة."],[39885,"يا معاذ، يسر ولا تعسر."],[39886,"»."],[39887,"وذكر حديثا طويلا في وفاة النبي صلى الله عليه وآله وسلم وعود معاذ من اليمن، ودخوله المدينة، وإتيانه منزل عائشة ليلا، وأنه طرق الباب، فقالت: من هذا الذي يطرق بابنا ليلا؟ فقال: أنا معاذ، فقالت: يا عنقودة، افتحي الباب."],[39888,"وقد روى هذا الحديث عن عبيد الله بن عمر، وسمى الجارية غفيرة."],[39889,"ونذكرها إن شاء الله تعالى."],[39890,"أخرجها أبو موسى."],[39891,"٧١٥٦ - عويمرة بنت عويم"],[39892,"عويمرة بنت عويم بن ساعدة الأنصارية بايعت رسول الله صلى الله عليه وآله وسلم قاله ابن حبيب."],[39893,"حرف الغين"],[39894,"٧١٥٧ - غائثة"],[39895,"د ع: غائثة وقيل غاثية أتت النبي صلى الله عليه وآله وسلم فقالت: إن أمي ماتت وعليها نذر أن تمشي إلى الكعبة، فقال: «اقضي عنها»."],[39896,"رواه عثمان بن عطاء، عن أبيه مرسلا."],[39897,"أخرجه ابن منده، وأبو نعيم."],[39898,"٧١٥٨ - غزيلة بنت جابر"],[39899,"ب د ع: غزيلة ويقال غزية بنت جابر بن حكيم الدوسية أم شريك، هي التي وهبت نفسها للنبي."],[39900,"قاله أبو نعيم."],[39901,"وقال أبو عمر: هي أنصارية من بني النجار، قال والصواب عزيلة إن شاء الله تعالى."],[39902,"روى عنها جابر بن عبد الله، وابن المسيب، وغيرهما."],[39903,"روى ابن لهيعة، عن أبي الزبير، عن جابر، عن أم شريك، أنها سمعت رسول الله صلى الله عليه وآله وسلم يقول: «ليفرن الناس من الدجال في الجبال»."],[39904,"قلت: فأين العرب يومئذ؟ قال: «هم قليل»."],[39905,"أخرجه الثلاثة، وقال أبو عمر: هي غير أم شريك العامرية، وإحداهما التي وهبت نفسها، وفيها نظر، ويرد ذكرها في أم شريك في الكنى إن شاء الله تعالى، وقد اختلف في التي وهبت نفسها للنبي اختلافا كثيرا."],[39906,"٧١٥٩ - غفيرة بنت رباح"],[39907,"س: غفيرة بنت رباح أخت بلال مؤذن رسول الله صلى الله عليه وآله وسلم وأخت أخيه خالد."],[39908,"قال جعفر: هما أخوان وأخت، قاله محمد بن إسماعيل البخاري."],[39909,"أخرجها أبو موسى."],[39910,"٧١٦٠ - غفيرة مولاة عائشة"],[39911,"س: غفيرة مولاة عائشة وقيل عنقودة وقد ذكرت."],[39912,"أخرجها أبو موسى."],[39913,"٧١٦١ - غفيلة بنت الحارث"],[39914,"د: غفيلة بنت الحارث ويقال بنت عبيد بن الحارث روت عنها حجة بنت قريط."],[39915,"روى موسى بن عبيدة، عن زيد بن عبد الرحمن، عن أبي سلامة، عن أمه حجة بنت قريط، عن أمها غفيلة بنت الحارث، قالت: «اجتمعت أنا وأمي إلى رسول الله صلى الله عليه وآله وسلم وهو ضارب قبته بالأبطح، فأخذ علينا أن لا نشرك بالله شيئا»."],[39916,"أخرجه ابن منده ههنا، وقيل: عقيلة، بالعين المهملة والقاف."],[39917,"وقد تقدم ذكرها هناك."],[39918,"٧١٦٢ - الغميصاء الأنصارية"],[39919,"د: الغميصاء الأنصارية وقيل الرميصاء وهي أم سليم بنت ملحان، أم أنس بن مالك وهي بكنيتها أشهر."],[39920,"أخبرنا أبو ياسر عبد الوهاب بن هبة الله، بإسناده عن عبد الله بن أحمد، حدثني أبي، حدثنا يحيى، حدثنا حميد، عن أنس، عن النبي صلى الله عليه وآله وسلم قال: «دخلت الجنة فسمعت خشفة فقلت: ما هذا؟»، فقالوا: «الغميصاء بنت ملحان»."],[39921,"أخرجها ابن منده، وروى لها: «حتى تذوقي عسيلته، ويذوق عسيلتك»."],[39922,"ويرد الكلام عليها في الترجمة التي بعدها"],[39923,"٧١٦٣ - الغميصاء الأنصارية"],[39924,"ع س: الغميصاء الأنصارية مطلقة عمرو بن حزم قال أبو موسى: وهي غير أم سليم، وأم حرام."],[39925,"أخبرنا أبو موسى، إذنا، أخبرنا أبو علي، أخبرنا أبو نعيم، حدثنا فاروق الخطابي، أخبرنا أبو مسلم الكشي، حدثنا أبو عمر الضرير، حدثنا حماد بن سلمة، عن هشام بن عروة، عن أبيه، عن عائشة، أن عمرو بن حزم طلق الغميصاء، فنكحها رجل فطلقها قبل أن يمسها، فأتت رسول الله صلى الله عليه وآله وسلم تسأله أن ترجع إلى زوجها الأول، فقال: «لا حتى يذوق الآخر من عسيلتها وتذوق من عسيلته»."],[39926,"ورواه ابن عباس فقال: الغميصاء أو الرميصاء، ولم يسم زوجها."],[39927,"أخرجها أبو نعيم، وأبو موسى."],[39928,"قلت: أخرج ابن منده هذا الحديث في ترجمة أم سليم الغميصاء، المقدم ذكرها ظنا منه أنها المخاطبة للنبي في العود إلى زوجها، وهو وهم، فإن الغميصاء أم سليم تزوجت بأبي طلحة بعد مالك بن النضر، ولم يتفارقا بطلاق إلى أن فرق الموت بينهما."],[39929,"والصواب عن أبي نعيم، وأبي موسى"],[39930,"حرف الفاء"],[39931,"٧١٦٤ - فاختة بنت الأسود"],[39932,"س: فاختة بنت الأسود بن المطلب بن أسد بن عبد العزى القرشية الأسدية روى ابن جريج، عن عكرمة، قال: فرق الإسلام بين أربع نسوة وأبناء بعولتهن: حمنة بنت أبي طلحة بن عبد العزى، كانت تحت خلف بن أسد بن عاصم الخزاعي، فخلف عليها الأسود بن خلف."],[39933,"وفاختة بنت الأسود بن المطلب كانت تحت أمية بن خلف: فخلف عليها ابنه صفوان بن أمية."],[39934,"أخرجها أبو موسى."],[39935,"٧١٦٥ - فاختة بنت أبي طالب"],[39936,"ب د ع: فاختة بنت أبي طالب بن عبد المطلب أخت علي بن أبي طالب لأبويه، وهي أم هانئ."],[39937,"اختلف في اسمها فقيل: فاختة، وقيل: هند، والأول أكثر."],[39938,"وهي بكنيتها أشهر، وترد في الكنى أكثر من هذا."],[39939,"أخرجها الثلاثة."],[39940,"ومن حديثها أن النبي صلى الله عليه وآله وسلم صلى ثماني ركعات غداة الفتح في بيتها."],[39941,"٧١٦٦ - فاختة بنت عمرو"],[39942,"ع س: فاختة بنت عمرو الزهرية خالة النبي صلى الله عليه وآله وسلم"],[39943,"أخبرنا أبو موسى، إجازة، أخبرنا أبو غالب، أخبرنا أبو بكر."],[39944,"ح قال أبو موسى: وأخبرنا الحسن، أخبرنا أبو نعيم، قالا: حدثنا سليمان بن أحمد، حدثنا محمد بن عبد الله الحضرمي، حدثنا معمر بن بكار السعدي، حدثنا عثمان بن عبد الرحمن، عن محمد بن المنكدر، عن جابر بن عبد الله، قال: سمعت رسول الله صلى الله عليه وآله وسلم يقول: «وهبت خالتي فاختة بنت عمرو غلاما، وأمرتها أن لا تجعله جازرا ولا صائغا ولا حجاما»."],[39945,"أخرجه أبو نعيم، وأبو موسى"],[39946,"٧١٦٧ - فاختة بنت الوليد"],[39947,"ب د ع: فاختة بنت الوليد بن المغيرة المخزومية وتقدم نسبها عند ذكر أخيها خالد بن الوليد."],[39948,"كانت زوج صفوان بن أمية بن خلف الجمحي، أسلمت يوم الفتح، وبايعت رسول الله صلى الله عليه وآله وسلم مع النساء اللاتي بايعنه."],[39949,"أخرجها الثلاثة."],[39950,"٧١٦٨ - الفارعة بنت أسعد بن زرارة"],[39951,"ب: الفارعة بنت أسعد بن زرارة الأنصاري أوصى بها أبوها أبو أمامة أسعد وبأختيها حبيبة وكبشة إلى رسول الله صلى الله عليه وآله وسلم فزوجها رسول الله صلى الله عليه وآله وسلم من نبيط بن جابر من بني مالك بن النجار."],[39952,"أخبرنا أبو منصور بن مكارم بن أحمد بن سعد المؤدب، بإسناده عن المعافي بن عمران، حدثنا أبو عقيل، عن بهية، عن عائشة، قالت: أهدينا يتيمة من الأنصار، قالت: فلما رجعنا، قال النبي صلى الله عليه وآله وسلم: «ما قلتم؟» قالت: سلمنا وانصرفنا."],[39953,"قال: «إن الأنصار قوم يعجبهم الغزل، ألا قلت يا عائشة:"],[39954,"أتيناكم أتيناكم … فحيونا نحييكم»."],[39955,"وهذه اليتيمة هي الفارعة بنت أسعد بن زرارة"],[39956,"٧١٦٩ - الفارعة بنت زرارة"],[39957,"س: الفارعة بنت زرارة بن عدس الأنصارية أخت أسعد بن زرارة الأنصاري، ثم من بني مالك بن النجار."],[39958,"أخرجها أبو موسى."],[39959,"٧١٧٠ - الفارعة بنت أبي سفيان"],[39960,"س: الفارعة بنت أبي سفيان بن حرب بن أمية بن عبد شمس القرشية الأموية كانت عند أبي أحمد بن جحش الأسدي."],[39961,"روى محمد بن عبد الله بن نمير، عن يونس، عن ابن إسحاق، قال: كان أول من خرج من مكة إلى المدينة مهاجرا عبد الله بن جحش بن رئاب الأسدي، أسد بن خزيمة، ومعه أهله الفارعة بنت أبي سفيان."],[39962,"أخرجها أبو موسى."],[39963,"وقد اختلف قوله، فإنه جعل في الترجمة أن الفارعة امرأة أبي أحمد بن جحش، فليحقق."],[39964,"وقد اختلفوا في أول من هاجر إلى المدينة، فقال الطبراني: أول من قدمها مهاجرا أبو سلمة بن عبد الأسد والله أعلم."],[39965,"٧١٧١ - الفارعة بنت أبي الصلت"],[39966,"ب د ع: الفارعة بنت أبي الصلت الثقفية أخت أمية بن أبي الصلت."],[39967,"روى عنها ابن عباس، أنها قدمت على رسول الله صلى الله عليه وآله وسلم بعد فتح الطائف."],[39968,"وكانت ذات لب وعقل وجمال، وكان رسول الله صلى الله عليه وآله وسلم بها معجبا، فقالت الفارعة: فقال لي رسول الله صلى الله عليه وآله وسلم: «تحفظين من شعر أخيك شيئا؟» قلت: نعم، وأعجب من ذلك، كان أخي إذا كان الليل."],[39969,"وذكرت قصة طويلة، وقالت: قدم أخي من سفر فأتاني فرقد على سريري، فأقبل طائران فسقط أحدهما على صدره، فشق ما بين صدره إلى ثنته، ثم أخرج قلبه ثم رد إلى مكانه وهو نائم، وأنشدت له الأبيات التي أولها:"],[39970,"باتت همومي تسري طوارقها … أكف عيني والدمع سابقها"],[39971,"ما رغب النفس في الحياة وإن … تحيا قليلا فالموت سائقها"],[39972,"ومنها قوله:"],[39973,"يوشك من فر من منيته … يوما على غرة يوافقها"],[39974,"من لم يمت عبطة يمت هرما … للموت كاس والمرء ذائقها"],[39975,"ولما حضرته الوفاة، قال عند المعاينة:"],[39976,"إن تغفر اللهم تغفر جما … وأي عبد لك لا ألما"],[39977,"ثم قال:"],[39978,"كل عيش وإن تطاول دهرا … صائر مرة إلى أن يزولا"],[39979,"ليتني كنت قبل ما قد بدا لي … في رءوس الجبال أرعى الوعولا"],[39980,"ثم مات، فقال النبي صلى الله عليه وآله وسلم: «كان مثل أخيك كمثل الذي آتاه الله آياته، فانسلخ منها فاتبعه الشيطان فكان من الغاوين»."],[39981,"أخرجها الثلاثة."],[39982,"٧١٧٢ - الفارعة بنت عبد الرحمن"],[39983,"الفارغة بنت عبد الرحمن الخثعمية تذكر في الصحابة."],[39984,"روى عنها السرى بن عبد الرحمن."],[39985,"أخرجها أبو عمر مختصرا."],[39986,"٧١٧٣ - الفارعة بنت قريبة"],[39987,"الفارعة بنت قريبة بن العجلان بن غنم بن عامر بن بياضة الأنصارية البياضية بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[39988,"٧١٧٤ - الفارعة بنت مالك"],[39989,"الفارعة بنت مالك أخت أبي سعيد الخدري، وقيل: الفريعة، ونذكرها في الفريعة أتم من هذا إن شاء الله تعالى."],[39990,"٧١٧٥ - الفاضلة الأنصارية"],[39991,"ب د ع: الفاضلة الأنصارية امرأة عبد الله بن أنيس الجهني."],[39992,"روت، أن النبي صلى الله عليه وآله وسلم خطبهم وحثهم على الصدقة، حديثها عند أهل المدينة."],[39993,"أخرجها الثلاثة."],[39994,"٧١٧٦ - فاطمة بنت أسد"],[39995,"ب د ع: فاطمة بنت أسد بن هاشم بن عبد مناف القرشية الهاشمية أم علي بن أبي طالب، وأم إخوته طالب وعقيل وجعفر."],[39996,"قيل: إنها توفيت قبل الهجرة."],[39997,"وليس بشيء، والصحيح أنها هاجرت إلى المدينة، وتوفيت بها."],[39998,"قال الشعبي: أم علي فاطمة بنت أسد، أسلمت وهاجرت إلى المدينة، وتوفيت بها."],[39999,"روى الأعمش، عن عمرو بن مرة، عن أبي البختري، عن علي، قال: «قلت لأمي فاطمة بنت أسد: اكفي فاطمة بنت رسول الله صلى الله عليه وآله وسلم سقاية الماء والذهاب في الحاجة، وتكفيك الداخل: الطحن والعجن»."],[40000,"وهذا يدل على هجرتها، لأن عليا إنما تزوج فاطمة بالمدينة."],[40001,"قال الزهري: هي أول هاشمية ولدت لهاشمي، وهي أيضا أول هاشمية ولدت خليفة، ثم بعدها فاطمة بنت رسول الله صلى الله عليه وآله وسلم ولدت الحسن، ثم زبيدة امرأة الرشيد ولدت الأمين، لا نعلم غيرهن، ثم إن هؤلاء الثلاثة لم تصف لهم الخلافة، فأما علي فإنه كان من اضطراب الأمور عليه إلى أن قتل، ما هو مشهور، وأما الحسن والأمين فخلعا."],[40002,"أخبرنا أبو الفرج بن أبي الرجاء، إجازة، بإسناده عن أبي بكر بن أبي عاصم، حدثنا عبد الله بن شبيب بن خالد القيسي، حدثنا يحيى بن إبراهيم بن هانئ، حدثنا حسين بن زيد بن علي، عن عبد الله بن محمد بن عمر بن علي، عن أبيه، أن رسول الله صلى الله عليه وآله وسلم كفن فاطمة بنت أسد في قميصه، واضطجع في قبرها، وجزاها خيرا."],[40003,"وروى عن ابن عباس نحو هذا، وزاد: فقالوا: ما رأيناك صنعت بأحد ما صنعت بهذه! قال: «إنه لم يكن بعد أبي طالب أبر بي منها، إنما ألبستها قميصي لتكسى من حلل الجنة."],[40004,"واضطجعت في قبرها ليهون عليها عذاب القبر»."],[40005,"قال الزبير: انقرض ولد أسد بن هاشم إلا من ابنته فاطمة بنت أسد."],[40006,"أخرجها الثلاثة"],[40007,"٧١٧٧ - فاطمة بنت أبي الأسد"],[40008,"ب س: فاطمة بنت أبي الأسد أو أبي الأسود بن عبد الأسد وهي ابنة أخي أبي سلمة بن عبد الأسد المخزومي."],[40009,"روى عمار الدهني، عن شقيق، قال: سرقت فاطمة بنت أبي الأسد، فأشفقت قريش أن يقطعها رسول الله صلى الله عليه وآله وسلم فكلموا أسامة بن زيد، فكلم رسول الله صلى الله عليه وآله وسلم فقال: «كل شيء ولا ترك حد من حدود الله عز وجل ولو كانت فاطمة بنت محمد لقطعتها."],[40010,"فقطعها»."],[40011,"وقد روي عن شقيق، عن فاطمة بنت أبي الأسود هذه، أن امرأة من قريش سرقت."],[40012,"وكان الأول أصح، لأن الحافظ بن ثابت ذكرها كذلك أيضا."],[40013,"أخرجها أبو عمر، وأبو موسى."],[40014,"٧١٧٨ - فاطمة بنت الحارث"],[40015,"ب س: فاطمة بنت الحارث بن خالد بن صخر بن عامر بن كعب بن سعد بن تيم بن مرة القرشية التيمية أمها ريطة بنت الحارث بن جبلة."],[40016,"ولدت بأرض الحبشة هي وأختاها زينب وعائشة ابنتا الحارث، وقيل: إن أخاهن موسى ولد بأرض الحبشة أيضا، وهلكوا جميعا من ماء شربوه بالطريق لما رجعوا من الحبشة، إلا فاطمة فإنها سلمت، ولم يبق من ولد الحارث غيرها."],[40017,"أخرجها أبو عمر، وأبو موسى."],[40018,"٧١٧٩ - فاطمة بنت أبي حبيش"],[40019,"ب د ع: فاطمة بنت أبي حبيش بن المطلب بن أسد بن عبد العزى القرشية الأسدية وهي التي سألت رسول الله صلى الله عليه وآله وسلم عن الاستحاضة."],[40020,"أخبرنا غير واحد، بإسنادهم عن محمد بن عيسى، حدثنا هناد، حدثنا وكيع وعبدة وأبو معاوية، عن هشام بن عروة، عن أبيه، عن عائشة، قالت: جاءت فاطمة بنت أبي حبيش إلى النبي صلى الله عليه وآله وسلم فقالت: يا رسول الله، إني امرأة أستحاض فلا أطهر، أفأدع الصلاة؟ قال: «لا، إنما ذلك عرق، وليس بالحيضة، فإذا أقبلت الحيضة فدعي الصلاة، وإذا أدبرت فاغسلي عنك الدم، وصلي»."],[40021,"أخرجها الثلاثة"],[40022,"٧١٨٠ - فاطمة بنت حمزة"],[40023,"د ع: فاطمة بنت حمزة بن عبد المطلب القرشية الهاشمية ابنة عم النبي صلى الله عليه وآله وسلم وقيل: اسمها أمامة، وقيل: عمارة."],[40024,"قاله أبو نعيم، وتكنى أم الفضل."],[40025,"أخبرنا يحيى بن محمود، إجازة، بإسناده إلى القاضي أبي بكر أحمد بن عمرو: قال: حدثنا أبو بكر بن أبي شيبة، حدثنا حسين بن علي، عن زائدة، عن محمد بن عبد الرحمن بن أبي ليلى، عن الحكم عن عبد الله بن شداد، عن بنت حمزة، قالت: مات مولى لي وترك ابنته، فقسم رسول الله صلى الله عليه وآله وسلم ما له بيني وبين ابنته، فجعل لي النصف، قال محمد: هي أخت ابن شداد لأمه قال: وحدثنا أبو بكر أحمد بن عمرو، قال: حدثنا يعقوب بن حميد، حدثنا عمران بن عيينة، عن يزيد بن أبي زياد، عن أبي فاختة، عن جعدة بن هبيرة، عن علي قال: أهدى إلى رسول الله صلى الله عليه وآله وسلم حلة مسيرة بحرير، فقال: «اجعلها خمرا بين الفواطم» فشققت منها أربعة أخمرة: خمارا لفاطمة بنت محمد، وخمارا لفاطمة بنت أسد، وخمارا لفاطمة بنت حمزة."],[40026,"ولم يذكر الرابعة."],[40027,"أخرجها ابن منده، وأبو نعيم"],[40028,"٧١٨١ - فاطمة الخزاعية"],[40029,"ع س: فاطمة الخزاعية ذكرها أبو بكر بن أبي عاصم في الوحدان، وأوردها الطبراني أيضا في الصحابيات."],[40030,"أخبرنا يحيى، إجازة، بإسناده عن أحمد بن عمرو، قال: حدثنا عبد الله بن محمد بن سالم القزاز، حدثنا عنبسة بن عبد الواحد بن أمية بن عبد الله بن سعيد بن العاص، عن صالح بن أبي الأخضر، عن الزهري، عن هند بنت الحارث وفاطمة الخزاعية، أن النبي صلى الله عليه وآله وسلم دخل على امرأة من الأنصار يعودها، فقال: «كيف تجدينك؟» قالت: بخير، وقد برحت بي أم ملدم، فقال: «اصبري فإنها تذهب من خبث الإنسان كما تذهب النار وسخ الحديد»."],[40031,"أخرجها أبو نعيم، وأبو موسى"],[40032,"٧١٨٢ - فاطمة بنت الخطاب"],[40033,"ب د ع: فاطمة بنت الخطاب بن نفيل بن عبد العزى القرشية العدوية أخت عمر بن الخطاب رضي الله عنهما."],[40034,"وهي امرأة سعيد بن زيد بن عمرو بن نفيل العدوي، أحد العشرة."],[40035,"أسلمت قديما أول الإسلام مع زوجها سعيد، قبل إسلام أخيها عمر، وهي كانت سبب إسلام أخيها عمر."],[40036,"روى مجاهد، عن ابن عباس، قال: سألت عمر عن إسلامه، فقال: خرجت بعد إسلام حمزة بثلاثة أيام، فإذا فلان المخزومي وكان قد أسلم، فقلت: تركت دين آبائك واتبعت دين محمد؟ قال: إن فعلت فقد فعله من هو أعظم عليك حقا مني! قلت: من هو؟ قال: أختك وختنك."],[40037,"قال: فانطلقت فوجدت الباب مغلقا، وسمعت همهمة، ففتح الباب، فدخلت فقلت: ما هذا الذي أسمع؟: قالت: ما سمعت شيئا."],[40038,"فما زال الكلام بيننا حتى أخذت برأس ختني فضربته فأدميته، فقامت إلي أختي فأخذت برأسي فقالت: قد كان ذاك على رغم أنفك! قال: فاستحييت حين رأيت الدم، وقلت: أروني هذا الكتاب."],[40039,"وذكر قصة إسلام عمر."],[40040,"وقد ذكرناه في إسلام عمر في ترجمته."],[40041,"أخرجها الثلاثة."],[40042,"٧١٨٣ - فاطمة بنت رسول الله ﷺ"],[40043,"ب د ع: فاطمة بنت رسول الله صلى الله عليه وآله وسلم سيدة نساء العالمين ما عدا مريم بنت عمران صلى الله عليهما أمها خديجة بنت خويلد."],[40044,"وكانت هي وأم كلثوم أصغر بنات رسول الله صلى الله عليه وآله وسلم. وقد اختلف: في أيتهن أصغر سنا؟ وقيل: إن رقية أصغرهن."],[40045,"وفيه عندي نظر، لأن النبي صلى الله عليه وآله وسلم زوج رقية من ابن أبي لهب، فطلقها قبل الدخول بها، أمره أبواه بذلك، ثم تزوجها عثمان رضي الله عنه وهاجرت معه إلى الحبشة، فما كان ليزوج الصغرى ويترك الكبرى."],[40046,"وكانت فاطمة تكنى أم أبيها، وكانت أحب الناس إلى رسول الله صلى الله عليه وآله وسلم وزوجها من علي بعد أحد، وقيل: تزوجها علي بعد أن ابتني رسول الله صلى الله عليه وآله وسلم بعائشة بأربعة أشهر ونصف، وابتني بها بعد تزويجه إياها بسبعة أشهر ونصف، وكان سنها يوم تزوجها خمسة عشرة سنة وخمسة أشهر في قول."],[40047,"وانقطع نسل رسول الله صلى الله عليه وآله وسلم إلا منها، فإن الذكور من أولاده ماتوا صغارا، وأما البنات فإن رقية رضي الله عنها ولدت عبد الله بن عثمان فتوفي صغيرا، وأما أم كلثوم فلم تلد، وأما زينب رضي الله عنها فولدت عليا ومات صبيا، وولدت أمامة بنت أبي العاص فتزوجها علي، ثم بعده المغيرة بن نوفل."],[40048,"وقال الزبير: انقرض عقب زينب."],[40049,"أخبرنا أبو أحمد عبد الوهاب بن علي الصوفي، أخبرنا أبو الفضل بن ناصر، أخبرنا الخطيب بن أبي الصقر الأنباري، أخبرنا أبو البركات أحمد بن عبد الواحد بن نظيف، أخبرنا أبو محمد بن رشيق، حدثنا أبو بشر الدولابي، حدثنا أحمد بن يحيى الصوفي، حدثنا إسماعيل بن أبان، حدثنا أبو مريم، عن أبي إسحاق، عن الحارث، عن علي قال: خطب أبو بكر وعمر يعني: فاطمة إلى رسول الله صلى الله عليه وآله وسلم فأبى رسول الله صلى الله عليه وآله وسلم عليهما، فقال عمر: أنت لها يا علي."],[40050,"فقلت: ما لي من شيء إلا درعي أرهنها."],[40051,"فزوجه رسول الله صلى الله عليه وآله وسلم فاطمة، فلما بلغ ذلك فاطمة بكت، قال: فدخل عليها رسول الله صلى الله عليه وآله وسلم فقال: «ما لك تبكين يا فاطمة فوالله لقد أنكحتك أكثرهم علما، وأفضلهم حلما، وأولهم سلما»"],[40052,"قال: وحدثنا الدولابي، حدثنا أحمد بن عبد الجبار، حدثنا يونس بن بكير، عن ابن إسحاق، حدثني عبد الله بن أبي نجيح، عن مجاهد، عن علي بن أبي طالب، قال: خطبت فاطمة إلى رسول الله صلى الله عليه وآله وسلم فقالت لي مولاة لي: هل علمت أن فاطمة خطبت إلى رسول الله صلى الله عليه وآله وسلم قلت: لا، قالت: فقد خطبت، فما يمنعك أن تأتي رسول الله صلى الله عليه وآله وسلم فيزوجك، فقلت: وعندي شيء أتزوج به؟ فقالت: إنك إن جئت رسول الله صلى الله عليه وآله وسلم زوجك، فوالله ما زالت ترجيني حتى دخلت على رسول الله صلى الله عليه وآله وسلم وكانت لرسول الله صلى الله عليه وآله وسلم جلالة وهيبة، فلما قعدت بين يديه أفحمت، فوالله ما أستطيع أن أتكلم، فقال: «ما جاء بك، ألك حاجة؟»، فسكت، فقال: «لعلك جئت تخطب فاطمة؟»، قلت: نعم، قال: «وهل عندك من شيء تستحلها به؟»، فقلت: لا والله يا رسول الله، فقال: «ما فعلت بالدرع التي سلحتكها؟»، فقلت: عندي والذي نفس علي بيده إنها لحطمية ما ثمنها أربعمائة درهم، قال: «قد زوجتك، فابعث بها، فإن كانت لصداق فاطمة بنت رسول الله صلى الله عليه وآله وسلم»"],[40053,"قال: وحدثنا الدولابي، حدثنا أبو جعفر محمد بن عوف بن سفيان الطائي، حدثنا أبو غسان مالك بن إسماعيل النهدي، حدثنا عبد الرحمن بن حميد الرواسي، حدثنا عبد الكريم بن سليط، عن ابن بريدة، عن أبيه، قال: قال رسول الله صلى الله عليه وآله وسلم ليلة البناء، يعني بفاطمة: «لا تحدثن شيئا حتى تلقاني»، فدعا رسول الله صلى الله عليه وآله وسلم بماء فتوضأ منه، ثم أفرغه على علي، وقال: «اللهم بارك فيهما، وبارك عليهما، وبارك لهما في نسلهما»."],[40054,"قال ابن إسحاق: وحدثني من لا أتهم: أن رسول الله صلى الله عليه وآله وسلم كان يغار لبناته غيرة شديدة، كان لا ينكح بناته على ضرة"],[40055,"أخبرنا غير واحد، بإسنادهم عن أبي عيسى، حدثنا عبد الله بن يونس وقتيبة بن سعيد، قالا: حدثنا الليث، عن ابن أبي مليكة، عن المسور بن مخرمة، قال: سمعت رسول الله صلى الله عليه وآله وسلم يقول وهو على المنبر: «إن بني هشام بن المغيرة استأذنوني في أن ينكحوا ابنتهم علي بن أبي طالب، فلا آذن، ثم لا آذن، ثم لا آذن، إلا أن يريد علي بن أبي طالب أن يطلق ابنتي وينكح ابنتهم، فإنها بضعة مني، يريبني ما رابها، ويؤذيني ما آذاها»"],[40056,"أخبرنا أبو محمد عبد الله بن سويدة، أخبرنا أبو الفضل بن ناصر السلامي، أخبرنا أبو صالح أحمد بن عبد الملك بن علي المؤذن، أخبرنا الحاكم أبو الحسن علي بن محمد الحافظ، والقاضي أبو بكر الخيري، قالا: أخبرنا أبو العباس محمد بن يعقوب، حدثنا الحسن بن مكرم، حدثنا عثمان بن عمر، حدثنا عبد الرحمن بن عبد الله، عن شريك بن عبد الله بن أبي نمر، عن عطاء بن يسار، عن أم سلمة، قالت: في بيتي نزلت: ﴿إِنَّمَا يُرِيدُ اللَّهُ لِيُذْهِبَ عَنْكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ﴾، قالت: فأرسل رسول الله صلى الله عليه وآله وسلم إلى فاطمة، وعلي، والحسن، والحسين، فقال: «هؤلاء أهلي»، قالت: فقلت: يا رسول الله، أفما أنا من أهل البيت؟ قال: «بلى، إن شاء الله عز وجل»."],[40057,"قال أبو صالح: قال الحاكم في المستدرك، عن الأصم، قال: صحيح على شرط مسلم ولم يخرجاه"],[40058,"قال: أخبرنا أبو صالح، أخبرنا أبو الحسن علي بن أحمد الأهوازي، أخبرنا أحمد بن عبيد بن إسماعيل الصفار، حدثنا تمام بن محمد بن غالب، حدثنا موسى بن إسماعيل، حدثنا حماد بن سلمة، عن علي بن زيد، عن أنس بن مالك، أن رسول الله صلى الله عليه وآله وسلم كان يمر ببيت فاطمة ستة أشهر إذا خرج لصلاة الفجر، يقول: «الصلاة يا أهل بيت محمد، ﴿إِنَّمَا يُرِيدُ اللَّهُ لِيُذْهِبَ عَنْكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا﴾»"],[40059,"قال: وأخبرنا أبو صالح، أخبرنا أبو القاسم عبد الملك بن محمد بن بشران، أخبرنا أبو علي أحمد بن الفضل بن العباس بن خزيمة، حدثنا عيسى بن عبد الله الطيالسي رعاث، حدثنا أبو نعيم، حدثنا زكريا بن أبي زائدة، عن فراس، عن الشعبي، عن مسروق، عن عائشة، قالت: أقبلت فاطمة تمشي، كأن مشيتها مشية رسول الله صلى الله عليه وآله وسلم فقال: «مرحبا يا بنتي»، ثم أجلسها عن يمينه أو عن شماله، ثم أسر إليها حديثا فبكت، ثم أسر إليها حديثا فضحكت، فقلت: ما رأيت كاليوم فرحا أقرب من حزن."],[40060,"فسألتها عما قال: فقالت: ما كنت لأفشي سر رسول الله صلى الله عليه وآله وسلم فلما قبض سألتها، فأخبرتني أنه أسر إلي فقال: «إن جبريل عليه السلام كان يعارضني بالقرآن في كل سنة مرة وإنه عارضني العام مرتين، وما أراه إلا وقد حضر أجلي، وإنك أول أهلي لحوقا بي، ونعم السلف أنا لك»."],[40061,"فبكيت، فقال: «ألا ترضين أن تكوني سيدة نساء العالمين»."],[40062,"قال أبو صالح: رواه البخاري في الصحيح، عن أبي نعيم."],[40063,"وهذا من غريب الصحيح، فإن زكريا روى عن الشعبي أحاديث في الصحيحين، وهذا يرويه عن فراس، عن الشعبي أخبرنا إبراهيم بن محمد، وغيره، بإسنادهم عن الترمذي، حدثنا حسين بن يزيد الكوفي، حدثنا عبد السلام بن حرب، عن أبي الحجاف، عن جميع بن عمير التيمي، قال: «دخلت مع عمي على عائشة، فسألت: أي الناس كأن أحب إلى رسول الله صلى الله عليه وآله وسلم قالت: فاطمة."],[40064,"قيل: من الرجال؟ قالت: زوجها، إن كان ما علمت صواما قواما»"],[40065,"أخبرنا أبو محمد بن سويدة، أخبرنا محمد بن ناصر، أخبرنا أبو صالح المؤذن، أخبرنا أبو بكر محمد بن عبد الله بن شاذان المقرئ، حدثنا محمد بن عبد الله القتاب، حدثنا أحمد بن عمرو بن أبي عاصم، حدثنا عمر بن الخطاب، حدثنا أبو صالح، حدثنا سفيان بن عيينة، عن ابن أبي نجيح، عن أبيه، عن رجل سمع علي بن أبي طالب يقول: سألت رسول الله صلى الله عليه وآله وسلم فقلت: أينا أحب إليك أنا أو فاطمة؟ قال: «فاطمة أحب إلي منك، وأنت أعز علي منها»"],[40066,"وأخبرنا يحيى بن محمود، إذنا، بإسناده، عن ابن أبي عاصم، قال: أخبرنا عبد الله بن عمر بن سالم المفلوج، وكان من خيار المسلمين عندي، حدثنا حسين بن زيد بن علي بن الحسين بن علي بن أبي طالب، عن عمرو بن علي، عن جعفر بن محمد، عن أبيه، عن علي بن حسين بن علي، عن حسين بن علي، عن علي، أن النبي صلى الله عليه وآله وسلم قال لفاطمة: «إن الله يغضب لغضبك ويرضى لرضاك»"],[40067,"أخبرنا أبو الفضل بن أبي الحسن المخزومي، بإسناده عن أحمد بن علي، حدثنا الحسن بن عثمان بن شقيق، حدثنا الأسود بن حفص المروزي، حدثنا حسين بن واقد، عن يزيد النحوي، عن عكرمة، عن ابن عباس، «أن النبي صلى الله عليه وآله وسلم كان إذا قدم من سفر قبل ابنته فاطمة»"],[40068,"قال: وحدثنا أحمد بن علي، حدثنا محمد بن إسماعيل بن أبي سمينة البصري، أخبرنا محمد بن خالد الحنفي، حدثنا موسى بن يعقوب الزمعي، عن هاشم بن هاشم، عن عبد الله بن وهب، عن أم سلمة، قالت: جاءت فاطمة إلى النبي صلى الله عليه وآله وسلم فسارها بشيء فبكت، ثم سارها بشيء فضحكت، فسالتها عنه، فقالت: أخبرني أنه مقبوض في هذه السنة فبكيت، فقال: «ما يسرك أن تكوني سيدة نساء أهل الجنة، إلا فلانة»، فضحكت"],[40069,"أخبرنا عبد الوهاب بن أبي حبة، بإسناده عن عبد الله بن أحمد، حدثني أبي، حدثنا عفان، حدثنا معاذ بن معاذ، حدثنا قيس بن الربيع، عن أبي"],[40070,"المقدام، عن عبد الرحمن الأزرق، عن علي، قال: دخل علي رسول الله صلى الله عليه وآله وسلم وأنا نائم، فاستسقى الحسن أو الحسين، قال: فقام النبي صلى الله عليه وآله وسلم إلى شاة لنا بكيء فحلبها فدرت، فجاءه الحسن فنحاه النبي صلى الله عليه وآله وسلم فقالت فاطمة: يا رسول الله، كأنه أحبهما إليك؟ قال: «لا، ولكنه استسقى قبله»، ثم قال: «إنا وإياك وهذين وهذا الراقد في مكان واحد يوم القيامة»"],[40071,"أخبرنا إبراهيم، وغيره، بإسنادهم، عن أبي عيسى، حدثنا سليمان بن عبد الجبار البغدادي، حدثنا علي بن قادم، حدثنا أسباط بن نصر الهمداني، عن السدي، عن صبيح مولى أم سلمة، عن زيد بن أرقم، أن رسول الله صلى الله عليه وآله وسلم قال لعلي وفاطمة والحسن والحسين: «أنا حرب لمن حاربتم، سلم لمن سالمتم»"],[40072,"أخبرنا أبو محمد الحسن بن علي بن الحسين الأسدي الدمشقي المعروف بابن البن، حدثنا جدى أبو القاسم الحسين بن الحسن، قال: قرأت على القاضي علي بن محمد بن علي المصيصي، أخبرنا القاضي أبو نصر محمد بن أحمد بن هارون بن عبد الله الغساني، أخبرنا أبو الحسن خيثمة بن سليمان بن حيدرة الأطرابلسي، قراءة عليه، حدثنا إبراهيم بن عبد الله القصار، أخبرنا العباس بن الوليد بن بكار الضبي بالبصرة، عن خالد بن عبد الله، عن بيان، عن الشعبي، عن أبي جحيفة، عن علي، قال: سمعت رسول الله صلى الله عليه وآله وسلم يقول: «إذا كان يوم القيامة نادى مناد من وراء الحجاب: يا أهل الجمع غضوا أبصاركم عن فاطمة بنت محمد حتى تمر»"],[40073,"أخبرنا أبو ياسر بن أبي حبة، بإسناده عن عبد الله بن أحمد، حدثني أبي، حدثنا إسماعيل بن إبراهيم، عن ليث، عن عبد الله بن الحسن هو ابن الحسن بن علي بن أبي طالب، عن أمه فاطمة بنت الحسين بن علي، عن جدتها فاطمة الكبرى هي بنت رسول الله صلى الله عليه وآله وسلم قالت: كان رسول الله صلى الله عليه وآله وسلم إذا دخل المسجد صلى على محمد وسلم، ثم قال: «رب اغفر لي ذنوبي"],[40074,"وافتح لي أبواب رحمتك»."],[40075,"وإذا خرج صلى على محمد وسلم، ثم قال: «رب اغفر لي ذنوبي وافتح لي أبواب فضلك»."],[40076,"هذا الحديث ليس إسناده بمتصل، فإن فاطمة بنت الحسين لم تدرك جدتها فاطمة الكبرى، والله أعلم وتوفيت فاطمة بعد رسول الله صلى الله عليه وآله وسلم بستة أشهر."],[40077,"هذا أصح ما قيل، وقيل: بثلاثة أشهر، وقيل: عاشت بعده سبعين يوما."],[40078,"وما رويت ضاحكة بعد وفاة رسول الله صلى الله عليه وآله وسلم حتى لحقت بالله عز وجل ووجدت عليه وجدا عظيما."],[40079,"قال أنس: قالت لي فاطمة: يا أنس، كيف طابت قلوبكم؟! تحثون التراب على رسول الله صلى الله عليه وآله وسلم. وكانت أول أهله لحوقا به، تصديقا لقوله صلى الله عليه وآله وسلم. ولما حضرها الموت، قالت لأسماء بنت عميس: يا أسماء، إني قد استقبحت ما يصنع بالنساء، يطرح على المرأة الثوب فيصفها."],[40080,"قالت أسماء: يا ابنة رسول الله صلى الله عليه وآله وسلم ألا أريك شيئا رأيته بأرض الحبشة؟ فدعت بجرائد رطبة فحنتها، ثم طرحت عليها ثوبا، فقالت فاطمة: ما أحسن هذا وأجمله! فإذا أنا مت فاغسليني أنت وعلي، ولا تدخلي علي أحدا."],[40081,"فلما توفيت جاءت عائشة، فمنعتها أسماء، فشكتها عائشة إلى أبي بكر، وقال: هذه الخثعمية تحول بيننا وبين بنت رسول الله صلى الله عليه وآله وسلم! فوقف أبو بكر على الباب، وقال: يا أسماء ما حملك على أن منعت أزواج النبي صلى الله عليه وآله وسلم أن يدخلن على بنت رسول الله صلى الله عليه وآله وسلم وقد صنعت لها هودجا؟! قالت: هي أمرتني ألا يدخل عليها أحد، وأمرتني أن أصنع لها ذلك."],[40082,"قال: فاصنعي ما أمرتك."],[40083,"وغسلها علي وأسماء."],[40084,"وهي أول من غطي نعشها في الإسلام، ثم بعدها زينب بنت جحش."],[40085,"وصلى عليها علي بن أبي طالب، وقيل: صلى عليها العباس."],[40086,"وأوصت أن تدفن ليلا، ففعل ذلك بها."],[40087,"ونزل في قبرها علي والعباس، والفضل بن العباس."],[40088,"قيل: توفيت لثلاث خلون من رمضان سنة إحدى عشرة، والله أعلم."],[40089,"وكان عمرها تسعا وعشرين سنة."],[40090,"وقال عبد الله بن الحسن بن الحسن بن علي: كان عمرها ثلاثين سنة."],[40091,"وقال الكلبي: كان عمرها خمسا وثلاثين سنة."],[40092,"وقد روي أنها اغتسلت لما حضرها الموت وتكفنت، وأمرت عليا أن لا يكشفها إذا توفيت، وأن يدرجها في ثيابها كما هي، ويدفنها ليلا."],[40093,"وقد ذكرنا في أم سلمى غسلها أيضا."],[40094,"والصحيح أن عليا وأسماء غسلاها والله أعلم."],[40095,"أخرجه الثلاثة."],[40096,"٧١٨٤ - فاطمة بنت سودة"],[40097,"فاطمة بنت سودة بن أبي ضبيس الجهنية."],[40098,"بايعت رسول الله صلى الله عليه وآله وسلم بعد الهجرة."],[40099,"قاله ابن حبيب."],[40100,"٧١٨٥ - فاطمة بنت شيبة"],[40101,"فاطمة بنت شيبة بن ربيعة وهي ابنة عم هند بنت عتبة بن ربيعة."],[40102,"وكانت امرأة عقيل بن أبي طالب."],[40103,"دخل عليها عقيل يوم حنين، وسيفه متلطخ دما، فقالت: ماذا أصبت من غنائم المشركين؟ فناولها إبرة، وقال: تخيطين بها ثيابك."],[40104,"فسمع منادي النبي صلى الله عليه وآله وسلم: «أدوا الخياط والمخيط» فأخذ الإبرة فألقاها في الغنائم."],[40105,"ذكرها ابن هشام، عن زيد بن أسلم، عن أبيه."],[40106,"وقال الواقدي: هذا الخبر لفاطمة بنت الوليد بن عتبة، زوجة عقيل."],[40107,"وروى ابن أبي مليكة، وابن أبي حسين: أن امرأة عقيل فاطمة بنت عتبة بن ربيعة، أخت هند."],[40108,"أخرجها الغساني مستدركا على أبي عمر."],[40109,"٧١٨٦ - فاطمة بنت صفوان"],[40110,"س: فاطمة بنت صفوان بن أمية بن محرث بن شق بن رقبة بن مخدج الكناني امرأة عمرو بن سعيد بن العاص."],[40111,"هاجرت معه إلى أرض الحبشة."],[40112,"أخبرنا أبو جعفر، بإسناده عن يونس، عن ابن إسحاق، في تسمية من هاجر إلى أرض الحبشة من بني أمية: عمرو بن سعيد بن العاص، ومعه امرأته فاطمة بنت صفوان بن أمية بن محرث بن شق بن رقبة."],[40113,"وماتت بها، وقتل عمرو بأجنادين من أرض الشام في خلافة أبي بكر رضي الله عنه."],[40114,"قاله ابن إسحاق."],[40115,"أخرجها أبو موسى"],[40116,"٧١٨٧ - فاطمة بنت الضحاك"],[40117,"ب: فاطمة بنت الضحاك الكلابية قال ابن إسحاق: تزوجها رسول الله صلى الله عليه وآله وسلم بعد وفاة ابنته زينب، وخيرها حين نزلت آية التخيير، فاختارت الدنيا، ففارقها رسول الله صلى الله عليه وآله وسلم فكانت بعد ذلك تلتقط البعر وتقول: أنا الشقية، أخترت الدنيا."],[40118,"هكذا قال، وهذا باطل، لأن الحديث الصحيح عن عائشة أن رسول الله صلى الله عليه وآله وسلم حين خير أزواجه بدأ بها، فاختارت الله ورسوله، وتتابع أزواج النبي صلى الله عليه وآله وسلم كلهن على ذلك."],[40119,"وقال قتادة وعكرمة: كان عنده تسع نسوة حين خيرهن، وهن اللاتي توفي عنهن."],[40120,"وروى جماعة أن التي قالت: أنا الشقية هي التي استعاذت منه."],[40121,"وقد اختلفوا فيها اختلافا كثيرا."],[40122,"وقد قيل: إن الضحاك بن سفيان عرض ابنته على رسول الله صلى الله عليه وآله وسلم واسمها فاطمة، وقال: إنها لم تصدع قط، فقال رسول الله صلى الله عليه وآله وسلم: «لا حاجة لي فيها»، وقيل: تزوجها سنة ثمان."],[40123,"أخرجها أبو عمر."],[40124,"٧١٨٨ - فاطمة بنت أبي طالب"],[40125,"فاطمة بنت أبي طالب أم هانئ اختلفوا في اسمها فقيل: فاختة وقد تقدمت وقيل: فاطمة، وقيل: هند."],[40126,"ونذكرها في الكنى أتم من هذا إن شاء الله تعالى."],[40127,"٧١٨٩ - فاطمة بنت عبد الله"],[40128,"ب: فاطمة بنت عبد الله أم عثمان بن أبي العاص الثقفي شهدت ولادة رسول الله صلى الله عليه وآله وسلم حين وضعته أمه آمنة، وكان ذلك ليلا، قالت: فما شيء أنظر إليه من البيت إلا نور، وإني لأنظر إلى النجوم تدنو، حتى أقول: يقعن علي."],[40129,"أخرجها أبو عمر."],[40130,"٧١٩٠ - فاطمة بنت عتبة"],[40131,"ب د ع: فاطمة بنت عتبة بن ربيعة بن عبد شمس القرشية العبشمية أخت هند بنت عتبة، وهي خالة معاوية."],[40132,"أسلمت يوم الفتح، وبايعت النبي صلى الله عليه وآله وسلم روى محمد بن العجلان، عن أبيه، عن فاطمة بنت عتبة بن ربيعة، «أن أخاها أبا حذيفة بن عتبة ذهب بها وبأختها هند يبايعان رسول الله صلى الله عليه وآله وسلم وذلك يوم الفتح، فلما اشترط علينا، قالت هند: أو تعلم في نساء قومك هذه الهنات والعاهات؟ قال: بايعه فهكذا يشترط»."],[40133,"وروى محمد بن عجلان، عن أبيه، عن فاطمة، أنها جاءت رسول الله صلى الله عليه وآله وسلم فقالت: يا رسول الله، قد كنت وما في الأرض قبة أحب إلي أن تهدم من قبتك، وإني اليوم وما في الأرض قبة أحب إلى بقاء من قبتك، فقال: «أما إن أحدكم لن يؤمن حتى أكون أحب إليه من نفسه»."],[40134,"أخرجها الثلاثة."],[40135,"٧١٩١ - فاطمة بنت عمرو"],[40136,"د ع: فاطمة بنت عمرو بن حرام عمة جابر بن عبد الله."],[40137,"أخبرنا أبو الفضل عبد الله بن أحمد، بإسناده عن أبي داود الطيالسي، حدثنا شعبة، عن محمد بن المنكدر، عن جابر بن عبد الله، قال: لما قتل أبي جعلت أكشف الثوب عن وجهه، فجعل القوم ينهونني ورسول الله صلى الله عليه وآله وسلم لا ينهاني، قال: فجعلت عمتي فاطمة بنت عمرو تبكي، فقال رسول الله صلى الله عليه وآله وسلم: «تبكين أولا تبكين، ما زالت الملائكة تظله بأجنحتها»."],[40138,"أخرجها ابن منده، وأبو نعيم"],[40139,"٧١٩٢ - فاطمة بنت عمرو بنت حرام"],[40140,"س: فاطمة بنت عمرو بن حرام لها صحبة."],[40141,"قاله أبو موسى، وقال: أوردها جعفر المستغفري كذلك، لم يزد، قال: وأظنها بنت عمرو بن حرام، عمة جابر."],[40142,"والله أعلم."],[40143,"٧١٩٣ - فاطمة بنت قيس بن خالد"],[40144,"ب د ع: فاطمة بنت قيس بن خالد الأكبر بن وهب بن ثعلبة بن وائلة بن عمرو بن شيبان بن محارب بن فهر القرشية الفهرية أخت الضحاك بن قيس، قيل: كانت أكبر منه بعشر سنين."],[40145,"وكانت من المهاجرات الأول، لها عقل وكمال، وهي التي طلقها أبو حفص بن المغيرة، فأمرها رسول الله صلى الله عليه وآله وسلم أن تعتد في بيت ابن أم مكتوم، وقدمت الكوفة على أخيها الضحاك بن قيس، وكان أميرا، فسمع منها الشعبي."],[40146,"أخبرنا إسماعيل بن علي، وغيره، بإسنادهم إلى أبي عيسى، حدثنا هناد، أخبرنا جرير، عن مغيرة، عن الشعبي، قال: قالت فاطمة بنت قيس طلقني زوجي ثلاثا على عهد رسول الله صلى الله عليه وآله وسلم فقال رسول الله صلى الله عليه وآله وسلم: «لا سكنى لك ولا نفقة»، ولما طلقها زوجها أبو حفص، خطبها معاوية، وأبو جهم بن حذيفة، فاستشارت رسول الله صلى الله عليه وآله وسلم فيهما، فقال النبي صلى الله عليه وآله وسلم: «أما معاوية فصعلوك لا مال له، وأما أبو حذيفة فلا يضع عصاه عن عاتقه»، وأمرها بأسامة بن زيد فتزوجته."],[40147,"وفي بيتها اجتمع أصحاب الشورى لما قتل عمر بن الخطاب رضي الله عنهم."],[40148,"وروت عن النبي صلى الله عليه وآله وسلم أحاديث."],[40149,"أخرجها الثلاثة"],[40150,"٧١٩٤ - فاطمة بنت المجلل"],[40151,"د ع: فاطمة بنت المجلل بن عبد الله بن قيس بن عبد ود بن نصر بن مالك بن حسل بن عامر بن لؤي القرشية العامرية تكنى أم جميل كانت من السابقين إلى الإسلام، وممن هاجر إلى الحبشة."],[40152,"أخبرنا أبو جعفر، بإسناده عن يونس بن بكير، عن محمد بن إسحاق، فيمن هاجر إلى الحبشة: وحاطب بن الحارث بن معمر معه امرأته فاطمة بنت المجلل بن عبد الله، وابناه: محمد بن حاطب والحارث بن حاطب، وهما لابنة المجلل."],[40153,"وتوفي زوجها بالحبشة، وقدمت هي، وابناها إلى المدينة في إحدى السفينتين روى عبد الله بن الحارث بن محمد بن حاطب، عن أبيه، عن جده محمد، قال: «لما قدمنا من أرض الحبشة خرجت بي أمي إلى رسول الله صلى الله عليه وآله وسلم فقالت: يا رسول الله، هذا ابن أخيك حاطب وقد أصابه هذا الحرق من النار، فادع الله له»."],[40154,"وقد ذكرناه في محمد بن حاطب."],[40155,"أخرجها ابن منده، وأبو نعيم."],[40156,"٧١٩٥ - فاطمة بنت منقذ"],[40157,"فاطمة بنت منقذ بن عمرو بن خنساء الأنصارية من بني مازن."],[40158,"بايعت رسول الله صلى الله عليه وآله وسلم قاله ابن حبيب."],[40159,"٧١٩٦ - فاطمة بنت الوليد بن عتبة"],[40160,"ب: فاطمة بنت الوليد بن عتبة بن ربيعة بن عبد شمس بن عبد مناف القرشية العبشمية امرأة سالم مولى أبي حذيفة، زوجها منه عمها أبو حذيفة بن عتبة."],[40161,"وكانت من المهاجرات الأول، ومن أفضل أيامى قريش."],[40162,"ولما قتل عنها سالم يوم اليمامة تزوجها بعده الحارث بن هشام بن المغيرة المخزومي فيما ذكره إسحاق بن أبي فروة، وليس ممن يحتج به."],[40163,"كذا ذكره العقيلي في نسبها، وذكر في ذلك حديث إسحاق بن أبي فروة، عن إبراهيم بن العباس بن الحارث، عن أبي بكر بن الحارث، عن فاطمة بنت الوليد أم أبي بكر، أنها كانت في الشام تلبس الجباب من ثياب الخز ثم تأتزر، فقيل لها كأنما يغنيك هذا عن الإزار؟ فقالت: سمعت رسول الله صلى الله عليه وآله وسلم يأمر بالإزار."],[40164,"كذا رواه عبد السلام بن حرب، عن إسحاق بن أبي فروة، عن إبراهيم."],[40165,"ولم ينسبها ابن أبي خيثمة ونسبها العقيلي، وغيره يخالفه ويقول: هي ابنة الوليد بن المغيرة المخزومي، فعلى هذا هي أخت خالد بن الوليد."],[40166,"أخرجها أبو عمر، وجعل الحديث في هذه الترجمة، وكان ينبغي أن يكون في ترجمة فاطمة بنت الوليد بن المغيرة، لأن الحديث مشهور بها."],[40167,"وأما ابن منده، وأبو نعيم فرويا هذا الحديث عن أبي بكر بن عبد الرحمن، وجعلاه في ترجمة فاطمة بنت الوليد القرشية، ولم ينسبها أكثر من هذا وكلاهما قرشيتان."],[40168,"ولكن أبو بكر ابن عبد الرحمن يروي عن المخزومية، فقد جعلنا علامتها ترجمتها والله أعلم."],[40169,"٧١٩٧ - فاطمة بنت الوليد بن المغيرة"],[40170,"ب د ع: فاطمة بنت الوليد بن المغيرة المخزومية أخت خالد بن الوليد."],[40171,"أسلمت يوم الفتح، وبايعت النبي صلى الله عليه وآله وسلم وهي زوج ابن عمها الحارث بن هشام بن المغيرة المخزومي."],[40172,"قاله أبو عمر، وقال: يقال: تزوجها بعده عمر."],[40173,"وفي ذلك نظر."],[40174,"وقال ابن منده، وأبو نعيم: فاطمة بنت الوليد القرشية."],[40175,"ورويا لها حديث الإزار، أنها كانت تلبسه فوق الجباب."],[40176,"فقيل لها: ألا يغنيك هذا عن الإزار؟ فقالت: سمعت رسول الله صلى الله عليه وآله وسلم يأمر بالإزار."],[40177,"أخرجه الثلاثة."],[40178,"قلت: قد أخرج أبو عمر هذا الحديث في ترجمة فاطمة بنت الوليد بن عتبة العبشمية، وأخرجه ابن منده، وأبو نعيم في فاطمة القرشية، وهو لهذه القرشية المخزومية، ومما يقوي أن الحديث لهذه أن بعض الرواة، قال: عن فاطمة بنت الوليد أم أبي بكر وأنها كانت بالشام، وهذه فاطمة المخزومية كانت بالشام مع زوجها الحارث بن هشام فلما مات عادت إلى المدينة."],[40179,"وقالوا: عن فاطمة بنت الوليد أم أبي بكر."],[40180,"وهذه المخزومية هي جدة أبي بكر بن عبد الرحمن بن الحارث بن هشام، وكثيرا ما يقولون للجد والجدة: أب وأم."],[40181,"وقال الزبير بن بكار في ولد الوليد بن المغيرة: وفاطمة بنت الوليد، ولدت عبد الرحمن وأم حكيم ولدي الحارث بن هشام."],[40182,"وهذا الحديث مشهور بهذه."],[40183,"أخبرنا غير واحد، إجازة، قالوا: أخبرنا الحافظ أبو القاسم علي بن الحسن بن هبة الله الدمشقي، قال: فاطمة بنت الوليد بن المغيرة بن عبد الله بن عمر بن مخزوم لها صحبة، روت عن النبي صلى الله عليه وآله وسلم حديثا واحدا، روى عنها ابن ابنها أبو بكر بن عبد الرحمن بن الحارث بن هشام، قالت: «سمعت رسول الله صلى الله عليه وآله وسلم يأمر بالإزار»."],[40184,"خرجت مع زوجها الحارث إلى الشام، واستشارها خالد في بعض أمره"],[40185,"٧١٩٨ - فاطمة بنت اليمان"],[40186,"ب د ع: فاطمة بنت اليمان أخت حذيفة بن اليمان وقد تقدم نسبها عند ذكر أخيها حذيفة بن اليمان."],[40187,"أخبرنا عبد الوهاب بن أبي حبة، بإسناده عن عبد الله بن أحمد، حدثني أبي، حدثنا محمد بن جعفر، حدثنا شعبة، عن حصين، عن أبي عبيدة بن حذيفة، عن عمته فاطمة، أنها قالت: أتينا رسول الله صلى الله عليه وآله وسلم نعوده في نساء."],[40188,"فإذا سقاء معلق نحوه يقطر ماؤه عليه، من شدة ما يجده من حر الحمى، فقلنا: يا رسول الله، لو دعوت الله فأذهب عنك هذا فقال رسول الله صلى الله عليه وآله وسلم: «إن من أشد الناس بلاء الأنبياء، ثم الذين يلونهم ثم الذين يلونهم» وروت عن النبي صلى الله عليه وآله وسلم كراهة تحلي النساء بالذهب."],[40189,"وهذا إن صح فهو منسوخ، أو على أن تركه أفضل من لبسه."],[40190,"وقد ذكرناه في أخت حذيفة."],[40191,"أخرجها الثلاثة."],[40192,"٧١٩٩ - فروة ظئر النبي ﷺ"],[40193,"فروة ظئر النبي صلى الله عليه وآله وسلم قالت: قال لي رسول الله صلى الله عليه وآله وسلم: «إذا أويت إلى فراشك فاقرئي: ﴿قُلْ يَأَيُّهَا الْكَافِرُونَ﴾ فإنها براءة من الشرك»."],[40194,"ذكرها أبو أحمد العسكري."],[40195,"٧٢٠٠ - فريعة بنت أبي أمامة أسعد بن زرارة الأنصاري"],[40196,"د ع: فريعة بنت أبي أمامة أسعد بن زرارة الأنصاري كان أبوها أوصى بها وبأختيها حبيبة وكبشه إلى النبي صلى الله عليه وآله وسلم فزوجها رسول الله صلى الله عليه وآله وسلم من نبيط بن جابر، من بني مالك بن النجار."],[40197,"أخرجها ابن منده، وأبو نعيم، وقيل: الفارعة، وهناك أخرجها أبو عمر."],[40198,"٧٢٠١ - فريعة بنت الحباب فريعة بنت الحباب بن رافع بن معاوية"],[40199,"فريعة بنت الحباب بن رافع بن معاوية الأنصارية مع بني الأبجر."],[40200,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[40201,"٧٢٠٢ - فريعة بن رافع"],[40202,"فريعة بنت رافع بن معاوية بن عبيد بن الجراح الأنصارية ثم من بني الأبحر."],[40203,"بايعت رسول الله صلى الله عليه وآله وسلم. وهي أم أسعد بن زرارة."],[40204,"قاله ابن حبيب."],[40205,"ويحتمل أن تكون هذه والتي قبلها واحدة، ويكون بعضهم قد أسقط اسم أبيها الحباب فالنسب واحد، والقبيلة واحدة، والله أعلم."],[40206,"٧٢٠٣ - فريعة بنت عمرو"],[40207,"فريعة بنت عمرو بن خنيس بن لوذان بن عبد ود وهي أم حسان بن ثابت الأنصاري الشاعر."],[40208,"٧٢٠٤ - فريعة بنت قيس"],[40209,"فريعة بنت قيس بن عمير بن لوذان بن ثعلبة بن مجدعة بن عمرو بن حريش بن جحجبى بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن إسحاق."],[40210,"٧٢٠٥ - فريعة بنت مالك بن الدخشم"],[40211,"فريعة بنت مالك بن الدخشم بن مالك الأنصارية ثم من بني عوف بن الخزرج."],[40212,"بايعت رسول الله صلى الله عليه وآله وسلم"],[40213,"٧٢٠٦ - فريعة بنت مالك بن سنان"],[40214,"ب د ع: فريعة بنت مالك بن سنان أخت أبي سعيد الخدري."],[40215,"تقدم نسبها عند ذكر أخيها."],[40216,"ويقال لها: الفارعة أيضا."],[40217,"شهدت بيعة الرضوان."],[40218,"وأمها حبيبة بنت عبد الله بن أبي ابن سلول."],[40219,"أخبرنا أبو أحمد بن سكينة، بإسناده عن أبي داود، حدثنا عبد الله بن مسلمة القعنبي، عن مالك، عن سعد بن إسحاق بن كعب بن عجرة، عن عمته زينب بنت كعب بن عجرة، أن الفريعة بنت مالك بن سنان وهي أخت أبي سعيد الخدري، أخبرتها، أنها جاءت إلى رسول الله صلى الله عليه وآله وسلم تسأله أن ترجع إلى أهلها في بني خذرة فإن زوجها خرج في طلب أعبد له ابقوا حتى إذا كانوا بطرف القدوم لحقهم فقتلوه."],[40220,"فسألت رسول الله صلى الله عليه وآله وسلم أن أرجع إلى أهلي، فإني لم يتركني في مسكن يملكه ولا نفقة، قالت: فقال رسول الله صلى الله عليه وآله وسلم: «نعم»، قالت: فخرجت حتى إذا كنت في الحجرة أو في المسجد، دعاني، أو أمر بي، فدعيت له، فقال: «كيف قلت؟» فرددت عليه القصة التي ذكرت من شأن زوجي، قالت: فقال: «امكثي في بيتك حتى يبلغ الكتاب أجله»."],[40221,"قالت: فاعتددت فيه أربعة أشهر وعشرا."],[40222,"قالت: فلما كان عثمان بن عفان أرسل إلي فسألني عن ذلك، فأخبرته، فاتبعه وقضى به."],[40223,"أخرجها الثلاثة"],[40224,"٧٢٠٧ - فريعة بنت معوذ"],[40225,"ب د ع: فريعة بنت معوذ بن عفراء الأنصارية تقدم نسبها عند الربيع بنت معوذ."],[40226,"لها صحبة وكانت مجابة الدعوة دخلت على النبي صلى الله عليه وآله وسلم حديثها في الرخصة في الغناء وضرب الدف في العرس، من حديث أهل البصرة."],[40227,"أخرجها الثلاثة."],[40228,"٧٢٠٨ - فريعة بنت وهب"],[40229,"س: فريعة بنت وهب الزهرية رفعها النبي صلى الله عليه وآله وسلم بيده، وقال: «من أراد أن ينظر إلى خالة رسول الله صلى الله عليه وآله وسلم فلينظر إلى هذه»."],[40230,"أخرجها أبو موسى مختصرا، وقال: أوردها جعفر هكذا، لم يزد."],[40231,"٧٢٠٩ - فسحم بنت أوس"],[40232,"فسحم بنت أوس بن خولي بن عبد الله بن الحارث الأنصارية من بني الحبلى."],[40233,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[40234,"٧٢١٠ - فضة النوبية"],[40235,"س: فضة النوبية جارية فاطمة الزهراء بنت رسول الله صلى الله عليه وآله وسلم"],[40236,"أخبرنا أبو موسى، كتابة، أخبرنا أبو الفضل جعفر بن عبد الواحد الثقفي، أخبرنا أبو عثمان إسماعيل بن عبد الرحمن العصائدي، إجازة، أخبرنا أبو سعيد محمد بن عبد الله بن حمدون وأبو طاهر بن خزيمة، قالا: أخبرنا أبو حامد بن الشرقي، أخبرنا أبو محمد عبد الله بن عبد الوهاب الخوارزمي، ابن عم الأحنف بن قيس في شوال سنة ثمان وخمسين ومائتين."],[40237,"ح قال أبو عثمان: أخبرنا أبو القاسم الحسن بن محمد الحافظ، حدثنا أبو عبد الله محمد بن علي بن بنسا، حدثنا أبي، حدثنا عبد الله بن عبد الوهاب الخوارزمي، حدثنا أحمد بن حماد المروزي، حدثنا محبوب بن حميد البصري وسأله عن هذا الحديث روح بن عباد، حدثنا القاسم بن بهرام، عن ليث، عن مجاهد، عن ابن عباس، قال في قوله تعالى: «﴿يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُ مُسْتَطِيرًا، وَيُطْعِمُونَ الطَّعَامَ عَلَى حُبِّهِ مِسْكِينًا وَيَتِيمًا وَأَسِيرًا﴾، قال: مرض الحسن والحسين، فعادهما جدهما رسول الله صلى الله عليه وآله وسلم وعادهما عامة العرب، فقالوا: يا أبا الحسن، لو نذرت على ولدك نذرا، فقال علي: إن برأ مما بهما صمت الله عز وجل ثلاثة أيام شكرا."],[40238,"وقالت فاطمة كذلك، وقالت جارية يقال لها فضة نوبية: إن برأ سيداي صمت لله عز وجل شكرا."],[40239,"فألبس الغلامان العافية، وليس عند آل محمد قليل ولا كثير."],[40240,"فانطق علي إلى شمعون الخيبري فاستقرض منه ثلاثة آصع من شعير، فجاء بها فوضعها، فقامت فاطمة إلى صاع فطحنته واختبزته، وصلى علي مع رسول الله صلى الله عليه وآله وسلم ثم أتى المنزل فوضع الطعام بين يديه، إذا أتاهم مسكين فوقف بالباب، فقال: السلام عليكم أهل بيت محمد، مسكين من أولاد المسلمين، أطعموني أطعمكم الله عز وجل على موائد الجنة."],[40241,"فسمعه علي، فأمرهم فأعطوه الطعام."],[40242,"ومكثوا يومهم وليلتهم لم يذوقوا إلا الماء."],[40243,"فلما كان اليوم الثاني قامت فاطمة إلى صاع وخبزته، وصلى علي مع النبي صلى الله عليه وآله وسلم ووضع الطعام بين يديه، إذ أتاهم يتيم فوقف بالباب، وقال: السلام عليكم أهل بيت محمد، يتيم بالباب من أولاد المهاجرين، استشهد والدي، أطعموني."],[40244,"فأعطوه الطعام، فمكثوا يومين لم يذوقوا إلا الماء."],[40245,"فلما كان اليوم الثالث قامت فاطمة إلى الصاع الباقي فطحنته واختبزته، فصلى علي مع النبي صلى الله عليه وآله وسلم ووضع الطعام بين يديه، إذ أتاهم أسير فوقف بالباب، وقال: السلام عليكم أهل بيت النبوة، تأسروننا وتشدوننا ولا تطعموننا، أطعموني فإني أسير فاعطوه الطعام ومكثوا ثلاثة أيام ولياليها لم يذوقوا إلا الماء."],[40246,"فأتاهم رسول الله صلى الله عليه وآله وسلم فرأى ما بهم من الجوع، فأنزل الله تعالى: ﴿هَلْ أَتَى عَلَى الإِنْسَانِ حِينٌ مِنَ الدَّهْرِ﴾ إلى قوله: ﴿لا نُرِيدُ مِنْكُمْ جَزَاءً وَلا شُكُورًا﴾."],[40247,"أخرجها أبو موسى"],[40248,"٧٢١١ - فكيهة بنت السكن"],[40249,"فكيهة بنت السكن بن يزيد الأنصارية من بني سواد."],[40250,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[40251,"٧٢١٢ - فكيهة بنت عبيد"],[40252,"فكيهة بنت عبيد بن دليم الأنصارية ثم من بني ساعدة، وهي ابنة عم سعد بن عبادة، وهي أم قيس بن سعد بن عبادة."],[40253,"بايعت رسول الله صلى الله عليه وآله وسلم"],[40254,"٧٢١٣ - فكيهة بنت المطلب"],[40255,"فكيهة بنت المطلب بن خلدة بن مخلد الأنصارية من بني زريق."],[40256,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[40257,"٧٢١٤ - فكيهة بنت يسار"],[40258,"ع س: فكيهة بنت يسار امرأة خطاب بن الحارث."],[40259,"أخبرنا أبو موسى، إذنا، أخبرنا أبو علي، أخبرنا أبو نعيم، حدثنا محمد بن أحمد بن الحسن، حدثنا محمد بن عثمان بن أبي شيبة، حدثنا منجاب بن الحارث، حدثنا إبراهيم بن يوسف، حدثنا زياد بن عبد الله البكائي، عن محمد بن إسحاق، في تسمية من أسلم بمكة من المهاجرات: حطاب بن الحارث، وامرأته فكيهة بنت يسار."],[40260,"أخرجها أبو نعيم، وأبو موسى"],[40261,"حرف القاف"],[40262,"٧٢١٥ - قتيلة بنت سعد"],[40263,"س: قتيلة بنت سعد من بني عامر بن لؤي، امرأة أبي بكر الصديق."],[40264,"وهي أم عبد الله وأسماء."],[40265,"أوردها جعفر في الصحابيات، وقال: تأخر إسلامها، سماها أبو أحمد الحافظ في كتاب الكني، وأورد جعفر لها الحديث المشهور، رواه هشام بن عروة، عن أبيه، عن أمه أسماء بنت أبي بكر، قالت: قدمت أمي علي وهي مشركة في عهد قريش، ومدتهم التي عاهدوا النبي صلى الله عليه وآله وسلم فاستأذنت رسول الله صلى الله عليه وآله وسلم فقلت: قدمت أمي وهي راغبة، أفاصلها؟ قال: «نعم هي أمك»."],[40266,"أخرجها أبو موسى، وقال: رواه جماعة عن هشام، وليس في شيء منها ذكر إسلامها، وفي جمع الروايات أنها مشركة."],[40267,"وقد تأول بعضهم وهي راغبة، يعني: في الإسلام، وليس كذلك إنما هي راغبة في شيء تأخذه وهي على شركها، ولهذا استأذنت أسماء النبي صلى الله عليه وآله وسلم في أن تصلها، ولو كانت راغبة في الإسلام لم تحتج إلى إذنه صلى الله عليه وآله وسلم"],[40268,"٧٢١٦ - قتيلة بنت صيفي"],[40269,"ب د ع: قتيلة بنت صيفي الجهنية ويقال الأنصارية وكانت من المهاجرات الأول."],[40270,"روى عنها عبد الله بن يسار."],[40271,"أخبرنا عبد الوهاب بن أبي حبة، بإسناده عن عبد الله بن أحمد، حدثني يحيى بن سعيد، حدثنا المسعودي، عن معبد بن خالد، عن عبد الله بن يسار، عن قتيلة بنت صيفي الجهنية، قالت: جاء حبر إلى النبي صلى الله عليه وآله وسلم فقال: نعم القوم أنتم يا محمد لولا أنكم تشركون، قال: «سبحان الله، وما ذلك؟» قال: تقولون: والكعبة إذا حلفتم، فأمهل رسول الله صلى الله عليه وآله وسلم شيئًا، ثم قال: «إنه قد قال، من حلف فليحلف برب الكعبة»، ثم قال: نعم القوم أنتم لولا أنكم تجعلون لله ندًا، قال: «وما ذلك؟»، قال: تقولون: ما شاء الله وشئت، قال: فأمهل رسول الله صلى الله عليه وآله وسلم شيئا، ثم قال: «إنه قد قال، من قال ما شاء الله فليقل: ثم شئت»."],[40272,"أخرجها الثلاثة"],[40273,"٧٢١٧ - قتيلة بنت العرباض"],[40274,"د ع: قتيلة بنت العرباض من بني مالك بن حسل لها ذكر في حديث."],[40275,"أخرجها ابن منده، وأبو نعيم كذا مختصرا."],[40276,"٧٢١٨ - قتيلة بنت عمرو"],[40277,"قتيلة بنت عمرو بن هلال الكنانية بايعت رسول الله صلى الله عليه وآله وسلم في حجة الوداع."],[40278,"قاله ابن حبيب."],[40279,"٧٢١٩ - قتيلة بنت قيس الكندية"],[40280,"ب ع س: قتيلة بنت قيس بن معد يكرب الكندية، أخت الأشعث بن قيس، وقيل: قيلة، والأول أصح."],[40281,"تزوجها رسول الله صلى الله عليه وآله وسلم سنة عشر ثم اشتكى، وقبض ولم تكن قدمت عليه ولا رآها ولا دخل بها."],[40282,"قيل: إنه تزوجها قبل وفاته بشهر، وقيل: إن النبي صلى الله عليه وآله وسلم أوصى أن تخير، فإن شاءت ضرب عليها الحجاب وتحرم على المؤمنين، وإن شاءت طلقها ولتنكح من شاءت."],[40283,"فاختارت النكاح فتزوجها عكرمة بن أبي جهل بحضرموت، فبلغ أبا بكر فقال: لقد هممت أن أحرق عليهما بيتهما، فقال له عمر: ما هي من أمهات المؤمنين، ولا دخل عليها، ولا ضرب عليها الحجاب، وقيل: إن رسول الله صلى الله عليه وآله وسلم لم يوص فيها بشيء، ولكنه لم يدخل بها، وارتدت مع أخيها حين ارتد، ثم نكحها عكرمة بن أبي جهل، فأراد أبو بكر أن يرجمه، فقال عمر: إن رسول الله صلى الله عليه وآله وسلم لم يدخل بها، وليست من أمهات المؤمنين، وقد برأها الله عز وجل بالردة."],[40284,"فسكت أبو بكر."],[40285,"وفيها وفي غيرها من أزواج النبي صلى الله عليه وآله وسلم اللاتي لم يدخل بهن، اختلاف كثير لم يتحصل منه كثير فائدة، وقد ذكرنا عند كل امرأة ما قيل فيها."],[40286,"والله أعلم."],[40287,"أخرجها أبو نعيم، وأبو عمر، وأبو موسى."],[40288,"٧٢٢٠ - قتيلة بنت النضر"],[40289,"قتيلة بنت النضر بن الحارث بن علقمة بن كلدة بن عبد مناف بن عبد الدار بن قصي القرشية العبدرية كانت تحت عبد الله بن الحارث بن أمية الأصغر بن عبد شمس، فولدت له عليا، والوليد، ومحمد، وأم الحكم."],[40290,"قال الواقدي: هي التي قالت الأبيات القافية في رسول الله صلى الله عليه وآله وسلم لما قتل أباها النضر بن الحارث يوم بدر، وهي:"],[40291,"يا راكبا إن الأثيل مظنة … من صبح خامسة وأنت موفق"],[40292,"أبلغ بها ميتا بأن تحية … ما إن تزال بها النجائب تعنق"],[40293,"مني إليه وعبرة مفسوحة … جادت لماتحها وأخرى تخنق"],[40294,"ظلت سيوف بني أبيه تنوشه … لله أرحام هناك تشقق"],[40295,"قسرا يقاد إلى المنية متعبا … رسف المقيد، وهو عان موثق"],[40296,"أمحمد أولست ضنء نجيبة … قومها والفحل فحل معرق"],[40297,"ما كان ضرك لو مننت وربما … من الفتى وهو المغيظ المحنق"],[40298,"فالنضر أقرب من تركت قرابة … وأحقهم إن كان عتق بعتق"],[40299,"فلما بلغ رسول الله صلى الله عليه وآله وسلم ذلك بكى حتى أخضلت الدموع لحيته، وقال: «لو بلغني شعرها قبل أن أقتله ما قتلته»."],[40300,"ذكر هذا الخبر عبد الله بن إدريس."],[40301,"وذكر الزبير، قال: فرق رسول الله صلى الله عليه وآله وسلم حتى دمعت عيناه، وقال لأبي بكر: «يا أبا بكر، لو سمعت شعرها لم أقتل أباها»."],[40302,"أخرجها أبو عمر."],[40303,"وروى بعضهم عتق يعتق بضم الياء وكسر التاء، ومعناه: إن كان شرف ونجابة وكرم نفس وأصل يعتق صاحبه فهو أحق به."],[40304,"٧٢٢١ - قرة العين بنت عبادة"],[40305,"قرة العين بنت عبادة بن نضلة بن مالك بن العجلان الأنصارية، ثم من بني عوف بن الخزرج."],[40306,"وهي أم عبادة بن الصامت."],[40307,"٧٢٢٢ - قريبة بنت أبي أمية"],[40308,"د ع س: قريبة بنت أبي أمية بن المغيرة بن عبد الله بن عمر بن مخزوم القرشية المخزومية لها ذكر في حديث أم سلمة زوج النبي صلى الله عليه وآله وسلم وهي أختها."],[40309,"روى أبو بكر بن عبد الرحمن بن الحارث بن هشام، عن أم سلمة، قالت: لما وضعت زينب جاءني النبي صلى الله عليه وآله وسلم فخطبني، فتزوجها رسول الله صلى الله عليه وآله وسلم فقال: «أين زينب؟» فقالت قريبة بنت أبي أمية ووافقها عنها: أخذها عمار بن ياسر، فقال النبي صلى الله عليه وآله وسلم: «أنا آتيكم الليلة»."],[40310,"أخرجه ابن منده، وأبو نعيم، وأبو موسى وإنما أخرجه أبو موسى لأن ابن منده اختصر ذكرها، ولو استدرك عليه أمثال هذا لكان كثيرا فلا أدري لم ذكر هذه؟."],[40311,"٧٢٢٣ - قريبة بنت الحارث"],[40312,"د ع: قريبة بنت الحارث العتوارية روت عنها بنتها عقيلة، قالت: جئت أنا وأمي قريبة بنت الحارث العتوارية في نساء من المهاجرات إلى النبي صلى الله عليه وآله وسلم وهو ضارب قبته بالأبطح، فأخذ علينا، أن لا نشرك بالله شيئا."],[40313,"قالت: فأقررنا وبسطنا أيدينا لنبايعه، فقال: «إني لا أمس يد النساء»:."],[40314,"فاستغفر لنا، وكان ذلك بيعتنا."],[40315,"أخرجها ابن منده، وأبو نعيم."],[40316,"٧٢٢٤ - قريبة بنت زيد"],[40317,"قريبة بنت زيد بن عبد ربه بن زيد الأنصارية الجشمية بايعت النبي صلى الله عليه وآله وسلم. قاله ابن حبيب."],[40318,"٧٢٢٥ - قريرة بنت الحارث العتوارية"],[40319,"ع س: قريرة بنت الحارث العتوارية وقيل قريبة وقد تقدمت."],[40320,"هكذا أخرجها الطبراني، وغيره."],[40321,"روت عنها ابنتها عقلية بنت عبيد بن الحارث."],[40322,"أخبرنا أبي موسى، كتابة، أخبرنا أبو غالب، أخبرنا أبو بكر."],[40323,"ح قال أبو موسى: وأخبرنا أبو علي، أخبرنا أبو نعيم، قالا: حدثنا سليمان بن أحمد، حدثنا محمد بن علي الصائغ، حدثنا حفص بن عمر الحدي، أخبرنا بكار بن عبد الله بن أخي موسى بن عبيد الربذي، حدثني موسى."],[40324,"ح زاد ابن ريذة، عن الطبراني، قال: وحدثنا معاذ بن المثنى، حدثنا علي بن المديني، حدثنا زيد بن الحباب، أخبرنا موسى بن عبيدة، حدثني زيد بن عبد الرحمن، وفي رواية: علي بن زيد بن عبد الله بن أبي سلامة، عن أمه حجة بنت قريظ، عن أمها عقيلة بنت عبيد بن الحارث، قالت: جئت أنا وأمي قريرة بنت الحارث العتوارية في نساء من المهاجرات، فبايعن النبي صلى الله عليه وآله وسلم وهو ضارب عليه قبته بالأبطح، فأخذ علينا: أن لا نشرك بالله شيئا الآية كلها، لما أقررنا وبسطنا أيدينا لنبايعه، قال: «إني لا أمس أيدي النساء»، فاستغفر لنا."],[40325,"فكانت تلك بيعتنا وقد تقدم في قريبة."],[40326,"أخرجها كذا أبو نعيم، وأبو موسى"],[40327,"٧٢٢٦ - قسرة بنت رواس"],[40328,"ب د ع: قسرة بنت رواس الكندية من عجائز العرب."],[40329,"أخبرنا أبو موسى، إذنا، أخبرنا أبو علي، أخبرنا أبو نعيم، حدثنا الحسين بن علي بن أحمد الربضي، حدثني ذكوان بن محمد بن علي الحرشي، حدثنا محمد بن خلاد العطار، حدثنا عبد الرحمن بن عمرو بن جبلة الباهلي، قال: حدثنا ميسرة بنت حبشي الطائية، عن قتيلة بنت عبد الله، عن قسرة بنت رواس الكندية، قالت: قال رسول الله صلى الله عليه وآله وسلم: «يا قسرة، أذكري الله تعالى عند الخطيئة، يذكرك عندها بالمغفرة."],[40330,"وأطيعي زوجك يكفيك شر الدنيا والآخرة."],[40331,"وبري والديك يكثر خير بيتك»."],[40332,"تفرد به ابن جبلة في أسانيد كثيرة للنساء خاصة، وغيره أوثق منه."],[40333,"أخرجها أبو نعيم، وأبو عمر، وأبو موسى"],[40334,"٧٢٢٧ - قفيرة الهلالية"],[40335,"قفيرة ويقال مليكة الهلالية امرأة عبد الله بن أبي حدرد."],[40336,"لم يرو عنها إلا عبد الرحمن الأعرج."],[40337,"ذكرها مسلم في كتاب الأفراد وذكرها أبو علي الغساني."],[40338,"٧٢٢٨ - قهطم بنت علقمة"],[40339,"س: قهطم بنت علقمة بن عبد الله بن أبي قيس امرأة سليط بن عمرو وابن عبد شمس بن عبد ود بن نصر بن مالك بن حسل بن عامر بن لؤي."],[40340,"هاجرا جميعا إلى أرض الحبشة، ورجعا جميعا في السفينة إلى المدينة، قاله ابن إسحاق."],[40341,"أخرجها أبو موسى."],[40342,"٧٢٢٩ - قيلة الأنمارية"],[40343,"ب د ع: قيلة الأنمارية وقال ابن خيثمة: الأنصارية: أخت بني أنمار، وقيل: أم بني أنمار."],[40344,"رأت النبي صلى الله عليه وآله وسلم روى عبد الله بن عثمان بن خيثم عنها، أنها قالت: رأيت رسول الله صلى الله عليه وآله وسلم عند المروة بحل من عمرة له، فجلست إليه فقلت: يا رسول الله، إني امرأة أشتري وأبيع، فربما أردت أن أبيع السلع فأستام بها أكثر ما أريد أن أبيعها، ثم أنقص حتى أبيعها بالذي أريد."],[40345,"وإذا أردت أن أشتري السلعة أعطيت بها أقل ما أريد أن آخذها به، حتى آخذها بالذي أريد، فقال النبي صلى الله عليه وآله وسلم: «لا تفعلي قيلة، إذا أردت أن تشتري السلعة فاستامي بها الذي تريدين أن تأخذي به، أعطيت أو منعت»."],[40346,"أخرجها الثلاثة."],[40347,"٧٢٣٠ - قيلة الخزاعية"],[40348,"ب: قيلة الخزاعية وهي أم سباع بن عبد العزى بن عمرو بن نضلة بن عباس بن سليمان الخزاعية، من حلفاء بني زهرة، فيها نظر."],[40349,"أخرجها أبو عمر."],[40350,"٧٢٣١ - قيلة بنت مخرمة"],[40351,"ب د ع: قيلة بنت مخرمة الغنوية وقيل العنزية وقيل العنبرية وهو الصحيح، لأنه قد قيل فيها: التميمية، والعنبر من تميم."],[40352,"روى عبد الله بن حسان العنبري، قال: حدثني جدتاي صفية، ودحيبة، ابنتا عليبة وكانتا ربيبتي قيلة بنت مخرمة، وكانت جدة أبيهما، أخبرتهما قيلة بنت مخرمة، وكانت تحت حبيب بن أزهر أخي بني جناب، فولدت له النساء، فتوفي عنها، فانتزع بناتها عمر بن أثوب بن أزهر فخرجت تبتغي الصحابة إلى رسول الله صلى الله عليه وآله وسلم في أول الإسلام، فبكت جويرية منهن حديثة، وهي أصغرهن، وعليها سييج لها فرحمتها فاحتملتها معها."],[40353,"وذكر القصة بطولها، وقالت: فقدمنا على رسول الله صلى الله عليه وآله وسلم وهو يصلي بالناس صلاة الغداة، فسمعت رسول الله صلى الله عليه وآله وسلم يقول: «المسلم أخو المسلم، يسعهما الماء والشجر، ويتعاونان على الفتان»."],[40354,"أخرجه الثلاثة، وهو حديث طويل كثير الغريب، أخرجه أبو نعيم، وأبو عمر مختصرا، وأخرجه ابن منده مطولا."],[40355,"أخبرنا غير واحد، بإسنادهم عن محمد بن عيسى، حدثنا عبد بن حميد، حدثنا عفان بن مسلم الصفار، حدثنا عبد الله بن حسان، أنه حدثه جدتاه: صفية ودحيبة، ابنتا عليبة، عن قيلة بنت مخرمة، وكانتا ربيبتها وقيل: جدة أبيهما أم أبيه، وأنها قالت: قدمنا على رسول الله صلى الله عليه وآله وسلم فذكرت الحديث بطوله حتى جاء رجل وقد ارتفعت الشمس، فقال: السلام عليك يا رسول الله، فقال رسول الله صلى الله عليه وآله وسلم: «وعليك السلام ورحمة الله»."],[40356,"وعليه، يعني النبي صلى الله عليه وآله وسلم أسمال مليتين كانتا بزعفران، وقد نفضتا، ومعه عسيب نخلة"],[40357,"حرف الكاف"],[40358,"٧٢٣٢ - كبشة بنت أبي أمامة"],[40359,"دس: كبشة بنت أبي أمامة أسعد بن زرارة وكانت تحت عبد الله بن أبي حبيبة، وهي خالة أبي أمامة بن سهل بن حنيف، وأختها الفارعة، وقيل: الفريعة، كانت تحت نبيط بن جابر، وكان أبوهن قد أوصى إلى رسول الله صلى الله عليه وآله وسلم بهن، فرباهن وزوجهن."],[40360,"أخرجها ابن منده، وأبو موسى."],[40361,"٧٢٣٣ - كبشة الأنصارية"],[40362,"ب د ع: كبشة الأنصارية جدة عبد الرحمن بن أبي عمرة، وقيل: كبيشة."],[40363,"وتعرف بالبرصاء، وهي غير منسوبة، وقد نسبها أبو عروبة فقال: كبشة بنت ثابت بن المنذر بن حرام، أخت حسان بن ثابت."],[40364,"وقال أحمد بن زهير، عن أبيه: هي من بني مالك بن النجار، وهذا يؤيد قول أبي عروبة، لأن حسان بن ثابت من بني مالك بن النجار."],[40365,"أخبرنا إبراهيم بن محمد بن مهران، وغيره، بإسنادهم إلى محمد بن عيسى، حدثنا ابن أبي عمر، حدثنا سفيان، عن يزيد بن يزيد، عن عبد الرحمن بن أبي عمرة، عن جدته كبشة، قالت: «دخلت على رسول الله صلى الله عليه وآله وسلم فشرب من في قربة معلقة قائما، فقمت إلى فيها فقطعته»."],[40366,"هذا يزيد بن يزيد هو أخو عبد الرحمن بن يزيد بن جابر، وهو أقدم منه موتا."],[40367,"أخرجها الثلاثة"],[40368,"٧٢٣٤ - كبشة بنت أوس"],[40369,"كبشة بنت أوس بن شريق وهي أم خزيمة بن ثابت، وهي أنصارية من بني خطمة."],[40370,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[40371,"٧٢٣٥ - كبشة بنت ثابت"],[40372,"كبشة بنت ثابت بن حارثة بن ثعلبة بن الجلاس الأنصارية من بني خدارة."],[40373,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[40374,"٧٢٣٦ - كبشة بنت حاطب"],[40375,"كبشة بنت حاطب بن قيس بن هيشة من بني معاوية."],[40376,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[40377,"٧٢٣٧ - كبشة بنت حكيم"],[40378,"كبشة بنت حكيم الثقفية جدة أم الحكم بن يحيى بن عقبة."],[40379,"روت عنها أم الحكم رأت النبي صلى الله عليه وآله وسلم. ولها صحبة."],[40380,"٧٢٣٨ - كبشة بنت رافع"],[40381,"ب: كبشة بنت رافع بن عبيد بن الأبجر وهو خدرة بن عوف بن الخزرج الأنصارية الخدرية، هي أم سعد بن معاذ الأشهلي، عاشت بعد ابنها وندبته لما مات."],[40382,"أخبرنا عبيد الله بن أحمد، بإسناده عن يونس، عن محمد بن إسحاق، قال: وقالت أم سعد حين حمل نعش سعد وهي تبكيه:"],[40383,"ويل أم سعد سعدا … صرامة وجدا"],[40384,"قال: فذكروا أن رسول الله صلى الله عليه وآله وسلم قال: «كل نائحة تكذب إلا نائحة سعد»."],[40385,"أخرجها أبو عمر"],[40386,"٧٢٣٩ - كبشة بنت عبد عمرو"],[40387,"كبشة بنت عبد عمرو بن عبيد بن قميئة بن عامر بن الخزرج الأنصارية من بني ساعدة."],[40388,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[40389,"٧٢٤٠ - كبشة بنت فروة"],[40390,"كبشة بنت فروة بن عمرو بن ودقة الأنصارية من بني بياضة."],[40391,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[40392,"٧٢٤١ - كبشة بنت كعب"],[40393,"كبشة بنت كعب بن مالك الأنصارية السلمية امرأة أبي قتادة الأنصاري."],[40394,"قال جعفر: لها صحبة ولم يورد لها شيئا."],[40395,"وقال غيره: تروي عن أبي قتادة في سؤر الهر."],[40396,"روى إسحاق بن عبد الله بن أبي طلحة، عن حميدة بنت عبيد بن رفاعة، عن كبشة بنت كعب بن مالك وكانت عند أبي قتادة أن أبا قتادة دخل عليها، قالت: فسكبت له وضوءا، قالت: فجاءت هرة تشرب، فأصغى لها الإناء حتى شربت، قالت كبشة: فرآني أنظر إليه، فقال: أتعجبين يا ابنة أخي؟ فقالت: نعم، فقال: إن رسول الله صلى الله عليه وآله وسلم قال: «إنها ليست بنجس، إنها من الطوافين عليكم والطوافات»."],[40397,"أخرجه أبو موسى."],[40398,"٧٢٤٢ - كبشة بنت معد يكرب"],[40399,"كبشة بنت معديكرب الكندية أم معاوية بن خديج."],[40400,"روي عن معاوية بن حديج، أنه قال: قدمت على رسول الله صلى الله عليه وآله وسلم ومعن أمي كبشة بنت معديكرب عمة الأشعث بن قيس، فقالت: يا رسول الله، إني آليت أن أطوف بالبيت حبوا، فقال لها: «طوفي على رجليك سبعين: سبعا عن يديك، وسبعا عن رجليك»."],[40401,"ذكرها ابن الدباغ الأندلسي."],[40402,"٧٢٤٣ - كبشة بنت واقد"],[40403,"كبشة بنت واقد بن عمرو بن الإطنابة بن عامر الأنصارية من بلحارث بن الخزرج."],[40404,"وهي أم عبد الله بن رواحة."],[40405,"بايعت رسول الله صلى الله عليه وآله وسلم قاله ابن حبيب."],[40406,"٧٢٤٤ - كبيرة بنت سفيان"],[40407,"ب د ع: كبيرة بنت سفيان وقيل بنت أبي سفيان الخزاعية وقيل الثقفية أدركت النبي صلى الله عليه وآله وسلم وروت عنه."],[40408,"روى عنها مولاها أبو ورقة بن سعيد، قال: وكانت أدركت الجاهلية والإسلام، وكانت من المبايعات، قالت: قلت: يا رسول الله، إني وأدت أربع بنين لي في الجاهلية، قال: «اعتقي أربع رقاب»، قالت: وقال رسول الله صلى الله عليه وآله وسلم: «دم عفراء أزكى عند الله من دم سوداوين»."],[40409,"أخرجها الثلاثة، وأبو موسى، إلا أن ابن منده وأبا نعيم، قالا: كثيرة بالثاء المثلثة، وقاله أبو عمرو، وأبو موسى بالباء الموحدة، وأوردها أبو عبد الله يعني: ابن منده بالثاء المثلثة."],[40410,"٧٢٤٥ - كبيشة بنت مالك"],[40411,"كبيشة تصغير كبشة بنت مالك بن قيس بن محرث الأنصارية من بني مازن."],[40412,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[40413,"٧٢٤٦ - كبيشة بنت معن"],[40414,"س: كبيشة بنت معن بن عاصم روى ابن جريج، عن عكرمة مولى ابن عباس، قال: نزلت في كبيشة بنت معن بن عاصم، كانت عند الأسلت فتوفي عنها، فجنح عليها ابنه أبو قيس بن الأسلت، فجاءت النبي صلى الله عليه وآله وسلم فقالت: يا رسول الله، لا أنا ورثت زوجي، ولا أنا تركت فأنكح فأنزل الله تعالى ﴿لا يَحِلُّ لَكُمْ أَنْ تَرِثُوا النِّسَاءَ كَرْهًا﴾."],[40415,"الآية كلها."],[40416,"أخرجها أبو موسى."],[40417,"٧٢٤٧ - كريمة بنت أبي حدرد"],[40418,"س: كريمة بنت أبي حدرد سلامة الأسلمي يقال: لها صحبة."],[40419,"وهي أم الدرداء الكبراء روى عنها أهل الشام."],[40420,"وقد قيل: اسمها خيرة."],[40421,"ولم يثبت البخاري لها صحبة."],[40422,"قال جعفر المستغفري: ليست امرأة أبي الدرداء."],[40423,"وهذا لم يقله غيره."],[40424,"أخرجها أبو موسى."],[40425,"٧٢٤٨ - كريمة بنت كلثوم"],[40426,"ع س: كريمة بنت كلثوم الحميرية"],[40427,"أخبرنا أبو موسى، إجازة، أخبرنا أبو غالب، أخبرنا أبو بكر، حدثنا أبو القاسم، حدثنا محمد بن محمد الجذوعي القاضي."],[40428,"ح قال أبو موسى: وأخبرنا أبو علي، أخبرنا أبو نعيم، حدثنا محمد بن أحمد بن الحسن، حدثنا محمد بن عثمان بن أبي شيبة، قالا: حدثنا عبد الجبار بن عاصم، حدثنا بقية بن الوليد، عن معاوية بن يحيى، عن سليمان بن موسى، عن مكحول، عن غضيف بن الحارث، عن عطية بن بسر المازني، قال: جاء عكاف بن وداعة الهلالي، فقال رسول الله صلى الله عليه وآله وسلم: «يا عكاف، لك زوجة؟» قال: لا، ولا أتزوج يا رسول الله حتى تزوجني من شئت، قال: فقال رسول الله صلى الله عليه وآله وسلم: «قد زوجتك على اسم الله تعالى والبركة كريمة بنت كلثوم الحميري»."],[40429,"أخرجها أبو نعيم، وأبو موسى"],[40430,"٧٢٤٩ - كعيبة بنت سعيد"],[40431,"ب: كعيبة بنت سعيد الأسلمية شهدت خيبر مع رسول الله صلى الله عليه وآله وسلم فأسهم لها سهم رجل."],[40432,"قال ذلك الواقدي."],[40433,"أخرجها أبو عمر."],[40434,"٧٢٥٠ - كلثم بنت برثن"],[40435,"ع س: كلثم وقيل كليبة بنت برثن العنبرية أم زبيب بن ثعلبة."],[40436,"أخبرنا أبو موسى، إذنا، أخبرنا أبو غالب، أخبرنا أبو بكر."],[40437,"ح قال أبو موسى: وأخبرنا الحسن بن أحمد، حدثنا أحمد بن عبد الله، قالا: حدثنا سليمان بن أحمد، حدثنا محمد بن صالح بن الوليد النرسي، حدثنا سعيد بن عمار بن شعيث بن عبد الله بن زبيب بن ثعلبة، حدثني أبي، قال: سمعت جدي زبيبا، قال: دعتني كليبة بنت برثن العنبرية فقالت: يا بني، إن هذا أخذ زربيتي التي كنت ألبس، فلببت الرجل فأتيت به النبي صلى الله عليه وآله وسلم فقلت: يا رسول الله، إن هذا أخذ زربية أمي، فقال: «رد عليه زربية أمه»."],[40438,"أخرجها أبو نعيم، وأبو موسى"],[40439,"٧٢٥١ - كلثم جدة عبد الرحمن بن أبي عمرة"],[40440,"س: كلثم جدة عبد الرحمن بن أبي عمرة روى ابن لهيعة، عن يزيد بن يزيد بن جابر، عن عبد الرحمن بن أبي عمرة، عن جدته كلثم، قالت: «دخل علينا رسول الله صلى الله عليه وآله وسلم وعندنا قربة معلقة، فشرب منها، فقطعت فم القربة ورفعتها»."],[40441,"قاله ابن وهب عن ابن لهيعة، وقيل: اسمها كبشة."],[40442,"وقد تقدم هذا الحديث في ترجمة كبشة."],[40443,"أخرجه أبو موسى."],[40444,"حرف اللام"],[40445,"٧٢٥٢ - لبابة بنت الحارث"],[40446,"ب د ع: لبابة بنت الحارث بن حزن بن بجير بن الهرم بن رويبة بن عبد الله بن هلال بن عامر بن صعصعة الهلالية أم الفضل وهي زوج العباس بن عبد المطلب، وأم الفضل، وعبد الله، ومعبد، وعبيد الله، وقثم، وعبد الرحمن، وغيرهم من بني العباس."],[40447,"وهي لبابة الكبرى وهي أخت ميمونة زوج النبي صلى الله عليه وآله وسلم وخالة خالد بن الوليد."],[40448,"يقال إنها أول امرأة أسلمت بعد خديجة وكان النبي صلى الله عليه وآله وسلم يزورها ويقيل عندها، وكانت من المنجبات، ولدت للعباس ستة رجال لم تلد امرأة مثلهم، ولها يقول عبد الله بن يزيد الهلالي:"],[40449,"ما ولدت نجيبة من فحل … كستة من بطن أم الفضل"],[40450,"أكرم بها من كهلة وكهل … عم النبي المصطفى ذي الفضل"],[40451,"وخاتم الرسل وخير الرسل"],[40452,"ولبابة أخت أسماء وسلمى وسلامة بنات عميس الخثعميات لأمهن، وأخوهن لأمهن: محمية بن جزء الزبيدي، أمهن كلهن هند بنت عوف الكنانية، وقيل: الحميرية."],[40453,"فمن قال الحميرية، قال: هند بنت عوف بن الحارث بن حماطة بن جرش من حمير."],[40454,"وهي التي قيل فيها: إنها أكرم الناس أصهارا لأن رسول الله صلى الله عليه وآله وسلم زوج ميمونة، والعباس زوج لبابة الكبرى، وجعفر بن أبي طالب، وأبو بكر الصديق، وعلى بن أبي طالب أزواج أسماء بنت عميس."],[40455,"وحمزة بن عبد المطلب زوج سلمى بنت عميس."],[40456,"وخلف عليها بعده شداد بن الهاد، والوليد بن المغيرة زوج لبابة الصغرى، وهي أم خالد، وكان المغيرة من سادات قريش."],[40457,"فأولاد العباس وأولاد جعفر، ومحمد بن أبي بكر، ويحيى بن علي، وخالد بن الوليد: أولاد خالة."],[40458,"روت عن النبي صلى الله عليه وآله وسلم أحاديث، روى عنها ابناها عبد الله وتمام، وأنس بن مالك، وعبد الله بن الحارث بن نوفل، وعمير مولاها."],[40459,"أخبرنا غير واحد، بإسنادهم عن محمد بن عيسى، حدثنا هناد، حدثنا عبدة، عن محمد بن إسحاق، عن الزهري، عن عبيد الله بن عبد الله، عن ابن عباس، عن أمه أم الفضل، قالت: «خرج علينا رسول الله صلى الله عليه وآله وسلم وهو عاصب رأسه في مرضه، فصلى المغرب فقرأ بالمرسلات، فما صلاها بعد حتى لقي الله عز وجل»."],[40460,"أخرجها الثلاثة."],[40461,"الهزم: بضم الهاء وفتح الزاي"],[40462,"٧٢٥٣ - لبابة بنت الحارث"],[40463,"ب: لبابة بنت الحارث أخت التي قبلها."],[40464,"وهي لبابة الصغرى، وهي أم خالد بن الوليد."],[40465,"في إسلامها وصحبتها نظر، أخرجها أبو عمر."],[40466,"٧٢٥٤ - لبابة بنت أبي لبابة"],[40467,"د ع: لبابة بنت أبي لبابة الأنصارية أدركت النبي صلى الله عليه وآله وسلم. روي عنها، أنها قالت: كنت أنا صاحبة أبي، وكان يقول: شدي وثاق عدو الله الذي خان الله ورسوله يعني: لما ربط نفسه بسلسلة في المسجد، وقد تقدم في اسم أبيها، قالت: ومر به أخوه رفاعة بن عبد المنذر، فناداه: يا أخي، هلم أكلمك."],[40468,"قال: لا، والله لا أكلمك أبدا حتى يرضى عنك الله تعالى، ورسول الله صلى الله عليه وآله وسلم. فسأل عنه رسول الله صلى الله عليه وآله وسلم فأخبروه خبره، فقال: «لو جاءني لكان لي فيه أمر»."],[40469,"فنزلت ﴿يَأَيُّهَا الَّذِينَ آمَنُوا لا تَخُونُوا اللَّهَ وَالرَّسُولَ﴾. الآية،"],[40470,"ونزلت: ﴿وَآخَرُونَ مُرْجَوْنَ لأَمْرِ اللَّهِ﴾."],[40471,"أخرجها ابن منده، وأبو نعيم."],[40472,"٧٢٥٥ - لبنى بنت الخطيم"],[40473,"لبنى بنت الخطيم الأنصارية الأوسية كانت عند قيس بن زيد بن عامر الظفري."],[40474,"بايعت رسول الله صلى الله عليه وآله وسلم قاله ابن حبيب."],[40475,"٧٢٥٦ - لسيبة بنت كعب"],[40476,"ع س: لسيبة بنت كعب وقيل بنت حرب أم عمارة الأنصارية، من بني النجار."],[40477,"ذكرها الطبراني في باب: اللام وقيل: نسيبة بالنون."],[40478,"وهو الأشهر، وتذكر في النون إن شاء الله تعالى."],[40479,"أخرجها أبو نعيم، وأبو موسى."],[40480,"٧٢٥٧ - لميس بنت عمرو"],[40481,"لميس بنت عمرو بن حرام الأنصارية بايعت النبي صلى الله عليه وآله وسلم قاله ابن حبيب."],[40482,"٧٢٥٨ - لهية أم ولد عمر بن الخطاب"],[40483,"س: لهية أم ولد عمر بن الخطاب لها صحبة، ذكرها جعفر في الصحابة وروى، بإسناده عن ابن أخي الزهري، عن عمه قال: حدثني رجال من أهل العلم، عن حفصة زوج النبي صلى الله عليه وآله وسلم أنها أرسلت لهية أم ولد عمر في يومها وقالت: إن رسول الله صلى الله عليه وآله وسلم خرج من عندي فاحتبس، فانظري عند أي نسائه."],[40484,"فانطلقت فوجدته عند صفية، فأخبرتها، فطفقت حفصة تقول: خلابة يهودية، ثم أمرت حفصة لهية أن ترجع إلى صفية حتى يخرج رسول الله صلى الله عليه وآله وسلم من عندها، فتخبرها بالذي، قالت حفصة فانطقت لهية فأخبرت صفية، فقالت لها صفية: والله إني لابنة نبي الله، أبي هارون، وإن عمي موسى، وإن زوجي رسول الله صلى الله عليه وآله وسلم وما أعرف لأحد أن يكون أفضل مني."],[40485,"فدخل رسول الله صلى الله عليه وآله وسلم وصفية تبكي، فقال لها: «ما لك؟» فأخبرته بالذي، قالت حفصة، وبالذي، قالت صفية."],[40486,"فصدقها رسول الله صلى الله عليه وآله وسلم فلما رأت حفصة تصديق رسول الله صلى الله عليه وآله وسلم صفية، قالت: والله لا أوذي صفية أبدا."],[40487,"أخرجها أبو موسى."],[40488,"٧٢٥٩ - ليلى بنت الإطنابة"],[40489,"ليلى بنت الإطنابة بن منصور بن معيص بن جشم الأنصارية من بلحبلى."],[40490,"بايعت رسول الله صلى الله عليه وآله وسلم قاله ابن حبيب."],[40491,"٧٢٦٠ - ليلى بنت ثابت"],[40492,"ليلى بنت ثابت بن المنذر الأنصارية من بني مالك بن النجار."],[40493,"بايعت رسول الله صلى الله عليه وآله وسلم قاله ابن حبيب."],[40494,"٧٢٦١ - ليلى بنت أبي حثمة"],[40495,"ب د ع: ليلى بنت أبي حثمة بن حذيفة بن غانم بن عامر بن عبد الله بن عبيد بن عويج بن عدي بن كعب بن لؤي القرشية العدوية امرأة عامر بن ربيعة."],[40496,"وهي أم ابنه عبد الله بن عامر، وبه كانت تكنى."],[40497,"وكانت من المهاجرات الأول."],[40498,"هاجرت الهجرتين إلى الحبشة وإلى المدينة، وصلت القبلتين."],[40499,"روت عنها الشفاء."],[40500,"يقال: إنها أول ظعينة دخلت المدينة مهاجرة، وقيل: أم سلمة."],[40501,"أخبرنا أبو جعفر، بإسناده عن يونس، عن محمد بن إسحاق، عن عبد الرحمن بن الحارث، عن عبد العزيز بن عبد الله بن عامر بن ربيعة، عن أمه ليلى، قالت: كان عمر بن الخطاب من أشد الناس علينا في إسلامنا، فلما تهيأنا للخروج إلى أرض الحبشة، جاءني عمر بن الخطاب وأنا على بعيري نريد أن نتوجه، فقال: «أين يا أم عبد الله؟ فقلت: آذيتمونا في ديننا، فنذهب في أرض الله حيث لا نؤذى في عبادة الله، فقال: صحبكم الله، ثم ذهب، فجاءني زوجي عامر بن ربيعة، فأخبرته بما رأيت من رقة عمر، فقال: ترجين أن يسلم؟ فقلت: نعم»."],[40502,"الحديث وروى عبد الله بن عامر، قال: دعتني أمي يوما ورسول الله صلى الله عليه وآله وسلم عندنا فقالت: تعال أعطك، فقال لها رسول الله صلى الله عليه وآله وسلم: «ما أردت أن تعطيه؟» قالت: تمرا، فقال لها: «أما إنك لو لم تعطيه شيئا كتبت عليك كذبة»."],[40503,"أخرجه الثلاثة."],[40504,"٧٢٦٢ - ليلى بنت حكيم"],[40505,"ليلى بنت حكيم الأنصارية الأوسية التي وهبت نفسها للنبي صلى الله عليه وآله وسلم. ذكرها أحمد بن صالح المصري في أزواج النبي صلى الله عليه وآله وسلم ولم يذكرها غيره."],[40506,"أخرجها أبو عمر، وأظنه تصحيفا، فإن ليلى بنت الخطيم التي يأتي ذكرها هي الأنصارية الأوسية التي وهبت نفسها للنبي، ويشتبه الخطيم بالحكيم، والله أعلم."],[40507,"٧٢٦٣ - ليلى بنت الخطيم"],[40508,"د ع: ليلى بنت الخطيم بن عدي بن عمرو بن سواد بن ظفر بن الخزرج بن عمرو الأنصارية الظفرية أخت قيس بن الخطيم."],[40509,"أقبلت إلى النبي صلى الله عليه وآله وسلم فقالت: يا ابن مباري الريح، أنا ليلى بنت الخطيم، جئتك أعرض نفسي عليك، فتزوجني."],[40510,"قال: «قد فعلت»."],[40511,"فرجعت إلى قومها فقالت: تزوجني رسول الله صلى الله عليه وآله وسلم فقالوا بئس ما صنعت! أنت امرأة غيرى، والنبي صاحب نساء، استقيليه."],[40512,"فرجعت إلى النبي صلى الله عليه وآله وسلم فقالت: أقلني."],[40513,"قال: «قد فعلت»."],[40514,"ذكر ذلك ابن أبي خيثمة."],[40515,"أخرجها ابن منده، وأبو نعيم، واستدركها أبو علي على أبي عمر."],[40516,"٧٢٦٤ - ليلى بنت ربعي"],[40517,"ليلى بنت ربعي بن عامر بن خلدة الأنصارية من بني بياضة."],[40518,"بايعت رسول الله صلى الله عليه وآله وسلم قاله ابن حبيب."],[40519,"٧٢٦٥ - ليلى بنت رباب"],[40520,"ليلى بنت رئاب بن حنيف الأنصارية من بني عوف بن الخزرج."],[40521,"بايعت رسول الله صلى الله عليه وآله وسلم قاله ابن حبيب."],[40522,"٧٢٦٦ - ليلى السدوسية"],[40523,"ب د ع: ليلى السدوسية امرأة بشير ابن الخصاصية."],[40524,"روى عنها إياد بن لقيط، قالت: إن رسول الله صلى الله عليه وآله وسلم سمى زوجها بشير ابن الخصاصية بشيرا، وكان اسمه زحما."],[40525,"وقالت: أردت أن أصوم يومين مواصلة، فذكرت ذلك لبشير، فقال: إن رسول الله صلى الله عليه وآله وسلم نهى عنه، وقال: «يفعل ذلك اليهود، ولكن صوموا، فإذا كان الليل فأفطروا»."],[40526,"أخرجه الثلاثة."],[40527,"٧٢٦٧ - ليلى بنت أبي سفيان"],[40528,"ليلى بنت أبي سفيان بن الحارث بن قيس بن زيد بن أمية الأنصارية الأشهلية بايعت رسول الله صلى الله عليه وآله وسلم قاله ابن حبيب."],[40529,"٧٢٦٨ - ليلى بنت سماك"],[40530,"ليلى بنت سماك بن ثابت بن سفيان بن جشم بن عمرو بن امرئ القيس الأنصارية من بلحارث بن الخزرج."],[40531,"بايعت رسول الله صلى الله عليه وآله وسلم قاله ابن حبيب."],[40532,"٧٢٦٩ - ليلى مولاة عائشة"],[40533,"ب د ع: ليلى مولاة عائشة روى عنها أبو عبد الله المدني، أنها قالت: قلت: يا رسول الله، إنك تخرج من الخلاء فأدخل في أثرك، فلا أرى شيئا إلا أني أجد ريح المسك."],[40534,"قال: «إنا معشر الأنبياء بنيت أجسادنا على أرواح أهل الجنة فما خرج منا من نتن ابتلعته الأرض»."],[40535,"أبو عبد عباد بن جعفر بن رفاعة الله المدني: مجهول."],[40536,"أخرجها الثلاثة."],[40537,"٧٢٧٠ - ليلى بنت عبادة"],[40538,"ليلى بنت عبادة الأنصارية الساعدية أخت عبادة بن عبادة بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[40539,"٧٢٧١ - ليلى بنت عبد الله"],[40540,"س: ليلى بنت عبد الله بن عبد شمس بن خف بن صداد بن عبد الله بن قرط بن رزاح بن عدي بن كعب القرشية العدوية وهي التي تدعى الشفاء، قاله جعفر عن محمد بن حبان."],[40541,"أخرجه أبو موسى."],[40542,"٧٢٧٢ - ليلى عمة عبد الرحمن بن أبي ليلى"],[40543,"ب: ليلى عمة عبد الرحمن بن أبي ليلى بايعت رسول الله صلى الله عليه وآله وسلم وروت عنه."],[40544,"روت أم حمادة بنت محمد بن عبد الرحمن بن أبي ليلى، عن عمتها، قالت: كانت أم ليلى تصبغ لها درعها وخمارها وملحفتها كل شهر، وتختضب غمسا، وتقول: على هذا بايعنا رسول الله صلى الله عليه وآله وسلم."],[40545,"كذا قال الغساني: أم ليلى."],[40546,"وقال أبو عمر: ليلى."],[40547,"والله أعلم."],[40548,"٧٢٧٣ - ليلى الغفارية"],[40549,"ب د ع: ليلى الغفارية كانت تخرج مع رسول الله صلى الله عليه وآله وسلم في مغازية، تداوي الجرحى وتقوم على المرضى."],[40550,"روى عنها ذلك موسى بن القاسم، وحديثها عن النبي صلى الله عليه وآله وسلم أن النبي صلى الله عليه وآله وسلم قال لعائشة: «هذا علي بن أبي طالب أول الناس إيمانا»."],[40551,"أخرجها الثلاثة."],[40552,"٧٢٧٤ - ليلى بنت قانف"],[40553,"ب د ع: ليلى بنت قانف الثقفية"],[40554,"أخبرنا أبو ياسر، بإسناده عن عبد الله، حدثني أبي، حدثنا يعقوب بن إبراهيم، حدثنا أبي، عن ابن إسحاق، حدثنا نوح بن حكيم الثقفي، وكان قارئا للقرآن عن رجل من ولد عروة بن مسعود يقال له: داود قد ولدته أم حبيبة بنت أبي سفيان، عن ليلى بنت قانف، أنها قالت: «كنت فيمن شهد غسل أم كلثوم بنت النبي صلى الله عليه وآله وسلم قالت: فأول ما أعطانا النبي صلى الله عليه وآله وسلم من كفنها الحقو، ثم الدرع، ثم الخمار، ثم الملحفة، ثم أدرجت في الثوب الآخر إدراجا، ورسول الله صلى الله عليه وآله وسلم عند الباب معه كفنها يناولنا ثوبا ثوبا»."],[40555,"قانف: بالنون."],[40556,"أخرجها الثلاثة"],[40557,"٧٢٧٥ - ليلى بنت نهيك"],[40558,"ليلى بنت نهيك بن إساف بن عدي بن جشم بن مجدعة وهي أخت البراء."],[40559,"بايعت رسول الله صلى الله عليه وآله وسلم قاله ابن حبيب."],[40560,"حرف الميم"],[40561,"٧٢٧٦ - مارية القبطية"],[40562,"ب د ع: مارية القبطية مولاة رسول الله صلى الله عليه وآله وسلم وسريته وهي أم ولده إبراهيم ابن النبي صلى الله عليه وآله وسلم أهداها له المقوقس صاحب الإسكندرية، وأهدى معها أختها سيرين وخصيا يقال له: مأبور، وبغلة شهباء، وحلة من حرير."],[40563,"وقال محمد بن إسحاق: أهدى المقوقس إلى رسول الله صلى الله عليه وآله وسلم جواري أربعا، منهن: مارية أم إبراهيم، وسيرين التي وهبها النبي صلى الله عليه وآله وسلم لحسان بن ثابت، فولدت له عبد الرحمن."],[40564,"وأما مأبور الخصي الذي أهداه المقوقس مع مارية، وهو الذي اتهم بمارية، فأمر النبي صلى الله عليه وآله وسلم عليا أن يقتله، فقال علي: يا رسول الله، أكون كالسكة المحماة، أو الشاهد يرى ما لا يرى الغائب؟ فقال: «بل الشاهد يرى ما لا يرى الغائب»."],[40565,"فذهب علي إليه ليقتله فرآه مجبوبا ليس له ذكر، فعاد إلى رسول الله صلى الله عليه وآله وسلم فقال: إنه لمجبوب."],[40566,"وأهديت مارية فوصلت إلى المدينة سنة ثمان، وتوفيت سنة ست عشرة في خلافة عمر."],[40567,"وكان عمر يجمع الناس بنفسه لشهود جنازتها، وصلى عليها عمر."],[40568,"أخرجها الثلاثة."],[40569,"٧٢٧٧ - مارية جارية النبي ﷺ"],[40570,"ب د ع: مارية جارية النبي صلى الله عليه وآله وسلم تكنى أم الرباب حديثها عند أهل البصرة، أنها قالت: تطأطأت للنبي صلى الله عليه وآله وسلم حتى صعد حائطا ليلة فر من المشركين."],[40571,"رواه عبد الله بن حبيب، عن أم سليمان، عن أمها، عن جدتها مارية."],[40572,"أخرجها الثلاثة."],[40573,"٧٢٧٨ - مارية خادم النبي ﷺ"],[40574,"ب د ع: مارية خادم النبي صلى الله عليه وآله وسلم جدة المثنى بن صالح بن مهران، مولى عمرو بن حريث."],[40575,"لها حديث واحد من حديث أهل الكوفة، رواه أبو بكر بن عياش، عن المثنى بن صالح بن مهران، عن جدته مارية وكانت خادما لرسول الله صلى الله عليه وآله وسلم قالت: ما مسست بيدي شيئا قط ألين من كف رسول الله صلى الله عليه وآله وسلم. أخرجها الثلاثة، وقال أبو عمر: لا أدري أهي الأولى أم لا؟ وقال أبو نعيم: أفردها المتأخر يعني: ابن منده عن المتقدمة، وهي عندي المتقدمة."],[40576,"والله أعلم."],[40577,"٧٢٧٩ - مارية مولاة حجير"],[40578,"ب: مارية أو ماوية مولاة حجير بن أبي إهاب التميمي حليف بني نوفل هي التي حبس في بيتها خبيب بن عدي."],[40579,"أخبرنا عبيد الله بن أحمد، بإسناده عن يونس، عن ابن إسحاق، عن ابن أبي نجيح، عن ماوية مولى حجير بن أبي إهاب، قالت: حبس خبيب بمكة في بيتي، فلقد طلعت عليه يوما وإن في يده لقطفا من عنب أعظم من رأسه، يأكل منه، وما في الأرض يومئذ حبة عنب."],[40580,"هكذا في رواية يونس والبكائي عن ابن إسحاق ماوية بالواو، ورواه عبد الله بن إدريس مارية بالراء."],[40581,"أخرجها أبو عمر"],[40582,"٧٢٨٠ - محبة بنت الربيع"],[40583,"محبة بنت الربيع بن عمرو بن أبي زهير الأنصارية ثم من بلحارث بن الخزرج، أخت سعد بن الربيع."],[40584,"بايعت النبي صلى الله عليه وآله وسلم قاله ابن حبيب."],[40585,"٧٢٨١ - محجنة"],[40586,"د ع: محجنة سوداء كانت تقم المسجد فتوفيت على عهد رسول الله صلى الله عليه وآله وسلم. روى يحيى بن أبي أنيسة، عن علقمة بن مرثد، عن رجل من أهل المدينة، قال: كانت امرأة من أهل المدينة يقال لها: محجنة كانت تقم المسجد، فتفقدها رسول الله صلى الله عليه وآله وسلم فأخبر أنها قد ماتت، فقال: «ألا آذنتموني بها؟» فخرج فصلى عليها وكبر أربعًا."],[40587,"قال يحيى بن أبي أنيسة: وحدثنا الزهري، عن أبي أمامة بن سهل، عن النبي صلى الله عليه وآله وسلم نحوه."],[40588,"أخرجها ابن منده، وأبو نعيم."],[40589,"٧٢٨٢ - محياة بنت خالد بن سنان"],[40590,"س: محياة بنت خالد بن سنان"],[40591,"أخبرنا أبو موسى، إجازة، أخبرنا أبو الرجاء أحمد بن محمد بن عبد العزيز القارئ، أخبرنا أبو بكر محمد بن أحمد الصفار، أخبرنا أبو سعيد محمد بن علي بن عمرو، أخبرنا أبو بكر أحمد بن إبراهيم الجرجاني، حدثني محمد بن عمير الرازي الحافظ، حدثني عمرو بن إسحاق بن العلاء، حدثني جدي إبراهيم بن العلاء، حدثنا أبو محمد القرشي الهاشمي، حدثنا هشام بن عروة، عن ابن عمارة، عن أبيه عمارة بن حزن بن شيطان بقصة خالد بن سنان، قال: فلما بعث الله محمدا صلى الله عليه وآله وسلم أتته محياة بنت خالد، فانتسبت له، فبسط لها رداءه وأجلسها عليه، وقال: «ابنة أخي نبي ضيعه قومه»."],[40592,"أخرجها أبو موسى"],[40593,"٧٢٨٣ - مرضية"],[40594,"مرضية ذكرها ابن أبي عاصم في الوحدان."],[40595,"أخبرنا يحيى بن محمود، إجازة، بإسناده إلى أحمد بن عمرو بن أبي عاصم، حدثنا عمرو بن بشر أبو حفص الصيرفي، حدثنا يحيى بن راشد، حدثنا محمد بن حمران، حدثنا عبد الله بن حبيب، عن أم سليمان، عن أمها مرضية، أنها قالت: أراكم تنكرون شيئا رأيته يصنع على عهد رسول الله صلى الله عليه وآله وسلم: رأيت الميت على عهد رسول الله صلى الله عليه وآله وسلم يتبع بالمجمر"],[40596,"٧٢٨٤ - مريم بنت إياس"],[40597,"ب: مريم بنت إياس الأنصارية مدنية روى عنها عمرو بن يحيى المازني."],[40598,"أخرجها أبو عمر مختصرا."],[40599,"٧٢٨٥ - مريم المغالية"],[40600,"ع س: مريم المغالية امرأة ثابت بن قيس بن شماس."],[40601,"روى يونس بن بكير، عن ابن إسحاق، عن عبادة بن الوليد بن عبادة بن الصامت، عن الربيع بنت معوذ، «أنها اختلعت من زوجها، فأمرها عثمان أن تبرئ رحمها بحيضة واحدة، قالت الربيع: وإنما أخذ ذلك عثمان رضي الله عنه من قول رسول الله صلى الله عليه وآله وسلم لمريم المغالية حين افتدت من زوجها»."],[40602,"أخرجها أبو نعيم، وأبو موسى."],[40603,"٧٢٨٦ - مزيدة العصرية"],[40604,"ع س: مزيدة العصرية روى هود بن عبد الله بن سعد، عن جدته مزيدة العصرية، أن رسول الله صلى الله عليه وآله وسلم عقد رايات الأنصار وجعلها صفرا."],[40605,"أخرجها أبو نعيم، وأبو موسى."],[40606,"قلت: جعل أبو نعيم مزيدة في هذه الترجمة امرأة، وقد ذكره هو وغيره في الرجال فقال: مزيدة بن جابر العصري العبدي، جد هود بن عبد الله بن سعد."],[40607,"وهو الصواب، وذكره في النساء وهم."],[40608,"قال البخاري: مزيدة العصري العبدي، له صحبة."],[40609,"روى عنه هود بن عبد الله يعد في البصريين."],[40610,"وكذلك ذكره أبو عروبة الحراني، وأبو عمر، وغيرهم."],[40611,"وقد ذكره أبو موسى، وقال: إنما مزيدة رجل لا امرأة."],[40612,"والله أعلم."],[40613,"٧٢٨٧ - مسرة"],[40614,"د ع: مسرة كان اسمها غيرة، فسماها رسول الله صلى الله عليه وآله وسلم مسرة."],[40615,"لها ذكر في حديث رواه زيد بن أبي أنيسة، عن الزهري مرسلا."],[40616,"أخرجها ابن منده، وأبو نعيم مختصرا."],[40617,"٧٢٨٨ - مسيكة جارية عبد الله بن أبي ابن سلول"],[40618,"د ع: مسيكة جارية عبد الله بن أبي ابن سلول نزلت فيها وفي أميمة: ﴿وَلا تُكْرِهُوا فَتَيَاتِكُمْ عَلَى الْبِغَاءِ﴾ قاله ابن منده."],[40619,"وروى عن أبي معاوية، عن الأعمش، عن أبي سفيان، عن جابر أن أميمة ومسيكة جاريتي عبد الله، شكتا إلى النبي صلى الله عليه وآله وسلم عبد الله بن أبي فنزلت: ﴿وَلا تُكْرِهُوا فَتَيَاتِكُمْ عَلَى الْبِغَاءِ﴾"],[40620,"أخبرنا أبو الفضل بن أبي الحسن الطبري الفقيه، بإسناده عن أبي يعلى أحمد بن علي، حدثنا ابن نمير، حدثنا ابن أبي عبيدة، عن أبيه، عن الأعمش، عن أبي سفيان، عن جابر، قال: «كانت جارية لعبد الله بن أبي يقال لها: مسيكة، فأكرهها، فأتت النبي صلى الله عليه وآله وسلم فشكت ذلك إليه، فأنزل الله تعالى: ﴿وَلا تُكْرِهُوا فَتَيَاتِكُمْ عَلَى الْبِغَاءِ إِنْ أَرَدْنَ تَحَصُّنًا لِتَبْتَغُوا عَرَضَ الْحَيَاةِ الدُّنْيَا﴾»."],[40621,"الآية."],[40622,"أخرجها ابن منده، وأبو نعيم، وقد ذكرناها في معاذة أتم من هذا"],[40623,"٧٢٨٩ - مطيعة بنت النعمان"],[40624,"مطيعة بنت النعمان بن مالك الأنصارية من بني عمرو بن عوف."],[40625,"كان اسمها عاصية، فسماها رسول الله صلى الله عليه وآله وسلم مطيعة، وبايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[40626,"٧٢٩٠ - معاذة زوج الأعشى"],[40627,"س: معاذة زوج الأعشى المازنية وهي التي نشزت على زوجها الأعشى."],[40628,"أخبرنا أبو موسى، إجازة، أخبرنا أبو غالب الكوشيدي ومحمد بن أبي القاسم النقراني وأبو شكر أحمد بن علي الحبال، قالوا: أخبرنا أبو بكر محمد بن عبد الله بن أحمد، حدثنا سليمان بن أحمد، أخبرنا عبد الله بن أحمد بن حنبل، حدثني العباس بن عبد العظيم العنبري، حدثنا أبو سلمة عبيد بن عبد الرحمن الحنفي، حدثنا الجنيد بن أمين بن ذروة بن نضلة بن طريف بن بهصل الحرمازي، حدثنا أمين، عن أبيه ذروة، عن أبيه نضلة، أن رجلا منهم يقال له: الأعشى واسمه عبد الله بن الأعور وكانت عنده امرأة من قومه يقال لها: معاذة، خرج في رجب يمير أهله من هجر، فهربت امرأته بعده ناشزا، فعاذت برجل منهم، فأتى النبي صلى الله عليه وآله وسلم فأنشأ يقول:"],[40629,"يا سيد الناس وديان العرب … أشكو إليك ذربة من الذرب"],[40630,"كالذئبة الغبساء في ظل السرب … أخلفت العهد وألطت بالذنب"],[40631,"خرجت أبغيها الطعام في رجب … فخلفتني بنزاع وهرب"],[40632,"وأوردتني بين عيص مؤتشب … وهن شر غالب لمن غلب"],[40633,"أخرجه أبو موسى."],[40634,"وقد تقدمت القصة في الأعشى"],[40635,"٧٢٩١ - معاذة جارية عبد الله بن أبي ابن سلول"],[40636,"ب س: معاذة جارية عبد الله بن أبي ابن سلول روى الليث، عن عقيل، عن الزهري، عن محمد بن ثابت أخي بني الحارث بن الخزرج، في قوله عز وجل: «﴿وَلا تُكْرِهُوا فَتَيَاتِكُمْ عَلَى الْبِغَاءِ﴾، قال: نزلت في معاذة جارية عبد الله بن أبي ابن سلول، وذلك أنه كان عنده أسير فكان عبد الله يضربها لتمكنه من نفسها، رجاء أن تحبل منه، فيأخذ في ذلك فداء، وهو العرض الذي، قال الله عز وجل: ﴿لِتَبْتَغُوا عَرَضَ الْحَيَاةِ الدُّنْيَا﴾ وكانت الجارية تأبى عليه وهي مسلمة، قال الزهري: كانت مسلمة فاضلة، فأنزل الله هذه الآية، ثم إنها عتقت وبايعت النبي صلى الله عليه وآله وسلم بيعة النساء، فتزوجها بعد ذلك سهل بن قرظة، أخو بني عمرو بن عوف، فولدت عبد الله بن سهل وأم سعيد بنت سهل، ثم هلك عنها أو فارقها فتزوجها الحمير بن عدي القاري، أخو بني خطمة، فولدت له توأما: الحارث وعديا ابني الحمير، ثم فارقها فتزوجها عامر بن عدي رجل من بني خطمة أيضا، فولدت له أم حبيب بنت عامر»."],[40637,"قيل في نسبها: معاذة بنت عبد الله بن حبر بن الضرير بن أمية بن خدارة بن الحارث بن الخزرج."],[40638,"وقال ابن ماكولا: وأما الضرير بضم الضاد المعجمة، وفتح الراء فمعاذة بنت عبد الله بن حبر بن الضرير بن أمية بن خدارة بن الحارث بن الخزرج."],[40639,"وذكر من أمرها نحو ما تقدم."],[40640,"أخرجها أبو عمر، وأبو موسى."],[40641,"إلا أن أبا عمر قال: معاذة بنت عبد الله، وقيل: مسيكة."],[40642,"قال الزهري: معاذة."],[40643,"وقال الأعمش، عن أبي سفيان، عن جابر: اسمها مسيكة، قال: والصحيح قول ابن شهاب إن شاء الله تعالى."],[40644,"وقد روى أبو صالح، عن ابن عباس القصة، وسمى الجارية، مسيكة، فوافق الأعمش، والله أعلم."],[40645,"قلت: قول ابن شهاب في نسبها ما ذكرناه إلى خدارة، يدل على أن الأنصار قد كان يسبي بعضهم بعضا في الجاهلية فإن بني خدرة، وخدارة هم من ولد الحارث بن الخزرج، وعبد الله بن أبي من بني الحبلي بن غنم بن عوف بن الخزرج، فكلهم خزرجيون، ومع ذا فقد كانت معاذة من خدارة وهي أمة لعبد الله بن أبي، والله أعلم."],[40646,"٧٢٩٢ - معاذة الغفارية"],[40647,"س: معاذة الغفارية"],[40648,"أخبرنا أبو موسى، كتابة، قال: أخبرنا أبو سعد محمد بن عبد الله المعداني، حدثنا أبو الحسين بن أبي القاسم، حدثنا أحمد بن موسى، حدثني محمد بن علي، حدثنا جعفر بن أحمد بن رزين الموصلي، حدثنا يعقوب الدورقي، حدثنا يعلى بن عبيد، حدثنا حارثة بن أبي الرجال، عن عمرة، قالت: قالت لي معاذة الغفارية: كنت أنيسا برسول الله صلى الله عليه وآله وسلم أخرج معه في الأسفار، أقوم على المرض وأداوي الجرحى، فدخلت على رسول الله صلى الله عليه وآله وسلم ببيت عائشة وعلي رضي الله عنهما خارج من عنده، فسمعته يقول: «يا عائشة، إن هذا أحب الرجال إلي وأكرمهم علي، فاعرفي له حقه وأكرمي مثواه»."],[40649,"وذكر الحديث في «النظر إلى علي عبادة»."],[40650,"أخرجها أبو موسى"],[40651,"٧٢٩٣ - مليكة جدة إسحاق بن عبد الله"],[40652,"ب د ع: مليكة جدة إسحاق بن عبد الله بن أبي طلحة وقيل جدة أنس بن مالك لها صحبة."],[40653,"روى عنها أنس بن مالك."],[40654,"أخبرنا أبو الحرم مكي بن ربان النحوي، بإسناده عن يحيى بن يحيى، عن مالك، عن إسحاق بن عبد الله بن أبي طلحة، عن أنس بن مالك، أن جدته مليكة دعت النبي صلى الله عليه وآله وسلم لطعام، فأكل منه، ثم قال: «قوموا فلأصلي لكم»."],[40655,"قال أنس: فقمت إلى حصير قد اسود من طول ما لبس فنضحته بالماء، فقام عليه رسول الله صلى الله عليه وآله وسلم وصففت أنا واليتيم خلفه، والعجوز من ورائنا، فصلى بنا ركعتين، ثم انصرف."],[40656,"وأخرجه الترمذي، عن إسحاق الأنصاري، عن معن، عن مالك، به. قيل: إنها أم سليم، وقيل: أم حرام."],[40657,"ولا يصح ذلك، والاختلاف في اسم أم سليم كثير على ما نذكره في اسمها، إن شاء الله تعالى."],[40658,"أخرجها الثلاثة، إلا أن أبا عمر قال: جدة إسحاق."],[40659,"وقال ابن منده، وأبو نعيم: جدة أنس بن مالك."],[40660,"قلت: يصح قول أبي عمر أنها جدة إسحاق، لأنه إسحاق بن عبد الله، وأم عبد الله أم سليم."],[40661,"ولا يصح أن تكون أم سليم على قول ابن منده وأبي نعيم، لأن أم سليم هي أم أنس بن مالك وليست بجدة له، ولم تكن لأنس جدة من أبيه ولا من أمه مسلمة، حتى يحمل عليها، فما أقرب قول أبي عمر من الصحيح، والله أعلم"],[40662,"٧٢٩٤ - مليكة بنت خارجة"],[40663,"ب: مليكة ويقال حبيبة بنت خارجة بن زيد بن أبي زهير الأنصارية تقدم ذكرها في حبيبة."],[40664,"أخرجها أبو عمر."],[40665,"٧٢٩٥ - مليكة بنت خارجة"],[40666,"س: مليكة بنت خارجة بن سنان بن أبي حارثة بن مرة بن عوف بن سعد بن ذبيان بن بغيض بن ريث بن غطفان بن سعد بن قيس عيلان المرية روى ابن جريج، عن عكرمة، قال: فرق الإسلام بين أربع نسوة وبين أبناء بعولتهن."],[40667,"وذكر منهن: مليكة بنت خارجة بن سنان، كانت تحت زبان بن سيار بن عمرو بن جابر بن عقيل بن هلال بن سمي بن مازن بن فزارة الفزاري، فخلف عليها ابنه منظور بن زبان."],[40668,"أخرجها أبو موسى."],[40669,"٧٢٩٦ - مليكة امرأة خباب بن الأرت"],[40670,"د: مليكة امرأة خباب بن الأرت أدركت النبي صلى الله عليه وآله وسلم. روى حديثها أبو خالد الدالاني، عن المنهال بن عمرو موقوفا."],[40671,"أخرجها ابن منده مختصرا."],[40672,"٧٢٩٧ - مليكة أم السائب"],[40673,"د ع: مليكة أم السائب بن الأقرع الثقفية كانت تبيع العطر."],[40674,"روى عطاء بن السائب، عن بعض أصحابه، عن السائب بن الأقرع أن أمه مليكة دخلت تبيع العطر من النبي صلى الله عليه وآله وسلم فقال لها: «يا مليكة، ألك حاجة؟» قالت: نعم قال: «فكلميني فيها أقضها لك»، فقالت: لا، والله لا إلا أن تدعو لابني وهو معها، وهو غلام فأتاه فمسح برأسه، ودعا له."],[40675,"أخرجها ابن منده، وأبو نعيم."],[40676,"٧٢٩٨ - مليكة بنت عمرو الزيدية"],[40677,"ب د ع: مليكة بنت عمرو الزيدية من زيد اللات بن سعد سعد العشيرة بن مذحج."],[40678,"حديثها عند زهير بن معاوية عن امرأة من أهله، عنها، قالت: اشتكيت وجعا في حلقي، فأتيتها، فوصفت لي سمن بقر، وقالت: إن رسول الله صلى الله عليه وآله وسلم قال: «ألبانها شفاء، وسمنها دواء»."],[40679,"أخبرنا يحيى بن محمود، فيما أذن لي، بإسناده عن أبي بكر بن أبي عاصم، حدثنا إسماعيل بن عبد الله بن عثمان بن صالح، حدثنا عبد الله بن وهب، قال: كتب إلي حمزة بن عبد الواحد بن محمد بن عمرو بن حلحلة، عن محمد بن عمرو، أن مليكة أخبرته، أنها سمعت رسول الله صلى الله عليه وآله وسلم يقول: «إذا سمعتم بقوم قد خسف بهم فقد أظلت الساعة»."],[40680,"أخرجها الثلاثة"],[40681,"٧٢٩٩ - مليكة بنت عمرو بن سهل"],[40682,"مليكة بنت عمرو بن سهل الأنصارية من بني عبد الأشهل، امرأة أبي الهيثم بن التيهان."],[40683,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[40684,"٧٣٠٠ - مليكة بنت عويمر"],[40685,"ب س: مليكة بنت عويمر الهذلية إحدى المرأتين اللتين ضربت إحداهما بطن الأخرى، فألقت جنينا، وكانتا ضرتين هذليتين."],[40686,"قال ابن عباس: كان اسم إحداهما مليكة والأخرى أم عطيف."],[40687,"رواه سماك، عن عكرمة، عن ابن عباس."],[40688,"أخرجها أبو عمر، وأبو موسى."],[40689,"إلا أن أبا موسى، قال: بنت عويم بغير راء قال: وقيل: بنت ساعدة، وقال: أم عفيف، بفاءين."],[40690,"وأما أبو عمر فقال: عويمر براء، وغطيف بغين معجمة وطاء."],[40691,"فقول أبي موسى يدل على أنها بنت عويم بن ساعدة الأنصاري أو أخته، والقصة التي ساقها أبو موسى في إلقاء الجنين وقضاء رسول الله صلى الله عليه وآله وسلم فيه بغرة عبد أو أمة يدل على أنها من هذيل."],[40692,"٧٣٠١ - مندوس بنت خلاد"],[40693,"مندوس بنت خلاد بن سويد بن ثعلبة الأنصارية الخزرجية بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[40694,"٧٣٠٢ - مندوس بنت عبادة"],[40695,"مندوس بنت عبادة بن دليم بن حارثة بن أبي حزيمة الأنصارية الساعدية وهي أخت سعد بن عبادة."],[40696,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[40697,"٧٣٠٣ - مندوس بنت عمرو"],[40698,"مندوس بنت عمرو بن خنيس بن لوذان بن عبد ود الأنصارية، أخت المنذر بن عمرو، وهي أم مسلمة بن مخلد."],[40699,"بايعت النبي صلى الله عليه وآله وسلم. قاله ابن حبيب."],[40700,"٧٣٠٤ - منيعة"],[40701,"د ع: منيعة رأت النبي صلى الله عليه وآله وسلم. روت عنها ابنتها قريبة."],[40702,"أنها أتت النبي صلى الله عليه وآله وسلم فقال: «ما نجواك؟» فأخبرته بأمرها وهي منتقبة فقال: «يا أمة الله، أسفري فإن الإسفار من الإسلام، وإن النقاب من الفجور»."],[40703,"أخرجه ابن منده، وأبو نعيم."],[40704,"٧٣٠٥ - ميمونة بنت الحارث الهلالية"],[40705,"ب د ع: ميمونة بنت الحارث بن حزن الهلالية تقدم نسبها عند أختها لبابة."],[40706,"وميمونة زوج النبي صلى الله عليه وآله وسلم وقد تقدم ذكر أخواتها: لبابة الكبرى، ولبابة الصغرى، وأسماء بنت عميس، وغيرهن."],[40707,"وكان اسم ميمونة برة فسماها رسول الله صلى الله عليه وآله وسلم ميمونة، قاله كريب، عن ابن عباس، وهي خالته وخالة خالد بن الوليد وكانت قبل رسول الله صلى الله عليه وآله وسلم عند أبي رهم بن عبد العزى بن عبد ود بن مالك بن حسل بن عامر بن لؤي، وقيل: عند سخبرة بن أبي رهم، وقيل: كانت عند خويطب بن عبد العزى، وقيل: عند فروة بن عبد العزى الأسدي أسد بن خزيمة."],[40708,"قاله قتادة."],[40709,"تزوجها رسول الله صلى الله عليه وآله وسلم بعد زوجها سنة سبع في عمرة القضاء في ذي القعدة، فأرسل رسول الله صلى الله عليه وآله وسلم جعفر بن أبي طالب إليه فخطبها، فجعلت أمرها إلى العباس بن عبد المطلب، فزوجها من رسول الله صلى الله عليه وآله وسلم وقيل: بل العباس، قال لرسول الله صلى الله عليه وآله وسلم: إن ميمونة بنت الحارث قد تأيمت من أبي رهم بن عبد العزى، هل لك أن تزوجها؟ فتزوجها رسول الله صلى الله عليه وآله وسلم"],[40710,"أخبرنا أبو جعفر، بإسناده عن يونس بن بكير، عن ابن إسحاق، قال: «ثم تزوج رسول الله صلى الله عليه وآله وسلم بعد صفية ميمونة بنت الحارث الهلالية، وكانت قبله عند أبي رهم بن عبد العزى»"],[40711,"قال يونس: حدثنا جعفر بن برقان، عن ميمون بن مهران، عن يزيد بن الأصم، قال: «تزوج رسول الله صلى الله عليه وآله وسلم ميمونة وهو حلال في قبة لها»، وماتت فيها، ويزيد هو ابن أخت ميمونة، وقيل: تزوجها وهو محرم"],[40712,"أخبرنا غير واحد، بإسنادهم عن محمد بن عيسى، حدثنا حميد بن مسعدة، حدثنا سفيان بن حبيب، عن هشام بن حسان، عن عكرمة، عن ابن عباس، «أن النبي صلى الله عليه وآله وسلم تزوج ميمونة وهو محرم» ولهذا الاختلاف اختلف الفقهاء في نكاح المحرم، وقال بعضهم: تزوجها رسول الله صلى الله عليه وآله وسلم وهو حلال، وظهر أمر تزويجها وهو محرم ثم بنى بها وهو حلال بسرف بطريق مكة، وماتت بسرف أيضا حيث بنى بها رسول الله صلى الله عليه وآله وسلم ودفنت هناك."],[40713,"ولما فرغ رسول الله صلى الله عليه وآله وسلم من عمرته أقام بمكة ثلاثا، فأتاه سهيل بن عمرو، في نفر من أهل مكة فقالوا: يا محمد، اخرج عنا فاليوم آخر شرطك وكان شرط في الحديبية أن يعتمر من قابل، ويقيم بمكة ثلاثا، فقال: «دعوني أبتني بأهلي وأصنع لكم طعاما»، فقالوا: لا حاجة لنا بطعامك."],[40714,"فخرج فبنى فيها بسرف قريب من مكة."],[40715,"وقال ابن شهاب وقتادة: هي التي وهبت نفسها للنبي صلى الله عليه وآله وسلم فأنزل الله تعالى: ﴿وَامْرَأَةً مُؤْمِنَةً إِنْ وَهَبَتْ نَفْسَهَا لِلنَّبِيِّ﴾."],[40716,"الآية."],[40717,"والصحيح ما تقدم أخبرنا أبو منصور بن مكارم بن أحمد، بإسناده عن المعافي بن عمران، عن هشام بن سعد، عن زيد بن أسلم، عن عطاء بن يسار، عن ميمونة زوج النبي صلى الله عليه وآله وسلم أنه سئل عن الجبن فقال: «اقطع بالسكين، وسم الله تعالى، وكل» وتوفيت سنة إحدى وخمسين، وقيل: سنة ثلاث وستين عام الحرة، وصلى عليها ابن عباس، ودخل قبرها هو ويزيد بن الأصم."],[40718,"وعبد الله بن شداد بن الهاد، وهم أولاد أخواتها، ونزل معهم عبيد الله الخولاني، وكان يتيما في حجرها."],[40719,"أخرجها الثلاثة."],[40720,"٧٣٠٦ - ميمونة مولاة رسول الله ﷺ"],[40721,"ب د ع: ميمونة مولاة رسول الله صلى الله عليه وآله وسلم روى عنها علي بن أبي طالب، وزياد بن أبي سودة."],[40722,"قال أبو نعيم: هي عندي ميمونة بنت سعد، وقد أفردها المتأخر، يعني: ابن منده."],[40723,"روى معاوية بن صالح، عن زياد بن أبي سودة، عن ميمونة، وليست زوج النبي صلى الله عليه وآله وسلم أنها قالت: يا رسول الله، افتنا عن بيت المقدس، فقال رسول الله صلى الله عليه وآله وسلم: «أرض المحشر والمنشر، ائتوه فصلوا فيه، فإن الصلاة فيه كألف صلاة»."],[40724,"قالت: أرأيت يا رسول الله من لم يطلق أن يأتيه؟ قال: «فإن لم يطق ذلك فليهد إليه زيتا يسرج فيه، فمن أهدى إليه كان كمن صلى فيه»."],[40725,"وروى عبيد الله بن موسى، عن إسرائيل، عن زيد بن جبير، عن أبي يزيد الضبي، عن ميمونة مولاة رسول الله صلى الله عليه وآله وسلم أن رسول الله صلى الله عليه وآله وسلم سئل عن ولد الزنا، فقال: «لا خير فيه، نعلان أجاهد فيهما أحب إلي من أن أعتق ولد الزنا»."],[40726,"وأن رسول الله صلى الله عليه وآله وسلم سئل عن رجل قبل امرأته صائما، فقال: «أفطر»."],[40727,"أخرجها الثلاثة، إلا أن أبا عمر أخرج لهذه فضل بيت المقدس، «وأن أشد عذاب القبر في الغيبة والبول»."],[40728,"٧٣٠٧ - ميمونة بنت سعد"],[40729,"د ع: ميمونة بنت سعد خادم رسول الله صلى الله عليه وآله وسلم روى حديثها أيوب بن خالد، وهلال بن أبي هلال."],[40730,"أخبرنا إسماعيل بن علي، وغيره، بإسنادهم عن محمد بن عيسى، قال: حدثنا علي بن خشرم، أخبرنا عيسى بن يونس، عن موسى بن عبيدة، عن أيوب بن خالد، عن ميمونة بنت سعد، وكانت تخدم النبي صلى الله عليه وآله وسلم أن النبي صلى الله عليه وآله وسلم قال: «مثل الرافلة في الزينة في غير أهلها كمثل الظلمة يوم القيامة لا نور لها» وروى عن محمد بن هلال، عن أبيه، أنه سمع ميمونة بنت سعد، تقول: سمعت رسول الله صلى الله عليه وآله وسلم يقول: «من أجمع الصوم من الليل فليصم، ومن أصبح ولم يجمع فلا يصم»."],[40731,"أخرجها ابن منده، وأبو نعيم."],[40732,"٧٣٠٨ - ميمونة بنت صبيح"],[40733,"ع س: ميمونة بنت صبيح، وقيل: صفيح بن الحارث، أم أبي هريرة سماها الطبراني، ولم تسم في الحديث الذي ذكرناه في أميمة."],[40734,"وقال أبو محمد بن قتيبة: خالة سعيد بن صفيح، كان من أشد الناس."],[40735,"أخبرنا عبد الوهاب بن أبي حبة، بإسناده عن عبد الله بن أحمد، حدثني أبي، حدثنا عبد الرحمن، حدثنا عكرمة بن عمار، حدثني أبو كثير، حدثنا أبو هريرة، قال: ما «خلق الله مؤمنا سمع بي ولا يراني إلا أحبني."],[40736,"قلت: وما علمك بذلك يا أبا هريرة؟ قال: إن أمي كانت امرأة مشركة، وإني كنت أدعوها إلى الإسلام فتأتي علي …"],[40737,"»."],[40738,"وذكر إسلام أبي هريرة بطوله، وهو مذكور في الكنى في أم أبي هريرة، فلا نطول بذكره."],[40739,"أخرجها أبو نعيم، وأبو موسى"],[40740,"٧٣٠٩ - ميمونة بنت عبد الله"],[40741,"ميمونة بنت عبد الله من بني مريد: بطن من بلي وكان يقال لهم: الجعادرة، حلفاء بني أمية بن زيد من الأنصار."],[40742,"قاله ابن إسحاق وذكر إسلامها، وسماها ابن هشام، وهي التي أجابت كعب بن الأشرف في بكائه قتلى بدر بأبيات أولها: بكت عين من يبكي لبدر وأهله وعلت بمثليه لؤي بن غالب."],[40743,"استدركه الغساني على أبي عمر."],[40744,"٧٣١٠ - ميمونة بنت أبي عنبسة"],[40745,"ب د ع: ميمونة بنت أبي عنبسة أو بنت عنبسة قاله ابن منده، وأبو عمر."],[40746,"وقال أبو نعيم: وهو تصحيف، وإنما هو عسيب، ورواه كذلك."],[40747,"روى المسجع بن مصعب أبو عبد الله العبدي، عن ربيعة بنت مرثد، وكانت تنزل في بني قريع، عن منبه، عن ميمونة بنت أبي عسيب، وقيل: بنت أبي عنبسة مولاة النبي صلى الله عليه وآله وسلم أن امرأة من جرش أتت النبي صلى الله عليه وآله وسلم فقالت: يا عائشة، أغيثيني بدعوة من رسول الله صلى الله عليه وآله وسلم تسكنيني بها، وتطمنيني بها، وأنه قال لها: «ضعي يدك اليمني على فؤادك فامسحيه وقولي: بسم الله، اللهم داوني بدوائك، واشفني بشفائك، وأغنني بفضلك عمن سواك»."],[40748,"قالت ربيعة: فدعوت به فوجدته جيدا."],[40749,"أخرجها الثلاثة."],[40750,"٧٣١١ - ميمونة بنت كردم"],[40751,"ب د ع: ميمونة بنت كردم الثقفية."],[40752,"روى عنها يزيد بن مقسم"],[40753,"أخبرنا أبو ياسر، بإسناده عن عبد الله، حدثني أبي، حدثنا يزيد بن هارون، عن عبد الله بن يزيد بن مقسم بن ضبة الطائفي، قال: سمعت عمتي سارة بنت مقسم، عن ميمونة بنت كردم، قالت: رأيت رسول الله صلى الله عليه وآله وسلم بمكة وهو على ناقة له، أنا مع أبي، وبيد رسول الله صلى الله عليه وآله وسلم درة كدرة الكتاب، وسمعت الأعراب يقولون: الطبطبية الطبطبية."],[40754,"الحديث، وسأل أبوها رسول الله صلى الله عليه وآله وسلم فقال: إني كنت نذرت لأنحرن ببوانة، فقال: «هل بها وثن؟»."],[40755,"قال: لا."],[40756,"قال: «أوف بنذرك»."],[40757,"وروى الفضل بن دكين، عن عبد الله بن عبد الرحمن بن يعلى بن كعب الثقفي، عن يزيد بن مقسم، عن ميمونة."],[40758,"أخرجها الثلاثة"],[40759,"٧٣١٢ - ميمونة"],[40760,"د ع: ميمونة غير منسوبة."],[40761,"روت عنها آمنة بنت عمر."],[40762,"قال أبو نعيم: أفردها المتأخر يعني: ابن منده وذكرها سليمان بن أحمد في ميمونة بنت سعد."],[40763,"أخبرنا يحيى بن أبي الرجاء، إذنا، بإسناده عن أبي بكر بن أبي عاصم، حدثنا علي بن ميمون أبو الحسن العطار، حدثنا عثمان بن عبد الرحمن الحراني، عن عبد الحميد بن يزيد، عن آمنة بنت عمر، عن ميمونة، أنها قالت: يا رسول الله، أفتنا عن الصدقة."],[40764,"قال: «إنها حجاب من النار لمن احتسبها يبتغي بها وجه الله تعالى»."],[40765,"قالت: افتنا في ثمن الكلب."],[40766,"قال: «طعمة جاهلية وقد أغنى الله عنها»."],[40767,"قالت: أفتنا في عذاب القبر."],[40768,"قال: «أثر البول، فمن أصابه بول فليغسله، فمن لم يجد ماء مسحه بتراب طيب»."],[40769,"ذكر هذا الحديث ابن منده، وأبو نعيم وروى أبو نعيم، في هذه الترجمة أيضا عن سليمان بن أحمد، عن أحمد بن النضر العسكري، عن إسحاق بن زريق الراسبي، عن عثمان بن عبد الرحمن الطرائفي، عن عبد الحميد بن يزيد، عن آمنة بنت عمر بن عبد العزيز، عن ميمونة بنت سعد، أنها قالت: يا رسول الله، افتنا عن السرقة، قال: «من أكلها وهو يعلم أنها سرقة فقد شرك في إثمها وعارها»."],[40770,"وروى أبو نعيم، أيضا عن الحسن بن سفيان، عن عمرو بن هشام، عن عثمان بن عبد الرحمن، عن عبد الحميد، عن آمنة، عن ميمونة بنت سعد، أنها قالت: يا رسول الله، أفتنا في الغسل من الجنابة، كما يكفي الرأس من الماء؟ قال: «ثلاث حثيات»."],[40771,"أخرجها ابن منده، وأبو نعيم."],[40772,"قلت: أخرج أبو نعيم حديث سليمان بن أحمد والحسن بن سفيان، مستدلا بهما على أن آمنة بنت عمر التي ذكرها ابن منده أنها تروي عن هذه ميمونة التي لم ينسبها وجعلها غير ميمونة بنت سعد، قد روت عن ميمونة بنت سعد، ليظهر بهذا أنهما واحدة."],[40773,"وبالجملة فقد جعل أبو نعيم هذه والتي قبلها مولاة النبي صلى الله عليه وآله وسلم التي روى عنها علي، وميمونة بنت سعد واحدة، وجعلهن ابن منده ثلاثا، وأما أبو عمر فلم يترجم إلا ميمونة بنت أبي عنبسة مولاة النبي صلى الله عليه وآله وسلم وميمونة بنت سعد، وقال: روى عنها أيوب بن خالد في قلبة الصائم وعتق ولد الزنا، وميمونة أخرى مولاة النبي صلى الله عليه وآله وسلم وقال: حديثها عند أهل الشام في فضل بيت المقدس."],[40774,"وهذه التي تروي فضل القدس قد اتفقوا على أنها غير الثلاث، إنما الاختلاف في الثلاث كما ذكرناه، وما أقرب قول أبي نعيم من الصواب، والله أعلم."],[40775,"حرف النون"],[40776,"٧٣١٣ - نائلة بنت سعد"],[40777,"نائلة بنت سعد بن مالك الأنصارية من بني ساعدة."],[40778,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[40779,"٧٣١٤ - نبيتة بنت الضحاك"],[40780,"نبيته بنت الضحاك بن خليفة قاله ابن المديني هكذا: أوله نون، ثم باء موحدة، وياء تحتها نقطتان، ثم فوقها نقطتان."],[40781,"وقال غيره."],[40782,"ثبيته أوله ثاء مثلثة، وقد تقدمت."],[40783,"ذكر هذا الأمير أبو نصر."],[40784,"٧٣١٥ - نبعة الحبشية"],[40785,"س: نبعة الحبشية جارية أم هانئ، ذكرها عبد الغني وابن ماكولا."],[40786,"روى الكلبي، عن أبي صالح، عن أم هانئ بنت أبي طالب، في مسرى رسول الله صلى الله عليه وآله وسلم أنها كانت تقول: ما أسري برسول الله صلى الله عليه وآله وسلم إلا وهو في بيتي نائم عندي تلك الليلة، فصلى العشاء الآخرة ثم نام ونمنا، فلما كان قبل الصبح أهبنا رسول الله صلى الله عليه وآله وسلم فلما صلى الصبح وصلينا معه قال: «يا أم هانئ، لقد صليت العشاء الآخرة كما رأيت، ثم جئت بيت المقدس فصليت فيه، ثم صليت صلاة الغداة معكم»، ثم قام ليخرج فأخذت بطرف ردائه، فكشف عن بطنه وكأنه قبطية مطوية، فقلت له: يا نبي الله، لا تحدث بهذا الناس فيكذبوك ويؤذوك."],[40787,"قال: «والله لأحدثنهم»."],[40788,"قالت: فقلت لجارية لي حبشية يقال لها: نبعة: ويحك! اتبعي رسول الله صلى الله عليه وآله وسلم تسمعي ما يقول للناس وما يقولون له."],[40789,"فلما خرج رسول الله صلى الله عليه وآله وسلم إلى الناس أخبرهم، فعجبوا وقالوا: ما آية ذلك يا محمد؟."],[40790,"وذكر الحديث."],[40791,"أخرجه أبو موسى."],[40792,"٧٣١٦ - نتيلة بنت قيس"],[40793,"نتيلة بنت قيس بن جرير بن عمرو بن عوف بن مبذول الأنصارية ثم من بني مازن."],[40794,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[40795,"٧٣١٧ - ندبة مولاة ميمونة"],[40796,"ندبة مولاة ميمونة لها ذكر في حديث لعائشة."],[40797,"أخرجها ابن منده، وأبو نعيم كذا مختصرا."],[40798,"٧٣١٨ - نسيبة بنت الحارث"],[40799,"ب د ع: نسيبة بنت الحارث أم عطية الأنصارية."],[40800,"وهي مشهورة بكنيتها، ويرد ذكرها في الكنى مستقصى إن شاء الله تعالى."],[40801,"وهي التي غسلت بنت النبي صلى الله عليه وآله وسلم روت عنها حفصة بنت سيرين."],[40802,"قاله أبو عمر."],[40803,"وأما ابن منده، وأبو نعيم فجعلا أم عطية نسيبة بنت كعب، فخالفا أبا عمر في نسبها، وقالا: هي التي غسلت بنت النبي صلى الله عليه وآله وسلم وسيما أيضا أم عمارة نسيبة بنت كعب."],[40804,"وخالفهما أبو عمر في أم عطية بنت الحارث، وجعل أم عمارة نسيبة بنت كعب، مثلهما، ووافقة ابن ماكولا فقال: وأما نسيبة بضم أوله، وفتح ثانيه فهي نسيبة أم عطية الأنصارية، لها صحبة ورواية."],[40805,"روى عنها محمد ابن سيرين، وحفصة أخته، قال: وأما نسيبة بفتح أوله، وكسر ثانيه فهي أم عمارة نسيبة بنت كعب الأنصارية، كانت تشهد المشاهد مع رسول الله صلى الله عليه وآله وسلم لها رواية."],[40806,"روى عنها عبد الرحمن بن عبد الله بن أبي صعصعة، والحارث بن عبد الله بن كعب، وغيرهما، والله أعلم."],[40807,"أخرجها الثلاثة."],[40808,"نسيبة هذه: بضم النون وفتح السين."],[40809,"٧٣١٩ - نسيبة بنت كعب"],[40810,"ب د ع: نسيبة بنت كعب بن عمرو أم عمارة الأنصارية."],[40811,"شهدت العقبة."],[40812,"أخبرنا أبو جعفر، بإسناده عن يونس، عن ابن إسحاق، فيمن شهد العقبة، قال: وكان من بني الخزرج اثنان وستون رجلا وامرأتان، منهم تسعة نقباء، فيزعمون أن المرأتين قد بايعتا."],[40813,"كان رسول الله صلى الله عليه وآله وسلم لا يصافح النساء، إنما كان يأخذ عليهن، فإذا أقرن، قال: «اذهبن فقد بايعتكن»."],[40814,"والمرأتان من بني مازن بن النجار، نسيبة وأختها ابنتا كعب بن عمرو بن عوف بن مبذول بن عمرو بن غنم بن مازن بن النجار، كان معها زوجها وابناها، وزوجها زيد بن عاصم بن كعب، وابناها عبد الله، وحبيب، ابنا زيد بن عاصم."],[40815,"وابنها حبيب هو الذي أخذه مسيلمة تقدمت قصته معه، وقيل: إن المرأة الثانية: أسماء بنت عمرو بن عدي، أم منيع، وقد تقدمت روت أم عمارة، عن النبي صلى الله عليه وآله وسلم في الصائم إذا أكل عنده."],[40816,"أخرجها الثلاثة."],[40817,"نسيبة هذه: بفتح النون، وكسر السين."],[40818,"قاله الأمير أبو نصر."],[40819,"٧٣٢٠ - نسيبة بنت نيار"],[40820,"نسيبة بنت نيار بن الحارث بن بلال بن أحيحة الأنصارية من بني جحجبي، بايعت رسول الله صلى الله عليه وآله وسلم قاله ابن حبيب."],[40821,"٧٣٢١ - نسيكة بنت الجلاس"],[40822,"ع س: نسيكة أم عمرو بن الجلاس روت عنها حبيبة بنت سمعان."],[40823,"أخبرنا أبو موسى، إذنا، أخبرنا أحمد بن العباس، أخبرنا محمد بن عبد الله."],[40824,"ح قال أبو موسى: وأخبرنا الحسن بن أحمد، أخبرنا أحمد بن عبد الله، قالا: حدثنا سليمان بن أحمد، حدثنا محمد بن عبد الله الحضرمي، حدثنا عبد الله بن الحكم بن أبي زياد القطواني، حدثنا عبيد الله بن موسى، عن إبراهيم بن إسماعيل، عن حبيبة بنت سمعان نسيكة أم عمرو بن الجلاس، قالت: إني لعند عائشة رضي الله عنها وقد ذبحت شاة لها، فدخل رسول الله صلى الله عليه وآله وسلم وفي يده عصية، فألقاها ثم هوى إلى المسجد فصلى فيه ركعتين، ثم هوى إلى فراشه فانبطح عليها، ثم قال: «هل من غداء؟» فأتيناه بصحفة فيها خبز شعير، وفيها كسرة وقطعة من الكرش، وفيها الذراع، قالت: فأخذت عائشة قطعة من الكرش، فإنها لتنهشها إذ قالت: لقد ذبحنا شاة اليوم فما أمسكنا منها غير هذا."],[40825,"قالت: يقول رسول الله صلى الله عليه وآله وسلم: «لا، بل كلها أمسكت إلا هذا»."],[40826,"أخرجها ابن منده، وأبو نعيم"],[40827,"٧٣٢٢ - نعامة"],[40828,"نعامة من سبي بلعنبر."],[40829,"كانت امرأة جميلة، فعرض علهيا النبي صلى الله عليه وآله وسلم أن يتزوجها، فلم تلبث أن جاء زوجها الحريش."],[40830,"ذكرها ابن الدباغ."],[40831,"٧٣٢٣ - نعم امرأة شماس"],[40832,"نعم امرأة شماس بن عثمان بن الشريد المخزومي وقيل إنها بنت حسان أنشد لها ابن إسحاق أبياتا ترثي زوجها، وقتل بأحد: يا عين جودي بدمع غير إبساس على كريم من الفتيان لباس صعب البديهة ميمون نقيبته حمال ألوية ركاب أفراس اقول لما أتى الناعي له جزعا أودى الجواد وأودى المطعم الكاسي وقلت لما خلت منه مجالسه لا يبعد الله منا قرب شماس ذكره ابن الدباغ عن الغساني، مستدركا على أبي عمر."],[40833,"٧٣٢٤ - نعمى بنت جعفر"],[40834,"د ع: نعمى بنت جعفر بن أبي طالب ذكرت في حديث رواه عبد الملك بن جريج، عن عطاء، عن أسماء بنت عميس، أن النبي صلى الله عليه وآله وسلم قال لنعمى بنت جعفر: «ما لي أرى أجساد بني جعفر أنضاء؟ أبهم حاجة؟» قالت: لا، ولكنهم تسرع إليهم العين، أفأرقيهم؟ قالت: فعرضت عليه كلاما لا بأس به، فقال: «ارقيهم»."],[40835,"أخرجها ابن منده، وأبو نعيم."],[40836,"قلت: حديث الرقية لأولاد جعفر إنما هو معروف عن أمهم أسماء، ولا أعرف في أولاد جعفر: نعمى."],[40837,"٧٣٢٥ - نفيسة بنت أمية"],[40838,"ب: نفيسة بنت أمية أخت يعلى ابن أمية التميمي."],[40839,"لها صحبة ورواية عن النبي صلى الله عليه وآله وسلم. روت عنها أم سعد بنت سعد بن الربيع، أنها قالت: ولدت خديجة للنبي صلى الله عليه وآله وسلم القاسم، والطاهر، وزينب، ورقية، وأم كلثوم، وفاطمة، صلى الله عليهم أجمعين."],[40840,"٧٣٢٦ - نفيسة بنت عمرو"],[40841,"نفيسة بنت عمرو بن خلدة بن مخلد الأنصارية الزرقية بايعت رسول الله صلى الله عليه وآله وسلم قاله ابن حبيب."],[40842,"٧٣٢٧ - نهية"],[40843,"س: نهية وقيل لهية باللام قاله ابن ماكولا، وهي أم ولد عمرو بن الخطاب رضي الله عنه، وهو عبد الرحمن بن عمر الذي يدعى أبا شحمة، وقد تقدم ذكرها في اللام."],[40844,"أخرجها أبو موسى مختصرا."],[40845,"٧٣٢٨ - النوار بنت قيس"],[40846,"النوار بنت قيس بن الحارث بن عدي وقال ابن حبيب: النوار بنت قيس بن لوذان بن عدي بن مجدعة."],[40847,"واتفقا أنها من المبايعات."],[40848,"قاله العدوي وابن حبيب، وذكرها الغساني مستدركا على أبي عمر."],[40849,"٧٣٢٩ - النوار بنت مالك"],[40850,"ب د ع: النوار بنت مالك بن صرمة من بني عدي بن النجار."],[40851,"وهي أم زيد بن ثابت الأنصاري الفقيه الفرضي، كاتب رسول الله صلى الله عليه وآله وسلم روت عن النبي صلى الله عليه وآله وسلم. روت عنها أم سعد بنت أسعد بن زرارة."],[40852,"أخرجها الثلاثة."],[40853,"٧٣٣٠ - نوبة"],[40854,"س: نوبة قال عبد الغني بن سعيد الحافظ: ذكرها في حديث زائدة، عن عاصم، عن أبي وائل، عن مسروق، عن عائشة، قالت: مرض رسول الله صلى الله عليه وآله وسلم واشتد مرضه، فوجد في نفسه خفة فخرج بين بريرة ونوبة."],[40855,"أخرجها أبو موسى."],[40856,"٧٣٣١ - نويلة بنت أسلم"],[40857,"ب د ع: نويلة بنت أسلم وقيل بنت مسلم جدة جعفر بن محمود بن مسلمة."],[40858,"قاله أبو نعيم وابن منده."],[40859,"وقال أبو عمر: نولة بنت أسلم الأنصارية، صلت القبلتين، حديثها يروى عن جعفر بن محمود، عن جدته نولة."],[40860,"أخبرنا يحيى بن محمود، إجازة، بإسناده عن ابن أبي عاصم، حدثنا محمد بن سنان يزيد بن، عن إسحاق بن إدريس، حدثنا إبراهيم بن جعفر، عن أبيه جعفر بن محمود، عن جدته أم أبيه نويلة بنت أسلم، أنها قالت: صلينا الظهر أو العصر في مسجد بني حارثة، فاستقبلنا مسجد إيلياء، فصلينا ركعتين، ثم جاءنا من يخبرنا أن رسول الله صلى الله عليه وآله وسلم قد استقبل البيت الحرام، فتحول النساء مكان الرجال، والرجال مكان النساء، فصلينا السجدتين الباقيتين ونحن مستقبلو البيت الحرام."],[40861,"فحدثني رجل من بني حارثة، أن النبي صلى الله عليه وآله وسلم قال حين بلغه ذلك: «أولئك قوم آمنوا بالغيب»."],[40862,"أخرجها الثلاثة. قلت: قد اختلفوا في اسم هذه فقيل: بديلة بالباء الموحدة قاله الواقدي عن جعفر، وقيل: تويلة بالتاء فوقها نقطتان قاله إبراهيم بن حمزة عن جعفر، وقيل: نويلة بالنون، قاله إسحاق بن إدريس عن جعفر، والله أعلم، فإن الاسم واحد، والباقي تصحيف."],[40863,"حرف الهاء"],[40864,"٧٣٣٢ - هالة بنت خويلد"],[40865,"د ع: هالة بنت خويلد بن أسد بن عبد العزى بن قصي القرشية الأسدية أخت خديجة بنت خويلد زوج النبي صلى الله عليه وآله وسلم. ورد ذكرها في حديث عائشة."],[40866,"أخبرنا مسمار بن عمر بن العويس وأبو الفرج محمد بن عبد الرحمن، وغير واحدا، بإسنادهم عن محمد بن إسماعيل، قال: وقال إسماعيل بن خليل: أخبرنا علي بن مسهر، عن هشام بن عروة، عن أبيه، عن عائشة، قالت: استأذنت هالة بنت خويلد أخت خديجة على رسول الله صلى الله عليه وآله وسلم فعرف استئذان خديجة، فارتاع لذلك، وقال: «اللهم هالة»."],[40867,"فغرت فقلت: ما تذكر من عجوز من عجائز قريش حمراء الشدقين، هلكت في الدهر، وأبدلك الله خيرا منها."],[40868,"أخرجه ابن منده، وأبو نعيم."],[40869,"قلت: هذه هالة على هذا النسب هي أم أبي العاص بن الربيع، وليس لخديجة أخت أخرى اسمها هالة."],[40870,"والله أعلم"],[40871,"٧٣٣٣ - هجيمة أم الدرداء"],[40872,"د ع س: هجيمة وقيل خيرة أم الدرداء مختلف في اسمها وصحبتها."],[40873,"أخرجها ابن منده، وأبو نعيم كذا مختصرا."],[40874,"قلت: كلام أبي نعيم وأبي موسى يدل على أن هجيمة وخيرة واحدة، وقد اختلف في اسمها وفي صحبتها."],[40875,"وأبو موسى إنما تبع أبا نعيم وقلده، وهما اثنتان: خيرة أم الدرداء الكبرى ولها صحبة، وهجيمة أم الدرداء الصغرى، ولا صحبة لها."],[40876,"وقد ذكرنا خبرهما في خيرة مستقصى."],[40877,"٧٣٣٤ - هريرة بنت زمعة"],[40878,"س: هريرة نبت زمعة بن قيس بن عبد شمس أخت سودة بنت زمعة أم المؤمنين."],[40879,"قال جعفر: لها صحبة."],[40880,"وروى، بإسناده عن طالب بن حجير، عن هود، عن رجل من عبد القيس كان حجاجا في الجاهلية، يقال له: معبد بن وهب أنه تزوج امرأة من قريش يقال لها: هريرة بنت زمعة أخت سودة بنت زمعة أم المؤمنين، وأنه شهد بدرا فقاتل بسيفين، فقال النبي صلى الله عليه وآله وسلم: «يا لهف نفسي على فتيان عبد القيس! أما إنهم أسد الله تعالى في الأرض»."],[40881,"أخرجها أبو موسى."],[40882,"٧٣٣٥ - هزيلة بنت ثابت"],[40883,"هزيلة بنت ثابت بن ثعلبة بن الجلاس الأنصارية بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[40884,"٧٣٣٦ - هزيلة بنت الحارث"],[40885,"ب ع س: هزيلة بنت الحارث بن حزن الهلالية أخت ميمونة بنت الحارث أم المؤمنين."],[40886,"قال جعفر: هو اسم أم حفيد التي أهدت إلى ميمونة الضباب والأقط والسمن."],[40887,"وكانت قد نكحت في الأعراب."],[40888,"روى القعنبي، عن مالك، عن عبد الرحمن بن عبد الله بن أبي صعصعة، عن سليمان بن يسار، قال: دخل رسول الله صلى الله عليه وآله وسلم بيت ميمونة بنت الحارث، فأتى بضباب فيهن بيض، ومعه عبد الله بن عباس وخالد بن الوليد، فقال: «من أين لكم هذا؟» قالت: أهدته إلي أختي هزيلة بنت الحارث، فقال لعبد الله وخالد: «كلا»، فقالا: ألا تأكل؟ قال: «إني يحضرني من الله تعالى حاضر»."],[40889,"أخرجها الثلاثة."],[40890,"٧٣٣٧ - هزيلة بنت سعيد"],[40891,"هزيلة بنت سعيد بن سهل بن مالك بن كعب بايعت رسول الله صلى الله عليه وآله وسلم قاله ابن حبيب."],[40892,"وهي من بني دينار من الأنصار."],[40893,"٧٣٣٨ - هزيلة بنت عمرو"],[40894,"هزيلة بنت عمرو بن عتبة بن خديج بن عامر بن جشم بن الحارث بن الخزرج وهي أم سعد بن الربيع."],[40895,"بايعت رسول الله صلى الله عليه وآله وسلم قاله ابن حبيب وابن ماكولا."],[40896,"خديج: بالخاء المعجمة المفتوحة."],[40897,"قال الدارقطني: ليس في الأنصار حديج بالحاء المهملة."],[40898,"٧٣٣٩ - هزيلة بنت مسعود"],[40899,"هزيلة بنت مسعود بن زيد الأنصارية من بني حرام."],[40900,"بايعت رسول الله صلى الله عليه وآله وسلم قاله ابن حبيب."],[40901,"٧٣٤٠ - همينة بنت خالد"],[40902,"ع س: همينة بنت خالد أو خلف بن أسعد بن عامر بن بياضة بن سبيع بن جعثمة بن سعد بن مليح بن عمرو بن ربيعة الخزاعية وقيل همينة بنت خلف وهو أصح."],[40903,"وهي أخت عبد الله بن خلف، والد طلحة الطلحات."],[40904,"هاجرت مع زوجها خالد بن سعيد بن العاص إلى أرض الحبشة، فولدت له هناك سعيدا وأمة، فتزوج أمة الزبير بن العوام، فولدت له خالدا وعمرا."],[40905,"روى منجاب بن الحارث، عن زياد بن عبد الله البكائي، عن ابن إسحاق في تسمية من هاجر من المسلمين إلى الحبشة: خالد بن سعيد بن العاص."],[40906,"وامرأته همينة بنت خالد بن أسعد بن عامر بن بياضة من خزاعة."],[40907,"أخرجها أبو نعيم، وأبو موسى."],[40908,"قلت: كذا نسبها أبو موسى على الشك، فقال: خالد أو خلف."],[40909,"وقال أبو نعيم: خالد، ولم يشك."],[40910,"ونقلاه عن البكائي، عن ابن إسحاق."],[40911,"والذي عندنا من طريق ابن هشام، عن البكائي، عن ابن إسحاق: خلف، بالفاء."],[40912,"وهو الصحيح، فإن نسبها يقضي بذلك، فإنها عمة طلحة الطلحات، وطلحة هو: ابن عبد الله بن خلف، لا خلاف فيه."],[40913,"وقيل فيها أيضا: أميمة وأمينة، وقد تقدما."],[40914,"والله أعلم."],[40915,"٧٣٤١ - هند بنت أثاثة"],[40916,"هند بنت أثاثة بن عباد بن المطلب بن عبد مناف القرشية المطلبية أخت مسطح بن أثاثة."],[40917,"ذكرها العسكري في ترجمة أخيها مسطح، وذكرها ابن إسحاق أيضا."],[40918,"أخبرنا أبو جعفر، بإسناده، عن يونس، عن ابن إسحاق، قال: فحدثني صالح بن كيسان، قال: ثم علت هند بنت عتبة، يعني يوم أحد على صخرة مشرفة، فنادت بأعلى صوتها، ثم قالت حين ظفروا بما أصابوا من أصحاب رسول الله صلى الله عليه وآله وسلم:"],[40919,"نحن جزيناكم بيوم بدر … والحرب بعد الحرب ذات سعر"],[40920,"ما كان عتبة لي من صبر … أبي وعمي وشقيق بكري"],[40921,"شفيت نفسي وقضيت نذري … شفيت وحشي غليل صدري"],[40922,"وهي أطول من هذا. فأجابتها هند بنت أثاثة بن عباد، وكانت من اللواتي أسلمن بمكة:"],[40923,"خزيت في بدر وغير بدر … يا بنت وقاع عظيم الكفر"],[40924,"صبحك الله غداة الفجر … بالهاشميين الطوال الزهر"],[40925,"بكل قطاع حسام يفري … حمزة ليثي، وعلي صقري"],[40926,"وذكرها أيضا ابن هشام، ولها أشعار غير هذا تجيب بها هند بنت عتبة."],[40927,"٧٣٤٢ - هند بنت أسيد"],[40928,"ب د ع: هند بنت أسيد بن حضير الأنصارية لها ذكر في حديث محمد بن عبد الرحمن بن سعد بن زرارة."],[40929,"لم يزد ابن منده، وأبو نعيم على هذا."],[40930,"قال أبو عمر: روى عنها أبو الرجال، عن النبي صلى الله عليه وآله وسلم أنه كان يخطب بالقرآن، قالت:"],[40931,"وما تعلمت ق وَالْقُرْءَانِ الْمَجِيدِ إلا من كثرة ما كنت أسمعها من يخطب بها على المنبر."],[40932,"٧٣٤٣ - هند بنت أبي أمية"],[40933,"هند بنت أبي أمية بن المغيرة بن عبد الله بن عمر بن مخزوم القرشية المخزومية زوج النبي صلى الله عليه وآله وسلم وإحدى أمهات المؤمنين، واسم أبيها أبي أمية: حذيفة، ويعرف بزاد الركب."],[40934,"وهو أحد أجواد قريش المشهورين بالكرم."],[40935,"وأمها عاتكة بنت عامر بن ربيعة بن مالك بن جذيمة بن علقمة وهو جذل الطعان بن فراس الكنانية."],[40936,"اختلف في اسمها، فقيل: رملة."],[40937,"وليس بشيء، وقيل: هند."],[40938,"وهو الأكثر."],[40939,"وكانت قبل أن يتزوجها رسول الله صلى الله عليه وآله وسلم تحت أبي سلمة بن عبد الأسد المخزومي، وكانت هي وزوجها أول من هاجر إلى الحبشة، ويقال أيضا: إن أم سلمة أول ظعينة هاجرت إلى المدينة، وقيل: بل ليلى بنت أبي حثمة امرأة عامر بن ربيعة."],[40940,"وتزوجها رسول الله صلى الله عليه وآله وسلم سنة ثلاث، بعد وقعة بدر، وقيل: إنه شهد أحدا ومات بعدها."],[40941,"قاله ابن إسحاق."],[40942,"ولما دخل بها قال لها: «إن شئت سبعت عندك وسبعت لنسائي، وإن شئت ثلثت ودرت؟» فقالت: ثلث."],[40943,"وتوفيت أم سلمة أول أيام يزيد بن معاوية، وقيل: إنها توفيت في شهر رمضان أو شوال سنة تسع وخمسين، وصلى عليها أبو هريرة، وقيل: صلى عليها سعيد بن زيد أحد العشرة."],[40944,"قال محارب بن دثار: أوصت أم سلمة أن يصلي عليها سعيد بن زيد، وكان مروان بن الحكم أميرا على المدينة."],[40945,"وقال الحسن بن عثمان: كان أمير المدينة يومئذ الوليد بن عتبة بن أبي سفيان، ودخل قبرها ابناها عمر وسلمة ابنا أبي سلمة، وابن أخيها عبد الله بن عبد الله بن أبي أمية."],[40946,"ودفنت بالبقيع."],[40947,"روت عن النبي صلى الله عليه وآله وسلم أحاديث، ويرد ذكرها في الكنى أكثر من هذا إن شاء الله تعالى."],[40948,"أخرجها الثلاثة."],[40949,"٧٣٤٤ - هند بنت أوس"],[40950,"هند بنت أوس بن شريق أم سعد بن خيثمة الأنصارية من بني خطمة."],[40951,"بايعت رسول الله صلى الله عليه وآله وسلم قاله ابن حبيب."],[40952,"٧٣٤٥ - هند الجهنية"],[40953,"س: هند الجهنية روى أبو بكر محمد بن عبد الله بن إبراهيم الشافعي، عن أبي العباس بن مسروق الطوسي، عن عمر بن عبد الحكم، وحفص بن عبد الله الوراق، والقاسم بن الحسن، كلهم عن ابن سعد، عن أبيه، «أنه كان في بدء الإسلام رجل شاب يقال له: بشر كان يختلف إلى رسول الله صلى الله عليه وآله وسلم وكان من بني أسد بن عبد العزى، وكان طريقه إذا غدا على رسول الله صلى الله عليه وآله وسلم أخذ على جهينة، وإذا فتاة من جهينة نظرت إليه فتعشقته، وكان بها من الحسن والجمال حظ عظيم، وكان للفتاة زوج يقال له: سعد بن سعيد، وكانت الفتاة تعقد كل غداة لبشر على أن يجتاز بها لينظر إليها، فلما جازها أخذها حبه»."],[40954,"وذكر القصة بطولها، ذكرها جعفر المستغفري."],[40955,"وأخرجها أبو موسى."],[40956,"٧٣٤٦ - هند الخولانية"],[40957,"د ع: هند الخولانية زوج بلال بن رباح."],[40958,"سماها سعيد بن عبد الملك، عن الأوزاعي، عن عمير بن هانئ."],[40959,"قيل: إن لها صحبة وهي من أهل داريا، من أرض دمشق."],[40960,"أخبرنا أبو محمد بن أبي القاسم بن الحسن بن هبة الله الدمشقي."],[40961,"إجازة بإذنه من أبي البركات بن المبارك، أخبرنا أبو الحسين بن الطيوري، أخبرنا عبد العزيز بن علي الأزجي، أخبرنا عبد الرحمن بن عمر بن أحمد بن خيثمة، أخبرنا أبو بكر محمد بن أحمد بن يعقوب بن شيبة، حدثني جدي، حدثنا عبد الرحمن بن المبارك، حدثنا عبد الأعلى بن عبد الأعلى، حدثنا سعيد الجريري، عن أبي الورد القشيري، حدثتني امرأة من بني عامر، عن امرأة بلال، أن النبي صلى الله عليه وآله وسلم أتاها فسلم فقال: «أثم بلال؟» فقالت: لا، فقال: «لعلك غضبى على بلال؟» فقالت: إنه يجئني كثيرا فيقول: قال رسول الله، فقال لها رسول الله: «ما حدثك عني فقد صدقك، بلال لا يكذب، لا تغضبي بلال، فلا يقبل منك عمل ما غضب عليك بلال»."],[40962,"أخرجها ابن منده، وأبو نعيم وقال أبو نعيم: ذكرها المتأخر، يعني: ابن منده، وهذا عندي فيه نظر، فإن بلالا إنما تزوج في خولان لما أقام بالشام، وذلك بعد وفاة النبي صلى الله عليه وآله وسلم وليس في الحديث أنها من خولان، ولعل هذه غير الخولانية، والله أعلم."],[40963,"٧٣٤٧ - هند بنت ربيعة"],[40964,"ب: هند بنت ربيعة بن الحارث بن عبد المطلب بن هاشم ولدت على عهد رسول الله صلى الله عليه وآله وسلم. وهي التي كانت عند حبان بن واسع هي وامرأة له أنصارية، فطلق الأنصارية وهي ترضع، فمرت بها سنة ثم هلك عنها ولم تحض، فقالت: أنا أرثه ولم أحض."],[40965,"فاختصما إلى عثمان بن عفان رضي الله عنه، فقضى لها بالميراث، فلامت الهاشمية عثمان فقال: هذا عمل ابن عمك، وهو أشار علينا بهذا."],[40966,"يعني: علي بن أبي طالب."],[40967,"أخرجها أبو عمر."],[40968,"٧٣٤٨ - هند بنت سماك"],[40969,"هند بنت سماك بن عتيك بن امرئ القيس عمة أسيد بن حضير الأنصاري الأشهلي."],[40970,"هي أم الحارث بن أوس بن معاذ، قاله العدوي في نسب الأنصار، وقال: كانت من المبايعات."],[40971,"وقال ابن حبيب: هي أم عبد الله وعمرو، ابني سعد بن معاذ."],[40972,"ذكرها ابن الدباغ عن الغساني."],[40973,"٧٣٤٩ - هند بنت أبي طالب"],[40974,"ب س: هند بنت أبي طالب أم هانئ القرشية الهاشمية."],[40975,"اختلف في اسمها فقيل: هند، وقيل: فاختة."],[40976,"وحجة من يقول هند ما"],[40977,"أخبرنا به أبو جعفر، بإسناده عن يونس، عن ابن إسحاق، قال: وأما هبيرة بن أبي وهب المخزومي، وهو زوج أم هانئ، فإنه أقام بنجران حتى مات مشركا."],[40978,"وقال حين بلغه إسلام أم هانئ بنت أبي طالب، وكانت تحته، واسم أم هانئ هند:"],[40979,"أشاقتك هند أم أتاك سؤالها … كذاك النوى أسبابها وانفتالها"],[40980,"وقد أرقت في رأس حصن ممرد … بنجران يسرى بعد ليل خيالها وهي أكثر من هذا."],[40981,"أخرجها أبو عمر، وأبو موسى."],[40982,"٧٣٥٠ - هند بنت عتبة"],[40983,"ب د ع: هند بنت عتبة بن ربيعة بن عبد شمس بن عبد مناف القرشية الهاشمية امرأة أبي سفيان بن حرب، وهي أم معاوية."],[40984,"أسلمت في الفتح بعد إسلام زوجها أبي سفيان، وأقرها رسول الله صلى الله عليه وآله وسلم على نكاحها، كان بينهما في الإسلام ليلة واحدة، وكانت امرأة لها نفس وأنفة ورأي وعقل."],[40985,"وشهدت أحدا كافرة، وهي القائلة يومئذ:"],[40986,"نحن بنات طارق … نمشي على النمارق"],[40987,"إن تقبلوا نعانق … أو تدبروا نفارق"],[40988,"فراق غير وامق"],[40989,"فلما قتل حمزة مثلت به وشقت بطنه واستخرجت كبده فلاكتها، فلم تطق إساغتها."],[40990,"فبلغ ذلك النبي صلى الله عليه وآله وسلم فقال: «لو أساغتها لم تمسها النار»، وقيل: إن الذي مثل بحمزة معاوية بن المغيرة بن أبي العاص بن أمية، جد عبد الملك بن مروان لأمه، وقتله النبي صلى الله عليه وآله وسلم صبرا منصرفه من أحد."],[40991,"ثم إن هند أسلمت يوم الفتح وحسن إسلامها، فلما بايع رسول الله صلى الله عليه وآله وسلم النساء وفي البيعة: ﴿وَلا يَسْرِقْنَ وَلا يَزْنِينَ﴾، قالت هند: وهل تزني الحرة وتسرق؟ فلما قال: ﴿وَلا يَقْتُلْنَ أَوْلادَهُنَّ﴾، قالت: ربيناهم صغارا وقتلتهم كبارا؟ وشكت إلى رسول الله صلى الله عليه وآله وسلم زوجها أبا سفيان وقالت: إنه شحيح لا يعطيها من الطعام ما يكفيها وولدها، فقال لها رسول الله صلى الله عليه وآله وسلم: «خذي من ماله بالمعروف ما يكفيك وولدك»."],[40992,"روى هشام بن عروة، عن أبيه، قال: قالت هند لأبي سفيان: إني أريد أن أبايع محمدا."],[40993,"قال: قد رأيتك تكذبين هذا الحديث أمس! قالت: والله ما رأيت الله عبد حق عبادته في هذا المسجد قبل الليلة، والله إن باتوا إلا مصلين."],[40994,"قال: فإنك قد فعلت ما فعلت، فاذهبي برجل من قومك معك."],[40995,"فذهبت إلى عثمان بن عفان، وقيل: إلى أخيها أبي حذيفة بن عتبة، فذهب معها فاستأذن لها فدخلت وهي من منتقبة، فقال: «تبايعيني على أن لا تشركي بالله شيئا»، وذكر نحو ما تقدم من قولها للنبي صلى الله عليه وآله وسلم."],[40996,"وشهدت اليرموك، وحرضت على قتال الروم مع زوجها أبي سفيان، وكانت قبل أبي سفيان تحت حفص بن المغيرة المخزومي وقصتها معه مشهورة، وتوفيت هند في خلافة عمر بن الخطاب في اليوم الذي مات فيه أبو قحافة والد أبي بكر الصديق."],[40997,"أخرجها الثلاثة."],[40998,"٧٣٥١ - هند بنت عمرو"],[40999,"د ع: هند بنت عمرو بن حرام الأنصارية أخت عبد الله بن عمرو."],[41000,"وهي عمة جابر بن عبد الله."],[41001,"روى حديثها الواقدي، عن أيوب بن النعمان، عن أبيه، عنها."],[41002,"أخرجها ابن منده، وأبو نعيم مختصرا."],[41003,"٧٣٥٢ - هند بنت محمود"],[41004,"هند بنت محمود بن مسلمة بن خالد بن عدي الأنصارية بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41005,"٧٣٥٣ - هند بنت منبه"],[41006,"هند بنت منبه بن الحجاج القرشية السهمية أسلمت يوم الفتح."],[41007,"وهي أم عبد الله بن عمرو بن العاص، قاله الواقدي."],[41008,"استدركه ابن الدباغ على الغساني."],[41009,"٧٣٥٤ - هند بنت المنذر"],[41010,"هند بنت المنذر بن الجموح بن زيد بن حرام الأنصارية الساعدية بايعت رسول الله صلى الله عليه وآله وسلم قاله ابن حبيب."],[41011,"٧٣٥٥ - هند بنت هبيرة"],[41012,"س: هند بنت هبيرة ذكرها النسائي هكذا."],[41013,"أخبرنا أبو القاسم يعيش بن صدقة الفقيه، بإسناده عن أبي عبد الرحمن النسائي: أخبرنا عبيد الله بن سعيد، حدثنا معاذ بن هشام، حدثني أبي، عن أبي يحيى بن أبي كثير، قال: حدثني زيد، عن أبي سلام، عن أبي أسماء الرحبي، أن ثوبان مولى رسول الله صلى الله عليه وآله وسلم حدثه، قال: جاءت هند بنت هبيرة إلى رسول الله صلى الله عليه وآله وسلم وفي يدها فتخ، أي خواتيم ضخام، فجعل رسول الله صلى الله عليه وآله وسلم يضرب يدها، فدخلت على فاطمة تشكو إليها الذي صنع بها رسول الله صلى الله عليه وآله وسلم فانتزعت فاطمة سلسلة كانت في عنقها من ذهب، فقالت: هذه أهداها إلي أبو حسن."],[41014,"فدخل رسول الله صلى الله عليه وآله وسلم والسلسلة في يدها، فقال: «يا فاطمة، أيغرك أن يقول الناس: ابنة رسول الله صلى الله عليه وآله وسلم وفي يدك سلسلة من نار؟!» ثم خرج ولم يقعد."],[41015,"فأرسلت فاطمة السلسلة إلى السوق فباعتها، واشترت بثمنها غلاما، وقال مرة: عبدا فأعتقته، فحدثت بذلك رسول الله صلى الله عليه وآله وسلم فقال: «الحمد الله الذي نجى فاطمة من النار»."],[41016,"أخرجها أبو موسى"],[41017,"٧٣٥٦ - هند بنت الوليد"],[41018,"س: هند بنت الوليد بن عتبة بن ربيعة بن عبد شمس القرشية العبشمية وهي ابنة خال معاوية، سماها أبو عمر فاطمة."],[41019,"وقال الدارقطني: سماها مالك فاطمة، وخالفه غيره عن الزهري، فقالوا: هند."],[41020,"وهو الصواب."],[41021,"أخبرنا أبو أحمد عبد الوهاب بن علي بن سكينة، بإسناده عن أبي داود السجستاني، حدثنا أحمد بن صالح، حدثنا عنبسة، حدثني يونس، عن ابن شهاب، حدثني عروة بن الزبير، عن عائشة زوج النبي صلى الله عليه وآله وسلم وأم سلمة، «أن أبا حذيفة بن عتبة بن ربيعة كان تبني سالما وأنكحه ابنة أخيه هند بنت الوليد بن عتبة، وهو مولى لامرأة من الأنصار، كما تبنى رسول الله صلى الله عليه وآله وسلم زيد بن حارثة."],[41022,"وكان من تبنى رجلا في الجاهلية دعاه الناس إليه وورث ميراثه، حتى أنزل الله عز وجل ﴿ادْعُوهُمْ لآبَائِهِمْ﴾."],[41023,"الآية، فردوا إلى آبائهم، فمن لم يعلم له أب كان مولى وأخا في الدين، فجاءت سهلة بنت سهيل بن عمرو امرأة أبي حذيفة القرشية العامرية فقالت: يا رسول الله، إنا كنا نرى سالما ولدا."],[41024,"وذكر الحديث أنها أرضعته»."],[41025,"وقد ذكرناه في غير موضع من كتابنا هذا"],[41026,"٧٣٥٧ - هند بنت يزيد"],[41027,"ب: هند بنت يزيد بن البرصاء من بني أبي بكر بن كلاب."],[41028,"هكذا ذكرها أبو عبيدة في أزواج النبي صلى الله عليه وآله وسلم. وقال أحمد بن صالح المصري: هي عمرة بنت يزيد."],[41029,"وفيها اضطراب كثير جدا."],[41030,"أخرجها أبو عمر."],[41031,"حرف الياء"],[41032,"٧٣٥٨ - يسيرة بنت مليل"],[41033,"يسيرة بنت مليل بن زيد بن خالد بن العجلان الأنصارية من بني عوف بن الخزرج."],[41034,"بايعت رسول الله صلى الله عليه وآله وسلم قاله ابن حبيب."],[41035,"٧٣٥٩ - يسيرة أم ياسر"],[41036,"ب د ع: يسيرة أم ياسر الأنصارية وقيل: بل هي يسيرة بنت ياسر."],[41037,"تكنى أم حميضة."],[41038,"كانت من المهاجرات المبايعات."],[41039,"قاله أبو عمر."],[41040,"وقال ابن منده، وأبو نعيم: يسيرة من المهاجرات."],[41041,"غير منسوبة، حديثها عند حميضة بنت ياسر."],[41042,"أخبرنا غير واحد بإسنادهم عن أبي عيسى، حدثنا موسى بن حزام وعبد بن حميد، وغير واحد، قالوا: حدثنا محمد بن بشر، عن هانئ بن عثمان، عن أمه حميضة بنت ياسر، عن جدتها يسيرة وكانت من المهاجرات، قالت: قال رسول الله صلى الله عليه وآله وسلم: «عليكن بالتسبيح والتقديس والتهليل، واعقدن بالأنامل، فإنهن مسئولات مستنطقات»."],[41043,"أخرجها الثلاثة يسيرة: بضم الياء، وفتح السين المهملة، وبعدها ياء ثانية."],[41044,"آخر أسماء خير النساء، والحمد لله رب العالمين."],[41045,"ويتلوه زائدة كتاب الكنى، إن شاء الله تعالى."],[41046,"الكنى من النساء الصحابيات"],[41047,"حرف الهمزة"],[41048,"٧٣٦٠ - أم أبان بنت عتبة"],[41049,"ب: أم أبان بنت عتبة بن ربيعة بن عبد شمس بن عبد مناف القرشية العبشمية خالة معاوية."],[41050,"كانت بالشام مع زوجها أبان بن سعيد بن العاص فقتل عنها بأجنادين، فعادت إلى المدينة."],[41051,"ولما قدمت من الشام خطبها عمر، وعلي، والزبير، وطلحة."],[41052,"فاختارت طلحة، فتزوجها."],[41053,"ولا تعرف لها رواية."],[41054,"أخرجها أبو عمر."],[41055,"٧٣٦١ - أم الأزهر"],[41056,"ب د ع: أم الأزهر العائشية روت عنها زينب بنت الزبرقان العائشية، أن أباها ذهب بها إلى النبي صلى الله عليه وآله وسلم فمسح بيده عليها، وكانت امرأة صالحة عابدة."],[41057,"أخرجها الثلاثة."],[41058,"٧٣٦٢ - أم إسحاق الغنوية"],[41059,"أم إسحاق الغنوية روت عنها أم حكيم بنت دينار، وكانت من المهاجرات."],[41060,"روى أبو عاصم الضحاك بن مخلد، عن بشار بن عبد الملك، عن أم حكيم بنت دينار مولاة أم إسحاق، أنها قالت: «خرجت إلى النبي صلى الله عليه وآله وسلم مع أخي، فلما كنت في بعض الطريق، قال لي أخي: اقعدي يا أم إسحاق فإني نسيت نفقتي بمكة."],[41061,"فقلت: إني أخشى عليك الفاسق تعني زوجها قال: كلا، إن شاء الله، قالت: فلبثت أياما فمر بي رجل قد عرفته، ولا أسميه، فقال: ما يقعدك ههنا يا أم إسحاق؟ قلت: أنتظر إسحاق، ذهب يأخذ نفقته، قال: لا إسحاق لك، قد لحقه الفاسق زوجك فقتله."],[41062,"فقدمت فدخلت على رسول الله صلى الله عليه وآله وسلم وهو يتوضأ، قلت: يا رسول الله، قتل إسحاق وأنا أبكي، وهو ينظر إلي فأخذ كفا من ماء فنضحه في وجهي، قال بشار: قالت جدتي: فلقد كانت تصيبنا المصيبة العظيمة، فنرى الدموع في عينيها ولا تسيل على خدها»."],[41063,"أخبرنا أبو ياسر، بإسناده عن عبد الله، حدثني أبي، حدثنا عبد الصمد، حدثنا بشار بن عبد الملك، حدثتني أم حكيم بنت دينار، عن مولاتها أم إسحاق، أنها كانت عند رسول الله صلى الله عليه وآله وسلم فأتي بقصعة من ثريد فأكلت معه، ومعه ذو اليدين، فناولها رسول الله صلى الله عليه وآله وسلم عزقا فقال: «يا أم إسحاق، أصيبي من هذه.» فذكرت أني صائمة، فبردت يدي: لا أقدمها ولا أؤخرها، فقال النبي صلى الله عليه وآله وسلم: «مالك؟» قلت: كنت صائمة فنسيت، فقال ذو اليدين: الآن بعدما شبعت؟ فقال النبي صلى الله عليه وآله وسلم: «إنما هو رزق ساقه الله تعالى إليك»"],[41064,"٧٣٦٣ - أم أسيد الأنصارية"],[41065,"ع س: أم أسيد الأنصارية امرأة أبي أسيد الأنصاري."],[41066,"أخبرنا محمد بن محمد بن سرايا بن علي الفقيه وغير واحد، قالوا، بإسنادهم عن محمد بن إسماعيل، حدثنا سعيد بن أبي مريم، حدثنا أبو غسان، عن أبي حازم، عن سهل بن سعد هو الساعدي، قال: «لما عرس أبو أسيد الساعدي دعا النبي صلى الله عليه وآله وسلم وأصحابه، فما صنع لهم طعاما ولا قربه إليهم، إلا امرأته أم أسيد بلت تمرات في تور من حجارة من الليل، فلما فرغ النبي صلى الله عليه وآله وسلم من الطعام أمالته له، فسقته تتحفه بذلك»."],[41067,"أخرجها أبو نعيم، وأبو موسى"],[41068,"٧٣٦٤ - أم أبي أمامة"],[41069,"أم أبي أمامة بن ثعلبة بن الحارث هو الذي حضرت أمه الوفاة عند مسير رسول الله صلى الله عليه وآله وسلم إلى بدر، فقال ابنها أبو أمامة لأخيها أبي بردة بن نيار: أقم على أختك، فقال: بل أقم أنت على أمك."],[41070,"فارتفعا إلى رسول الله صلى الله عليه وآله وسلم فأمر أبا أمامة بالإقامة على أمه."],[41071,"فرجع رسول الله صلى الله عليه وآله وسلم من بدر وقد توفيت، فصلى عليها."],[41072,"وهذه غير أم أبي أمامة بن سهل بن حنيف لأن هذا أبا أمامة بن سهل ولد بعد الهجرة، وسماه رسول الله صلى الله عليه وآله وسلم وكناه أبا أمامة، ثم هو من بني عمرو بن عوف من [*]"],[41073,"[*] (تعليق الشاملة): في المطبوع «بن»، وما أثبتناه من طبعتي الوهبية والشعب. وهو: «عمرو بن عوف بن مالك بن الأوس»"],[41074,"الأوس، وأما أبو أمامة بن ثعلبة فإنه كان في الهجرة رجلا، ثم هو من بني حارثة بن الحارث، بطن من الخزرج، فهو غيره والله أعلم."],[41075,"وقد ذكرناه في أبي أمامة، وفي غيره."],[41076,"٧٣٦٥ - أم أبي أمامة بن سهل"],[41077,"س: أم أبي أمامة بن سهل بن حنيف أوردها جعفر المستغفري، ولم يورد لها شيئا."],[41078,"أخرجها أبو موسى كذا مختصرا."],[41079,"٧٣٦٦ - أم أنس الأنصارية"],[41080,"ع س: أم أنس الأنصارية وليست أم أنس بن مالك."],[41081,"ذكرها الطبراني."],[41082,"أخبرنا أبو موسى، إذنا، أخبرنا أبو غالب، أخبرنا أبو بكر."],[41083,"ح قال أبو موسى: وأخبرنا الحسن بن أحمد، أخبرنا أبو نعيم، قالا: حدثنا سليمان بن أحمد، حدثنا الحسين بن إسحاق هو التستري، حدثنا هشام بن عمار، حدثني الوليد بن مسلم، عن عنبسة بن عبد الرحمن، عن محمد بن زاذان، عن أم سعد امرأة زيد بن ثابت، عن أم أنس، قالت: قلت: يا رسول الله، إن نفسي تغلبني عن عشاء الآخرة، فقال رسول الله صلى الله عليه وآله وسلم: «عجليها يا أم أنس، إذا ما الليل بطن كل واد فقد حل وقت الصلاة، فصلي ولا إثم عليك»."],[41084,"أخرجها أبو نعيم، وأبو موسى"],[41085,"٧٣٦٧ - أم أنس بنت البراء"],[41086,"د ع: أم أنس بنت البراء بن معرور وقيل أم بشر وقيل أم مبشر روى وهب بن جرير، عن أبيه، عن محمد بن إسحاق، عن عبد الله بن أبي نجيح، عن مجاهد، عن أم أنس بنت البراء بن معرور، قالت: سمعت رسول الله صلى الله عليه وآله وسلم: يقول: «ألا أنبئكم بخير الناس؟»، قلنا: بلى."],[41087,"قال: «رجل، وأشار بيده إلى المغرب، أخذ بعنان فرسه في سبيل الله، ينتظر أن يغير أو يغار عليه»، ثم قال: «ألا أنبئكم بالذي يليه؟»، قلنا: بلى، فثنى بيده إلى الحجاز، وقال: «رجل في غنيمة له، يقيم الصلاة ويؤتي الزكاة، ويعرف حق الله في ماله، قد اعتزل شرور الناس»."],[41088,"ورواه محمد بن سلمة، عن ابن إسحاق، عن ابن أبي نجيح، فقال: أم بشر."],[41089,"أخرجها ابن منده، وأبو نعيم."],[41090,"٧٣٦٨ - أم أنس جدة موسى بن عمران"],[41091,"ب س: أم أنس جدة موسى بن عمران بن أبي أنس الأنصاري روى عنها موسى بن عمران، أنها قالت: يا رسول الله، جعلك الله في الرفيق الأعلى، وأنا معك، فقال: «آمين."],[41092,"»، فقال لها: «عليك بالصلاة واهجري المعاصي فإنه أفضل من الجهاد»."],[41093,"أخرجها أبو عمر، وأبو موسى، إلا أن أبا عمر قال: جدة يونس بن أبي أنس."],[41094,"وقال أبو موسى: جدة موسى."],[41095,"وقد وافق البخاري أبا عمر، فقد ذكره في التاريخ الكبير فقال: يونس بن عمران بن أبي أنس، يروي عن جدته أم أنس."],[41096,"والله أعلم."],[41097,"ورواها أبو موسى عن الطبراني من طريقين، فقال: أم موسى بن عمران."],[41098,"٧٣٦٩ - أم أنس بنت عمرو"],[41099,"أم أنس بنت عمرو بن مرضخة من بني عوف بن الخزرج الأنصارية."],[41100,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41101,"٧٣٧٠ - أم أوس البهزية"],[41102,"ب د ع: أم أوس البهزية روى خلف بن خليفة، عن أبي هاشم الرماني، عن أوس بن خالد البهزي، عن أم أوس البهزية، أنها سلأت سمنا لها، فجعلته في عكة ثم أهدته إلى النبي صلى الله عليه وآله وسلم فقبله، وأخذ ما فيه، ودعا لها بالبركة."],[41103,"فردها إليها وهي ممتلئة سمنا، فظنت أن النبي صلى الله عليه وآله وسلم لم يقبلهما، فجاءت النبي صلى الله عليه وآله وسلم ولها صراخ، فقال: «أخبروها بالقصة»."],[41104,"فأكلت منه بقية عمر النبي صلى الله عليه وآله وسلم وولاية أبي بكر، وولاية عمر، وولاية عثمان، حتى كان بين علي ومعاوية ما كان."],[41105,"أخرجها الثلاثة."],[41106,"٧٣٧١ - أم أيمن مولاة رسول الله ﷺ"],[41107,"ب د ع: أم أيمن مولاة رسول الله صلى الله عليه وآله وسلم وحاضنته واسمها بركة وهي حبشية فأعتقها عبد الله أبو رسول الله صلى الله عليه وآله وسلم. وأسلمت قديما أول الإسلام، وهاجرت إلى الحبشة، إلى المدينة، وبايعت رسول الله صلى الله عليه وآله وسلم وقيل: إنها كانت لأخت خديجة، فوهبتها لرسول الله صلى الله عليه وآله وسلم وقيل: كانت لأم رسول الله صلى الله عليه وآله وسلم وهي التي شربت بول النبي صلى الله عليه وآله وسلم فقال لها: «لا ييجع بطنك أبدا»."],[41108,"، وقيل: إن التي شربت بوله بركة جارية أم حبيبة، وتكنى أم أيمن، بابنها أيمن بن عبيد."],[41109,"وتزوجها زيد بن حارثة بن عبيد الحبشي، وكان رسول الله صلى الله عليه وآله وسلم يقول: «أم أيمن أمي بعد أمي»."],[41110,"وكان يزورها في بيتها."],[41111,"أخبرنا عبد الوهاب، بإسناده عن عبد الله، حدثني أبي، حدثنا عبد الصمد، حدثنا حماد، عن ثابت، عن أنس، «أن أم أيمن بكت لما قبض رسول الله صلى الله عليه وآله وسلم فقيل لها: ما يبكيك على رسول الله صلى الله عليه وآله وسلم فقالت: إني علمت، أن النبي صلى الله عليه وآله وسلم سيموت، ولكن أبكي على الوحي الذي رفع عنا»"],[41112,"أخبرنا يحيى بن محمود وأبو ياسر، بإسنادهما عن مسلم بن أبي الحسين، قال: حدثنا أبو الطاهر وحرملة، قالا: حدثنا ابن وهب، أخبرني يونس، عن ابن شهاب، عن أنس بن مالك، قال: «لما قدم المهاجرون من مكة …"],[41113,"»."],[41114,"وذكر الحديث، وقال: قال ابن شهاب: وكان من شأن أم أيمن أم أسامة بن زيد أنها كانت وصيفة لعبد الله بن عبد المطلب، وكانت من الحبشة، فلما ولدت آمنة رسول الله صلى الله عليه وآله وسلم بعدما توفي أبوه، حضنته أم أيمن حتى كبر، ثم أعتقها رسول الله صلى الله عليه وآله وسلم ثم أنكحها زيد بن حارثة، ثم توفيت بعدما توفي رسول الله صلى الله عليه وآله وسلم بخمسة أشهر، وقيل: بستة أشهر، وقيل: إن أبا بكر وعمر كانا يزورانها كما كان رسول الله صلى الله عليه وآله وسلم يزورها."],[41115,"أخرجها الثلاثة"],[41116,"٧٣٧٢ - أم أيوب الأنصارية"],[41117,"ب د ع: أم أيوب الأنصارية امرأة أبي أيوب، وهي: بنت قيس بن عمرو بن امرئ القيس من الخزرج."],[41118,"أخبرنا غير واحد، بإسنادهم عن محمد بن عيسى، حدثنا الحسن بن الصباح، عن ابن عيينة، عن عبيد الله بن أبي يزيد، عن أبيه، أن أم أيوب أخبرته، قالت: نزل علينا رسول الله صلى الله عليه وآله وسلم فتكلفنا له طعاما فيه بعض هذه البقول، فكره أكله، وقال لأصحابه: «كلوه إني لست كأحدكم، إني أخاف أن أوذي صاحبي» قال الحميدي: قال سفيان: رأيت رسول الله صلى الله عليه وآله وسلم في النوم، فقلت: يا رسول الله، هذا الحديث الذي تحدث به أم أيوب عنك إن الملائكة تتأذى مما يتأذى منه بنو آدم؟ قال: حق."],[41119,"أخرجها الثلاثة."],[41120,"٧٣٧٣ - أم أيوب بنت مسعود"],[41121,"س: أم أيوب بنت مسعود قال جعفر: ذكرها البخاري، ولم يورد لها شيئا."],[41122,"أخرجها أبو موسى مختصرا."],[41123,"حرف الباء"],[41124,"٧٣٧٤ - أم بجيد الأنصارية"],[41125,"ب د ع: أم بجيد الأنصارية الحارثية قيل اسمها حواء وفي ذلك اضطراب، وهي مشهورة بكنيتها."],[41126,"بايعت النبي صلى الله عليه وآله وسلم"],[41127,"أخبرنا إبراهيم بن محمد، وغيره، بإسنادهم عن أبي عيسى، حدثنا قتيبة، أخبرنا الليث، عن سعيد بن أبي هند، عن عبد الرحمن بن بجيد، عن جدته أم بجيد وكانت ممن بايع رسول الله صلى الله عليه وآله وسلم أنها قالت لرسول الله صلى الله عليه وآله وسلم: إن المسكين ليقوم على بابي فما أجد شيئا أعطيه إياه؟ فقال لها رسول الله صلى الله عليه وآله وسلم: «إن لم تجدي له شيئا تعطيه إياه إلا ظلفا محرقا، فادفعيه في يده»."],[41128,"أخرجها الثلاثة"],[41129,"٧٣٧٥ - أم بردة بنت المنذر"],[41130,"ب س: أم بردة بنت المنذر بن زيد بن لبيد بن خراش بن عامر بن غنم بن عدي بن النجار الأنصارية النجارية أرضعت إبراهيم ابن النبي صلى الله عليه وآله وسلم دفعه النبي صلى الله عليه وآله وسلم إليها ساعة وضعته أمه مارية، فلم تزل ترضعه حتى مات عندها."],[41131,"وهي امرأة البراء بن أوس، قاله أبو عمر."],[41132,"وقال أبو موسى، عن أبي القاسم بن إسماعيل بن محمد بن الفضل، قال: ولد إبراهيم في ذي الحجة سنة ثمان، فدفعه رسول الله صلى الله عليه وآله وسلم إلى أم بردة بنت المنذر، فكانت ترضعه."],[41133,"قال أبو موسى: والمشهور أن التي أرضعته أم سيف، ولعلهما كانتا جميعا أرضعتاه في وقتين."],[41134,"وهو الصحيح، إلا أن أبا عمر لم يذكر أم سيف ههنا."],[41135,"٧٣٧٦ - أم بشر بنت البراء"],[41136,"ب د ع: أم بشر وقيل أم مبشر بنت البراء بن معرور قيل اسمها خليدة ولا يصح."],[41137,"روى عنها عبد الله بن كعب بن مالك، وعبد الله بن يزيد."],[41138,"روى الزهري، عن عبد الرحمن بن عبد الله بن كعب بن مالك، عن أبيه، قال: لما حضرت كعبا الوفاة أتته أم بشر بنت البراء بن معرور فقالت: يا أبا عبد الرحمن، إن لقيت أبي فأقره مني السلام، فقال: لعمر الله يا أم بشر نحن أشغل من ذلك، فقالت: أما سمعت رسول الله صلى الله عليه وآله وسلم يقول: «إن أرواح المؤمنين نسمة تسرح في الجنة حيث شاءوا، وإن نسمة الفاجر في سجين»."],[41139,"قال: بلى."],[41140,"قالت: هو ذاك."],[41141,"ورواه يونس، والزبيدي، وغيرهما عن الزهري، فقال: أم مبشر."],[41142,"أخرجها الثلاثة."],[41143,"٧٣٧٧ - أم بلال امرأة بلال"],[41144,"س: أم بلال امرأة بلال قال جعفر: ذكرها البخاري فيمن روى عن النبي صلى الله عليه وآله وسلم من نساء خزاعة."],[41145,"أخرجها أبو موسى مختصرا."],[41146,"٧٣٧٨ - أم بلال بنت هلال"],[41147,"ب د ع: أم بلال بنت هلال الأسلمية قاله أبو نعيم."],[41148,"وقال أبو عمر: أم بلال بنت هلال المزنية: شهد أبوها الحديبية، وروت هي عن النبي صلى الله عليه وآله وسلم"],[41149,"أخبرنا عبد الوهاب بن أبي حبة، بإسناده عن عبد الله بن أحمد، حدثني أبي، حدثنا يحيى بن سعيد، حدثني محمد بن أبي يحيى الأسلمي، عن أمه أم بلال وكان أبوها مع النبي صلى الله عليه وآله وسلم يوم الحديبية، قالت: قال رسول الله صلى الله عليه وآله وسلم: «ضحوا بالجذع من الضأن، فإنه جائز»."],[41150,"ورواه أنس بن عياض، عن محمد بن أبي يحيى، عن أمه، عن أم بلال، عن أبيها: نحوه."],[41151,"أخرجها الثلاثة"],[41152,"٧٣٧٩ - أم بيان"],[41153,"أم بيان بنت زيد بن مالك أخت سعد بن زيد."],[41154,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41155,"حرف الثاء"],[41156,"٧٣٨٠ - أم ثابت بنت ثعلبة"],[41157,"أم ثابت بنت ثعلبة بن محصن الأنصارية بايعت النبي صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41158,"٧٣٨١ - أم ثابت بنت جبر"],[41159,"أم ثابت بنت جبر بن عتيك بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41160,"٧٣٨٢ - أم ثابت بنت سنان"],[41161,"أم ثابت بنت سنان بن عبيد الأنصارية، من بني الأبجر بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41162,"٧٣٨٣ - أم ثابت بنت قيس"],[41163,"أم ثابت بنت قيس بن شماس الأنصارية."],[41164,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41165,"٧٣٨٤ - أم ثابت بنت مسعود"],[41166,"أم ثابت بنت مسعود بن سعد بن قيس بن خلدة الأنصارية الزرقية بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41167,"٧٣٨٥ - أم ثعلبة بنت ثابت"],[41168,"أم ثعلبة بنت ثابت بن الجذع الأنصارية من بني حرام."],[41169,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41170,"حرف الجيم"],[41171,"٧٣٨٦ - أم الجلاس"],[41172,"ب: أم الجلاس التميمية هي أم عبد الله بن عياش بن أبي ربيعة المخزومي، اسمها أسماء تقدم ذكرها في حرف الهمزة."],[41173,"أخرجها أبو عمر."],[41174,"٧٣٨٧ - أم جميل بنت أوس"],[41175,"س: أم جميل بنت أوس المرئية من بني امرئ القيس."],[41176,"قالت: أتيت النبي صلى الله عليه وآله وسلم مع أبي، وعلي ذوائب وقنزعة."],[41177,"ذكرت عند ذكر أبيها، قاله جعفر."],[41178,"أخرجها أبو موسى مختصرا."],[41179,"٧٣٨٨ - أم جميل بنت الجلاس"],[41180,"أم جميل بنت الجلاس بن سويد الأنصارية من بني عبد الأشهل."],[41181,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41182,"٧٣٨٩ - أم جميل بنت الحباب"],[41183,"أم جميل بنت الحباب بن المنذر بن الجموح الأنصارية من بني حرام."],[41184,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41185,"٧٣٩٠ - أم جميل بنت أبي حزم"],[41186,"أم جميل بنت أبي حزم بن عتيك بن النعمان الأنصارية من بني مالك."],[41187,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41188,"٧٣٩١ - أم جميل بنت الخطاب"],[41189,"د ع: أم جميل بنت الخطاب أخت عمر بن الخطاب، امرأة سعيد بن زيد، واسمها فاطمة."],[41190,"وقد ذكرت في فاطمة."],[41191,"أخرجها ابن منده، وأبو نعيم."],[41192,"٧٣٩٢ - أم جميل بنت عبد الله د ع: أم جميل بنت عبد الله روى عنها سعيد بن المسيب."],[41193,"روى موسى بن عبيدة، عن عبد الله بن عبيدة، عن سعيد بن المسيب، عن أم جميل بنت عبد الله، أن زوجها ضربها، فذكرت ذلك للنبي صلى الله عليه وآله وسلم فقال: «هل لك أن تباريه؟»، فبارته."],[41194,"أخرجها ابن منده، وأبو نعيم."],[41195,"٧٣٩٣ - أم جميل بنت قطبة"],[41196,"أم جميل بنت قطبة بن عامر بن حديدة الأنصارية من بني سواد."],[41197,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41198,"٧٣٩٤ - أم جميل بنت المجلل"],[41199,"ب د ع: أم جميل بنت المجلل بن عبد وقيل: عبيد بن أبي قيس بن عبدود بن نصر بن مالك بن حسل بن عامر بن لؤي هاجرت مع زوجها حاطب بن الحارث إلى الحبشة."],[41200,"وهي أم محمد بن حاطب."],[41201,"وتوفي زوجها حاطب في الحبشة، فخلف عليها زيد بن ثابت، فولدت له، وهاجرت إلى المدينة أيضا."],[41202,"روى عنها ابنها محمد."],[41203,"أخبرنا أبو ياسر، بإسناده عن عبد الله، حدثني أبي، حدثنا إبراهيم بن أبي العباس ويونس بن محمد، عن عبد الرحمن بن عثمان بن إبراهيم بن محمد بن حاطب، عن أبيه، عن جده محمد بن حاطب، عن أمه أم جميل بنت المجلل، قالت: «أقبلت بك من أرض الحبشة، حتى إذا كنت من المدينة على ليلة أو ليلتين، إذ طبخت لك طبيخا ففني الحطب، فذهبت أطلب، فتناولت القدر فانكفأت على ذراعك …"],[41204,"»."],[41205,"الحديث وقد تقدم في محمد، وغيره."],[41206,"أخرجها الثلاثة."],[41207,"المجلل: بالجيم."],[41208,"٧٣٩٥ - أم جندب أم أبي ذر"],[41209,"د ع: أم جندب هي أم أبي ذر الغفاري لها ذكر في إسلام أبي ذر."],[41210,"أخبرنا عبد الله بن أبي نصر الخطيب، بإسناده إلى أبي داود الطيالسي، قال: حدثنا سليمان بن المغيرة، عن حميد بن هلال، عن عبد الله بن الصامت، عن أبي ذر قال: «لما أسلمت أتيت أخي وأمي، فقالت: ما بنا رغبة عن دينك، فأسلمت»."],[41211,"أخرجها ابن منده، وأبو نعيم"],[41212,"٧٣٩٦ - أم جندب أم سليمان بن عمر"],[41213,"د ع: أم جندب وهي أم سليمان بن عمرو روى حديثها ابنها سليمان بن عمرو بن الأحوص، أنها رأت النبي صلى الله عليه وآله وسلم غداة الجمرة، وهو يرمي الجمرة، وهو يقول: «أيها الناس، لا يقتل بعضكم بعضا، ارموا بمثل حصى الخذف»."],[41214,"٧٣٩٧ - أم جندب الأزدية"],[41215,"ب د ع: أم جندب الأزدية"],[41216,"أخبرنا عبد الوهاب بن أبي حبة، بإسناده عن عبد الله بن أحمد، حدثني أبي، حدثنا يزيد، حدثنا الحجاج بن أرطاة، عن أبي يزيد مولى عبد الله بن الحارث، عن أم جندب الأزدية، قالت: قال النبي صلى الله عليه وآله وسلم: «ارموا الجمار بمثل حصى الخذف، ولا تقتلوا أنفسكم»."],[41217,"قاله أبو عمر وقال: هي أم سليمان بن عمرو بن الأحوص: وقال ابن منده، وأبو نعيم: أم جندب الأزدية."],[41218,"ولم يذكرا أنها أم سليمان، إلا أن أبا نعيم، قال: وهي عندي المتقدمة يعني أم سليمان وذكر لها هذا الحديث في رمي الجمار، وروياه عن أبي يزيد، عن أم جندب، وعن جندب، عن أمه."],[41219,"أخرجها الثلاثة."],[41220,"قلت: الصحيح أنهما واحدة كما قاله أبو عمرو، وأبو نعيم، وقد كشف أبو عمر الغطاء وأزال اللبس بأن قال: هي أم سليمان، كما ذكرناه عنه، والله أعلم."],[41221,"٧٣٩٨ - أم جندب بنت مسعود"],[41222,"أم جندب بنت مسعود بن أوس الأنصارية الظفرية بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41223,"حرف الحاء"],[41224,"٧٣٩٩ - أم الحارث الأنصارية"],[41225,"ب: أم الحارث الأنصارية جدة عمارة بن غزية شهدت حنينا مع النبي صلى الله عليه وآله وسلم. أخرجها أبو عمر مختصرا."],[41226,"٧٤٠٠ - أم الحارث بنت ثابت"],[41227,"أم الحارث بنت ثابت بن الجذع الأنصارية من بني حرام."],[41228,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41229,"٧٤٠١ - أم الحارث بنت عياش"],[41230,"ب د ع: أم الحارث بنت عياش بن أبي ربيعة المخزومية لها رؤية من رسول الله صلى الله عليه وآله وسلم"],[41231,"أخبرنا يحيى بن محمود، إذنا، بإسناده عن ابن أبي عاصم، حدثنا هشام بن عمار، حدثنا شعيب بن إسحاق، عن ابن جريج، عن محمد بن يحيى بن حبان، عن أم الحارث بنت عياش بن أبي ربيعة، أنها رأت بديل بن ورقاء يطوف على جمل أورق على أهل المنازل بمنى، يقول: إن رسول الله صلى الله عليه وآله وسلم «ينهاكم أن تصوموا هذه الأيام، فإنها أيام أكل وشرب»."],[41232,"أخرجها الثلاثة"],[41233,"٧٤٠٢ - أم الحارث بنت مالك"],[41234,"أم الحارث بنت مالك بن خنساء بن سنان الأنصارية بايعت النبي صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41235,"٧٤٠٣ - أم حارثة الربيع بنت النضر"],[41236,"س: أم حارثة الربيع بنت النضر."],[41237,"ذكرت في الراء."],[41238,"أخرجها أبو موسى مختصرا."],[41239,"٧٤٠٤ - أم حبان بنت عامر"],[41240,"أم حبان بنت عامر بن نابي بن زيد بن حرام بن كعب بن سلمة الأنصارية هي أخت عقبة بن عامر بن نابي."],[41241,"أسلمت وبايعت."],[41242,"قاله ابن ماكولا، عن محمد بن سعد."],[41243,"حبان: بكسر الحاء، وبالباء الموحدة."],[41244,"٧٤٠٥ - أم حبيب بنت العاص"],[41245,"س: أم حبيب بنت العاص بن أمية بن عبد شمس كانت عند عمرو بن عبدود، قاله جعفر."],[41246,"أخرجها أبو موسى مختصرا."],[41247,"فعلى هذا هي عمة خالد، وعمرو، وأبان بني سعيد بن العاص، وفيه بعد."],[41248,"والله أعلم."],[41249,"٧٤٠٦ - أم حبيب بنت العباس"],[41250,"ب د ع: أم حبيب بنت العباس بن عبد المطلب وقيل أم حبيبة والأول أكثر لها ذكر في حديث عبد الله بن العباس."],[41251,"روى يونس بن بكير، عن ابن إسحاق، قال: حدثني الحسين بن عبد الله بن عبيد الله بن العباس، عن عكرمة، عن عبد الله بن عباس، قال: نظر رسول الله صلى الله عليه وآله وسلم إلى أم حبيب بنت العباس تدب بين يديه، فقال: «لئن بلغت هذه وأنا حي لأتزوجنها»."],[41252,"فقبض قبل أن تبلغ فتزوجها الأسود بن سفيان بن عبد الأسد بن هلال بن عبد الله المخزومي."],[41253,"فولدت له رزق بن الأسود، ولبابة بنت الأسود سمتها باسم أمها أم الفضل لبابة بنت الحارث."],[41254,"أخرجها الثلاثة."],[41255,"٧٤٠٧ - أم حبيب مولاة أم عطية"],[41256,"د ع: أم حبيب مولاة أم عطية ذكرها الطبراني في المكنيات من الصحابيات، وروى، بإسناده عن شريك بن عبد الله، عن عبد الملك بن أبي سليمان، عن أم حبيب مولاة أم عطية، قالت: كنت في النسوة اللواتي أهدين بعض بنات رسول الله صلى الله عليه وآله وسلم فقال: «اصببن إذ صببتن على رأسها ثلاثا في الغسل من الجنابة»."],[41257,"أخرجها الثلاثة."],[41258,"٧٤٠٨ - أم حبيبة بنت جحش"],[41259,"ع ب س: أم حبيبة وقيل أم حبيب والأول أكثر وهي بنت جحش بن رئاب الأسدية، أخت زينب بنت جحش أم المؤمنين."],[41260,"وكانت تستحاض، وأهل السير يقولون: إن المستحاضة حمنة."],[41261,"قال أبو عمر: والصحيح أنهما كانتا تستحاضان."],[41262,"أخبرنا أبو ياسر، بإسناده عن عبد الله، حدثني أبي، حدثنا محمد بن سلمة الحراني، عن محمد بن إسحاق، عن الزهري، عن عروة، عن أم حبيبة بنت جحش، «أنها استحيضت، فسألت رسول الله صلى الله عليه وآله وسلم فأمرها بالغسل عند كل صلاة، فإن كانت لتخرج من المركن وقد علت حمرة الدم على الماء فتصلي»."],[41263,"وقد اختلف على الزهري في إسناده، فرواه ابن عيينة، عن الزهري، عن عمرة، عن عائشة، أن أم حبيب، أو أم حبيبة"],[41264,"أخبرنا يحيى بن محمود وأبو ياسر، بإسنادهما عن أبي الحسين مسلم بن الحجاج، حدثنا محمد بن سلمة المرادي، حدثنا عبد الله بن وهب، عن عمرو بن الحارث، عن الزهري، عن عروة بن الزبير وعمرة بنت عبد الرحمن، عن عائشة زوج النبي صلى الله عليه وآله وسلم أن أم حبيب بنت جحش ختنة رسول الله صلى الله عليه وآله وسلم وتحت عبد الرحمن بن عوف، استحيضت سبع سنين، واستفتت رسول الله صلى الله عليه وآله وسلم. . . . . ."],[41265,"الحديث."],[41266,"وقال معمر: عن الزهري، عن عمرة، عن أم حبيب."],[41267,"ورواه يحيى بن أبي كثير، عن أبي سلمة، عن أم حبيبة، نحوه."],[41268,"أخرجها أبو نعيم، وأبو عمر، وأبو موسى"],[41269,"٧٤٠٩ - أم حبيبة بنت أبي سفيان"],[41270,"ب د ع: أم حبيبة بنت أبي سفيان صخر بن حرب بن أمية بن عبد شمس القرشية الأموية زوج النبي صلى الله عليه وآله وسلم إحدى أمهات المؤمنين."],[41271,"كنيت بابنتها حبيبة بنت عبيد الله بن جحش، واسمها رملة."],[41272,"وقد ذكرناها في الراء."],[41273,"وكانت من السابقين إلى الإسلام."],[41274,"وهاجرت إلى الحبشة مع زوجها عبيد الله، فولدت هناك حبيبة، فتنصر عبيد الله، ومات بالحبشة نصرانيا، وبقيت أم حبيبة مسلمة بأرض الحبشة، فأرسل رسول الله صلى الله عليه وآله وسلم يخطبها إلى النجاشي، قالت أم حبيبة: ما شعرت إلا برسول النجاشي جارية يقال لها أبرهة، كانت تقوم على ثيابه ودهنه، فاستأذنت علي، فأذنت لها، فقالت إن الملك يقول لك: إن رسول الله صلى الله عليه وآله وسلم كتب إلي أن أزوجكه، فقلت: بشرك الله بخير، قالت: ويقول لك الملك: وكلي من يزوجك، فأرسلت إلى خالد بن سعيد بن العاص بن أمية فوكلته، وأعطيت أبرهة سوارين من فضة كانت علي، وخواتيم فضة كانت في أصابعي، سرورا بما بشرتني به، فلما كان العشى أمر النجاشي جعفر بن أبي طالب ومن هناك من المسلمين يحضرون، وخطب النجاشي فحمد الله، وقال: أما بعد، فإن رسول الله صلى الله عليه وآله وسلم كتب إلي أن أزوجه أم حبيبة بنت أبي سفيان، فأجبت إلى ما دعا إليه رسول الله صلى الله عليه وآله وسلم. وقد أصدقتها أربعمائة دينار، ثم سكب الدنانير بين يدي القوم، فتكلم خالد بن سعيد فحمد الله وأثنى عليه، وقال: «أما بعد فقد أجبت رسول الله صلى الله عليه وآله وسلم إلى ما دعا إليه، وزوجته أم حبيبة بنت أبي سفيان، وبارك الله لرسوله» ودفع النجاشي الدنانير إلى خالد فقبضها، ثم أرادوا أن يتفرقوا فقال: «اجلسوا فإن من سنة الأنبياء إذا تزوجوا أن يؤكل طعام على التزويج»، ودعا بطعام فأكلوا، ثم تفرقوا، وقيل: إن الذي وكلته أم حبيبة ليعقد النكاح عثمان بن عفان بن أبي العاص بن أمية من أجل أن أمها صفية بنت أبي العاص عمة عثمان."],[41275,"قال ابن إسحاق: تزوجها رسول الله صلى الله عليه وآله وسلم بعد زينب بنت خزيمة الهلالية."],[41276,"لا اختلاف بين أهل السير، وغيرهم في أن النبي صلى الله عليه وآله وسلم تزوج أم حبيبة وهي بالحبشة، إلا ما رواه مسلم بن الحجاج في صحيحه أن أبا سفيان لما أسلم طلب من رسول الله صلى الله عليه وآله وسلم أن يتزوجها فأجابه إلى ذلك."],[41277,"وهو وهم من بعض رواته."],[41278,"أخبرنا أبو بكر محمد بن عبد الوهاب بن عبد الله بن علي الأنصاري يعرف بابن الشيرجي الدمشقي، وغير واحد، قالوا: أخبرنا الحافظ أبو القاسم علي بن الحسن بن هبة الله، أخبرنا أبو المكارم محمد بن أحمد بن المحسن الطوسي، حدثنا أبو الفضل محمد بن أحمد بن الحسن العارف الميهني، أخبرنا أبو بكر أحمد بن الحسن بن أحمد الحرشي، حدثنا أبو محمد حاجب بن أحمد بن يرحم الطوسي، حدثنا عبد الرحيم بن منيب المروزي، حدثنا يزيد بن هارون، حدثنا محمد بن عبد الله الشعيثي، عن أبيه، عن عنبسة بن أبي سفيان، عن أم حبيبة زوج النبي صلى الله عليه وآله وسلم تعني عن النبي صلى الله عليه وآله وسلم قال: «من صلى أربعا قبل الظهر وأربعا بعدها، حرم على النار»."],[41279,"وتوفيت أم حبيبة سنة أربع وأربعين."],[41280,"أخرجها الثلاثة"],[41281,"٧٤١٠ - أم حذيفة بن اليمان"],[41282,"د ع: أم حذيفة بن اليمان لها ذكر في حديث حذيفة."],[41283,"روى إسرائيل، عن ميسرة بن حبيب، عن المنهال بن عمرو، عن زر بن حبيش، عن حذيفة، قال: قالت لي أمي: متى عهدك بالنبي صلى الله عليه وآله وسلم فقلت لها: ما لي به عهد منذ كذا وكذا، فأتيته وهو يصلي المغرب، فقال: «يا حذيفة، أما رأيت العارض الذي عرض؟» قلت: بلى، قال: «ذاك ملك أتاني وبشرني بأن الحسن والحسين سيدا شباب أهل الجنة، وأن فاطمة سيدة نساء أهل الجنة»."],[41284,"أخرجها ابن منده، وأبو نعيم."],[41285,"٧٤١١ - أم حرام بنت ملحان"],[41286,"ب د ع: أم حرام بنت ملحان بن خالد بن زيد بن حرام بن جندب بن عامر بن غنم بن عدي بن النجار الأنصارية الخزرجية أمها مليكة بنت مالك بن عدي بن زيد مناة بن عدي ابن عمرو بن مالك بن النجار."],[41287,"وأم حرام خالة أنس بن مالك، وهي زوجة عبادة بن الصامت، واسمها الرميصاء، وقيل: الغميصاء، ولا يصح لها اسم."],[41288,"وكان رسول الله صلى الله عليه وآله وسلم يكرمها ويزورها في بيتها، ويقيل عندها، وأخبرها أنها شهيدة."],[41289,"أخبرنا أبو ياسر، بإسناده عن عبد الله بن أحمد، حدثني أبي، أخبرنا عبد الصمد، حدثني أبي، حدثنا يحيى بن سعيد، حدثني محمد بن يحيى بن حبان، حدثني أنس بن مالك، عن أم حرام بنت ملحان، وكانت خالته، أن رسول الله صلى الله عليه وآله وسلم نام أو قال في بيتها، فاستيقظ وهو يضحك، وقال: «عرض علي ناس من أمتي يركبون ظهر البحر الأخضر كالملوك على الأسرة»، قالت: فقلت: يا رسول الله، دع الله أن يجعلني منهم."],[41290,"قال: «إنك منهم»، ثم نام فاستيقظ وهو يضحكك، فقلت: يا رسول الله، ما يضحك؟ فقال: «عرض علي ناس من أمتي يركبون ظهر البحر الأخضر كالملوك على الأسرة»."],[41291,"قلت: يا رسول الله، ادع الله أن يجعلني منهم، قال: «أنت من الأولين»."],[41292,"فتزوجها عبادة بن الصامت، فأخرجها معه، فلما جاز البحر بها ركبت دابة فصرعتها فقتلتها."],[41293,"وكانت تلك الغزوة غزوة قبرس فدفنت فيها."],[41294,"وكان أمير ذلك الجيش معاوية بن أبي سفيان في خلافة عثمان، ومعه أبو ذر، وأبو الدرداء، وغيرهما من الصحابة، وذلك سنة سبع وعشرين."],[41295,"أخرجها الثلاثة"],[41296,"٧٤١٢ - أم حرملة بنت عبد الأسود"],[41297,"ب س: أم حرملة بنت عيد الأسود بن جذيمة بن أقيش بن عامر بن بياضة بن سبيع بن جعثمة بن سعد بن مليح بن عمرو بن خزاعة أسلمت قديما، وهاجرت إلى الحبشة مع زوجها جهم بن قيس بن عبد بن شرحبيل."],[41298,"قاله ابن إسحاق."],[41299,"أخرجها أبو عمر، وأبو موسى وهو نسبها."],[41300,"٧٤١٣ - أم حسان بنت شداد"],[41301,"س: أم حسان بن شداد ذكرناها في ترجمة ابنها حسان."],[41302,"أخرجها أبو موسى."],[41303,"٧٤١٤ - أم الحصين بنت إسحاق"],[41304,"ب د ع: أم الحصين بنت إسحاق الأحمسية"],[41305,"أخبرنا يحيى بن محمود وأبو ياسر، بإسنادهما عن مسلم أبي الحسين، قال: حدثني أحمد بن حنبل، حدثني محمد بن سلمة، عن أبي عبد الرحيم، عن زيد بن أبي أنيسة، عن يحيى بن الحصين، عن أم الحصين جدته، قالت: «حججت مع النبي صلى الله عليه وآله وسلم حجة الوداع، فرأيت أسامة وبلالا، أحدهما آخذ بخطام ناقة رسول الله صلى الله عليه وآله وسلم والآخر رافع ثوبه يستره من الحر، حتى رمى جمرة العقبة»."],[41306,"واسم أبي عبد الرحيم: خالد بن أبي يزيد."],[41307,"أخرجها الثلاثة"],[41308,"٧٤١٥ - أم حفيد"],[41309,"ب د ع: أم حفيد واسمها هزيلة بنت الحارث الهلالية وهي أخت ميمونة بنت الحارث أم المؤمنين، وهي أيضا خالة ابن عباس، وخالد بن الوليد."],[41310,"وذكرت في حديث ابن عباس."],[41311,"وهي التي أهدت السمن والأقط والأضب إلى رسول الله صلى الله عليه وآله وسلم فأكل السمن والأقط، ولم يأكل الضباب، تركها تقذرا، وأكلت على مائدته صلى الله عليه وآله وسلم وكانت تسكن البادية."],[41312,"أخبرنا أبو الفضل بن أبي الحسن الطبري، بإسناده عن أحمد بن علي، قال: حدثنا أبو عوانة، عن أبي بشر، عن سعيد بن جبير، عن ابن عباس، قال: «أهدت أم حفيد خالتي ابنة الحارث إلى رسول الله صلى الله عليه وآله وسلم سمنا وأقطا وأضبا، فدعا بهن رسول الله صلى الله عليه وآله وسلم فأكلن على مائدته، تركهن تقذرا لهن، ولو كن حراما لما أكلن على مائدة رسول الله صلى الله عليه وآله وسلم ولا أمر بأكلهن»."],[41313,"أخرجها الثلاثة"],[41314,"٧٤١٦ - أم الحكم بنت الزبير"],[41315,"د ع: أم الحكم بنت الزبير بن عبد المطلب القرشية الهاشمية بنت عم النبي صلى الله عليه وآله وسلم وهي أخت ضباعة بنت الزبير."],[41316,"وقيل فيها: أم حكيم"],[41317,"أخبرنا أبو أحمد بن علي الأمين، بإسناده عن سليمان بن الأشعث، حدثنا أحمد بن صالح، حدثنا عبد الله بن وهب، حدثني عياش بن عقب الحضرمي، عن الفضل بن الحسن بن عمرو بن أمية الضمري، أن أم الحكم أو ضباعة ابنتي الزبير، حدثته أنها قالت: أصاب رسول الله صلى الله عليه وآله وسلم سبيا، فذهبت أنا وأختي إلى فاطمة بنت رسول الله صلى الله عليه وآله وسلم ثم أتينا رسول الله صلى الله عليه وآله وسلم فشكونا إليه ما نحن فيه، فسألناه أن يأمر لنا بشيء من السبي، فقال رسول الله صلى الله عليه وآله وسلم: «سبقكن يتامى بدر، ولكن سأدلكن على ما هو خير لكن من ذلك: تكبرن الله عز وجل على إثر كل صلاة ثلاثا وثلاثين تكبيرة، وثلاثا وثلاثين تسبيحة، وثلاثا وثلاثين تحميدة، ولا إله إلا الله وحده، لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير» روى قتادة، عن عبد الله بن الحارث، عن أم الحكم بنت الزبير، أن النبي صلى الله عليه وآله وسلم «أكل من لحم كتف، ثم قام إلى الصلاة فصلى ولم يتوضأ»."],[41318,"أخرجها ابن منده."],[41319,"وأبو نعيم."],[41320,"٧٤١٧ - أم الحكم بنت أبي سفيان"],[41321,"ب: أم الحكم بنت أبي سفيان صخر بن حرب بن أمية بن عبد شمس القرشية الأموية أخت أم حبيبة، زوج النبي صلى الله عليه وآله وسلم لأبيها، وأخت معاوية لأبيه وأمه."],[41322,"أسلمت يوم الفتح، وكانت حين نزل قوله تعالى: ﴿وَلا تُمْسِكُوا بِعِصَمِ الْكَوَافِرِ﴾، تحت عياض بن غنم القهري، فطلقها حينئذ، فتزوجها عبد الله بن عثمان الثقفي، وهي أم عبد الرحمن بن عبد الله بن عثمان، المعروف بابن أم الحكم."],[41323,"أخرجها أبو عمر."],[41324,"٧٤١٨ - أم الحكم الضمرية"],[41325,"س: أم الحكم الضمرية قسم لها رسول الله صلى الله عليه وآله وسلم من خيبر ثلاثين وسقا، قاله جعفر."],[41326,"وأخبرنا يحيى، كتابة، بإسناده عن ابن أبي عاصم، قال: حدثنا أبو بكر بن أبي شيبة، عن زيد بن الحباب، عن عياش بن عقبة، عن الفضل بن الحسن بن عمرو بن أمية الضمري، قال: حدثني ابن أم الحكم، قال: حدثتني أمي أم الحكم، أن رسول الله صلى الله عليه وآله وسلم قدم من بعض غزواته وقد أصاب رقيقا، فذهبت هي وأختها حتى دخلت على فاطمة، فذهبت إلى رسول الله صلى الله عليه وآله وسلم فسألته أن يخدمهن فشكين إليه الحاجة، فقال رسول الله صلى الله عليه وآله وسلم: «سبقكن يتامى أهل بدر، أو أيامى أهل بدر»."],[41327,"أخرجها أبو موسى، وترجمها ضمرية وذكرها ابن أبي عاصم كما رويناه عنه ههنا، ولم يجعلها ضمرية إلا أنه جعلها ترجمة منفردة عن أم الحكم بنت الزبير، التي تقدم ذكرها، جعلهما اثنتين."],[41328,"وما أظنه إلا وهما، فإن الحديث تقدم عن أم الحكم بنت الزبير، ولعل من جعلها ضمرية اشتبه عليه، حيث رأى الراوي ضمريا، والله أعلم."],[41329,"وقد أخرج ابن منده هذا المتن لبنت الزبير، ولم يزد أبو موسى عليه، إلا أنه جعلها ضمرية، فإن كان ظنها غيرها، فهما واحدة، فإن الحديث، والإسناد واحدا"],[41330,"٧٤١٩ - أم الحكم بنت عبد الرحمن الأنصارية"],[41331,"أم الحكم بنت عبد الرحمن بن مسعود بن ثعلبة الأنصارية من بني خدارة."],[41332,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41333,"٧٤٢٠ - أم الحكم الغفارية"],[41334,"أم الحكم الغفارية ذكرها الحسن بن سفيان."],[41335,"أخبرنا أبو موسى، إجازة، أخبرنا الحسن، حدثنا أحمد بن عبد الله، حدثنا أبو عمرو بن حمدان، حدثنا الحسن بن سفيان، حدثنا عبد الله بن محمد الخطابي، حدثنا يحيى بن المتوكل، قال: حدثتنا ماطرة، حدثتني أم جعفر بنت النعمان، عن أم الحكم الغفارية، أنها سئلت: هل سمعت رسول الله صلى الله عليه وآله وسلم يذكر الساعة؟ قالت: نعم سمعته يقول: «إذا قلت العرب …"],[41336,"»."],[41337,"هذا الحديث معروف بأمر شريك"],[41338,"٧٤٢١ - أم حكيم بنت الحارث"],[41339,"ب د ع: أم حكيم بنت الحارث بن هشام القرشية المخزومية وأمها فاطمة بنت الوليد أخت خالد."],[41340,"وشهدت أحدا كافرة، ثم أسلمت يوم الفتح، كانت تحت ابن عمها عكرمة بن أبي جهل، ولما أسلمت كان زوجها قد هرب إلى اليمن، فاستأمنت له من النبي صلى الله عليه وآله وسلم واستأذنته في أن تسير في طلبه فأذن لها، فردته فأسلم."],[41341,"وقتل عنها عكرمة، فتزوجها خالد بن سعيد، فلما نزل المسلمون مرج الصفر عند دمشق، أراد خالد أن يعرس بها، فقالت: لو تأخرت حتى يهزم الله هذه الجموع؟ فقال: إن نفسي تحدثني أني أقتل، فقالت: فدونك."],[41342,"فأعرس بها عند القنطرة التي بالصفر، فبها سميت قنطرة أم حكيم."],[41343,"وأولم عليها فما فرغوا من الطعام حتى تقدمت الروم، وقاتلوا وقتل خالد، وقاتلت أم حكيم يومئذ فقتلت سبعة بعمود الفسطاط الذي عرس بها خالد فيه."],[41344,"أخرجها الثلاثة."],[41345,"٧٤٢٢ - أم حكيم بنت حرام"],[41346,"أم حكيم بنت حزام أسرت يوم بدر، ثم أسلمت وبايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41347,"٧٤٢٣ - أم حكيم بنت الزبير"],[41348,"ب د ع: أم حكيم بنت الزبير بن عبد المطلب وقيل أم الحكم واسمها صفية، وهي أخت ضباعة."],[41349,"روي لها أن النبي صلى الله عليه وآله وسلم أكل من كتف ثم صلى ولم يتوضأ."],[41350,"وروى لها ابن منده، وأبو نعيم، بإسنادهما عن عياش بن عقبة الحضرمي، عن الفضل بن الحسن، عن ابن أم الحكم، عن أمة أم الحكم بنت الزبير، حديث طلب الخادم."],[41351,"وقد تقدم في أم الحكم."],[41352,"وحديث حماد بن سلمة، عن عمار، عن أم حكيم، قالت: «أكل رسول الله صلى الله عليه وآله وسلم كتف شاة فصلى ولم يتوضأ»."],[41353,"أخبرنا به يحيى بن محمود، إذنا، بإسناده عن ابن أبي عاصم، حدثنا هدبة بن خالد، حدثنا حماد بن سلمة، عن عمار بن أبي عمار، عن أم حكيم بنت الزبير بن عبد المطلب، قالت: «دخل علي رسول الله صلى الله عليه وآله وسلم بيتي، فأكل كتفا، ثم جاءه بلال فآذنه بالصلاة، فذهب فصلى ولم يتوضأ»."],[41354,"وقد روى هذا الحديث، عن أم حكيم، عن أختها."],[41355,"أخرجها الثلاثة"],[41356,"٧٤٢٤ - أم حكيم امرأة عثمان"],[41357,"د ع: أم حكيم امرأة عثمان بن مظعون كانت تعتكف مع عمر، رواه عمر بن ذر، عن مجاهد مرسلا."],[41358,"أخرجها ابن منده، وأبو نعيم، وقال أبو نعيم: إنما هي بنت حكيم، واسمها خولة بنت حكيم."],[41359,"٧٤٢٥ - أم حكيم بنت عتبة"],[41360,"ب: أم حكيم بنت عتبة بن أبي وقاص كانت من المهاجرات."],[41361,"أخرجها أبو عمر مختصرا."],[41362,"٧٤٢٦ - أم حكيم بنت وداع"],[41363,"ب د ع: أم حكيم بنت وداع الخزاعية كانت من المهاجرات، قاله أبو نعيم، وأبو عمر."],[41364,"وقال ابن منده: وادع."],[41365,"روت عنها صفية بنت جرير أنها سمعت النبي صلى الله عليه وآله وسلم يقول: «تهادوا فإنه يذهب بغوائل الصدور»."],[41366,"وسمعت النبي صلى الله عليه وآله وسلم يقول: «عجلوا الإفطار وأخروا السحور»."],[41367,"أخرجها الثلاثة."],[41368,"٧٤٢٧ - أم حميد الأنصارية"],[41369,"ب د ع: أم حميد الأنصارية امرأة أبي حميد الساعدي"],[41370,"أخبرنا يحيى بن محمود، إجازة، بإسناده عن ابن أبي عاصم، حدثنا أبو بكر بن أبي شيبة، حدثنا زيد بن الحباب، عن عبد الحميد بن المنذر بن أبي حميد الساعدي، عن أبيه، عن جدته أم حميد، أنها قالت: قلت: يا رسول الله، يمنعنا أزواجنا أن نصلي معك، ونحب الصلاة معك؟ فقال رسول الله صلى الله عليه وآله وسلم: «صلاتكن في بيوتكن أفضل من صلاتكن في حجركن، وصلاتكن في حجركن أفضل من صلاتكن في دوركن، وصلاتكن في دوركن أفضل من صلاتكن في الجماعة»."],[41371,"ورواه ابن وهب، عن داود بن قيس، عن عبيد الله بن سويد الأنصاري، عن عمته أم حميد امرأة أبي حميد، عن النبي صلى الله عليه وآله وسلم نحوه."],[41372,"أخرجها الثلاثة"],[41373,"حرف الخاء"],[41374,"٧٤٢٨ - أم خارجة، امرأة زيد بن ثابت"],[41375,"د ع: أم خارجة امرأة زيد بن ثابت أدركت النبي صلى الله عليه وآله وسلم ذكرها ابن أبي عاصم في الوحدان."],[41376,"أخبرنا يحيى فيما أذن لي، بإسناده عن ابن أبي عاصم، حدثنا محمد بن إسماعيل، حدثنا مكي بن إبراهيم، حدثنا عبيد الله بن أبي زياد، حدثنا أبو بكر بن عبد الله بن أبي ربيعة، حدثتني أم خارجة امرأة زيد بن ثابت، قالت: أتينا رسول الله صلى الله عليه وآله وسلم في حائط ومعه أصحابه، إذ قال: «أول رجل يطلع عليكم فهو من أهل الجنة»، فليس أحد منا إلا وهو يتمنى أن يكون من وراء الحائط، قالت: فبينما نحن كذلك إذ سمعنا حسا، فرفعنا أبصارنا إليه ننظر من يدخل، فقال رسول الله صلى الله عليه وآله وسلم: «عسى أن يكون عليا»."],[41377,"فدخل علي بن أبي طالب."],[41378,"أخرجها ابن منده، وأبو نعيم"],[41379,"٧٤٢٩ - أم خارجة بنت النضر"],[41380,"أم خارجة بنت النضر بن ضمضم الأنصارية من بني عدي بن النجار، بايعت النبي صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41381,"٧٤٣٠ - أم خالد بنت الأسود"],[41382,"ع س: أم خالد بنت الأسود بن عبد يغوث القرشية الزهرية"],[41383,"أخبرنا يحيى، إذنا، بإسناده عن ابن أبي عاصم، حدثنا محمد بن مصفى، حدثنا معاوية بن حفص، عن ابن المبارك، عن معمر، عن الزهري، عن عبيد الله بن عبد الله، عن أم خالد بنت الأسود بن عبد يغوث، أنها دخلت على النبي صلى الله عليه وآله وسلم فقال: «من هذه؟» قالوا: أم خالد بنت الأسود، قال: «الحمد لله الذي يخرج الحي من الميت»، وقيل: اسمها خالدة."],[41384,"وقد ذكرناها."],[41385,"أخرجها أبو نعيم، وأبو موسى"],[41386,"٧٤٣١ - أم خالد بنت خالد بن سعيد"],[41387,"ب د ع: أم خالد بنت خالد بن سعيد بن العاص بن أمية القرشية الأموية اسمها أمة وأمها همينة بنت خلف الخزاعية أسلمت أيضا، وقد ذكرناها."],[41388,"أخبرنا أبو بكر بن عمر بن العويس، وغير واحد، بإسنادهم عن محمد بن إسماعيل، حدثنا حبان، أخبرنا ابن المبارك، عن خالد بن سعيد، عن أبيه، عن أمه أم خالد، قالت: أتيت رسول الله صلى الله عليه وآله وسلم مع أبي، وعلي قميص أصفر، فقال رسول الله صلى الله عليه وآله وسلم: «سنة سنة»، قال عبد الله: وهي بالحبشية: حسنة فذهبت ألعب بخاتم النبوة فزبرني أبي، فقال رسول الله صلى الله عليه وآله وسلم: «دعها»"],[41389,"قال: وحدثنا محمد بن إسماعيل، حدثنا الفضل بن دكين، حدثنا إسحاق بن سعيد، عن أبيه سعيد بن فلان بن سعيد بن العاص، عن أم خالد بنت خالد، قالت: أتي النبي صلى الله عليه وآله وسلم بثياب فيها خميصة سوداء صغيرة فقال: «من ترون أكسو هذه؟» فسكت القوم، فقال: «ائتوني بأم خالد»، فأتي بها تحمل، فأخذ الخميصة بيده فألبسها، وقال: «أبلي وأخلقي»، وكان فيها علم أخضر أو أصفر، فقال: «يا أم خالد، هذا سناه."],[41390,"وسناه». بالحبشية. حسنة."],[41391,"أخرجها الثلاثة"],[41392,"٧٤٣٢ - أم خالد بنت يعيش"],[41393,"أم خالد بنت يعيش بن قيس بن عمرو الأنصارية من بني مالك."],[41394,"بايعت النبي صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41395,"٧٤٣٣ - أم خلاد"],[41396,"أم خلاد هي التي سالت عن ابنها وقد قتل."],[41397,"وقد تقدمت القصة في خلاد الأنصاري، في حرف الخاء."],[41398,"٧٤٣٤ - أم خناس"],[41399,"أم خناس قال ابن ماكولا: وأما خناس، أوله خاء معجمة، وبعدها نون خفيفة وذكر خناسا السكوني ثم قال: أم خناس، امرأة مسعود، لها صحبة."],[41400,"٧٤٣٥ - أم خولة بنت حكيم"],[41401,"ب: أم خولة بنت حكيم الأنصارية روى بكير بن الأشج، عن خولة، عن أمها، أن رسول الله صلى الله عليه وآله وسلم قال لأم سلمة: «لا تطيبي وأنت محد ولا تمسي الحناء فإنه طيب»."],[41402,"أخرجها أبو عمر."],[41403,"٧٤٣٦ - أم الخير بنت صخر"],[41404,"ب د ع: أم الخير بنت صخر بن عامر بن كعب بن سعد بن تيم بن مرة القرشية التيمية واسمها سلمى، وهي أم أبي بكر الصديق."],[41405,"قال الزبير: بايعت النبي صلى الله عليه وآله وسلم. روى القاسم بن محمد، عن عائشة، قالت: لما أسلم أبو بكر قام خطيبا، فكان أول خطبته دعا إلى الله ورسوله، فثار المشركون على أبي بكر، فضربوه ضربا شديدا، ودنا منه عتبة بن ربيعة وجعل يضربه بنعلين مخصوفتين ويحرفهما بوجهه، ونزا على بطن أبي بكر حتى ما يعرف أنفه من وجه."],[41406,"فجاءت بنو تيم فحملت أبا بكر في ثوب حتى أدخلوه منزله، لا يشكون في موته، وجعل أبوه وبنو تيم يكلمونه، فأجابهم آخر النهار فقال: ما فعل رسول الله صلى الله عليه وآله وسلم فنالوا منه بألسنتهم وعذلوه وفارقوه، فلم يزل يسأل عن رسول الله صلى الله عليه وآله وسلم حتى حمل إليه فأكب عليه رسول الله صلى الله عليه وآله وسلم يقبله، ورق عليه رسول الله صلى الله عليه وآله وسلم رقة شديدة، فقال أبو بكر: يا رسول الله هذه أمي، وأنت مبارك، فادع لها، وادعها إلى الإسلام، لعل الله أن يستنقذها بك من النار."],[41407,"فدعا لها رسول الله صلى الله عليه وآله وسلم ودعاها إلى الله تعالى فأسلمت."],[41408,"قال أبو نعيم: لما توفي أبو بكر رضي الله عنه ورثه أبواه جميعا، أبو قحافة وأم الخير."],[41409,"روى الزهري، عن عبيد الله بن عبد الله بن عتبة، عن ابن عباس، قال: «أسلمت أم أبي بكر، وأم عثمان، وأم طلحة، وأم الزبير، وأم عبد الرحمن بن عوف، وأم عمار بن ياسر»."],[41410,"قيل: إنها أسلمت قديما مع ابنها أبي بكر وتوفيت أم الخير قبل أبي قحافة."],[41411,"أخرجها الثلاثة."],[41412,"حرف الدال والذال"],[41413,"٧٤٣٧ - أم الدحداح"],[41414,"أم الدٍحداح زوج أبي الدحداح لها ذكر في حديث أبي الدحداح وصدقته بالحائط الذي فيه النخل، فقال: يا أم الدحداح، اخرجي، يعني: من الحائط."],[41415,"ذكره الأشيري."],[41416,"٧٤٣٨ - أم الدرداء"],[41417,"ب د ع: أم الدرداء زوج أبي الدرداء وهي الكبرى واسمها خيرة بنت أبي حدرد الأسلمي قاله أحمد بن حنبل وابن معين، وقالا: أم الدرداء الصغرى اسمها هجيمة الوصابية، قاله أبو عمر."],[41418,"وقال أبو نعيم: اسمها خيرة، وقيل: هجيمة."],[41419,"روى عنها معاذ بن أنس، وطلحة بن عبيد الله، وميمون بن مهران."],[41420,"أخبرنا أبو ياسر، بإسناده عن عبد الله بن أحمد، حدثني أبي، حدثنا ابن نمير، حدثنا فضيل بن غزوان، سمعت طلحة بن عبيد الله بن كريز، قال: سمعت أم الدرداء، قالت: سمعت رسول الله صلى الله عليه وآله وسلم يقول: «يستجاب للمرء بظهر الغيب لأخيه، فما دعا لأخيه بدعوة إلا قال الملك: ولك بمثل» وكانت أم الدرداء من فضلاء النساء وعقلائهن، ومن ذوات العبادة."],[41421,"وتوفيت قبل أبي الدرداء بسنتين، وكانت وفاتها بالشام في خلافة عثمان، وحفظت عن رسول الله صلى الله عليه وآله وسلم وعن زوجها أبي الدرداء."],[41422,"أخرجها الثلاثة."],[41423,"قلت: قول أبي نعيم: اسمها خيرة، وقيل هجيمة وهم لا شك فيه، لأنه قد ظن أنهما واحدة."],[41424,"وقد اختلف في اسمها، وليس كذلك إنما هما اثنتان، أم الدرداء الكبرى وهي هذه خيرة، ولها صحبة."],[41425,"وأم الدرداء الصغرى، وهي هجيمة الوصابية، وقد تقدم الكلام عليهما في خيرة من الأسماء، أتم من هذا."],[41426,"٧٤٣٩ - أم ذر"],[41427,"د ع: أم ذر، بالذال العجمية، هي امرأة أبي ذر الغفاري لها ذكر في وفاة أبي ذر."],[41428,"أخرجها ابن منده، وأبو نعيم."],[41429,"٧٤٤٠ - أم أبي ذر"],[41430,"أم أبي ذر أسلمت، وقد ذكر إسلامها في حديث طويل في إسلام أبي ذر وأمه وأخيه، وقد ذكرناه في إسلام أبي ذر."],[41431,"٧٤٤١ - أم ذرة"],[41432,"أم ذرة مذكورة في الصحابيات."],[41433,"حديثها عند محمد بن المنكدر، أنها سمعت النبي صلى الله عليه وآله وسلم يقول: «أنا وكافل اليتيم يوم القيامة كهاتين»."],[41434,"حرف الراء"],[41435,"٧٤٤٢ - أم رافع بنت عثمان"],[41436,"أم رافع بنت عثمان بن خلدة بن مخلد الأنصارية من بني زريق."],[41437,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41438,"٧٤٤٣ - أم رافع"],[41439,"د ع: أم رافع أدركت النبي صلى الله عليه وآله وسلم. واسمها سلمى، وقد ذكرها في سلمى."],[41440,"روى الليث، عن هشام بن سعد، عن زيد ابن أسلم، عن عبيد الله بن وهب، عن أم رافع، أنها قالت: يا رسول الله، أخبرني بشيء أفتتح به صلاتي، فقال: «إذا قمت إلى الصلاة فقولي: الله أكبر عشرا، فإنك إذا قلت ذلك قال الله عز وجل: هذا لي، ثم قولي: سبحان الله وبحمده عشرا، فإنك إذا قلت ذلك قال الله عز وجل: هذا لي."],[41441,"واحمدي الله عز وجل عشرا، فإنك إذا قلت ذلك قال الله عز وجل: هذا لي."],[41442,"واستغفري الله عشرا، فإنك إذا قلت ذلك قال الله عز وجل: قد غفرت لك»."],[41443,"ورواه عطاف بن خالد، عن زيد بن أسلم، عن أم رافع، أنها قالت: دلني يا رسول الله على عمل يأجرني الله عليه."],[41444,"قال: «يا أم رافع، إذا قمت إلى الصلاة فسبحي الله عشرا، واحمديه عشرا، وهلليه عشرا، وكبريه عشرا، واستغفريه عشرا، فإنك إذا سبحت، قال: هذا لي، وإذا حمدت، قال: هذا لي."],[41445,"وإذا هللت، قال: هذا لي، وإذا كبرت، قال: هذا لي."],[41446,"وإذا استغفرت، قال: قد غفرت لك»."],[41447,"أخرجه ابن منده، وأبو نعيم."],[41448,"٧٤٤٤ - أم رافع بنت عبد الله"],[41449,"أم رافع بنت عبد الله بن النعمان بن عبيد الأنصارية من بني مالك."],[41450,"أدركت النبي، وبايعته."],[41451,"قاله ابن حبيب."],[41452,"٧٤٤٥ - أم ربعة بنت خذام"],[41453,"س: أم ربعة بنت خذام قال أبو موسى: كأنها كنية خنساء بنت خذام."],[41454,"أخبرنا القاضي أبو الخير عمر بن محمد بن عبد الله بن عزيزة، حدثنا شجاع وأحمد، ابنا علي ابن شجاع، قالا: أخبرنا محمد بن إسحاق الحافظ، أخبرنا أحمد بن محمد بن زياد، حدثنا عباس بن محمد الدوري، حدثنا أحمد بن يونس، حدثنا أبو بكر بن عياش، عن يعقوب بن عطاء، عن عطاء، عن ابن عباس، قال: «زوج خذام ربعة ابنته وهي كارهة، فأتت النبي صلى الله عليه وآله وسلم فذكرت ذلك له، فنزعها من زوجها، فتزوجها أبو لبابة»."],[41455,"هذا حديث غريب عن يعقوب، وفي سائر الروايات أنها خنساء."],[41456,"أخرجها أبو موسى"],[41457,"٧٤٤٦ - أم الربيع بنت أسلم"],[41458,"أم الربيع بنت أسلم بن الحريش بن عدي بن مجدعة امرأة برذع بن زيد الظفري، وهي أم يزيد بن برذع."],[41459,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41460,"٧٤٤٧ - أم الربيع"],[41461,"أم الربيع"],[41462,"أخبرنا يعيش بن صدقة بن علي، بإسناده عن أبي عبد الرحمن بن شعيب: أخبرنا أحمد بن سليمان، حدثنا عفان، حدثنا حماد بن سلمة، حدثنا ثابت، عن أنس، أن أم الربيع أم حارثة جرحت إنسانا، فاختصموا إلى النبي صلى الله عليه وآله وسلم فقال رسول الله صلى الله عليه وآله وسلم: «القصاص القصاص»، فقالت أم الربيع: يا رسول الله، أتقتص من فلانة؟ لا، والله لا يقتص منها أبدا، فقال رسول الله صلى الله عليه وآله وسلم: «سبحان الله يا أم الربيع القصاص كتاب الله»، قالت: لا، والله لا يقتص منها أبدا."],[41463,"فما زالت حتى قبلوا الدية، فقال رسول الله صلى الله عليه وآله وسلم: «إن من عباد الله من لو أقسم على الله لأبره»."],[41464,"هكذا في هذه الرواية، وقد روى أن الربيع هي التي أقسمت، والله أعلم"],[41465,"٧٤٤٨ - أم رعلة"],[41466,"س: أم رعلة القشيرية أوردها جعفر المستغفري."],[41467,"روى بإسناد ضعيف عن الأوزاعي، عن عطاء، عن ابن عباس، قال: وفدت إلى النبي صلى الله عليه وآله وسلم امرأة يقال لها: أم رعلة القشيرية، وكانت امرأة ذات لسان وفصاحة، فقالت: السلام عليك يا رسول الله ورحمة الله وبركاته، إنا ذوات الخدور، ومحل أزر البعول، ومربيات الأولاد، وممهدات المهاد، ولا حظ لنا في الجيش الأعظم، فعلمنا شيئا يقربنا إلى الله عز وجل فقال لها النبي صلى الله عليه وآله وسلم: «عليكن بذكر الله عز وجل آناء الليل وأطراف النهار، وغض البصر، وخفض الصوت …"],[41468,"» الحديث."],[41469,"أخرجه أبو موسى."],[41470,"٧٤٤٩ - أم رمثة"],[41471,"ب: أم رمثة شهدت فتح خيبر."],[41472,"أخرجها أبو عمر مختصرا، وقال: لا أعرف لها غير هذا الخبر."],[41473,"أخبرنا أبو جعفر، بإسناده عن يونس، عن ابن إسحاق في تسمية من أعطاه النبي صلى الله عليه وآله وسلم من خيبر: ولأم رميثة أربعين وسقا"],[41474,"٧٤٥٠ - أم رومان بنت عامر"],[41475,"ب د ع: أم رومان بنت عامر بن عويمر بن عبد شمس بن عتاب بن أذينة بن سبيع بن دهمان بن الحارث بن غنم بن مالك بن كنانة الكنانية امراة أبي بكر الصديق."],[41476,"وهي أم عائشة، وعبد الرحمن ولدي أبي بكر."],[41477,"كذا نسبها الزبير، وخالفه غيره خلافا كثيرا، وأجمعوا أنها من بني غنم بن مالك بن كنانة."],[41478,"وتوفيت في حياة رسول الله صلى الله عليه وآله وسلم في ذي الحجة سنة ست من الهجرة، وقيل: سنة أربع، وقيل: سنة خمس، قاله أبو عمر، فنزل رسول الله صلى الله عليه وآله وسلم في قبرها، واستغفر لها."],[41479,"وروي عن النبي صلى الله عليه وآله وسلم أنه قال: «من سره أن ينظر إلى امرأة من الحور العين فلينظر إلى أم رومان»."],[41480,"وكانت قبل أبي بكر تحت عبد الله بن الحارث بن سخبرة بن جرثومة الخير بن عادية بن مرة الأزدي، فولدت له الطفيل، وتوفي عنها، فخلف عليها أبو بكر، فولدت له عائشة، وعبد الرحمن، فهما أخوان الطفيل لأمه."],[41481,"روى هشام بن عروة، عن أبيه، عن عائشة، قالت: «لما هاجر رسول الله صلى الله عليه وآله وسلم خلفنا وخلف بناته، فلما استقر بعث زيد بن حارثة، وبعث معه أبا رافع مولاه، وأعطاهما بعيرين وخمسمائة درهم يشتريان بها ما يحتاجان إليه من الظهر، وبعث أبو بكر معهما عبد الله بن أريقط ببعيرين أو ثلاثة، وكتب إلى ابنه عبد الله بن أبي بكر أن يحمل أمي أم رومان وأن وأختي أسماء، فخرجوا مصطحبين، وكان طلحة يريد الهجرة فسار معهم، وخرج زيد، وأبو رافع بفاطمة وأم كلثوم وسودة بنت زمعة، زوج النبي صلى الله عليه وآله وسلم وأم أيمن."],[41482,"فقدمنا المدينة والنبي صلى الله عليه وآله وسلم يبني مسجده وأبياتنا حول المسجد، فأنزل فيها أهله»."],[41483,"أخرجها الثلاثة."],[41484,"قلت: من زعم أنها توفيت سنة أربع أو خمس، فقد وهم، فإنه صح أنها كانت في الإفك حية، وكان الإفك سنة ست في شعبان، والله أعلم."],[41485,"حرف الزاي"],[41486,"٧٤٥١ - أم زفر"],[41487,"ب د ع: أم زفر هي التي كان بها مس من الجن."],[41488,"روى ابن جريج، عن الحسن بن مسلم، عن طاوس، قال: كان النبي صلى الله عليه وآله وسلم يؤتى بالمجانين، فيضرب صدر أحدهم فيبرأ، فأتي بمجنونة يقال لها: أم زفر، فضرب صدرها فلم تبرا ولم يخرج شيطانها فقال رسول الله صلى الله عليه وآله وسلم: «هو يعيبها في الدنيا، ولها في الآخرة خير»."],[41489,"قال ابن جريج: وأخبرني عطاء أنه رأى أم زفر امرأة سوداء طويلة على سلم الكعبة."],[41490,"قال ابن جريج: أخبرني عبد الكريم، عن الحسن، أنه سمعه يقول: كانت امرأة تحمق، فجاء أخوتها فشكوا ذلك إليه، فقال: «إن شئتم دعوت الله فبرأت، وإن شئتم كانت كما هي، ولا حساب عليها في الآخرة»."],[41491,"فخيرها إخوتها فقالت: دعوني كما أنا."],[41492,"فتركوها."],[41493,"أخرجها الثلاثة."],[41494,"٧٤٥٢ - أم زفر ماشطة خديجة"],[41495,"س: أم زفر ماشطة خديجة وكانت عجوزا سوداء تغشى النبي صلى الله عليه وآله وسلم في زمان خديجة."],[41496,"روى عطاء بن أبي رباح، قال: قال لي ابن عباس: ألا أريك امرأة من أهل الجنة؟ قلت: بلى."],[41497,"قال: هذه المرأة السوداء، أتت رسول الله صلى الله عليه وآله وسلم فقالت: إني أصرع، وإني أنكشف فادع الله عز وجل قال: «إن شئت صبرت ولك الجنة، وإن شئت دعوت الله أن يعافيك»، فقالت: أصبر، قالت: فإني أنكشف، فادع الله أن لا أنكشف."],[41498,"فدعا لها."],[41499,"وروى ابن جريج، عن عطاء، أنه رأى أم زفر امرأة سوداء على سلم الكعبة."],[41500,"أخرجها كذا أبو موسى، وقال: يحتمل أن تكون أم زفر التي ذكروها."],[41501,"قلت: كذا ذكرها أبو موسى، وذكر حديث ابن عباس وابن جريج، وهذان الحديثان يدلان أنهما واحدة، والذي ذكره أبو موسى عن ابن جريج في هذه الترجمة، ذكره أبو عمر في الترجمة الأولى، وقوله في هذه: إنها العجوز التي كانت تغشى النبي صلى الله عليه وآله وسلم في حياة خديجة، يدل أنها غير الأولى، إلا أن يكون الصرع حدث بها، والله أعلم."],[41502,"٧٤٥٣ - أم زياد الأشجعية"],[41503,"د ع: أم زياد الأشجعية جدة حشرج."],[41504,"أخبرنا يحيى بن أبي الرجاء، إذنا، بإسناده عن ابن أبي عاصم، حدثنا أبو بكر بن أبي شيبة، عن زيد بن الحباب، عن رافع بن سلمة الأشجعي، عن حشرج بن زياد الأشجعي، عن جدته أم أبيه، أنها غزت مع النبي صلى الله عليه وآله وسلم يوم خيبر سادسة ست نسوة، فبلغ النبي صلى الله عليه وآله وسلم فبعث إلينا فقال: «بإذن من خرجتن؟» ورأينا فيه الغضب، فقلنا: خرجنا ومعنا دواء نداوي به الجرحى، ونناول السهام، ونسقي السويق، ونغزل الشعر، ونعين في سبيل الله، فقال لنا: «أقمن»."],[41505,"فلما فتح الله عليه خيبر قسم لنا كما قسم للرجال، فقلت: ما كان؟ قالت: تمرا."],[41506,"أخرجها ابن منده، وأبو نعيم"],[41507,"٧٤٥٤ - أم زيد بنت حرام"],[41508,"أم زيد بنت حرام بن عمرو صاحبة الجمل، وهي أنصارية من بني مالك."],[41509,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41510,"٧٤٥٥ - أم زيد بنت السكن"],[41511,"أم زيد بنت السكن بن عتبة بن عمرو بن خديج الأنصارية من بني جشم."],[41512,"بايعت رسول الله صلى الله عليه وآله وسلم قاله ابن حبيب."],[41513,"٧٤٥٦ - أم زيد"],[41514,"أم زيد."],[41515,"روى أسباط، عن السدي، قال: كانت امرأة من الأنصار يقال لها أم زيد اختصمت مع زوجها، وأرادت أن تلحق بأهلها، فمنعها، فاقتتل زوجها وأهلها، فنزل قوله تعالى: ﴿وَإِنْ طَائِفَتَانِ مِنَ الْمُؤْمِنِينَ اقْتَتَلُوا فَأَصْلِحُوا بَيْنَهُمَا﴾."],[41516,"الآية، لا أدري هي واحدة ممن قبلها، أم غيرها، لأنه لم يرفع في نسبها حتى تعرف، فذكرناها احتياطيا إلى أن تحقق."],[41517,"٧٤٥٧ - أم زينب بنت الفريعة"],[41518,"د ع: أم زينب واسمها حبيبة بنت الفريعة وهي أم زينب بنت نبيط بن جابر."],[41519,"روى عبد الله بن إدريس، عن محمد بن عمارة، عن زينب بنت نبيط بن جابر، قالت: «أوصى أبو أمامة بأمي وخالتي إلى النبي صلى الله عليه وآله وسلم فأتاه حلي من ذهب ولؤلؤ، يقال له: الرعاث، قالت: فحلاهن من الرعاث»."],[41520,"وقد ذكرت في حبيبة."],[41521,"أخرجها ابن منده، وأبو نعيم."],[41522,"٧٤٥٨ - أم زينب"],[41523,"د ع: أم زينب دعا لها النبي صلى الله عليه وآله وسلم روى عطاء بن خالد، عن أبيه، خالد بن الزبير، عن أبيه الزبير بن عبد الله، عن أبيه عبد الله بن رديح بن ذؤيب، عن أبيه ذؤيب، أن وفدا للنبي صلى الله عليه وآله وسلم مروا بأم زينب، فأخذوا زربيتها، فلحق ابن زينب بالنبي صلى الله عليه وآله وسلم فقال: يا رسول الله، أخذ الوفد زربية أمي، فقال النبي صلى الله عليه وآله وسلم: «ردوا عليه زربية أمه»."],[41524,"فأخذ منهم زربية أمه، ثم رفع النبي صلى الله عليه وآله وسلم يده، وقال: «بارك الله فيك يا غلام، وبارك لأمك فيك»."],[41525,"أخرجها ابن منده، وأبو نعيم."],[41526,"حرف السين"],[41527,"٧٤٥٩ - أم سالم الأشجعية"],[41528,"د ع: أم سالم الأشجعية ذكرها أبو بكر بن أبي عاصم في الصحابيات."],[41529,"أخبرنا أبو موسى، كتابة، أخبرنا الحسن بن أحمد، أخبرنا أحمد بن عبد الله وعبد الرحمن بن محمد، قالا: أخبرنا عبد الله بن محمد بن فورك، أخبرنا أبو بكر بن أبي عاصم، حدثنا عقبة بن مكرم، حدثنا عبد الرحمن بن مهدي، عن سفيان، عن حبيب بن أبي ثابت، عن رجل، عن أم سالم الأشجعية، أن رسول الله صلى الله عليه وآله وسلم أتاها وهي في قبة، فقال: «ما أحسنها إن لم تكن ميتة»، قال: فجعلت أتتبعها."],[41530,"أخرجها ابن منده، وأبو نعيم"],[41531,"٧٤٦٠ - أم سارة"],[41532,"دع: أم سارة وقيل سارة مولاة لقريش."],[41533,"ذكرها في حديث أنس."],[41534,"روى قتادة، عن أنس، أن أم سارة كانت مولاة لقريش، فأتت النبي صلى الله عليه وآله وسلم فشكت إليه الحاجة، ثم إن رجلا بعث معها بكتاب إلى أهل مكة لتحفظ عياله، فنزلت: ﴿يَأَيُّهَا الَّذِينَ آمَنُوا لا تَتَّخِذُوا عَدُوِّي وَعَدُوَّكُمْ أَوْلِيَاءَ﴾."],[41535,"أخرجها ابن منده، وأبو نعيم، وقال أبو نعيم: لا أعلم أحدا ذكرها في الصحابة ونسبها إلى الإسلام، غير المتأخر يعني: ابن منده."],[41536,"قلت: هذه القصة هي قصة حاطب بن أبي بلتعة، لما أرسل إلى أهل مكة يعلمهم بمسير النبي صلى الله عليه وآله وسلم إليهم، فأرسل عليا والزبير إلى روضة خاخ، فأخذا الكتاب منها."],[41537,"٧٤٦١ - أم السائب الأنصارية"],[41538,"ب د ع: أم السائب الأنصارية وقيل أم المسيب"],[41539,"أخبرنا أبو الفضل بن أبي الحسن المخزومي، بإسناده عن أبي يعلى، قال: حدثنا القواريري، حدثنا يزيد بن زريع، حدثنا حجاج الصواف، عن أبي الزبير، عن جابر، أن رسول الله صلى الله عليه وآله وسلم دخل على أم السائب أو: أم المسيب وهي ترفرف، فقال: «ما لك يا أم السائب» أو: «يا أم المسيب ترفرفين؟» قالت: الحمى، لا بارك الله فيها! فقال: «لا تسبي الحمى، فإنها تذهب خطايا ابن آدم، كما يذهب الكير خبث الحديد»."],[41540,"أخرجها الثلاثة"],[41541,"٧٤٦٢ - أم السائب النخعية"],[41542,"ب: أم السائب النخعية لها صحبة، أخرجها أبو عمر مختصرا."],[41543,"٧٤٦٣ - أم سبرة"],[41544,"س: أم سبرة في إسناد حديثها نظر."],[41545,"روى محمد بن إسحاق الثقفي، عن قتيبة، عن رشدين، عن أبي بكر الأنصاري، عن سبرة، عن أمه أنها سمعت رسول الله صلى الله عليه وآله وسلم يقول: «لا صلاة لمن لا وضوء له، ولا وضوء لمن لم يذكر الله عز وجل: ولا يؤمن بي من لا يحب الأنصار»."],[41546,"أخرجها أبو موسى."],[41547,"٧٤٦٤ - أم سعد الأنصارية"],[41548,"ب: أم سعد الأنصارية وهي كبشة بنت رافع بن عبيد بن ثعلبة أم سعد بن معاذ، وقد ذكرناها في كبشة."],[41549,"أخرجها أبو عمر."],[41550,"٧٤٦٥ - أم سعد بنت الربيع"],[41551,"د ع: أم سعد بنت الربيع الأنصارية تقدم نسبها عند ذكر ابنها، توفيت بعد سعد، وهي أخت أم خارجة امرأة زيد بن ثابت، لها ذكر ولا تعرف لها رواية."],[41552,"أخرجها ابن منده، وأبو نعيم."],[41553,"٧٤٦٦ - أم سعد بنت زيد"],[41554,"ب د ع: أم سعد بنت زيد بن ثابت الأنصارية وقيل: امرأة زيد بن ثابت."],[41555,"روى حديثها محمد بن زاذان، وقيل: لم يسمع منها، بينهما عبد الله بن خارجة."],[41556,"روى محمد بن عبد الله بن عمار الموصلي، عن عثمان بن عبد الرحمن، عن عنبسة الكوفي، عن محمد بن زاذان، عن أم سعد بنت زيد بن ثابت، قالت: سمعت رسول الله صلى الله عليه وآله وسلم «يأمر بدفن الدم إذا احتجم»."],[41557,"ومن حديثها، أن النبي صلى الله عليه وآله وسلم «كان إذا سافر لم تفارقه المرآة والمكحلة، يكونان معه»."],[41558,"وروى عنها محمد، أن النبي صلى الله عليه وآله وسلم قال: «الوضوء مد، والغسل صاع»."],[41559,"أخرجها الثلاثة."],[41560,"٧٤٦٧ - أم سعد بنت سعد بن الربيع"],[41561,"ع س: أم سعد بنت سعد بن الربيع بن عمرو بن أبي زهير من بني الحارث بن الخزرج تقدم نسبها عند ذكر أبيها فرق أبو نعيم بينها وبين أم سعد بنت الربيع التي تقدم ذكرها."],[41562,"أخبرنا أبو موسى، إذنا، أخبرنا أبو علي، أخبرنا أبو نعيم."],[41563,"ح قال أبو موسى: وأخبرنا حبيب بن محمد بن أحمد، حدثنا أحمد بن محمد بن النعمان، قالا: حدثنا محمد بن إبراهيم بن علي، حدثنا الحسين بن محمد بن حماد، حدثنا عمرو بن هشام الحراني، حدثنا محمد بن سلمة، عن ابن إسحاق، عن داود بن الحصين، قال: «كنت أقرأ على أم سعد بن الربيع مع ابن ابنها موسى بن سعد، وكانت يتيمة في حجر أبي بكر فقرأت عليها: ﴿وَالَّذِينَ عَقَدَتْ أَيْمَانُكُمْ﴾، فقالت: لا، ولكن: ﴿وَالَّذِينَ عَقَدَتْ أَيْمَانُكُمْ﴾ إنما نزلت في أبي بكر، وعبد الرحمن بن أبي بكر، حين أبى أن يسلم، فحلف أبو بكر أن لا يورثه، فلما أسلم أمره الله تعالى أن يورثه»."],[41564,"أخرجها أبو نعيم، وأبو موسى"],[41565,"٧٤٦٨ - أم سعد، أم أبي سعيد الخدري"],[41566,"د ع: أم سعد وهي أم أبي سعيد الخدري روى عنها ابنها أبو سعيد."],[41567,"روى قتيبة، عن ابن أبي الرجال، عن عمارة بن غزية، عن عبد الرحمن، عن أبيه، قال: سرحتني أمي إلى النبي صلى الله عليه وآله وسلم فأتيته، فقال: «من استغني أغناه الله»."],[41568,"أخرجها ابن منده، وأبو نعيم."],[41569,"٧٤٦٩ - أم سعد بن عبادة"],[41570,"د ع."],[41571,"أم سعد بن عبادة توفيت على عهد رسول الله صلى الله عليه وآله وسلم روى الزهري، عن عبيد الله بن عبد الله، عن ابن عباس، أن سعدا سأل النبي صلى الله عليه وآله وسلم فقال: إن أمي ماتت وعليها نذر لم تقضه؟ فقال: «اقضه عنها»."],[41572,"أخبرنا فتيان، بإسناده عن القعنبي، عن مالك، عن سعيد بن عمرو بن شرحبيل بن سعيد بن سعد بن عبادة، عن أبيه، عن جده قال: خرج سعد بن عبادة مع النبي صلى الله عليه وآله وسلم في بعض مغازيه، فحضرت أمه الوفاة بالمدينة، فقيل لها: أوصي، فقالت: فيم أوصي؟ المال مال سعد."],[41573,"فتوفيت قبل أن يقدم سعد."],[41574,"فلما قدم ذكر ذلك له، فقال سعد: يا رسول الله، «هل ينفعها أن أتصدق عنها؟ فقال النبي صلى الله عليه وآله وسلم: نعم»، فقال سعد: حائط كذا وكذا صدقة."],[41575,"لحائط سماه"],[41576,"أخبرنا غير واحد، بإسنادهم عن محمد بن عيسى، حدثنا محمد بن بشار، عن يحيى بن سعيد، عن سعيد بن أبي عروبة، عن قتادة، عن ابن المسيب، «أن أم سعد ماتت والنبي غائب، فلما قدم صلى عليها وقد مضى لذلك شهر»."],[41577,"أخرجها ابن منده، وأبو نعيم"],[41578,"٧٤٧٠ - أم سعد بنت مرة"],[41579,"ب د ع: أم سعد بنت مرة بن عمرو الجمحية قاله أبو نعيم."],[41580,"وقال ابن منده: سعد بن عمرو أصح، وقال أبو عمر: أم سعيد بنت عمرو الجمحية."],[41581,"قال: وقيل: بنت عمير."],[41582,"واتفقوا كلهم أن حديثها كافل اليتيم."],[41583,"روى يزيد بن زريع، عن محمد بن عمرو، عن صفوان بن سليم، عن أم سعد بنت مرة بن عمرو الجمحية، قالت: قال رسول الله صلى الله عليه وآله وسلم: «من كفل يتيما له أو لغيره، كنت أنا وهو في الجنة كهاتين»، يعني أصبعيه السبابة والوسطي."],[41584,"ورواه محمد بن بشر، عن محمد بن عمرو، عن صفوان، عن أم سعد بنت عمرو بن مرة."],[41585,"ورواه ابن عيينة، عن صفوان، عن أم سعد بنت مرة الزهرية."],[41586,"أخرجه الثلاثة."],[41587,"٧٤٧١ - أم سفيان بن الضحاك"],[41588,"د ع س: أم سفيان بن الضحاك ذكرت في الصحابة ولا يثبت، ذكرها الطبراني وجعفر المستغفري فيهم."],[41589,"أخبرنا عبد الوهاب بن هبة الله، بإسناده عن عبد الله، حدثني هدبة بن خالد، أخبرنا حماد بن سلمة، عن يعلى بن عطاء، عن موسى بن عبد الرحمن، عن أم سفيان، أن يهودية كانت تدخل على عائشة فتتحدث، فإذا قامت، قالت: أعاذك الله من عذاب القبر."],[41590,"فلما جاء رسول الله صلى الله عليه وآله وسلم أخبرته بذلك، فقال: «كذبت، إنما ذاك لأهل الكتاب». فكسفت الشمس، فقال: «أعوذ بالله من عذاب القبر»."],[41591,"أخرجه ابن منده، وأبو نعيم، وقد أخرجه أبو موسى مستدركا على ابن منده، وقد أخرجه ابن منده فلا وجه لاستدراكه عليه"],[41592,"٧٤٧٢ - أم سلمة بنت أبي أمية"],[41593,"ب د ع: أم سلمة بنت أبي أمية بن المغيرة بن عبد الله بن عمر بن مخزوم القرشية المخزومية زوج النبي صلى الله عليه وآله وسلم واسمها: هند."],[41594,"وكان أبوها يعرف بزاد الركب."],[41595,"وكانت قبل النبي صلى الله عليه وآله وسلم عند أبي سلمة بن عبد الأسد المخزومي، فولدت له: سلمة، وعمر، ودرة، وزينب."],[41596,"وتوفي فخلف عليها رسول الله صلى الله عليه وآله وسلم بعده."],[41597,"وكانت من المهاجرات إلى الحبشة وإلى المدينة."],[41598,"أخبرنا أبو جعفر، بإسناده عن يونس، عن إسحاق، قال: حدثني والدي إسحاق بن يسار، عن سلمة بن عبد الله بن عمر بن أبي سلمة، عن جدته أم سلمة، قالت: «لما أجمع أبو سلمة الخروج إلى المدينة، رحل بعيرا له وحملني، وحمل معي ابني سلمة، ثم خرج يقود بعيره."],[41599,"فلما رآه رجال بني المغيرة بن عبد الله بن عمر بن مخزوم قاموا إليه فقالوا: هذه نفسك غلبتنا عليها، أرأيت صاحبتنا هذه؟ علام تترك تسير بها في البلاد؟ ونزعوا خطام البعير من يده، وأخذوني."],[41600,"وغضبت عند ذلك بنو عبد الأسد، وأهووا إلى سلمة وقالوا:"],[41601,"والله لا نترك ابننا عندها إذ نزعتموها من صاحبنا."],[41602,"فتجاذبوا ابني سلمة حتى خلعوا يده، وانطلق به بنو عبد الأسد رهط أبي سلمة، وحبسني بنو المغيرة عندهم."],[41603,"وانطلق زوجي أبو سلمة حتى لحق بالمدينة، ففرق بيني وبين زوجي وبين ابني."],[41604,"قالت: فكنت أخرج كل غداة فأجلس بالأبطح، فما أزال أبكي، حتي أمسي سنة أو قريبها."],[41605,"حتى مر بي رجل من بني عمي، من بني المغيرة، فرأى ما بي، فرحمني فقال لبني المغيرة: ألا تخرجون من هذه المسكينة؟ فرقتم بينها وبين زوجها وبين ابنها، فقالوا لي: الحقي بزوجك إن شئت."],[41606,"ورد علي بنو عبد الأسد عند ذلك ابني، فرحلت بعيري ووضعت ابني في حجري، ثم خرجت أريد زوجي بالمدينة، وما معي أحد من خلق الله، فقلت: أتبلغ بمن لقيت حتى أقدم على زوجي."],[41607,"حتى إذا كنت بالتنعيم لقيت عثمان بن طلحة بن أبي طلحة أخا بني عبد الدار فقال: أين يا بنت أبي أمية؟ قالت: أريد زوجي بالمدينة، فقال: هل معك أحد؟ فقلت: لا والله، إلا الله وابني هذا، فقال: والله ما لك من مترك."],[41608,"فأخذ بخطام البعير فانطلق معي يقودني، فوالله ما صحبت رجلا من العرب أراه كان أكرم منه، إذ بلغ المنزل أناخ بي ثم تنحى إلى شجرة اضطجع تحتها، فإذا دنا الرواح قام إلى بعير فقدمه فرحله، ثم استأخر عني، وقال: اركبي."],[41609,"فإذا ركبت واستويت على بعيري أتى فأخذ بخطامه، فقادني حتى ننزل."],[41610,"فلم يزل يصنع ذلك حتى قدم بي إلى المدينة، فلما نظر إلى قرية بني عمرو بن عوف بقباء، قال: زوجك في هذه القرية وكان أبو سلمة نازلا بها فدخلتها على بركة الله تعالى، ثم انصرف راجعا إلى مكة."],[41611,"وكانت تقول: ما أعلم أهل بيت أصابهم في الإسلام ما أصاب آل أبي سلمة، وما رأيت صاحبا قط كان أكرم من عثمان بن طلحة، وقيل: إنها أول ظعينة هاجرت إلى المدينة، والله أعلم، وتزوجها رسول الله صلى الله عليه وآله وسلم بعد أبي سلمة»"],[41612,"أخبرنا يعيش بن صدقة الفقيه، بإسناده عن أحمد بن شعيب: أخبرنا محمد بن إسماعيل بن إبراهيم، حدثنا يزيد، عن حماد بن سلمة، عن ثابت البناني، حدثني ابن عمر بن أبي سلمة، عن أبيه، عن أم سلمة، قالت: لما انقضت عدتها بعث إليها أبو بكر يخطبها عليه فلم تزوجه."],[41613,"فبعث إليها رسول الله صلى الله عليه وآله وسلم عمر بن الخطاب يخطبها عليه."],[41614,"فقلت: أخبر رسول الله صلى الله عليه وآله وسلم أني امرأة غيرى، وأني امرأة مصبية، وليس أحد من أوليائي شاهد."],[41615,"فأتى رسول الله صلى الله عليه وآله وسلم فذكر ذلك له، فقال: «ارجع إليها فقل لها: أما قولك إني امرأة غيرى فسأدعو الله فيذهب غيرتك، وأما قولك إني امرأة مصبية فستكفين صبيانك، وأما قولك ليس أحد من أوليائي شاهد فليس أحد من أوليائك شاهد ولا غائب يكره ذلك»، فقالت لابنها عمر: قم فزوج رسول الله صلى الله عليه وآله وسلم فزوجه."],[41616,"مختصرا"],[41617,"أخبرنا أرسلان بن يغان أبو محمد الصوفي، أخبرنا أبو الفضل بن طاهر بن سعيد بن أبي سعيد الميهني الصوفي، أخبرنا أبو بكر أحمد بن علي ابن خلف، أخبرنا الحاكم أبو عبد الله محمد بن عبد الله، أخبرنا أبو العباس محمد بن يعقوب الأصم، حدثنا الحسن بن مكرم، حدثنا عثمان بن عمر، حدثنا عبد الرحمن بن عبد الله بن دينار، عن شريك بن أبي نمر، عن عطاء بن يسار، عن أم سلمة، قالت: في بيتي نزلت ﴿إِنَّمَا يُرِيدُ اللَّهُ لِيُذْهِبَ عَنْكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ﴾، قالت: فأرسل رسول الله صلى الله عليه وآله وسلم إلى فاطمة، وعلي، والحسن، والحسين، فقال: «هؤلاء أهل بيتي»، قالت: فقلت: يا رسول الله، أنا من أهل البيت؟ قال: «بلى، إن شاء الله»."],[41618,"أخرجها الثلاثة"],[41619,"٧٤٧٣ - أم سلمة بنت أبي حكيم"],[41620,"ب د ع: أم سلمة بنت أبي حكيم وقيل أم سليم وقيل أم سليمان لا يوقف على اسمها."],[41621,"حديثها أنها أدركت القواعد من النساء تصلين مع النبي صلى الله عليه وآله وسلم الفرائض."],[41622,"أخرجها الثلاثة."],[41623,"٧٤٧٤ - أم سلمة بنت يزيد بن السكن"],[41624,"س: أم سلمة بنت يزيد بن السكن واسمها أسماء"],[41625,"أخبرنا إبراهيم بن محمد، وغيره، بإسنادهم عن أبي عيسى، حدثنا عبد بن حميد، عن أبي نعيم هو الفضل بن دكين عن يزيد بن عبد الله الشيباني، قال: سمعت شهر بن حوشب، عن أم سلمة الأنصارية، قالت: قالت امرأة من النسوة: ما هذا المعروف الذي لا ينبغي لنا أن نعصيك فيه؟ قال: «لا تنحن»."],[41626,"قلت: يا نبي الله، إن بني فلان قد أسعدوني على عمي، ولا بد لي من قضائهن."],[41627,"فأبي علي، فعاتبته مرارا، فأذن لي في قضائهن، فلم أنح بعد قضائهن ولا على غيره حتى الساعة، ولم تبق امرأة إلا قد ناحت غيري."],[41628,"أخرجها أبو موسى، وقال: قال أبو عيسى: قال عبد بن حميد: أم سلمة هي أسماء بنت يزيد بن السكن"],[41629,"٧٤٧٥ - أم سلمى بنت أبي أمية"],[41630,"س: أم سلمى بنت أبي أمية"],[41631,"أخبرنا أبو موسى، إذنا، أخبرنا أبو سعد محمد بن علي الكاتب المعروف بالسرفتح وأبو علي الحسن بن أحمد، قالا: أخبرنا أبو منصور عبد الرزاق بن أحمد، حدثنا عبد الله بن محمد أبو الشيخ، حدثنا زكريا الساجي، حدثنا محمد بن الحارث بن مدلج المخزومي، عن عمرو بن عثمان بن سهل بن أبي حثمة، قال: سمعت أم سلمى ابنة أبي أمية، قالت: تزوج رسول الله صلى الله عليه وآله وسلم في شوال، وبني في شوال."],[41632,"كذا أورده أبو الشيخ في كتاب النكاح، وعمرو بن عثمان هذا قيل: يروى عن أبي بكر ابن سليمان بن أبي حثمة، ولعل أم سلمى ترويه عن عائشة، والله أعلم."],[41633,"أخرجها أبو موسى"],[41634,"٧٤٧٦ - أم سلمى"],[41635,"ع س: أم سلمى ذكرها الإمام أحمد بن حنبل في مسنده."],[41636,"قال أبو نعيم: وهي فيما أرى امرأة أبي رافع."],[41637,"أخبرنا أبو ياسر، بإسناده عن عبد الله بن أحمد، حدثني أبي، حدثنا أبو النضر، حدثنا إبراهيم بن سعد، عن محمد بن إسحاق، عن عبد الله بن علي بن أبي رافع، عن أبيه، عن أم سلمى، قالت: اشتكت فاطمة شكواها التي قبضت فيها، فكنت أمرضها، فأصبحت يوما كأمثل ما رأيتها في شكواها تلك، قالت: وخرج علي لبعض حاجته، فقالت: يا أمه، اسكبي لي غسلا."],[41638,"فسكبت لها غسلا، فاغتسلت كأحسن ما رأيتها تغتسل، ثم قالت: يا أمة، أعطيني ثيابي الجدد."],[41639,"فأعطيتها فلبستها، ثم قالت لي: يا أمه، اجعلي لي فراشي في وسط البيت."],[41640,"ففعلت، فاضطجعت واستقبلت القبلة، وجعلت يدها تحت خدها، ثم قالت: يا أمه، إني مقبوضة الآن، قد تطهرت الآن، فلا يكشفني أحد."],[41641,"فقبضت مكانها، قالت: فجاء علي فأخبرته."],[41642,"أخرجها أبو نعيم، وأبو موسى"],[41643,"٧٤٧٧ - أم سليط"],[41644,"ب: أم سليط امرأة من المبايعات."],[41645,"حضرت مع النبي صلى الله عليه وآله وسلم. قال عمر بن الخطاب: كانت تزفر لنا القرب يوم أحد."],[41646,"أخرجها أبو عمر."],[41647,"٧٤٧٨ - أم سليم بنت سحيم"],[41648,"ب: أم سليم بنت سحيم هي أمة أو أمية بنت أبي الحكم الغفارية."],[41649,"تقدم ذكرها في حرف الهمزة."],[41650,"أخرجها أبو عمر."],[41651,"٧٤٧٩ - أم سليم بنت ملحان"],[41652,"ب د ع: أم سليم بنت ملحان بن خالد بن زيد بن حرام بن جندب بن عامر بن غنم بن عدي بن النجار الأنصارية الخزرجية النجارية أم أنس بن مالك."],[41653,"اختلف في اسمها فقيل: سهلة، وقيل: رميلة، وقيل: رميثة، وقيل: مليكة، والغميصاء، والرميصاء."],[41654,"كانت تحت مالك بن النضر والد أنس بن مالك في الجاهلية، غضب عليها وخرج إلى الشام، ومات هناك."],[41655,"فخطبها أبو طلحة الأنصاري وهو مشرك، فقالت: أما إني فيك لراغبة، وما مثلك يرد، ولكنك كافر، وأنا امرأة مسلمة، فإن تسلم فلك مهري، ولا أسألك غيره."],[41656,"فأسلم."],[41657,"وتزوجها وحسن إسلامه، فولدت له غلاما مات صغيرا، وهو أبو عمير، وكان معجبا به، فأسف عليه، ثم ولدت له عبد الله بن أبي طلحة، وهو والد إسحاق، فبارك الله في إسحاق وإخوته، وكانوا عشرة، كلهم حمل عنه العلم."],[41658,"أخبرنا عمر بن محمد بن طبرزد، وغيره، قالوا: أخبرنا أبو القاسم هبة الله بن محمد بن عبد الواحد بن الحصين، أخبرنا أبو طالب محمد بن محمد بن غيلان، أخبرنا أبو بكر محمد بن عبد الله بن إبراهيم، حدثنا أبو جعفر محمد بن مسلمة الواسطي، حدثنا يزيد بن هارون، حدثنا حماد بن سلمة، عن ثابت وإسماعيل بن عبد الله بن أبي طلحة، عن أنس، «أن أبا طلحة خطب أم سليم فقالت: يا أبا طلحة، ألست تعلم أن إلهك الذي تعبد ينبت من الأرض، ينجرها حبشي بني فلان؟ قال: بلى."],[41659,"قالت: أفلا تستحيي تعبد خشبة؟! إن أنت أسلمت فإني لا أريد منك الصداق غيره."],[41660,"قال: حتى أنظر في أمري."],[41661,"فذهب ثم جاء فقال: أشهد أن لا إله إلا الله وأن محمدا رسول الله، فقالت: يا أنس، زوج أبا طلحة."],[41662,"فتزوجها» وكانت تغزو مع رسول الله صلى الله عليه وآله وسلم وروت عنه أحاديث، وروى عنها ابنها أنس."],[41663,"أخبرنا غير واحد، بإسنادهم عن محمد بن عيسى، حدثنا محمد بن بشار، حدثنا محمد بن جعفر، حدثنا شعبة، قال: سمعت قتادة يحدث عن أنس، عن أم سليم، أنها قالت: يا رسول الله أنس خادمك، ادعوا الله له."],[41664,"قال: «اللهم، أكثر ماله وولده، وبارك له فيما أعطيته» وكانت من عقلاء النساء."],[41665,"أخرجها الثلاثة."],[41666,"٧٤٨٠ - أم سليمان بنت أبي حكيم"],[41667,"ب د ع: أم سليمان وقيل أم سلمة وقيل أم سليم بنت أبي حكيم العدوية وهي أم سليمان بن أبي حثمة."],[41668,"روى عنها عبد الله بن الطيب، أنها قالت: أدركت القواعد من النساء وهن يصلين مع رسول الله صلى الله عليه وآله وسلم الفرائض."],[41669,"أخرجها الثلاثة."],[41670,"وتقدم ذكرها في أم سلمة."],[41671,"٧٤٨١ - أم سليمان بن عمرو"],[41672,"ب: أم سليمان بن عمرو بن الأحوص روى عنها ابنها سليمان."],[41673,"أخبرنا يحيى، بإسناده عن أبي بكر بن أبي عاصم، حدثنا أبو بكر بن أبي شيبة، حدثنا علي بن مسهر، عن يزيد بن أبي زياد، عن سليمان بن عمرو بن الأحوص، عن أمه، أنها قالت: رأيت رسول الله صلى الله عليه وآله وسلم عند جمرة العقبة وهو راكب بغلة، ورجل خلفه يستره من الناس، فسألت عن الرجل، فقيل لي: هذا الفضل بن عباس."],[41674,"فازدحم الناس عليه، فقال: «أيها الناس لا يقتل بعضكم بعضا، وإذا رميتم الجمرة فارموها بمثل حصى الخذف»."],[41675,"واستبطن الوادي ورمى الجمرة بسبع حصيات، يكبر مع كل حصاة، وانصرف."],[41676,"اختلفوا في هذا الحديث، فمنهم من يجعله لجدة سليمان بن عمرو بن الأحوص، ومنهم من يجعله لأمه، ومنهم من يقول: عن سليمان، عن أبيه."],[41677,"وقيل فيها: أم جندب."],[41678,"ويرد ذكرها إن شاء الله تعالى."],[41679,"أخرجها أبو عمر"],[41680,"٧٤٨٢ - أم سمرة بن جندب"],[41681,"د ع: أم سمرة بن جندب لها ذكر في حديث عبد الحميد بن جعفر، عن أبيه، أن أم سمرة بن جندب مات عنها زوجها وترك ابنه سمرة، وكانت امرأة جميلة، فقدمت المدينة فخطبت، فكانت تقول: لا أتزوج إلا برجل يقوم بنفقة ابنها سمرة حتى يبلغ."],[41682,"فتزوجها رجل من الأنصار على ذلك، فكانت معه في الدار."],[41683,"وكان النبي صلى الله عليه وآله وسلم يعرض غلمان الأنصار في كل عام من بلغ منهم بعثه."],[41684,"أخرجها ابن منده، وأبو نعيم."],[41685,"٧٤٨٣ - أم سنان الأسلمية"],[41686,"ب د ع: أم سنان الأسلمية روى عنها ابن عباس، وابنتها ثبيتة بنت حنظلة."],[41687,"روى أبو سنان يزيد بن حريث، عن ثبيتة بنت حنظلة، عن أمها أم سنان الأسلمية، وكانت من المبايعات، قالت: جئت النبي صلى الله عليه وآله وسلم فقلت: يا رسول الله، إني جئتك على حياء، وما جئت حتى ألجئت من الحاجة، فقال: «لو استغنيت لكان خيرا لك»."],[41688,"ومن حديثها، أنها قالت: أتيت رسول الله صلى الله عليه وآله وسلم فبايعته على الإسلام، فنظر إلى يدي فقال: «ما على إحداكن أن تغير أظفارها»."],[41689,"أخرجها الثلاثة."],[41690,"ثبيتة: بالثاء المثلثة المضمومة، والباء الموحدة المفتوحة، والياء تحتها نقطتان، والتاء فوقها نقطتان."],[41691,"٧٤٨٤ - أم سنان الأنصارية"],[41692,"ب س: أم سنان الأنصارية"],[41693,"أخبرنا أبو موسى، إجازة، أخبرنا الحسن بن أحمد، أخبرنا أحمد بن عبد الله، حدثنا علي بن هارون، حدثنا يوسف القاضي، حدثنا محمد بن أبي بكر، حدثنا يزيد بن زريع، حدثنا حبيب المعلم، عن عطاء، عن ابن عباس، أن النبي صلى الله عليه وآله وسلم لما رجع من حجة الوداع لقي امرأة من الأنصار، يقال لها أم سنان، فقال: «عمرة في رمضان تقضي حجة»، أو «حجة معي»."],[41694,"أخرجها أبو عمر، وأبو موسى"],[41695,"٧٤٨٥ - أم سنبلة الأسلمية"],[41696,"ب د ع: أم سنبلة الأسلمية تعد في أهل المدينة."],[41697,"روى زيد بن الحباب، عن عمرو بن قيظي بن شداد بن أسيد المدني، عن سليمان، وزرعة، ومحمد ابني الحصين بن سياه بن سوار، عن أم سنبلة، وهي جدتهم، قالت: أتيت النبي صلى الله عليه وآله وسلم بهدية، فأبى نساء النبي صلى الله عليه وآله وسلم أن يأخذنها وقلن: إنا لا نأخذ هدية."],[41698,"فجاء رسول الله صلى الله عليه وآله وسلم فقال: «خذوا هدية أم سنبلة، فهي أهل باديتنا، ونحن أهل حاضرتها»."],[41699,"وأعطاها وادي كذا وكذا، فاشتراه عبد الله بن حسن بن حسن بن علي بن أبي طالب منهم، وأعطاهم ذودا."],[41700,"قال عمرو بن قيظي: فرأيت بعضا."],[41701,"وقد روى سليمان بن بلال، وعبد العزيز بن أبي حازم، وغيرهما، عن عبد الرحمن بن حرملة، عن عبد الله بن نيار بن مكرم الأسلمي، عن عروة، عن عائشة، قالت: «أهدت أم سنبلة لرسول الله صلى الله عليه وآله وسلم» وذكر نحوه."],[41702,"أخرجه الثلاثة."],[41703,"٧٤٨٦ - أم سوادة"],[41704,"أم سوادة بن الربيع روى عبد الله بن يزيد الخثعمي، عن مسلم بن عبد الرحمن، عن سوادة بن الربيع، قال: أتيت النبي صلى الله عليه وآله وسلم بأمي، فأمر لها بشياه من غنم، وقال لها: «مري بنيك أن يقلموا أظفارهم، أن يوجعوا ضروع الغنم»."],[41705,"ذكرها ابن الدباغ، عن الغساني، مستدركا على أبي عمر."],[41706,"٧٤٨٧ - أم سهلة"],[41707,"أم سهلة زوج عاصم بن عدي ولدت سهلة بخيبر."],[41708,"قاله الواقدي."],[41709,"ذكرها ابن الدباغ أيضا."],[41710,"٧٤٨٨ - أم سيف"],[41711,"ب د ع: أم سيف ظئر إبراهيم ابن النبي صلى الله عليه وآله وسلم ذكرها في حديث أنس."],[41712,"روى عاصم بن علي، عن سليمان بن المغيرة، عن ثابت، عن أنس، قال: قال رسول الله صلى الله عليه وآله وسلم: «ولد لي الليلة غلام فسميته باسم أبي إبراهيم»."],[41713,"قال: فدفعه إلى أم سيف امرأة قين يقال له: أبو سيف، فانطلق رسول الله صلى الله عليه وآله وسلم يأتيه، فسبقته فأسرعت المشي بين يدي رسول الله صلى الله عليه وآله وسلم فانتهيت إلى أبي سيف وهو ينفخ بكيره."],[41714,"الحديث."],[41715,"وقد تقدم."],[41716,"أخرجها الثلاثة."],[41717,"حرف الشين"],[41718,"٧٤٨٩ - أم شباث"],[41719,"س: أم شباث وهي أم منيع ذكرت في ترجمة ابنها شباث."],[41720,"أخرجها أبو موسى مختصرا."],[41721,"٧٤٩٠ - أم شبيب"],[41722,"د ع: أم شبيب امرأة الضحاك بن سفيان الكلابي روى الزهري، أن الضحاك بن سفيان الكلابي، قال: يا رسول الله، هل لك في أخت أم شبيب امرأة الضحاك من بني أبي بكر بن كلاب."],[41723,"أخرجها ابن منده، وأبو نعيم مختصرين."],[41724,"٧٤٩١ - أم شرحبيل"],[41725,"أم شرحبيل بنت فروة بن عمرو الأنصارية البياضية بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41726,"٧٤٩٢ - أم الشريد"],[41727,"أم الشريد روى أبو داود السجستاني، عن موسى بن إسماعيل، عن حماد، عن محمد بن عمرو، عن أبي سلمة، عن الشريد، أن أمه أوصته أن يعتق عنها رقبة مؤمنة، قال: وعندي جارية سوداء نوبية، فقال رسول الله صلى الله عليه وآله وسلم: «ادعوا بها»."],[41728,"فدعوا بها، فقال لها رسول الله صلى الله عليه وآله وسلم: «من ربك؟» قالت: الله، قال: «فمن أنا؟» قالت: رسول الله صلى الله عليه وآله وسلم. قال: «أعتقها فإنها مؤمنة»."],[41729,"٧٤٩٣ - أم شريك بنت أنس"],[41730,"أم شريك آخره كاف هي بنت أنس بن رافع بن امرئ القيس بن زيد الأنصارية الأشهلية بايعت رسول الله صلى الله عليه وآله وسلم."],[41731,"قاله ابن حبيب."],[41732,"٧٤٩٤ - أم شريك بنت جابر"],[41733,"ب: أم شريك بنت جابر الغفارية ذكرها أحمد بن صالح المصري في أزواج النبي صلى الله عليه وآله وسلم. أخرجها أبو عمر مختصرا."],[41734,"وقال ابن حبيب: بايعت النبي صلى الله عليه وآله وسلم"],[41735,"٧٤٩٥ - أم شريك بنت خالد"],[41736,"أم شريك بنت خالد بن خنيس بن لوذان بن عبد ود بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41737,"٧٤٩٦ - أم شريك الدوسية"],[41738,"د ع: أم شريك الدوسية من المهاجرات."],[41739,"ذكرها ابن منده."],[41740,"وقال أبو نعيم: ذكرها المتأخر يعني: ابن منده وأفردها عن العامرية، قال: وهي عندي العامرية."],[41741,"وهي التي يأتي ذكرها."],[41742,"قال: وقيل: هي بنت جابر."],[41743,"أخبرنا أبو جعفر بن السمين، بإسناده عن يونس بن بكير، عن عبد الأعلى بن أبي المساور القرشي، عن محمد بن عمرو بن عطاء، عن أبي هريرة قال: «كانت امرأة من دوس يقال لها: أم شريك أسلمت في رمضان، فأقبلت تطلب من يصحبها إلى رسول الله صلى الله عليه وآله وسلم فلقيت رجلا من اليهود، فقال: ما لك يا أم شريك؟ قالت: أطلب من يصحبني إلى رسول الله صلى الله عليه وآله وسلم. قال: تعالي فأنا أصحبك» وذكر الحديث بطوله."],[41744,"ذكر ابن منده هذا الحديث، وذكره أبو نعيم أيضا، وذكر معه حديثا يرويه الكلبي، عن أبي صالح، عن ابن عباس، قال: وقع في قلب أم شريك الإسلام وهي بمكة، وهي إحدى نساء قريش، ثم إحدى بني عامر بن لؤي، وكانت تحت أبي العكر الدوسي، فأسلمت، ثم جعلت تدخل على نساء قريش فتدعوهن سرا وترغبهن في الإسلام، حتى ظهر أمرها بمكة، فأخذوها وسيروها إلى قومها."],[41745,"وذكر الحديث بطوله، وإنما أخرج هذا الحديث ليستدل به على أنها أم شريك العامرية ليست غيرها."],[41746,"وقد رواه ابن إسحاق مثل ابن منده، وترجم عليه إسلام أم شريك الدوسية والله أعلم."],[41747,"أخرجها ابن منده، وأبو نعيم، ولم يخرجها أبو عمر، وأرى إنما تركها لأنه ظنها العامرية"],[41748,"٧٤٩٧ - أم شريك القرشية"],[41749,"ب د ع: أم شريك القرشية العامرية من بني عامر بن لؤي، اسمها غزية وقيل: غزيلة بنت دودان بن عوف بن عمرو بن عامر بن رواحة بن حجير بن عبد بن معيص بن عامر بن لؤي."],[41750,"وقال ابن الكلبي في نسبها إلى رواحة، وقال: رواحة بن منقذ بن عمرو بن معيص بن عامر بن لؤي."],[41751,"وقيل في نسبها: أم شريك بنت عوف بن عمرو بن جابر بن ضباب بن حجير بن عبد بن معيص بن عامر بن لؤي."],[41752,"قيل: إنها التي وهبت نفسها للنبي صلى الله عليه وآله وسلم وقيل: إن التي وهبت نفسها غيرها."],[41753,"وقيل ذلك عن عدة من النساء ذكرناهن في مواضعهن من الكتاب، وذكرها بعضهم في أزواج النبي صلى الله عليه وآله وسلم ولا يصح من ذلك شيء، لكثرة الاضطراب فيه."],[41754,"وكانت عند أبي العكر بن سمي بن الحارث الأزدي، فولدت له شريكا، وقيل: إنها كانت عند الطفيل بن الحارث، فولدت له شريكا."],[41755,"والأول أصح، قاله أبو عمر، وقيل: أم شريك الأنصارية، تزوجها النبي صلى الله عليه وآله وسلم ولم يدخل بها، لأنه كره غيرة الأنصار."],[41756,"أخبرنا عبد الوهاب بن أبي حبة، بإسناده عن عبد الله بن أحمد، حدثني أبي، حدثنا روح، حدثنا ابن جريج، قال: أخبرني أبو الزبير، أنه سمع جابر بن عبد الله، يقول: أخبرتني أم شريك، أنها سمعت رسول الله صلى الله عليه وآله وسلم يقول: «ليفرن الناس من الدجال في الجبال»."],[41757,"قالت أم شريك: يا رسول الله، فأين العرب يومئذ؟ قال: «قليل» وروى عنها ابن المسيب، أن النبي صلى الله عليه وآله وسلم أمرها بقتل الأوزاغ."],[41758,"أخرجها الثلاثة."],[41759,"٧٤٩٨ - أم شيبة الأزدية"],[41760,"ب د ع: أم شيبة الأزدية المكية روى حديثها حماد بن سلمة، عن عبد الملك بن عمير."],[41761,"وهو حديث حسن في آداب المجالسة."],[41762,"أخرجها الثلاثة."],[41763,"حرف الصاد"],[41764,"٧٤٩٩ - أم صابر"],[41765,"د ع: أم صابر بنت نعيم بن مسعود الأشجعي أدركت النبي صلى الله عليه وآله وسلم. روت عن أبيها روى عنها إبراهيم بن صابر، عن أبيه عنها عن أبيها، أن النبي صلى الله عليه وآله وسلم قال: «الحرب خدعة»."],[41766,"أخرجها ابن منده، وأبو نعيم."],[41767,"٧٥٠٠ - أم صبيح"],[41768,"أم صبيح روى عنها ابنها صبيح بن سعيد النجاشي، أنها قالت: كان اسمي عنبة فسماني رسول الله صلى الله عليه وآله وسلم عنقودة."],[41769,"ذكره ابن ماكولا."],[41770,"عنبة: بالنون، والباء الموحدة."],[41771,"٧٥٠١ - أم صبية"],[41772,"ب د ع: أم صبية الجهنية اختلف في اسمها فقيل: خولة بنت قيس."],[41773,"قاله أبو عمر."],[41774,"وقيل غير ذلك."],[41775,"وهي جدة خارجة بن الحارث بن رافع بن مكيث."],[41776,"حديثها عند أهل المدينة."],[41777,"أخبرنا يحيى بن محمود، إذنا، بإسناده عن أبي بكر بن عمرو، قال: حدثنا أبو بكر بن أبي شيبة، عن أسامة بن زيد، عن أبي النعمان بن خربوذ، عن أم صبية الجهنية، أنها قالت: اختلفت يدي ويد رسول الله صلى الله عليه وآله وسلم في إناء واحد من الوضوء."],[41778,"أخرجها الثلاثة وقد ذكر أحمد بن حنبل في مسنده ترجمة خولة بنت قيس امرأة حمزة، وروى لها: «الدنيا خضرة حلوة»."],[41779,"وذكر ترجمة أم صبية الجهنية ترجمة أخرى، وروى لها حديث الوضوء، على أنه يذكر الواحد في ترجمتين وثلاثة وأكثر، والله أعلم."],[41780,"حرف الضاد"],[41781,"٧٥٠٢ - أم الضحاك بنت مسعود"],[41782,"ب د ع: أم الضحاك بنت مسعود الأنصارية الحارثية شهدت خيبر مع النبي صلى الله عليه وآله وسلم فأسهم لها سهم رجل."],[41783,"روى حديثها حرام بن محيصة، وسهل بن أبي حثمة."],[41784,"وروى الزهري، عن حرام بن محيصة، عن أم الضحاك بن مسعود الحارثية، قالت: قال رسول الله صلى الله عليه وآله وسلم: «لا تحقرن جارة لجارتها ولو فرسن شاة»."],[41785,"أخرجها الثلاثة."],[41786,"٧٥٠٣ - أم ضميرة"],[41787,"ع: أم ضميرة مولاة رسول الله صلى الله عليه وآله وسلم"],[41788,"روى أبو وهب، عن ابن أبي ذئب، عن حسين بن عبد الله بن ضميرة، عن أبيه، عن جده، أن رسول الله صلى الله عليه وآله وسلم مر بأم ضميرة وهي تبكي، فقال: «ما يبكيك؟» قالت: فرق بيني وبين أمي، فقال رسول الله صلى الله عليه وآله وسلم: «لا يفرق بين الوالدة وولدها»."],[41789,"أخرجها ابن منده، وأبو نعيم."],[41790,"حرف الطاء"],[41791,"٧٥٠٤ - أم طارق مولاة سعد بن عبادة"],[41792,"أم طارق، مولاة سعد بن عبادة"],[41793,"أخبرنا أبو الفرج بن أبي الرجاء، بإسناده عن أبي بكر بن أبي عاصم، قال: حدثنا المسيب بن واضح، حدثنا أبو إسحاق الفزاري، عن الأعمش، عن جعفر بْن عبد الرحمن، عن أم طارق مولاة سعد، قالت: أتانا رسول الله صلى الله عليه وآله وسلم فاستأذن مرارًا، فلم نرد، فرجع، فقال سعد: ائتي رسول الله صلى الله عليه وآله وسلم فاقري عليه السلام، وأخبريه أنا سكتنا عنه رجاء أن يزيدنا."],[41794,"أخرجها ابن منده، وأبو نعيم"],[41795,"٧٥٠٥ - أم طارق"],[41796,"س: أم طارق قسم لها رسول الله صلى الله عليه وآله وسلم من خيبر أربعين وسقا."],[41797,"رواه جعفر، بإسناده عن ابن إسحاق."],[41798,"أخرجها أبو موسى مختصرًا."],[41799,"٧٥٠٦ - أم الطفيل امرأة أبي بن كعب"],[41800,"ب د ع: أم الطفيل امرأة أبي بن كعب."],[41801,"روى عنها محمد بن أبي بن كعب، وعمارة بن عامر، وبسر بن سعيد."],[41802,"أخبرنا أبو ياسر بن أبي حبة، بإسناده عن عبد الله، حدثني أبي، حدثنا إسحاق بن عيسى، أخبرني ابن لهيعة، عن بكير، عن بسر بن سعيد، عن أبي بن كعب، قال: نازعني عمر بن الخطاب في المتوفى عنها وهي حامل، فقلت: تزوج إذا وضعت، فقالت أم الطفيل أم ولدي لعمر: قد أمر رسول الله صلى الله عليه وآله وسلم سبيعة الأسلمية أن تنكح إذا وضعت وروى سعيد بن هلال، عن مروان بن عثمان، عن عمارة بن عامر بن حزم الأنصاري، عن أم الطفيل امرأة أبي بن كعب، قالت: سمعت رسول الله صلى الله عليه وآله وسلم يقول: «رأيت ربي عز وجل في المنام» …"],[41803,"الحديث."],[41804,"أخرجها ابن منده، وأبو نعيم."],[41805,"٧٥٠٧ - أم طليق"],[41806,"د: أم طليق، امرأة أبي طليق."],[41807,"روى المختار بن فلفل، عن طلق بن حبيب، عن أبي طليق."],[41808,"أن امرأته، وهي أم طليق، قالت له، وله جمل وناقة: أعطني جملك أحج عليه."],[41809,"قال: هو حبيس في سبيل الله."],[41810,"ثم إنها سألت رسول الله صلى الله عليه وآله وسلم: ما يعدل الحج؟ فقال: «عمرة في رمضان»."],[41811,"أخرجه ابن منده."],[41812,"حرف العين"],[41813,"٧٥٠٨ - أم عامر الأشهلية"],[41814,": أم عامر الأشهلية دخلت على النبي صلى الله عليه وآله وسلم. روى عنها أبو سفيان مولى ابن أبي أحمد من حديث الواقدي."],[41815,"أخرجها ابن منده، وأبو نعيم."],[41816,"٧٥٠٩ - أم عامر بن الجراح"],[41817,"س: أم عامر بن الجراح أبي عبيدة الفهري وهي امرأة من بني الحارث بن فهر."],[41818,"أدركت الإسلام وأسلمت."],[41819,"قاله جعفر، عن خليفة بن خياط."],[41820,"أخرجها أبو موسى."],[41821,"٧٥١٠ - أم عامر بنت سويد"],[41822,"أم عامر بنت سويد قال أبو موسى: أوردها جعفر، لم يزد وهو أخرجها."],[41823,"٧٥١١ - أم عامر بنت كعب"],[41824,"س: أم عامر بنت كعب الأنصارية روت عنها ليلة مولاة خبيب بن عبد الرحمن، أن النبي صلى الله عليه وآله وسلم قال لها: «هلمي فكلي»."],[41825,"قالت: إني صائمة: قال: «إن الملائكة يصلون على الصائم إذا أكل عنده»."],[41826,"أخرجها أبو عمر."],[41827,"٧٥١٢ - أم عامر بن واثلة"],[41828,"ع س: أم عامر بن واثلة أبي الطفيل"],[41829,"أخبرنا يحيى، إجازة، بإسناده عن أبي بكر القاضي، حدثنا أبو كريب، حدثنا معاوية بن هشام، حدثنا سفيان، عن جابر الجعفي، عن أبي الطفيل، قال: رأيت رسول الله صلى الله عليه وآله وسلم يوم فتح مكة، فما أنسى بياض وجهه مع شدة سواد شعره، فقلت لأمي: من هذا؟ فقالت: هذا رسول الله صلى الله عليه وآله وسلم أخرجها أبو نعيم، وأبو موسى"],[41830,"٧٥١٣ - أم عامر بنت يزيد بن السكن"],[41831,"ب د ع: أم عامر بنت يزيد بن السكن الأنصارية الأشهلية قال أبو عمر: إن صح هذا فهي أسماء بنت يزيد بن السكن."],[41832,"وقد تقدم ذكرها في اسمها، والاختلاف في كنيتها، أو هي أخت أسماء، وقيل: أم عامر بنت سعيد بن السكن اسمها فكيهة، هذا قول الأكثر في أم عامر بنت سعيد بن السكن، لا بنت يزيد بن السكن، فعلى هذا هي بنت عم أسماء بنت يزيد بن السكن."],[41833,"وكانت من المبايعات، قاله أبو عمر."],[41834,"وكذلك سماها ابن منده، فقال: أم عامر بنت سعيد بن السكن."],[41835,"قال أبو نعيم: وهم، يعني: ابن منده، إنما هي بنت يزيد بن السكن."],[41836,"وقول أبي عمر يؤيد قول ابن منده ويصححه."],[41837,"ومن حديثها ما"],[41838,"أخبرنا به أبو ياسر، بإسناده عن عبد الله: حدثني أبي، حدثنا أبو عامر، حدثنا إبراهيم بن إسماعيل بن أبي حبيبة، حدثني عبد الرحمن بن عبد الرحمن الأشهلي، عن أم عامر بنت يزيد بن السكن، وكانت من المبايعات إنها أتت النبي صلى الله عليه وآله وسلم بعرق فتعرقه وهو في مسجد بني فلان، ثم قام إلى الصلاة فصلى ولم يتوضأ."],[41839,"وروى داود بن الحصين، عن أبي سفيان، مولى ابن أبي أحمد، عنها أنها أول من بايع رسول الله صلى الله عليه وآله وسلم من النساء."],[41840,"أخرجها الثلاثة."],[41841,"٧٥١٤ - أم عبد الله بن أنيس"],[41842,"د ع: أم عبد الله بن أنيس، من ولد عبد الله بن أنيس، امرأة كعب بن مالك."],[41843,"روى حديثها ابن وهب، عن عمرو بن الحارث، عن يحيى بن سعيد، عن عبد الله بن أنيس، عن أمه، وكانت عند كعب بن مالك، أن رسول الله صلى الله عليه وآله وسلم خرج على كعب بن مالك وهو ينشد في مسجد رسول الله صلى الله عليه وآله وسلم فلما رآه كأنه انقبض، فقال رسول الله صلى الله عليه وآله وسلم: «انشد» فأنشد …"],[41844,"وذكر الحديث."],[41845,"أخرجها ابن منده، وأبو نعيم."],[41846,"٧٥١٥ - أم عبد الله بن أوس"],[41847,"ب د ع: أم عبد الله بن أوس أخت شداد بن أوس الأنصارية."],[41848,"أخبرنا أبو منصور بن مكارم المؤدب، بإسناده عن المعافي بن عمران، عن أبي بكر الغساني، عن ضمرة بن حبيب، عن أم عبد الله، أخت شداد بن أوس أنها بعثت إلى النبي صلى الله عليه وآله وسلم بقدح لبن عند فطره وهو صائم، وذلك في طول النهار وشدة الحر، فرد إليها رسولها، أنى كان لك هذا اللبن فقالت: من شاة لي."],[41849,"فرد إليها رسولها، أنى كانت لك هذه الشاة؟ فقالت: اشتريتها من مالي."],[41850,"فأخذه منها."],[41851,"فلما كان الغد أتته أم عبد الله فقالت: يا رسول الله، بعثت إليك باللبن مرثية لك، من شدة الحر وطول النهار، فرددت الرسول فيه، فقال: «بذلك أمرت الرسل أن لا تأكل إلا طيبًا، ولا تعمل إلا صالحا»."],[41852,"أخرجها الثلاثة"],[41853,"٧٥١٦ - أم عبد الله بن بسر"],[41854,"د ع: أم عبد الله بن بسر روى عنها ابنها عبد الله بن بسر."],[41855,"أخبرنا أبو الفضل عبد الله بن أحمد الطوسي، بإسناده عن أبي داود الطيالسي: حدثنا شعبة، عن يزيد بن خمير، قال: سمعت عبد الله بن بسر قال: أتانا رسول الله صلى الله عليه وآله وسلم فألقت له أمي قطيفة فجلس عليها، فأتته بتمر فجعل يأكل ويقول بالنوى هكذا."],[41856,"وقال أبو داود هكذا بالسبابة والوسطي، كما يرمي بالنواة فوق أصبعيه، ثم دعا بشراب فشرب، ثم سقى الذي عن يمينه فقالت أمي: يا رسول الله، ادع الله لنا، فقال رسول الله صلى الله عليه وآله وسلم: «اللهم بارك لهم فيما رزقتهم، واغفر لهم وارحمهم»."],[41857,"قال: فما زلنا نتعرف بركة تلك الدعوة."],[41858,"أخرجها ابن منده، وأبو نعيم"],[41859,"٧٥١٧ - أم عبد الله الدوسية"],[41860,"د ع: أم عبد الله الدوسية أدركت النبي صلى الله عليه وآله وسلم. روى حديثها الزهري، عنها: أنها أدركت النبي صلى الله عليه وآله وسلم يقول: «يوم الجمعة واجب على كل قرية فيها إمام، وإن لم يكن فيها إلا أربعة»."],[41861,"أخرجها ابن منده، وأبو نعيم."],[41862,"٧٥١٨ - أم عبد الله، من بني زهرة"],[41863,"س: أم عبد الله من بني زهرة."],[41864,"أخرجها أبو موسى، وقال: أوردها جعفر، ولم يورد لها شيئا."],[41865,"٧٥١٩ - أم عبد الله بن عامر"],[41866,"د ع: أم عبد الله بن عامر بن ربيعة تقدم ذكرها."],[41867,"أخرجها ابن منده، وأبو نعيم كذا مختصرًا."],[41868,"وقد أخرجها أبو موسى فقال: أم عبد الله بنت أبي حثمة، هي أم عبد الله بن عامر بن ربيعة، ذكر ابن منده أنه أخرجها في ترجمة ابنها أو زوجها."],[41869,"هذا كلام أبي مُوسَى، وليس لاستدراكه وجه، فإن ابن منده أخرجها ترجمة منفردة، وليست مدرجة في ترجمة ابنها ولا زوجها."],[41870,"٧٥٢٠ - أم عبد الله بن عمر بن الخطاب"],[41871,"س: أم عبد الله بن عمر بن الخطاب."],[41872,"أخرجها أبو موسى، وقال: ذكر في حديث أن عبد الله هاجر مع أبويه، وقيل: إن أمه زينب بنت مظعون."],[41873,"٧٥٢١ - أم عبد الله زوجة أبي موسى الأشعري"],[41874,"ب د ع: أم عبد الله زوجة أبي موسى الأشعري"],[41875,"أخبرنا عبد الوهاب بن هبة الله، بإسناده عن عبد الله بن أحمد، حدثني أبي، حدثنا أبو معاوية، حدثنا الأعمش، عن إبراهيم، عن سهم ابن منجاب، عن القرثع، أنه سمع أبا موسى الأشعري، وصاحت امرأته، فقال لها: أما علمت ما قال رسول الله صلى الله عليه وآله وسلم قالت:"],[41876,"بلى."],[41877,"ثم سكتت."],[41878,"فلما مات قيل لها: أي شيء قال رسول الله صلى الله عليه وآله وسلم قالت: إن رسول الله صلى الله عليه وآله وسلم لعن من حلق أو خرق أو سلق."],[41879,"أخرجه الثلاثة"],[41880,"٧٥٢٢ - أم عبد الله بن نبيه بن الحجاج"],[41881,"د ع: أم عبد الله بنت نبيه بن الحجاج السهمية، امرأة عمرو بن العاص."],[41882,"وهي أم ابنه عبد الله بن عمرو."],[41883,"قال لها النبي صلى الله عليه وآله وسلم: «نعم البيت أبو عبد الله، وأم عبد الله، وعبد الله»."],[41884,"روى عنها ابنها عبد الله بن عمرو."],[41885,"روى عبد الملك بن قدامة، عن عمرو بن شعيب، عن أبيه، عن جده، قال: كانت أم عبد الله بن عمرو ابنة نبيه بن الحجاج، وكانت تلطف رسول الله صلى الله عليه وآله وسلم فأتاها ذات يوم فقال: «كيف أنت يا أم عبد الله؟» قالت: بخير، وعبد الله رجل قد ترك الدنيا. . . . الحديث."],[41886,"أخرجها ابن منده، وأبو نعيم."],[41887,"٧٥٢٣ - أم عبد الله امرأة نعيم بن النحام"],[41888,"د ع: أم عبد الله امرأة نعيم بن النحام."],[41889,"روى عروة بن الزبير، عن عبد الله بن عمر، أنه أتى أباه عمر بن الخطاب فقال: إني قد خطبت بنت نعيم بن النحام، وأريد أن تمشي معي فتكلمه لي، فقال عمر: إني أعلم بنعيم منك، عنده ابن أخ يتيم ولم يكن ليترك لحمه، فقال: إن أمها قد خطبت إلي، فقال عمر: فإن كنت فاعلًا فاذهب معك بعمك زيد بن الخطاب."],[41890,"قال: فذهبنا إليه، فكلمه زيد، قال: فكأنما كان نعيم سمع كلام عمر، فقال: مرحبًا بك وأهلًا …"],[41891,"وذكر منزلته وشرفه، ثم قال: إن عندي ابن أخ يتيم، فلم أكن لأصل لحوم الناس وأترك لحمي."],[41892,"قال: فقالت أمها من ناحية البيت: والله لا يكون هذا حتى يقضي به علينا رسول الله صلى الله عليه وآله وسلم أتحبس أيم بني عدي على ابن أخيك، سفية، أو قال: ضعيف، ثم خرجت حتى أتت رسول الله صلى الله عليه وآله وسلم فأخبرته الخبر، فدعا نعيما فقص عليه كما قال لعبد الله بن عمر، فقال رسول الله صلى الله عليه وآله وسلم: «صل رحمك، وأرض أيمك، فإن لهما من أمرهما نصيبا»."],[41893,"أخرجها ابن منده، وأبو نعيم."],[41894,"٧٥٢٤ - أم عبد الحميد امرأة رافع بن خديج"],[41895,"د ع: أم عبد الحميد امرأة رافع بن خديج."],[41896,"روى عنها يحيى بن عبد الحميد بن رافع بن خديج: أن رافع بن خديج رمي بسهم يوم أحد أو يوم خيبر في ثندوته، فأتى النبي صلى الله عليه وآله وسلم فقال: يا رسول الله، أنزع السهم، فقال: «يا رافع، إن شئت نزعت السهم والقطنة جميعا، وإن شئت نزعت السهم وتركت القطنة وشهدت لك يوم القيامة أنك شهيد»."],[41897,"قال: أنزع السهم واترك القطنة، واشهد لي أني شهيد."],[41898,"ففعل ذلك، فعاش إلى أيام معاوية، فانتقض به الجرح فمات منه."],[41899,"أخرجها ابن منده، وأبو نعيم."],[41900,"٧٥٢٥ - أم عبد الرحمن بن أذينة"],[41901,"ب: أم عبد الرحمن بن أذينة روي عنها حديث مخرجه من أهل الكوفة: سمعت النبي صلى الله عليه وآله وسلم يقول: «ارموا الجمار بمثل حصى الخذف»."],[41902,"أخرجها أبو عمر."],[41903,"٧٥٢٦ - أم عبد الرحمن بنت أبي سعيد الخدري"],[41904,"د ع: أم عبد الرحمن بنت أبي سعيد الخدري روى عبد العزيز بن محمد، عن محمد بن أبي حميد، عن هند بنت سعد بن إبراهيم بن أبي سعيد الخدري، عن عمتها، وهي أم عبد الرحمن بنت أبي سعيد، قالت: جاءنا رسول الله صلى الله عليه وآله وسلم عائدا لأبي سعيد، فقرب إليه ذراع شاة، فأكل منها، ثم حضرت الصلاة فصلى ولم يتوضأ."],[41905,"أخرجه ابن منده، وأبو نعيم."],[41906,"٧٥٢٧ - أم عبد الرحمن بن طارق"],[41907,"د ع: أم عبد الرحمن بن طارق بن علقمة"],[41908,"أخبرنا يحيى بن محمود، إجازة، بإسناده عن ابن أبي عاصم: حدثنا الحسن بن علي، حدثنا أبو عاصم، عن ابن جريج، عن عبيد الله بن أبي يزيد، عن عبد الرحمن بن طارق، عن أمه، أن النبي صلى الله عليه وآله وسلم كان يأتي مكانًا في دار يعلى، فيستقبل البيت فيدعو، ويخرج معه فيدعو، ونحن مسلمات."],[41909,"أخرجها ابن منده، وأبو نعيم"],[41910,"٧٥٢٨ - أم عبد الرحمن بن كعب"],[41911,"س: أم عبد الرحمن بن كعب بن مالك أوردها جعفر كذا، ولم يورد لها شيئا: إن لم تكن ابنة كعب بن مالك فهي أخرى غيرها."],[41912,"أخرجها أبو موسى."],[41913,"٧٥٢٩ - أم عبد بنت عبد ود بن سواء"],[41914,"ب د ع: أم عبد بنت عبد ود بن سواء بن قريم بن صاهلة الهذلية هي أم عبد الله بن مسعود كذا سماها أبو عمر غير مضافة إلى اسم الله تعالى."],[41915,"وقال ابن منده، وأبو نعيم: أم عبد الله بن مسعود، روى عنها ابنها عبد الله، وكلاهما واحدة."],[41916,"وقول أبي عمر أصح، لأن النبي صلى الله عليه وآله وسلم وغيره كانوا يقولون لابن مسعود: ابن أم عبد."],[41917,"روت عن النبي صلى الله عليه وآله وسلم أنها رأته يقنت في الوتر قبل الركوع."],[41918,"وروى أبو إسحاق السبيعي، عن مصعب بن سعد، قال: فرض عمر بن الخطاب للنساء المهاجرات في ألفين ألفين، منهن أم عبد."],[41919,"وروى أبو إسحاق السبيعي، أن عمر انتظر أم عبد حتى صلت على عتبة بن مسعود ابنها."],[41920,"أخرجه الثلاثة."],[41921,"٧٥٣٠ - أم عبد بنت الحارث"],[41922,"س: أم عبد بنت الحارث بن يزيد الهذلي."],[41923,"ذكرها جعفر كذلك."],[41924,"أخرجها أبو موسى مختصرًا."],[41925,"٧٥٣١ - أم عبس بنت مسلمة"],[41926,"أم عبس الأنصارية ذكرها محمد بن سعد في تاريخه فقال: أم عبس بنت مسلمة، أخت محمد بن مسلمة لأبويه، تزوجها أبو عبس بن جبر بن عمرو، فولدت له، وأسلمت وبايعت رسول الله صلى الله عليه وآله وسلم. ذكرها الأشيري."],[41927,"٧٥٣٢ - أم عبيد بنت سراقة"],[41928,"أم عبيد بنت سراقة بن الحارث بن عدي الأنصارية بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[41929,"٧٥٣٣ - أم عبيد بنت صخر"],[41930,"س: أم عبيد بنت صخر بن مالك روى ابن جريج، عن عكرمة، قال: فرق الإسلام بين أربع نسوة وبين أبناء بعولتهن: حمنة بنت أبي طلحة بن عبد العزى بن عثمان بن عبد الدار."],[41931,"كانت تحت خلف بن أسد بن عاصم بن بياضة الخزاعي، فخلف عليها الأسود بن خلف."],[41932,"وفاختة بنت الأسود بن المطلب كانت تحت أمية بن خلف، فخلف عليها صفوان بن أمية."],[41933,"وأم عبيد بنت صخر بن مالك بن عمرو بن عزيز، كانت تحت الأسلت، فخلف عليها أبو قيس بن الأسلت، والأسلت من الأنصار."],[41934,"ومليكة بنت خارجة بن سنان بن أبي حارثة، كانت تحت زبان بن سيار، فخلف عليها منظور بن زبان بن سيار."],[41935,"أخرجها أبو موسى."],[41936,"زبان: بالزاي، والباء الموحدة، وآخره نون."],[41937,"وسيار: بالسين المهملة والياء تحتها نقطتان."],[41938,"٧٥٣٤ - أم عبيس"],[41939,"ب ع س: أم عبيس قال الزبير: كانت فتاة لبني تيم بن مرة، فأسلمت أول الإسلام، وكانت ممن استضعفه المشركون، فعذبوها، فاشتراها أبو بكر فأعتقها، وكنيت بابنها عبيس بن كريز."],[41940,"أخبرنا أبو جعفر، بإسناده عن يونس بن بكير، عن هشام بن عروة، عن أبيه، أن أبا بكر أعتق ممن كان يعذب في الله سبعة: بلالًا، وعامر بن فهيرة، وزنيرة، وجارية بني مؤمل، والنهدية، وابنتها، وأم عبيس."],[41941,"أخرجها أبو عمر، وأبو نعيم، وأبو موسى."],[41942,"عبيس: بضم العين المهملة، وفتح الباء الموحدة، وتسكين الياء تحتها نقطتان، وآخره سين مهملة"],[41943,"٧٥٣٥ - أم عثمان بنت خثيم"],[41944,"س: أم عثمان بنت خثيم الخزاعية روى وهب بن جرير، عن أبيه، عن قيس بن سعد، عن عطاء، عن أم عثمان بنت خثيم الخزاعية: أنها سألت النبي صلى الله عليه وآله وسلم عن العقيقة، فقال: «عن الغلام شاتان مكافئتان، وعن الجارية شاة»."],[41945,"أخرجها أبو موسى، وقال: هذا الحديث يعرف بأم كرز الكعبية."],[41946,"٧٥٣٦ - أم عثمان بنت سفيان"],[41947,"ب د ع: أم عثمان بنت سفيان أم بني شيبة الأكابر."],[41948,"كانت من المبايعات."],[41949,"روت عنها صفية بنت شيبة، وروى عبد الله بن مسافع، عن أمه، عنها."],[41950,"أخبرنا أبو ياسر، بإسناده عن عبد الله: حدثني أبي، حدثنا روح وأبو نعيم، قالا: حدثنا هشام بن أبي عبد الله، عن بديل بن ميسرة، عن صفية بنت شيبة، عن أم ولد شيبة، أنها قالت: رأيت رسول الله صلى الله عليه وآله وسلم يسعى بين الصفا والمروة، ويقول: «لا يقطع الأبطح إلا شدا»."],[41951,"رواه حماد بن زيد، عن بديل بن ميسرة، عن مغيرة بن حكيم، عن صفية، عن امرأة منهم، أنها رأت النبي صلى الله عليه وآله وسلم. . . . . فذكر نحوه."],[41952,"أخرجها الثلاثة"],[41953,"٧٥٣٧ - أم عثمان بن أبي العاص"],[41954,"ب د ع: أم عثمان بن أبي العاص الثقفي روى عنها ابنها عثمان."],[41955,"روى حديثها عبد الله بن عثمان بن أبي سليمان، عن ابن أبي سويد الثقفي، عن عثمان بن أبي العاص، عن أمه، أنها شهدت آمنة لما ولدت النبي صلى الله عليه وآله وسلم فلما ضربها المخاض نظرت إلى النجوم تدلى حتى إني لأقول: ليقعن علي، فلما ولدت خرج لها نور أضاء له البيت الذي نحن فيه والجدار، فما شيء أنظر إليه إلا نور."],[41956,"أخرجها الثلاثة."],[41957,"٧٥٣٨ - أم عجرد"],[41958,"ب د ع: أم عجرد الخزاعية لها ذكر في حديث المثنى بن الصباح، عن عمرو بن شعيب، عن أبيه، عن جده قال: سمعت أم عجرد الخزاعية تسأل رسول الله صلى الله عليه وآله وسلم قالت: يا رسول الله، أمر كنا نفعله في الجاهلية ألا نفعله في الإسلام؟ قال: «ما هذا؟» قالت: العقيقة."],[41959,"قال: «فافعلوا، عن الغلام شاتان مكافئتان، وعن الجارية شاة»."],[41960,"مثل حديث أم كرز."],[41961,"أخرجها الثلاثة، إلا أن ابن منده وأبا نعيم لم يذكرا متن الحديث، إنما قالا: عمرو بن شعيب، عن أبيه، عن جده."],[41962,"لم يزيدا عليه، وذكر المتن أبو عمر."],[41963,"٧٥٣٩ - أم عصمة العوصية"],[41964,"د ع: أم عضمة العوصية رأت النبي صلى الله عليه وآله وسلم. روت عنها أم الشعثاء، أنها قالت: قال رسول الله صلى الله عليه وآله وسلم: «ما من مسلم يعمل ذنبًا إلا وقف الملك الموكل بإحصاء ذنوبه ثلاث ساعات، فإن استغفر الله من ذنبه ذلك لم يرفعه عليه يوم القيامة»."],[41965,"هكذا رواه سعيد بن سنان، عن أم الشعثاء."],[41966,"وقال غيره: أم عطية."],[41967,"والله أعلم."],[41968,"أخرجها ابن منده، وأبو نعيم."],[41969,"٧٥٤٠ - أم عطاء مولاة الزبير"],[41970,"ب د ع: أم عطاء، مولاة الزبير بن العوام لها صحبة ورواية."],[41971,"أخبرنا أبو ياسر، بإسناده عن عبد الله بن أحمد: حدثني أبي، حدثنا يعقوب، حدثنا أبي، عن محمد بن إسحاق، عن عبد الله بن عطاء بن إبراهيم، مولى الزبير، عن أمه وجدته أم عطاء، قالتا: والله لكأننا ننظر إلى الزبير بن العوام حين أتانا على بغلة له بيضاء، فقال: يا أم عطاء، إن رسول الله صلى الله عليه وآله وسلم قد نهى المسلمين أن يأكلوا من لحوم نسكهم فوق ثلاث."],[41972,"فقالت: كيف نصنع بما أهدي؟ قال: أما ما أهدي لكن فشأنكن به."],[41973,"أخرجها الثلاثة"],[41974,"٧٥٤١ - أم عطية الأنصارية"],[41975,"س: أم عطية الأنصارية الخافضة أوردها جعفر، قال أبو موسى: وأظنها المذكورة، يعني: أم عطية نسيبة التي يأتي ذكرها بعد هذه."],[41976,"وروى بإسناد له عن الوليد بن صالح، عن عبيد الله بن عمرو، عن عبد الملك بن عمير، عن عطية القرظي، قال: كانت بالمدينة خافضة يقال لها: أم عطية، فقال لها رسول الله صلى الله عليه وآله وسلم: «أشمي ولا تخفي، فإنه أسرى للوجه، وأحظى عند الزوج»."],[41977,"قال أبو موسى: وهذا الحديث يروى بغير هذا الإسناد."],[41978,"٧٥٤٢ - أم عطية الأنصارية"],[41979,"ب: أم عطية الأنصارية."],[41980,"اسمها نسيبة بنت الحارث وقيل: نسيبة بنت كعب قال أحمد بن زهير: سمعت يحيى بن معين وأحمد بن حنبل يقولان: أم عطية الأنصارية نسيبة بنت كعب."],[41981,"قال أبو عمر: في هذا نظر، لأن أم عمارة نسيبة بنت كعب."],[41982,"تعد أم عطية في أهل البصرة."],[41983,"وكانت من كبار نساء الصحابة."],[41984,"وكان تغسل الموتى، وتغزو مع رسول الله صلى الله عليه وآله وسلم. روى عنها محمد بن سيرين، وأخته حفصة، وعبد الملك بن عمير، وعلي بن الأقمر."],[41985,"أخبرنا غير واحد، بإسنادهم عن أبي عيسى الترمذي: حدثنا أحمد بن منيع، أخبرنا هشم، أخبرنا خالد ومنصور وهشام، فأما خالد وهشام، فقالا: عن محمد وحفصة، وقال منصور: عن محمد، عن أم عطية، قالت: توفيت إحدى بنات النبي صلى الله عليه وآله وسلم فقال: «اغسلنها وترًا ثلاثًا أو خمسًا أو أكثر من ذلك إن رأيتن، واغسلنها بماء وسدر، واجعلن في الآخرة كافورًا أو شيئًا من كافور، فإذا فرغتن فآذنني»."],[41986,"فلما فرغنا آذناه فألقي إلينا حقوه، وقال: «أشعرنها إياه»."],[41987,"أخرجها ههنا أبو عمر، وأخرجها الثلاثة في النون من الأسماء"],[41988,"٧٥٤٣ - أم عطية العوصية"],[41989,"د ع: أم عطية العوصية."],[41990,"وقيل: أم عصمة."],[41991,"والأول أكثر، رأت النبي صلى الله عليه وآله وسلم روى أبو مهدي سعيد بن سنان، عن أم الشعثاء، عن أم عصمة العوصية، امرأة من قيس، وذكر حديث: «ما من مسلم يعمل ذنبًا إلا وقف الملك الموكل بإحصاء ذنوبه …"],[41992,"»."],[41993,"الحديث."],[41994,"وقد تقدم في أم عصمة."],[41995,"ورواه غير سعيد فقال: أم عطية."],[41996,"أخرجها ابن منده، وأبو نعيم."],[41997,"٧٥٤٤ - أم عفيف بنت مسروح"],[41998,"س: أم عفيف بنت مسروح، زوج حمل بن مالك بن النابغة"],[41999,"أخبرنا أبو موسى، إجازة، أخبرنا أبو علي، أخبرنا أبو نعيم، أخبرنا سليمان بن أحمد، حدثنا عبد الله بن أحمد بن حنبل، حدثني محمد بن عباد المكي، حدثني محمد بن سليمان بن مسمول، عن عمرو بن تميم بن عويم، عن أبيه، عن جده، قال: كانت أختي مليكة وامرأة منا يقال لها: أم عفيف بنت مسروح، تحت حمل بن مالك بن النابغة، فضربت أم عفيف مليكة بمسطح بيتها، وهي حامل فقتلتها وذا بطنها فقضى رسول الله صلى الله عليه وآله وسلم فيها بالدية، وفي جنينها بغرة عبد أو أمة."],[42000,"أخرجها أبو موسى"],[42001,"٧٥٤٥ - أم عفيف النهدية"],[42002,"ب د ع: أم عفيف النهدية، إحدى المبايعات."],[42003,"روى عنها أبو عثمان النهدي، أنها قالت: بايعنا رسول الله صلى الله عليه وآله وسلم فأخذ علينا لا نحدث غير ذي محرم خاليًا، به، وأمرنا أن نقرأ بفاتحة الكتاب على ميتنا."],[42004,"أخرجها الثالثة."],[42005,"٧٥٤٦ - أم عقيل"],[42006,"د ع: أم عقيل، روى عنها ابنها عقيل."],[42007,"روى عبد السلام بن حرب، عن إسحاق بن أبي فروة، عن عقيل، عن أمه أم عقيل، قالت: أتيت رسول الله صلى الله عليه وآله وسلم فقلت: إن أبا عقيل مات وأوصى بهذا الجمل في سبيل الله، وإنه أعجف؟ فقال: «يا أم عقيل، اعتمري، فإن عمرة في رمضان تعدل حجة»."],[42008,"أخرجها ابن منده، وأبو نعيم، وقال أبو نعيم: الصواب أم معقل."],[42009,"وترد في الميم إن شاء الله تعالى."],[42010,"٧٥٤٧ - أم العلاء الأنصارية"],[42011,"ب د ع: أم العلاء الأنصارية من المبايعات."],[42012,"أخبرنا عبد الوهاب بن هبة الله، بإسناده عن عبد الله: حدثني أبي، حدثنا أبو كامل، حدثنا إبراهيم بن سعد، حدثنا ابن شهاب ح ويعقوب، حدثنا أبي، عن ابن شهاب، عن خارجة بن زيد بن ثابت، عن أم العلاء، وهي امرأة من نسائهم، قال يعقوب: أخبرته أنها بايعت صلى الله عليه وآله وسلم قال يعقوب: طار لهم في السكنى عثمان بن مظعون حين اقترعت الأنصار على سكنى المهاجرين، قالت أم العلاء: فاشتكى عثمان بن مظعون عندنا فمرضناه، حتى إذا توفي أدرجناه في أثوابه، فدخل علينا رسول الله صلى الله عليه وآله وسلم. فقلت: رحمة الله عليك يا أبا السائب، شهادتي عليك لقد أكرمك الله، فقال رسول الله صلى الله عليه وآله وسلم: «وما يدريك أن الله أكرمه؟»، قالت: فقلت: لا أدري بأبي أنت وأمي! فقال رسول الله صلى الله عليه وآله وسلم: «أما هذا فقد جاءه اليقين من ربه، وإني لأرجو له الخير من الله، ووالله ما أدري وأنا رسول الله صلى الله عليه وآله وسلم ما يفعل بي؟»، قال يعقوب: به، قالت: فقلت: والله لا أزكي أحدًا بعده أبدًا."],[42013,"فأحزنني ذلك فنمت، فرأيت لعثمان عينًا تجري، فجئت إلى رسول الله صلى الله عليه وآله وسلم فأخبرته، فقال رسول الله صلى الله عليه وآله وسلم: «ذاك عمله»."],[42014,"روى عمرو بن دينار في آخرين، عن الزهري، وعبد الملك بن عمير، عن أم العلاء في مرض المسلم أنه يكفره."],[42015,"قيل: إنها غير هذه. قال ابن السكن: أم العلاء التي روى عنها خارجة بن زيد غير التي روى عنها عبد الملك بن عمير."],[42016,"وذكر أم العلاء ثالثة، وهي غيرهما جميعًا، مخرج حديثها عن أهل الشام في عيادة رسول الله صلى الله عليه وآله وسلم لها، وقد ذكرناها."],[42017,"أخرجها الثلاثة."],[42018,"٧٥٤٨ - أم العلاء عمة حزام بن حكيم"],[42019,"د ع: أم العلاء عمة حزام بن حكيم روى عنها عبد الملك بن عمير، أنها قالت: عادني رسول الله صلى الله عليه وآله وسلم فقال: «يا أم العلاء، أبشري فإن مرض المسلم يذهب الله به خطاياه، كما تذهب النار خبث الحديد»."],[42020,"وروى أيضا هذا الحديث حزام بن حكيم، عن عمته أم العلاء، عن النبي صلى الله عليه وآله وسلم. أخرجها ابن منده، وأبو نعيم."],[42021,"وأما أبو عمر فقد تقدم قوله في ترجمة أم العلاء الأنصارية عن ابن السكن، فهو أيضا قد أخرجها، إلا أنه لم يجعل لها ترجمة منفردة، والله أعلم."],[42022,"٧٥٤٩ - أم علي بنت خالد"],[42023,"أم علي بنت خالد بن تيم بن بياضة بن خفاف، التي نزل الآذان في بيتها."],[42024,"قاله ابن الكلبي."],[42025,"قال العدوي: ولم أر أهل الحجاز يعرفون هذا، ولا ابن القداح ولا ابن مزروع."],[42026,"ذكرها ابن الدباغ، عن أبي علي."],[42027,"٧٥٥٠ - أم عمارة الأنصارية"],[42028,"د ع: أم عمارة الأنصارية أخبرنا إسماعيل بن علي، وغير واحد، بإسنادهم عن محمد بن عيسى، حدثنا عبد بن حميد، حدثنا محمد بن كثير، أخبرنا سليمان بن كثير، عن عكرمة، عن أم عمارة، أنها أتت النبي صلى الله عليه وآله وسلم فقالت: ما أرى كل شيء إلا للرجال! ما أرى النساء يذكرن بشيء! فنزلت: ﴿إِنَّ الْمُسْلِمِينَ وَالْمُسْلِمَاتِ وَالْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ﴾ الآية."],[42029,"أخرجها ابن منده، وأبو نعيم، وذكر هذا الحديث في هذه الترجمة، وأورده أبو عمر في ترجمة أم عمارة بنت كعب التي نذكرها بعد هذه إن شاء الله تعالى، كأنه رآهما واحدة"],[42030,"٧٥٥١ - أم عمارة الأنصارية"],[42031,"ب د ع: أم عمارة بنت كعب بن عمرو بن عوف بن مبذول بن عمرو بن غنم بن مازن بن النجار وهي أنصارية من بني مازن، واسمها نسيبة، وقد تقدمت في النون."],[42032,"وهي أم حبيب، وعبد الله ابني زيد بن عاصم."],[42033,"كانت قد شهدت بيعة العقبة، وشهدت أحدًا مع زوجها زيد بن عاصم ومع ابنيها حبيب، وعبد الله، في قوله ابن إسحاق، وشهدت بيعة الرضوان، وشهدت يوم اليمامة فقاتلت حتى أصيبت يدها وجرحت يومئذ اثنتي عشرة جراحة."],[42034,"روت عن النبي صلى الله عليه وآله وسلم: «الصائم إذا أكل عنده صلت عليه الملائكة»."],[42035,"وروى عنها عكرمة مولى ابن عباس، أنها قالت للنبي: ما أرى كل شيء إلا للرجال …"],[42036,"الحديث."],[42037,"قاله أبو عمر."],[42038,"وأما ابن منده، وأبو نعيم فلم ينسباها، بل قالا: أم عمارة بنت كعب الأنصارية، وروى لها أبو نعيم حديث: «الصائم إذا أكل عنده»."],[42039,"وأما ابن منده فروى لها، أن النبي صلى الله عليه وآله وسلم نحر بدنه قيامًا، وقال: «رحم الله المحلقين»."],[42040,"فابن منده، وأبو نعيم جعلا هذه والتي قبلها ترجمتين، وأبو عمر جعلهما واحدة، فلو نسبها ابن منده، وأبو نعيم لظهر هل هما واحدة أم اثنتان؟ والله أعلم."],[42041,"أخرجها الثلاثة."],[42042,"٧٥٥٢ - أم عمر بن خلدة"],[42043,"د ع: أم عمر بن خلدة الأنصارية أخبرنا يحيى فيما أذن لي، بإسناده عن القاضي أبي بكر أحمد بن عمرو، قال: حدثنا أبو بكر بن أبي شيبة، حدثنا وكيع، عن موسى بن عبيدة، عن منذر بن جهم، عن عمر بن خلدة، عن أمه."],[42044,"قالت: إن النبي صلى الله عليه وآله وسلم بعث عليًا ينادي بمنى: «إنها أيام أكل وشرب وبعال»."],[42045,"أخرجها ابن منده، وأبو نعيم."],[42046,"هذه أم عمر، بضم العين"],[42047,"٧٥٥٣ - أم عمرو بن حريث"],[42048,"س: أم عمرو بن حريث"],[42049,"أخبرنا أبو موسى، إذنا، أخبرنا أبو نصر أحمد بن عمر الغازي، أخبرنا إسماعيل بن زاهر النيسابوري، أخبرنا القطان، أخبرنا عبد الله بن جعفر بن درستويه، حدثنا يعقوب بن سفيان، حدثنا ابن نمير، حدثنا يحيى بن يمان، حدثنا إسماعيل بن أبي خالد، قال: سمعت عمرو بن حريث، يقول: ذهبت بي أمي إلى النبي صلى الله عليه وآله وسلم فمسح على رأسي، ودعا لي بالرزق."],[42050,"أخرجه أبو موسى، عمرو: بفتح العين"],[42051,"٧٥٥٤ - أم عمرو امرأة الزبير بن العوام"],[42052,"د ع: أم عمرو وامرأة الزبير بن العوام روت عنها أم شبيب، أنها قالت: سمعت رسول الله صلى الله عليه وآله وسلم يقول: «أنشد الله امرأ يصلي في الحجر»."],[42053,"أخرجها ابن منده، وأبو نعيم."],[42054,"٧٥٥٥ - أم عمرو بنت سلامة"],[42055,"أم عمرو بنت سلامة بن وقش بن زغبة بن زعوراء الأنصارية بايعت النبي صلى الله عليه وآله وسلم. قاله ابن حبيب."],[42056,"٧٥٥٦ - أم عمرو بن سليم"],[42057,"ب د ع: أم عمرو بن سليم الزرقي روى يزيد بن الهاد، عن عبد الله بن أبي سلمة، عن عمرو بن سليم، عن أمه: أنها سمعت عليًا ينادي وهم بمنى مع رسول الله صلى الله عليه وآله وسلم: «إنها أيام أكل وشرب»."],[42058,"أخرجها الثلاثة."],[42059,"وقد تقدم هذا المتن في ترجمة أم عمر بن خلدة."],[42060,"ورواه ابن إسحاق، عن حكيم بن حكيم بن عباد، عن مسعود بن الحكم، عن أمه."],[42061,"ونذكره إن شاء الله تعالى في موضعه."],[42062,"٧٥٥٧ - أم عمرو بنت محمود"],[42063,"أم عمرو بنت محمود بن مسلمة بن سلمة بن خالد بن عدي بن مجدعة وهي ابنة أخي محمد بن مسلمة."],[42064,"قتل أبوها بخيبر."],[42065,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[42066,"٧٥٥٨ - أم عميس"],[42067,"أم عميس بن مسلمة بن سلمة بن خالد بن عدي الأنصارية، أخت محمد ومحمود ابني مسلمة."],[42068,"وهي امرأة رافع بن خديج."],[42069,"وهي التي نزل فيها: ﴿وَإِنِ امْرَأَةٌ خَافَتْ مِنْ بَعْلِهَا نُشُوزًا أَوْ إِعْرَاضًا﴾."],[42070,"الآية."],[42071,"بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[42072,"٧٥٥٩ - أم عياش"],[42073,"ب د ع: أم عياش خادم النبي صلى الله عليه وآله وسلم ومولاته، وقيل: مولاة رقية."],[42074,"أخبرنا يحيى بن أبي الرجاء، إجازة، بإسناده عن ابن أبي عاصم: حدثنا هدبة، عن عبد الواحد بن صفوان، حدثنا أبي، عن أمه، عن جدته أم عياش، وكانت خادم النبي صلى الله عليه وآله وسلم بعثها مع ابنته إلى عثمان، قالت: كنت أمغث لعثمان الزبيب غدوة فيشربه عشية، وأنبذه عشية فيشربه غدوة."],[42075,"فسألني ذات يوم فقال: «تخلطين فيه شيئا؟» قلت: أجل، قال: «فلا تعودي» روى عبد الكريم بن روح، عن عنبسة بن سعيد البزاز، عن أبيه، عن جدته أم أبيه أم عياش، وكانت أمة لرقية بنت رسول الله صلى الله عليه وآله وسلم قالت: كنت أوضئ رسول الله صلى الله عليه وآله وسلم وأنا قائمة وهو قاعد."],[42076,"أخرجها الثلاثة."],[42077,"٧٥٦٠ - أم عيسى بنت الجزار"],[42078,"أم عيسى بنت الجزار العصرية لها صحبة عن النبي صلى الله عليه وآله وسلم. حدث عبد الرحمن بن عمرو بن جبلة، عن أم فروة ابنة مزاحم العصرية، عن أمها أم عيسى بنت الجزار."],[42079,"قاله ابن ماكولا، وقال: وأما الجزار، بعد الجيم زاي، وبعد الألف راء، فأم عيسى، وذكرها."],[42080,"حرف الغين"],[42081,"٧٥٦١ - أم الغادية"],[42082,"ب د ع: أم الغادية هاجرت إلى المدينة إلى النبي صلى الله عليه وآله وسلم مع أبي الغادية، وحبيب بن الحارث."],[42083,"روى محمد بن عبد الرحمن الطفاوي، عن العاصي بن عمرو الطفاوي، عن حبيب بن الحارث، وأبي الغادية، أنهما خرجا مهاجرين إلى رسول الله صلى الله عليه وآله وسلم ومعهما أم الغادية فأسلموا."],[42084,"فقالت المرأة: أوصي يا رسول الله."],[42085,"قال: «إياك وما يسوء الأذن»."],[42086,"أخرجها الثلاثة، وقال أبو عمر: إسنادها مجهول."],[42087,"٧٥٦٢ - أم غطيف"],[42088,"ع س: أم غطيف الهذلية هي التي ضربت مليكة في حديث حمل بن مالك بن النابغة."],[42089,"هكذا سميت في رواية أبساط، عن سماك، عن عكرمة."],[42090,"قاله أبو نعيم، وأبو بكر الخطيب."],[42091,"أخرجها أبو نعيم، وأبو موسى."],[42092,"حرف الفاء"],[42093,"٧٥٦٣ - أم فروة ظئر النبي ﷺ"],[42094,"س: أم فروة ظئر النبي صلى الله عليه وآله وسلم هكذا ذكرها جعفر المستغفري، وروى بإسناده، عن إسحاق بن أبي إسرائيل، عن مؤمل، عن سفيان، عن أبي إسحاق، عن أم فروة ظئر النبي صلى الله عليه وآله وسلم قالت: قال لي رسول الله صلى الله عليه وآله وسلم: «إذا أويت إلى فراشك فاقرئي ﴿قُلْ يَأَيُّهَا الْكَافِرُونَ﴾، فإنها براءة من الشرك»."],[42095,"قد اختلف في راوي هذا الحديث، فقيل فروة."],[42096,"وقيل: أبو فروة."],[42097,"وقيل: نوفل."],[42098,"وهذا القول أغرب الأقوال."],[42099,"أخرجها أبو موسى."],[42100,"٧٥٦٤ - أم فورة الأنصارية"],[42101,"د ع: أم فروة الأنصارية من المبايعات."],[42102,"أخبرنا أبو ياسر، بإسناده عن عبد الله بن أحمد: حدثني أبي، حدثنا أبو عاصم، عن عبد الله بن عمر، عن القاسم بن غنام البياضي، عن عماته، عن أم فروة، قالت: سئل رسول الله صلى الله عليه وآله وسلم: أي العمل أفضل؟ فقال: «الصلاة لأول وقتها»."],[42103,"ورواه الليث، وعبد الرزاق، وأبو نعيم، وغيرهم، عن عبد الله بن عمر، عن القاسم، عن جدته أم أبيه الدنيا، عن جدته أم فروة."],[42104,"وذكره."],[42105,"ورواه قزعة بن سويد، والمعتمر بن سليمان، عن عبيد الله بن عمر."],[42106,"ورواه ابن أبي فديك، عن الضحاك بن عثمان، عن القاسم بن غنام، عن امرأة من المبايعات."],[42107,"ولم يسمها."],[42108,"أخرجها ابن منده، وأبو نعيم"],[42109,"٧٥٦٥ - أم فروة بنت أبي قحافة"],[42110,"ب د ع: أم فروة بنت أبي قحافة التيمية تقدم نسبها عند ذكر أبيها، وهي أخت أبي بكر الصديق، أمها هند بنت نقيد بن بجير بن عبد بن قصي."],[42111,"وهي التي زوجها أخوها أبو بكر من الأشعث بن قيس الكندي، فولدت له محمدًا وإسحاق، وقريبة وحبابة."],[42112,"وكانت أم فروة من المبايعات، بايعت رسول الله صلى الله عليه وآله وسلم. وروت عنه أنه قال: «إن أحب الأعمال إلى الله، عز وجل الصلاة في أول وقتها» قاله أبو عمر."],[42113,"واختصرها ابن منده، وأبو نعيم فقالا: أم فروة بنت أبي قحافة، أخت أبي بكر الصديق، صاحب الطوق، لها ذكر في حديث فتح مكة."],[42114,"أخرجها الثلاثة."],[42115,"قلت: قد ذكر أبو عمر حديث الصلاة في أول وقتها في هذه الترجمة، وقال: قد قال بعضهم في أم فروة هذه: إنها أنصارية، وهو وهم، قال: وإنما جاء ذلك، والله أعلم، لأن القاسم بن غنام الأنصاري يقول في حديثه مرة عن جدته الدنيا، ومرة عن جدته القصوى، ومرة عن بعض أمهاته، عن عمة له."],[42116,"والصواب ما ذكرناه."],[42117,"وأما ابن منده، وأبو نعيم فإنهما ذكرا هذا الحديث في أم فروة الأنصارية."],[42118,"كما ذكرناه قبل هذه الترجمة، وقد قال الطبراني: أم فروة هذه، يعني التي تروي حديث الصلاة، هي أخت أبي بكر الصديق."],[42119,"وقال غيره: هي أخرى سواها والله أعلم."],[42120,"على أن القاسم بن غنام من الأنصار، يروي عن جدة له، أو عن بعض أهله، وكيف اختلفت الرواية عليه، فهي من الأنصار، وليس لأخت أبي بكر فيه مدخل."],[42121,"والله أعلم."],[42122,"٧٥٦٦ - أم الفضل بنت الحارث"],[42123,"ب د ع: أم الفضل بنت الحارث زوج العباس بن عبد المطلب، واسمها لبابة."],[42124,"وقد تقدمت في اللازم."],[42125,"روت عن النبي صلى الله عليه وآله وسلم أنه قرأ في المغرب بالمرسلات."],[42126,"أخرجها الثلاثة."],[42127,"٧٥٦٧ - أم الفضل بنت حمزة"],[42128,"ب د ع: أم الفضل بنت حمزة بن عبد المطلب."],[42129,"قيل: اسمها فاطمة."],[42130,"وقيل غير ذلك."],[42131,"وهي بنت عم النبي صلى الله عليه وآله وسلم. روى عنها عبد الله بن شداد بن الهاد، أنها قالت: توفي مولى لنا وترك ابنة وأختًا، فأتيا رسول الله، فأعطي الأبنة النصف وأعطى الأخت النصف."],[42132,"كذا رواه أبو عمر."],[42133,"وأما ابن منده، وأبو نعيم فإنهما، قالا: عن عبد الله بن شداد، عن أم الفضل بنت حمزة، قالت: مات مولى لنا، هي أعتقته، وترك ابنة، وإن رسول الله صلى الله عليه وآله وسلم قسم ميراثه بين أم الفضل وابنته، أعطى الابنة النصف، وأعطى أم الفضل النصف."],[42134,"أخرجها الثلاثة، وقد ذكرت في فاطمة."],[42135,"٧٥٦٨ - أم الفضل بنت العباس"],[42136,"س: أم الفضل بنت العباس بن عبد المطلب."],[42137,"أخرجها أبو موسى، وقال: كذا، فرق جعفر بين هذه وبين أم الفضل زوجة العباس، وقد أخرجها البخاري فيمن روى عن النبي صلى الله عليه وآله وسلم من نساء بني هاشم."],[42138,"حرف القاف"],[42139,"٧٥٦٩ - أم قرثع"],[42140,"ع س: أم مرتع، غير منسوبة."],[42141,"أخبرنا أبو موسى، إذنا، أخبرنا أبو علي، أخبرنا أبو نعيم، أخبرنا أبو محمد بن حبان، حدثنا محمد بن جرير، حدثنا عصام بن رواد، حدثنا أبي، عن عمرو بن قيس، عن عطاء، عن أم قرثع، قالت: أتيت النبي صلى الله عليه وآله وسلم فقلت: يا رسول الله، إني امرأة أغلب على عقلي."],[42142,"فقال: «ما شئت، إن شئت دعوت الله لك، وإن شئت تصبرين؟ فقد وجبت لك الجنة»."],[42143,"قالت: أصبر."],[42144,"أخرجها أبو نعيم، وأبو موسى، وقد ذكرنا هذا الحديث في أم زفر، ولعلها قد صحفت"],[42145,"٧٥٧٠ - أم قرة"],[42146,"د ع: أم قرة بن دعموص لها ذكر."],[42147,"أخرجها ابن منده، وأبو نعيم مختصرًا."],[42148,"٧٥٧١ - أم قيس بنت محصن"],[42149,"ب د ع: أم قيس بنت محصن بن حرثان الأسدية، أخت عكاشة بن محصن."],[42150,"أسلمت بمكة قديمًا، وبايعت النبي صلى الله عليه وآله وسلم وهاجرت إلى المدينة."],[42151,"أخبرنا جماعة، بإسنادهم عن أبي عيسى، حدثنا قتيبة وأحمد بن منيع، قالا: حدثنا سفيان عن الزهري، عن عبيد الله بن عبد الله بن عتبة، عن أم قيس بنت محصن، أنها قالت: خلت بابن لي على رسول الله صلى الله عليه وآله وسلم لم يأكل الطعام، فبال عليه، فدعا بماء فرشه عليه قال أبو عمر: روى عنها من الصحابة، وابصة بن معبد."],[42152,"وروى عنها عبيد الله بن عبد الله، ونافع مولى حمنة بنت شجاع."],[42153,"وزعم العقيلي في حديث ذكره عن ابن لهيعة، عن أبي الأسود، عن درة بنت معاذ أنها أخبرته عن أم قيس أنها سألت النبي صلى الله عليه وآله وسلم أنتزاور إذا متنا، يزور بعضنا بعضًا؟ قال: «يكون النسم طائرًا يعلق بالجنة، حتى إذا كان يوم القيامة دخل كل نفس في جثتها»."],[42154,"قال العقيلي: أم قيس هذه أنصارية، وليست بنت محصن."],[42155,"قال أبو عمر: وقد قيل: إن التي روت هذا الحديث أم هانئ الأنصارية ذكر ذلك ابن أبي خيثمة، وغيره، وسنذكرها إن شاء الله تعالى."],[42156,"أخرجها الثلاثة، إلا أن أبا عمر كان يجب عليه أن يجعل أم قيس الأنصارية ترجمة مفردة، فلم يفعل، بل جعل حديثها في ترجمة أم قيس بنت محصن الأسدية."],[42157,"أخبرنا محمد بن محمد بن سرايا، وغيره، قالوا بإسنادهم عن محمد بن إسماعيل: حدثنا أبو اليمان، أخبرنا شعيب، عن الزهري، أخبرني عبيد الله بن عبد الله، أن أم قيس بنت محصن الأسدية، أسد خزيمة، وكانت من المهاجرات الأول اللاتي بايعن رسول الله صلى الله عليه وآله وسلم وهي أخت عكاشة، أنها أتت رسول الله صلى الله عليه وآله وسلم بابن لها قد أغلقت عليه من العذرة، فقال النبي صلى الله عليه وآله وسلم: «علام تدغرن أولادكن بهذا العلاق، عليكم بالعود الهندي، فإن فيه سبعة أشفية، منها ذات الجنب يريد الكست، وهو العود الهندي»"],[42158,"٧٥٧٢ - أم قيس"],[42159,"د ع: أم قيس، من المهاجرات، غير منسوبة."],[42160,"روى الأعمش، عن أبي وائل، عن ابن مسعود، قال: كان فينا رجل خطب امرأة يقال لها: أم قيس، فأبت أن تزوجه حتى يهاجر، فهاجر فتزوجها، فكنا نسميه: مهاجر أم قيس."],[42161,"أخرجها ابن منده، وأبو نعيم."],[42162,"٧٥٧٣ - أم قيس الهذلية"],[42163,"س: أم قيس الهذلية أوردها جعفر، ولم يذكر عنها شيئا."],[42164,"أخرجها أبو موسى."],[42165,"حرف الكاف"],[42166,"٧٥٧٤ - أم كبشة القضاعية"],[42167,"ب د ع: أم كبشة القضاعية العذرية"],[42168,"أخبرنا يحيى بن محمود، فيما أذن لي، بإسناده عن ابن أبي عاصم: حدثنا أبو بكر ابن أبي شيبة، أخبرنا حميد بن عبد الرحمن، عن الحسن بن صالح، عن الأسود بن قيس، قال: حدثني سعيد بن عمرو القرشي، أن أم كبشة امرأة من عذرة قضاعة، قالت: يا رسول الله، أئذن لي أن أخرج في جيش كذا وكذا."],[42169,"قال: «لا»."],[42170,"قالت: يا رسول الله، إني ليس أريد أن أقاتل إنما أريد أن أداوي الجرحى والمرضى وأسقي الماء."],[42171,"قال: «لولا أن تكون سنة ويقال: فلانة خرجت، لأذنت لك، ولكن اجلسي»."],[42172,"أخرجها ابن منده، وأبو نعيم"],[42173,"٧٥٧٥ - أم كثير بنت يزيد"],[42174,"ع س: أم كثير بنت يزيد الأنصارية"],[42175,"أخبرنا أبو موسى، إذنا، أخبرنا أبو علي، حدثنا أحمد بن عبد الله، حدثنا أبو أحمد الغطريفي، حدثنا محمد بن إبراهيم بن شعيب الغازي، حدثنا أحمد بن سهيل الوراق، أخبرنا إسحاق بن عيسى، أخبرنا أبو الصباح، وفي نسخة أحمد بن الصباح عن أم كثير بنت يزيد الأنصارية، قالت: دخلت أنا وأختي على رسول الله صلى الله عليه وآله وسلم فقالت له: إن أختي تريد أن تسألك عن شيء، وهي تستحيي؟! قال: «فلتسأل، فإن طلب العلم فريضة»."],[42176,"قالت: فقلت له، أو قالت أختي، إن لي ابنًا يلعب بالحمام، فقال: «أما إنه لعبة المنافقين»."],[42177,"أخرجها أبو نعيم، وأبو موسى"],[42178,"٧٥٧٦ - أم كجة زوج أوس بن ثابت"],[42179,"ع س: أم كجة زوج أوس بن ثابت."],[42180,"نزلت فيه آية المواريث."],[42181,"أخبرنا أبو محمد عبد الله بن علي بن عبد الله بن سويدة، بإسناده عن أبي الحسن علي بن أحمد المفسر، في قوله تعالى: ﴿لِلرِّجَالِ نَصيِبٌ مِمَّا تَرَكَ الْوَالِدَانِ وَالأَقْرَبُونَ﴾."],[42182,"الآية، قال: قال ابن عباس في رواية الكلبي: إن أوس بن ثابت الأنصاري توفي وترك ثلاث بنات وامرأة، يقال لها أم كجة، فقام رجلان من بني عمه فأخذا ماله، ولم يعطيا امرأته ولا بناته شيئًا، فجاءت أم كجة إلى رسول الله صلى الله عليه وآله وسلم فذكرت له ذلك، فنزلت هذه الآية وروى عبد الله بن محمد بن عقيل، عن جابر، قال: جاءت أم كجة إلى النبي صلى الله عليه وآله وسلم فقالت: يا رسول الله، إن لي ابنتين قد مات أبوهما، وليس يعطيان شيئًا."],[42183,"فأنزل الله تعالى: ﴿يُوصِيكُمُ اللَّهُ فِي أَوْلادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الأُنْثَيَيْنِ﴾."],[42184,"الآيتين."],[42185,"أخرجها أبو نعيم، وأبو موسى."],[42186,"٧٥٧٧ - أم الكرام السلمية"],[42187,"ب: أم الكرام السلمية روت عن النبي صلى الله عليه وآله وسلم في كراهة التحلي بالذهب للنساء."],[42188,"روى عنها الحكم بن جحل."],[42189,"ليس إسناد حديثها بالقوي، وقد ثبتت الرخصة في ذلك للنساء."],[42190,"أخرجها أبو عمر."],[42191,"٧٥٧٨ - أم كرز الخزاعية"],[42192,"ب د ع: أم كرز الخزاعية الكعبية روى عنها: ابن عباس، وحبيبة بنت ميسرة، ومجاهد، وعطاء بن أبي رباح."],[42193,"أخبرنا يحيى، كتابة، بإسناده عن ابن أبي عاصم، حدثنا محمد بن خالد بن عبد الله الواسطي، حدثنا أبي، عن سعيد بن أبي عروبة، عن قتادة، عن عطاء، عن ابن عباس، عن أم كرز الخزاعية، قالت: سألت النبي صلى الله عليه وآله وسلم عن العقيقة، فقال: «عن الغلام شاتان مكافئتان، وعن الجارية شاة»."],[42194,"اختلف على عطاء فيه، فروي عن عطاء، عن أم كرز."],[42195,"وروي عن عطاء، عن حبيبة بنت ميسرة، عن أم كرز."],[42196,"ورواه ابن عيينة، عن عبيد الله بن أبي يزيد، عن أبيه، عن سباع بن ثابت، عن أم كرز، نحوه."],[42197,"أخبرنا أبو أحمد بن علي الصوفي، بإسناده، عن أبي داود السجستاني، أخبرنا مسدد، عن سفيان، عن عبيد الله بن أبي يزيد … .."],[42198,"بإسناده، نحوه."],[42199,"أخرجها الثلاثة"],[42200,"٧٥٧٩ - أم كعب الأنصارية"],[42201,"ع س: أم كعب الأنصارية توفيت في عهد النبي صلى الله عليه وآله وسلم"],[42202,"أخبرنا يحيى بن محمود وعبد الوهاب بن هبة الله، بإسنادهما عن مسلم بن الحجاج، حدثنا يحيى بن يحيى، أخبرنا عبد الوارث بن سعيد، عن حسين بن ذكوان، حدثني عبد الله بن بريدة، عن سمرة بن جندب، قال: صليت خلف النبي صلى الله عليه وآله وسلم وصلى على أم كعب، ماتت وهي نفساء، فقام رسول الله صلى الله عليه وآله وسلم للصلاة عليها وسطها."],[42203,"أخرجها أبو نعيم، وأبو موسى"],[42204,"٧٥٨٠ - أم كلثوم بنت أبي بكر"],[42205,"د ع: أم كلثوم بنت أبي بكر الصديق روى إبراهيم بن طهمان، عن يحيى بن سعيد، عن حميد بن نافع، عن أم كلثوم بنت أبي بكر الصديق: أن النبي صلى الله عليه وآله وسلم نهى عن ضرب النساء، ثم شكاهن الرجال، فخلى النبي صلى الله عليه وآله وسلم بينهم وبين ضربهن، فقال النبي صلى الله عليه وآله وسلم: «لقد طاف الليلة بآل محمد سبعون امرأة، كلهن قد ضربن»."],[42206,"ورواه الليث بن سعد عن يحيى."],[42207,"وقال الثوري، عن يحيى، عن حميد بن نافع، عن زينب بنت أبي سلمة، نحوه."],[42208,"أخرجه ابن منده، وأبو نعيم."],[42209,"قلت: ليس لأم كلثوم بنت أبي بكر صحبة، لأنها ولدت بعد وفاة النبي صلى الله عليه وآله وسلم وأمها بنت خارجة، وهي التي قال فيها أبو بكر لعائشة في مرضه الذي توفي فيه: إني أرى ذات بطن بنت خارجة بنتا."],[42210,"فولدت أم كلثوم بعد موته."],[42211,"وكان هذا يعد من كراماته رضي الله عنه."],[42212,"٧٥٨١ - أم كلثوم بنت رسول الله ﷺ"],[42213,"ب د ع س: أم كلثوم بنت رسول الله صلى الله عليه وآله وسلم وأمها خديجة بنت خويلد."],[42214,"قال الزبير: أم كلثوم أسن من رقية ومن فاطمة."],[42215,"وخالفه غيره، والصحيح أنها أصغر من رقية، لأن رسول الله صلى الله عليه وآله وسلم زوج رقية من عثمان، فلما توفيت زوجه أم كلثوم، وما كان ليزوج الصغرى ويترك الكبرى، والله أعلم."],[42216,"وكان رسول الله صلى الله عليه وآله وسلم قد زوج رقية وأم كلثوم من عتبة وعتيبة ابني أبي لهب، فلما أنزل الله عز وجل: ﴿تَبَّتْ يَدَا أَبِي لَهَبٍ﴾، قال أبو لهب لابنيه: رأسي من رءوسكما حرام إن لم تطلقا ابنتي محمد."],[42217,"قالت أم جميل أمهما حمالة الحطب بنت حرب بن أمية لابنيها: إن رقية وأم كلثوم قد صبتا، فطلقاهما."],[42218,"ففعلا، فطلقاهما قبل الدخول بهما."],[42219,"فزوج النبي صلى الله عليه وآله وسلم رقية من عثمان، فلما توفيت زوجه أم كلثوم رضي الله عنهم."],[42220,"وكان نكاحه إياها في ربيع الأول من سنة ثلاث، وبنى بها في جمادى الآخرة من السنة، ولم تلد منه ولدًا، وتوفيت سنة تسع، وصلى عليها رسول الله صلى الله عليه وآله وسلم وهي التي غسلتها أم عطية وحكت قول رسول الله صلى الله عليه وآله وسلم: «اغسلنها ثلاثًا، أو خمسًا، أو أكثر»."],[42221,"وألقى إليهم حقوه، وقال: «أشعرنها إياه»، ونزل في قبلها علي، والفضل، وأسامة بن زيد، وقيل: إن أبا طلحة الأنصاري استأذن رسول الله صلى الله عليه وآله وسلم في أن ينزل معهم، فأذن له، وقال: «لو أن لنا ثالثة لزوجنا عثمان بها»."],[42222,"وروى سعيد بن المسيب: أن النبي صلى الله عليه وآله وسلم رأى عثمان بعد وفاة رقية مهمومًا لهفان، فقال له: «ما لي أراك مهمومًا؟» فقال: يا رسول الله، وهل دخل على أحد ما دخل علي، ماتت ابنة رسول الله صلى الله عليه وآله وسلم التي كانت عندي، وانقطع ظهري، وانقطع الصهر بيني وبينك."],[42223,"فبينما هو يحاوره إذ قال النبي صلى الله عليه وآله وسلم: «يا عثمان، هذا جبريل عليه السلام يأمرني عن الله عز وجل أن أزوجك أختها أم كلثوم على مثل صداقها، وعلى مثل عشرتها»."],[42224,"فزوجه إياها."],[42225,"أخرجها الثلاثة، واستدركها أبو موسى على ابن منده، وقد أخرجها ابن منده في بنات رسول الله صلى الله عليه وآله وسلم وأخرجها في الكاف مختصرًا، فليس لاستدراكه وجه، والله أعلم."],[42226,"٧٥٨٢ - أم كلثوم بنت أبي سلمة"],[42227,"ب د ع: أم كلثوم بنت أبي سلمة بن عبد الأسد المخزومية، ربيبة رسول الله صلى الله عليه وآله وسلم أمها أم سلمة."],[42228,"أخبرنا يحيى بن أبي الرجاء، إجازة بإسناده، عن ابن أبي عاصم: حدثنا الصلت بن مسعود، حدثنا مسلم بن خالد، عن موسى بن عقبة، عن أمه، عن أم كلثوم بنت أبي سلمة، قالت: لما تزوج النبي صلى الله عليه وآله وسلم أم سلمة، قال لها: «إني قد أهديت للنجاشي هدية، ولا أراها إلا سترجع إلينا، النجاشي قد مات فيما أرى، أهديت له حلة وأواقي من مسك فإن رجعت إلينا فهي لك»."],[42229,"قالت أم سلمة: فكان كما قال النبي صلى الله عليه وآله وسلم مات النجاشي، ورجعت الهدية إلى رسول الله صلى الله عليه وآله وسلم فبعث إلى كل امرأة من نسائه أوقية من المسك، وبعث إلى أم سلمة بالحلة، وبما بقي من المسك أخرجها الثلاثة إلا أن ابن منده لم ينسبها، إنما قال أم كلثوم غير منسوبة، وذكر لها هذا الحديث في الهدية، وهي هذه، والله أعلم."],[42230,"٧٥٨٣ - أم كلثوم بنت سهيل"],[42231,"أم كلثوم بنت سهيل بن عمرو أسلمت أول الإسلام."],[42232,"أخبرنا عبيد الله بن أحمد، بإسناده عن يونس، عن ابن إسحاق، في تسمية من هاجر إلى أرض الحبشة: وأبو سبرة بن أبي رهم، من بني عامر بن لؤي، معه امرأته أم كلثوم بنت سهيل بن عمرو وقد ذكرناها في ترجمة زوجها."],[42233,"٧٥٨٤ - أم كلثوم بنت العباس"],[42234,"د ع: أم كلثوم بنت العباس بن عبد المطلب أدركت النبي صلى الله عليه وآله وسلم وأمها أم سلمة بنت محمية بن جزء الزبيدي."],[42235,"روى الدرواردي، عن يزيد بن الهاد، عن محمد بن إبراهيم، عن أم كلثوم بنت العباس، قالت: قال رسول الله صلى الله عليه وآله وسلم: «إذا اقشعر جلد العبد من خشية الله تعالى، تحاتت عنه خطاياه، كما يتحات عن الشجرة البالية ورقها»."],[42236,"كذا رواه ابن منده من حديث إسماعيل بن عبد الله بن مسعود، عن ضرار بن صرد، عن الدراوردي."],[42237,"ورواه أبو نعيم من حديث الحسين بن جعفر القتات."],[42238,"عن ضرار، عن الدراوردي، عن يزيد، عن محمد بن إبراهيم، عن أم كلثوم، عن أبيها العباس."],[42239,"وكأنه رأى هذا أصح."],[42240,"وتزوج الحسن بن علي أم كلثوم هذه، فولدت له محمدًا وجعفرًا، ثم فارقها فتزوجها أبو موسى الأشعري، فولدت له موسى."],[42241,"ومات عنها فتزوجها عمران بن طلحة، ففارقها فرجعت إلى دار أبي موسى، فماتت فدفنت بظاهر الكوفة."],[42242,"٧٥٨٥ - أم كلثوم بنت عقبة"],[42243,"ب د ع: أم كلثوم بنت عقبة بن أبي معيط بن أبي عمرو بن أمية بن عبد شمس القرشية الأموية أخت الوليد بن عقبة، واسم أبي معيط: أبان، واسم أبي عمرو: ذكوان."],[42244,"وأمها أروى بنت كريم بن ربيعة بن حبيب بن عبد شمس، عمة عبد الله بن عامر."],[42245,"وهي أخت عثمان بن عفان لأمه."],[42246,"أسلمت بمكة قديمًا، وصلت القبلتين، وبايعت رسول الله صلى الله عليه وآله وسلم وهاجرت إلى المدينة ماشية، فسار أخواها الوليد وعمارة أبنا عقبة خلفها ليرداها، فمنعها الله تعالى."],[42247,"أخبرنا عبيد الله بن أحمد، بإسناده عن يونس بن بكير، عن ابن إسحاق، قال: حدثني الزهري وعبد الله بن أبي بكر بن حزم، قالا: هاجرت أم كلثوم بنت عقبة إلى رسول الله صلى الله عليه وآله وسلم عام الحديبية، فجاء أخواها الوليد وفلان ابنا عقبة إلى رسول الله صلى الله عليه وآله وسلم يطلبانها، فأبى أن يردها عليهما وقال المفسرون: فيها نزلت: ﴿يَأَيُّهَا الَّذِينَ آمَنُوا إِذَا جَاءَكُمُ الْمُؤْمِنَاتُ مُهَاجِرَاتٍ فَامْتَحِنُوهُنَّ اللَّهُ أَعْلَمُ بِإِيمَانِهِنَّ﴾."],[42248,"الآية."],[42249,"ولما قدمت المدينة تزوجها زيد بن حارثة، فقتل عنها يوم مؤتة، فتزوجها الزبير بن العوام، فولدت له زينب، ثم طلقها فتزوجها عبد الرحمن بن عوف، فولدت له إبراهيم وحميدًا، وغيرهما، ومات عنها."],[42250,"فتزوجها عمرو بن العاص، فمكثت عنده شهرًا، ثم ماتت."],[42251,"روى عنها ابنها حميد بن عبد الرحمن."],[42252,"أخبرنا غير واحد عن أبي عيسى: حدثنا أحمد بن منيع، حدثنا إسماعيل بن إبراهيم، عن معمر، عن الزهري، عن حميد بن عبد الرحمن، عن أمه أم كلثوم بنت عقبة أنها سمعت النبي صلى الله عليه وآله وسلم يقول: «ليس بالكاذب من أصلح بين الناس، فقال خيرا»."],[42253,"أخرجها الثلاثة"],[42254,"٧٥٨٦ - أم كلثوم بنت علي بن أبي طالب"],[42255,"ب: أم كلثوم بنت علي بن أبي طالب، أمها فاطمة بنت رسول الله صلى الله عليه وآله وسلم ولدت قبل وفاة رسول الله صلى الله عليه وآله وسلم. خطبها عمر بن الخطاب إلى أبيها علي، فقال: إنها صغيرة."],[42256,"فقال عمر: زوجنيها يا أبا الحسن فإني أرصد من كرامتها ما لا يرصده أحد."],[42257,"فقال له علي: أنا أبعثها إليك، فإن رضيتها فقد زوجتكها."],[42258,"فبعث إليها ببرد، وقال لها: قولي له: هذا البرد الذي قلت لك."],[42259,"فقالت ذلك لعمر، فقال: قولي له: قد رضيت رضي الله عنك."],[42260,"ووضع يده عليها، فقالت: أتفعل هذا؟! لولا أنك أمير المؤمنين لكسرت أنفك، ثم جاءت أباها فأخبرته الخبر، وقالت له: بعثتني إلى شيخ سوء."],[42261,"قال: يا بنية إنه زوجك."],[42262,"فجاء عمر فجلس إلى المهاجرين في الروضة، وكان يجلس فيها المهاجرون الأولون، فقال: رفئوني."],[42263,"فقالوا: بماذا يا أمير المؤمنين؟ قال: تزوجت أم كلثوم بنت علي، سمعت رسول الله صلى الله عليه وآله وسلم يقول: «كل سبب ونسب وصهر ينقطع يوم القيامة، إلا سببي ونسبي وصهري»."],[42264,"وكان لي به عليه الصلاة والسلام النسب والسبب، فأردت أن أجمع إليه الصهر."],[42265,"فرفئوه، فتزوجها على مهر أربعين ألفًا، فولدت له زيد بن عمر الأكبر، ورقية."],[42266,"وتوفيت أم كلثوم وابنها زيد في وقت واحد، وكان زيد قد أصيب في حرب كانت بين بني عدي، خرج ليصلح بينهم، فضربه رجل منهم في الظلمة فشجه وصرعه، فعاش أيامًا ثم مات هو وأمه، وصلى عليهما عبد الله بن عمر، قدمه حسن بن علي."],[42267,"ولما قتل عنها عمر تزوجها عون بن جعفر."],[42268,"أخبرنا عبد الوهاب بن علي بن علي الأمين، أخبرنا أبو الفضل محمد بن ناصر، أخبرنا الخطيب أبو طاهر محمد بن أحمد بن أبي الصقر، أخبركم أبو البركات أحمد بن عبد الواحد بن الفضل بن نظيف بن عبد الله الفراء، قلت له: أخبركم أبو محمد الحسن بن رشيق؟ فقال: نعم، حدثنا أبو بشر محمد بن أحمد بن حماد الدولابي، حدثنا أحمد بن عبد الجبار، حدثنا يونس بن بكير، عن ابن إسحاق، عن حسن بن حسن بن علي بن أبي طالب، قال: لما تأيمت أم كلثوم بنت علي من عمر بن الخطاب، رضي الله عنهم، دخل عليها حسن وحسين أخواها، فقالا لها: إنك ممن قد عرفت سيدة نساء المسلمين وبنت سيدتهن، وإنك والله إن أمكنت عليا من رمتك لينكحنك بعض أيتامه، ولئن أردت أن تصيبي بنفسك مالًا عظيمًا لتصيبينه، فوالله ما قاما حتى طلع علي يتكئ على عصاه، فجلس فحمد الله وأثنى عليه، وذكر منزلتهم من رسول الله صلى الله عليه وآله وسلم وقال: قد عرفتم منزلتكم عندي يا بني فاطمة، وأثرتكم على سائر ولدي، لمكانكم من رسول الله صلى الله عليه وآله وسلم وقرابتكم منه."],[42269,"فقالوا: صدقت، رحمك الله، فجزاك الله عنا خيرًا."],[42270,"فقال: أي بنية، إن الله عز وجل قد جعل أمرك بيدك، فأنا أحب أن تجعليه بيدي، فقالت: أي أبة، إني لامرأة أرغب فيما يرغب فيه النساء، وأحب أن أصيب مما تصيب النساء من الدنيا، وأنا أريد أن أنظر في أمر نفسي."],[42271,"فقال: لا، والله يا بنية ما هذا من رأيك، ما هو إلا رأي هذين، ثم قام فقال: والله لا أكلم رجلًا منهما أو تفعلين، فأخذا بثيابه، فقالا: اجلس يا أبة."],[42272,"فوالله ما على هجرتك من صبر، اجعلي أمرك بيده."],[42273,"فقالت: قد فعلت."],[42274,"قال: فإني قد زوجتك من عون بن جعفر، وإنه لغلام، وبعث لها بأربعة ألف درهم، وأدخلها عليه."],[42275,"أخرجها أبو عمر"],[42276,"حرف اللام وحرف الميم"],[42277,"٧٥٨٧ - أم ليلى بنت رواحة"],[42278,"ب د ع: أم ليلى بنت رواحة الأنصارية امرأة أبي ليلى، وهي والدة عبد الرحمن بن أبي ليلى."],[42279,"بايعت النبي صلى الله عليه وآله وسلم روى حديثها محمد بن عمران بن أبي ليلى، عن عمته حمادة بنت محمد، عن عمتها آمنة بن عبد الرحمن، عن جدتها أم ليلى، قالت: بايعنا رسول الله صلى الله عليه وآله وسلم فكان فيما أخذ علينا أن نختضب بالغمس."],[42280,"أخرجها الثلاثة."],[42281,"٧٥٨٨ - أم مالك الأنصارية"],[42282,"ب د ع: أم مالك الأنصارية"],[42283,"أخبرنا يحيى بن محمود، إجازة، بإسناده، عن ابن أبي عاصم، حدثنا أبو بكر بن أبي شيبة، حدثنا محمد بن فضيل، عن عطاء بن السائب، عن يحيى بن جعدة، عن رجل حدثه، عن أم مالك الأنصارية، قالت: جاءت بعكة من سمن إلى رسول الله صلى الله عليه وآله وسلم فأمر رسول الله صلى الله عليه وآله وسلم بلالًا فعصرها ثم دفعها إليها فرفعتها فإذا هي مملوءة فأتت النبي صلى الله عليه وآله وسلم فقالت: يا رسول الله، نزل في شيء؟ قال: «وما ذاك يا أم مالك؟»، قالت: رددت علي هديتي، قالت: فدعا بلالًا فسأله عن ذلك، فقال: والذي بعثك بالحق لقد عصرتها حتى استحييت، فقال: «هنيئًا لك يا أم مالك، هذه بركة والله عجل ثوابها»، ثم علمها أن تقول في دبر كل صلاة: سبحان الله عشرًا، والحمد لله عشرًا، والله أكبر عشرًا روى عنها عبد الرحمن بن سابط."],[42284,"قالت: أتيت رسول الله صلى الله عليه وآله وسلم ولحيي يرعدن من الحمى، فقال: «ما لك يا أم مالك؟» قلت: يا رسول الله أم ملدم فعل الله بها، قال: «لا تسبيها فإن الله يحط عن العبد بها الذنوب كما يتحات ورق الشجر»."],[42285,"أخرجها الثلاثة."],[42286,"٧٥٨٩ - أم مالك البهزية"],[42287,"ب د ع: أم مالك البهزية"],[42288,"أخبرنا إسماعيل وإبراهيم، وغيرهما، بإسنادهم إلى أبي عيسى، قال: حدثنا عمران بن موسى القزاز، حدثنا عبد الوارث بن سعيد، حدثنا محمد بن جحادة، عن رجل، عن طاوس، عن أم مالك البهزية، قالت: ذكر رسول الله صلى الله عليه وآله وسلم فتنة فقربها، فقلت: يا رسول الله، من خير الناس فيها؟ قال: «رجل في ماشية يؤدي حقها ويعبد ربه، ورجل آخذ برأس فرسه يخيف العدو ويخيفونه»."],[42289,"أخرجها الثلاثة"],[42290,"٧٥٩٠ - أم مبشر بنت البراء بن معرور"],[42291,"ب د ع: أم مبشر بنت البراء بن معرور الأنصارية قيل: إنها زوج زيد بن حارثة."],[42292,"وقيل: غيرها."],[42293,"روى عنها جابر بن عبد الله، وغيره، روت عن رسول الله صلى الله عليه وآله وسلم أحاديث، منها ما"],[42294,"أخبرنا به يحيى، كتابة، بإسناده عن ابن أبي عاصم."],[42295,"حدثنا أبو بكر بن أبي شيبة ومحمد بن عبد الله بن نمير، قال: حدثنا عبد الله بن إدريس، عن الأعمش، عن أبي سفيان، عن جابر، عن أم مبشر، أنها سمعت النبي صلى الله عليه وآله وسلم يقول في بيت حفصة: «لا يدخل النار أحد شهد بدرًا والشجرة»."],[42296,"فقالت حفصة: يا رسول الله إن الله يقول: ﴿وَإِنْ مِنْكُمْ إِلا وَارِدُهَا﴾؟ فقال رسول الله صلى الله عليه وآله وسلم: «فمه؟ ﴿ثُمَّ نُنَجِّي الَّذِينَ اتَّقَوْا﴾»"],[42297,"وروى محمد بن إسحاق، عن ابن أبي نجيح، عن مجاهد، عن أم مبشر بنت البراء بن معرور، قالت: سمعت رسول الله صلى الله عليه وآله وسلم يقول لأصحابه: «ألا أخبركم بخير الناس؟» قالوا: بلى يا رسول الله."],[42298,"قال: «رجل في غنيمة له، يقيم الصلاة، ويؤتي الزكاة، قد اعتزل شرور الناس»."],[42299,"أخرجها الثلاثة."],[42300,"وذكر ابن منده، وأبو نعيم هذين الحديثين في ترجمة واحدة، وجعلا الاثنتين، هذه والتي بعدها واحدة."],[42301,"وأخرج أبو نعيم حديث جابر، عن امرأة زيد، وأخرج حديث مجاهد، عن بنت البراء بن معرور، وجعلهما ترجمتين، والله أعلم، وما أقرب أن يكونا واحدة."],[42302,"٧٥٩١ - أم مبشر الأنصارية، امرأة زيد بن حارثة"],[42303,"ع س: أم مبشر الأنصارية، امرأة زيد بن حارثة."],[42304,"قيل: إنها المتقدمة الذكر بنت البراء بن معرور."],[42305,"وقيل: هي غيرها."],[42306,"وأخرج أبو نعيم، وأبو موسى هذه غير الأولى بنت البراء، وقد تقدم القول فيها في الأولى."],[42307,"وقد فرق ابن أبي عاصم أيضا بينهما، جعلهما اثنتين، فذكر في ترجمة بنت البراء فضل من شهد بدرًا، وذكر في هذه"],[42308,"ما أخبرنا به ابن أبي حبة، وأبو الفرج بن أبي الرجاء، بإسنادهما إلى مسلم بن الحجاج: حدثنا قتيبة، حدثنا الليث ح، قال مسلم: وحدثنا محمد بن رمح، أخبرنا الليث، عن أبي الزبير، عن جابر، أن النبي صلى الله عليه وآله وسلم دخل على أم مبشر الأنصارية في نخل لها، فقال لها النبي صلى الله عليه وآله وسلم: «من غرس هذا النخيل، أمسلم أم كافر؟» قالت: بل مسلم، فقال: «لا يغرس مسلم غرسًا، ولا يزرع زرعًا، فيأكل منه إنسان أو دابة أو شيء إلا كانت له صدقة» وقد ذكر أحمد بن حنبل في مسنده الحديثين في ترجمة أم مبشر امرأة زيد بن حارثة، إلا أنه لم ينسبها إلى البراء بن معرور، بل قال: أم مبشر، امرأة زيد بن حارثة."],[42309,"وروى لها الحديثين، وهذا يدل أنه رآهما واحدة، والله أعلم."],[42310,"٧٥٩٢ - أم محجن"],[42311,"س: أم محجن روى ابن بريدة، عن أبيه، أن النبي صلى الله عليه وآله وسلم مر على قبر حديث عهد بدفن، فقال: «متى دفن هذا؟» فقيل: يا رسول الله، هذه أم محجن، كانت مولعة بلقط القذى في المسجد، قال: «أفلا آذنتموني؟!» قالوا: كنت نائمًا، فكرهنا أن نهيجك."],[42312,"قال: «فلا تفعلوا، فإن صلاتي على موتاكم تنور لهم في قبورهم؟»."],[42313,"قال: فصف أصحابه فصلى عليها."],[42314,"ورواه يحيى بن أبي أنيسة، عن علقمة، عن رجل من أهل المدينة، مرسلًا: وسمى المرأة محجنة."],[42315,"أخرجها أبو موسى."],[42316,"٧٥٩٣ - أم محمد الأنصارية"],[42317,"س: أم محمد الأنصارية روى عمر بن ذر، عن عبيد الله بن الحبحاب، عن أم محمد الأنصارية، قالت: سمعت رسول الله صلى الله عليه وآله وسلم يقول: «من قال عند مطعمه ومشربه: بسم الله خير الأسماء، بسم الله رب الأرض والسماء، بسم الله الذي لا يضر مع اسمه شيء، لم يضره ما أكل أو شرب»."],[42318,"أخرجها أبو موسى."],[42319,"٧٥٩٤ - أم محمد بن حاطب"],[42320,"س: أم محمد بن حاطب بن الحارث."],[42321,"وهي: أم جميل بنت المجلل ذكرت في الجيم من الكنى."],[42322,"قيل: اسمها فاطمة."],[42323,"قاله جعفر، وإنما قيل لها أم محمد بابنها، محمد بن حاطب، وهو قليل."],[42324,"أخرجها أبو موسى"],[42325,"٧٥٩٥ - أم محمد خولة بنت قيس"],[42326,"س: أم محمد خولة بنت قيس روى آدم بن أبي إياس، عن أبي معشر، عن سعيد المقبري، عن عبيد سنوطي، قال: دخلنا على خولة بنت قيس، وكانت تحت حمزة بن عبد المطلب رضي الله عنه، فتزوجها بعده النعمان بن عجلان، فقلنا: يا أم محمد، حدثينا."],[42327,"فقال لها زوجها النعمان: انظري ماذا تحدثين فإن الحديث عن رسول الله صلى الله عليه وآله وسلم بغير ثبت شديد، فقالت: بئس مالي!"],[42328,"أحدثهم عن رسول الله صلى الله عليه وآله وسلم بما ينفعهم فأكذب على رسول الله صلى الله عليه وآله وسلم سمعت رسول الله صلى الله عليه وآله وسلم يقول: «الدنيا خضرة حلوة، من أخذ مالًا بحله يبارك له فيه، ورب متخوض في مال الله عز وجل ومال رسول الله صلى الله عليه وآله وسلم فيما شاءت نفسه له النار يوم القيامة»."],[42329,"أخرجها أبو موسى."],[42330,"٧٥٩٦ - أم مرثد"],[42331,"ب د ع: أم مرثد الأسلمية، وقيل: الغنوية أسلمت يوم الفتح، وبايعت النبي صلى الله عليه وآله وسلم يوم الفتح."],[42332,"روت عنها أم خارجة بنت سعد بن الربيع امرأة زيد بن ثابت، أنها قالت: خرجنا مع رسول الله صلى الله عليه وآله وسلم وهو في ناس من الأنصار في رعل، والرعل: النخل، فقال رسول الله صلى الله عليه وآله وسلم: «إن أول من يشرف عليكم، من تسمعون خشخشته بهذا الوادي، لمن أهل الجنة»."],[42333,"فأشرف عليهم علي بن أبي طالب."],[42334,"رواه مكي بن إبراهيم، عن أبي بكر بن عبد الله بن أبي ربيعة، عن أم خارجة، عن النبي صلى الله عليه وآله وسلم مثله."],[42335,"ولم يذكر أم مرثد."],[42336,"وقد تقدم ذكرها."],[42337,"أخرجها الثلاثة."],[42338,"٧٥٩٧ - أم مسطح"],[42339,"ب س: أم مسطح بنت أبي رهم بن المطلب بن عبد مناف القرشية المطلبية واسم أبي رهم أنيس، بفتح الهمزة، وكسر النون، وهي ابنة خالة أبي بكر الصديق، أمها بنت صخر بن عامر، يقال: اسمها سلمى بنت صخر ابن عامر بن كعب بن سعد بن تيم بن مرة."],[42340,"لهذا ذكر في حديث الإفك."],[42341,"أخرجها أبو عمر، وأبو موسى."],[42342,"٧٥٩٨ - أم مسعود بن الحكم"],[42343,"ب د ع: أم مسعود بن الحكم روى محمد بن إسحاق، عن حكيم بن حكيم بن عباد بن حنيف، عن مسعود بن الحكم، عن أمه أنها حدثت، قالت: كأني أنظر إلى علي بن أبي طالب على بغلة رسول الله صلى الله عليه وآله وسلم البيضاء في شعب الأنصار وهو يقول: أيها الناس، إن رسول الله صلى الله عليه وآله وسلم قال: «أيها الناس، إنها أيام أكل وشرب»."],[42344,"ورواه يزيد بن الهاد عن عبد الله بن أبي سلمة فقال: عن عمرو بن سليم، عن أمه."],[42345,"وقد ذكرناها."],[42346,"أخرجها الثلاثة."],[42347,"٧٥٩٩ - أم مسلم الأشجعية"],[42348,"ب د ع: أم مسلم الأشجعية لها صحبة، حديثها عند أهل الكوفة."],[42349,"أخبرنا أبو ياسر، بإسناده عن عبد الله، حدثني أبي، حدثنا عبد الرحمن بن مهدي، حدثنا سفيان، عن حبيب بن أبي ثابت، عن رجل من بني المصطلق، عن أم مسلم الأشجعية."],[42350,"أن رسول الله صلى الله عليه وآله وسلم أتاها وهي في قبة من أدم، فقال: «ما أحسنها إن لم يكن فيها ميتة!» قالت: فجعلت أتتبعها."],[42351,"أخرجها الثلاثة"],[42352,"٧٦٠٠ - أم مسلم خادم صفية"],[42353,"د ع: أم مسلم خادم صفية ذكرت في الصحابة، ولا يعرف لها صحبة."],[42354,"أخرجها ابن منده، وأبو نعيم مختصرًا."],[42355,"٧٦٠١ - أم المسيب"],[42356,"ع س: أم المسيب."],[42357,"وقيل: أم السائب الأنصارية"],[42358,"أخبرنا أبو موسى، كتابة، أخبرنا أبو علي، حدثنا أحمد بن جعفر بن معبد، حدثنا يحيى بن مطرف، حدثنا مسلم بن إبراهيم، حدثنا الحسن بن أبي جعفر، حدثنا أبو الزبير، عن جابر: أن النبي صلى الله عليه وآله وسلم أتى على امرأة من الأنصار يقال لها أم المسيب، وهي ترفرف من الحمى، فقال لها النبي صلى الله عليه وآله وسلم: «ما لك؟» قالت: الحمى، لا بارك الله فيها."],[42359,"فقال لها النبي صلى الله عليه وآله وسلم: «لا تسبيها فإنها تذهب الذنوب كما يذهب الكير خبث الحديد»."],[42360,"رواه عبد الوهاب الثقفي، عن أيوب، عن الزبير، عن جابر."],[42361,"وقال: يقال لها أم السائب."],[42362,"أخرجها أبو نعيم، وأبو موسى"],[42363,"٧٦٠٢ - أم مطاع الأسلمية"],[42364,"ب د ع: أم مطاع الأسلمية مدنية."],[42365,"حديثها عند عطاء بن أبي مروان، عن أبيه، عنها: أنها شهدت خيبر مع رسول الله صلى الله عليه وآله وسلم فأسهم لها سهم رجل."],[42366,"أخرجها الثلاثة، وقال أبو عمر: شهودها خيبر صحيح، وفي سهم الرجل نظر."],[42367,"٧٦٠٣ - أم معاذ"],[42368,"س: أم معاذ روى أيوب السختياني، عن حفصة بنت سيرين، عن أم عطية، قالت: بايعنا رسول الله صلى الله عليه وآله وسلم على أن لا نشرك بالله شيئا، ونهى عن النياحة، فقبضت امرأة يدها، فما قال لها رسول الله صلى الله عليه وآله وسلم شيئًا، فانطلقت فرجعت فبايعها، فما وفت امرأة إلا أم سليم، وأم العلاء بنت أبي سبرة، وأم معاذ."],[42369,"أو قال: ابنة أبي سبرة، وامرأة معاذ."],[42370,"أخرجها أبو موسى."],[42371,"٧٦٠٤ - أم معاذ الأنصارية"],[42372,"د ع: أم معاذ الأنصارية روى محمد بن إسحاق، عن عبد الله بن عبد الله بن الحارث، عن سالم أبي النضر، قال: دخل رسول الله صلى الله عليه وآله وسلم على عثمان بن مظعون وهو يموت، فأمر رسول الله صلى الله عليه وآله وسلم بثوب فسجي عليه، وكان عثمان نازلًا على امرأة من الأنصار، يقال لها أم معاذ، فمكث رسول الله صلى الله عليه وآله وسلم متكئًا عليه طويلا ً، ثم تنحى فبكى، فبكى أهل البيت، فقال: «إلى رحمة الله أبا السائب»."],[42373,"وكان السائب ابنه قد شهد معه بدرًا، قالت أم معاذ: هنيئًا لك أبا السائب الجنة."],[42374,"فقال رسول الله صلى الله عليه وآله وسلم: «وما يدريك يا أم معاذ، ما هو فقد جاءه اليقين، ولا نعلم إلا خيرًا»."],[42375,"قالت: لا، والله لا أقولها لأحد بعده أبدًا."],[42376,"أخرجها ابن منده، وأبو نعيم."],[42377,"٧٦٠٥ - أم معاذ بنت خالد"],[42378,"ع س: أم معبد بنت خالد الخزاعية الكعبية، واسمها عاتكة وهي أخت حبيش بن خالد."],[42379,"وهي التي نزل عليها رسول الله صلى الله عليه وآله وسلم لما هاجر إلى المدينة."],[42380,"وقد تقدمت قصة نزوله عليها، وما ظهر لها من معجزاته صلى الله عليه وآله وسلم. أخرجها أبو نعيم، وأبو موسى."],[42381,"٧٦٠٦ - أم معبد مولاة قرظة"],[42382,"ب د ع: أم معبد مولاة قرظة بن كعب في صحبتها خلاف."],[42383,"روى موسى بن محمد الأنصاري، عن يحيى بن الحارث التيمي، عن أم معبد مولاة قرظة بن كعب الأنصاري، قالت: كنت أسقي أناسًا من أصحاب النبي صلى الله عليه وآله وسلم منهم زيد بن أرقم ومعاذ بن جبل نبيذ الذرة، فقيل لها: فأين ما تذكرين من المزفت؟ فقالت: على الخبير سقط، إن المحرم لما أحل كالمستحل لما حرم الله، أما الدباء فهو القزع الذي نهى عنه رسول الله صلى الله عليه وآله وسلم وأما الحنتم فحناتم بأرض العجم، فهو الذي نهى عنه رسول الله صلى الله عليه وآله وسلم وأما النقير فأصول النخل المحفرة النابتة في الأرض، فهي التي نهى عنها رسول الله صلى الله عليه وآله وسلم. أخرجها ابن منده، وأبو نعيم."],[42384,"٧٦٠٧ - أم معبد زوج كعب بن مالك"],[42385,"ب د ع: أم معبد زوج كعب بن مالك الأنصارية وكانت ممن صلت القبلتين، وهي أم معبد بن كعب."],[42386,"روى يزيد بن زريع، عن محمد بن إسحاق، عن معبد بن كعب، عن أمه، وكانت قد صلت القبلتين، قالت: قال رسول الله صلى الله عليه وآله وسلم: «لا تنتبذوا التمر والزبيب جميعًا، انتبذوا كل واحد على حدته»."],[42387,"أخرجها الثلاثة."],[42388,"٧٦٠٨ - أم معبد"],[42389,"ب ع س: أم معبد غير منسوبة."],[42390,"قاله أبو نعيم."],[42391,"وقال أبو عمر: أنصارية."],[42392,"أخبرنا أبو موسى، إذنًا، أخبرنا أبو علي، أخبرنا أبو نعيم، حدثنا محمد بن نصر، حدثنا محمد بن عبد الله بن الحسن، حدثنا محمد بن بكير الحضرمي، حدثنا الفرج بن فضالة، عن الإفريقي، عن مولى أم معبد، عن أم معبد، أن النبي صلى الله عليه وآله وسلم كان يدعو: «اللهم طهر قلبي من النفاق، وعملي من الرياء، ولساني من الكذب، وعيني من الخيانة فإنك تعلم خائنة الأعين وما تخفي الصدور»."],[42393,"أخرجها أبو نعيم، وأبو عمر، وأبو موسى"],[42394,"٧٦٠٩ - أم معقل الأسدية"],[42395,"ب د ع: أم معقل الأسدية، من أسد بن خزيمة، وقيل: الأشجعية."],[42396,"وقيل: الأنصارية."],[42397,"أخبرنا أبو أحمد بن سكينة، بإسناده عن أبي داود سليمان بن الأشعث: حدثنا أبو كامل، حدثنا أبو عوانة، عن إبراهيم بن مهاجر، عن أبي بكر بن عبد الرحمن بن الحارث بن هشام، قال: أخبرني رسول مروان الذي أرسل إلى أم معقل، قالت: جاء أبو معقل حاجا مع رسول الله صلى الله عليه وآله وسلم فلما قدم، قالت أم معقل: قد علمت أن علي حجة فانطلقا يمشيان حتى دخلا عليه، فقالت: يا رسول الله، إن علي حجة، وإن لأبي معقل بكرًا."],[42398,"قال أبو معقل: صدقت، جعلته في سبيل الله."],[42399,"فقال رسول الله صلى الله عليه وآله وسلم: «فلتحج عليه، فإنه في سبيل الله عز وجل»."],[42400,"فأعطاها البكر، فقالت: يا رسول الله، إني امرأة قد كبرت وسقمت، فهل من عمل يجزي عني من حجتي؟ قال: «عمرة في رمضان تعدل حجة»."],[42401,"ورواه عن أبي بكر بن عبد الرحمن عمارة بن عمير، وجامع بن شداد، وسمي مولاه، والزهري فقال: جاء معقل أو أبو معقل إلى النبي صلى الله عليه وآله وسلم فقال: يا رسول الله، إن أم معقل جعلت عليها الحج معك، فلم يتيسر لها، فما يعدل الحجة معك؟ فقال: «عمرة في رمضان»."],[42402,"ورواه ابن إسحاق، عن عيسى بن معقل بن أبي معقل، عن يوسف بن عبد الله بن سلام، عن جدته أم معقل، نحوه."],[42403,"أخرجها الثلاثة"],[42404,"٧٦١٠ - أم مغيث"],[42405,"ب د ع: أم مغيث لها صحبة."],[42406,"صلت القبلتين."],[42407,"روى إسحاق بن عبد الله بن أبي فروة، عن محمد بن يوسف، عن أبيه، عن أم مغيث: أنها سمعت رسول الله صلى الله عليه وآله وسلم نهى عن الخليطين."],[42408,"فقلت: وما هما؟ قال: «التمر والزبيب»."],[42409,"وكانت أم مغيث جدة ربيعة بن عبد الرحمن، أم أمه."],[42410,"أخرجها الثلاثة."],[42411,"٧٦١١ - أم المغيرة"],[42412,"س: أم المغيرة بنت نوفل بن الحارث بن عبد المطلب ذكرناها في ترجمة أبي البراد، زوجها رسول الله صلى الله عليه وآله وسلم من تميم الداري."],[42413,"أخرجها أبو موسى."],[42414,"٧٦١٢ - أم المنذر"],[42415,"ب د ع: أم المنذر بنت قيس الأنصارية."],[42416,"وقيل: العدوية قاله أبو عمر."],[42417,"قيل: اسمها سلمى."],[42418,"حديثها عند أهل المدينة، قاله أبو عمر."],[42419,"وقال أبو نعيم: هي أخت سليط بن قيس، من بني مازن بن النجار."],[42420,"إحدى خالات النبي صلى الله عليه وآله وسلم صلت معه القبلتين."],[42421,"أخبرنا أبو أحمد عبد الوهاب بن علي، بإسناده عن سليمان بن الأشعث، حدثنا هارون بن عبد الله، حدثنا أبو داود وأبو عامر، لفظ أبي عامر عن فليح بن سليمان، عن أيوب بن عبد الرحمن بن عبد الله بن أبي صعصعة، عن يعقوب بن أبي يعقوب، عن أم المنذر بنت قيس الأنصارية، قالت: دخل علي رسول الله صلى الله عليه وآله وسلم ومعه على، وعلي ناقة ولنا دوالي معلقة، فقام رسول الله صلى الله عليه وآله وسلم يأكل منها، وقام علي ليأكل، فطفق رسول الله صلى الله عليه وآله وسلم يقول لعلي: «مه، إنك ناقه»."],[42422,"حتى كف علي، قالت: وصنعت شعيرًا وسلقًا، فجئت به، فقال رسول الله صلى الله عليه وآله وسلم: «يا علي، من هذا فأصب، فإنه أوفق لك»."],[42423,"وروى محمد بن إسحاق، عن سليط بن أيوب، عن أمه، عن سلمى بنت قيس أم المنذر."],[42424,"أخرجها الثلاثة. قلت: قوله أنصارية وعدوية ولا فرق بينهما فإن عدي بن النجار من الأنصار، وجعلها أبو عمر عدوية، وجعلها أبو نعيم من بني مازن بن النجار، ثم قال: إحدى خالات النبي صلى الله عليه وآله وسلم. فهذا يقوي قول أبي عمر، لأن أخوال النبي صلى الله عليه وآله وسلم بنو عدي بن النجار، والله أعلم."],[42425,"٧٦١٣ - أم منظور"],[42426,"أم منظور بنت محمد بن مسلمة بن سلمة بن خالد بن عدي الأنصارية بايعت رسول الله صلى الله عليه وآله وسلم. قاله ابن حبيب."],[42427,"٧٦١٤ - أم منيع"],[42428,"ب ع س: أم منيع الأنصارية."],[42429,"قيل هي أم شباث."],[42430,"قيل اسمها أسماء بنت عمرو بن عدي بن نابي بن عمرو بن سواد بن غنم بن كعب ابن سلمة شهدت العقبة هي وأم عمارة نسيبة، ولم يشهدها من النساء غيرهما."],[42431,"أخرجها أبو نعيم، وأبو عمر، وأبو موسى."],[42432,"حرف النون"],[42433,"٧٦١٥ - أم نائلة"],[42434,"د ع: أم نائلة الخزاعية."],[42435,"روت عنها أم الأسود الخزاعية."],[42436,"روى إبراهيم بن نصر، عن مسلم بن إبراهيم، عن أم الأسود الخزاعية، عن أم نائلة الخزاعية: أن النبي صلى الله عليه وآله وسلم سأل عن رجل يقال له: قيس، فقال: «لا أقرته الأرض»."],[42437,"فكان لا يدخل أرضًا فيستقر فيها حتى يخرج منها."],[42438,"أخرجها ابن منده أبو نعيم، وقال أبو نعيم: ذكرها المتأخر، يعني ابن منده، وأسقط بريدة، واسمها نائلة الخزاعية، وروى عن عبد الله بن جعفر، عن إسماعيل بن عبد الله، عن مسلم بن إبراهيم، عن أم الأسود الخزاعية، عن بريدة: أن النبي صلى الله عليه وآله وسلم سأل عن رجل."],[42439,"وذكره."],[42440,"٧٦١٦ - أم نبيط"],[42441,"د ع: أم نبيط الأنصارية، اختلف في اسمها."],[42442,"روى عنها ابنها نبيط."],[42443,"أخبرنا الحسن بن محمد بن هبة الله الدمشقي، أخبرنا محمد بن الخليل بن فارس، حدثنا أبو القاسم علي بن محمد بن علي بن أبي العلاء، أخبرنا أبو محمد بن عثمان بن أبي نصر، حدثنا إبراهيم بن محمد بن أبي ثابت، حدثنا يزيد بن محمد، حدثنا عتبة بن الزبير، من ولد كعب بن مالك، حدثنا محمد بن عبد الخالق، من ولد النعمان بن بشير، حدثنا عبد الملك بن نبيط، عن أبيه، عن جده، عن جدته أم نبيط، قالت: أهدينا جارية لنا من بني النجار، ومعي دف أضرب به، وأنا أقول:"],[42444,"أتيناكم أتيناكم … فحيونا نحييكم"],[42445,"لولا الذهب الأحمر … ما حلت بواديكم"],[42446,"قالت: فوقف علنيا رسول الله فقال: «ما هذا يا أم نبيط؟»، فقلت: بأبي أنت وأمي يا رسول الله، جارية منا من بني النجار، نهديها إلى زوجها."],[42447,"قال: «فتقولين ماذا؟»، قالت:"],[42448,"فأعدت عليه، فقال رسول الله صلى الله عليه وآله وسلم: «لولا الحنطة السمراء ما سمن عذاريكم»."],[42449,"أخرجها ابن منده، وأبو نعيم"],[42450,"٧٦١٧ - أم نصر"],[42451,"ب د ع: أم نصر المحاربية روى إبراهيم بن المختار الرازي، عن ابن إسحاق، عن عاصم بن عمر بن قتادة، عن أم نصر المحاربية، قالت: سأل رجل رسول الله صلى الله عليه وآله وسلم عن لحوم الحمر الأهلية، فقال: «أليس ترعى الكلأ وتأكل الشجر؟» قال: بلى، قال: «فأصب من لحومها»."],[42452,"أخرجه الثلاثة، وقال أبو عمر: تفرد به إبراهيم، عن ابن إسحاق، وليس ممن يحتج به، وقد ثبتت الكراهية والنهي عنها من وجوه."],[42453,"حرف الهاء"],[42454,"٧٦١٨ - أم هاشم"],[42455,"ب د ع: أم هاشم، وقيل: أم هشام بنت حارثة بن النعمان الأنصارية بايعت بيعة الرضوان."],[42456,"روى عنها عبد الرحمن بن سعد، وخبيب بن عبد الرحمن، وعمرة."],[42457,"أخبرنا أبو الفرج بن أبي الرجاء وعبد الوهاب بن هبة الله، بإسنادهما عن مسلم بن الحجاج: حدثنا عمرو الناقد، حدثنا يعقوب بن إبراهيم بن سعد، حدثنا أبي، عن محمد بن إسحاق، عن عبد الله بن أبي بكر بن حزم، عن يحيى بن عبد الله بن عبد الرحمن بن سعد بن زرارة، عن أم هشام بنت حارثة بن النعمان، قالت: لقد كان تنورنا وتنور رسول الله صلى الله عليه وآله وسلم واحدًا سنتين، أو: سنة وبعض سنة ما أخذت ق وَالْقُرْءَانِ الْمَجِيدِ إلا من لسان رسول الله صلى الله عليه وآله وسلم وكان رسول الله صلى الله عليه وآله وسلم يقرأ بها كل جمعة إذا خطب الناس."],[42458,"أخرجها الثلاثة"],[42459,"٧٦١٩ - أم هانئ الأنصارية"],[42460,"ب د ع: أم هانئ الأنصارية لا أقف على نسبها."],[42461,"وقد اختلف في اسمها، فقيل: أم قيس، وقيل: أم هانئ، والله أعلم."],[42462,"أخبرنا يحيى بن محمود، بإسناده عن ابن أبي عاصم، حدثنا أبو بكر، حدثنا الحسن بن موسى، حدثنا ابن لهيعة، حدثنا أبو الأسود محمد بن عبد الرحمن بن نوفل، عن درة بنت معاذ، عن أم هانئ الأنصارية: أنها سألت رسول الله صلى الله عليه وآله وسلم أنتزاور إذا متنا، ويرى بعضنا بعضًا؟ فقال النبي صلى الله عليه وآله وسلم: «يكون النسم طيرًا يعلق بالشجر، حتى إذا كان يوم القيامة دخلت كل نفس في جسدها»."],[42463,"أخرجها الثلاثة"],[42464,"٧٦٢٠ - أم هانئ بنت أبي طالب"],[42465,"ب د ع: أم هانئ بنت أبي طالب عبد مناف القرشية الهاشمية بنت عم النبي صلى الله عليه وآله وسلم وأخت علي بن أبي طالب، أمها فاطمة بنت أسد."],[42466,"واختلف في اسمها، فقيل: هند."],[42467,"وقيل: فاطمة."],[42468,"وقيل: فاختة."],[42469,"كانت تحت هبيرة بن أبي وهب بن عمرو بن عائذ بن عمران بن مخزوم المخزومي."],[42470,"أسلمت عام الفتح، فلما أسلمت وفتح رسول الله صلى الله عليه وآله وسلم مكة، هرب هبيرة إلى نجران، وقال حين فر معتذرًا من فراره:"],[42471,"لعمرك ما وليت ظهري محمدًا … وأصحابه جبنًا، ولا خيفة القتل"],[42472,"ولكنني قلبت أمري فلم أجد … لسيفي غناء إن ضربت ولا نبلي"],[42473,"وقفت فلما خفت ضيقة موقفي … رجعت لعود كالهزبر أبي الشبل"],[42474,"قال خلف الأحمر: أبيات هبيرة في الاعتذار خير من قول الحارث بن هشام، يعني قوله:"],[42475,"الله يعلم ما تركت قتالهم … حتى علوا فرسي بأشقر مزبد"],[42476,"وقال الأصمعي: أحسن ما قيل في الاعتذار من الفرار قول الحارث بن هشام."],[42477,"أخبرنا عبيد الله بن أحمد، بإسناده عن يونس بن بكير، عن ابن إسحاق: أن هبيرة أقام بنجران فلما بلغه إسلام أم هانئ وكانت تحته، قال أبياتًا منها:"],[42478,"وعاذلة هبت بليل تلومني … وتعذلني بالليل، ضل ضلالها"],[42479,"وتزعم أني إن أطعت عشيرتي … سأردى، وهل يردين إلا زوالها؟"],[42480,"ومنها يخاطب أم هانئ:"],[42481,"فإن كنت قد تابعت دين محمد … وقطعت الأرحام منك حبالها"],[42482,"فكوني على أعلى سحيق بهضبة … ململمة غبراء يبس بلالها"],[42483,"وهي أكثر من هذا. وولدت أم هانئ لهبيرة عمرًا، وبه كان يكنى هبيرة، وهانئًا ويوسف وجعدة."],[42484,"أخبرنا غير واحد، بإسنادهم عن محمد بن عيسى: حدثنا أبو موسى، حدثنا محمد بن جعفر، حدثنا شعبة، عن عمرو بن مرة، عن عبد الرحمن بن أبي ليلى، قال: ما أخبرني أحد أنه رأى النبي صلى الله عليه وآله وسلم يصلي الضحى إلا أم هانئ، فإنها حدثت أن رسول الله صلى الله عليه وآله وسلم دخل بيتها يوم فتح مكة فاغتسل، فسبح ثماني ركعات، ما رأيته صلى صلاة أخف منها، غير أنه كان يتم الركوع والسجود."],[42485,"أخرجها الثلاثة"],[42486,"٧٦٢١ - أم الهذيل"],[42487,"ع س: أم الهذيل، غير منسوبة."],[42488,"أخبرنا محمد بن أبي بكر المديني، إذنًا، أخبرنا أبو علي، أخبرنا أبو نعيم، حدثنا أبو بحر محمد بن الحسن، حدثنا محمد بن غالب بن حرب، حدثنا هانئ بن يحيى اليشكري، حدثنا الحسن بن أبي جعفر، عن ليث، عن سلم الفقيمي، عن أبيه، عن أم الهذيل، أن رسول الله صلى الله عليه وآله وسلم دخل أرضًا، فرأى راعيًا متجردًا، فقال: «يا فلان، انظر ما كان من ضيعة فافرع واستوف أجرك والحق بأهلك»، فقال: يا رسول الله، ألم أحسن الولاية والقيام على الضيعة؟ قال: «بلى، ولكن لا حاجة بنا فيمن إذا خلي لم يستحي من الله عز وجل»."],[42489,"أخرجها أبو نعيم، وأبو موسى"],[42490,"٧٦٢٢ - أم أبي هريرة"],[42491,"أم أبي هريرة، أسلمت وروى إسلامها أبو هريرة."],[42492,"أخبرنا أبو الفرج بن محمود وأبو ياسر، بإسنادهما إلى أبي الحسين مسلم، حدثنا عمرو الناقد، حدثنا عمرو بن يونس اليمامي، حدثنا عكرمة بن عمار، عن أبي كثير يزيد بن عبد الرحمن، حدثني أبو هريرة، قال: كنت أدعو أمي إلى الإسلام وهي مشركة، فدعوتها يومًا فأسمعتني في رسول الله صلى الله عليه وآله وسلم ما أكره، فأتيت رسول الله صلى الله عليه وآله وسلم وأنا أبكي، فقلت: يا رسول الله، إني كنت أدعوا أمي إلى الإسلام فتأبى علي، وإني دعوتها اليوم فأسمعتني فيك ما أكره، فادع الله أن يهدي أم أبي هريرة، فقال رسول الله صلى الله عليه وآله وسلم: «اللهم اهد أم أبي هريرة»."],[42493,"فخرجت مستبشرًا بدعوة نبي الله صلى الله عليه وآله وسلم فلما جئت فصرت إلى الباب فإذا هو مجاف، فسمعت أمي خشف قدمي فقالت: مكانك يا أبا هريرة، وسمعت خضخضة الماء، قال: ولبست درعها، وعجلت عن خمارها ففتحت الباب، وقالت: يا أبا هريرة، أشهد أن لا إله إلا الله، وأشهد أن محمدًا رسول الله، قال: فرجعت إلى رسول الله صلى الله عليه وآله وسلم فأخبرته، فحمد الله، وقال خيرًا"],[42494,"٧٦٢٣ - أم هشام بنت حارثة"],[42495,"أم هشام بنت حارثة بن النعمان الأنصارية."],[42496,"وقيل: أم هاشم وقد تقدم ذكرها."],[42497,"أخبرنا أبو الفضل بن أبي الحسن الطبري، بإسناده عن أبي يعلى أحمد بن علي قال: حدثنا زهير، حدثنا جرير، عن محمد بن إسحاق، عن عبد الله بن أبي بكر، عن يحيى بن عبد الله، عن أم هشام بنت حارثة بن النعمان، قالت: قرأت ق وَالْقُرْآنِ الْمَجِيدِ من في رسول الله صلى الله عليه وآله وسلم وكان يقرؤها في كل جمعة إذا خطب الناس."],[42498,"قال أبو داود السجستاني: رواه يحيى بن أيوب، وابن أبي الرجال، عن يحيى بن سعيد، عن عمرة، عن أم هشام بنت حارثة بن النعمان"],[42499,"٧٦٢٤ - أم هلال بن بلال"],[42500,"د ع: أم هلال بن بلال ذكرها مسلم بن الحجاج في الصحابة، ولم يذكر لها حديثًا."],[42501,"قاله ابن منده، وقال أبو نعيم: أم هلال بنت بلال، ذكرها المتأخر، وقال: ذكرها مسلم في الصحابة لم يزد عليه."],[42502,"قال أبو نعيم: ووهم فيه، إنما هي أم بلال بنت هلال."],[42503,"وقد تقدم ذكرها في باب الباء."],[42504,"أخرجها ابن منده، وأبو نعيم."],[42505,"ومن العجب أن ابن منده قد أخرجها في الباء أم بلال، وههنا عكس الاسمين!."],[42506,"حرف الواو"],[42507,"٧٦٢٥ - أم ورقة بنت حمزة"],[42508,"س: أم ورقة بنت حمزة بن عبد المطلب قال جعفر: قال محمد بن حبان: اختلفوا في اسمها، فقيل: عمارة."],[42509,"وقيل: أمامة."],[42510,"وقيل: أم الفضل."],[42511,"تقدم ذكرها."],[42512,"أخرجها أبو موسى."],[42513,"٧٦٢٦ - أم ورقة بنت عبد الله"],[42514,"ب د ع: أم ورقة بنت عبد الله بن الحارث بن عويمر الأنصارية."],[42515,"وقيل: أم ورقة بنت نوفل وهي مشهورة بكنيتها، واختلفوا في نسبها."],[42516,"أخبرنا عبد الوهاب بن علي الصوفي، بإسناده عن أبي داود: حدثنا عثمان بن أبي شيبة، حدثنا وكيع، حدثنا الوليد بن عبد الله بن جميع، حدثتني جدتي وعبد الرحمن بن خلاد الأنصاري، عن أم ورقة بنت نوفل: أن رسول الله صلى الله عليه وآله وسلم لما غزا بدرًا، قالت له: ائذن لي فأخرج معك فأمرض مرضاكم، لعل الله أن يرزقني الشهادة."],[42517,"قال: «قري في بيتك فإن الله يرزقك الشهادة»."],[42518,"قال: فكانت تسمى الشهيدة."],[42519,"قال: وكانت قد قرأت القرآن، فاستأذنت النبي صلى الله عليه وآله وسلم في أن تتخذ في دارها مؤذنًا، فأذن لها، قال: وكانت قد دبرت غلامًا لها وجارية، فقاما إليها بالليل فغماها بقطيفة لها حتى ماتت وذهبا، فأصبح عمر فقام في الناس فقال: من عنده من هذين علم، أو: من رآهما، فليجيء بهما، فأمر بهما فصلبا، فكانا أول مصلوب بالمدينة."],[42520,"قال أبو داود: حدثنا الحسن بن حماد الحضرمي، حدثنا محمد بن فضيل، عن الوليد بن جميع، عن عبد الرحمن بن خلاد، عن أم ورقة بنت عبد الله بن الحارث بهذا الحديث، والأول أتم."],[42521,"أخرجها الثلاثة قيل: إن عمر، رضي الله عنه، لما قيل له: إنها قتلت، قال: صدق رسول الله صلى الله عليه وآله وسلم حين كان يقول: «انطلقوا بنا نزور الشهيدة»."],[42522,"٧٦٢٧ - أم الوليد بنت عمر"],[42523,"ب د ع: أم الوليد بنت عمر روى عنها سالم بن عبد الله بن عمر، أنها قالت: أطلع رسول الله صلى الله عليه وآله وسلم ذات عشية فقال: «أيها الناس، أما تستحيون؟» فقالوا: مم ذاك يا رسول الله؟! قال: «تجمعون ما لا تأكلون، وتبنون ما لا تعمرون، وتأمون ما لا تدركون! ألا تستحيون من ذلك؟!»."],[42524,"أخرجها الثلاثة، وقال أبو عمر: حديثها عند الوازع بن نافع، وهو منكر الحديث، يروي عن أبي سلمة وسالم أحاديث لا تعرف إلا به."],[42525,"٧٦٢٨ - أم وهب بنت أبي أمية"],[42526,"س: أم وهب بنت أبي أمية قال ابن جريج: جاء الإسلام وعند أبي سفيان بن حرب ست نسوة، وعند صفوان بن أمية بن خلف ست: أم وهب بنت أبي أمية بن قيس من الغياطلة، وفاختة بنت الأسود بن المطلب، وأميمة بنت أبي سفيان بن حرب، وعاتكة بنت الوليد بن المغيرة، وبرزة بنت مسعود بن عمرو، وابنة ملاعب الأسنة عامر بن مالك بن جعفر."],[42527,"فطلق أم وهب، كانت قد أسنت، وفرق الإسلام بينه وبين فاختة، وكانت عند أبيه."],[42528,"وكانت عاتكة وابنة ملاعب الأسنة عنده، حتى طلق عاتكة في خلافة عمر بن الخطاب."],[42529,"أخرجها أبو موسى."],[42530,"حرف الياء"],[42531,"٧٦٢٩ - أم يحيى امرأة أسيد"],[42532,"د ع: أم يحيى امرأة أسيد بن خضير لها ذكر في حديث قراءة أسيد، وليس لها رواية."],[42533,"ذكرها ابن منده، وأبو نعيم مختصرًا."],[42534,"٧٦٣٠ - أم يحيى بنت أبي إهاب"],[42535,"ع س: أم يحيى بنت أبي إهاب"],[42536,"أخبرنا عمر بن محمد بن المعمر، أخبرنا أبو غالب بن البناء، أخبرنا أبو محمد الجوهري، أخبرنا أبو بكر بن مالك، حدثنا بشر بن موسى، حدثنا هوذة بن خليفة، حدثنا ابن جريج، عن عبد الله بن أبي مليكة، عن عقبة بن الحارث بن عامر: أنه تزوج أم يحيى بنت أبي إهاب، فجاءت أمة سوداء، فقالت: قد أرضعتكما، قال: فجئت النبي صلى الله عليه وآله وسلم فذكرت ذلك له، فقال: «وقد زعمت أنها أرضعتكما؟» فنهاه عنها."],[42537,"أخرجها أبو نعيم، وأبو موسى"],[42538,"٧٦٣١ - أم يحيى بن الحصين"],[42539,"أم يحيى بن الحصين"],[42540,"أخبرنا أبو ياسر، بإسناده عن عبد الله بن أحمد، حدثني أبي، حدثنا وكيع، عن إسرائيل، عن أبي إسحاق، عن يحيى بن الحصين، عن أمه، قالت: سمعت رسول الله صلى الله عليه وآله وسلم يقول: «أيها الناس، اسمعوا وأطيعوا وإن أمر عليكم عبد مجدع»."],[42541,"وقد رواه يحيى بن سعيد، عن شعبة، عن يحيى فقال: عن جدته. ونذكره في جدة يحيى إن شاء الله تعالى."],[42542,"٧٦٣٢ - أم يحيى بنت يعلى"],[42543,"ع س: أم يحيى بنت يعلى بن منبه ذكرها القاضي أبو أحمد في تاريخه، قال: أتت النبي صلى الله عليه وآله وسلم بابنها يوم فتح مكة."],[42544,"وقال: قاله سعيد بن الصلت، وخالفه غيره، وذكرها أبو عبد الله في تاريخه، وقال: أدركت النبي صلى الله عليه وآله وسلم. أخرجها أبو نعيم، وأبو موسى."],[42545,"٧٦٣٣ - أم يحيى"],[42546,"س: أم يحيى أخرى."],[42547,"أخرجها أبو موسى، وقال: ذكرناها في ترجمة زيدة."],[42548,"وقيل: زائدة، جارية عمر بن الخطاب."],[42549,"٧٦٣٤ - أم يزيد بن الحارث"],[42550,"س: أم يزيد بن الحارث روى حماد بن سلمة، عن الحجاج بن أرطاة، عن يزيد بن الحارث، عن أمه، أنها سمعت النبي صلى الله عليه وآله وسلم يقول: يعني بعرفات، أو منى: «يا أيها الناس، عليكم بالسكينة والوقار»."],[42551,"رواه يزيد بن هارون، عن الحجاج، عن أبي يزيد مولى عبد الله بن الحارث، عن أم جندب الأزدية."],[42552,"أخرجها أبو موسى."],[42553,"٧٦٣٥ - أم يقظة بنت علقمة"],[42554,"أم يقظة بنت علقمة، زوج سليط بن عمرو."],[42555,"هاجرت معه إلى أرض الحبشة، فولدت له هناك سليط بن سليط."],[42556,"آخر الكنى من النساء، الحمد لله رب العالمين، وصلاته على سيدنا محمد النبي وآله وصحبه وسلم."],[42557,"أسماء النساء المجهولات"],[42558,"كالأخوات، والبنات، والجدات، والخالات، والعمات، وغير ذلك"],[42559,"ذكر من عرف بأخت فلان،"],[42560,"ورتبتهن على أسماء الإخوة"],[42561,"٧٦٣٦ - أخوات جابر بن عبد الله"],[42562,"س: أخوات جابر بن عبد الله الأنصاري وقد اختلفت الرواية في عددهن، فقيل: سبع."],[42563,"وقيل: تسع."],[42564,"أخبرنا أبو القاسم يعيش بن صدقة بن علي الفقيه، بإسناده إلى أبي عبد الرحمن أحمد بن شعيب، أخبرنا إسماعيل بن مسعود، حدثنا خالد، عن عبد الملك، عن عطاء، عن جابر: أنه تزوج امرأة على عهد رسول الله صلى الله عليه وآله وسلم فلقيه النبي صلى الله عليه وآله وسلم فقال: «أتزوجت يا جابر؟» قال: نعم."],[42565,"قال: «بكرًا أم ثيبًا؟» قال: بل ثيبًا."],[42566,"قال: «فهلا بكرًا تلاعبك؟» قلت: يا رسول الله، إن لي أخوات، فخشيت أن تدخل بيني وبينهن."],[42567,"قال: «فذاك إذن، إن المرأة تنكح على دينها ومالها وجمالها، فعليك بذات الدين."],[42568,"تربت يداك»."],[42569,"أخرجهن أبو موسى"],[42570,"٧٦٣٧ - أخت الحارث بن سراقة"],[42571,"أخت الحارث بن سراقة"],[42572,"أخبرنا أبو جعفر، بإسناده عن يونس، عن ابن إسحاق، قال: لما أتى الناس بالمدينة أسماء من قتل من المسلمين يوم بدر، بكى النساء على قتلاهن، فقالت أم الحارث بن سراقة، إحدى بني عدي بن النجار، وأخته: والله لا نبكي عليه حتى يقدم رسول الله صلى الله عليه وآله وسلم فنسأله، فإن كان من أهل الجنة لم نبك عليه، وإن كان من أهل النار بكينا عليه، فلما قدم رسول الله صلى الله عليه وآله وسلم أتتاه فسألتاه، فقال: «إنها جنان، وإنه لفي الفردوس الأعلى»"],[42573,"٧٦٣٨ - أخت حذيفة بن اليمان"],[42574,"س: أخت حذيفة بن اليمان."],[42575,"قيل هي فاطمة."],[42576,"وقيل: هي خولة"],[42577,"أخبرنا أبو أحمد بن سكينة، بإسناده عن أبي داود، قال: حدثنا مسدد، حدثنا أبو عوانة، عن منصور، عن ربعي، عن امرأته، عن أخت لحذيفة أن رسول الله صلى الله عليه وآله وسلم قال: «يا معشر النساء، أما لكن في الفضة ما تحلين به، أما إنه ليس منكن امرأة تتحلى ذهبًا تظهره إلا عذبت به»."],[42578,"أخرجها أبو موسى"],[42579,"٧٦٣٩ - أخت عقبة بن عامر"],[42580,"س: أخت عقبة بن عامر"],[42581,"حدثنا أبو أحمد، بإسناده عن أبي داود، حدثنا مخلد بن خالد، حدثنا عبد الرزاق، أخبرنا ابن جريج، أخبرنا سعيد بن أبي أيوب أن يزيد بن أبي حبيب، أخبره أن أبا الخير حدثه، عن عقبة بن عامر الجهني، قال: نذرت أختي أن تمشي إلى بيت الله عز وجل فأمرتني أن أستفتي لها رسول الله صلى الله عليه وآله وسلم فاستفتيت النبي صلى الله عليه وآله وسلم فقال: «لتمشي ولتركب»."],[42582,"أخرجها أبو موسى"],[42583,"٧٦٤٠ - أخت معقل بن يسار"],[42584,"س: أخت معقل بن يسار"],[42585,"أخبرنا غير واحد، بإسنادهم عن أبي عيسى: حدثنا عبد بن حميد، حدثنا هاشم بن القاسم، عن المبارك بن فضالة، عن الحسن، عن معقل بن يسار، أنه زوج أخته رجلًا من المسلمين على عهد رسول الله صلى الله عليه وآله وسلم فكانت عنده ثم طلقها تطليقة لم يراجعها حتى انقضت العدة فخطبها مع الخطاب، فقال أخوها: والله لا ترجع إليك، فأنزل الله تعالى: ﴿وَإِذَا طَلَّقْتُمُ النِّسَاءَ فَبَلَغْنَ أَجَلَهُنَّ فَلا تَعْضُلُوهُنَّ﴾ الآية."],[42586,"واسمها جميل، بضم الجيم، وقد تقدمت."],[42587,"أخرجها أبو موسى"],[42588,"٧٦٤١ - أخت النعمان بن بشير"],[42589,"س: أخت النعمان بن بشير روى محمد بن إسحاق، عن سعيد بن مينا: أن بنتًا لبشير أخت النعمان بن بشير، قالت: دعتني أمي عمرة بنت رواحة فأعطتني حفنة من تمر في ثوبي، وقالت: اذهبي بهذا إلى أبيك وخالك عبد الله بن رواحة لغدائهما، قالت: فمررت برسول الله صلى الله عليه وآله وسلم وأنا ألتمس أبي وخالي، فقال: «ما هذا معك؟» قلت: هذا تمر بعثتني به أمي إلى أبي وخالي يتغديانه."],[42590,"قال: «هاتيه»."],[42591,"قالت: فصببته في كفي رسول الله صلى الله عليه وآله وسلم فما ملأهما، ثم أمر بثوب فبسط، ثم دحا بالتمر عليه فتبدد فوق الثوب، ثم قال لإنسان عنده: «اصرخ في الخندق، أن هلم إلى الغداء»."],[42592,"فاجتمع أهل الخندق فجعلوا يأكلون، وجعل يزداد حتى صدر أهل الخندق وإنه ليسقط من أطراف الثوب، وهم ثلاثة آلاف."],[42593,"أخرجها أبو موسى."],[42594,"ذكر البنات وجعلت آباءهن على حروف المعجم"],[42595,"٧٦٤٢ - بنتا أوس بن ثابت"],[42596,"س: بنتا أوس بن ثابت"],[42597,"أخبرنا أبو موسى، إجازة، أخبرنا أبو الفتح إسماعيل بن الفضل وأبو الفضل جعفر بن عبد الواحد، قالا: أخبرنا أبو طاهر بن عبد الرحيم، حدثنا أبو الشيخ، حدثنا أبو يحيى الرازي، حدثنا سهل بن عثمان، حدثنا عبد الله بن الأجلح الكندي، عن أبي صالح، عن ابن عباس، قال: كان أهل الجاهلية لا يورثون البنات ولا الولد الصغار الذكور حتى يدركوا، فمات رجل من الأنصار من أصحاب رسول الله صلى الله عليه وآله وسلم يقال له: أوس بن ثابت، وترك ابنتين وابنًا صغيرًا، فجاء ابنا عمه، وهما عصبته، فأخذ ميراثه كله فذكر نزول قوله تعالى: ﴿وَيَسْتَفْتُونَكَ فِي النِّسَاء﴾. الآية، و﴿يُوصِيكُمُ اللَّهُ فِي أَوْلادِكُمْ﴾ الآية."],[42598,"أخرجها أبو موسى"],[42599,"٧٦٤٣ - بنت ثابت"],[42600,"ع س: بنت ثابت بن قيس بن شماس"],[42601,"أخبرنا أبو موسى، أخبرنا أبو علي، أخبرنا أبو نعيم، حدثنا عبد الله بن محمد، حدثنا أبو بكر بن أبي عاصم، حدثنا هشام بن عمار، حدثنا صدقة بن خالد، عن عبد الرحمن بن يزيد بن جابر، عن عطاء الخراساني، عن بنت ثابت بن قيس بن شماس، قالت: لما أنزل الله عز وجل: ﴿يَأَيُّهَا الَّذِينَ آمَنُوا لا تَرْفَعُوا أَصْوَاتَكُمْ فَوْقَ صَوْتِ النَّبِيِّ﴾، دخل ثابت بيته وأغلق عليه بابه، وطفق يبكي."],[42602,"ففقده رسول الله صلى الله عليه وآله وسلم فأرسل إليه فسأله، فأخبره فقال: أنا رجل شديد الصوت، أخاف أن يكون قد حبط عملي؟ قال: «لست منهم، بل تعيش بخير، وتموت بخير»."],[42603,"أخرجه أبو نعيم، وأبو موسى"],[42604,"٧٦٤٤ - بنت الحصين"],[42605,"أم بنت الحصين بن الحارث بن المطلب قسم لها رسول الله صلى الله عليه وآله وسلم ولبنات عمها عبيدة بن الحارث مائة وسوق من خيبر."],[42606,"قاله يونس، عن ابن إسحاق."],[42607,"٧٦٤٥ - بنت أبي الحكم"],[42608,"ع س: بنت أبي الحكم الغفاري"],[42609,"أخبرنا أبو موسى، كتابة، أخبرنا أبو علي، أخبرنا أبو نعيم، حدثنا سليمان بن أحمد، أخبرنا حجاج بن عمران السدوسي، عن يحيى بن خلف، حدثنا عبد الأعلى، عن محمد بن إسحاق، عن سليمان بن سحيم، عن أمه بنت أبي الحكم الغفاري، قالت: سمعت رسول الله صلى الله عليه وآله وسلم يقول: «إن الرجل ليدنو من الجنة حتى ما يكون بينه وبينها ذراع، فيتكلم بالكلمة فيتباعد عنها أبعد من صنعاء»."],[42610,"أخرجها أبو نعيم، وأبو موسى"],[42611,"٧٦٤٦ - بنت خباب"],[42612,"ع س: بنت خباب بن الأرت"],[42613,"أخبرنا يحيى بن محمود، إذنًا، بإسناده عن ابن أبي عاصم، حدثنا أبو بكر بن أبي شيبة، حدثنا وكيع، عن الأعمش، عن أبي إسحاق، عن عبد الرحمن بن زيد الفائشي، عن ابنة لخباب، قالت: خرج خباب في سرية، فكان رسول الله صلى الله عليه وآله وسلم يتعاهدنا، حتى كان يحلب عنزًا لنا في جفنة لنا، فكان يحلبها حتى تمتلئ، فلما رجع خباب حلبها فرجع حلابها إلى ما كان."],[42614,"رواه إسرائيل، عن أبي إسحاق، وقال: عن عبد الرحمن بن مالك الأحمسي."],[42615,"أخرجها أبو نعيم، وأبو موسى"],[42616,"٧٦٤٧ - بنت أبي سبرة"],[42617,"ع س: بنت أبي سبرة، تقدم ذكرها في ترجمة أم معاذ."],[42618,"أخرجها أبو نعيم، وأبو موسى."],[42619,"٧٦٤٨ - بنتا سعد بن الربيع"],[42620,"س: بنتا سعد بن الربيع روى عبد الله بن محمد بن عقيل، عن جابر بن عبد الله، قال: جاءت امرأة النبي صلى الله عليه وآله وسلم فقالت له: هاتان بنتا سعد بن الربيع، قتل معك يوم أحد، فأخذ عمهما ما كل شيء ترك أبوهما، فقال: «سيقضي الله عز وجل في ذلك ما شاء»."],[42621,"فنزلت: ﴿يُوصِيكُمُ اللَّهُ فِي أَوْلادِكُمْ﴾، فقال النبي صلى الله عليه وآله وسلم: «أعط هاتين الجاريتين الثلثين مما ترك أبوهما، وأعط أمهما الثمن، وما بقي فهو لك»."],[42622,"أخرجها أبو موسى."],[42623,"٧٦٤٩ - بنت صفوان"],[42624,"بنت صفوان بن أمية بن خلف الجمحية روى عبد الرحمن بن عبد القارئ، عن بنت صفوان بن أمية الجمحي، قالت: دعا رسول الله صلى الله عليه وآله وسلم بوضوء، فخرجت له بتور من حجارة، حزرته مقدار ثلاثة أرباع المد، فتوضأ به."],[42625,"ذكره أبو أحمد العسكري."],[42626,"٧٦٥٠ - بنات عبيدة بن الحارث"],[42627,"بنات عبيدة بن الحارث بن المطلب قتل أبوهن يوم بدر."],[42628,"أخبرنا أبو جعفر، بإسناده عن يونس، عن ابن إسحاق، فيمن قسم له النبي صلى الله عليه وآله وسلم من خيبر: ولبنات عبيدة بن الحارث، وبنت حصين بن الحارث مائة وسق"],[42629,"٧٦٥١ - بنت عفيف"],[42630,"بنت عفيف"],[42631,"أخبرنا يحيى، إجازة، بإسناده، عن ابن أبي عاصم: حدثنا عقبة بن مكرم، حدثنا محمد بن موسى، حدثنا عبد المنعم بن الصلت، عن أبي يزيد المدني، عن امرأة منهم يقال لها: بنت عفيف، قالت: أتينا رسول الله صلى الله عليه وآله وسلم لنبايعه، فأخذ علينا أن لا نحدث الرجال إلا محرمًا، وأمرنا أن نقرأ على موتانا بفاتحة الكتاب."],[42632,"كذا ذكرها ابن أبي عاصم، وذكرها غيره أم عفيف، وقد تقدمت في الكنى"],[42633,"٧٦٥٢ - بنت قهد"],[42634,"س: بنت قهد."],[42635,"قيل: اسمها خولة روى عنها محمود بن لبيد: أن رسول الله صلى الله عليه وآله وسلم دخل يومًا على عمه حمزة، وكانت تحته، فصنعت له سخينة، فأكلوا."],[42636,"الحديث."],[42637,"أخرجها أبو موسى، وهي زوج حمزة، وقد أسقط من نسبها، وقد تقدم ذكرها."],[42638,"٧٦٥٣ - بنت الوليد بن المغيرة"],[42639,"س: بنت الوليد بن المغيرة قيل اسمها عاتكة."],[42640,"وهي التي استأمنت لزوجها صفوان بن أمية بن خلف من النبي صلى الله عليه وآله وسلم يوم الفتح، وقد تقدم ذكرها."],[42641,"أخرجها أبو موسى."],[42642,"٧٦٥٤ - بنت هبيرة"],[42643,"س: بنت هيبرة"],[42644,"أخبرنا أبو القسم بن صدقة الفقيه، بإسناده عن أبي عبد الرحمن النسائي: أخبرنا سليمان بن سلم البلخي، حدثنا النضر بن شميل، حدثنا هشام، عن يحيى، عن أبي سلام، عن أبي أسماء الرحبي، عن ثوبان، قال: جاءت ابنة هبيرة إلى رسول الله صلى الله عليه وآله وسلم وفي يدها فتخ من ذهب. . . . الحديث."],[42645,"قيل: اسمها هند. وقد تقدم ذكرها."],[42646,"أخرجها أبو موسى"],[42647,"ذكر من عرف بالجدودة وجعلت أولاد الأخ على الحروف أيضا"],[42648,"٧٦٥٥ - جدة الأنصاري"],[42649,"س: جدة الأنصاري روى وكيع، عن إسماعيل بن رافع أبي رافع، عن شيخ من الأنصار، عن جدته، قال: وكانت من المهاجرات، قالت: دخل علي رسول الله صلى الله عليه وآله وسلم وأنا أختضب، فقال: «يرحمك الله أم فلان! فهلا هكذا؟». وأشار بيده إلى النقش."],[42650,"أخرجها أبو موسى."],[42651,"٧٦٥٦ - جدة حشرج"],[42652,"س: جدة حشرج بن زياد، وهي أم زياد"],[42653,"أخبرنا أبو ياسر، بإسناده عن عبد الله بن أحمد: حدثني أبي، حدثنا ابن موسى، عن رافع بن سلمة الأشجعي، عن حشرج بن زياد الأشجعي، عن جدته أم أبيه، قالت: خرجنا مع رسول الله صلى الله عليه وآله وسلم في غزاة خيبر، وأنا سادسة ست نسوة، قالت: فبلغ رسول الله صلى الله عليه وآله وسلم أن معه نساء، قالت: فأرسل إلينا فدعانا، قالت: فرأينا في وجهه الغضب، فقال: «ما أخرجكن، وبأمر من خرجتن؟» قلنا: خرجنا معك نناول السهام ونسقي السويق، ومعنا دواء للجرحى، ونغزل الشعر، فنعين به في سبيل الله."],[42654,"قال: «قمن فانصرفن»."],[42655,"قالت: فلما فتح الله عليه خيبر، أخرج لنا سهامًا كسهام الرجل، فقلت لها: يا جدة، وما الذي أخرج لكن؟ قالت: التمر."],[42656,"أخرجها أبو موسى"],[42657,"٧٦٥٧ - جدة حفص بن سعيد"],[42658,"س: جدة حفص بن سعيد القرشي"],[42659,"أخبرنا أبو محمد بن سويدة، بإسناده عن الواحدي، قال: أخبرنا أبو عبد الرحمن محمد بن أحمد بن جعفر، أخبرنا أبو بكر بن الحسن الشيباني، أخبرنا محمد بن عبد الرحمن الدغولي، حدثنا أبو عبد الرحمن محمد بن يونس، عن الفضل بن دكين، عن حفص بن سعيد بن الأعور القرشي، قال: حدثتني أمي، عن أمها، وكانت خادم النبي صلى الله عليه وآله وسلم أن جروا دخل تحت سرير في بيت النبي صلى الله عليه وآله وسلم فمات، فمكث النبي صلى الله عليه وآله وسلم أربعة أيام لا ينزل عليه الوحي، فقال: «يا خولة، ما حدث في بيت رسول الله صلى الله عليه وآله وسلم جبريل عليه السلام لا يأتيني»، ثم خرج فقلت في نفسي: لو هيأت البيت فكنسته؟ فأهويت بالمكنسة تحت السرير، فبدا لي الجرو ميتا، فألقيته خلف الدار."],[42660,"فجاء النبي صلى الله عليه وآله وسلم يرعد لحياه، وكان إذا نزل عليه الوحي أخذته الرعدة، فقال: «يا خولة، دثريني»."],[42661,"فأنزل الله عز وجل: ﴿وَالضُّحَى وَاللَّيْلِ إِذَا سَجَى﴾ إلى قوله ﴿فَتَرْضَى﴾."],[42662,"أخرجها أبو موسى."],[42663,"وهذا فيه نظر، فإن الصحيح أن هذه السورة من أول ما نزل بمكة، والقصة فيه مشهورة صحيحة"],[42664,"٧٦٥٨ - جدة خارجة بن زيد"],[42665,"س: جدة خارجة بن زيد روى عبد الله بن محمد بن عقيل، عن جابر بن عبد الله، قال: خرجنا مع رسول الله صلى الله عليه وآله وسلم حتى جئنا امرأة من الأنصار، وهي جدة خارجة بن زيد بن ثابت، فزرناها، فرشت لنا صورًا فقعدنا تحته فأكلنا، ثم جاءت المرأة بابنتين لها فقالت: يا رسول الله، هاتان ابنتا ثابت بن قيس، قتل معك يوم أحد، وقد أخذ عمهما مالهما. . . . . الحديث. وقد تقدم في بنتي أوس بن ثابت."],[42666,"أخرجها أبو موسى."],[42667,"قلت: الصحيح أنهما ابنتا أوس بن ثابت، فإن أوس قتل يوم أحد في قول، ولا يعرف في أحد ثابت بن قيس، والله أعلم."],[42668,"٧٦٥٩ - جدة أبي السائب"],[42669,"ع س: جدة أبي السائب"],[42670,"أخبرنا يحيى، إجازة، بإسناده عن ابن أبي عاصم: حدثنا محمد بن إدريس، عن نعيم بن حماد، عن حسين بن زيد بن علي، عن أبي السائب، عن جدته، وكانت من المهاجرات، أن رسول الله صلى الله عليه وآله وسلم أقطعها بئرًا بالعقيق."],[42671,"أخرجها أبو نعيم، وأبو موسى"],[42672,"٧٦٦٠ - جدة السلمي"],[42673,"س: جدة السلمي روى علي بن حجر، عن عيسى بن يونس، عن رجل من بني سليم، عن جدته: أن النبي صلى الله عليه وآله وسلم دخل عليها وهي تختضب، فقال: «هلا يا أم فلان هكذا»، على ظهر كفه، يعني النقش."],[42674,"أخرجها أبو موسى."],[42675,"وقد روى مثل هذا عن جدة الأنصاري."],[42676,"٧٦٦١ - جدة الصلت بن زبيد"],[42677,"س: جدة الصلت بن زييد روى عنها الصلت، قالت: جاءت أم الغلامين إلى النبي صلى الله عليه وآله وسلم فقالت: يا رسول الله: إن بابني العذرة: فما ترى؟ فقال: «خذي كست مر، وحبة سوداء، وزيتًا، فاسعطيهما وتوكلي»."],[42678,"فلم تقرها نفسها أن أعلقت عليهما، فقدرت منيتهما، فزملتهما، ثم أتت رسول الله صلى الله عليه وآله وسلم فقالت: لمعصيتي لله ولرسوله أعظم من مصابي بهما."],[42679,"قال: «أنت والدة فلا جناح عليك»."],[42680,"ووافق ذلك عنده نساء، فقال: «يا معشر نساء المهاجرين، لا تعلقن على أولادكن فإنه قتل السر»."],[42681,"أخرجه أبو موسى."],[42682,"٧٦٦٢ - جدة ضمرة بن سعيد"],[42683,"س: جدة ضمرة بن سعيد"],[42684,"أخبرنا عبد الوهاب بن هبة الله، بإسناده عن عبد الله: حدثنا أبي، حدثنا يزيد بن هارون، أخبرنا محمد بن إسحاق، عن ابن لضمرة بن سعيد، عن أهله، عن جدته، وكانت صلت مع رسول الله صلى الله عليه وآله وسلم القبلتين، قالت: دخلت على رسول الله صلى الله عليه وآله وسلم فقال: «اختضبي»."],[42685,"قالت: فما تركت الخضاب."],[42686,"أخرجها أبو موسى"],[42687,"٧٦٦٣ - جدة عمرو بن معاذ"],[42688,"جدة عمرو بن معاذ"],[42689,"أخبرنا يحيى، إجازة، بإسناده، عن ابن أبي عاصم: حدثنا يعقوب بن حميد، حدثنا إسماعيل بن داود بن عبد الله بن مخراق، عن هشام بن سعد، عن زيد بن أسلم، عن عمرو بن معاذ الأنصاري: أن سائلًا وقف على باب بيتهم، فقالت جدته: أطعموه."],[42690,"فقالوا: ليس عندنا."],[42691,"قالت: اسقوه سويقًا، فإني سمعت رسول الله صلى الله عليه وآله وسلم يقول: «ردوا السائل ولو بظلف محرق»."],[42692,"واسمها حواء."],[42693,"وقد تقدم ذكرها"],[42694,"٧٦٦٤ - جدة القرشي"],[42695,"س: جدة القرشي روى زكريا بن أبي زائدة، عن عبد الملك بن عمير، حدثني فلان القرشي، عن جدته: أنها سمعت النبي يقول: «أفضل العمل الإيمان بالله عز وجل وجهاد في سبيله، وحج مبرور»."],[42696,"أخرجها أبو موسى."],[42697,"٧٦٦٥ - جدة يحيى بن الحصين"],[42698,"س: جدة يحيى بن الحصين، هي أخت أم الحصين."],[42699,"أخبرنا أبو ياسر، بإسناده عن عبد الله، حدثني أبي، حدثنا يحيى بن سعيد، عن شعبة، حدثنا يحيى بن حصين بن عروة، قال: حدثتني جدتي، قالت: سمعت رسول الله صلى الله عليه وآله وسلم يقول: «ولو استعمل عليكم عبد يقودكم بكتاب الله عز وجل فاسمعوا له وأطيعوا»."],[42700,"أخرجها أبو موسى"],[42701,"٧٦٦٦ - جدة يوسف بن مسعود"],[42702,"س: جدة يوسف بن مسعود الأنصاري الزرقي."],[42703,"وهي أم مسعود بن الحكم روى يوسف بن مسعود بن الحكم الأنصاري، عن جدته: أنها أيام أكل وشرب."],[42704,"وقد تقدم ذكرها في أم مسعود."],[42705,"أخرجها أبو موسى."],[42706,"ذكر الخالات وجعلت أولاد الأخت الراوين عنهن على حروف المعجم"],[42707,"٧٦٦٧ - خالة أبي أمامة"],[42708,"ع س: خالة أبي أمامة بن سهل بن حنيف"],[42709,"أخبرنا يحيى بن محمود، إذنًا، بإسناده عن ابن أبي عاصم: حدثنا الحسن بن علي، حدثنا ابن أبي مريم وأبو صالح، قالا: حدثنا الليث بن سعد، حدثني خالد بن يزيد، عن سعيد بن أبي هلال، عن مروان بن عثمان، عن أبي أمامة بن سهل بن حنيف، عن خالته، أنها قالت: لقد أقرأناها رسول الله صلى الله عليه وآله وسلم: آية الرجم: (الشيخ والشيخة إذا زنيا فارجموهما ألبتة بما قضيا من اللذة)."],[42710,"أخرجها أبو نعيم، وأبو موسى"],[42711,"٧٦٦٨ - خالة جابر بن عبد الله"],[42712,"س: خالة جابر بن عبد الله"],[42713,"أخبرنا يحيى، إجازة، بإسناده، عن ابن أبي عاصم: حدثنا الحسن بن علي، حدثنا أبو عاصم، عن ابن جريج، عن أبي الزبير، عن جابر: أن خالته كانت في عدة، فأرادت أن تخرج إلى نخل لها تجذه، فقال لها رجل: ليس ذلك لك."],[42714,"فسألت النبي صلى الله عليه وآله وسلم فقال: «اخرجي فجذي نخلك، فعسى أن تصدقي أو تصنعي معروفًا»."],[42715,"أخرجها أبو موسى"],[42716,"٧٦٦٩ - خالة خالد بن عبد الله"],[42717,"ع س: خالة خالد بن عبد الله بن حرملة المدلجي"],[42718,"أخبرنا يحيى، إجازة، بإسناده، عن ابن أبي عاصم: حدثنا أبو بكر بن أبي شيبة، عن محمد بن بشر، عن خالد بن عبد الله بن حرملة، عن خالته، قالت: خطب رسول الله صلى الله عليه وآله وسلم الناس وهو عاصب إصبعه، لدغته عقرب، فقال: «إنكم تقولون: لا عدو، ولا تزالون تقاتلون عدوًا حتى تقاتلوا يأجوج ومأجوج، عراض الوجوه، صغار العيون، صهب الشعاف من كل حدب ينسلون، كأن وجوهم المجان المطرقة»."],[42719,"رواه غيره عن محمد بن بشر، عن محمد بن عمرو، عن خالد."],[42720,"أخرجها أبو نعيم، وأبو موسى"],[42721,"٧٦٧٠ - خالة زينب بنت نبيط"],[42722,"ع س: خالة زينب بنت نبيط روى محمد بن عمارة بن عمرو، عن زينب بنت نبيط بن جابر، عن أمها أو خالتها بنات أبي أمامة أسعد بن زرارة، قالت: أوصى إلي رسول الله صلى الله عليه وآله وسلم. وقد تقدم ذكرهن."],[42723,"أخرجها أبو نعيم، وأبو موسى."],[42724,"٧٦٧١ - خالة السائب بن يزيد خالة السائب بن يزيد"],[42725,"ع س: خالة السائب بن يزيد"],[42726,"أخبرنا يحيى، إجازة، بإسناده، عن ابن أبي عاصم: حدثنا هشام بن عمار، حدثنا حاتم بن إسماعيل، عن الجعيد بن عبد الرحمن بن أوس، عن السائب بن يزيد، قال: ذهبت بي خالتي إلى رسول الله صلى الله عليه وآله وسلم فقالت: يا رسول الله، إن ابن أختي وجع، فمسح رأسي ودعا لي بالبركة، ثم توضأ فشربت وضوءه."],[42727,"أخرجها أبو نعيم، وأبو موسى"],[42728,"٧٦٧٢ - خالة أم سلمة"],[42729,"س: خالة أم سلمة أسماء بنت يزيد روى شهر بن حوشب، عن أم سلمة الأنصارية، أنها كانت في النسوة اللاتي أخذ عليهن رسول الله صلى الله عليه وآله وسلم ما أخذ، وكانت معها خالته."],[42730,"الحديث."],[42731,"أخرجها أبو موسى."],[42732,"ذكر من عرفت بالزوجية وجعلت الأزواج على حروف المعجم"],[42733,"٧٦٧٣ - زوجة أوس بن ثابت"],[42734,"زوجة أوس بن ثابت."],[42735,"تقدم ذكرها في ترجمة بنت أوس."],[42736,"٧٦٧٤ - زوجة بلال"],[42737,"س: زوجة بلال ورواه أبو الورد القشيري، عن امرأة من بني عامر، عن امرأة بلال: أن النبي صلى الله عليه وآله وسلم أتاها فسلم، فقال: «أثم بلال؟»."],[42738,"وقد ذكرت في الكنى في أم بلال."],[42739,"أخرجها أبو موسى."],[42740,"٧٦٧٥ - زوجة ثابت بن قيس"],[42741,"س: زوجة ثابت بن قيس ذكرت في ترجمة ابنتيها."],[42742,"أخرجها أبو موسى مختصرًا."],[42743,"٧٦٧٦ - زوجة جابر بن عبد الله"],[42744,"س: زوجة جابر بن عبد الله"],[42745,"أخبرنا الخطاب عبد الله بن أحمد بن عبد القاهر، بإسناده، عن أبي داود الطيالسي: حدثنا حماد بن زيد، عن عمرو بن دينار، قال: سمعت جابر بن عبد الله يقول: تزوجت امرأة على عهد رسول الله صلى الله عليه وآله وسلم ثيبًا، فقال رسول الله صلى الله عليه وآله وسلم: «فهلا بكرًا تلاعبها وتلاعبك»."],[42746,"الحديث."],[42747,"أخرجها أبو موسى"],[42748,"٧٦٧٧ - زوجة رافع بن خديج"],[42749,"س: زوجة رافع بن خديج ذكرها جعفر، ولم يورد لها شيئا."],[42750,"أخرجها أبو موسى مختصرًا."],[42751,"٧٦٧٨ - زوجة سعد بن الربيع"],[42752,"س: زوجة سعد بن الربيع ذكرت في ترجمة بنتها."],[42753,"أخرجها أبو موسى مختصرًا."],[42754,"٧٦٧٩ - زوجة سلمة بن هشام"],[42755,"زوجة سلمة بن هشام"],[42756,"أخبرنا عبيد الله بن أحمد، بإسناده عن يونس، عن ابن إسحاق: حدثني عبد الله بن أبي بكر بن حزم، عن عامر بن عبد الله بن الزبير: أن أم سلمة زوج النبي صلى الله عليه وآله وسلم قالت لأمرأة سلمة بن هشام بن المغيرة المخزومي: ما لي لا أرى سلمة يحضر الصلاة مع رسول الله صلى الله عليه وآله وسلم ومع المسلمين؟ فقالت: والله ما يستطيع أن يخرج، كلما خرج صاح به الناس: يا فرار، يا فرار، فررتم في سبيل الله حتى قعد في بيته، فما يخرج."],[42757,"وكان في غزوة مؤتة"],[42758,"٧٦٨٠ - زوجة عبد الله بن رواحة"],[42759,"س: زوجة عبد الله بن رواحة روى إسماعيل بن عياش، عن ربيعة بن صالح المدلجي، عن عكرمة، قال: بينا عبد الله بن رواح مع أهله، إذ خطرت جارية له في ناحية الدار، فقام إليها فواقعها، فأدركته امرأته وهو عليها، فذهبت لتجيء بالسكين، فجاءت وقد فرغ وقام عنها، فقالت: لم أرك حيث كنت! قال: فقلت: إن رسول الله صلى الله عليه وآله وسلم نهانا أن يقرأ أحدنا القرآن جنبًا، قالت: فإن كنت صادقًا فاقرأ، قال: نعم."],[42760,"وقال:"],[42761,"أتانا رسول الله يتلو كتابه … كما لاح مشهور من الصبح ساطع"],[42762,"أتى بالهدى بعد العمى فقلوبنا … به موقنات أن ما قال واقع"],[42763,"يبيت يجافي جنبه عن فراشه … إذا استثقلت بالمشركين المضاجع"],[42764,"وقيل: إنما قال غير هذه الأبيات. فقالت: آمنت بالله وكذبت بصري. قال عبد الله: غدوت إلى رسول الله صلى الله عليه وآله وسلم فذكرت ذلك، فضحك حتى بدت نواجذه. أخرجه أبو موسى."],[42765,"٧٦٨١ - زوجة معاذ"],[42766,"ع س: زوجة معاذ، لها ذكر في حديث أم عطية."],[42767,"أخبرنا أبو موسى، إجازة، أخبرنا أبو علي، حدثنا أبو نعيم، حدثنا محمد بن جعفر بن الهيثم، حدثنا جعفر بن محمد الصائغ، حدثنا معاوية بن عمرو، حدثنا زائدة، قال أبو نعيم: وحدثنا أبو أحمد الغطريفي، حدثنا عبد الله بن محمد بن شيرويه، حدثنا إسحاق بن راهويه، حدثنا النضر بن شميل."],[42768,"ح، قال أبو نعيم: وحدثنا أبو عمرو بن حمدان، حدثنا الحسن بن سفيان، حدثنا محمد بن قدامة، حدثنا النضر بن شميل، قالا: حدثنا هشام بن حسان، عن حفصة بنت سيرين، عن أم عطية، قالت: كان فيما أخذ علينا في البيعة أن لا ننوح، فما وفت منا غير خمس، منهن امرأة معاذ."],[42769,"وفي رواية أبي عمرو، قال: غير أم سليم، وابنة أبي سبرة، وامرأة معاذ، وامرأة أخرى."],[42770,"وكانت لا تعد نفسها لأنها لما كان يوم الحرة لم يزل بها النساء حتى قامت."],[42771,"أخرجها أبو نعيم، وأبو موسى"],[42772,"٧٦٨٢ - زوجة أبي موسى الأشعري"],[42773,"زوجة أبي موسى الأشعري"],[42774,"أخبرنا يحيى فيما أذن لي، بإسناده عن ابن أبي عاصم، قال: حدثنا أبو بكر بن أبي شيبة، حدثنا أبو معاوية، عن الأعمش، عن إبراهيم، عن سهم بن المنجاب، عن القرثع، قال: لما ثقل أبو موسى صاحت عليه امرأته، فقال لها: أما علمت ما قال رسول الله صلى الله عليه وآله وسلم قالت: بلى، ثم سكتت، فقيل لها بعد: أي شيء قال رسول الله صلى الله عليه وآله وسلم قالت: «إن الله برئ ممن حلق أو خرق أو سلق»"],[42775,"ذكر من عرف بالعمومة وجعلت أولاد الأخ على الحروف أيضا"],[42776,"٧٦٨٣ - عمة الحارث بن أبي قرظة"],[42777,"س: عمة الحارث بن أبي قرظة قال جعفر: ذكرها البخاري فيمن روت عن النبي صلى الله عليه وآله وسلم من نساء خزاعة وأسلم."],[42778,"أخرجها أبو موسى."],[42779,"٧٦٨٤ - عمة حسناء الصريمية"],[42780,"س: عمة حسناء الصريمية روى إسحاق بن راهويه، عن إسحاق الأزرق، عن عوف الأعرابي، عن حسناء بنت معاوية الصريمية، كذا قال: عن عمتها، قالت: قلت للنبي: من في الجنة؟ قال: «النبي صلى الله عليه وآله وسلم في الجنة، والشهيد في الجنة، والمولود في الجنة، والموءدة في الجنة»."],[42781,"أخرجه أبو موسى، وقال: في أكثر الكتب خنساء، بالخاء المعجمة، والنون، والسين، وهي عند المحققين: حسناء، بالحاء المهملة، والسين والنون، والله أعلم."],[42782,"٧٦٨٥ - عمة حصين بن محصن"],[42783,"ع س: عمة حصين بن محصن الخطمي"],[42784,"أخبرنا أبو موسى، إذنًا، أخبرنا أبو منصور محمد بن عبد الله بن مندويه الشروطي والحسن بن أحمد المقرئ، قالا: حدثنا أحمد بن عبد الله، حدثنا أحمد بن يوسف بن خلاد، حدثنا الحارث بن أبي أسامة، حدثنا يزيد بن هارون، حدثنا يحيى بن سعيد، عن بشير بن يسار، عن حصين بن محصن: أن عمة له أتت النبي صلى الله عليه وآله وسلم في حاجة لها، ففرغت من حاجتها، فقال لها: «أذات بعل أنت؟» قالت: نعم."],[42785,"قال: «فكيف أنت له؟» قالت: ما آلوه إلا ما عجزت عنه."],[42786,"قال: «انظري أين أنت منه، فإنه جنتك ونارك»."],[42787,"أخرجها أبو نعيم، وأبو موسى"],[42788,"٧٦٨٦ - عمة سنان بن عبد الله الجهني"],[42789,"ع س: عمة سنان بن عبد الله الجهني أخبرنا أبو موسى، إذنًا، أخبرنا أبو غالب الكوشيدي، أخبرنا أبو بكر بن ريذة، أخبرنا الطبراني، حدثنا عمرو بن أبي الطاهر بن السرح، حدثنا يوسف بن عدي."],[42790,"ح قال الطبراني: وحدثنا عبيد بن غنام، حدثنا أبو بكر بن أبي شيبة، قالا: حدثنا عبد الرحيم بن سليمان، عن محمد بن كريب، عن ابن عباس، عن سنان بن عبد الله الجهني: أن عمته حدثته، أنها أتت النبي صلى الله عليه وآله وسلم فقالت: يا رسول الله، أمي توفيت وعليها مشي إلى الكعبة نذرًا."],[42791,"فقال النبي صلى الله عليه وآله وسلم: «هل تستطيعين أن تمشي عنها؟» قالت: نعم."],[42792,"قال: «فامشي عن أمك»."],[42793,"قالت: أو يجزئ ذلك عنها؟ قال: «نعم، لو كان عليها دين هل كان يقبل منك؟» قالت: نعم، فقال النبي صلى الله عليه وآله وسلم: «الله عز وجل أحق بذلك»."],[42794,"أخرجها أبو نعيم، وأبو موسى"],[42795,"٧٦٨٧ - عمة العاص الطفاوي"],[42796,"ع س: عمة العاص الطفاوي."],[42797,"قيل هي أم الغادية روى العاص بن عمرو الطفاوي، عن عمته، قالت: دخلت مع ناس على النبي صلى الله عليه وآله وسلم فقلت: حدثني حديثًا ينفعني الله به."],[42798,"قال: «إياك وما يسؤ الأذن»."],[42799,"أخرجها أبو نعيم، وأبو موسى."],[42800,"٧٦٨٨ - عمة عبد ربه بن سعيد"],[42801,"ع س: عمة عبد ربه بن سعيد الأنصاري"],[42802,"أخبرنا يحيى بن محمود، كتابة، بإسناده عن ابن أبي عاصم، حدثنا يعقوب بن حميد، عن عبد العزيز بن محمد، عن محمد بن أبي حميد، عن عبد ربه بن سعيد بن قيس، عن عمته، قالت: قال رسول الله صلى الله عليه وآله وسلم: «إن أم ملدم تخرج خبث ابن آدم كما تخرج النار خبث الحديد»."],[42803,"أخرجها أبو نعيم، وأبو موسى"],[42804,"٧٦٨٩ - عمة معبد بن كعب"],[42805,"ع س: عمة معبد بن كعب"],[42806,"قال بالإسناد الذي قبله: عن يعقوب بن حميد، عن ابن عيينة، عن محمد بن إسحاق، عن معبد بن كعب بن مالك، عن أمه أو عن عمته، أن النبي صلى الله عليه وآله وسلم قال: «يا هؤلاء، إن البذاذة من الإيمان»."],[42807,"أخرجها أبو نعيم، وأبو موسى"],[42808,"٧٦٩٠ - عمة هند بنت سعيد"],[42809,"ع س: عمة هند بنت سعيد بن أبي سعيد الخدري."],[42810,"وقيل بنت أبي سعيد."],[42811,"وقيل تكنى أم عبد الرحمن"],[42812,"أخبرنا أبو موسى، كتابة، أخبرنا الحسن بن أحمد، حدثنا أحمد بن عبد الله وعبد الرحمن بن أبي بكر، قالا: حدثنا عبد الله بن محمد بن محمد، حدثنا أبو بكر بن أبي عاصم، حدثنا يعقوب بن حميد، حدثنا عبد العزيز بن محمد، عن محمد بن أبي حميد، عن هند بنت سعيد، عن عمتها، أن النبي صلى الله عليه وآله وسلم زارهم، فأكل كتف شاة، ثم صلى ولم يتوضأ."],[42813,"أخرجها أبو نعيم، وأبو موسى"],[42814,"ذكر من لم يسم من الصحابيات"],[42815,"٧٦٩١ - امرأة من بني أسد"],[42816,"امرأة من بني أسد"],[42817,"أخبرنا يحيى بن محمود، إجازة، بإسناده إلى أحمد بن عمرو: حدثنا محمد بن عوف، حدثنا محمد بن إسماعيل، حدثنا أبي، عن ضمضم بن زرعة، عن شريح بن عبيد، عن حديث حبيب بن عبيد، عن حديث ابن الأبج السليحي، أن امرأة من بني أسد، قالت: كنت يوما عند زينب امرأة رسول الله صلى الله عليه وآله وسلم وهي تصبغ ثيابها بالمغرة فطلع رسول الله صلى الله عليه وآله وسلم فلما رأى المغرة خرج، فلما رأت ذلك زينب علمت أن رسول الله صلى الله عليه وآله وسلم قد كره ما أحدثت، فغسلت ثيابها ووارت كل حمرة، ثم رجع رسول الله صلى الله عليه وآله وسلم فاطلع، فلما لم ير شيئا دخل."],[42818,"أخرجها أبو نعيم"],[42819,"٧٦٩٢ - امرأة من بني عبد الأشهل"],[42820,"ع: امرأة من بني عبد الأشهل، من الأنصار."],[42821,"أخبرنا أبو أحمد بن سكينة، بإسناده عن السجستاني: حدثنا عبد الله بن محمد النفيلي وأحمد بن يونس، قالا: حدثنا زهير، حدثنا عبد الله بن عيسى، عن موسى بن عبد الله بن يزيد، عن امرأة من بني عبد الأشهل، قالت: قلت: يا رسول الله، إن لنا طريقًا إلى المسجد منتنة فكيف نفعل إذا مطرنا؟ قال: «أليس بعدها طريق هي أطيب منها؟» قالت: قلت: بلى."],[42822,"قال: «فهذه بهذه»."],[42823,"أخرجها أبو نعيم"],[42824,"٧٦٩٣ - امرأة"],[42825,"ع: امرأة"],[42826,"أخبرنا أبو الفرج بن أبي الرجاء، بإسناده عن القاضي أبي بكر بن عمرو، حدثنا عقبة بن مكرم، حدثنا ابن أبي عدي، عن حسين المعلم، عن إسحاق بن عبد الله بن أبي فروة، عن عبد الله بن محمد بن عبد الله الأنصاري، عن امرأة من قومه، قالت: دخل علي رسول الله صلى الله عليه وآله وسلم وأنا آكل بشمالي، وكنت امرأة عسراء، فضرب يدي، وقال: «لا تأكلي بشمالك، فقد أطلق الله يمينك»."],[42827,"فتحولت شمالي يمينًا، فما أكلت بها بعد."],[42828,"أخرجها أبو نعيم"],[42829,"٧٦٩٤ - امرأة من الأنصار"],[42830,"ع: امرأة من الأنصار"],[42831,"أخبرنا أبو ياسر، بإسناده عن عبد الله: حدثني أبي، أخبرنا يزيد، أخبرنا شريك بن عبد الله، عن جامع بن أبي راشد، عن منذر الثوري، عن الحسن بن محمد بن علي، عن امرأة من الأنصار، قالت: دخلت على أم سلمة، فدخل عليها رسول الله صلى الله عليه وآله وسلم فاستترت بكم درعي، فتكلم بكلام لم أفهمه ثم خرج."],[42832,"فقلت: يا أم المؤمنين، كأني رأيت رسول الله صلى الله عليه وآله وسلم دخل وهو غضبان؟ فقالت: نعم، أو ما سمعت ما قال؟ قلت: وما قال؟ قلت: قال: «إن السوء إذا فشا في الأرض فلم يتناه عنه، أرسل الله بأسه على الأرض»."],[42833,"قالت: قلت: وفيهم الصالحون؟ قال: «نعم، وفيهم الصالحون يصيبهم ما أصاب الناس، ثم يقبضهم الله إلى مغفرته ورحمته»."],[42834,"أخرجها أبو نعيم"],[42835,"٧٦٩٥ - امرأة من المبايعات"],[42836,"ع: امرأة من المبايعات"],[42837,"أخبرنا عبد الوهاب بن علي ابن سكينة، بإسناده عن أبي داود: حدثنا مسدد، حدثنا حميد بن الأسود، حدثنا الحجاج عامل عمر بن عبد العزيز على الربذة، حدثني أسيد بن أبي أسيد، عن امرأة من المبايعات، أنها قالت: كان فيما أخذ علينا رسول الله صلى الله عليه وآله وسلم أن لا نعصيه في المعروف، ولا نخمش وجها ولا ننشر شعرًا، ولا نشق جيبًا، ولا ندعو ويلًا."],[42838,"أخرجها أبو نعيم"],[42839,"٧٦٩٦ - امرأة من المبايعات"],[42840,": ع: امرأة من المبايعات أخبرنا يحيى بن محمود الثقفي، فيما أذن لي، بإسناده عن ابن أبي عاصم: حدثنا أبو سعيد عبد الرحمن بن إبراهيم، حدثنا ابن أبي فديك، أخبرني الضحاك بن عثمان، عن عمه، عن عمرو بن عبد الله بن كعب بن مالك، عن امرأة من المبايعات، أنها قالت: جاءنا رسول الله صلى الله عليه وآله وسلم في بني سلمة فقربنا إليه طعامًا فأكل ومعه أصحابه، ثم قرب إليه وضوء فتوضأ، ثم أقبل على أصحابه فقال: «ألا أخبركم بمكفرات الخطايا»."],[42841,"قالوا: بلى."],[42842,"قال: «إسباغ الوضوء على المكاره، وكثرة الخطى إلى المساجد، وانتظار الصلاة بعد الصلاة»."],[42843,"أخرجها أبو نعيم"],[42844,"٧٦٩٧ - امرأة من خثعم"],[42845,"امرأة من خثعم"],[42846,"أخبرنا غير واحد، بإسنادهم عن أبي عيسى: حدثنا أحمد بن منيع، حدثنا روح بن عباده، حدثنا ابن جريج، أخبرني ابن شهاب، عن سليمان بن يسار، عن عبد الله بن عباس، عن الفضل بن عباس، أن امرأة من خثعم، قالت: يا رسول الله، إن أبي أدركته فريضة الله في الحج."],[42847,"وهو شيخ كبير لا يستطيع أن يستوي على ظهر البعير؟ قال: «حجي عنه»"],[42848,"٧٦٩٨ - امرأة من بني عبد الدار"],[42849,"امرأة من بني عبد الدار"],[42850,"أخبرنا يحيى، إذنًا، بإسناده عن ابن أبي عاصم: حدثنا محمد بن علي بن ميمون، حدثنا سليمان بن عبيد الله، حدثنا يونس، عن ابن أبي ذئب، عن الزهري، عن عبيد الله بن عبد الله بن عتبة، عن صفية بنت أبي عبيد، عن الدارية، امرأة من بني عبد الدار، كانت في حجر رسول الله صلى الله عليه وآله وسلم قالت: سمعت رسول الله صلى الله عليه وآله وسلم يقول: «من استطاع أن يموت بالمدينة فليفعل، فمن مات فيها كنت له شهيدًا أو شفيعًا»."],[42851,"كذا ذكرها ابن أبي عاصم، وذكرها أبو نعيم فقال: عن امرأة يتيمة كانت في حجر رسول الله صلى الله عليه وآله وسلم من ثقيف، وذكرها، وقال: عن عبيد الله بن عبد الله بن عمر بن الخطاب."],[42852,"وقال ابن أبي عاصم: عبيد الله بن عبد الله بن عتبة."],[42853,"والله أعلم"],[42854,"٧٦٩٩ - امرأة سوداء"],[42855,"امرأة سوداء"],[42856,"أخبرنا أبو أحمد بن سكينة، بإسناده عن أبي داود: حدثنا سليمان بن حرب ومسدد، قالا: حدثنا حماد بن زيد، عن ثابت، عن أبي رافع، عن أبي هريرة رضي الله عنه، أن امرأة سوداء، أو رجلًا، كان يقم المسجد، ففقده، النبي صلى الله عليه وآله وسلم فسأل عنه، فقيل: مات، فقال: «ألا آذنتموني به؟»، قال: دلوني على قبره، فدلوه، فصلى عليه"],[42857,"٧٧٠٠ - امرأة صلت القبلتين"],[42858,"ع: امرأة صلت القبلتين"],[42859,"أخبرنا أبو ياسر، بإسناده عن عبد الله بن أحمد: حدثني أبي، حدثنا يزيد بن هارون، أخبرنا ابن إسحاق، عن ابن ضمرة بن سعيد، عن جدته، عن امرأة من نسائهم، كانت صلت القبلتين مع النبي صلى الله عليه وآله وسلم قالت: دخل علي رسول الله صلى الله عليه وآله وسلم فقال: «اختضبي، تترك إحداكن الخضاب حتى تكون يدها كيد الرجل!»، قالت: فما تركت الخضاب، وإن كانت لتخضب وهي ابنة ثمانين سنة."],[42860,"أخرجها أبو نعيم."],[42861,"قلت: قد تقدم ذكر الخضاب في ترجمة جدة ضمرة بن سعيد."],[42862,"ورواه أبو موسى، بإسناده عن ابن نمير، عن ابن إسحاق، عن ابن لضمرة، عن أهله، عن جدته، وكانت صلت القبلتين، وقد أورد الإمام أحمد بن حنبل في مسنده، عن يزيد، عن ابن إسحاق مثل رواية أبي موسى، عن جدة ضمرة، وقال: وكانت صلت القبلتين."],[42863,"ورواه أحمد أيضًا، عن يزيد، بإسناده، عن ابن إسحاق، عن ابن ضمرة، عن جدته، عن امرأة من نسائهم صلت القبلتين."],[42864,"والله أعلم"],[42865,"٧٧٠١ - امرأة"],[42866,"امرأة"],[42867,"أخبرنا يحيى بن محمود وأبو ياسر، بإسنادهما عن مسلم، حدثنا محمد بن المثنى، حدثنا عثمان بن عمر، أخبرنا شعبة، عن ثابت البناني، عن أنس بن مالك: أن رسول الله صلى الله عليه وآله وسلم أتى على امرأة تبكي على صبي لها، فقال: «اتقي الله واصبري»، فقالت: وما تبالي بمصيبتي؟! فلما ذهب قيل لها: إنه رسول الله صلى الله عليه وآله وسلم. فأخذها مثل الموت، فأتت بابه فلم تجد على بابه بوابين، فقالت: يا رسول الله، لم أعرفك، فقال لها: «الصبر عند أول صدمة»، أو قال: «عند أول الصدمة»"],[42868,"٧٧٠٢ - امرأة من بني غفار"],[42869,"امرأة من بني غفار"],[42870,"أخبرنا عبيد الله بن أحمد، بإسناده عن يونس، عن محمد بن إسحاق."],[42871,"حدثني سليمان بن سحيم، عن أمية بنت أبي الصلت، عن امرأة من بني غفار، قالت: جئت رسول الله صلى الله عليه وآله وسلم في نسوة من بني غفار، فقلنا: يا رسول الله، إنا قد أردنا أن نخرج معك في وجهك هذا إلى خيبر فنداوي الجرحى ونعين المسلمين، فقال رسول الله صلى الله عليه وآله وسلم: «على بركة الله .."],[42872,"» وذكر الحديث"],[42873,"٧٧٠٣ - امرأة سألت النبي عن صوم السبت"],[42874,"ع: امرأة سألت النبي صلى الله عليه وآله وسلم عن صوم السبت"],[42875,"أخبرنا أبو ياسر، بإسناده عن عبد الله، قال: حدثني أبي، حدثنا حسن بن موسى، حدثنا ابن لهيعة، حدثنا موسى بن وردان، أخبرني عبيد بن حنين مولى خارجة: أن المرأة التي سألت رسول الله صلى الله عليه وآله وسلم عن صيام يوم السبت حدثته أنها سألت رسول الله صلى الله عليه وآله وسلم عن ذلك فقال: «لا لك ولا عليك»."],[42876,"أخرجها أبو نعيم"],[42877,"٧٧٠٤ - امرأة روى عنها عطاء بن يسار"],[42878,"ع: امرأة روى عنها عطاء بن يسار"],[42879,"أخبرنا أبو ياسر، بإسناده عن عبد الله بن أحمد: حدثني أبي، حدثنا عبد الرزاق، أخبرنا معمر، عن زيد بن أسلم، عن عطاء بن يسار، أن امرأة حدثته، قالت: نام رسول الله صلى الله عليه وآله وسلم ثم استيقظ يضحك .. وذكر حديث الغزاة في البحر."],[42880,"وقد تقدم ذكره في ترجمة أم حرام بنت ملحان."],[42881,"أخرجها أبو نعيم."],[42882,"قال أبو القاسم بن عساكر الدمشقي: هذه غير أم حرام، لأن هذه غزت مع المنذر بن الزبير، وأم حرام غزت في خلافة عثمان، وماتت ذلك الوقت."],[42883,"والمنذر غزا مع يزيد بن معاوية إلى القسطنطينية أيام أبيه."],[42884,"والله أعلم"],[42885,"٧٧٠٥ - امرأة من أهل مكة"],[42886,"ع: امرأة من أهل مكة"],[42887,"أخبرنا أبو ياسر، بإسناده، عن عبد الله: حدثني أبي، حدثنا عبد الصمد، حدثني ديلم أبو غالب القطان، حدثني الحكم بن حجل، حدثتني أم الكرام أنها حجت فلقيت امرأة بمكة كثيرة الحشم، ليس عليهم حلي إلا الفضة، فقلت لها: ما لي لا أرى على أحد من حشمك حليًا إلا الفضة، قالت: كان جدي عند رسول الله صلى الله عليه وآله وسلم وأنا معه علي قرطان من ذهب، فقال رسول الله صلى الله عليه وآله وسلم: «شهابان من نار، فنحن أهل بيت لا نلبس إلا الفضة»."],[42888,"أخرجها أبو نعيم"],[42889,"٧٧٠٦ - جارية حبشية كانت تخدم النبي ﷺ"],[42890,"س: جارية حبشية كانت تخدم النبي صلى الله عليه وآله وسلم قال ثمامة بن حزن القشيري: سألت عائشة عن النبيذ فقالت: هذه خادم لرسول الله صلى الله عليه وآله وسلم فسلها، الجارية حبشية، فقالت: كنت أنبذ لرسول الله صلى الله عليه وآله وسلم في سقاء عشاء، فأوكيه وأعلقه، فإذا أصبح شرب منه."],[42891,"أخرجه أبو موسى."],[42892,"٧٧٠٧ - جارية عبد الله بن عمر بن الخطاب"],[42893,"جارية عبد الله بن عمر بن الخطاب"],[42894,"أخبرنا أبو جعفر، بإسناده عن يونس بن بكير، عن ابن إسحاق، قال: وهب رسول الله صلى الله عليه وآله وسلم عمر بن الخطاب فلانة، وهي جارية من سبي هوازن، فوهبها لابنه عبد الله بن عمر."],[42895,"قال ابن إسحاق: فحدثني نافع، عن ابن عمر، قال: فبعثت بجاريتي إلى أخوالي من بني جمح ليصلحوا لي منها حتى أطوف بالبيت ثم آتيهم إذا فرغت، فخرجت من المسجد فإذا الناس يشتدون، فقلت: ما شأنكم؟ قالوا: رد علينا رسول الله صلى الله عليه وآله وسلم نساءنا وأبناءنا، فقلت: دونكم صاحبتكم، فهي في بني جمح، فانطلقوا فأخذوها"],[42896,"٧٧٠٨ - جارية من بني المؤمل"],[42897,"س: جارية من بني المؤمل أسلمت قديمًا في أول الإسلام، وكانت ممن يعذب في الله بمكة، فاشتراها أبو بكر وأعتقها أبو بكر رضي الله عنها، واشترى معها بلالًا وعامر بن فهيرة، وغيرهم، كانوا كلهم يعذبون في الله عز وجل فاشتراهم وأعتقهم، فقيل له: لو اشتريت ما يمنع ظهرك! فقال: منع ظهري أريد."],[42898,"أخرجها أبو موسى."],[42899,"٧٧٠٩ - ظئر محمد بن طلحة"],[42900,"ع س: ظئر محمد بن طلحة"],[42901,"أخبرنا أبو موسى، كتابة، أخبرنا أبو العباس، أخبرنا أبو بكر الضبي، حدثنا سليمان بن أحمد، حدثنا عبيد بن غنام، حدثنا أبو بكر بن أبي شيبة."],[42902,"ح، قال أبو موسى: وأخبرنا أبو علي، حدثنا أبو نعيم، حدثنا أبو عمرو بن حمدان، حدثنا محفوظ بن أبي توبة، قالا: حدثنا يزيد بن هارون، عن إبراهيم بن عثمان، عن محمد بن عبد الرحمن، مولى آل طلحة، عن عيسى بن طلحة، قال: حدثتني ظئر محمد بن طلحة، قالت: لما ولد محمد بن طلحة أتينا به رسول الله صلى الله عليه وآله وسلم فقال: «ما سميتموه؟» قلنا: محمدًا."],[42903,"قال: «هذا اسمي، وكنيته أبو القاسم»."],[42904,"أخرجها أبو نعيم، وأبو موسى"],[42905,"٧٧١٠ - أم ولد شيبة بن عثمان"],[42906,"س: أم ولد شيبة بن عثمان روى هشام الدستوائي، عن بديل بن ميسرة، عن صفية بنت شيبة، عن أم ولد شيبة، قالت: رأيت رسول الله صلى الله عليه وآله وسلم يسعى بين الصفا والمروة، لا يقطع الأبطح إلا شدا."],[42907,"أخرجها أبو موسى."],[42908,"٧٧١١ - الغامدية"],[42909,"س: الغامدية المرجومة في الزنا"],[42910,"وهي التي أتت رسول الله صلى الله عليه وآله وسلم فقالت: يا رسول الله، طهرني، فقال لها: «ارجعي»."],[42911,"ثم أتته من الغد فاعترفت بالزنا، وقالت: والله إني لحبلى."],[42912,"فقال لها: «ارجعي حتي تلدي»."],[42913,"فلما ولدت جاءت بالصبي تحمله، فقالت: يا نبي الله، هذا وقد ولدته."],[42914,"قال: «اذهبي فأرضعيه حتى تفطميه»."],[42915,"فلما فطمته جاءت بالصبي وفي يده كسرة خبز، فقالت: يا نبي الله، هذا قد فطمته."],[42916,"فأمر النبي صلى الله عليه وآله وسلم بالصبي فدفع إلى رجل من المسلمين."],[42917,"وأمرها بها فرجمت."],[42918,"فرماها خالد بحجر فنضح الدم على وجهه، فسبها."],[42919,"فسمع النبي صلى الله عليه وآله وسلم سبه إياها، فقال: «مه! فوالذي نفس بيده لقد تابت توبة لو تابها صاحب مكس لغفر له»."],[42920,"فصلى عليها ودفنت."],[42921,"أخرجها أبو موسى، والله أعلم."]])